#include <iostream>

using namespace std;

// Class representing temperature in Celsius
class Celsius {
private:
    float temperature;

public:
    // Convert Celsius to Fahrenheit
    float toFahrenheit() {
        temperature = 32; // Set temperature for conversion
        return (temperature * 1.8) + 32; // Return converted temperature
    }
};

// Class representing temperature in Fahrenheit
class Fahrenheit {
private:
    float temperature;

public:
    // Convert Fahrenheit to Celsius
    float toCelsius() {
        temperature = 60; // Set temperature for conversion
        return (temperature - 32) * 0.55556; // Return converted temperature
    }
};

int main() {
    float celsiusToFahrenheitResult, fahrenheitToCelsiusResult;
    Celsius celsiusConverter;
    Fahrenheit fahrenheitConverter;

    // Perform Celsius to Fahrenheit conversion
    celsiusToFahrenheitResult = celsiusConverter.toFahrenheit();
    cout << "32 Celsius to Fahrenheit is " << celsiusToFahrenheitResult << endl;

    // Perform Fahrenheit to Celsius conversion
    fahrenheitToCelsiusResult = fahrenheitConverter.toCelsius();
    cout << "60 Fahrenheit to Celsius is " << fahrenheitToCelsiusResult << endl;

    return 0;
}

#include <iostream>

class PrimeChecker {
public:
    char continueInput;
    int number;

    // Checks if the number is prime and outputs the result
    void checkPrime() {
        int divisorCount = 0;

        // Count the number of divisors for the given number
        for (int i = 2; i < number; i++) {
            if (number % i == 0) {
                divisorCount++;
            }
        }

        // Output the result based on the number of divisors found
        if (divisorCount == 0) {
            std::cout << number << " is prime " << std::endl;
        } else {
            std::cout << number << " is not prime " << divisorCount << std::endl;
        }
    }
};

int main() {
    PrimeChecker primeChecker;

    std::cout << "Enter 'y' to continue and 'n' to stop" << std::endl;

    do {
        std::cout << "Enter number: ";
        std::cin >> primeChecker.number;

        primeChecker.checkPrime();

        std::cout << "(y/n) ";
        std::cin >> primeChecker.continueInput;

        // Exit the loop if the user chooses to stop
        if (primeChecker.continueInput == 'n') {
            break;
        }
    } while (true);

    return 0;
}

