using namespace std;

const float PI = 3.14;

// Class representing a circle with methods to calculate area and perimeter
class Circle {
public:
    float radius;

    float calculatePerimeter() {
        return (2 * PI * radius);
    }

    float calculateArea() {
        return (PI * radius * radius);
    }
};

// Class representing a rectangle with methods to calculate area and perimeter
class Rectangle {
public:
    float length, breadth;

    float calculatePerimeter() {
        return (2 * (length + breadth));
    }

    float calculateArea() {
        return (length * breadth);
    }
};

// Class representing a triangle with methods to calculate area and perimeter
class Triangle {
public:
    float side1, side2, side3;

    float calculatePerimeter() {
        return (side1 + side2 + side3);
    }

    float calculateArea() {
        float semiPerimeter = (side1 + side2 + side3) / 2;
        return sqrt(semiPerimeter * (semiPerimeter - side1) * (semiPerimeter - side2) * (semiPerimeter - side3));
    }
};

int main() {
    do {
        cout << "Enter: \n 1.Circle \n 2.Rectangle \n 3.Triangle" << endl;
        int shapeChoice;
        char continueChoice = 'y';

        cin >> shapeChoice;

        // Handle circle selection
        if (shapeChoice == 1) {
            Circle circleInstance;
            cout << "Enter radius: ";
            cin >> circleInstance.radius;
            cout << "The area = " << circleInstance.calculateArea() 
                 << " and the perimeter = " << circleInstance.calculatePerimeter() << endl;
        }
        // Handle rectangle selection
        else if (shapeChoice == 2) {
            Rectangle rectangleInstance;
            cout << "Enter length and breadth: " << endl;
            cin >> rectangleInstance.length >> rectangleInstance.breadth;
            cout << "The area = " << rectangleInstance.calculateArea() 
                 << " and the perimeter = " << rectangleInstance.calculatePerimeter() << endl;
        }
        // Handle triangle selection
        else if (shapeChoice == 3) {
            Triangle triangleInstance;
            cout << "Enter the three sides of the triangle: " << endl;
            cin >> triangleInstance.side1 >> triangleInstance.side2 >> triangleInstance.side3;
            cout << "The area = " << triangleInstance.calculateArea() 
                 << " and the perimeter = " << triangleInstance.calculatePerimeter() << endl;
        }

        cout << "Do you want to continue (y/n): ";
        cin >> continueChoice;

        if (continueChoice == 'n') {
            break;
        }
    } while (true);
}

