#include <iostream>

class Time {
private:
    int hour, minute, second;
    char isAfterNoon;

public:
    // Default constructor initializes time to 00:00:00
    Time() : hour(0), minute(0), second(0) {}

    // Parameterized constructor initializes time with given values
    Time(int hh, int mm, int ss) : hour(hh), minute(mm), second(ss) {}

    // Displays the current time in HH:MM:SS format
    void displayTime() const {
        std::cout << "The time is " << hour << " : " << minute << " : " << second;
    }

    // Adjusts time format based on whether it's after noon
    void adjustTimeFormat() {
        std::cout << "Is the time after noon (y/n): ";
        std::cin >> isAfterNoon;

        // Normalize seconds and adjust minutes accordingly
        while (second >= 60) {
            minute++;
            second -= 60;
        }

        // Normalize minutes and adjust hours accordingly
        while (minute >= 60) {
            hour++;
            minute -= 60;
        }

        // Adjust hour for PM if applicable
        if (isAfterNoon == 'y') {
            hour += 12;
        }

        // Normalize hour to fit within a 24-hour format
        hour %= 24;
    }
};

int main() {
    char userChoice;
    int hh = 0, mm = 0, ss = 0;

    std::cout << "Do you want to enter time (y/n): ";
    std::cin >> userChoice;

    // Prompt user for time input if desired
    if (userChoice == 'y') {
        std::cout << "Enter hour: ";
        std::cin >> hh;
        std::cout << "Enter minute: ";
        std::cin >> mm;
        std::cout << "Enter second: ";
        std::cin >> ss;
    }

    Time timeObject(hh, mm, ss);
    timeObject.adjustTimeFormat();
    timeObject.displayTime();

    return 0;
}

