// Class to manage and concatenate two character arrays
class StringConcatenator {
private:
    int index1, index2;

public:
    char* firstString = new char[14];
    char* secondString = new char[18];
    char* concatenatedString = new char[33];

    StringConcatenator();
    void concatenate(char*, char*);
    void displayConcatenatedString();
    ~StringConcatenator();
};

// Constructor to initialize the character arrays
StringConcatenator::StringConcatenator() {
    firstString = "Engineers are ";
    secondString = "Creatures of logic";
}

// Concatenates two character arrays into a single string
void StringConcatenator::concatenate(char* str1, char* str2) {
    for (index1 = 0; index1 < 14; index1++) {
        concatenatedString[index1] = str1[index1];
    }

    for (index2 = 0; index2 < 18; index2++) {
        concatenatedString[index2 + 14] = str2[index2];
    }

    concatenatedString[32] = '\0'; // Null-terminate the concatenated string
}

// Displays the concatenated string
void StringConcatenator::displayConcatenatedString() {
    cout << concatenatedString;
}

// Destructor to free allocated memory
StringConcatenator::~StringConcatenator() {
    delete[] firstString;
    delete[] secondString;
    delete[] concatenatedString;
}

int main() {
    StringConcatenator stringObj;
    stringObj.concatenate(stringObj.firstString, stringObj.secondString);
    stringObj.displayConcatenatedString();
    return 0;
}

