    vehicleCount = count;
    std::cout << "Enter rental hours: ";
    std::cin >> rentalHours;
    std::cout << "Enter rental rate: ";
    std::cin >> rentalRate;

    // Apply discount for vehicle counts greater than 10
    if (vehicleCount > 10) {
        rentalRate -= static_cast<int>(0.1 * rentalRate);
    }
