class Calculator
{
private:
    int initialValue;
    int currentSum;

public:
    Calculator() {}
    Calculator(int value);

    int add(int value);    // Adds a value to the current sum
    int display() const;   // Returns the initial value
};

Calculator::Calculator(int value)
{
    initialValue = value;
}

int Calculator::add(int value)
{
    currentSum = initialValue + value; // Update the current sum with the new value
    return currentSum;
}

int Calculator::display() const
{
    return initialValue; // Return the initial value
}

