    std::cout << "Value of constant object: " << constantCalculator.display() << '\n';   // Display constant object value
    std::cout << "Changing value of non-constant object: " << normalCalculator.add(5) << '\n'; // Update and display new sum

    // std::cout << "Changing value of constant object: " << constantCalculator.add(6) << std::endl; // Cannot modify constant object

