#include <iostream>

class CartesianCoordinate;

class CoordinateOperations
{
public:
    void add(const CartesianCoordinate& a, const CartesianCoordinate& b, float* sumX, float* sumY);
    void subtract(const CartesianCoordinate& a, const CartesianCoordinate& b, float* subX, float* subY);
    void multiply(const CartesianCoordinate& a, const CartesianCoordinate& b, float* mulX, float* mulY);
    void divide(const CartesianCoordinate& a, const CartesianCoordinate& b, float* divX, float* divY);
};

class CartesianCoordinate
{
private:
    float x;
    float y;

public:
    CartesianCoordinate() {}
    CartesianCoordinate(float xValue, float yValue);

    friend void CoordinateOperations::add(const CartesianCoordinate&, const CartesianCoordinate&, float*, float*);
    friend class CoordinateOperations;
};

CartesianCoordinate::CartesianCoordinate(float xValue, float yValue)
    : x(xValue), y(yValue) {}

void CoordinateOperations::add(const CartesianCoordinate& a, const CartesianCoordinate& b, float* sumX, float* sumY)
{
    *sumX = a.x + b.x;
    *sumY = a.y + b.y;
}

void CoordinateOperations::subtract(const CartesianCoordinate& a, const CartesianCoordinate& b, float* subX, float* subY)
{
    *subX = a.x - b.x;
    *subY = a.y - b.y;
}

void CoordinateOperations::multiply(const CartesianCoordinate& a, const CartesianCoordinate& b, float* mulX, float* mulY)
{
    *mulX = a.x * b.x;
    *mulY = a.y * b.y;
}

void CoordinateOperations::divide(const CartesianCoordinate& a, const CartesianCoordinate& b, float* divX, float* divY)
{
    *divX = a.x / b.x;
    *divY = a.y / b.y;
}

void inputCoordinates(float* x, float* y)
{
    std::cout << "Enter x-coordinate: ";
    std::cin >> *x;
    std::cout << "Enter y-coordinate: ";
    std::cin >> *y;
}

int main()
{
    float x, y, sumX, sumY, subX, subY, mulX, mulY, divX, divY;

    inputCoordinates(&x, &y);
    CartesianCoordinate firstCoordinate(x, y);
    std::cout << "First object created" << '\n';

    inputCoordinates(&x, &y);
    CartesianCoordinate secondCoordinate(x, y);
    std::cout << "Second object created" << '\n';

    CoordinateOperations operations;
    operations.add(firstCoordinate, secondCoordinate, &sumX, &sumY);
    operations.subtract(firstCoordinate, secondCoordinate, &subX, &subY);
    operations.multiply(firstCoordinate, secondCoordinate, &mulX, &mulY);
    operations.divide(firstCoordinate, secondCoordinate, &divX, &divY);

    std::cout << "Sum = " << sumX << " , " << sumY 
              << " Difference = " << subX << " , " << subY 
              << " Product = " << mulX << " , " << mulY 
              << " Quotient = " << divX << " , " << divY << '\n';

    return 0;
}

#include <iostream>

class Coordinate {
private:
    float x, y, z;

public:
    Coordinate() : x(0), y(0), z(0) {}
    Coordinate(float xValue, float yValue, float zValue);

    friend void addCoordinates(const Coordinate& first, const Coordinate& second);
    friend void subtractCoordinates(const Coordinate& first, const Coordinate& second);
    friend Coordinate operator+(const Coordinate& first, const Coordinate& second);
    friend Coordinate operator-(const Coordinate& first, const Coordinate& second);
};

Coordinate operator+(const Coordinate& first, const Coordinate& second) {
    Coordinate result;
    result.x = first.x + second.x;
    result.y = first.y + second.y;
    result.z = first.z + second.z;
    return result;
}

Coordinate operator-(const Coordinate& first, const Coordinate& second) {
    Coordinate result;
    result.x = first.x - second.x;
    result.y = first.y - second.y;
    result.z = first.z - second.z;
    return result;
}

Coordinate::Coordinate(float xValue, float yValue, float zValue) 
    : x(xValue), y(yValue), z(zValue) {}

void addCoordinates(const Coordinate& first, const Coordinate& second) {
    Coordinate result = first + second;
    std::cout << "Addition:\n" << result.x << ", " << result.y << ", " << result.z << std::endl;
}

void subtractCoordinates(const Coordinate& first, const Coordinate& second) {
    Coordinate result = first - second;
    std::cout << "Difference:\n" << result.x << ", " << result.y << ", " << result.z << std::endl;
}

int main() {
    float x, y, z;

    std::cout << "Enter first x, y and z coordinates: ";
    std::cin >> x >> y >> z;
    Coordinate firstCoordinate(x, y, z);

    std::cout << "Enter second x, y and z coordinates: ";
    std::cin >> x >> y >> z;
    Coordinate secondCoordinate(x, y, z);

    addCoordinates(firstCoordinate, secondCoordinate);
    subtractCoordinates(firstCoordinate, secondCoordinate);

    return 0;
}

#include <iostream>

class Comparable {
public:
    int value;

    Comparable() : value(0) {}
    Comparable(int x);
};

Comparable::Comparable(int x) : value(x) {}

// Overloaded equality operator to compare two Comparable objects
bool operator==(const Comparable& lhs, const Comparable& rhs) {
    return lhs.value == rhs.value;
}

// Overloaded inequality operator to compare two Comparable objects
bool operator!=(const Comparable& lhs, const Comparable& rhs) {
    return lhs.value != rhs.value;
}

// Overloaded less-than operator to compare two Comparable objects
bool operator<(const Comparable& lhs, const Comparable& rhs) {
    return lhs.value < rhs.value;
}

// Overloaded greater-than operator to compare two Comparable objects
bool operator>(const Comparable& lhs, const Comparable& rhs) {
    return lhs.value > rhs.value;
}

// Overloaded less-than-or-equal operator to compare two Comparable objects
bool operator<=(const Comparable& lhs, const Comparable& rhs) {
    return lhs.value <= rhs.value;
}

// Overloaded greater-than-or-equal operator to compare two Comparable objects
bool operator>=(const Comparable& lhs, const Comparable& rhs) {
    return lhs.value >= rhs.value;
}

int main() {
    int firstInput, secondInput;

    std::cout << "Enter first object integer: ";
    std::cin >> firstInput;

    std::cout << "Enter second object integer: ";
    std::cin >> secondInput;

    Comparable firstObject(firstInput), secondObject(secondInput);

    // First comparison between two Comparable objects
    std::cout << "\nFirst Comparison: ";
    if (firstObject < secondObject) {
        std::cout << "\nSecond object is greater.";
    } else if (firstObject > secondObject) {
        std::cout << "\nFirst object is greater.";
    }

    // Second comparison for equality
    std::cout << '\n' << "Second Comparison: ";
    if (firstObject != secondObject) {
        std::cout << "\nFirst and second objects are not equal.";
    } else {
        std::cout << "\nObjects are equal.";
    }

    // Third comparison for less-than-or-equal and greater-than-or-equal
    std::cout << '\n' << "Third Comparison: ";
    if (firstObject <= secondObject) {
        std::cout << "\nSecond object is greater than or equal to the first object.";
    } else {
        std::cout << "\nFirst object is greater than or equal to the second object.";
    }

    return 0;
}

#include <iostream>

class Date {
private:
    int day, month, year;

public:
    Date() {}
    Date(int day = 23, int month = 11, int year = 2003);

    void displayDate();

    // Overloaded pre-increment operator to advance the date
    void operator++() {
        ++day;

        // Handle month transition for months with 30 days
        if (day > 30 && month != 2) {
            month++;
            day = 1;
        } 
        // Handle February transition
        else if (month == 2 && day > 28) {
            month++;
            day = 1;
        }

        // Handle year transition
        if (month > 12) {
            year++;
            month = 1;
        }

        // Special case for leap year adjustment
        if ((year % 4) == 0 && day == 28 && month == 2) {
            day++;
        }
    }

    // Overloaded post-increment operator to advance the date
    void operator++(int) {
        int temp = day++;

        // Handle month transition for months with 30 days
        if (day > 30 && month != 2) {
            month++;
            day = 1;
        } 
        // Handle February transition
        else if (month == 2 && day > 28) {
            month++;
            day = 1;
        }

        // Handle year transition
        if (month > 12) {
            year++;
            month = 1;
        }

        // Special case for leap year adjustment
        if ((year % 4) == 0 && day == 28 && month == 2) {
            day++;
        }
    }
};

Date::Date(int day, int month, int year) {
    this->day = day;
    this->month = month;
    this->year = year;
}

void Date::displayDate() {
    std::cout << "\nThe date is: " << day << "/" << month << "/" << year;
}

int main() {
    Date dateInstance(28, 12, 2003);
    char continueAdding, choice;

    std::cout << "Choose: \n1. Post increment \n2. Pre increment\n";
    std::cin >> choice;

    do {
        dateInstance.displayDate();
        if (choice == '1') {
            dateInstance++;
        } else if (choice == '2') {
            ++dateInstance;
        }
        std::cout << "\nDo you want to add to day (y/n): ";
        std::cin >> continueAdding;
    } while (continueAdding == 'y');

    return 0;
}

#include <iostream>

class DistanceConverter {
private:
    int meters;
    float centimeters;

public:
    DistanceConverter(int meters = 0, float centimeters = 0);
    DistanceConverter(float totalMeters);
    void display() const;

    // Conversion operator to float representing total meters
    operator float() const {
        return meters + (centimeters / 100.0f);
    }
};

DistanceConverter::DistanceConverter(int meters, float centimeters) {
    this->meters = meters;
    this->centimeters = centimeters;
}

DistanceConverter::DistanceConverter(float totalMeters) {
    meters = static_cast<int>(totalMeters);
    centimeters = (totalMeters - meters) * 100.0f;
}

void DistanceConverter::display() const {
    std::cout << meters << "m " << centimeters << "cm ";
}

int main() {
    int inputMeters;
    float inputCentimeters;

    std::cout << "Enter meters: ";
    std::cin >> inputMeters;

    std::cout << "Enter centimeters: ";
    std::cin >> inputCentimeters;

    DistanceConverter distance(inputMeters, inputCentimeters);
    float totalDistance = distance; // Conversion to float from class

    std::cout << totalDistance << "\n";

    DistanceConverter convertedDistance = totalDistance;
    convertedDistance.display();

    return 0;
}

