    float inch;

public:
    FeetInch(float f = 0, float i = 0) : feet(f), inch(i) {}

    // Conversion operator to MetricCentimeter
    operator MetricCentimeter();

    void display() const {
        std::cout << std::fixed << "\nFeet: " << feet << "\tInch: " << inch;
    }
};

class MetricCentimeter {
    float meter;
    float centimeter;

public:
    MetricCentimeter(float m = 0, float c = 0) : meter(m), centimeter(c) {}

    // Conversion operator to FeetInch
    operator FeetInch() {
        return FeetInch(3.2808 * meter, centimeter * 0.3937);
    }

    void display() const {
        std::cout << "\nMeter: " << meter << "\tCentimeter: " << centimeter;
    }
};

// Conversion from FeetInch to MetricCentimeter
FeetInch::operator MetricCentimeter() {
    return MetricCentimeter(feet / 3.2808, inch / 0.3937);
}

int main() {
    FeetInch feetInch1, feetInch2(1.58, 11.1);
    MetricCentimeter metricCentimeter1(2, 1.6), metricCentimeter2;

    feetInch1 = static_cast<FeetInch>(metricCentimeter1);
    metricCentimeter2 = static_cast<MetricCentimeter>(feetInch2);

    std::cout << "\nObject 1:";
    feetInch2.display();
    metricCentimeter2.display();

    std::cout << "\nObject 2:";
    metricCentimeter1.display();
    feetInch1.display();

    return 0;
}

