vector<Account *> Account::loadAllAccounts() {
    vector<Account *> accounts;
    ifstream inputFile("bank_ledger.txt");
    if (!inputFile)
        return {};
    // Populate the vector with account information from the file
    while (!inputFile.eof())
        inputFile >> accounts;
    return accounts;
}

long Account::retrieveLastAccountNumber() {
    // Return the latest account number from the list
    return Account::accountList.empty() ? 0 : (*Account::accountList.back()).getAccountNumber();
}

// Facilitators
void Account::openAccount() {
    string firstName;
    string lastName;
    cout << "\n*OPEN AN ACCOUNT*" << endl;
    cout << "First Name: " << endl;
    cin >> firstName;
    cout << "Last Name: " << endl;
    cin >> lastName;
    long initialAmount;
    cout << "Account Amount: " << endl;
    cin >> initialAmount;
    accountList.push_back(new Account("", "", 0));
    accountList.back()->setFirstName(firstName);
    accountList.back()->setLastName(lastName);
    accountList.back()->setAccountAmount(initialAmount);
    cout << *accountList.back() << endl;
    // Save the new account to the ledger file
    ofstream outputFile("bank_ledger.txt", ios::app);
    outputFile << *accountList.back();
    outputFile.close();
}

Account *Account::findAccountByNumber(const long &accountNumber) {
    // Search for an account by its number
    auto iterator = std::find_if(accountList.begin(), accountList.end(),
                                  [&](auto accountPtr) { return compareAccountNumber(accountPtr, accountNumber); });
    return (iterator != accountList.end()) ? *iterator : nullptr;
}

void Account::checkBalance() {
    long accountNumber;
    cout << "\n*BALANCE ENQUIRY*" << endl;
    cout << "Enter Account Number: " << endl;
    cin >> accountNumber;
    Account *accountPtr = findAccountByNumber(accountNumber);
    if (accountPtr != nullptr)
        cout << *accountPtr << endl;
    else
        cout << "Account Not Found." << endl;
}

void Account::updateLedger() {
    ofstream outputFile("bank_ledger.txt", ios::trunc);
    for (auto accountPtr : accountList)
        outputFile << *accountPtr;
    outputFile.close();
}

void Account::depositFunds() {
    long accountNumber;
    long depositAmount;
    cout << "\n*DEPOSIT*" << endl;
    cout << "Enter Account Number: " << endl;
    cin >> accountNumber;
    Account *accountPtr = findAccountByNumber(accountNumber);
    if (accountPtr != nullptr) {
        cout << *accountPtr << endl;
        cout << "\nEnter Deposit Amount: " << endl;
        cin >> depositAmount;
        accountPtr->setAccountAmount(depositAmount + accountPtr->getAccountAmount());
        cout << "Total Amount " << depositAmount << " has been deposited into Account Number " << accountNumber << endl;
        // Update the ledger file
        updateLedger();
        cout << *accountPtr << endl;
    } else {
        cout << "Account Not Found." << endl;
    }
}

void Account::withdrawFunds() {
    long accountNumber;
    long withdrawalAmount;
    cout << "\n*WITHDRAWAL*" << endl;
    cout << "Enter Account Number: " << endl;
    cin >> accountNumber;
    Account *accountPtr = findAccountByNumber(accountNumber);
    if (accountPtr != nullptr) {
        cout << *accountPtr << endl;
        cout << "\nEnter Withdrawal Amount: " << endl;
        cin >> withdrawalAmount;
        accountPtr->setAccountAmount(accountPtr->getAccountAmount() - withdrawalAmount);
        cout << "Total Amount " << withdrawalAmount << " has been withdrawn from Account Number " << accountNumber << endl;
        // Update the ledger file
        updateLedger();
        cout << *accountPtr << endl;
    } else {
        cout << "Account Not Found." << endl;
    }
}

void Account::closeAccount() {
    cout << "\n *CLOSE ACCOUNT* " << endl;
    long accountNumber;
    cout << "Enter Account Number: " << endl;
    cin >> accountNumber;
    Account *accountPtr = findAccountByNumber(accountNumber);
    if (accountPtr != nullptr) {
        auto iterator = std::remove_if(accountList.begin(), accountList.end(),
                                        [&](Account *acc) { return acc->getAccountNumber() == accountNumber; });
        accountList.erase(iterator, accountList.end());
        updateLedger();
        cout << "Account Number " << accountNumber << " has been closed." << endl;
    } else {
        cout << "Account Not Found." << endl;
    }
}

void Account::displayAllAccounts() {
    cout << "\n*ALL ACCOUNTS*";
    for (auto accountPtr : accountList)
        cout << *accountPtr << endl;
}

// Destructor
Account::~Account() = default;

// Friend Functions
ifstream &operator>>(ifstream &inputFile, vector<Account *> &accounts) {
    long accountNumber;
    string firstName;
    string lastName;
    long accountAmount;
    inputFile >> accountNumber >> firstName >> lastName >> accountAmount;
    accounts.push_back(new Account(accountNumber, firstName, lastName, accountAmount));
    return inputFile;
}

