#include <iostream>
#include <cstring>
#define MAX_CHAR_LENGTH 50

using namespace std;

class Book {
private:
    int *price, *stock;
    char *title, *authorName, *publisherName;

public:
    static int totalStock;

    // Allocates memory for the class variables.
    Book() {
        price = new int;
        stock = new int;
        title = new char[MAX_CHAR_LENGTH];
        authorName = new char[MAX_CHAR_LENGTH];
        publisherName = new char[MAX_CHAR_LENGTH];
        *stock = 0;
    }

    // Collects book details from user input.
    void collectData() {
        totalStock -= *stock;
        cout << "Enter the Title, Author, Publisher, Price, Stock: ";
        cin >> title >> authorName >> publisherName >> *price >> *stock;
        totalStock += *stock;
    }

    // Displays the book details.
    void displayData() const {
        cout << title << "\t" << authorName << "\t" << publisherName << "\t\t" << *price << "\t" << *stock << endl;
    }

    // Checks if the provided title and author match the book's details.
    bool matches(const char *name, const char *author) const {
        return (strcmp(title, name) == 0 && strcmp(authorName, author) == 0);
    }

    // Processes the purchase of books and updates stock accordingly.
    void processPurchase() {
        int quantity;
        cout << "Enter quantity of books: ";
        cin >> quantity;
        if (quantity > *stock) {
            cout << "Insufficient stock available";
            return;
        }
        cout << "Total cost of books is " << quantity * (*price) << endl;
        *stock -= quantity;
        totalStock -= quantity;
    }
};

int Book::totalStock = 0;

int main() {
    Book *bookCollection[10];
    int userChoice, currentBookIndex = 0;
    char author[MAX_CHAR_LENGTH], title[MAX_CHAR_LENGTH];

    while (true) {
