                bookCollection[currentBookIndex] = new Book();
                bookCollection[currentBookIndex++]->collectData();
                break;
            case 2:
                cout << "Title\tAuthor\tPublisher\t\tPrice\tStock\n";
                for (int i = 0; i < currentBookIndex; i++)
                    bookCollection[i]->displayData();
                break;
            case 5:
                cout << "Enter title and author of book to search: ";
                cin >> title >> author;
                for (int i = 0; i < currentBookIndex; i++)
                    if (bookCollection[i]->matches(title, author))
                        break;
                if (i == currentBookIndex)
                    cout << "Book not found";
                else {
                    cout << "Title\tAuthor\tPublisher\t\tPrice\tStock\n";
                    bookCollection[i]->displayData();
                    bookCollection[i]->collectData();
                }
                break;
            case 4:
                cout << "Enter title and author of book to search: ";
                cin >> title >> author;
                for (int i = 0; i < currentBookIndex; i++)
                    if (bookCollection[i]->matches(title, author))
                        break;
                if (i == currentBookIndex)
