class Complex {
    int realPart, imaginaryPart;

public:
    // Initializes a Complex number by prompting user input
    Complex() {
        requestInput();
    }

    // Initializes a Complex number with specified real and imaginary parts
    Complex(int real, int imaginary) {
        realPart = real;
        imaginaryPart = imaginary;
    }

    // Prompts the user to input the real and imaginary parts
    void requestInput() {
        cout << "Enter the Real and Imaginary parts: ";
        cin >> realPart >> imaginaryPart;
    }

    // Overloads the + operator to add two Complex numbers
    Complex operator + (const Complex& other) {
        return Complex(realPart + other.realPart, imaginaryPart + other.imaginaryPart);
    }

    // Friend function to add two Complex numbers
    friend Complex addComplexNumbers(const Complex& complex1, const Complex& complex2);
};

// Adds two Complex numbers and returns the result
Complex addComplexNumbers(const Complex& complex1, const Complex& complex2) {
    return Complex(complex1.realPart + complex2.realPart, complex1.imaginaryPart + complex2.imaginaryPart);
}

