    TourBus() {
        busId = 0;
        maxSeats = 50;
        bookedSeats = 0;
        fare = 0;
        strcpy(departureTime, "9:10am");
        strcpy(destination, "");
    }

    void inputDetails();
    void displayDetails();
    void showDetails();
    int getId() const {
        return busId;
    }
    void bookSeat() {
        bookedSeats++;
    }
    const char* getDestination() const {
        return destination;
    }
    const char* getDepartureTime() const {
        return departureTime;
    }
    int getBookedSeats() const {
        return bookedSeats;
    }
    int getMaxSeats() const {
        return maxSeats;
    }
    int getFare() const {
        return fare;
    }
};

class Ticket {
    char customerName[50];
    TourBus bus;

public:
    void generate(const char customerName[], const TourBus& bus) {
        strcpy(this->customerName, customerName);
        this->bus = bus;
    }

    void display() const {
        std::cout << "Customer Name: " << customerName << std::endl;
        std::cout << "Bus Details: " << std::endl;
