                bus.inputDetails();
                busFile.write(reinterpret_cast<char*>(&bus), sizeof(bus));
                busFile.close();
                std::cout << "Bus added successfully." << std::endl;
                break;

            case 2: {
                int id, found = 0;
                std::cout << "Enter the bus ID to be displayed: ";
                std::cin >> id;
                busFile.open("tour.dat", std::ios::in | std::ios::binary);
                if (busFile.fail()) {
                    std::cout << "Can't open file." << std::endl;
                } else {
                    while (busFile.read(reinterpret_cast<char*>(&bus), sizeof(bus))) {
                        if (bus.getId() == id) {
                            bus.showDetails();
                            found = 1;
                            break;
                        }
                    }
                    if (!found) {
                        std::cout << "Bus not found." << std::endl;
                    }
                }
                busFile.close();
                break;
            }

            case 3:
                busFile.open("tour.dat", std::ios::in | std::ios::binary);
                if (busFile.fail()) {
                    std::cout << "Can't open file." << std::endl;
                } else {
                    while (busFile.read(reinterpret_cast<char*>(&bus), sizeof(bus))) {
                        bus.displayDetails();
                    }
                }
                busFile.close();
                break;

            case 4: {
                int id, found = 0;
                std::cout << "Enter the bus ID to be deleted: ";
                std::cin >> id;
                busFile.open("tour.dat", std::ios::in | std::ios::binary);
                tempFile.open("temp.dat", std::ios::out | std::ios::binary);
                if (busFile.fail()) {
                    std::cout << "Can't open file." << std::endl;
                } else {
                    while (busFile.read(reinterpret_cast<char*>(&bus), sizeof(bus))) {
                        if (bus.getId() != id) {
                            tempFile.write(reinterpret_cast<char*>(&bus), sizeof(bus));
                        } else {
                            bus.showDetails();
                            found = 1;
                        }
                    }
                    if (!found) {
                        std::cout << "Bus not found." << std::endl;
                    } else {
                        std::cout << "Bus deleted." << std::endl;
                    }
                }
                busFile.close();
                tempFile.close();
                remove("tour.dat");
                rename("temp.dat", "tour.dat");
