                    int found = 0;
                    while (busFile.read(reinterpret_cast<char*>(&bus), sizeof(bus))) {
                        if (strcmp(bus.getDestination(), destination) == 0) {
                            bus.showDetails();
                            found = 1;
                            std::cout << "Enter the customer name: ";
