                            bus.bookSeat();
                            ticket.generate(customerName, bus);
                            std::fstream ticketFile("tickets.dat", std::ios::app | std::ios::binary);
                            ticketFile.write(reinterpret_cast<char*>(&ticket), sizeof(ticket));
                            ticketFile.close();
                            busFile.seekp(busFile.tellg() - sizeof(bus), std::ios::beg);
                            busFile.write(reinterpret_cast<char*>(&bus), sizeof(bus));
                            std::cout << "Ticket booked." << std::endl;
