                        }
                    }
                    if (!found) {
                        std::cout << "No bus found." << std::endl;
                    }
                }
                busFile.close();
                break;
            }

            case 6: {
                std::cout << "Booked Tickets: " << std::endl;
                std::fstream ticketFile("tickets.dat", std::ios::in | std::ios::binary);
                if (ticketFile.fail()) {
                    std::cout << "Can't open file." << std::endl;
                } else {
                    Ticket ticket;
                    while (ticketFile.read(reinterpret_cast<char*>(&ticket), sizeof(ticket))) {
                        ticket.display();
                    }
                }
                ticketFile.close();
                break;
            }
        }
    } while (choice != 7);

    return 0;
}

