#include <iostream>
using namespace std;

class BankingSystem
{
private:
    long int accountNumber, mobileNumber, accountBalance, depositAmount, withdrawalAmount;
    string customerName, customerAddress, customerEmail;
    char depositChoice, continueChoice;

public:
    void openNewAccount(int customerCount, BankingSystem *accounts);
    void displayAccountInfo();
    void withdrawAmount();
    void depositAmount();
    void displayBalanceInfo();
    int checkAccountExistence(long int accountNumber, BankingSystem *accounts, int totalAccounts);
    int getAccountNumber();
};

void BankingSystem::openNewAccount(int customerCount, BankingSystem *accounts)
{
    accountBalance = 0;
    depositAmount = 0;
    int isUniqueAccount = 0;

    cout << "WELCOME! YOU ARE CUSTOMER NUMBER " << (customerCount + 1) << endl << endl;
    cout << "PLEASE ENTER A DESIRED ACCOUNT NUMBER" << endl;

    do {
        cin >> accountNumber;
        if (accountNumber == checkAccountExistence(accountNumber, accounts, customerCount)) {
            cout << "ACCOUNT NUMBER ALREADY EXISTS. PLEASE ENTER A UNIQUE ONE" << endl;
            isUniqueAccount = 1;
        } else {
            isUniqueAccount = 0;
        }
    } while (isUniqueAccount == 1);

    cin.ignore();
    cout << "PLEASE ENTER YOUR NAME" << endl;
    getline(cin, customerName);
    cout << "PLEASE ENTER YOUR ADDRESS" << endl;
    getline(cin, customerAddress);
    cout << "PLEASE ENTER YOUR MOBILE NUMBER" << endl;
    cin >> mobileNumber;
    cin.ignore();
    cout << "PLEASE ENTER YOUR VALID EMAIL ID" << endl;
    getline(cin, customerEmail);
    cout << "WOULD YOU LIKE TO DEPOSIT AN AMOUNT? (Y/N)" << endl;
    cin >> depositChoice;

    do {
        if (toupper(depositChoice) == 'Y') {
            cout << "PLEASE ENTER THE AMOUNT" << endl;
            cin >> depositAmount;
            accountBalance += depositAmount;
        } else if (toupper(depositChoice) == 'N') {
            cout << "NO WORRIES, YOU CAN HAVE A ZERO BALANCE ACCOUNT" << endl;
            break;
        } else {
            cout << "PLEASE ENTER A VALID CHOICE" << endl;
        }
        cout << "WOULD YOU LIKE TO ADD MORE DEPOSIT? (Y/N)" << endl;
        cin >> continueChoice;
    } while (toupper(continueChoice) == 'Y');

    cout << endl;
    cout << "HELLO " << customerName << ", YOUR ACCOUNT NUMBER " << accountNumber << " HAS A BALANCE OF " << accountBalance << endl << endl;
}

int BankingSystem::checkAccountExistence(long int accountNumberToCheck, BankingSystem *accounts, int totalAccounts)
{
    for (int i = 0; i < totalAccounts; i++) {
        if (accounts[i].getAccountNumber() == accountNumberToCheck) {
            return accountNumberToCheck;
        }
    }
    return 0;
}

int BankingSystem::getAccountNumber()
{
    return accountNumber;
}

void BankingSystem::displayAccountInfo()
{
    cout << "HELLO " << customerName << ", YOUR ACCOUNT NUMBER " << accountNumber << " HAS A BALANCE OF " << accountBalance << endl;
}

void BankingSystem::withdrawAmount()
{
    cout << "HELLO " << customerName << ", YOUR CURRENT BALANCE IS " << accountBalance << endl << "PLEASE ENTER THE AMOUNT TO WITHDRAW" << endl;
    do {
        cin >> withdrawalAmount;
        if (accountBalance < withdrawalAmount) {
            cout << "INSUFFICIENT BALANCE" << endl;
        } else {
            accountBalance -= withdrawalAmount;
        }
        cout << "WOULD YOU LIKE TO CONTINUE WITHDRAWING? (Y/N)" << endl;
        cin >> continueChoice;
    } while (toupper(continueChoice) == 'Y');
    cout << "YOUR NEW BALANCE IS " << accountBalance << endl;
}

void BankingSystem::depositAmount()
{
    cout << "HELLO " << customerName << ", YOUR CURRENT BALANCE IS " << accountBalance << endl << "PLEASE ENTER THE AMOUNT TO DEPOSIT" << endl;
    do {
        cin >> withdrawalAmount;
        accountBalance += withdrawalAmount;
        cout << "WOULD YOU LIKE TO CONTINUE DEPOSITING? (Y/N)" << endl;
        cin >> continueChoice;
    } while (toupper(continueChoice) == 'Y');
    cout << "YOUR NEW BALANCE IS " << accountBalance << endl;
}

