void issueBook(string bookCode) {
    MYSQL* connection;
    MYSQL_ROW row;
    MYSQL_RES* result;
    string remainingCopies;
    int queryState, availableCopies;

    connection = mysql_init(0);
    if (connection) {
        cout << "Connection object created, conn=" << connection << endl;
    } else {
        cout << "Connection object problem: " << mysql_error(connection);
    }

    connection = mysql_real_connect(connection, "localhost", "root", "", "lms", 0, NULL, 0);
    string query = "SELECT * FROM book WHERE code='" + bookCode + "'";
    const char* q = query.c_str();
