#ifndef SINGLY_LINKED_LIST
#define SINGLY_LINKED_LIST

#include <stdexcept>

// Forward declarations of classes
template <typename T>
class SLL;

template <typename T>
class Iterator;

// Node class representing each element in the linked list
template <typename T>
class Node {
public:
    Node() : next(nullptr) {}

    Node(T data, Node<T>* link = nullptr) : info(data), next(link) {}

    // Grant access to SLL and Iterator classes
    friend class SLL<T>;
    friend class Iterator<T>;

private:
    T info;
    Node<T>* next;
};

// Iterator class for traversing the linked list
template<typename T>
class Iterator {
public:
    Iterator(Node<T>* p) : current(p) {}

    Iterator next() {
        current = current->next;
        return *this;
    }

    T content() {
        return current->info;
    }

    bool isEqual(const Iterator<T>& itr) const {
        return current == itr.current;
    }

    bool operator==(const Iterator<T>& itr) const {
        return isEqual(itr);
    }

    bool operator!=(const Iterator<T>& itr) const {
        return !isEqual(itr);
    }

    Iterator operator++() {
        return next();
    }

    T& operator*() {
        return current->info;
    }

    // Grant access to SLL class
    friend class SLL<T>;

private:
    Node<T>* current;
};

// Singly Linked List class
template<typename T>
class SLL {
public:
    SLL() : head(nullptr), tail(nullptr), size(0) {}

    ~SLL() {
        while (head != nullptr) {
            Node<T>* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void addFirst(T data);
    void addLast(T data);
    void add(Iterator<T> p, T data);
    void removeRoom(Iterator<T> p);
    T removeFirst();
    T removeLast();
    bool remove(T target);
    Node<T> getObject(int index) const;
    T getInfo(int index) const;
    Iterator<T> begin() const;
    Iterator<T> end() const;

    friend class Iterator<T>;

private:
    Node<T>* head;
    Node<T>* tail;
    long size;
};

template<typename T>
void SLL<T>::addFirst(T data) {
    Node<T>* newNode = new Node<T>(data, head);
    head = (head == nullptr) ? newNode : head;
    tail = (tail == nullptr) ? newNode : tail;
    size++;
}

template<typename T>
void SLL<T>::addLast(T data) {
    Node<T>* newNode = new Node<T>(data);
    if (head == nullptr) {
        head = tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }
    size++;
}

template<typename T>
void SLL<T>::add(Iterator<T> p, T data) {
    Node<T>* newNode = new Node<T>(data, p.current->next);
    p.current->next = newNode;
}

template<typename T>
void SLL<T>::removeRoom(Iterator<T> p) {
    if (p.current == head) {
        delete head;
        head = nullptr;
        return;
    }

    Node<T>* currentNode = head;
    while (currentNode->next != p.current) {
        currentNode = currentNode->next;
    }

    Node<T>* nodeToRemove = p.current;
    p.current = currentNode;
    p.current->next = nodeToRemove->next;
    delete nodeToRemove;
}

template<typename T>
T SLL<T>::removeFirst() {
    if (head == nullptr) {
        throw std::runtime_error("ERROR: Empty List!");
    }
    Node<T>* temp = head;
    head = head->next;
    if (head == nullptr) {
        tail = nullptr;
    }
    T data = temp->info;
    delete temp;
    size--;
    return data;
}

template<typename T>
T SLL<T>::removeLast() {
    if (head == nullptr) {
        throw std::runtime_error("ERROR: Empty List!");
    }
    Node<T>* currentNode = head;
    if (head == tail) {
        T data = head->info;
        delete head;
        head = tail = nullptr;
        size--;
        return data;
    }

    while (currentNode->next != tail) {
        currentNode = currentNode->next;
    }

    T data = tail->info;
    delete tail;
    tail = currentNode;
    tail->next = nullptr;
    size--;
    return data;
}

template<typename T>
bool SLL<T>::remove(T target) {
    if (head == nullptr) {
        throw std::runtime_error("ERROR: Empty List!");
    }

    Node<T>* currentNode = head;
    Node<T>* previousNode = nullptr;

    while (currentNode != nullptr) {
        if (currentNode->info == target) {
            if (previousNode == nullptr) {
                head = head->next;
                if (head == nullptr) {
                    tail = nullptr;
                }
            } else {
                previousNode->next = currentNode->next;
                if (currentNode == tail) {
                    tail = previousNode;
                }
            }
            delete currentNode;
            size--;
            return true;
        }
        previousNode = currentNode;
        currentNode = currentNode->next;
    }
    return false;
}

template<typename T>
Node<T> SLL<T>::getObject(int index) const {
    if (index < 0 || index >= size) {
        throw std::runtime_error("Index out of range");
    }
    Node<T>* currentNode = head;
    for (int i = 0; i < index; i++) {
        currentNode = currentNode->next;
    }
    return *currentNode;
}

template<typename T>
T SLL<T>::getInfo(int index) const {
    if (index < 0 || index >= size) {
        throw std::runtime_error("Index out of range");
    }
    Node<T>* currentNode = head;
    for (int i = 0; i < index; i++) {
        currentNode = currentNode->next;
    }
    return currentNode->info;
}

template<typename T>
Iterator<T> SLL<T>::begin() const {
    return Iterator<T>(head);
}

template<typename T>
Iterator<T> SLL<T>::end() const {
    return Iterator<T>(tail->next);
}

