/**
 * Checks if a video with the given barcode already exists.
 * barcode: The barcode to look up.
 * Returns 1 if found, 0 otherwise.
 */
int checkBarcodeExists(int barcode) {
    inputFile.seekg(ios::beg);
    Video video;
    while (inputFile.read(reinterpret_cast<char*>(&video), sizeof(video))) {
        if (video.getBarcode() == barcode) {
            return 1;
        }
    }
    return 0;
}

