        }
    } while (pinStream.str().length() > 4 || pinStream.str().length() < 4);

    newNode->pin = temporaryAccountPin;

    cout << setw(18) << "Initial Amount: ";     
    cin >> temporaryInitialDeposit;
    temporaryBalance = temporaryInitialDeposit;

    newNode->balance = temporaryBalance;

    // Generate a random account number
    srand(static_cast<unsigned>(time(0))); 
    int randomAccountNumber = 0;
    for(int index = 0; index < 20; index++) { 
        randomAccountNumber += (rand() % 10) + 1; 
    }

    accountNumber = randomAccountNumber; // Assign random number to accountNumber
    newNode->accountNumber = accountNumber;

    // Insert new node into the linked list
    if (headPtr == nullptr) { 
        headPtr = newNode;
    } else {
        currPtr = headPtr;
        while (currPtr->nextNode != nullptr) {
            currPtr = currPtr->nextNode;      
        }   
        currPtr->nextNode = newNode;  
    }

    cout << "\n  Your new account number is " << accountNumber << "\n\n";
}

