bool AccountHolder::validateAccountNumber() {
    cin.ignore(); // Clear the input buffer

    // Request and validate user's account number
    do {
        cin >> temporaryAccountNumber;

        if (headPtr == nullptr) {
            cout << "  No accounts in database.";
            return false;
        } else {
            currPtr = headPtr;
            while (currPtr != nullptr) {
                if (currPtr->accountNumber == temporaryAccountNumber)
                    return true;                           
                currPtr = currPtr->nextNode;
            }
            cout << "  Account not in database. Please try again: ";
        }
    } while (true);
}

