//*************************************************************//
//       method to deposit funds                               //
//*************************************************************//

void AccountHolder::depositFunds() {
    cin.ignore(); // Clear the input buffer
    cin >> temporaryAmount; 

    currPtr = headPtr;

    while (currPtr != nullptr) {
        if (currPtr->accountNumber == temporaryAccountNumber && currPtr->pin == temporaryAccountPin) {
            currPtr->balance += temporaryAmount;
            break; // Exit the loop
        }
        currPtr = currPtr->nextNode;                           
    }  
}

//*************************************************************//
//       method to withdraw funds                              //
//*************************************************************//

bool AccountHolder::withdrawFunds() {
    cin.ignore(); // Clear the input buffer
    cin >> temporaryAmount;  

    currPtr = headPtr;

    while (currPtr != nullptr) {
        if (currPtr->accountNumber == temporaryAccountNumber && currPtr->pin == temporaryAccountPin) {
            if (temporaryAmount < currPtr->balance) {
                currPtr->balance -= temporaryAmount;
                return true;
            }
            return false; // Insufficient funds
        }
        currPtr = currPtr->nextNode;                          
    }
    return false; // Account not found
}

//*************************************************************//
//       method to close account                               //
//*************************************************************//

void AccountHolder::closeAccount() {
    cin.ignore(); // Clear the input buffer

    // Request and validate user's account and pin numbers
    cout << "  Enter account number: ";
    if (validateAccountNumber()) {
        cout << "  Enter pin number: ";
        validatePinNumber();
    }

    NodePointer deleteNode = nullptr; // Pointer for the node to be deleted
    tempPtr = headPtr;
    currPtr = headPtr;

    while (currPtr != nullptr && (currPtr->accountNumber != temporaryAccountNumber || currPtr->pin != temporaryAccountPin)) {
        tempPtr = currPtr;
        currPtr = currPtr->nextNode;                         
    }

    if (currPtr != nullptr) {
        deleteNode = currPtr;
        currPtr = currPtr->nextNode; 
        tempPtr->nextNode = currPtr; // Patch the linked list
        delete deleteNode; // Remove the node from the list
        cout << "  Your account was successfully deleted.";
    } else {
        cout << "  Account not found.";
    }
}

