         << find_mode_index(int_array, 9, sizeof(int), compare_ints) << endl << endl;
    cout << "Index of the mode in the double array: "
         << find_mode_index(double_array, 5, sizeof(double), compare_doubles) << endl << endl;
    cout << "Index of the mode in the char array: "
         << find_mode_index(char_array, 6, sizeof(char), compare_chars) << endl << endl;
    cout << "Index of the mode in the DayOfYear array: "
         << find_mode_index(days, 12, sizeof(DayOfYear), compare_days) << endl << endl;
