int find_mode_index(const void* array, size_t element_count, size_t element_size, bool (*equals)(const void*, const void*)) {
    // Initialize variables to track the mode and its frequency.
    int first_index = -1;
    int current_count = 0;
    int max_count = 0;
    unsigned char* temp;

    unsigned char* start = (unsigned char*)array;
    unsigned char* end = (unsigned char*)(start + (element_count * element_size));

    // Iterate through each element to find the mode.
    for (unsigned char* current = start; current < end; current += element_size) {
        for (unsigned char* compare = start; compare < end; compare += element_size) {
            if (equals(current, compare)) {
                ++current_count;
            }
        }
        if (current_count > max_count) {
            // Update mode information if a new mode is found.
            max_count = current_count;
            temp = current;
        }
        current_count = 0;
    }

    // Calculate the index of the mode based on its address.
    first_index = (temp - start) / element_size;

    return first_index;
}

