bool compare_days(const void* a, const void* b) {
    const DayOfYear* first = (const DayOfYear*)a;
    const DayOfYear* second = (const DayOfYear*)b;

    return (first->day == second->day && first->month == second->month);
}

bool compare_ints(const void* a, const void* b) {
    const int* first = (const int*)a;
    const int* second = (const int*)b;

    return (*first == *second);
}

bool compare_doubles(const void* a, const void* b) {
    const double* first = (const double*)a;
    const double* second = (const double*)b;

    return (*first == *second);
}

bool compare_chars(const void* a, const void* b) {
    const char* first = (const char*)a;
    const char* second = (const char*)b;

    return (*first == *second);
}

bool compare_people(const void* a, const void* b) {
    const Person* first = (const Person*)a;
    const Person* second = (const Person*)b;

    return (first->getAge() == second->getAge() &&
            first->getHeight() == second->getHeight() &&
            first->getFirstName() == second->getFirstName() &&
            first->getLastName() == second->getLastName());
}

