    cout << "It's your turn to play\n";
    cin >> userInput;

    game2 += game2[userInput.c_str()];
    cout << game2++;
    cout << game2;

    // Undo the last move and show the state
    cout << game2--;
    cout << game2--;

    cout << --game2;
    cout << --game2;

    cout << "The game has been reset to the beginning, it's your turn to play\n";
    cin >> userInput;

    game2 += game2[userInput.c_str()];
    cout << game2++;
    cout << game2;

    cout << "-------------------------------------------------------------\n";
    cout << "Testing the () operator\n";
    cout << game2(4, "d");
}

