// Utility class for string manipulation and memory management
class StringHelper {
public:
    // Calculate the length of a string
    static int GetStringLength(const string& str) {
        return str.length();
    }

    // Create a new string from a temporary character buffer
    static char* CreateStringFromBuffer(const char* buffer) {
        int length = GetStringLength(buffer);
        char* newString = new char[length + 1];
        strcpy(newString, buffer);
        return newString;
    }
};

// Class representing a book in the library
class Book {
public:
    char* ID;        // Book ID
    char* Title;     // Book Title
    char* Type;      // Book Type
    char* Author;    // Book Author
    int Quantity;    // Available quantity of the book

    // Default constructor
    Book() : ID(nullptr), Title(nullptr), Type(nullptr), Author(nullptr), Quantity(0) {}

    // Load book data from a file
    void LoadDataFromFile(ifstream& file) {
        char temp[100];
        file >> temp;
        ID = StringHelper::CreateStringFromBuffer(temp);
        file.ignore();
        file.getline(temp, 100);
        Title = StringHelper::CreateStringFromBuffer(temp);
        file.getline(temp, 100);
        Author = StringHelper::CreateStringFromBuffer(temp);
        file >> Quantity;
    }

    // Assignment operator
    void operator=(const Book& rhs) {
        ID = StringHelper::CreateStringFromBuffer(rhs.ID);
        Title = StringHelper::CreateStringFromBuffer(rhs.Title);
        Author = StringHelper::CreateStringFromBuffer(rhs.Author);
        Quantity = rhs.Quantity;
    }
};

// Class representing the library containing books
class Library {
public:
    Book** BookList;     // List of all available books
    int AvailableBooks;  // Count of available books

    // Default constructor
    Library() : BookList(nullptr), AvailableBooks(0) {}

    // Update the book data in the file
    void UpdateBooks() {
        ofstream outFile("Books.txt");
        for (int i = 0; i < AvailableBooks; i++) {
            outFile << BookList[i]->ID << endl;
            outFile << BookList[i]->Title << endl;
            outFile << BookList[i]->Author << endl;
            outFile << BookList[i]->Quantity;
            if (i != AvailableBooks - 1) {
                outFile << endl;
            }
        }
        outFile.close();
    }

    // Read book data from the file and populate the BookList
    void ReadDataFromFile() {
        ifstream inFile("Books.txt");
        char temp[100];
        while (inFile >> temp) {
            AvailableBooks++;
            inFile.ignore(100, '\n'); // Skip to the next line
        }
        inFile.clear();
        inFile.seekg(0, ios::beg); // Reset file pointer

        BookList = new Book*[AvailableBooks];
        for (int i = 0; i < AvailableBooks; i++) {
            BookList[i] = new Book;
            BookList[i]->LoadDataFromFile(inFile);
        }
        inFile.close();
    }

    // Display available books
    void ViewAvailableBooks() {
        if (BookList != nullptr) {
            for (int i = 0; i < AvailableBooks; i++) {
                cout << BookList[i]->ID << "\t" << BookList[i]->Title << "\t" << BookList[i]->Author << "\t" << BookList[i]->Quantity << endl;
            }
        } else {
            cout << "No books found!" << endl;
        }
    }

    // Search for a book by ID
    Book* SearchByID(const char* id) {
        for (int i = 0; i < AvailableBooks; i++) {
            if (strcmp(BookList[i]->ID, id) == 0) {
                return BookList[i];
            }
        }
        return nullptr;
    }

    // Search for a book by title
    Book* SearchByTitle(const char* title) {
        for (int i = 0; i < AvailableBooks; i++) {
            if (strcmp(BookList[i]->Title, title) == 0) {
                return BookList[i];
            }
        }
        return nullptr;
    }

    // Search for books by author
    Book** SearchByAuthor(const char* author, int& count) {
        Book** authors = new Book*[AvailableBooks];
        count = 0;
        for (int i = 0; i < AvailableBooks; i++) {
            if (strcmp(BookList[i]->Author, author) == 0) {
                authors[count++] = BookList[i];
            }
        }
        return authors;
    }

    // Search for a book based on user input
    void SearchBook() {
        cout << "1. Search by ID\n2. Search by Title\n3. Search by Author\n";
        int choice;
        cin >> choice;

        if (choice == 1) {
            char id[10];
            cout << "Enter the ID: ";
            cin >> id;
            Book* book = SearchByID(id);
            if (book) {
                cout << book->ID << "\t" << book->Title << "\t" << book->Author << "\t" << book->Quantity << endl;
            } else {
                cout << "ID not found!" << endl;
            }
        } else if (choice == 2) {
            char title[100];
            cout << "Enter the Title: ";
            cin.ignore();
            cin.getline(title, 100);
            Book* book = SearchByTitle(title);
            if (book) {
                cout << book->ID << "\t" << book->Title << "\t" << book->Author << "\t" << book->Quantity << endl;
            } else {
                cout << "Title not found!" << endl;
            }
        } else if (choice == 3) {
            char author[100];
            cout << "Enter the Author Name: ";
            cin.ignore();
            cin.getline(author, 100);
            int count;
            Book** books = SearchByAuthor(author, count);
            if (count > 0) {
                for (int i = 0; i < count; i++) {
                    cout << books[i]->ID << "\t" << books[i]->Title << "\t" << books[i]->Author << "\t" << books[i]->Quantity << endl;
                }
                delete[] books;
            } else {
                cout << "No books found by that author!" << endl;
            }
        }
    }
};

