    cout << "Enter initial deposit amount: ";
    cin >> accountBalance;

    cout << "Your account has been successfully created.\n";
}

void BankAccount::depositMoney() {
    int depositAmount;
    cout << "Enter amount to deposit: ";
    cin >> depositAmount;

    accountBalance += depositAmount;
    cout << "Total balance: " << accountBalance << endl;
}

void BankAccount::withdrawMoney() {
    float withdrawalAmount;
    cout << "\nWithdraw:\nEnter amount to withdraw: ";
    cin >> withdrawalAmount;

    accountBalance -= withdrawalAmount;
    cout << "Your remaining balance is: " << accountBalance << endl;
}

void BankAccount::displayAccountDetails() {
    cout << "Account Holder Name: " << accountHolderName << endl;
    cout << "Address: " << address << endl;
    cout << "Account Type: " << accountType << endl;
    cout << "Total Balance: " << accountBalance << endl;
}

int main() {
    int choice;
    char continueOption;
    BankAccount account;

    do {
        cout << "1. Open Account\n";
        cout << "2. Deposit Money\n";
        cout << "3. Withdraw Money\n";
        cout << "4. Display Account Details\n";
        cout << "5. Exit\n";
        cout << "Select an option from above: ";
        cin >> choice;

        switch (choice) {
            case 1:
                account.openAccount();
                break;
            case 2:
                account.depositMoney();
                break;
            case 3:
                account.withdrawMoney();
                break;
            case 4:
                account.displayAccountDetails();
                break;
            case 5:
                exit(0);
            default:
                cout << "Invalid option, please try again.\n";
                break;
        }

        cout << "\nDo you want to select another option? Press 'y' for yes or 'N' to exit: ";
        cin >> continueOption;

    } while (continueOption == 'y' || continueOption == 'Y');

    return 0;
}

