#include <iostream>
using namespace std;

class ComplexNumber {
public:
    ComplexNumber(int realPart, int imaginaryPart);
    ComplexNumber();
    ~ComplexNumber();

    static int getCount() { return count; }

    ComplexNumber operator+(const ComplexNumber& other) const;
    ComplexNumber operator-(const ComplexNumber& other) const;
    ComplexNumber operator*(const ComplexNumber& other) const;

    friend ostream& operator<<(ostream& output, const ComplexNumber& complex);
    friend istream& operator>>(istream& input, ComplexNumber& complex);

    bool operator==(const ComplexNumber& other) const;
    ComplexNumber& operator=(const ComplexNumber& other);

private:
    static int count;
    int real;
    int imag;
};

void testComplexNumberOperations();

int ComplexNumber::count = 0;

int main() {
    testComplexNumberOperations();
    return 0;
}

ComplexNumber::ComplexNumber(int realPart, int imaginaryPart) : real(realPart), imag(imaginaryPart) {
    count++;
}

ComplexNumber::ComplexNumber() : ComplexNumber(1, 1) {
    // Delegating constructor to initialize with default values
}

ComplexNumber::~ComplexNumber() {
    count--;
}

ComplexNumber ComplexNumber::operator+(const ComplexNumber& other) const {
    ComplexNumber result;
    result.real = real + other.real;
    result.imag = imag + other.imag;
    return result;
}

ComplexNumber ComplexNumber::operator-(const ComplexNumber& other) const {
    ComplexNumber result;
    result.real = real - other.real;
    result.imag = imag - other.imag;
    return result;
}

ComplexNumber ComplexNumber::operator*(const ComplexNumber& other) const {
    ComplexNumber result;
    result.real = real * other.real - imag * other.imag;
    result.imag = real * other.imag + imag * other.real;
    return result;
}

ostream& operator<<(ostream& output, const ComplexNumber& complex) {
    output << complex.real << " + " << complex.imag << "i" << endl;
    return output;
}

istream& operator>>(istream& input, ComplexNumber& complex) {
    cout << "Enter real part: ";
    input >> complex.real;
    cout << "Enter imaginary part: ";
    input >> complex.imag;
    return input;
}

bool ComplexNumber::operator==(const ComplexNumber& other) const {
    return (real == other.real && imag == other.imag);
}

ComplexNumber& ComplexNumber::operator=(const ComplexNumber& other) {
    // Member-wise assignment
    real = other.real;
    imag = other.imag;
    return *this;
}

void testComplexNumberOperations() {
    ComplexNumber number1, number2;
    cin >> number1;
    cin >> number2;

    cout << number1;
    cout << number2;

    cout << "Adding result of two numbers: " << number1 + number2 << endl;
    cout << "Subtraction result of two numbers: " << number1 - number2 << endl;
    cout << "Multiplication result of two numbers: " << number1 * number2 << endl;

    if (number1 == number2) {
        cout << "Two numbers are equal!" << endl;
    } else {
        cout << "Two numbers are not equal!" << endl;
    }

    number1 = number2;

    if (number1 == number2) {
        cout << "Two numbers are equal!" << endl;
    } else {
        cout << "Two numbers are not equal!" << endl;
    }

    cout << "Number of objects: " << ComplexNumber::getCount() << endl;
}

