    ~String(); // Destructor to clean up allocated memory
    String& operator=(const String& rightSide); // Assignment operator
    String(const String& strObject); // Copy constructor
    String& operator+(const String& secondString); // Concatenation operator
    char& operator[](int index); // Indexing operator
    friend ostream& operator<<(ostream& outstream, const String& myString); // Output stream operator

    void addCharacterToEnd(char letter, int lastIndex); // Add character to the end of the string
    bool isFull() const; // Check if the string is full
    int getLength() const; // Get the length of the string
};

