String::String(int size) : length(size) {
    characters = new char[size];
}

inline int String::getLength() const {
    return length;
}

String& String::operator=(const String& rightSide) {
    if (length < rightSide.length) {
        delete[] characters;
        characters = new char[rightSide.length];
        length = rightSide.length;
    }
    for (int i = 0; i < length; i++) {
        characters[i] = rightSide.characters[i];
    }
    return *this;
}

String::String(const String& strObject) : length(strObject.length) {
    characters = new char[length];
    for (int i = 0; i < length; i++) {
        characters[i] = strObject.characters[i];
    }
}

String& String::operator+(const String& secondString) {
    String temp(length);
    for (int i = 0; i < length; i++) {
        temp.characters[i] = characters[i];
    }
    delete[] characters;
    length = temp.length + secondString.length;
    characters = new char[length];
    for (int i = 0; i < temp.length; i++) {
        characters[i] = temp.characters[i];
    }
    for (int i = 0; i < secondString.length; i++) {
        addCharacterToEnd(secondString.characters[i], temp.length);
        temp.length++;
    }
    return *this;
}

char& String::operator[](int index) {
    if (index >= length) {
        cout << "Illegal access for your string!" << endl;
        exit(1);
    }
    return characters[index];
}

ostream& operator<<(ostream& outstream, const String& myString) {
    for (int i = 0; i < myString.length; i++) {
        outstream << myString.characters[i];
    }
    return outstream;
}

void String::addCharacterToEnd(char letter, int lastIndex) {
    characters[lastIndex] = letter;
}

String::~String() {
    delete[] characters;
}

