#include <iostream>
using namespace std;

class GtuVector {
public:
    GtuVector(); // Default constructor
    GtuVector(int limit); // Constructor with capacity limit
    GtuVector(const GtuVector& other); // Copy constructor
    ~GtuVector(); // Destructor
    GtuVector& operator=(const GtuVector& rhs); // Assignment operator

    GtuVector& operator+=(const GtuVector& rhs); // Add elements from another vector
    void addElement(int element); // Add a single element to the vector
    bool isFull() const; // Check if the vector is full
    int getSize() const; // Get the current size of the vector
    int getCapacity() const; // Get the current capacity of the vector
    void setSize(int newSize); // Set the size of the vector
    void setCapacity(int newCapacity); // Set the capacity of the vector
    static int getNumberOfVectors(); // Get the total number of vector instances
    int& operator[](int index); // Access element at a specific index
    GtuVector intersect(const GtuVector& other); // Find common elements between two vectors
    GtuVector concat(const GtuVector& other); // Merge two vectors into a new vector
    friend ostream& operator<<(ostream& output, const GtuVector& vector); // Output stream operator
    GtuVector operator++(); // Prefix increment operator
    GtuVector operator++(int); // Postfix increment operator

private:
    int* elements; // Dynamic array to hold vector elements
    int size; // Current number of elements in the vector
    int capacity; // Maximum capacity of the vector
    static int vectorCount; // Static counter for the number of vector instances
};

void testMyVector();
int GtuVector::vectorCount = 0;

int main() {
    testMyVector();
}

GtuVector::GtuVector() : GtuVector(50) { }

GtuVector::GtuVector(int limit) : capacity(limit), size(0) {
    elements = new int[capacity];
    vectorCount++;
}

GtuVector::GtuVector(const GtuVector& other) : capacity(other.capacity), size(other.size) {
    elements = new int[capacity];
    for (int i = 0; i < size; ++i) {
        elements[i] = other.elements[i];
    }
    vectorCount++;
}

GtuVector::~GtuVector() {
    delete[] elements;
    vectorCount--;
}

GtuVector& GtuVector::operator=(const GtuVector& rhs) {
    if (capacity <= rhs.size) {
        delete[] elements;
        elements = new int[rhs.capacity];
        capacity = rhs.capacity;
    }
    size = rhs.size;
    for (int i = 0; i < size; ++i) {
        elements[i] = rhs.elements[i];
    }
    return *this;
}

GtuVector& GtuVector::operator+=(const GtuVector& rhs) {
    int newSize = size + rhs.size;
    if (capacity <= newSize) {
        capacity = newSize * 2;
        GtuVector temp(capacity);
        for (int i = 0; i < size; ++i) {
            temp.elements[i] = elements[i];
        }
        delete[] elements;
        elements = new int[capacity];
        for (int i = 0; i < size; ++i) {
            elements[i] = temp.elements[i];
        }
    }
    for (int i = size; i < newSize; ++i) {
        elements[i] = rhs.elements[i - size];
    }
    size = newSize;
    return *this;
}

void GtuVector::addElement(int element) {
    if (size == capacity) {
        capacity = size * 2;
        GtuVector temp(capacity);
        for (int i = 0; i < size; ++i) {
            temp.elements[i] = elements[i];
        }
        delete[] elements;
        elements = new int[capacity];
        *this = temp;
    }
    elements[size] = element;
    size++;
}

inline bool GtuVector::isFull() const {
    return size == capacity;
}

inline int GtuVector::getSize() const {
    return size;
}

inline int GtuVector::getCapacity() const {
    return capacity;
}

inline void GtuVector::setSize(int newSize) {
    size = newSize;
}

inline void GtuVector::setCapacity(int newCapacity) {
    capacity = newCapacity;
}

int& GtuVector::operator[](int index) {
    if (index >= size || index < 0) {
        cout << "Invalid index value!";
        exit(1);
    }
    return elements[index];
}

GtuVector GtuVector::intersect(const GtuVector& other) {
    int newSize = (size < other.size) ? size : other.size;
    GtuVector intersectionVector(newSize * 2);
    int k = 0;

    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < other.size; j++) {
            if (elements[i] == other.elements[j]) {
                intersectionVector.elements[k++] = elements[i];
            }
        }
    }
    intersectionVector.setSize(k);
    return intersectionVector;
}

GtuVector GtuVector::concat(const GtuVector& other) {
    int newSize = size + other.size;
    GtuVector concatenatedVector(newSize * 2);
    int k = 0;

    for (int i = 0; i < size; ++i) {
        if (i >= other.size || elements[i] != other.elements[i]) {
            concatenatedVector.elements[k++] = elements[i];
        }
    }
    for (int i = size; i < other.size; ++i) {
        concatenatedVector.elements[k++] = other.elements[i];
    }
    concatenatedVector.setSize(k);
    return concatenatedVector;
}

ostream& operator<<(ostream& output, const GtuVector& vector) {
    output << "Your int vector is: ";
    for (int i = 0; i < vector.getSize(); ++i) {
        output << vector.elements[i];
        if (i < vector.getSize() - 1) {
            output << ", ";
        }
    }
    output << endl;
    return output;
}

GtuVector GtuVector::operator++(int) {
    GtuVector temp(capacity + 1);
    temp = *this;
    temp.capacity++;
    return temp;
}

GtuVector GtuVector::operator++() {
    GtuVector temp(capacity + 2);
    temp = *this;
    temp.capacity += 2;
    return temp;
}

void testMyVector() {
    GtuVector vector1(20), vector2, vector3; // Initialize vectors with specified capacities
    for (int i = 0; i < 10; ++i) {
        vector1.addElement(i);
    }
    for (int i = 7; i < 30; ++i) {
        vector2.addElement(i);
    }

    cout << "Initial values of vectors:" << endl;
    cout << vector1;
    cout << vector2;

    cout << "After adding values from vector2 to vector1:" << endl;
    vector1 += vector2;
    cout << vector1;

    cout << "After intersecting vector1 and vector2:" << endl;
    vector3 = vector1.intersect(vector2);
    cout << vector3;

    cout << "After concatenating vector1 and vector2:" << endl;
    cout << vector1.concat(vector2);

    cout << "Total number of vector instances: " << GtuVector::getNumberOfVectors() << endl;
}

