#ifndef CARD_H
#define CARD_H

#include <string>

class Card {
public:
    enum class Suit { None, Spade, Heart, Diamond, Club };
    enum class Rank { Unknown, Ace, Two, Three, Four, Five, Six, Seven, Eight, Nine, Ten, Jack, Queen, King };

    // Default constructor initializes card to None and Unknown
    Card() : my_suit(Suit::None), my_rank(Rank::Unknown) {}

    // Constructor with specified suit and rank
    Card(Suit suit, Rank rank) : my_suit(suit), my_rank(rank) {}

    Suit get_suit() const { return my_suit; }
    Rank get_rank() const { return my_rank; }

    // Returns the name of the rank as a string
    std::string get_rank_name() const { return rank_names[static_cast<int>(my_rank)]; }

    // Returns the name of the suit as a string
    std::string get_suit_name() const { return suit_names[static_cast<int>(my_suit)]; }

    // Returns the icon representation of the suit
    std::string get_suit_icon() const;

    // Calculates points based on the number of people
    int calculate_points(int people);

    // Prints the card details
    void display() const;

    // Sets the rank of the card
    void set_rank(Rank rank) { my_rank = rank; }

    // Assignment operator to copy card properties
    void operator=(const Card &card) {
        my_suit = card.get_suit();
        my_rank = card.get_rank();
    }

    // Static method to get the name of a rank
    static std::string get_rank_name(Rank rank) { return rank_names[static_cast<int>(rank)]; }

    // Comparison function to sort cards by suit
    static bool compare_by_suit(const Card &first_card, const Card &second_card) {
        return first_card.my_suit > second_card.my_suit;
    }

    // Comparison function to sort cards by rank
    static bool compare_by_rank(const Card &first_card, const Card &second_card) {
        return first_card.my_rank < second_card.my_rank;
    }

    // Determines if one card can capture another
    static bool can_capture(Card card1, Card card2);

private:
    Suit my_suit;
    Rank my_rank;
    static const std::string suit_names[];
    static const std::string rank_names[];
};

#endif // CARD_H

