class Deck {
public:
    Deck() {} // Khởi tạo một bộ bài rỗng.

    void add(const Card& card) { 
        cards.push_back(card); 
    }

    int size() const { 
        return cards.size(); 
    } // Trả về số lượng thẻ trong bộ bài.

    Card deal() { 
        Card card = cards.back(); 
        cards.pop_back(); 
        return card; 
    }

    Card deal(int index) { 
        Card card = cards.at(index); 
        cards.erase(cards.begin() + index); 
        return card; 
    }

    Card card(int index) const { 
        return cards.at(index); 
    } // Trả về thẻ tại vị trí chỉ định.

    Card top() { 
        return cards.back(); 
    }

    void fill_and_shuffle(); // Điền và xáo trộn bộ bài.
    void sort(); // Sắp xếp bộ bài.
    void print(); // In ra bộ bài.

    void operator=(const Deck &otherDeck) { 
        cards = otherDeck.cards; 
    }

    Card::Rank special_check(int n); // Kiểm tra đặc biệt cho thẻ.

private:
    std::vector<Card> cards; // Danh sách các thẻ trong bộ bài.
};

