class Reservation
{
private:
    std::string customerName;
    int arrivalDate;
    int accommodationDays;
    int numberOfPersons;
    unsigned int reservationId = 0;
    Room* assignedRoom = nullptr;

public:
    static unsigned int globalReservationId;

    Reservation()
    {
        reservationId = globalReservationId++;
    }

    Reservation(std::string name, int arrival, int days, int persons)
    {
        reservationId = globalReservationId++;
        customerName = name;
        arrivalDate = arrival;
        accommodationDays = days;
        numberOfPersons = persons;
    }

    void assignRoom(Room* room)
    {
        assignedRoom = room;
    }

    unsigned int getId() const
    {
        return reservationId;
    }

    int getArrival() const
    {
        return arrivalDate;
    }

    int getDays() const
    {
        return accommodationDays;
    }

    int getNumberOfPersons() const
    {
        return numberOfPersons;
    }

    friend std::ostream& operator<<(std::ostream& os, const Reservation& res);
};

unsigned int Reservation::globalReservationId = 0;

std::ostream& operator<<(std::ostream& os, const Reservation& res)
{
    os << "\nRes. ID : " << res.reservationId
       << " from : " << res.customerName
       << " for " << res.numberOfPersons
       << " persons, arriving on " << res.arrivalDate
       << " and staying for " << res.accommodationDays
       << " days.\nWhich means from " << res.arrivalDate
       << " to " << res.arrivalDate + res.accommodationDays << " of the month.\n\n";
    return os;
}

class Room
{
private:
    float costPerPerson = 10.0f;

protected:
    std::array<Reservation*, 30> availabilityTable = { nullptr };
    unsigned int roomCode;
    int maxRoomCapacity = 10;
    Reservation* currentReservation;

public:
    static unsigned int globalRoomCode;

    Room()
    {
        roomCode = globalRoomCode++;
    }

    virtual bool addNewReservation(Reservation* reservation)
    {
        currentReservation = reservation;
        std::cout << "\nNew reservation request for " << currentReservation->getNumberOfPersons() << " persons"
                  << "\nArrival on " << currentReservation->getArrival() << " of the month" << std::endl;

        if (currentReservation->getNumberOfPersons() > maxRoomCapacity)
            return false;

        for (int i = currentReservation->getArrival(); i < currentReservation->getArrival() + currentReservation->getDays(); i++)
        {
            if (availabilityTable[i] != nullptr) {
                std::cout << "Conflict! Already Reserved\n";
                return false;
            }
        }

        for (int i = currentReservation->getArrival(); i < currentReservation->getArrival() + currentReservation->getDays(); i++)
        {
            std::cout << "Reservation for day: " << i << " completed successfully" << std::endl;
            availabilityTable[i] = currentReservation;
        }
        std::cout << "Reservation completed with ID: " << currentReservation->getId() << std::endl;

        currentReservation->assignRoom(this);
        return true;
    }

    virtual float computeTotalCost() const
    {
        for (const auto& element : availabilityTable)
        {
            if (element != nullptr) {
                return static_cast<float>(element->getNumberOfPersons() * element->getDays() * costPerPerson);
            }
        }
        return 0.0f;
    }

    bool cancelReservation(int reservationId)
    {
        std::cout << "\nCanceling reservation ID: " << reservationId << std::endl;
        for (int i = 0; i < availabilityTable.size(); i++)
        {
            if (availabilityTable[i] != nullptr && availabilityTable[i]->getId() == reservationId)
            {
                std::cout << "Reservation with ID: " << availabilityTable[i]->getId() << " has been canceled\n";
                availabilityTable[i] = nullptr;
                return true;
            }
        }
        return false;
    }

    float getReservationPercentage() const
    {
        int count = 0;
        for (const auto& reservation : availabilityTable)
        {
            if (reservation != nullptr) {
                count++;
            }
        }
        return (static_cast<float>(count) / availabilityTable.size()) * 100;
    }

    unsigned int getRoomCode() const
    {
        return roomCode;
    }
};

unsigned int Room::globalRoomCode = 1;

class RoomTypeA : public Room
{
public:
    float computeTotalCost() const override
    {
        return costPerDay * currentReservation->getDays();
    }

protected:
    float costPerDay = 50.0f;
};

class RoomTypeB : public RoomTypeA
{
public:
    float computeTotalCost() const override
    {
        float totalCost = 0.0f;

        for (int i = 0; i < currentReservation->getDays(); i++) {
            float dailyCost = costPerDay - i * discountPerDay;
            totalCost += (dailyCost > costPerDay / 2) ? dailyCost : costPerDay / 2;
        }
        return totalCost;
    }

    bool cancelReservation(int reservationId) override
    {
        return false;
    }

private:
    float discountPerDay = 10.0f;
};

