class Hotel
{
public:
    std::string hotelName;
    std::vector<Room> rooms;
    std::vector<Reservation> reservations;

    void addNewRoom(const Room& newRoom)
    {
        rooms.push_back(newRoom);
    }

    Room* retrieveRoomById(unsigned int roomId)
    {
        for (auto& room : rooms) {
            if (room.getRoomCode() == roomId)
                return &room;
        }
        return nullptr;
    }

    Reservation* retrieveReservationById(unsigned int reservationId)
    {
        for (auto& reservation : reservations) {
            if (reservation.getId() == reservationId)
                return &reservation;
        }
        return nullptr;
    }

    bool addReservationToRoom(const Reservation& reservation, unsigned int roomId)
    {
        Room* room = retrieveRoomById(roomId);
        if (room != nullptr && room->addNewReservation(const_cast<Reservation*>(&reservation))) {
            reservations.push_back(reservation);
            return true;
        }
        return false;
    }

    unsigned int addReservationToAnyRoom(const Reservation& reservation)
    {
        for (auto& room : rooms) {
            if (room.addNewReservation(const_cast<Reservation*>(&reservation))) {
                reservations.push_back(reservation);
                std::cout << "Reservation with ID: " << reservation.getId()
                          << " completed successfully, at room " << room.getRoomCode() << std::endl;
                return room.getRoomCode();
            }
        }
        std::cout << "Reservation Failed" << std::endl;
        return 0;
    }

    void cancelReservation(unsigned int reservationId)
    {
        Reservation* reservation = retrieveReservationById(reservationId);
        if (reservation != nullptr) {
            reservations.erase(std::remove_if(reservations.begin(), reservations.end(),
                [reservationId](const Reservation& res) { return res.getId() == reservationId; }), reservations.end());

            for (auto& room : rooms) {
                room.cancelReservation(reservationId);
            }
        }
    }
};

