// Class representing a dynamic vector that can grow in size as needed.
template <class ElementType>
class DynamicVector {
private:
	ElementType* elements; // Pointer to the array of elements
	int currentSize;       // Current number of elements in the vector
	int currentCapacity;   // Current capacity of the vector

	// Resizes the dynamic vector to accommodate more elements
	void resizeVector(double growthFactor = 2.0);

public:
	DynamicVector(int initialCapacity = 10);
	DynamicVector(const DynamicVector& sourceVector);
	~DynamicVector();

	DynamicVector& operator=(const DynamicVector& sourceVector);
	void addElement(const ElementType& elementToAdd);
	int getSize() const;
	ElementType* getAllElements() const;
	void removeElement(int index);
	void updateElement(int index, const ElementType& newElement);
};

template <class ElementType>
DynamicVector<ElementType>::DynamicVector(int initialCapacity)
	: currentSize(0), currentCapacity(initialCapacity) {
	elements = new ElementType[currentCapacity];
}

template <class ElementType>
DynamicVector<ElementType>::DynamicVector(const DynamicVector& sourceVector)
	: currentSize(sourceVector.currentSize), currentCapacity(sourceVector.currentCapacity) {
	elements = new ElementType[currentCapacity];
	for (int i = 0; i < currentSize; i++) {
		elements[i] = sourceVector.elements[i];
	}
}

template <class ElementType>
DynamicVector<ElementType>::~DynamicVector() {
	delete[] elements;
}

template <class ElementType>
int DynamicVector<ElementType>::getSize() const {
	return currentSize;
}

template <class ElementType>
DynamicVector<ElementType>& DynamicVector<ElementType>::operator=(const DynamicVector& sourceVector) {
	if (this != &sourceVector) {
		currentSize = sourceVector.currentSize;
		currentCapacity = sourceVector.currentCapacity;

		delete[] elements;
		elements = new ElementType[currentCapacity];
		for (int i = 0; i < currentSize; i++) {
			elements[i] = sourceVector.elements[i];
		}
	}
	return *this;
}

template <class ElementType>
void DynamicVector<ElementType>::addElement(const ElementType& elementToAdd) {
	if (currentSize == currentCapacity) {
		resizeVector();
	}
	elements[currentSize++] = elementToAdd;
}

template <class ElementType>
void DynamicVector<ElementType>::removeElement(int index) {
	currentSize--;
	for (int i = index; i < currentSize; i++) {
		elements[i] = elements[i + 1];
	}
}

template <class ElementType>
void DynamicVector<ElementType>::updateElement(int index, const ElementType& newElement) {
	elements[index] = newElement;
}

template <class ElementType>
void DynamicVector<ElementType>::resizeVector(double growthFactor) {
	currentCapacity *= static_cast<int>(growthFactor);
	ElementType* newElements = new ElementType[currentCapacity];
	for (int i = 0; i < currentSize; i++) {
		newElements[i] = elements[i];
	}
	delete[] elements;
	elements = newElements;
}

template <class ElementType>
ElementType* DynamicVector<ElementType>::getAllElements() const {
	return elements;
}

