// Base class for asset management
class BaseAsset {
protected:
    char serialNumber[50];
    int day, month, year;

public:
    void inputBasicData();
    void displayBasicData();
};

// Base class method definitions
void BaseAsset::inputBasicData() {
    clear();
    printw("\tADDITION");
    printw("\n ENTER SERIAL NO : ");
    scanw(serialNumber);
    printw("\nENTER THE EXPIRY DATE (format: dd mm yyyy): ");
    scanw("%d%d%d", &day, &month, &year);
}

void BaseAsset::displayBasicData() {
    printw("\n Serial No : %s", serialNumber);
    printw("\t Warranty Date : %d/%d/%d", day, month, year);
}

// Inherited class for specific asset details
class Asset : public BaseAsset {
    int ram;
    int hardDisk;
    char processor[30];

public:
    char operatingSystem[30];
    char status[50];
    int code;

    // Basic functions
    void inputData();
    void displayData();
    void editData();
    int getCode();

    // Report functions
    void displayExpiredWarranty();
    void displayNearingWarranty();
} assetInstance;

// Inherited class method definitions
void Asset::inputData() {
    clear();
    inputBasicData();
    printw(" \n ENTER COMPUTER CODE : ");
    cin >> code;
    printw(" \n ENTER RAM   : ");
    cin >> ram;
    printw("\n Enter hard disk  : ");
    cin >> hardDisk;
    printw(" \n ENTER THE OPERATING SYSTEM : ");
    gets(operatingSystem);
    printw(" \n ENTER PROCESSOR  : ");
    gets(processor);
    printw(" \n ENTER STATUS  : ");
    gets(status);
}

void Asset::displayData() {
    displayBasicData();
    cout << "\n\nCODE" << "\tRAM" << "\tHARD DISK" << "\tOPERATING SYSTEM" << "\tPROCESSOR";
    cout << "\n\n" << code;
    cout << "\t" << ram;
    cout << "\t" << hardDisk;
    cout << "\t\t" << operatingSystem;
    cout << "\t\t" << processor;
    cout << "\nstatus:\t";
    puts(status);
    cout << "\t--------------------------------------------------------" << endl;
}

void Asset::editData() {
    char choice;
    if (confirmModification("computer code") == 'y') {
        cout << "\n ENTER NEW COMPUTER CODE  :";
        cin >> code;
    }
    if (confirmModification("ram") == 'y') {
        cout << "\nEnter new ram";
        cin >> ram;
    }
    if (confirmModification("hard disk") == 'y') {
        cout << "\nEnter new hard disk";
        cin >> hardDisk;
    }
    if (confirmModification("processor") == 'y') {
        cout << "\n ENTER NEW PROCESSOR : ";
        gets(processor);
    }
    if (confirmModification("operating system") == 'y') {
        cout << "\n ENTER NEW OPERATING SYSTEM :";
        gets(operatingSystem);
    }
    if (confirmModification("STATUS") == 'y') {
