void displayAllAssets() {
    ifstream fileInput;
    int recordCount, index;
    fileInput.open("c:\\ams.dat");
    clear();
    recordCount = getRecordCount();
    for (index = 0; index < recordCount; index++) {
        fileInput.read((char*)&assetInstance, sizeof(assetInstance));
        assetInstance.displayData();
        getch();
    }
    fileInput.close();
}

int getRecordCount() {
    ifstream fileInput;
    fileInput.open("c:\\ams.dat");
    fileInput.seekg(0, ios::end);
    int recordCount = fileInput.tellg() / sizeof(assetInstance);
    cout << " \n NUMBER OF RECORDS = " << recordCount << endl;
    return recordCount;
}

void searchAsset() {
    ifstream fileInput;
    fileInput.open("c:\\ams.dat");
    if (fileInput.fail()) {
        cout << " \n FILE NOT FOUND ";
        getch();
    }
    clear();
    cout << "\t\t\t [SEARCHING] ";
    cout << " \n ENTER THE COMPUTER CODE TO BE SEARCHED : ";
    int searchCode;
    cin >> searchCode;
    int recordCount = getRecordCount();
    for (int index = 0; index < recordCount; index++) {
        fileInput.read((char*)&assetInstance, sizeof(assetInstance));
        if (searchCode == assetInstance.code) {
            assetInstance.displayData();
        }
    }
    getch();
    if (fileInput.eof())
        cout << " \n RECORD NOT FOUND ";
}

void addAsset() {
    ofstream fileOutput;
    fileOutput.open("c:\\ams.dat", ios::out | ios::app);
    assetInstance.inputData();
    fileOutput.write((char*)&assetInstance, sizeof(assetInstance));
    fileOutput.close();
}

char confirmModification(char *fieldName) {
    cout << "\n MODIFY \t " << fieldName << "\t" << "Y/N";
    char choice;
    choice = getch();
    return (choice == 'y' || choice == 'Y') ? 'y' : 'n';
}

void modifyAsset(char option) {
    clear();
    int searchCode, recordCount, index;
    fstream fileInput;
    ofstream fileOutput;
    cout << "\tMODIFICATION\n";
    recordCount = getRecordCount();
    if (recordCount == 0) {
        cout << "\n FILE IS EMPTY ! ";
        getch();
    }
    fileInput.open("c:\\ams.dat", ios::in);
    fileOutput.open("c:\\temp.dat", ios::out); // Saving all records to a temporary file
    while (fileInput.good()) {
        fileInput.read((char*)&assetInstance, sizeof(assetInstance));
        fileOutput.write((char*)&assetInstance, sizeof(assetInstance));
    }
    fileInput.close();
    fileOutput.close();
    fileOutput.open("c:\\ams.dat", ios::trunc);
    fileInput.open("c:\\temp.dat", ios::in);
    char choice;
    cout << "\n ENTER COMPUTER CODE :";
    cin >> searchCode;
    choice = cin.get();
    for (index = 0; index < recordCount; index++) {
        fileInput.read((char*)&assetInstance, sizeof(assetInstance));
        if (searchCode == assetInstance.code) {
            assetInstance.displayData();
            if (option == 'D') { // If Delete option selected
                cout << "Are you sure to delete this record (Y/N)? ";
                choice = getch();
                if ((choice != 'y') && (choice != 'Y')) // Does not write record if choice is 'YES'
                    fileOutput.write((char*)&assetInstance, sizeof(assetInstance));
            }
            if (option == 'E') { // If Edit option selected
                assetInstance.editData();
                fileOutput.write((char*)&assetInstance, sizeof(assetInstance));
            }
        } else {
            fileOutput.write((char*)&assetInstance, sizeof(assetInstance));
        }
    }
    fileOutput.close();
    fileInput.close();
}

void sortByOperatingSystem(char *os) {
    int comparisonResult, recordCount;
    recordCount = getRecordCount();
    ifstream fileInput;
    fileInput.open("c:\\ams.dat");
    for (int index = 0; index < recordCount; index++) {
        fileInput.read((char*)&assetInstance, sizeof(assetInstance));
        comparisonResult = strcmp(os, assetInstance.operatingSystem);
        if (comparisonResult == 0) {
            assetInstance.displayData();
            cout << "\n\n";
        }
    }
    fileInput.close();
    getch();
}

void checkAssetStatus(char *status) {
    int comparisonResult, recordCount;
    recordCount = getRecordCount();
    ifstream fileInput;
    fileInput.open("c:\\ams.dat");
    for (int index = 0; index < recordCount; index++) {
        fileInput.read((char*)&assetInstance, sizeof(assetInstance));
        comparisonResult = strcmp(status, assetInstance.status);
        if (comparisonResult == 0) {
            assetInstance.displayData();
            cout << "\n\n";
        }
    }
    fileInput.close();
    getch();
}

void Asset::displayExpiredWarranty() {
    time_t currentTime = time(NULL);
    struct tm currentDate = *localtime(&currentTime);
    int currentDay = currentDate.tm_mday;
    int currentMonth = currentDate.tm_mon;
    int currentYear = currentDate.tm_year;
    ifstream fileInput;
    fileInput.open("c:\\ams.dat");
    int recordCount = getRecordCount();
    if (recordCount == 0) {
        cout << "\n FILE IS EMPTY ! ";
        getch();
    }
    for (int index = 0; index < recordCount; index++) {
        fileInput.read((char*)&assetInstance, sizeof(assetInstance));
        if (year < currentYear)
            assetInstance.displayData();
        else if (year == currentYear) {
            if (month < currentMonth)
                assetInstance.displayData();
            else if (month == currentMonth) {
                if (day < currentDay)
                    assetInstance.displayData();
            }
        }
    }
    fileInput.close();
}

void Asset::displayNearingWarranty() {
    time_t currentTime = time(NULL);
    struct tm currentDate = *localtime(&currentTime);
    int currentDay = currentDate.tm_mday;
    int currentMonth = currentDate.tm_mon;
    int currentYear = currentDate.tm_year;
    ifstream fileInput;
    fileInput.open("c:\\ams.dat");
    int recordCount = getRecordCount();
    if (recordCount == 0) {
        cout << "\n FILE IS EMPTY ! ";
        getch();
    }
    for (int index = 0; index < recordCount; index++) {
        fileInput.read((char*)&assetInstance, sizeof(assetInstance));
        if (year > currentYear)
            assetInstance.displayData();
        else if (year == currentYear) {
            if (month > currentMonth)
                assetInstance.displayData();
            else if (month == currentMonth) {
                if (day >= currentDay)
                    assetInstance.displayData();
            }
        }
    }
    fileInput.close();
}

void showSubMenu() {
    char choice;
    cout << "\t\t\t\t REPORTS MENU";
    cout << "\n\n\t\t\t1.   Sort according to operating system";
    cout << "\n\n\t\t\t2.   Status";
    cout << "\n\n\t\t\t3.   List of warranty expired computers";
    cout << "\n\n\t\t\t4.   List of computers nearing expiry";
    cout << "\n\n\t\t\t5.   Back to the main menu";
    choice = getch();
    switch (choice) {
        case '1':
            clear();
            cout << "\t\t Operating system menu";
            cout << " \n\n\t1. Windows XP Professional ";
            cout << "\n\t2. Windows 98";
            cout << "\n\t3. Windows 2000";
            cout << "\n\t4. Return to report menu";
            char osChoice;
            osChoice = getch();
            switch (osChoice) {
                case '1':
                    clear();
                    sortByOperatingSystem("windows xp");
                    break;
                case '2':
                    clear();
                    sortByOperatingSystem("windows 98");
                    break;
                case '3':
                    clear();
                    sortByOperatingSystem("windows 2000");
                    break;
                case '4':
                    clear();
                    showSubMenu();
                    break;
            }
            break;

        case '2':
            clear();
            cout << "\n\n\t\t STATUS MENU";
            char statusChoice;
            cout << "\n\n\t\t1. List of working computers";
            cout << "\n\n\t\t2. List of non-working computers";
            cout << "\n\n\t\t3. Back to report menu";
            statusChoice = getch();
            switch (statusChoice) {
                case '1':
                    clear();
                    checkAssetStatus("working");
                    break;
                case '2':
                    clear();
                    checkAssetStatus("not working");
                    break;
                case '3':
                    clear();
                    showSubMenu();
                    break;
            }
            break;

        case '3':
            clear();
            cout << "\n\n\t\tWARRANTY EXPIRED COMPUTERS";
            assetInstance.displayExpiredWarranty();
            getch();
            break;

        case '4':
            clear();
            cout << "\n\n\t\t COMPUTERS NEARING EXPIRY";
            assetInstance.displayNearingWarranty();
            getch();
            break;

        case '5':
            clear();
            showMainMenu();
            break;
    }
}

void showMainMenu() {
    char choice;
    do {
        clear();
        printw("\n\n\t\t***MENU****");
        printw("\n\n\t\t 1:  ADD NEW ASSET");
        printw("\n\n\t\t 2:  DELETE AN ASSET");
        printw("\n\n\t\t 3:  EDIT AN ASSET");
        printw("\n\n\t\t 4:  VIEW ALL ASSETS");
        printw("\n\n\t\t 5:  REPORTS");
        printw("\n\n\t\t 6:  SEARCH");
        printw("\n\n\t\t 7:  EXIT");
        choice = getch();
        switch (choice) {
            case '1':
                addAsset();
                break;
            case '2':
                modifyAsset('D');
                break;
            case '3':
                modifyAsset('E');
                break;
            case '4':
                displayAllAssets();
                break;
            case '5':
                clear();
                showSubMenu();
                break;
            case '6':
                searchAsset();
                break;
        }
    } while (choice != '7');
}

