#include <iostream>

using namespace std;

// Base class representing a parent entity
class Parent {
protected:
    int height;

public:
    Parent() {
        cout << "Constructor of class Parent is called, which is the base class" << endl;
    }
};

// Derived class representing a child entity
class Child : public Parent {
public:
    // Constructor that initializes height and calls the base class constructor
    Child(int heightValue) : Parent() {
        height = heightValue;
        cout << "Constructor of class Child is called, which is derived from Parent" << endl;
    }

    // Displays the height of the child
    void display() {
        cout << "Height is " << height << endl;
    }
};

int main() {
    Child amartyapandey(20); // Create an instance of Child with height 20
    amartyapandey.display();  // Display the height
    return 0;
}

