    // Constructor initializes height and indicates construction of the base class
    Parent(int h) {
        cout << "Constructor of Parent class is called." << endl;
        height = h;
    }
};

// Derived class representing a child that inherits from Parent
class Child : public Parent {
public:
    // Constructor initializes height via the Parent constructor
    Child(int x) : Parent(x) {
        cout << "Child class constructor is called." << endl;
    }

    // Displays the height of the child
    void display() {
        cout << "Height is " << height << endl;
    }
};

