class Derived2 : public Base {
public:
    void display() override {
        cout << "Called from derived class 2." << endl;
    }
};

int main() {
    Base *basePointer;

    // Khởi tạo đối tượng Base và gọi phương thức hiển thị
    basePointer = new Base();
    basePointer->display();

    // Khởi tạo đối tượng Derived1 và gọi phương thức hiển thị
    basePointer = new Derived1();
    basePointer->display();

    // Khởi tạo đối tượng Derived2 và gọi phương thức hiển thị
    basePointer = new Derived2();
