#include <iostream>
using namespace std;

const int ARRAY_SIZE = 5;

template <typename T>
class Array {
    T elements[ARRAY_SIZE];

public:
    // Accepts user input to populate the array
    void input() {
        for (int index = 0; index < ARRAY_SIZE; index++) {
            cout << "Element " << index + 1 << ": ";
            cin >> elements[index];
        }
    }

    // Sorts the array in ascending order using a simple comparison-based algorithm
    void sort() {
        T temp;
        for (int i = 0; i < ARRAY_SIZE; i++) {
            for (int j = 0; j < ARRAY_SIZE; j++) {
                if (elements[i] < elements[j]) {
                    temp = elements[i];
                    elements[i] = elements[j];
                    elements[j] = temp;
                }
            }
        }
    }

    // Returns the minimum value in the array
    T minimum() {
        return elements[0];
    }

    // Returns the maximum value in the array
    T maximum() {
        return elements[ARRAY_SIZE - 1];
    }
};

int main() {
    Array<int> intArray;
    cout << "Enter the elements of the integer array:" << endl;
    intArray.input();
    intArray.sort();
    cout << "Min = " << intArray.minimum() << endl;
    cout << "Max = " << intArray.maximum() << endl;

    Array<float> floatArray;
    cout << "Enter the elements of the float array:" << endl;
    floatArray.input();
    floatArray.sort();
    cout << "Min = " << floatArray.minimum() << endl;
    cout << "Max = " << floatArray.maximum() << endl;

    return 0;
}

#include <iostream>
using namespace std;

const int VECTOR_SIZE = 3;

template<class T>
class Vector
{
    T* elements;

public:
    // Default constructor initializes vector elements to zero
    Vector()
    {
        elements = new T[VECTOR_SIZE];
        for (int i = 0; i < VECTOR_SIZE; i++)
        {
            elements[i] = 0;
        }
    }

    // Constructor that initializes vector with provided array
    Vector(T* array)
    {
        elements = new T[VECTOR_SIZE];
        for (int i = 0; i < VECTOR_SIZE; i++)
        {
            elements[i] = array[i];
        }
    }

    // Overloaded operator to calculate the scalar product of two vectors
    T operator*(Vector &other)
    {
        T scalarProduct = 0;
        for (int i = 0; i < VECTOR_SIZE; i++)
        {
            scalarProduct += elements[i] * other.elements[i];
        }
        return scalarProduct;
    }
};

int main()
{
    int intArray1[VECTOR_SIZE] = {1, 2, 3};
    int intArray2[VECTOR_SIZE] = {2, 3, 4};

    Vector<int> vector1(intArray1);
    Vector<int> vector2(intArray2);

    int intProduct = vector1 * vector2;
    cout << "Product = " << intProduct << endl;

    double doubleArray1[VECTOR_SIZE] = {1.8, 2.6, 3.4};
    double doubleArray2[VECTOR_SIZE] = {2.8, 3.2, 4.7};

    Vector<double> vector3(doubleArray1);
    Vector<double> vector4(doubleArray2);

    double doubleProduct = vector3 * vector4;
    cout << "Product = " << doubleProduct << endl;

    return 0;
}

#include <iostream>
using namespace std;

class Clock {
    int hour, minute, second;

public:
    // Reads time input from the user and validates the values.
    void input() {
        cout << "Hour: ";
        cin >> hour;
        if (hour > 24 || hour < 0) {
            throw Exception('H');
        }

        cout << "Min: ";
        cin >> minute;
        if (minute > 60 || minute < 0) {
            throw Exception('M');
        }

        cout << "Sec: ";
        cin >> second;
        if (second > 60 || second < 0) {
            throw Exception('S');
        }
    }

    // Displays the current time in a formatted manner.
    void display() {
        cout << "Time: " << hour << " : " << minute << " : " << second;
    }

    class Exception {
    public:
        char errorCode;
        Exception(char code) : errorCode(code) {}
    };
};

int main() {
    Clock clockInstance;
    try {
        clockInstance.input();
        clockInstance.display();
    } catch (Clock::Exception error) {
        switch (error.errorCode) {
            case 'H':
                cout << "Hour can't be greater than 24." << endl;
                break;
            case 'M':
                cout << "Minute can't be greater than 60." << endl;
                break;
            case 'S':
                cout << "Second can't be greater than 60." << endl;
                break;
        }
    }
    return 0;
}

