using namespace std;

template <class T>
class Repository
{
private:
    vector<T> elements;

public:
    void addElement(T element);
    void removeElement(T element);
    void updateElement(T element);
    int getSize() const;
    vector<T> getAllElements() const;
};

// Adds a new element to the repository if it does not already exist
template<class T>
void Repository<T>::addElement(T element)
{
    auto iterator = find_if(elements.begin(), elements.end(), [&](const T& current) { return current == element; });
    if (iterator != elements.end())
        throw RepoException{ "Element already exists!\n" };
    elements.push_back(element);
}

// Removes an element from the repository if it exists
template<class T>
void Repository<T>::removeElement(T element)
{
    auto iterator = std::find_if(elements.begin(), elements.end(), [&](const T& current) { return current == element; });
    if (iterator == elements.end())
        throw RepoException{ "Element does not exist!\n" };
    elements.erase(iterator);
}

// Updates an existing element in the repository
template<class T>
void Repository<T>::updateElement(T element)
{
    auto iterator = find_if(elements.begin(), elements.end(), [&](const T& current) { return current == element; });
    if (iterator == elements.end())
        throw RepoException{ "Element does not exist!\n" };
    elements[iterator - elements.begin()] = element;
}

// Returns the number of elements in the repository
template<class T>
int Repository<T>::getSize() const
{
    return elements.size();
}

// Retrieves all elements from the repository
template<class T>
vector<T> Repository<T>::getAllElements() const {
    return elements;
}

