#include <bits/stdc++.h>
#define SPACE 10
using namespace std;

class TreeNode
{
public:    
    int value; 
    TreeNode *left;
    TreeNode *right;

    TreeNode() : value(0), left(nullptr), right(nullptr) {}

    TreeNode(int v) : value(v), left(nullptr), right(nullptr) {}
};

class BinarySearchTree
{
public:
    TreeNode *root;

    BinarySearchTree() : root(nullptr) {}

    bool isEmpty() const
    {
        return root == nullptr;
    }

    void insertNode(TreeNode *newNode)
    {
        if (root == nullptr)
        {
            root = newNode;
            cout << "Value added at root" << endl;
        }
        else
        {
            TreeNode *current = root;

            while (current != nullptr)
            {
                if (newNode->value == current->value)
                {
                    cout << "Duplicates are not allowed, insert another value" << endl;
                    return;
                }

                if (newNode->value < current->value)
                {
                    if (current->left == nullptr)
                    {
                        current->left = newNode;
                        cout << "Value inserted to left" << endl;
                        break;
                    }
                    current = current->left;
                }
                else
                {
                    if (current->right == nullptr)
                    {
                        current->right = newNode;
                        cout << "Value inserted to right" << endl;
                        break;
                    }
                    current = current->right;
                }
            }
        }
    }

    void print2D(TreeNode *node, int space) const
    {
        if (node == nullptr)
        {
            return;
        }
        space += SPACE;
        print2D(node->right, space);
        cout << endl;
        for (int i = SPACE; i < space; i++)
        {
            cout << " ";
        }
        cout << node->value << "\n";
        print2D(node->left, space);
    }

    void printPreorder(TreeNode* node) const
    {
        if (node == nullptr)
        {
            return;
        }
        cout << node->value << " ";
        printPreorder(node->left);
        printPreorder(node->right);
    } 

    void printInorder(TreeNode* node) const
    {
        if (node == nullptr)
        {
            return;
        }
        printInorder(node->left);
        cout << node->value << " ";
        printInorder(node->right);
    }

    void printPostorder(TreeNode* node) const
    {
        if (node == nullptr)
        {
            return;
        }
        printPostorder(node->left);
        printPostorder(node->right);
        cout << node->value << " ";
    }

    TreeNode* iterativeSearch(int value) const
    {
        TreeNode* current = root;
        while (current != nullptr)
        {
            if (value == current->value)
            {
                return current;
            }
            current = (value < current->value) ? current->left : current->right;
        }
        return nullptr; 
    }

    int height(TreeNode* node) const
    {
        if (node == nullptr)
        {
            return -1;
        }
        return max(height(node->left), height(node->right)) + 1;
    }

    void printLevel(TreeNode* node, int level) const
    {
        if (node == nullptr)
        {
            return;
        }
        if (level == 0)
        {
            cout << node->value << " "; 
        }
        else
        {
            printLevel(node->left, level - 1);
            printLevel(node->right, level - 1);
        }
    }

    void printBFS(TreeNode* node) const
    {
        int treeHeight = height(node);
        for (int i = 0; i <= treeHeight; i++)
        {
            printLevel(node, i);
        }
    }

    TreeNode* minValueNode(TreeNode* node) const
    {
        TreeNode* current = node;
        while (current && current->left != nullptr)
        {
            current = current->left;
        }
        return current;
    }

    TreeNode* deleteNode(TreeNode* node, int value)
    {
        if (node == nullptr)
        {
            return nullptr;
        }

        if (value < node->value)
        {
            node->left = deleteNode(node->left, value);
        }
        else if (value > node->value)
        {
            node->right = deleteNode(node->right, value);
        }
        else
        {
            if (node->left == nullptr)
            {
                TreeNode* temp = node->right;
                delete node;
                return temp;
            }
            else if (node->right == nullptr)
            {
                TreeNode* temp = node->left;
                delete node;
                return temp;
            }
            TreeNode* temp = minValueNode(node->right);
            node->value = temp->value;
            node->right = deleteNode(node->right, temp->value);
        }
        return node;
    }
};

int main()
{
    BinarySearchTree bst;
    int option, value;

    do
    {
        cout << "Select an operation (0 to exit):" << endl;
        cout << "1. Insert a node" << endl;
        cout << "2. Search a node" << endl;
        cout << "3. Delete a node" << endl;
