        cout << "5. Height of the tree" << endl;
        cout << "6. Clear Screen" << endl;
        cout << "0. Exit" << endl;

        cin >> option;

        TreeNode *newNode = new TreeNode();

        switch (option)
        {
        case 0:
            break;
        case 1:
            cout << "Insert" << endl;
            cout << "Enter the value for BST: " << endl;
            cin >> value;
            newNode->value = value;
            bst.insertNode(newNode);
            cout << endl;
            break;
        case 2:
            cout << "Search" << endl;
            cout << "Enter the number to search: " << endl;
            cin >> value;
            newNode = bst.iterativeSearch(value);
            cout << (newNode != nullptr ? "Value found" : "Value not found") << endl;
            break;
        case 3:
            cout << "Delete" << endl;
            cout << "Enter the value to be deleted: " << endl;
            cin >> value;
            newNode = bst.iterativeSearch(value);
            if (newNode != nullptr)
            {
                bst.deleteNode(bst.root, value);
                cout << "Value deleted" << endl;
            }
            else
            {
                cout << "Value not found" << endl;
            }
            break;
        case 4:
            cout << "Print" << endl;
            bst.print2D(bst.root, 5);
            cout << "\nPrinting BFS:" << endl;
            bst.printBFS(bst.root);
            cout << "\nPrinting by preorder:" << endl;
