// Searches for a value in the inorder array and returns its index
int findIndexInInorder(int inorder[], int startIndex, int endIndex, int targetValue)
{
    for (int i = startIndex; i <= endIndex; i++)
    {
        if (inorder[i] == targetValue)
        {
            return i;
        }
    }
    return -1;
}

// Constructs the binary tree from postorder and inorder traversals
TreeNode* constructTree(int postorder[], int inorder[], int startIndex, int endIndex)
{
    // Base case: no elements to construct the tree
    if (startIndex > endIndex)
    {
        return nullptr;
    }

    // Start from the end of postorder array to get the root
    static int currentIndex = 4;
    int rootValue = postorder[currentIndex];
    currentIndex--;

    // Create the current node
    TreeNode *currentNode = new TreeNode(rootValue);

    if (startIndex == endIndex)
    {
        // Leaf node case: no children
        return currentNode;
    }

    // Find the position of the root in the inorder array
    int rootPosition = findIndexInInorder(inorder, startIndex, endIndex, rootValue);

    // Recursively build the right and left subtrees
    currentNode->rightChild = constructTree(postorder, inorder, rootPosition + 1, endIndex);
    currentNode->leftChild = constructTree(postorder, inorder, startIndex, rootPosition - 1);

    return currentNode;
}

// Performs inorder traversal of the binary tree and prints the values
void printInorderTraversal(TreeNode* root)
{
    if (root == nullptr)
    {
        return;
    }
    printInorderTraversal(root->leftChild);
    cout << root->value << " ";
    printInorderTraversal(root->rightChild);
}

int main()
{
    int postorder[] = {4, 2, 5, 3, 1};
    int inorder[] = {4, 2, 1, 5, 3};

    // Construct the binary tree from the given traversals
    TreeNode* rootNode = constructTree(postorder, inorder, 0, 4);
    printInorderTraversal(rootNode);
    cout << endl;

    return 0;
}

