// Searches for the index of a given value in the inorder array
int findIndexInInorder(int inorder[], int start, int end, int target) {
    for (int i = start; i <= end; i++) {
        if (inorder[i] == target) {
            return i;
        }
    }
    return -1; // Target not found
}

// Constructs the binary tree from preorder and inorder traversals
TreeNode* constructTree(int preorder[], int inorder[], int start, int end) {
    static int preorderIndex = 0; // Tracks the current index in the preorder array
    if (start > end) {
        return nullptr; // Base case: no elements to construct the tree
    }

    int currentValue = preorder[preorderIndex++];
    TreeNode *currentNode = new TreeNode(currentValue);

    if (start == end) {
        return currentNode; // Leaf node case
    }

    int inorderIndex = findIndexInInorder(inorder, start, end, currentValue);

    // Recursively construct the left and right subtrees
    currentNode->leftChild = constructTree(preorder, inorder, start, inorderIndex - 1);
    currentNode->rightChild = constructTree(preorder, inorder, inorderIndex + 1, end);

    return currentNode;
}

