// Calculates the sum of node values at a specific level in the binary tree
int sumAtLevel(TreeNode* root, int targetLevel)
{
    if (root == nullptr) {
        return -1;
    }

    queue<TreeNode*> nodeQueue;
    nodeQueue.push(root);
    nodeQueue.push(nullptr);
    int levelSum = 0;
    int currentLevel = 0;

    while (!nodeQueue.empty())
    {
        TreeNode* currentNode = nodeQueue.front();
        nodeQueue.pop();

        if (currentNode != nullptr) {
            if (currentLevel == targetLevel) {
                levelSum += currentNode->value;
            }
            // Enqueue left child if it exists
            if (currentNode->leftChild) {
                nodeQueue.push(currentNode->leftChild);
            }
            // Enqueue right child if it exists
            if (currentNode->rightChild) {
                nodeQueue.push(currentNode->rightChild);
            }
        }
        // Move to the next level
        else if (!nodeQueue.empty())
        {
            nodeQueue.push(nullptr);
            currentLevel++;
        }
    }
    return levelSum;
}

