#include <iostream>
using namespace std;

// Định nghĩa cấu trúc nút cho danh sách liên kết vòng
class Node {
public:
    int value;
    Node* nextNode;

    Node(int val) {
        value = val;
        nextNode = nullptr;
    }
};

// Chèn nút mới vào đầu danh sách
void insertAtHead(Node*& head, int val) {
    Node* newNode = new Node(val);
    if (head == nullptr) {
        newNode->nextNode = newNode;
        head = newNode;
        return;
    }

    Node* lastNode = head;
    while (lastNode->nextNode != head) {
        lastNode = lastNode->nextNode;
    }

    lastNode->nextNode = newNode;
    newNode->nextNode = head;
    head = newNode;
}

// Chèn nút mới vào cuối danh sách
void insertAtTail(Node*& head, int val) {
    Node* newNode = new Node(val);
    if (head == nullptr) {
        insertAtHead(head, val);
        return;
    }

    Node* lastNode = head;
    while (lastNode->nextNode != head) {
        lastNode = lastNode->nextNode;
    }
    lastNode->nextNode = newNode;
    newNode->nextNode = head;
}

// Xóa nút đầu tiên trong danh sách
void deleteAtHead(Node*& head) {
    if (head == nullptr) {
        cout << "Danh sách rỗng" << endl;
        return;
    }

    Node* lastNode = head;
    while (lastNode->nextNode != head) {
        lastNode = lastNode->nextNode;
    }

    Node* nodeToDelete = head;
    lastNode->nextNode = head->nextNode;
    head = head->nextNode;

    delete nodeToDelete;
}

// Xóa nút tại vị trí chỉ định
void deleteAtPosition(Node*& head, int position) {
    if (position == 1) {
        deleteAtHead(head);
        return;
    }

    Node* currentNode = head;
    int index = 1;

    while (index != position - 1) {
        currentNode = currentNode->nextNode;
        index++;
    }

    Node* nodeToDelete = currentNode->nextNode;
    currentNode->nextNode = currentNode->nextNode->nextNode;

    delete nodeToDelete;
}

// Hiển thị danh sách
void display(Node* head) {
    if (head == nullptr) return;

    Node* currentNode = head;
    do {
        cout << currentNode->value << " ";
        currentNode = currentNode->nextNode;
    } while (currentNode != head);
    cout << endl;
}

int main() {
    Node* head = nullptr;
    insertAtTail(head, 1);
    insertAtTail(head, 2);
    insertAtTail(head, 3);
    insertAtTail(head, 4);
    display(head);
    insertAtHead(head, 6);
    display(head);
    deleteAtHead(head);
    display(head);
    deleteAtPosition(head, 3);
    display(head);
}

