    }
};

class DoublyCircularLinkedList {
private:
    Node* head;
    Node* tail;

public:
    DoublyCircularLinkedList() {
        head = nullptr;
        tail = nullptr;
    }

    // Initializes the list with user-defined number of elements
    void create() {
        int numberOfElements;
        cout << "Enter how many data you want to enter? " << endl;
        cin >> numberOfElements;
        for (int i = 0; i < numberOfElements; i++) {
            int temp;
            cin >> temp;
            addAtEnd(temp);
        }
    }

    // Adds an element at the beginning of the list
    void addAtBeginning(int element) {
        if (head == nullptr) {
            Node* newNode = new Node(element);
            head = newNode;
            tail = head;
            return;
        }
        Node* newNode = new Node(element);
        newNode->next = head;
        newNode->previous = tail;
        head->previous = newNode;
        tail->next = newNode;
        head = newNode;
    }

    // Adds an element at the end of the list
    void addAtEnd(int element) {
        if (head == nullptr) {
            addAtBeginning(element);
            return;
        }
        Node* newNode = new Node(element);
        newNode->previous = tail;
        newNode->next = head;
        tail->next = newNode;
        head->previous = newNode;
        tail = newNode;
    }

    // Adds an element at a specific position in the list
    void addAtPosition(int position, int element) {
        int totalCount = count();
        if (position > totalCount + 1 || position < 1) {
            cout << "Invalid position = " << position << endl;
            return;
        }
        if (position == 1) {
            addAtBeginning(element);
        } else {
            Node* newNode = new Node(element);
            Node* currentNode = head;
            for (int i = 1; i < position - 1; i++) {
                currentNode = currentNode->next;
            }
            newNode->previous = currentNode;
            newNode->next = currentNode->next;
            currentNode->next = newNode;
        }
    }

    // Deletes the first element of the list
    void deleteAtBeginning() {
        if (head == nullptr) {
            cout << "Your list is empty " << endl;
            return;
        }
        if (head == tail) {
            delete head;
            head = nullptr;
            tail = nullptr;
            return;
        }
        Node* tempNode = head;
        head = head->next;
        head->previous = tail;
        tail->next = head;
        delete tempNode;
    }

    // Deletes the last element of the list
    void deleteAtEnd() {
        if (head == nullptr) {
            cout << "List empty ";
            return;
        }
        if (head == tail) {
            delete head;
            head = nullptr;
            tail = nullptr;
            return;
        }
        tail->previous->next = head;
        head->previous = tail->previous;
        Node* tempNode = tail;
        tail = tail->previous;
        delete tempNode;
    }

    // Deletes an element at a specific position in the list
    void deleteAtPosition(int position) {
        int totalCount = count();
        if (position < 1 || position > totalCount) {
            cout << "Invalid position " << endl;
            return;
        }
        if (position == 1) {
            deleteAtBeginning();
        } else {
            Node* currentNode = head;
            for (int i = 0; i < position - 1; i++) {
                currentNode = currentNode->next;
            }
            Node* nodeToDelete = currentNode->next;
            currentNode->next = nodeToDelete->next;
            nodeToDelete->next->previous = currentNode;
            delete nodeToDelete;
            if (currentNode->next == head) {
                tail = currentNode;
            }
        }
    }

    // Counts the number of elements in the list
    int count() {
        if (head == nullptr) {
            return 0;
        }
        int counter = 1;
        Node* currentNode = head;
        while (currentNode->next != head) {
            counter++;
            currentNode = currentNode->next;
        }
        return counter;
    }

    // Displays the elements of the list
    void display() {
        if (head == nullptr) {
            cout << "It's empty !! " << endl;
            return;
        }
        Node* currentNode = head;
        while (currentNode != tail) {
            cout << currentNode->value << " ";
            currentNode = currentNode->next;
        }
        cout << currentNode->value;
        cout << "\n" << endl;
    }
};

