#include <iostream>
using namespace std;

class Node {
public:
    int value;
    Node* nextNode;

    // Constructor to initialize node with a value
    Node(int val) {
        value = val;
        nextNode = nullptr;
    }
};

// Inserts a new node with the given value at the end of the list
void insertAtTail(Node*& head, int val) {
    Node* newNode = new Node(val);
    if (head == nullptr) {
        head = newNode;
        return;
    }

    Node* currentNode = head;
    // Traverse to the end of the list
    while (currentNode->nextNode != nullptr) {
        currentNode = currentNode->nextNode;
    }
    currentNode->nextNode = newNode;
}

// Inserts a new node with the given value at the beginning of the list
void insertAtHead(Node*& head, int val) {
    Node* newNode = new Node(val);
    newNode->nextNode = head;
    head = newNode;
}

// Searches for a node with the specified key and reports its presence
void search(Node* head, int key) {
    Node* currentNode = head;
    bool found = false;

    // Traverse the list to find the key
    while (currentNode != nullptr) {
        if (currentNode->value == key) {
            found = true;
            break;
        }
        currentNode = currentNode->nextNode;
    }

    // Output the result of the search
    if (found) {
        cout << key << " is present" << endl;
    } else {
        cout << key << " is not present" << endl;
    }
}

// Displays the values of all nodes in the list
void display(Node* head) {
    Node* currentNode = head;
    // Traverse and print each node's value
    while (currentNode != nullptr) {
        cout << currentNode->value << " ";
        currentNode = currentNode->nextNode;
    }
    cout << endl;
}

// Deletes the head node of the list
void deleteHead(Node*& head) {
    Node* nodeToDelete = head;
    head = head->nextNode;
    delete nodeToDelete;
}

// Deletes the first occurrence of a node with the specified value
void deleteAnywhere(Node*& head, int val) {
    if (head == nullptr) {
        return;
    }

    // Handle deletion of the head node
    if (head->nextNode == nullptr) {
        deleteHead(head);
        return;
    }

    Node* currentNode = head;
    // Traverse to find the node before the one to delete
    while (currentNode->nextNode != nullptr && currentNode->nextNode->value != val) {
        currentNode = currentNode->nextNode;
    }

    // If the node to delete is found, perform deletion
    if (currentNode->nextNode != nullptr) {
        Node* nodeToDelete = currentNode->nextNode;
        currentNode->nextNode = currentNode->nextNode->nextNode;
        delete nodeToDelete;
    }
}

int main() {
    Node* head = nullptr;
    insertAtHead(head, 1);
    insertAtTail(head, 2);
    insertAtTail(head, 3);
    insertAtTail(head, 4);

    display(head);
    search(head, 3);
    display(head);

    deleteHead(head);
    display(head);

    deleteAnywhere(head, 4);
    display(head);
}

#include <iostream>
using namespace std;

class Node {
public:
    int key;
    int data;
    Node* next;

    Node() : key(0), data(0), next(nullptr) {}

    Node(int k, int d) : key(k), data(d), next(nullptr) {}
};

class SinglyLinkedList {
public:
    Node* head;

    SinglyLinkedList() : head(nullptr) {}

    SinglyLinkedList(Node* n) : head(n) {}

    Node* findNodeByKey(int key) {
        Node* currentNode = head;
        while (currentNode != nullptr) {
            if (currentNode->key == key) {
                return currentNode;
            }
            currentNode = currentNode->next;
        }
        return nullptr;
    }

    void appendNode(Node* newNode) {
        if (findNodeByKey(newNode->key) != nullptr) {
            cout << "Node with key " << newNode->key << " already exists." << endl;
            return;
        }

        if (head == nullptr) {
            head = newNode;
            cout << "Node appended." << endl;
        } else {
            Node* currentNode = head;
            while (currentNode->next != nullptr) {
                currentNode = currentNode->next;
            }
            currentNode->next = newNode;
            cout << "Node appended." << endl;
        }
    }

    void prependNode(Node* newNode) {
        if (findNodeByKey(newNode->key) != nullptr) {
            cout << "Node with key " << newNode->key << " already exists." << endl;
            return;
        }

        newNode->next = head;
        head = newNode;
        cout << "Node prepended." << endl;
    }

    void insertNodeAfterKey(int key, Node* newNode) {
        Node* existingNode = findNodeByKey(key);
        if (existingNode == nullptr) {
            cout << "No node exists with key value " << key << "." << endl;
            return;
        }

        if (findNodeByKey(newNode->key) != nullptr) {
            cout << "Node with key " << newNode->key << " already exists." << endl;
            return;
        }

        newNode->next = existingNode->next;
        existingNode->next = newNode;
        cout << "Node inserted." << endl;
    }

    void deleteNodeByKey(int key) {
        if (head == nullptr) {
            cout << "List is empty." << endl;
            return;
        }

        if (head->key == key) {
            head = head->next;
            cout << "Node deleted." << endl;
            return;
        }

        Node* previousNode = head;
        Node* currentNode = head->next;

        while (currentNode != nullptr) {
            if (currentNode->key == key) {
                previousNode->next = currentNode->next;
                cout << "Node with key " << key << " deleted." << endl;
                return;
            }
            previousNode = currentNode;
            currentNode = currentNode->next;
        }

        cout << "No node exists with key value " << key << "." << endl;
    }

    void updateNodeData(int key, int newData) {
        Node* existingNode = findNodeByKey(key);
        if (existingNode != nullptr) {
            existingNode->data = newData;
            cout << "Node data updated successfully." << endl;
        } else {
            cout << "Node with key " << key << " does not exist." << endl;
        }
    }

    void printList() {
        if (head == nullptr) {
            cout << "List is empty." << endl;
            return;
        }

        cout << "\nSingly linked list values are:" << endl;
        Node* currentNode = head;
        while (currentNode != nullptr) {
            cout << "(" << currentNode->key << ", " << currentNode->data << ") --> ";
            currentNode = currentNode->next;
        }
        cout << "nullptr" << endl;
    }
};

int main() {
    SinglyLinkedList list;
    int option;
    int key, newKey, data;

    do {
        cout << "\nSelect an operation:" << endl;
        cout << "1. Append a node" << endl;
