        cout << "\nEnter Choice : ";
        cin >> choice;

        switch (choice) {
            case 1:
                students[count].addData();
                count++;
                break;
            case 2:
                for (int j = 0; j < count; j++) {
                    Student::displayHeader(); // Call static function to display header
                    students[j].display();
                }
                break;
            case 3:
                int facultyDivision;
                cout << "\nEnter Division of Faculty: ";
                cin >> facultyDivision;

                for (int j = 0; j < count; j++) {
                    cout << "\n * * * Student Information System (Faculty of OOP) * * *" << endl; 
                    faculty.displayByDivision(students[j], facultyDivision);
                }
                break;
            case 4:
                exit(0);
        }
    } while (choice != 4); // End of while loop

    return 0; // End of main
} // End of main function

