    // Sets the roll number for the student
    void setRollNumber(int number) {
        rollNumber = number;
    }

    // Displays the roll number of the student
    void displayRollNumber() const {
        cout << "Student roll number is: " << rollNumber << endl;
    }
};

// Class representing test scores, inheriting from Student
class Test : public virtual Student {
protected:
    float physicsScore;
    float mathScore;

public:
    // Sets the marks obtained in physics and maths
    void setMarks(float physics, float math) {
        physicsScore = physics;
        mathScore = math;
    }

    // Displays the marks obtained in the subjects
    void displayMarks() const {
        cout << "Your marks in the subjects are:" << endl
             << "Physics marks: " << physicsScore << endl
             << "Maths marks: " << mathScore << endl;
    }
