// Class representing sports scores, inheriting from Student
class Sports : public virtual Student {
protected:
    int sportsScore;

public:
    // Sets the score obtained in sports
    void setScore(int score) {
        sportsScore = score;
    }

    // Displays the sports score
    void displayScore() const {
        cout << "Your score is: " << sportsScore << endl;
    }
};

// Class representing the final result, inheriting from Test and Sports
class Result : public Test, public Sports {
protected:
    float totalScore;

public:
    // Calculates the total result based on marks and sports score
    void calculateResult() {
        totalScore = physicsScore + mathScore + sportsScore;
    }

