}

#include <iostream>
using namespace std;

class ComplexNumber {
    int realPart;
    int imaginaryPart;

public:
    // Default constructor initializes the complex number to 0 + 0i
    ComplexNumber() : realPart(0), imaginaryPart(0) {}

    // Parameterized constructor to initialize with specific values
    ComplexNumber(int real, int imaginary) : realPart(real), imaginaryPart(imaginary) {}

    // Input method to get the real and imaginary parts from the user
    void inputData() {
        cout << "\nEnter the real part: ";
        cin >> realPart;
        cout << "Enter the imaginary part: ";
        cin >> imaginaryPart;
    }

    // Display method to show the entered complex number
    void displayData() const {
        cout << "Entered data = " << realPart << " + " << imaginaryPart << "i" << endl;
    }

    // Print method to output the complex number in standard form
    void print() const {
        cout << realPart << " + " << imaginaryPart << "i" << endl;
    }

    // Overloaded operator to add two complex numbers
    ComplexNumber operator +(const ComplexNumber& other) const {
        return ComplexNumber(realPart + other.realPart, imaginaryPart + other.imaginaryPart);
    }
};

int main() {
    ComplexNumber firstComplex;
    firstComplex.inputData();
    firstComplex.displayData();

    ComplexNumber secondComplex;
    secondComplex.inputData();
    secondComplex.displayData();

    ComplexNumber thirdComplex;
    thirdComplex.inputData();
    thirdComplex.displayData();

    // Sum the three complex numbers
    ComplexNumber resultComplex = firstComplex + secondComplex + thirdComplex;
    resultComplex.print();

    return 0;
}

