    // Calculate the total price for purchasing a specified number of books
    double CalculateNetPrice(int quantity) const {
        // Apply discount if quantity exceeds the minimum required for discount
        if (quantity > minimumDiscountQuantity) {
            return static_cast<double>(quantity) * price * discountRate;
        } else {
            return static_cast<double>(quantity) * price;
        }
    }

