#ifndef BPLUSTREE_H
#define BPLUSTREE_H

#include "FileManager.hpp"
#include "Node.hpp"
#include <cstring>
#include <cmath>
#include "vector.hpp"
#include "utility.hpp"

namespace sjtu {

    template<class Key_Type,
            class Value_Type,
            class Compare = std::less<Key_Type>,
            class Compare_value = std::less<Value_Type>
    >
    class BPlusTree {

        bool compare(const Key_Type &x, const Key_Type &y) const {
            static Compare comparator;
            return comparator(x, y);
        }

        bool isEqual(const Key_Type &x, const Key_Type &y) const {
            return !(compare(x, y) || compare(y, x));
        }

        bool compareValue(const Value_Type &x, const Value_Type &y) const {
            static Compare_value comparator;
            return comparator(x, y);
        }

        bool isEqualValue(const Value_Type &x, const Value_Type &y) const {
            return !(compareValue(x, y) || compareValue(y, x));
        }

    private:
        typedef TreeNode<Key_Type, Value_Type> Node;

        struct Result {
            bool success;
            bool modified;
            Result(bool a, bool b) : success(a), modified(b) {}
            Result() {}
        };

    private:
        char filename[50];
        int branch_degree, leaf_degree;
        int key_byte_size, value_byte_size;
        Node pool[50];
        Node nodes[101];

    public:
        int node_count;
        int pool_count;
        FileManager<Key_Type, Value_Type> file_manager;

    private:
        void retrieveBlock(addType address, Node &current) {
            int position;
            for (position = 0; position < pool_count; position++) {
                if (nodes[position].address == address) {
                    if (position != 0) {
                        nodes[100] = nodes[position - 1];
                        nodes[position - 1] = nodes[position];
                        nodes[position] = nodes[100];
                        current = nodes[position - 1];
                    } else {
                        current = nodes[0];
                    }
                    break;
                }
            }
            if (position == pool_count) {
                if (pool_count <= 100) {
                    current = pool[pool_count++];
                    file_manager.get_block(address, current);
                } else {
                    file_manager.write_block(pool[99]);
                    current = pool[99];
                    file_manager.get_block(address, current);
                }
            }
        }

        Result removeNode(Node &current, const Key_Type &key) {
            int sibling_offset = 1;

            if (current.isLeaf) {
                int delete_position = current.search_exact(key);
                if (delete_position == -1)
                    return Result(false, false);
                else {
                    current.keys.erase(delete_position);
                    current.vals.erase(delete_position);
                    return Result(true, true);
                }
            } else {
                Node &child = pool[node_count++];
                child.clear();
                int child_position = findChild(current, key, child);
                Result result_info = removeNode(child, key);
                if (!result_info.success) {
                    node_count--;
                    return Result(false, false);
                }
                if (child.isLeaf) {
                    if (child.keys.size() >= static_cast<int>(ceil(leaf_degree / 2.0))) {
                        file_manager.write_block(child);
                        node_count--;
                        return Result(true, false);
                    } else {
                        Node &sibling = pool[node_count++];
                        int sibling_position;
                        int key_position;
                        Node *left_node, *right_node;

                        if (child_position == current.childs.size() - 1) {
                            file_manager.get_block(current.childs[current.childs.size() - 2], sibling);
                            sibling_position = current.childs.size() - 2;
                        } else {
                            file_manager.get_block(current.childs[child_position + sibling_offset], sibling);
                            sibling_position = child_position + sibling_offset;
                        }

                        if (child_position < sibling_position) {
                            key_position = child_position;
                            left_node = &child;
                            right_node = &sibling;
                        } else {
                            key_position = sibling_position;
                            left_node = &sibling;
                            right_node = &child;
                        }

                        if (child.keys.size() + sibling.keys.size() <= leaf_degree) {
                            left_node->next = right_node->next;
                            if (file_manager.tail_off == right_node->address)
                                file_manager.tail_off = left_node->address;

                            for (int i = 0; i < right_node->keys.size(); ++i) {
                                left_node->keys.push_back(right_node->keys[i]);
                                left_node->vals.push_back(right_node->vals[i]);
                            }

                            current.keys.erase(key_position);
                            current.childs.erase(key_position + 1);
                            file_manager.write_block(*left_node);
                            node_count -= 2;
                            return Result(true, true);
                        } else {
                            if (sibling_position < child_position) {
                                while (child.keys.size() < static_cast<int>(ceil(leaf_degree / 2.0))) {
                                    Key_Type key_shift = sibling.keys.back();
                                    Value_Type val_shift = sibling.vals.back();

                                    sibling.keys.pop_back();
                                    sibling.vals.pop_back();

                                    child.keys.insert(0, key_shift);
                                    child.vals.insert(0, val_shift);

                                    current.keys[key_position] = child.keys[0];
                                }
                                file_manager.write_block(child);
                                file_manager.write_block(sibling);
                                node_count -= 2;
                                return Result(true, true);
                            } else {
                                while (child.keys.size() < static_cast<int>(ceil(leaf_degree / 2.0))) {
                                    Key_Type key_shift = sibling.keys.front();
                                    Value_Type val_shift = sibling.vals.front();

                                    sibling.keys.erase(0);
                                    sibling.vals.erase(0);

                                    child.keys.push_back(key_shift);
                                    child.vals.push_back(val_shift);

                                    current.keys[key_position] = sibling.keys[0];
                                }
                                file_manager.write_block(child);
                                file_manager.write_block(sibling);
                                node_count -= 2;
                                return Result(true, true);
                            }
                        }
                    }
                } else {
                    if (child.childs.size() >= static_cast<int>(ceil(branch_degree / 2.0))) {
                        if (result_info.modified)
                            file_manager.write_block(child);
                        node_count--;
                        return Result(true, false);
                    } else {
                        Node &sibling = pool[node_count++];
                        int sibling_position;
                        int key_position;
                        Key_Type key_bt;
                        Node *left_node, *right_node;

                        if (child_position == current.childs.size() - 1) {
                            file_manager.get_block(current.childs[current.childs.size() - 2], sibling);
                            sibling_position = current.childs.size() - 2;
                        } else {
                            file_manager.get_block(current.childs[child_position + sibling_offset], sibling);
                            sibling_position = child_position + sibling_offset;
                        }

                        if (child_position < sibling_position) {
                            key_position = child_position;
                            left_node = &child;
                            right_node = &sibling;
                        } else {
                            key_position = sibling_position;
                            left_node = &sibling;
                            right_node = &child;
                        }

                        key_bt = current.keys[key_position];

                        if (child.childs.size() + sibling.keys.size() <= branch_degree) {
                            left_node->keys.push_back(key_bt);
                            for (int i = 0; i < right_node->keys.size(); ++i)
                                left_node->keys.push_back(right_node->keys[i]);
                            for (int i = 0; i < right_node->childs.size(); ++i)
                                left_node->childs.push_back(right_node->childs[i]);

                            current.keys.erase(key_position);
                            current.childs.erase(key_position + 1);
                            file_manager.write_block(*left_node);
                            file_manager.write_block(*right_node);
                            node_count -= 2;
                            return Result(true, true);
                        } else {
                            if (sibling_position < child_position) {
                                while (child.childs.size() < static_cast<int>(ceil(branch_degree / 2.0))) {
                                    Key_Type key_shift = sibling.keys.back();
                                    addType child_shift = sibling.childs.back();

                                    sibling.keys.pop_back();
                                    sibling.childs.pop_back();

                                    child.keys.insert(0, key_bt);
                                    child.childs.insert(0, child_shift);

                                    current.keys[key_position] = key_shift;
                                }
                                file_manager.write_block(child);
                                file_manager.write_block(sibling);
                                node_count -= 2;
                                return Result(true, true);
                            } else {
                                while (child.childs.size() >= static_cast<int>(ceil(branch_degree / 2.0))) {
                                    Key_Type key_shift = sibling.keys.front();
                                    addType child_shift = sibling.childs.front();

                                    sibling.keys.erase(0);
                                    sibling.childs.erase(0);

                                    child.keys.push_back(key_shift);
                                    child.childs.push_back(child_shift);

                                    current.keys[key_position] = key_shift;
                                }
                                file_manager.write_block(child);
                                file_manager.write_block(sibling);
                                node_count -= 2;
                                return Result(true, true);
                            }
                        }
                    }
                }
            }
        }

        Key_Type splitBranch(Node &branch, Node &nextBranch) {
            int mid = static_cast<int>(ceil(branch_degree / 2.0));
            Key_Type mid_key = branch.keys[mid - 1];

            nextBranch.childs.assign(branch.childs, mid, branch.childs.size());
            nextBranch.keys.assign(branch.keys, mid, branch.keys.size());

            branch.childs.shorten_len(mid);
            branch.keys.shorten_len(mid - 1);
            return mid_key;
        }

        void splitLeaf(Node &leaf, Node &nextLeaf) {
            nextLeaf.keys.assign(leaf.keys, leaf.keys.size() / 2, leaf.keys.size());
            nextLeaf.vals.assign(leaf.vals, leaf.vals.size() / 2, leaf.vals.size());

            leaf.keys.shorten_len(leaf.keys.size() / 2);
            leaf.vals.shorten_len(leaf.vals.size() / 2);
        }

        bool insertInLeaf(Node &current, const Key_Type &key, const Value_Type &value) {
            int index = current.search_sup(key);
            if (index == -1) {
                current.keys.push_back(key);
                current.vals.push_back(value);
                return true;
            }
            current.keys.insert(index, key);
            current.vals.insert(index, value);
            return true;
        }

        Result insertNode(Node &current, const Key_Type &key, const Value_Type &value) {
            if (current.isLeaf) {
                bool success = insertInLeaf(current, key, value);
                return Result(success, success);
            } else {
                Node &child = pool[node_count++];
                int child_position = findChild(current, key, child);
                Result result_info = insertNode(child, key, value);
                if (!result_info.success) {
                    node_count--;
                    return Result(false, false);
                }
                if (child.isLeaf) {
                    if (child.keys.size() <= leaf_degree) {
                        file_manager.write_block(child);
                        node_count--;
                        return Result(true, false);
                    } else {
                        Node &newLeaf = pool[node_count++];
                        file_manager.append_block(newLeaf, true);
                        if (file_manager.tail_off == child.address)
                            file_manager.tail_off = newLeaf.address;

                        splitLeaf(child, newLeaf);
                        newLeaf.next = child.next;
                        child.next = newLeaf.address;

                        current.childs.insert(child_position + 1, newLeaf.address);
                        current.keys.insert(child_position, newLeaf.keys[0]);

                        file_manager.write_block(child);
                        file_manager.write_block(newLeaf);
                        node_count -= 2;
                        return Result(true, true);
                    }
                } else {
                    if (child.childs.size() <= branch_degree) {
                        file_manager.write_block(child);
                        node_count--;
                        return Result(true, false);
                    } else {
                        Key_Type mid_key;
                        Node &newBranch = pool[node_count++];
                        file_manager.append_block(newBranch, false);

                        mid_key = splitBranch(child, newBranch);
                        current.childs.insert(child_position + 1, newBranch.address);
                        current.keys.insert(child_position, mid_key);

                        file_manager.write_block(child);
                        file_manager.write_block(newBranch);
                        node_count -= 2;
                        return Result(true, true);
                    }
                }
            }
        }

        int findChild(Node &current, const Key_Type key, Node &child) {
            int index = current.search_sup(key);
            if (index == -1) {
                file_manager.get_block(current.childs.back(), child);
                return current.childs.size() - 1;
            } else {
                file_manager.get_block(current.childs[index], child);
                return index;
            }
        }

        void searchToLeaf(Key_Type key, Node &result) {
            file_manager.get_root(result);
            while (!result.isLeaf) {
                findChild(result, key, result);
            }
        }

        int findChildMulti(Node &current, const Key_Type key) {
            int index = current.search_sup_multi(key);
            file_manager.get_block(current.childs[index], current);
            return index;
        }

        void searchToLeafMulti(Key_Type key, Node &result) {
            file_manager.get_root(result);
            while (!result.isLeaf) {
                findChildMulti(result, key);
            }
        }

    public:
        explicit BPlusTree(const char *fname) {
            strcpy(filename, fname);
            file_manager.set_fileName(fname);

            key_byte_size = sizeof(Key_Type);
            value_byte_size = sizeof(Value_Type);
            node_count = 0;

            leaf_degree = (BlockSize - node_utility_byte) / (key_byte_size + value_byte_size);
            branch_degree = (BlockSize - node_utility_byte) / (sizeof(addType) + key_byte_size);
        }

        ~BPlusTree() {
            if (file_manager.is_opened())
                file_manager.close_file();
        }

        bool clean() {
            if (!file_manager.is_opened()) return false;
            for (int i = 0; i < node_count; i++) {
                pool[i].clear();
            }
            node_count = 0;
            file_manager.clean();
            return true;
        }

        bool openFile() {
            return file_manager.open_file();
        }

        bool closeFile() {
            return file_manager.close_file();
        }

        sjtu::vector<Value_Type> findMulti(const Key_Type &key) {
            sjtu::vector<Value_Type> result;
            if (!find(key).first)
                return result;

            Node &current = pool[node_count++];
            searchToLeafMulti(key, current);
            int index = current.search_exact(key);
            node_count--;

            if (index == -1) {
                if (current.next == -1)
                    return result;

                file_manager.get_block(current.next, current);
                index = current.search_exact(key);
                if (index == -1)
                    return result;
            }

            index--;
            while (true) {
                index++;
                if (!isEqual(current.keys[index], key)) break;
                result.push_back(current.vals[index]);
                if (index == current.keys.size() - 1) {
                    if (current.next == -1) {
                        return result;
                    }
                    file_manager.get_block(current.next, current);
                    index = -1;
                }
            }
            return result;
        }

        std::pair<bool, Value_Type> find(const Key_Type &key) {
            Node &result = pool[node_count++];
            searchToLeaf(key, result);
            int index = result.search_exact(key);
            node_count--;

            if (index == -1)
                return std::pair<bool, Value_Type>(false, Value_Type());
            else
                return std::pair<bool, Value_Type>(true, result.vals[index]);
        }

        bool modify(Key_Type key, Value_Type value) {
            Node &leafNode = pool[node_count++];
            searchToLeaf(key, leafNode);
            int keyPosition = leafNode.search_exact(key);

            if (keyPosition == -1) {
                node_count--;
                return false;
            } else {
                leafNode.vals[keyPosition] = value;
                file_manager.write_block(leafNode);
                node_count--;
                return true;
            }
        }

        bool insert(const Key_Type &key, const Value_Type &value) {
            Node &root = pool[node_count++];

            if (file_manager.root_off == -1) {
                file_manager.append_block(root, true);
                root.keys.push_back(key);
                root.vals.push_back(value);

                file_manager.set_root(root.address);
                file_manager.write_block(root);

                file_manager.head_off = root.address;
                file_manager.tail_off = root.address;
                node_count--;
                return true;
            }

            file_manager.get_root(root);
            Result result_info = insertNode(root, key, value);

            if (!result_info.success) {
                node_count--;
                return false;
            } else {
                if (root.isLeaf) {
                    if (root.keys.size() > leaf_degree) {
                        Node &newLeaf = pool[node_count++];
                        Node &newRoot = pool[node_count++];
                        file_manager.append_block(newLeaf, true);

                        splitLeaf(root, newLeaf);
                        newLeaf.next = root.next;
                        root.next = newLeaf.address;

                        if (file_manager.tail_off == root.address)
                            file_manager.tail_off = newLeaf.address;

                        file_manager.append_block(newRoot, false);
                        newRoot.childs.push_back(root.address);
                        newRoot.childs.push_back(newLeaf.address);
                        newRoot.keys.push_back(newLeaf.keys[0]);

                        file_manager.root_off = newRoot.address;

                        file_manager.write_block(root);
                        file_manager.write_block(newLeaf);
                        file_manager.write_block(newRoot);
                        node_count -= 3;
                        return true;
                    } else {
                        if (result_info.modified) {
                            file_manager.write_block(root);
                        }
                        node_count--;
                        return true;
                    }
                } else {
                    if (root.childs.size() > branch_degree) {
                        Node &newBranch = pool[node_count++];
                        Node &newRoot = pool[node_count++];
                        Key_Type mid_key;

                        file_manager.append_block(newBranch, false);
                        mid_key = splitBranch(root, newBranch);

                        file_manager.append_block(newRoot, false);
                        newRoot.childs.push_back(root.address);
                        newRoot.childs.push_back(newBranch.address);
                        newRoot.keys.push_back(mid_key);

                        file_manager.root_off = newRoot.address;

                        file_manager.write_block(root);
                        file_manager.write_block(newBranch);
                        file_manager.write_block(newRoot);
                        node_count -= 3;
                        return true;
                    } else {
                        if (result_info.modified) {
                            file_manager.write_block(root);
                        }
                        node_count--;
                        return true;
                    }
                }
            }
        }

        bool erase(Key_Type key) {
            if (file_manager.root_off == -1) {
                return false;
            }

            Node &root = pool[node_count++];
            Result result_info;
            file_manager.get_root(root);
            result_info = removeNode(root, key);

            if (!result_info.success) {
                node_count--;
                return false;
            } else {
                if (root.isLeaf) {
                    if (root.keys.size() == 0) {
                        file_manager.root_off = file_manager.head_off = file_manager.tail_off = -1;
                    }
                    if (result_info.modified)
                        file_manager.write_block(root);
                } else {
                    if (root.childs.size() == 1) {
                        file_manager.root_off = root.childs[0];
                    } else if (result_info.modified) {
                        file_manager.write_block(root);
                    }
                }
                node_count--;
                return true;
            }
        }
    };
};

