#ifndef FILEMANAGER_H
#define FILEMANAGER_H

#include <cstring>
#include "BPlusTree.hpp"
#include "constant.h"
#include "Node.hpp"
#include "utility.hpp"

#define START_OFFSET 4096

namespace sjtu {

    template<class Key_Type,
             class Value_Type,
             class Comparator = std::less<Key_Type>,
             class ChildComparator = std::less<addType>>
    class FileManager {
    private:
        using Node = TreeNode<Key_Type, Value_Type>;

        char filename[100];
        FILE *file;
        bool isOpened;

        bool compare(const Key_Type &x, const Key_Type &y) const {
            static Comparator comparator;
            return comparator(x, y);
        }

        bool isEqual(const Key_Type &x, const Key_Type &y) const {
            return !(compare(x, y) || compare(y, x));
        }

    public:
        addType rootOffset;
        addType headOffset;
        addType tailOffset;
        addType appendOffset;

        struct Header {
            addType rootOffset = -1;
            addType headOffset = -1;
            addType tailOffset = -1;
            addType appendOffset = START_OFFSET;
        };

        struct Block {
            bool isLeaf;
            addType next;
            short keyCount;
            short valueCount;
            short childCount;
        };

    private:
        void createFile() {
            file = fopen(filename, "wb");
            rootOffset = headOffset = tailOffset = -1;
            appendOffset = START_OFFSET;
            Header header;
            fwrite(&header, sizeof(Header), 1, file);
            fclose(file);
        }

        void initialize() {
            file = fopen(filename, "r");
            if (file == nullptr) {
                createFile();
                file = fopen(filename, "r+b");
            } else {
                file = fopen(filename, "r+b");
                Header header;
                fread(&header, sizeof(Header), 1, file);
                headOffset = header.headOffset;
                tailOffset = header.tailOffset;
                rootOffset = header.rootOffset;
                appendOffset = header.appendOffset;
            }
        }

    public:
        FileManager() {
            filename[0] = '\0';
            isOpened = false;
            rootOffset = headOffset = tailOffset = -1;
            appendOffset = START_OFFSET;
            file = nullptr;
        }

        ~FileManager() {
            if (isOpened) {
                closeFile();
            }
        }

        void setFileName(const char *fname) {
            strcpy(filename, fname);
        }

        void clearFileName() {
            filename[0] = '\0';
        }

        bool openFile() {
            if (isOpened) {
                return false;
            } else {
                initialize();
                isOpened = true;
                return true;
            }
        }

        bool closeFile() {
            if (!isOpened) {
                std::cout << "File is not opened!\n";
                return false;
            } else {
                fseek(file, 0, SEEK_SET);
                Header header;
                header.headOffset = headOffset;
                header.rootOffset = rootOffset;
                header.tailOffset = tailOffset;
                header.appendOffset = appendOffset;
                fwrite(&header, sizeof(Header), 1, file);
                fclose(file);
                resetOffsets();
                return true;
            }
        }

        bool clean() {
            if (!isOpened) return false;
            fclose(file);
            resetOffsets();
            file = fopen(filename, "w+");
            fclose(file);
            file = fopen(filename, "wb+");
            fseek(file, 0, SEEK_SET);
            Header header;
            fwrite(&header, sizeof(Header), 1, file);
            return true;
        }

        bool isOpened() const {
            return isOpened;
        }

        void getBlock(addType offset, Node &node) {
            node.address = offset;
            Block block;
            fseek(file, offset, SEEK_SET);
            fread(&block, sizeof(Block), 1, file);
            node.isLeaf = block.isLeaf;
            node.next = block.next;
            short keySize = block.keyCount;
            short valueSize = block.valueCount;
            short childSize = block.childCount;

            node.keys.readFile(file, keySize);
            node.vals.readFile(file, valueSize);
            node.childs.readFile(file, childSize);
        }

        bool getNextBlock(const Node &current, Node &nextNode) {
            if (current.next == -1) {
                return false;
            } else {
                getBlock(current.next, nextNode);
                return true;
            }
        }

        bool getRoot(Node &node) {
            if (rootOffset == -1) return false;
            getBlock(rootOffset, node);
            return true;
        }

        bool getHead(Node &node) {
            if (headOffset == -1) return false;
            if (headOffset == 0) {
                getBlock(tree_utility_byte, node);
            } else {
                getBlock(headOffset, node);
            }
            return true;
        }

        bool getTail(Node &node) {
            if (tailOffset == -1) return false;
            if (tailOffset == 0) {
                getBlock(tree_utility_byte, node);
            } else {
                getBlock(tailOffset, node);
            }
            return true;
        }

        void appendBlock(Node &node, bool isLeaf) {
            node.clear();
            node.address = appendOffset;
            node.isLeaf = isLeaf;
            appendOffset += BlockSize;
        }

        void writeBlock(Node &node) {
            fseek(file, node.address, SEEK_SET);
            Block block;
            block.isLeaf = node.isLeaf;
            block.next = node.next;
            block.keyCount = node.keys.size();
            block.valueCount = node.vals.size();
            block.childCount = node.childs.size();
            fwrite(&block, sizeof(Block), 1, file);

            node.keys.writeFile(file);
            node.vals.writeFile(file);
            node.childs.writeFile(file);
        }

        void setRoot(addType offset) {
            rootOffset = offset;
        }

        addType getRoot() const {
            return rootOffset;
        }

        sjtu::vector<Value_Type> traverseMulti(const Key_Type &key) {
            sjtu::vector<Value_Type> results;
            if (headOffset == -1) {
                return results;
            }

            Node currentNode;
            getBlock(headOffset, currentNode);

            while (true) {
                if (compare(currentNode.keys[currentNode.keys.size() - 1], key)) {
                    if (currentNode.next != -1) {
                        getBlock(currentNode.next, currentNode);
                    } else {
                        return results;
                    }
                } else {
                    int index;
                    for (index = 0; index < currentNode.keys.size(); ++index) {
                        if (isEqual(currentNode.keys[index], key)) break;
                    }
                    --index;

                    while (true) {
                        index++;
                        if (!isEqual(currentNode.keys[index], key)) break;
                        results.push_back(currentNode.vals[index]);
                        if (index == currentNode.keys.size() - 1) {
                            if (currentNode.next == -1) {
                                return results;
                            }
                            getBlock(currentNode.next, currentNode);
                            index = -1;
                        }
                    }
                    break;
                }
            }
            return results;
        }

        void traverse() {
            if (headOffset == -1) {
                std::cout << "The file is empty!\n";
                return;
            }

            std::cout << rootOffset << " rootOffset\n";
            Node currentNode;
            getBlock(headOffset, currentNode);
            int totalKeys = 0;

            while (true) {
                totalKeys += currentNode.keys.size();
                if (currentNode.next == -1) break;
                getBlock(currentNode.next, currentNode);
            }
            std::cout << totalKeys << " total keys\n";
        }

    private:
        void resetOffsets() {
            rootOffset = headOffset = tailOffset = -1;
            appendOffset = START_OFFSET;
            file = nullptr;
            isOpened = false;
        }
    };
}

#endif

#ifndef TREENODE_H
#define TREENODE_H

#include "vector.hpp"
#include "constant.h"

#define MIN_COMPARISON_THRESHOLD 20

namespace sjtu {

    template<class KeyType,
             class ValueType,
             class KeyComparator = std::less<KeyType>,
             class ValueComparator = std::less<ValueType>>
    class TreeNode {
    public:
        addType address;          // Address in the file
        bool isLeaf;             // Indicates if the node is a leaf
        addType next;            // Address of the next node
        sjtu::vector<KeyType> keys;          // Keys stored in the node
        sjtu::vector<ValueType> values;      // Values associated with the keys
        sjtu::vector<addType> children;      // Addresses of child nodes

        // Compares two keys using the specified comparator
        bool CompareKeys(const KeyType &x, const KeyType &y) const {
            static KeyComparator keyComparator;
            return keyComparator(x, y);
        }

        // Checks if two keys are equal
        bool AreKeysEqual(const KeyType &x, const KeyType &y) const {
            return !CompareKeys(x, y) && !CompareKeys(y, x);
        }

        // Compares two values using the specified comparator
        bool CompareValues(const ValueType &x, const ValueType &y) const {
            static ValueComparator valueComparator;
            return valueComparator(x, y);
        }

        // Checks if two values are equal
        bool AreValuesEqual(const ValueType &x, const ValueType &y) const {
            return !CompareValues(x, y) && !CompareValues(y, x);
        }

        // Constructor to initialize a TreeNode
        explicit TreeNode(addType _address = -1, bool _isLeaf = true)
            : address(_address), next(-1), isLeaf(_isLeaf), children(), values(), keys() {}

        // Copy constructor
        TreeNode(const TreeNode &other) noexcept
            : address(other.address), next(other.next), isLeaf(other.isLeaf), 
              keys(other.keys), values(isLeaf ? other.values : sjtu::vector<ValueType>()), 
              children(isLeaf ? sjtu::vector<addType>() : other.children) {}

        // Assignment operator
        TreeNode &operator=(const TreeNode &other) {
            if (this != &other) {
                address = other.address;
                next = other.next;
                isLeaf = other.isLeaf;
                keys = other.keys;
                values = other.values;
                children = other.children;
            }
            return *this;
        }

        // Searches for the smallest index where key[index] > K, returns -1 if not found
        int SearchSup(KeyType K) {
            int pos = 0;
            if (keys.size() < MIN_COMPARISON_THRESHOLD) {
                while (pos < keys.size() && !CompareKeys(K, keys[pos])) pos++;
                return (pos == keys.size()) ? -1 : pos;
            } else {
                int low = 0, high = keys.size() - 1;
                while (high - low >= MIN_COMPARISON_THRESHOLD) {
                    int mid = (low + high) / 2;
                    if (!CompareKeys(K, keys[mid]))
                        low = mid;
                    else
                        high = mid;
                }
                while (low < keys.size() && !CompareKeys(K, keys[low])) ++low;
                return (low == keys.size()) ? -1 : low;
            }
        }

        // Searches for the exact index where key[index] = K
        int SearchExact(const KeyType &K) {
            int pos = 0;
            while (pos < keys.size() && !AreKeysEqual(K, keys[pos])) ++pos;
            return (pos == keys.size()) ? -1 : pos;
        }

        // Searches for the first index where keys[index] > K
        int SearchSupMulti(KeyType K) {
            int pos = 0;
            while (pos < keys.size() && CompareKeys(keys[pos], K)) pos++;
            return pos;
        }

        // Clears the contents of the node
        void ClearContent() {
            children.clear();
            keys.clear();
            values.clear();
        }

        // Resets the node to its initial state
        void Clear() {
            address = next = -1;
            isLeaf = true;
            ClearContent();
        }

        // Searches for a child node, returns -1 if not found
        int SearchChild(addType child) {
            if (children.size() < MIN_COMPARISON_THRESHOLD) {
                int i = 0;
                while (i < children.size() && children[i] != child) ++i;
                return (i == children.size()) ? -1 : i;
            } else {
                int low = 0, high = children.size() - 1;
                while (high - low >= MIN_COMPARISON_THRESHOLD) {
                    int mid = (low + high) / 2;
                    if (children[mid] == child)
                        return mid;
                    else if (children[mid] < child)
                        low = mid;
                    else
                        high = mid;
                }
                while (low < children.size() && children[low] != child) ++low;
                return (low == children.size()) ? -1 : low;
            }
        }
    };

};

