class CricketTeam
{
private:
    char playerName[40];
    char region[20];
    float battingAverage;
    float bowlingAverage;

public:
    // Collects player data from user input
    void readData()
    {
        cout << "Enter the Player name:" << endl;
        cin >> playerName;
        cout << "Enter the Region:" << endl;
        cin >> region;
        cout << "Enter the Batting average:" << endl;
        cin >> battingAverage;
        cout << "Enter the Bowling average:" << endl;
        cin >> bowlingAverage;
    }

    // Sorts the team based on batting and bowling averages
    void sortList(CricketTeam team[])
    {
        CricketTeam temp;
        for (int i = 0; i < 3; i++)
        {
            for (int j = 0; j < 2; j++)
            {
                // Swap if the current player's averages meet the sorting criteria
                if (team[j].battingAverage < team[j + 1].battingAverage && team[j].bowlingAverage > team[j + 1].bowlingAverage)
                {
                    temp = team[j];
                    team[j] = team[j + 1];
                    team[j + 1] = temp;
                }
            }
        }
        displayList(team);
    }

    // Generates a list of qualified players based on their averages
    void generateList(CricketTeam team[])
    {
        bool hasQualifiedPlayers = false;
        for (int i = 0; i < 3; i++)
        {
            // Check if player qualifies based on average criteria
            if (team[i].battingAverage > 30 && team[i].bowlingAverage < 25)
            {
                hasQualifiedPlayers = true;
                cout << team[i].playerName << endl;
            }
        }
        if (!hasQualifiedPlayers)
            cout << "Error: No qualified players found." << endl;
    }

    // Displays the list of players with their details
    void displayList(CricketTeam team[])
    {
        for (int i = 0; i < 3; i++)
        {
            cout << "-----Player List-----" << endl;
            cout << "Player Name: " << team[i].playerName << endl;
            cout << "Player Region: " << team[i].region << endl;
            cout << "Batting Average: " << team[i].battingAverage << endl;
            cout << "Bowling Average: " << team[i].bowlingAverage << endl;
        }
    }
};

int main()
{
    CricketTeam team[3];
    cout << "Enter the team details:" << endl;
    for (int i = 0; i < 3; i++)
    {
        team[i].readData();
    }
    cout << "The Qualified Players are:" << endl;
    team[0].generateList(team);

    team[0].sortList(team);

    return 0;
}

