// Class representing an addition operation with multiple constructors
class Adder {
    int firstOperand, secondOperand;

public:
    // Default constructor initializing operands to zero
    Adder() : firstOperand(0), secondOperand(0) {}

    // Constructor accepting two integers to initialize operands
    Adder(int a, int b) : firstOperand(a), secondOperand(b) {}

    // Copy constructor for creating a new Adder from an existing one
    Adder(const Adder &obj) : firstOperand(obj.firstOperand), secondOperand(obj.secondOperand) {}

    // Outputs the sum of the operands
    void print() const {
        cout << firstOperand + secondOperand << endl;
    }

    // Overloaded print function (not used in this context)
    void print(int a, int b) const {
        cout << firstOperand + secondOperand << endl;
    }

    // Overloaded print function accepting another Adder object (not used in this context)
    void print(const Adder &obj) const {
        cout << firstOperand + secondOperand << endl;
    }
};

