    Adder parameterizedAdder(10, 20); // Parameterized constructor
    Adder copiedAdder(parameterizedAdder); // Copy constructor

    defaultAdder.print();         // Print sum of default operands
    parameterizedAdder.print();   // Print sum of parameterized operands
    copiedAdder.print();          // Print sum of copied operands

    return 0;
}

