#include <iostream>
using namespace std;

class ComplexNumber
{
    double realPart, imaginaryPart;

public:
    ComplexNumber() = default;

    ComplexNumber(double real, double imaginary)
        : realPart(real), imaginaryPart(imaginary) {}

    ComplexNumber operator+(const ComplexNumber& other);
    ComplexNumber operator*(const ComplexNumber& other);

    void display() const;
};

ComplexNumber ComplexNumber::operator+(const ComplexNumber& other)
{
    ComplexNumber result;
    result.realPart = realPart + other.realPart;
    result.imaginaryPart = imaginaryPart + other.imaginaryPart;
    return result;
}

ComplexNumber ComplexNumber::operator*(const ComplexNumber& other)
{
    ComplexNumber result;
    result.realPart = realPart * other.realPart - imaginaryPart * other.imaginaryPart;
    result.imaginaryPart = realPart * other.imaginaryPart + imaginaryPart * other.realPart;
    return result;
}

void ComplexNumber::display() const
{
    cout << realPart << "+i" << imaginaryPart;
}

int main()
{
    ComplexNumber num1(2.3, 3.4);
    ComplexNumber num2(2.8, 3.6);
    ComplexNumber sum, product;

    sum = num1 + num2; // Perform addition using overloaded operator
    sum.display();

    product = sum * num2; // Perform multiplication using overloaded operator
    product.display();
}

#include <iostream>
using namespace std;

// Class for prefix unary operator overloading
class PrefixUnaryOperator {
    int x, y, z;

public:
    PrefixUnaryOperator() {}

    PrefixUnaryOperator(int xValue, int yValue, int zValue) {
        x = xValue;
        y = yValue;
        z = zValue;
    }

    // Overload the postfix decrement operator
    void operator--(int) {
        x--;
        y--;
        z--;
    }

    // Display the current values of x, y, and z
    void display() {
        cout << x << " " << y << " " << z << endl;
    }
};

// Class for postfix unary operator overloading
class PostfixUnaryOperator {
    int x, y, z;

public:
    PostfixUnaryOperator() {}

    PostfixUnaryOperator(int xValue, int yValue, int zValue) {
        x = xValue;
        y = yValue;
        z = zValue;
    }

    // Overload the prefix decrement operator
    void operator--() {
        --x;
        --y;
        --z;
    }

    // Display the current values of x, y, and z
    void display() {
        cout << x << " " << y << " " << z << endl;
    }
};

int main() {
    cout << "------In Prefixed------" << endl;
    PrefixUnaryOperator prefixOperator(2, 3, 4);
    prefixOperator--;
    prefixOperator.display();

    cout << "------Now in Post Fixed-----" << endl;
    PostfixUnaryOperator postfixOperator(2, 3, 4);
    --postfixOperator;
    postfixOperator.display();
}

