using namespace std;

struct SeatNode {
    int id;
    char status;
    string customerName;
    SeatNode* next;
    SeatNode* prev;
};

class MovieBookingSystem {
public:
    SeatNode* rows[10];
    SeatNode* currentNode;

    MovieBookingSystem() {
        // Initialize all rows to NULL
        for (int i = 0; i < 10; i++) {
            rows[i] = nullptr;
        }
        currentNode = nullptr;
    }

    void initializeSeats() {
        // Create a circular doubly linked list for each row of seats
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 7; j++) {
                currentNode = new SeatNode();
                currentNode->status = 'U'; // 'U' for Unbooked
                currentNode->next = nullptr;
                currentNode->prev = nullptr;

                if (rows[i] == nullptr) {
                    // First seat in the row
                    currentNode->next = currentNode;
                    currentNode->prev = currentNode;
                    rows[i] = currentNode;
                } else {
                    // Add seat to the end of the row
                    SeatNode* lastNode = rows[i];
                    while (lastNode->next != rows[i]) {
                        lastNode = lastNode->next;
                    }

                    lastNode->next = currentNode;
                    currentNode->prev = lastNode;
                    currentNode->next = rows[i];
                    rows[i]->prev = currentNode;
                }
            }
        }
    }

    void bookSeat() {
        cout << "Enter row and column to book a seat: " << endl;
        int row, column;
        cin >> row >> column;

        if (row < 11 && column < 7) {
            currentNode = rows[row - 1];
            for (int i = 1; i < column; i++) {
                currentNode = currentNode->next;
            }

            currentNode->status = 'B'; // 'B' for Booked

            cout << "Enter movie ID: " << endl;
            cin >> currentNode->id;
            cout << "Enter your name: " << endl;
            cin >> currentNode->customerName;

            cout << "Ticket booked! Enjoy the movie!" << endl;
        } else {
            cout << "Please enter valid row and column." << endl;
        }
    }

    void cancelBooking() {
        cout << "Enter row and column to cancel your seat: " << endl;
        int row, column;
        cin >> row >> column;

        if (row < 11 && column < 7) {
            currentNode = rows[row - 1];
            for (int i = 1; i < column; i++) {
                currentNode = currentNode->next;
            }

            currentNode->status = 'U'; // Reset status to Unbooked
            currentNode->id = 0;
            currentNode->customerName = "";

            cout << "Ticket canceled successfully." << endl;
        } else {
            cout << "Please enter valid row and column." << endl;
        }
    }

    void displaySeatStatus() {
        cout << "                           Screen                          " << endl;
        for (int i = 0; i < 10; i++) {
            currentNode = rows[i];
            for (int j = 0; j < 7; j++) {
                cout << "    " << currentNode->status << "    ";
                currentNode = currentNode->next;
            }
            cout << endl;
        }
    }

    void viewSeatDetails() {
        cout << "Enter row and column to view the details of the seat: " << endl;
        int row, column;
        cin >> row >> column;

        currentNode = rows[row - 1];
        for (int i = 1; i < column; i++) {
            currentNode = currentNode->next;
        }

        cout << "Seat details: " << endl;
        cout << "Seat status: " << currentNode->status << endl;
        cout << "Seat booked by: " << currentNode->customerName << endl;
        cout << "Movie ID: " << currentNode->id << endl;
    }
};

int main() {
    MovieBookingSystem bookingSystem;
    int continueBooking = 1, choice;

    cout << "!!!!!!!!!!!!!!!!!!!!!!!! Movie Ticket Booking System !!!!!!!!!!!!!!!!!!!!!!!!!!!" << endl;
    cout << endl << endl;
    cout << "                                 Today's Shows                                  " << endl;
    cout << "--------------------------------------------------------------------------------" << endl;
    cout << "| Movie ID         | Movie              |  Date             |  Time            |" << endl;
    cout << "| 12               | Titanic            |  12-12-19         |  3:00 PM         |" << endl;
    cout << "| 15               | The Avengers       |  13-12-19         |  6:00 PM         |" << endl;
    cout << "| 16               | X-Men              |  15-12-19         |  9:00 PM         |" << endl;
    cout << "--------------------------------------------------------------------------------" << endl;

    bookingSystem.initializeSeats();

    while (continueBooking) {
        cout << "          Enter 1 to Book tickets         " << endl;
        cout << "          Enter 2 to view booking status         " << endl;
        cout << "          Enter 3 to cancel booked tickets         " << endl;
        cout << "          Enter 4 to view details of seats         " << endl;
