#include "date.h"
#include <sstream>

Date::Date(const std::string& dateInput)
{
    std::istringstream dateStream(dateInput);
    int month, day, year;
    char separator1, separator2;

    // Parse the date input and set the corresponding date components if valid
    if (dateStream >> month >> separator1 >> day >> separator2 >> year && separator1 == '/' && separator2 == '/')
    {
        setMonth(month);
        setDay(day);
        setYear(year);
    }
}

bool Date::overlap(const Date& start1, const Date& end1, const Date& start2, const Date& end2)
{
    // Check if the date ranges overlap
    return (start1 > start2 && end2 > start1) || (end1 > start2 && end2 > end1);
}

bool Date::operator>(const Date& other) const
{
    // Compare two Date objects to determine if the current date is greater
    return (year > other.year) || 
           (year == other.year && month > other.month) || 
           (year == other.year && month == other.month && day > other.day);
}

Date::Date()
    : day(1), month(1), year(2000) // Initialize to a default date
{
}

int Date::getMonth() const
{
    return month;
}

int Date::getDay() const
{
    return day;
}

int Date::getYear() const
{
    return year;
}

bool Date::isLeapYear() const
{
    // Determine if the current year is a leap year
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

void Date::setDay(int newDay)
{
    // Validate and set the day based on the current month
    if ((month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12) && (newDay >= 1 && newDay <= 31))
    {
        day = newDay;
    }
    else if ((month == 4 || month == 6 || month == 9 || month == 11) && (newDay >= 1 && newDay <= 30))
    {
        day = newDay;
    }
    else if (month == 2)
    {
        if (isLeapYear() && (newDay >= 1 && newDay <= 29))
        {
            day = newDay;
        }
        else if (!isLeapYear() && (newDay >= 1 && newDay <= 28))
        {
            day = newDay;
        }
    }
}

void Date::setMonth(int newMonth)
{
    // Validate and set the month
    if (newMonth >= 1 && newMonth <= 12)
    {
        month = newMonth;
    }
}

void Date::setYear(int newYear)
{
    // Validate and set the year
    if (newYear > 0)
    {
        year = newYear;
    }
}

void Date::setDate(const std::string& dateInput)
{
    std::istringstream dateStream(dateInput);
    int month, day, year;
    char separator1, separator2;

    // Parse the date input and set the corresponding date components if valid
    if (dateStream >> month >> separator1 >> day >> separator2 >> year && separator1 == '/' && separator2 == '/')
    {
        setMonth(month);
        setDay(day);
        setYear(year);
    }
}

