#include "Library.h"

Library::Library() : _bookshelf(vector<Book>()) {}

// Adds a Book to the Library.
void Library::add(Book& newBook) {
    _bookshelf.push_back(newBook);
}

// Returns the entire bookshelf.
vector<Book>& Library::getAll() {
    return _bookshelf;
}

// Searches for a Book by name and returns a pointer to it.
Book* Library::search(const std::string& bookName) {
    for (Book& book : _bookshelf) {
        if (book.getName() == bookName) {
            return &book;
        }
    }
    std::cout << "|" << bookName << " BOOK NOT FOUND IN THIS LIBRARY." << std::endl;
    return nullptr; // Return null pointer if the book is not found.
}

// Checks out a Book by name, returning a dummy book if not found.
Book& Library::checkOutBook(const std::string& bookName) {
    Book* foundBook = search(bookName);
    if (foundBook == nullptr) {
        return Book("Not a book", "No Date"); // Return a dummy book if not found.
    }

    for (size_t index = 0; index < _bookshelf.size(); ++index) {
        if (_bookshelf[index].getName() == bookName) {
            Book result = _bookshelf[index]; // Copy the found book.
            _bookshelf.erase(_bookshelf.begin() + index); // Remove the book from the shelf.
            return result; // Return the checked-out book.
        }
    }
    return Book("Not a book", "No Date"); // Fallback return.
}

// Checks if the Library is empty.
bool Library::isEmpty() const {
    return _bookshelf.empty();
}

// Returns the number of books in the Library.
unsigned int Library::size() const {
    return _bookshelf.size();
}

// Overloads the output stream operator to display the Library contents.
std::ostream& operator<<(std::ostream& os, Library& libraryInstance) {
    os << "[\n";
    for (const Book& book : libraryInstance.getAll()) {
        os << book << "\n";
    }
    os << "]" << std::endl;
    return os;
}

// Deletes a Book by name from the Library.
void Library::deleteBook(const std::string& bookName) {
    for (size_t index = 0; index < _bookshelf.size(); ++index) {
        if (_bookshelf[index].getName() == bookName) {
            _bookshelf.erase(_bookshelf.begin() + index);
            return; // Exit after deletion.
        }
    }
}

