void IPLTeams::addTeam() {
    int teamCount;
    char teamName[100];

    cout << "\n********************************";
    cout << "\nYou can add up to 5 teams only";
    cout << "\n********************************";
    cout << "\nHow many teams do you want to add?: ";
    cin >> teamCount;

    fstream teamsFile;
    teamsFile.open("teams.txt", ios::app);
    teamsFile << "Newly Added teams:\n";

    for (int i = 0; i < teamCount; i++) {
        cout << "\nEnter a new team: ";
        cin >> teamName;
        teamsFile << (i + 9) << ". " << teamName << "\n";
    }
    teamsFile.close();
}

void IPLTeams::addPlayers() {
    int teamChoice, playerCount;
    char playerName[100], playerStyle[100];
    int playerAge;

    cout << "\n*******************************************************************************************";
    cout << "\nYou can only add players to the new team created.";
    cout << "\n----------------------------------------------------------------------------------------";
    cout << "\nSo if you have not created a team, first create it then come back to add the new players.";
    cout << "\n********************************************************************************************";
    cout << "\nIn which of the newly added teams do you want to enter players?: ";
    cout << "\n1. Team 9";
    cout << "\n2. Team 10";
    cout << "\n3. Team 11";
    cout << "\n4. Team 12";
    cout << "\n5. Team 13\n";
    cout << "Enter your choice: ";
    cin >> teamChoice;

    if (teamChoice >= 1 && teamChoice <= 5) {
        cout << "\nHow many players do you want to enter?: ";
        cin >> playerCount;

        fstream playerFile;
        playerFile.open("team" + to_string(teamChoice) + ".txt", ios::app);
        playerFile << "Players added\n";
        playerFile << "===============================================================================================================\n";
        playerFile << "Name                      Style            Age\n";

        for (int i = 1; i <= playerCount; i++) {
            cout << "\nEnter player name: ";
            cin >> playerName;
            cout << "Enter player style (LHS/RHS): ";
            cin >> playerStyle;
            cout << "Enter player's age: ";
            cin >> playerAge;

            playerFile << i << ". " << playerName << "                     " << playerStyle << "            " << playerAge << "\n";
        }
        playerFile.close();
    }
}

