class Hotel
{
    string *customerFirstName[100], *customerLastName[100];
    int totalIncome, singleRoomCount, doubleRoomCount;

    enum RoomStatus {
        Empty, Occupied
    } rooms[45];

public:
    Hotel();
    void manageRooms();
    void reserveRoom();
    void releaseRoom();
    void countOccupiedRooms();
    void querySingleRooms();
    void queryPresentationRooms();
    void displayIncome();
};

Hotel::Hotel()
{
    singleRoomCount = 0;
    doubleRoomCount = 0;
    totalIncome = 0;

    manageRooms();
}

void Hotel::manageRooms()
{
    for (int i = 1; i < 46; i++)
        rooms[i] = Empty;

    int choice;

    do {
        cout << "\n\t\t--- Altıntepe Hotel ---" << endl;
        cout << "\t\t1. Room Reservation" << endl;
        cout << "\t\t2. Release Room" << endl;
        cout << "\t\t3. Count Occupied Rooms" << endl;
        cout << "\t\t4. Query Single Rooms" << endl;
        cout << "\t\t5. Query Presentation Rooms" << endl;
        cout << "\t\t6. Daily Total Income" << endl;
        cout << "\t\t7. Exit" << endl;
        cout << "Enter your choice number: ";
        cin >> choice;

        switch (choice) {
            case 1: reserveRoom(); break;
            case 2: releaseRoom(); break;
            case 3: countOccupiedRooms(); break;
            case 4: querySingleRooms(); break;
            case 5: queryPresentationRooms(); break;
            case 6: displayIncome(); break;
            case 7: exit(1);
            default: cout << "\nInvalid number entered. Please try again: " << endl;
        }
    } while (choice != 7);
}

void Hotel::reserveRoom()
{
    int roomType, roomIndex, i = 1, j = 6, k = 16;
    string firstName, lastName;

    cout << "\n\t\t- Select Room Type -" << endl;
    cout << "\t\t1. Single Room (50₺)" << endl;
    cout << "\t\t2. Double Room (70₺)" << endl;
    cout << "\t\t3. Presentation Room (300₺)" << endl;
    cin >> roomType;

    switch (roomType) {
        case 1:
            for (; j < 16; j++) {
                if (rooms[j] != Occupied) {
                    rooms[j] = Occupied;
                    cout << "Your First Name: ";
                    cin >> firstName;
                    cout << "Your Last Name: ";
                    cin >> lastName;
                    cout << "Number of Days: ";
                    cin >> roomIndex;
                    totalIncome += roomIndex * 50;
                    doubleRoomCount++;
                    customerFirstName[j] = new string;
                    *customerFirstName[j] = firstName;
                    customerLastName[j] = new string;
                    *customerLastName[j] = lastName;
                    break;
                }
            }
            if (j == 16)
                cout << "Unfortunately, all single rooms are occupied." << endl;
            break;
        case 2:
            for (; k < 46; k++) {
                if (rooms[k] != Occupied) {
                    rooms[k] = Occupied;
                    cout << "Your First Name: ";
                    cin >> firstName;
                    cout << "Your Last Name: ";
                    cin >> lastName;
                    cout << "Number of Days: ";
                    cin >> roomIndex;
                    totalIncome += roomIndex * 70;
                    doubleRoomCount++;
                    customerFirstName[j] = new string;
                    *customerFirstName[j] = firstName;
                    customerLastName[j] = new string;
                    *customerLastName[j] = lastName;
                    break;
                }
            }
            if (k == 46)
                cout << "Unfortunately, all rooms are occupied." << endl;
            break;
        case 3:
            for (; i < 6; i++) {
                if (rooms[i] != Occupied) {
                    rooms[i] = Occupied;
                    cout << "Your First Name: ";
                    cin >> firstName;
                    cout << "Your Last Name: ";
                    cin >> lastName;
                    cout << "Number of Days: ";
                    cin >> roomIndex;
                    totalIncome += roomIndex * 300;
                    singleRoomCount++;
                    customerFirstName[j] = new string;
                    *customerFirstName[j] = firstName;
                    customerLastName[j] = new string;
                    *customerLastName[j] = lastName;
                    break;
                }
            }
            if (i == 6)
                cout << "Unfortunately, all presentation rooms are occupied." << endl;
            break;
