{
    cout << "Room number to release: ";
    int roomNumber;
    cin >> roomNumber;

    if (rooms[roomNumber] == Occupied) {
        if (roomNumber > 0 && roomNumber < 6) {
            rooms[roomNumber] = Empty;
            delete customerFirstName[roomNumber];
            delete customerLastName[roomNumber];
            singleRoomCount--;
            cout << "The specified room has been released." << endl;
        } else if (roomNumber > 5 && roomNumber < 14) {
            rooms[roomNumber] = Empty;
            delete customerFirstName[roomNumber];
            delete customerLastName[roomNumber];
            doubleRoomCount--;
            cout << "The specified room has been released." << endl;
        }
    } else {
        cout << "Please enter the correct room number.\n" << endl;
    }
}

