using namespace std;

class Grade {
public:
    int value = 0;
    string courseName = "";

    // Constructor to initialize grade value and course name
    Grade(int gradeValue, string course) {
        this->value = gradeValue;
        this->courseName = course;
    }

    // Default constructor
    Grade() {}
};

class Faculty {
public:
    string address = "";
    char name[100] = "";

    // Constructor to initialize faculty address and name
    Faculty(string addr, const char* name) {
        this->address = addr;
        strcpy_s(this->name, sizeof(this->name), name);
        this->name[sizeof(this->name) - 1] = '\0';
    }

    // Default constructor
    Faculty() {}
};

// Represents a student with associated grades and faculty
class Student {
    string name = "";
    int age = 0;
    Faculty faculty;
    Grade* grades = nullptr; // Pointer to dynamically allocated grades
    int gradeCount = 0;

public:
    // Constructor initializing student with name, age, and default faculty
    Student(string studentName, int studentAge) : faculty("CSIE", "Calea Dorobanti 15-17") {
        this->name = studentName;
        this->age = studentAge;
    }

    // Constructor initializing student with name, age, and grades
    Student(string studentName, int studentAge, Grade* gradesArray, int gradeCount) {
        this->name = studentName;
        this->age = studentAge;
        this->setGrades(gradesArray, gradeCount);
    }

    // Constructor initializing student with name, age, grades, and specific faculty
    Student(string studentName, int studentAge, Grade* gradesArray, int gradeCount, Faculty faculty) {
        this->name = studentName;
        this->age = studentAge;
        this->setGrades(gradesArray, gradeCount);
        this->faculty = faculty; // Using assignment operator from Faculty
    }

    // Set grades for the student
    void setGrades(Grade* gradesArray, int gradeCount) {
        if (gradesArray) {
            if (this->grades) {
                delete[] this->grades;
            }
            this->grades = new Grade[gradeCount];
            for (int i = 0; i < gradeCount; i++) {
                this->grades[i] = gradesArray[i];
            }
            this->gradeCount = gradeCount;
        }
    }

    // Copy constructor
    Student(const Student& other) {
        this->name = other.name;
        this->age = other.age;
        this->faculty = other.faculty;
        this->setGrades(other.grades, other.gradeCount);
    }

    // Destructor to clean up dynamically allocated memory
    ~Student() {
        if (this->grades) {
            delete[] this->grades;
        }
    }

    // Assignment operator
    void operator=(const Student& other) {
        if (this != &other) {
            this->name = other.name;
            this->age = other.age;
            this->faculty = other.faculty;
            this->setGrades(other.grades, other.gradeCount);
        }
    }

    friend void operator<<(ostream& console, Student& student);
    friend void operator<<(ofstream& file, Student& student);
};

// Overloaded output operator for Grade
void operator<<(ostream& console, Grade& grade) {
    console << endl << " Grade for " << grade.courseName << " is " << grade.value;
}

// Overloaded output operator for Faculty
void operator<<(ostream& console, Faculty& faculty) {
    console << endl << " Faculty " << faculty.name << "( " << faculty.address << " )";
}

// Overloaded output operator for Student
void operator<<(ostream& console, Student& student) {
    console << endl << " Name " << student.name << " has the age " << student.age;
    console << endl << student.faculty;
    if (student.gradeCount > 0) {
        for (int i = 0; i < student.gradeCount; i++) {
            console << student.grades[i];
        }
    }
}

// Overloaded output operator for writing Student to file
void operator<<(ofstream& file, Student& student) {
    file << endl << " Name " << student.name;
    file << endl << " Age " << student.age;
    file << endl << student.faculty;
    if (student.gradeCount > 0) {
        file << endl << " Grades: ";
        for (int i = 0; i < student.gradeCount; i++) {
            file << student.grades[i];
        }
    }
}

