		if (strlen(newFaculty) <= maxFacultySize) {
			strcpy_s(faculty, maxFacultySize + 1, newFaculty);
		} else {
			throw FacultyNameException();
		}
	}

	// Mutator method for setting the group number
	void setGroupNumber(int newGroupNumber) {
		if (newGroupNumber > 0 && newGroupNumber < 9999) {
			groupNumber = newGroupNumber;
		} else {
			throw GroupNumberException();
		}
	}

	// Method for updating the grade at a specific index
	void setGrade(int newGrade, int index) {
		if (newGrade < MIN_GRADE || newGrade > MAX_GRADE) {
			throw GradeValueException();
		}

		if (index >= noGrades || index < 0) {
			throw GradeValueException();
		}

		grades[index] = newGrade;
	}

	// Default constructor initializing with default values
	Student() {
		id = 90;
		groupNumber = 200;
		strcpy(faculty, "MAN");
	}

	// Constructor with parameters for custom initialization
	Student(char* facultyName, int groupNo, int studentId) {
		id = studentId;
		setGroupNumber(groupNo);
		strcpy(faculty, facultyName);
	}
