        gradeCount = count;

        // Prevent memory leak by deleting existing grades
        if (grades != nullptr) {
            delete[] grades;
        }

        // Allocate memory for new grades and perform deep copy
        grades = new int[count];
        for (int i = 0; i < count; i++) {
            grades[i] = studentGrades[i];
        }
