class Student {
    int studentId;
    char gender;
    float bacAverage;
    bool isOlympic;
    StudentType studentType;
    int credits[10]; // Credits from voluntary activities
    int creditCount;
    int* grades = nullptr;
    int gradeCount;
    string firstName;
    char lastName[100];
    char* faculty = nullptr;

public:
    Student(int id, char gen, float average, bool olympic, StudentType type,
            int* creditsArray, int creditCount, int* gradesArray, int gradeCount,
            string firstName, const char* lastName, const char* faculty) {
        this->studentId = id;
        this->gender = gen;
        this->bacAverage = average;
        this->isOlympic = olympic;
        this->studentType = type;

        for (int i = 0; i < creditCount; i++)
            this->credits[i] = creditsArray[i];
        this->creditCount = creditCount;

        this->grades = new int[gradeCount];
        for (int i = 0; i < gradeCount; i++)
            this->grades[i] = gradesArray[i];
        this->gradeCount = gradeCount;

        this->firstName = firstName;
        strcpy(this->lastName, lastName);
        this->faculty = new char[strlen(faculty) + 1];
        strcpy(this->faculty, faculty);
    }

    Student() {}

    // Writes student data to a binary file
    void writeToBinaryFile(ofstream& binaryFile) {
        binaryFile.write((char*)&this->studentId, sizeof(int));
        binaryFile.write(&this->gender, sizeof(char));
        binaryFile.write((char*)&this->bacAverage, sizeof(float));
        binaryFile.write((char*)&this->isOlympic, sizeof(bool));
        binaryFile.write((char*)&this->studentType, sizeof(StudentType));
        binaryFile.write((char*)&this->creditCount, sizeof(int));
        binaryFile.write((char*)this->credits, sizeof(int) * this->creditCount);
        binaryFile.write((char*)&this->gradeCount, sizeof(int));

        for (int i = 0; i < this->gradeCount; i++) {
            binaryFile.write((char*)&this->grades[i], sizeof(int));
        }

        int nameLengthWithTerminator = this->firstName.size() + 1;
        binaryFile.write((char*)&nameLengthWithTerminator, sizeof(int));
        binaryFile.write(this->firstName.c_str(), nameLengthWithTerminator * sizeof(char));

        binaryFile.write(this->lastName, sizeof(this->lastName));

        char buffer[100];
        strcpy(buffer, this->faculty);
        binaryFile.write(buffer, sizeof(buffer));
    }

    // Reads student data from a binary file
    void readFromBinaryFile(ifstream& binaryFile) {
        binaryFile.read((char*)&this->studentId, sizeof(int));
        binaryFile.read(&this->gender, sizeof(char));
        binaryFile.read((char*)&this->bacAverage, sizeof(float));
        binaryFile.read((char*)&this->isOlympic, sizeof(bool));
        binaryFile.read((char*)&this->studentType, sizeof(StudentType));
        binaryFile.read((char*)&this->creditCount, sizeof(int));
        binaryFile.read((char*)this->credits, sizeof(int) * this->creditCount);
        binaryFile.read((char*)&this->gradeCount, sizeof(int));

        if (this->grades != nullptr)
            delete[] this->grades;
        this->grades = new int[this->gradeCount];

        for (int i = 0; i < this->gradeCount; i++) {
            binaryFile.read((char*)&this->grades[i], sizeof(int));
        }

        int nameLengthWithTerminator;
        binaryFile.read((char*)&nameLengthWithTerminator, sizeof(int));
        char nameBuffer[100];
        binaryFile.read(nameBuffer, nameLengthWithTerminator * sizeof(char));
        this->firstName = string(nameBuffer);

        binaryFile.read(this->lastName, sizeof(this->lastName));

        char facultyBuffer[100];
        binaryFile.read(facultyBuffer, sizeof(facultyBuffer));

        if (this->faculty != nullptr)
            delete[] this->faculty;
        this->faculty = new char[strlen(facultyBuffer) + 1];
        strcpy(this->faculty, facultyBuffer);
    }

    friend ostream& operator<<(ostream& out, Student& student);
};

ostream& operator<<(ostream& out, Student& student) {
    out << endl << student.studentId << " | " << student.firstName << " | " << student.lastName << " | " << student.faculty;
    out << endl << "Is Olympic: " << student.isOlympic;
    out << endl << "Student Type: " << student.studentType;
    out << endl << "Grades: ";
    for (int i = 0; i < student.gradeCount; i++)
