#include <iostream>
#include <string>
using namespace std;

class Message {
    int priority = 0;
    string content = "";
public:
    // Constructor with parameters to initialize priority and content
    Message(int priorityValue, string messageContent) {
        this->priority = priorityValue;
        this->content = messageContent;
    }

    // Default constructor initializes priority to 0 and content to an empty string
    Message() {
        this->priority = 0;
        this->content = "";
    }

    string getContent() const {
        return this->content;
    }

    int getPriority() const {
        return this->priority;
    }

    // Overloaded assignment operator for Message
    Message& operator=(const Message& otherMessage) {
        this->priority = otherMessage.priority;
        this->content = otherMessage.content;
        return *this;
    }

    // Overloaded addition operator for Message and string
    Message operator+(const string& additionalContent) const {
        Message result = *this;
        result.content += additionalContent;
        return result;
    }

    // Overloaded addition operator for Message and Message
    Message operator+(const Message& otherMessage) const {
        Message result = *this;
        result.content += otherMessage.content;
        return result;
    }

    // Overloaded assignment operator for string
    void operator=(const string& newContent) {
        this->content = newContent;
    }

    // Overloaded compound assignment operator for Message and string
    void operator+=(const string& additionalContent) {
        this->content += additionalContent;
    }

    // Overloaded compound assignment operator for Message and int
    void operator*=(int repetitions) {
        *this = repetitions * (*this);
    }

    // Overloaded post-increment operator
    Message operator++(int) {
        Message copy = *this;
        this->priority += 1;
        return copy;
    }

    // Overloaded pre-increment operator
    Message operator++() {
        this->priority += 1;
        return *this;
    }

    // Overloaded logical NOT operator to check content length
    bool operator!() const {
        return this->content.size() > 5;
    }

    // Overloaded function call operator to append a message multiple times
    Message operator()(const string& message, int repetitions) const {
        Message result = *this;
        for (int i = 0; i < repetitions; i++) {
            result.content += message;
        }
        return result;
    }

    // Overloaded function call operator to extract a substring (to be implemented)
    Message operator()(int startIndex, int endIndex) const {
        Message result = *this;
        // TODO: Extract substring logic
        return result;
    }

    // Overloaded subscript operator for read/write access to content
    char& operator[](int index) {
        if (index >= 0 && index < this->content.size())
            return this->content[index];
        else
            throw out_of_range("Index is out of range");
    }

    // Overloaded cast operator to convert Message to int (priority)
    explicit operator int() const {
        return this->priority;
    }

    // Friend functions for additional operator overloads
    friend Message operator+(const string& message, const Message& msg);
    friend Message operator*(int repetitions, const Message& msg);
};

// Overloaded output stream operator for Message
ostream& operator<<(ostream& output, const Message& msg) {
    output << endl << msg.getPriority() << " - " << msg.getContent();
    return output;
}

// Overloaded addition operator for string and Message
Message operator+(const string& message, const Message& msg) {
    Message result = msg;
    result.content = message + result.content;
    return result;
}

// Overloaded multiplication operator for int and Message
Message operator*(int repetitions, const Message& msg) {
    Message result = msg;
    string initialContent = result.getContent();
    result.content = "";
    for (int i = 0; i < repetitions; i++) {
        result.content += initialContent;
    }
    return result;
}

int main() {
    Message message1(1, "Hello!");

    cout << message1;

    // Copy constructor
    Message message2 = message1;

    Message message3(10, "Operator demonstration");

    cout << message3 << message2;

    // Assignment operator
    message3 = message1 = message2;

    // Alternative assignment
    message3 = message2;
    message1 = message2;

    cout << message3;

    // Binary operators demonstration
    cout << endl << " ---------------------- Binary Operators";
    cout << message1;

    message2 = message1 + " completion";

    cout << message1;
    cout << message2;

    Message message4;
    message3 = " I forgot to add " + message2;
    message4 = message2 + message3;

    cout << message3;
    cout << message4;

    // Assignment operator
    message2 = "Hello ";

    cout << endl << message2;
    message1 = 3 * message2;
    cout << message1;

    // Compound assignment operators demonstration
    cout << endl << " ---------------------- Compound Assignment Operators";
    message1 = "Test";
    message2 = "Hi ";

    message1 += " operators";
    message2 *= 4;

    cout << message1;
    cout << message2;

    // Unary operators demonstration
    int var1 = 10;
    int var2 = var1++;
    int var3 = ++var1;

    cout << endl << " ---------------------- Unary Operators";
    cout << endl << var1 << " " << var2 << " " << var3;

    Message message5(20, "Important message");
    message1 = message5++;
    cout << message1;
    cout << message5;
    message2 = ++message5;
    cout << message2;
    cout << message5;

    // Special operators demonstration
    cout << endl << " ---------------------- Special Operators";
    message1 = "A long text";

    if (!message1)
        cout << endl << "Text has more than 5 characters";
    else
        cout << endl << "Text has at most 5 characters";

    // Function call operator for substring extraction
    message2 = message1(2, 6);
