void CriminalRecord::saveRecord() {
    ofstream outputFile("CBI", ios::app);
    inputRecord();
    outputFile.write(reinterpret_cast<char*>(&record), sizeof(record));
    outputFile.close();
}

void CriminalRecord::readRecords() {
    ifstream inputFile("CBI");
    inputFile.seekg(0, ios::beg);
    inputFile.read(reinterpret_cast<char*>(&record), sizeof(record));

    while (inputFile) {
        displayRecord();
        inputFile.read(reinterpret_cast<char*>(&record), sizeof(record));
    }
    inputFile.close();
}

void CriminalRecord::searchRecord() {
    char searchName[20];
    ifstream inputFile("CBI");
    cout << "Enter name of student to search: ";
    cin >> searchName;
    inputFile.seekg(0, ios::beg);
    inputFile.read(reinterpret_cast<char*>(&record), sizeof(record));

    while (inputFile) {
        if (strcasecmp(searchName, studentName) == 0) {
            displayRecord();
        }
        inputFile.read(reinterpret_cast<char*>(&record), sizeof(record));
    }
    inputFile.close();
}

void CriminalRecord::deleteRecord() {
    char deleteName[20];
    ifstream inputFile("CBI");
    ofstream tempFile("temp", ios::app);
    cout << "Enter the name of the student whose records you want to delete: ";
    cin >> deleteName;
    inputFile.seekg(0, ios::beg);
    inputFile.read(reinterpret_cast<char*>(&record), sizeof(record));

    while (inputFile) {
        if (strcasecmp(deleteName, studentName) != 0) {
            tempFile.write(reinterpret_cast<char*>(&record), sizeof(record));
        }
        inputFile.read(reinterpret_cast<char*>(&record), sizeof(record));
    }
    inputFile.close();
    tempFile.close();
    remove("CBI");
    rename("temp", "CBI");
}

void CriminalRecord::modifyRecord() {
    char modifyName[20];
    int option;
    cout << "\nEnter name of student whose record you want to modify: ";
    cin >> modifyName;
    fstream file("CBI", ios::in | ios::out);
    file.seekg(0, ios::beg);
    file.read(reinterpret_cast<char*>(&record), sizeof(record));
    int position = file.tellg();

    while (!file.eof()) {
        if (strcasecmp(modifyName, studentName) == 0) {
            cout << "\nPress 1 to change name\nPress 2 to change class\nPress 3 to change section\nPress 4 to change admission number\nPress 5 to change DOB\nPress 6 to change father's name\nPress 7 to change address\nPress 8 to change course\n";
            cin >> option;
            switch (option) {
                case 1: cin >> studentName; break;
                case 2: cin >> studentClass; break;
                case 3: cin >> studentSection; break;
                case 4: cin >> admissionNumber; break;
                case 5: cin >> dateOfBirth; break;
                case 6: cin >> fatherName; break;
                case 7: cin >> address; break;
                case 8: cin >> course; break;
            }
            file.seekg(position - sizeof(record), ios::beg);
            file.write(reinterpret_cast<char*>(&record), sizeof(record));
        }
        file.read(reinterpret_cast<char*>(&record), sizeof(record));
        position = file.tellg();
    }
    file.close();
}

