		path.setDx(velocityX);
		path.setDy(velocityY);
		path.setWrap(shouldWrap);
	}

	// Initializes a movable object at specified coordinates
	Moveable(int initialX, int initialY, double velocityX, double velocityY, bool shouldWrap, int objectX, int objectY) 
		: path(objectX, objectY)
	{
		path.setX(static_cast<double>(initialX));
		path.setY(static_cast<double>(initialY));
		path.setDx(velocityX);
		path.setDy(velocityY);
		path.setWrap(shouldWrap);
	}

	~Moveable() {}

	int getX() const { return static_cast<int>(path.getX()); }
	int getY() const { return static_cast<int>(path.getY()); }
	double getDX() const { return path.getDx(); }
	double getDY() const { return path.getDy(); }

	void setPosition(int x, int y) { 
		path.setX(static_cast<double>(x)); 
		path.setY(static_cast<double>(y)); 
	}

	void setChange(double dx, double dy) { 
		path.setDx(dx); 
		path.setDy(dy); 
	}

	virtual void draw() = 0; // Abstract method for rendering the object
	void move() { path++; } // Updates the object's position based on its path
	Path& getPath() { return path; }
	virtual bool isReadyToDie() { return path.isDead(); } // Checks if the object is marked for removal

protected:
	Path path; // Represents the movement path of the object
};

