#define _USE_MATH_DEFINES
#include <cmath>      // for M_PI, sin() and cos()
#include <iostream>   // for ISTREAM and OSTREAM
#include "point.h"

#define DEGREE_TO_RADIAN(value) ((double)((M_PI / 180.0) * (value)))
#define RADIAN_TO_DEGREE(value) ((double)((value) * (180.0 / M_PI)))

/*******************************************
 * Path
 * Represents a point in motion with angle and magnitude
 ******************************************/
class Path : public Point
{
public:
   // Constructors for initializing Path objects
   Path(int initialX, int initialY) : Point(initialX, initialY), deltaX(0.0), deltaY(0.0) { }
   Path(const Path &source) { *this = source; }
   Path(const Point &source) : deltaX(0.0), deltaY(0.0) { *this = source; }

   // Accessor methods
   Point getPoint() const;
   double getDeltaX() const { return deltaX; }
   double getDeltaY() const { return deltaY; }
   double getMagnitude() const { return sqrt(deltaX * deltaX + deltaY * deltaY); }
   double getAngle() const { return RADIAN_TO_DEGREE(atan2(-deltaY, deltaX)); }

   // Mutator methods
   void setDeltaX(double deltaX) { this->deltaX = deltaX; }
   void setDeltaY(double deltaY) { this->deltaY = deltaY; }
   void setMagnitude(double magnitude);
   void setAngle(double angle);
   void setVelocity(double angleDegrees, double speed);

   // Arithmetic operations
   Path operator++(int postfix);
   Path& operator++();       
   double operator-(const Path &rhs) const;   // Calculate minimum distance
   Path operator+(const Path &rhs) const;      // Perform Path addition
   Path& operator+=(const Path &rhs);

   // Comparison operation
   bool operator==(const Path &rhs);

   // Assignment operations
   const Path& operator=(const Path &rhs);
   const Path& operator=(const Point &rhs);

private:
   double deltaX; // Change in X direction
   double deltaY; // Change in Y direction
};

// Stream operators for debugging
std::ostream& operator<<(std::ostream &out, const Path &path);
std::istream& operator>>(std::istream &in, Path &path);

