// Represents a position on the screen with associated bounds
class Point
{
public:
   // Constructors for initializing Point instances
   Point(int objX, int objY) 
       : x(0.0), y(0.0), check(true), dead(false), wrap(false), objectX(objX), objectY(objY) {}
   Point() 
       : x(0.0), y(0.0), check(true), dead(false), wrap(false), objectX(0), objectY(0) {}
   Point(bool isCheck) 
       : x(0.0), y(0.0), check(isCheck), dead(false), wrap(false) {}
   Point(double posX, double posY);
   Point(const Point & other) { *this = other; }

   // Accessor methods for retrieving Point attributes
   double getX() const { return x; }
   double getY() const { return y; }
   bool isCheckEnabled() const { return check; }
   bool isDead() const { return dead; }
   double getXMin() const { return xMin; }
   double getXMax() const { return xMax; }
   double getYMin() const { return yMin; }
   double getYMax() const { return yMax; }
   bool isWrapEnabled() const { return wrap; }

   // Mutator methods for modifying Point attributes
   void setX(double posX);
   void setY(double posY);
   void incrementX(double deltaX) { setX(getX() + deltaX); }
   void incrementY(double deltaY) { setY(getY() + deltaY); }
   void setCheck(bool isEnabled) { check = isEnabled; }
   void setWrap(bool isEnabled) { wrap = isEnabled; }
   void markAsDead() { dead = true; }
   void revive() { dead = false; }
   const Point & operator=(const Point & rhs);

   static double xMin; // Minimum extent of the x position
   static double xMax; // Maximum extent of the x position
   static double yMin; // Minimum extent of the y position
   static double yMax; // Maximum extent of the y position

private:
   double x;           // Horizontal position
   double y;           // Vertical position
   bool check;        // Flag for bounds checking
   bool dead;         // Flag indicating if the point is out of bounds
   bool wrap;         // Flag indicating if wrapping around edges is enabled
   int objectX;       // Object's x-coordinate
   int objectY;       // Object's y-coordinate
};

