#define NAME_SIZE 50
#define MAX_BOOKS 5

using namespace std;

class Book {
    char title[NAME_SIZE];
    char author[NAME_SIZE];
    char currentUser[NAME_SIZE];
    bool isAvailable;

public:
    Book(const char* bookTitle) {
        strncpy(title, bookTitle, strlen(bookTitle));
        author[0] = '\0';
        isAvailable = true;
        currentUser[0] = '\0';
    }

    Book(const char* bookTitle, const char* bookAuthor) {
        strncpy(title, bookTitle, strlen(bookTitle));
        strncpy(author, bookAuthor, strlen(bookAuthor));
        isAvailable = true;
        currentUser[0] = '\0';
    }

    const char* getTitle() const {
        return title;
    }

    bool checkAvailability() const {
        return isAvailable;
    }

    void updateAvailability(bool availability) {
        isAvailable = availability;
    }

    void assignCurrentUser(const char* user) {
        strncpy(currentUser, user, strlen(user));
        isAvailable = false;
    }

    const char* getCurrentUser() const {
        return currentUser;
    }
};

class User {
    char name[NAME_SIZE];
    int issuedBooksCount;
    int maxBooksAllowed;

public:
    User(const char* userName) {
        strncpy(name, userName, strlen(userName));
        issuedBooksCount = 0;
        maxBooksAllowed = MAX_BOOKS;
    }

    const char* getName() const {
        return name;
    }

    void issueNewBook() {
        issuedBooksCount++;
    }

    void returnBook() {
        issuedBooksCount--;
    }

    bool isAllowedToBorrow() const {
        return (issuedBooksCount < maxBooksAllowed);
    }

    void setBorrowLimit(int limit) {
        maxBooksAllowed = limit;
    }
};

class BookStore {
    set<Book*> books;
    set<User*> users;

public:
    BookStore() = default;

    void addBook(const char* bookName) {
        Book* newBook = new Book(bookName);
        books.insert(newBook);
    }

    void addUser(const char* userName) {
        User* newUser = new User(userName);
        users.insert(newUser);
    }

    void lendBook(const char* bookName, const char* userName);
    void returnBook(const char* bookName);
    void setUserBorrowLimit(const char* userName, int totalBooks);
    void searchBook(const char* bookName) const;
    void searchUser(const char* userName) const;

private:
    Book* findBook(const char* bookName) const;
    User* findUser(const char* userName) const;
};

void BookStore::searchUser(const char* userName) const {
    User* user = findUser(userName);
    if (user) {
        cout << "User has been found." << endl;
    } else {
        cout << "No user found with name: " << userName << endl;
    }
}

void BookStore::searchBook(const char* bookName) const {
    Book* book = findBook(bookName);
    if (book) {
        cout << "Book has been found in the library." << endl;
    } else {
        cout << "No book found with name: " << bookName << endl;
    }
}

void BookStore::setUserBorrowLimit(const char* userName, int totalBooks) {
    User* user = findUser(userName);
    if (user) {
        user->setBorrowLimit(totalBooks);
    }
}

void BookStore::lendBook(const char* bookName, const char* userName) {
    User* user = findUser(userName);
    if (!user) {
        cout << "Invalid user name." << endl;
        return;
    }

    if (!user->isAllowedToBorrow()) {
        cout << "No more books can be issued to this user." << endl;
        return;
    }

    Book* book = findBook(bookName);
    if (!book) {
        cout << "Invalid book name." << endl;
        return;
    }

    if (book->checkAvailability()) {
        book->assignCurrentUser(userName);
        user->issueNewBook();
    } else {
        cout << "This book has already been issued." << endl;
    }
}

void BookStore::returnBook(const char* bookName) {
    Book* book = findBook(bookName);
    if (!book) {
        cout << "Invalid book name." << endl;
        return;
    }

    if (book->checkAvailability()) {
        cout << "This book is not issued to anyone." << endl;
        return;
    }

    const char* userName = book->getCurrentUser();
    book->updateAvailability(true);

    User* user = findUser(userName);
    if (user) {
        user->returnBook();
    }
}

Book* BookStore::findBook(const char* bookName) const {
    for (const auto& book : books) {
        if (strcmp(book->getTitle(), bookName) == 0) {
            return book;
        }
    }
    return nullptr;
}

User* BookStore::findUser(const char* userName) const {
    for (const auto& user : users) {
        if (strcmp(user->getName(), userName) == 0) {
            return user;
        }
    }
    return nullptr;
}

int main() {
    BookStore bookstore;
    char choice;
    char bookName[NAME_SIZE];
    char userName[NAME_SIZE];
    int totalBooks;

    cout << "Please choose one of the following options:" << endl;
    cout << "1. Add books to the library." << endl;
    cout << "2. Add users to the library." << endl;
    cout << "3. Lend books to users." << endl;
    cout << "4. Return books to the library." << endl;
    cout << "5. Limit the number of books borrowed by a user." << endl;
    cout << "6. Search for a book by title." << endl;
    cout << "7. Search for a user by name." << endl;
    cout << "9. Exit." << endl;

    while (true) {
        cin >> choice;
        switch (choice) {
            case '1':
                cin >> bookName;
                bookstore.addBook(bookName);
                break;
            case '2':
                cin >> userName;
                bookstore.addUser(userName);
                break;
            case '3':
                cin >> bookName >> userName;
                bookstore.lendBook(bookName, userName);
                break;
            case '4':
                cin >> bookName;
                bookstore.returnBook(bookName);
                break;
            case '5':
                cin >> userName >> totalBooks;
                bookstore.setUserBorrowLimit(userName, totalBooks);
                break;
            case '6':
                cin >> bookName;
                bookstore.searchBook(bookName);
                break;
            case '7':
                cin >> userName;
                bookstore.searchUser(userName);
                break;
            case '9':
                return 0;
            default:
                cout << "Invalid choice. Please try again." << endl;
        }
    }
}

