int Bank::retrieveBankId() {
    ifstream inputFile("account.txt", ios::in);
    Bank tempAccount;
    int id = 0;

    if (!inputFile) {
        return id++;
    } else {
        inputFile.read(reinterpret_cast<char*>(&tempAccount), sizeof(tempAccount));
        while (!inputFile.eof()) {
            id = tempAccount.bankId;
            inputFile.read(reinterpret_cast<char*>(&tempAccount), sizeof(tempAccount));
        }
        id++;
        return id;
    }
}

