        inputFile.read(reinterpret_cast<char*>(this), sizeof(*this));
        while (!inputFile.eof()) {
            if (strcmp(this->firstName, searchName) == 0) {
                displayHeader();
                displayDetails();
                break;
            }
            inputFile.read(reinterpret_cast<char*>(this), sizeof(*this));
        }

        if (inputFile.eof()) {
            cout << "Record not found" << endl;
        }
    }
    inputFile.close();
}

void Bank::updateAccount() {
    int id, recordIndex = 0;
    fstream file("account.txt", ios::in | ios::out | ios::binary | ios::ate);
    cout << "Enter the bank ID to update: ";
    cin >> id;

    if (!file) {
        cout << "File not found" << endl;
    } else {
        file.seekg(0);
        file.read(reinterpret_cast<char*>(this), sizeof(*this));
        while (!file.eof()) {
            recordIndex++;
            if (this->bankId == id) {
                displayHeader();
                displayDetails();
                cout << endl << "Re-enter the details" << endl;
                inputDetails();
                file.seekp((recordIndex - 1) * sizeof(Bank), ios::beg);
                file.write(reinterpret_cast<char*>(this), sizeof(*this));
                break;
            }
            file.read(reinterpret_cast<char*>(this), sizeof(*this));
        }

        if (file.eof()) {
            cout << "Record not found" << endl;
        }
    }
    file.close();
}

void Bank::deleteAccount() {
    ifstream inputFile("account.txt", ios::in | ios::binary);
    ofstream outputFile("deletedAccount.txt", ios::out | ios::app | ios::binary);
    int id;
    char confirmation[1];

    cout << "Enter the bank ID you want to delete: ";
    cin >> id;

    if (!inputFile) {
        cout << "File not found" << endl;
    } else {
        inputFile.read(reinterpret_cast<char*>(this), sizeof(*this));
        while (!inputFile.eof()) {
            if (this->bankId == id) {
                cout << "Record to delete:" << endl;
                displayHeader();
                displayDetails();
                cout << "Are you sure you want to delete? [Y/N]: ";
                cin >> confirmation;

                if (confirmation[0] == 'n' || confirmation[0] == 'N') {
                    outputFile.write(reinterpret_cast<char*>(this), sizeof(*this));
                } else {
                    cout << endl << "Record deleted" << endl;
                }
            } else {
                outputFile.write(reinterpret_cast<char*>(this), sizeof(*this));
            }
            inputFile.read(reinterpret_cast<char*>(this), sizeof(*this));
        }
        inputFile.close();
        outputFile.close();
        system("erase account.txt");
        system("rename deletedAccount.txt account.txt");
    }
}

int displayMenu() {
    system("clear");
    int choice;
    cout << "1. Create Bank Account" << endl;
    cout << "2. View All Accounts" << endl;
    cout << "3. Search Accounts" << endl;
    cout << "4. Update Bank Account" << endl;
    cout << "5. Delete Bank Account" << endl;
    cout << "6. Exit" << endl;
    cout << "Enter your choice: ";
    cin >> choice;
    return choice;
}

int main() {
    Bank bankAccount;
    int choice;

    choice = displayMenu();
    system("clear");
    switch (choice) {
        case 1:
            bankAccount.inputDetails();
            bankAccount.addAccount();
            break;
        case 2:
            bankAccount.displayAccounts();
            break;
        case 3:
            bankAccount.searchAccount();
            break;
        case 4:
            bankAccount.updateAccount();
            break;
        case 5:
            bankAccount.deleteAccount();
            break;
        case 6:
            exit(0);
        default:
            cout << "Enter a valid choice" << endl;
    }

    return 0;
}

