    void initialize_placements() {
        placements = {
            Placement(2018, 10, 42, 1950, 2000),
            Placement(2019, 11, 50, 1700, 1800),
            Placement(2020, 10, 42, 1900, 2200)
        };
    }

    string get_name() const {
        return name;
    }

    void set_name(string college_name) {
        name = college_name;
    }

    void set_location(string college_location) {
        location = college_location;
    }

    void set_students(int total_students) {
        student_count = total_students;
    }

    int get_students() const {
        return student_count;
    }

    string get_location() const {
        return location;
    }

    // Adds new placement statistics based on user input
    void add_placement_stats() {
        double average_salary, highest_package;
        int year, total_placed, total_appeared;

        cout << "Enter the year for placement statistics: ";
        cin >> year;
        cout << "Enter the average salary for year " << year << ": ";
        cin >> average_salary;
        cout << "Enter the highest package offered in year " << year << ": ";
        cin >> highest_package;
        cout << "Enter the total number of candidates placed in year " << year << ": ";
        cin >> total_placed;
        cout << "Enter the total number of candidates appeared in year " << year << ": ";
        cin >> total_appeared;

        placements.emplace_back(year, average_salary, highest_package, total_placed, total_appeared);
    }

    // Deletes placement statistics for a specified year
    void delete_placement_stat() {
        int year;
        cout << "Enter the year for which you want to delete placement statistics: ";
        cin >> year;

        auto it = remove_if(placements.begin(), placements.end(), [year](const Placement& p) {
            return p.year == year;
        });

        if (it != placements.end()) {
            placements.erase(it, placements.end());
            cout << "Deleted placement statistics for the year " << year << " successfully." << endl;
        } else {
            cout << "No placement statistics found for the year " << year << "." << endl;
        }
    }

    // Displays placement statistics for a specified year
    void show_placement_stat() const {
        int year;
        cout << "Enter the year for which you want to see placement statistics: ";
        cin >> year;

        cout << "\n\n\t\t=======================================================================================================\n\n";
        cout << "\t\t\t\t\t\t\t || PLACEMENT STATISTICS ||\n\n";
        cout << "\t\t=======================================================================================================\n\n";

        for (const auto& placement : placements) {
            if (placement.year == year) {
                cout << "\t\tAverage Salary" << "    |    "
                     << "Highest Package Offered" << "    |    "
                     << "Candidates Appeared" << "    |"
                     << "\tCandidates Placed" << "     |\n\n";
                cout << "\t\t-------------------------------------------------------------------------------------------------------\n\n";
                cout << "\t\t" << placement.average << " LPA\t\t\t   "
                     << placement.highest << " LPA\t\t\t "
                     << placement.total_appeared << "\t\t\t    "
                     << placement.total_placed << endl;
                return;
            }
        }
        cout << "No placement statistics found for the year " << year << "." << endl;
    }

    // Adds a new company to the list of companies that have visited the college
    void append_companies() {
        string new_company;
        cout << "Enter the company name: ";
        cin >> new_company;
        companies.push_back(new_company);
        cout << "Successfully added new company to records." << endl;
    }

    // Displays the list of companies that have visited the college
    void show_companies() const {
        cout << "\t\t\t\t\t\t\t|| LIST OF COMPANIES ||\n\n";
        cout << "\t\t\t-------------------------------------------------------------------------------------------------------\n\n";
        int index = 1;
        for (const auto& company : companies) {
            cout << "\t\t\t" << index++ << ". " << company << endl;
        }
    }

    struct CompareByYear {
        bool operator()(const Placement& first, const Placement& second) const {
            return first.year < second.year;
        }
    };

    // Displays the history of placements sorted by year
    void placement_history() const {
        vector<Placement> sorted_placements = placements;
        sort(sorted_placements.begin(), sorted_placements.end(), CompareByYear());

        cout << "\n\t\t\t\t\t      || PLACEMENT HISTORY ||\n\n";
        cout << "\t======================================================================================================================\n\n";
        cout << "\t|  YEAR" << "    |    "
             << "Average Salary" << "    |    "
             << "Highest Package Offered" << "    |    "
             << "Candidates Appeared" << "    |"
             << "\tCandidates Placed" << "     |\n\n";
        cout << "\t-----------------------------------------------------------------------------------------------------------------------\n\n";

        for (const auto& placement : sorted_placements) {
            cout << "\t   " << placement.year << "\t\t  "
                 << placement.average << " LPA\t\t\t  "
                 << placement.highest << " LPA\t\t\t  "
                 << placement.total_appeared << "\t\t\t    "
                 << placement.total_placed << endl;
        }
        cout << endl;
    }

    friend ostream& operator<<(ostream& out, const College& college);
};

