    out << "  Location: " << college.location << endl;
    out << "  Companies that visited: " << college.name << ":\n";

    int serial_number = 1;
    for (const auto& company : college.companies) {
        out << "   " << serial_number++ << ". " << company << endl;
    }
    return out;
}

