class PlacementStatistics
{
    double averagePackage;
    double highestPackage;

    int placementYear;
    int totalPlacedStudents;
    int totalAppearedStudents;

public: 
    PlacementStatistics(int year, double average, int highest, int placed, int appeared)
    {
        averagePackage = average;
        highestPackage = highest;
        placementYear = year;
        totalPlacedStudents = placed;
        totalAppearedStudents = appeared;
    }

    void setAveragePackage(double average)
    {
        averagePackage = average;
    }

    void setHighestPackage(double highest)
    {
        highestPackage = highest;
    }

    void setPlacementYear(int year)
    {
        placementYear = year;
    }

    void setTotalPlacedStudents(int placed)
    {
        totalPlacedStudents = placed;
    }

    void setTotalAppearedStudents(int appeared)
    {
        totalAppearedStudents = appeared;
    }

    double getAveragePackage() const
    {
        return averagePackage;
    }

    double getHighestPackage() const
    {
        return highestPackage;
    }

    int getTotalPlacedStudents() const
    {
        return totalPlacedStudents;
    }

    int getTotalAppearedStudents() const
    {
        return totalAppearedStudents;
    }

    int getPlacementYear() const
    {
        return placementYear;
    }

    // Calculate and display the percentage of students placed
    void displayPlacementPercentage() const
    {
        double percentage = (static_cast<double>(totalPlacedStudents) / totalAppearedStudents) * 100;
