                    std::cout << "\n\t\t\t\t\t\tFine to be Collected = Rs. " << fine << "\n";

                    char* bookName = currentCustomer->borrowedBooks[i].getTitle();
                    for (int j = 0; j < BookCount; ++j) {
                        if (strcmp(bookPointer[j]->getTitle(), bookName) == 0) {
                            ++(bookPointer[j]->availableCopies);
                            break;
                        }
                    }

                    for (int j = i; j < currentCustomer->bookCount; ++j) {
                        currentCustomer->borrowedBooks[j] = currentCustomer->borrowedBooks[j + 1];
                        currentCustomer->issueDates[j] = currentCustomer->issueDates[j + 1];
                        currentCustomer->returnDates[j] = currentCustomer->returnDates[j + 1];
                    }
                    --(currentCustomer->bookCount);
                    break;
                }
            }
            if (i == BookCount) {
                std::cout << "\n\n\t\t\t\t\t\tBook not Found\n";
            }
        } else if (searchChoice == '1') {
            char bookAuthor[25];
            std::cout << "\n\n\t\t\t\t\t\tEnter name of book to search : ";
            std::cin.ignore();
            std::cin.getline(bookAuthor, 25);

            for (int i = 0; i < currentCustomer->bookCount; ++i) {
                if (strcmp(currentCustomer->borrowedBooks[i].getAuthor(), bookAuthor) == 0) {
                    std::cout << "\n\n\t\t\t\t\t\tExpected Return date : " << currentCustomer->returnDates[i] << "\n";
                    Date actualReturnDate;
                    int errorFlag = 1;

                    while (errorFlag == 1) {
                        try {
                            std::cin >> actualReturnDate;
                            errorFlag = 0;
                        } catch (const char* msg) {
                            std::cout << "\n\t\t\t\t\t\tError : " << msg << "\n\n";
                        }
                        if (errorFlag == 0) {
                            int dateDifference = actualReturnDate - currentCustomer->issueDates[currentCustomer->bookCount];
                            if (dateDifference < 0) {
                                std::cout << "\n\t\t\t\t\t\tError : Return date before issue date\n\n";
                                errorFlag = 1;
                            }
                        }
                    }
                    int daysLate = actualReturnDate - currentCustomer->returnDates[i];
                    int fine = 0;

                    if (daysLate < 7) {
                        fine = 0;
                    } else if (daysLate <= 15) {
                        fine = (daysLate - 7) * 1;
                    } else if (daysLate <= 30) {
                        fine = (daysLate - 7) + (daysLate - 15) * 2;
                    } else {
                        fine = (daysLate - 7) + (daysLate - 15) * 2 + (daysLate - 30) * 5;
                    }

                    std::cout << "\n\n\t\t\t\t\t\tDays Late = " << daysLate << "\n";
                    std::cout << "\n\t\t\t\t\t\tFine to be Collected = Rs. " << fine << "\n";

                    for (int j = i; j < currentCustomer->bookCount; ++j) {
                        currentCustomer->borrowedBooks[j] = currentCustomer->borrowedBooks[j + 1];
                        currentCustomer->issueDates[j] = currentCustomer->issueDates[j + 1];
                        currentCustomer->returnDates[j] = currentCustomer->returnDates[j + 1];
                    }
                    --(currentCustomer->bookCount);
                    break;
                }
            }
            if (i == BookCount) {
                std::cout << "\n\n\t\t\t\t\t\tBook not Found\n";
            }
        }
    } else {
        std::cout << "\n\n\t\t\t\t\t\tInvalid Customer ID\n";
    }

    saveCustomerRecords();
    saveBookRecords();
}

