    cout << "\n\n\t\t\t\t\t\tEnter ID of customer to remove: ";
    cin >> customerId;
    bool customerFound = false;

    for (int i = 0; i < Customerct; ++i) {
        if (customer_ptr[i]->getid() == customerId) {
            cout << "\n\n\t\t\t\t\t\tCustomer found and deleted\n";
            customerFound = true;
            for (int j = i + 1; j < Customerct; ++j) {
                copyCustomerData(j - 1, j);
            }
            --Customerct;
            break;
        }
    }
    if (customerFound) {
        writeRecords();
    }
}

