// Main function to manage employee records
int main() {
    Employee currentEmployee, tempEmployee;
    char option, continueChoice;
    char departmentName[50];
    int employeeID, recordFound;

    std::fstream file;
    file.open(fileName, std::ios::ate | std::ios::in | std::ios::out | std::ios::binary);

    do {
        std::cout << "*******Menu********";
        std::cout << "\nEnter your option";
        std::cout << "\n1 => Add a new record";
        std::cout << "\n2 => Search record by employee ID";
        std::cout << "\n3 => List employees in a specific department";
        std::cout << "\n4 => Display all employees";
        std::cout << "\n5 => Update an employee record";
        std::cout << "\n6 => Delete an employee record";
        std::cout << "\n7 => Exit from the program\n";
        std::cout << "********************\n";
        std::cin >> option;

        switch (option) {
            case '1': // Add a new employee record
                currentEmployee.readData();
                file.seekg(0, std::ios::beg);
                recordFound = 0;
                file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));

                while (!file.eof()) {
                    if (tempEmployee.getID() == currentEmployee.getID()) {
                        std::cout << "This ID already exists... Try another ID";
                        recordFound = 1;
                        break;
                    }
                    file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                }

                if (recordFound == 1) break;

                file.clear();
                file.seekp(0, std::ios::end);
                file.write(reinterpret_cast<char*>(&currentEmployee), sizeof(currentEmployee));
                std::cout << "\nNew record has been added successfully...";
                break;

            case '2': // Search for an employee record by ID
                recordFound = 0;
                std::cout << "\nEnter ID of the employee to be searched: ";
                std::cin >> employeeID;
                file.seekg(0, std::ios::beg);
                file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));

                while (!file.eof()) {
                    if (tempEmployee.getID() == employeeID) {
                        std::cout << "\nThe record found....\n";
                        std::cout << std::setw(5) << "ID" 
                                  << std::setw(15) << "Name" 
                                  << std::setw(15) << "Post" 
                                  << std::setw(15) << "Department" 
                                  << std::setw(8) << "Salary";
                        tempEmployee.displayRecord();
                        recordFound = 1;
                        break;
                    }
                    file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                }

                file.clear();
                if (recordFound == 0) {
                    std::cout << "\nData not found for employee ID#" << employeeID;
                }
                break;

            case '3': // List employees in a specific department
                recordFound = 0;
                std::cout << "Enter department name to list employees within it: ";
                std::cin >> departmentName;
                file.seekg(0, std::ios::beg);
                file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));

                while (!file.eof()) {
                    if (strcmp(tempEmployee.getDepartment(), departmentName) == 0) {
                        std::cout << "\nThe record found for this department\n";
                        std::cout << std::setw(5) << "ID" 
                                  << std::setw(15) << "Name" 
                                  << std::setw(15) << "Post" 
                                  << std::setw(15) << "Department" 
                                  << std::setw(8) << "Salary";
                        tempEmployee.displayRecord();
                        recordFound = 1;
                        break;
                    }
                    file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                }

                file.clear();
                if (recordFound == 0) {
                    std::cout << "\nData not found for department " << departmentName;
                }
                break;

            case '4': // Display all employee records
                std::cout << "\nRecord for employees";
                file.clear();
                file.seekg(0, std::ios::beg);
                int recordCounter = 0;
                file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));

                while (!file.eof()) {
                    recordCounter++;
                    if (recordCounter == 1) {
                        std::cout << std::setw(5) << "ID" 
                                  << std::setw(15) << "Name" 
                                  << std::setw(15) << "Post" 
                                  << std::setw(15) << "Department" 
                                  << std::setw(8) << "Salary";
                    }
                    tempEmployee.displayRecord();
                    file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                }
                std::cout << "\n" << recordCounter << " records found......";
                file.clear();
                break;

            case '5': // Update an employee record
                int recordNumber = 0;
                std::cout << "\nFile is being modified....";
                std::cout << "\nEnter employee ID to be updated: ";
                std::cin >> employeeID;
                recordFound = 0;
                file.seekg(0, std::ios::beg);
                file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));

                while (!file.eof()) {
                    recordNumber++;
                    if (tempEmployee.getID() == employeeID) {
                        std::cout << "The old record of employee having ID " << employeeID << " is:";
                        tempEmployee.displayRecord();
                        recordFound = 1;
                        break;
                    }
                    file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                }

                if (recordFound == 0) {
                    std::cout << "\nData not found for employee ID#" << employeeID;
                    break;
                }

                file.clear();
                int location = (recordNumber - 1) * sizeof(tempEmployee);
                file.seekp(location, std::ios::beg);
                std::cout << "\nEnter new record for employee having ID " << employeeID;
                tempEmployee.readData();
                file.write(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                break;

            case '6': // Delete an employee record
                recordNumber = 0;
                std::cout << "\nEnter employee ID to be deleted: ";
                std::cin >> employeeID;
                recordFound = 0;
                file.seekg(0, std::ios::beg);
                file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));

                while (!file.eof()) {
                    recordNumber++;
                    if (tempEmployee.getID() == employeeID) {
                        std::cout << "The old record of employee having ID " << employeeID << " is: ";
                        tempEmployee.displayRecord();
                        recordFound = 1;
                        break;
                    }
                    file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                }

                char tempFile[] = "temp.txt";
                std::fstream tempFileStream(tempFile, std::ios::out | std::ios::binary);
                if (recordFound == 0) {
                    std::cout << "\nData not found for employee ID#" << employeeID;
                    break;
                } else {
                    file.clear();
                    file.seekg(0, std::ios::beg);
                    file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));

                    while (!file.eof()) {
                        if (tempEmployee.getID() != employeeID) {
                            tempFileStream.write(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                        }
                        file.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                    }
                    file.close();
                    tempFileStream.close();
                    tempFileStream.open(tempFile, std::ios::in | std::ios::binary);
                    file.open(fileName, std::ios::out | std::ios::binary);
                    tempFileStream.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));

                    while (!tempFileStream.eof()) {
                        file.write(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                        tempFileStream.read(reinterpret_cast<char*>(&tempEmployee), sizeof(tempEmployee));
                    }
                }
                tempFileStream.close();
                file.close();
                remove(tempFile);
                file.open(fileName, std::ios::ate | std::ios::in | std::ios::out | std::ios::binary);
                break;

            case '7': // Exit the program
                exit(0);
                break;

            default:
                std::cout << "Invalid Option";
        }
        std::cout << "\nDo you want to continue? (y/n): ";
        std::cin >> continueChoice;
    } while (continueChoice != 'n');

    return 0;
}

