    ~DerivedStringHolder() {
        delete[] buffer; // Free allocated buffer memory
    }

    void setBuffer(const char* newBuffer) {
        delete[] buffer; // Free existing buffer memory
        buffer = new char[strlen(newBuffer) + 1]; // Allocate new memory for the buffer
        strcpy(buffer, newBuffer); // Copy the new buffer content
    }

private:
    char* buffer; // Pointer to hold the dynamically allocated buffer
};

