#ifndef SPTR_HPP_
#define SPTR_HPP_

#include <boost/thread/thread.hpp>

namespace cs540 {

// Class to manage reference counting for shared pointers
class ReferenceCounter {
public:
    int count;
    mutable boost::mutex mutex;

    ReferenceCounter() : count(1) {}

    ReferenceCounter* get() {
        return this;
    }

    int getCurrentCount() {
        return count;
    }

    void increment() {
        boost::mutex::scoped_lock lock(mutex);
        ++count;
    }

    void decrement() {
        boost::mutex::scoped_lock lock(mutex);
        --count;
    }
};

template<typename T>
class SmartPointer {
public:
    T* pointer;
    ReferenceCounter* counter;

    // Default constructor initializes to null
    SmartPointer() : pointer(nullptr), counter(nullptr) {}

    // Constructor that initializes with a given object
    template<typename U>
    SmartPointer(U* u) : pointer(u) {
        counter = new ReferenceCounter;
    }

    // Copy constructor
    SmartPointer(const SmartPointer& other) 
        : pointer(other.get()), counter(other.getCounter()) {
        other.counter->increment();
    }

    // Template copy constructor for different types
    template<typename U>
    SmartPointer(const SmartPointer<U>& other) 
        : pointer(other.get()), counter(other.getCounter()) {
        other.counter->increment();
    }

    T* get() const {
        return pointer;
    }

    int getCount() {
        return counter->getCurrentCount();
    }

    ReferenceCounter* getCounter() const {
        return counter;
    }

    // Assignment operator for same types
    SmartPointer& operator=(const SmartPointer& rhs) {
        if (this->get() != rhs.get()) {
            pointer = rhs.get();
            counter = rhs.counter;
            counter->decrement();
        }
        return *this;
    }

    // Assignment operator for different types within hierarchy
    template<typename U>
    SmartPointer<T>& operator=(const SmartPointer<U>& rhs) {
        if (this->get() != rhs.get()) {
            pointer = rhs.get();
            counter = rhs.counter;
            counter->decrement();
        }
        return *this;
    }

    T& operator*() const {
        return *pointer;
    }

    T* operator->() const {
        return pointer;
    }

    void reset() {
        counter->decrement();
        pointer = nullptr;
    }

    // Conversion operator to bool for null checks
    operator bool() const {
        return pointer != nullptr;
    }
};

// Comparison operators for smart pointers
template<typename T1, typename T2>
bool operator==(const SmartPointer<T1>& lhs, const SmartPointer<T2>& rhs) {
    return lhs.pointer == rhs.pointer;
}

template<typename T1, typename T2>
bool operator!=(const SmartPointer<T1>& lhs, const SmartPointer<T2>& rhs) {
    return lhs.pointer != rhs.pointer;
}

template<typename T1>
bool operator!(const SmartPointer<T1>& ptr) {
    return !ptr.pointer;
}

// Static pointer cast for smart pointers
template<typename T, typename U>
SmartPointer<T> static_pointer_cast(const SmartPointer<U>& sp) {
    return SmartPointer<T>(sp);
}

// Dynamic pointer cast for smart pointers
template<typename T, typename U>
SmartPointer<T> dynamic_pointer_cast(const SmartPointer<U>& sp) {
    return SmartPointer<T>(sp);
}

} // end namespace cs540

