class RandomGenerator {
public:
    RandomGenerator(unsigned int seed = 0);
    // Generate random integer in the range [low, high].
    int operator()(int low, int high) {
        int32_t randomValue;
        int errorCode = random_r(&randomBuffer, &randomValue);
        assert(errorCode == 0);
        return int(randomValue * (double(high - low + 1) / (double(RAND_MAX) + 1)) + low);
    }
private:
    RandomGenerator(const RandomGenerator &);
    RandomGenerator &operator=(const RandomGenerator &);
private:
    random_data randomBuffer;
    char randomState[128];
};

RandomGenerator::RandomGenerator(unsigned int seed) {
    int errorCode;
    memset(&randomBuffer, 0, sizeof(randomBuffer));
    errorCode = initstate_r(seed, randomState, 128, &randomBuffer); 
    assert(errorCode == 0);
    errorCode = srandom_r(seed, &randomBuffer); 
    assert(errorCode == 0);
}

