void *operator new(size_t size) throw (bad_alloc) {
    char *pointer = (char *) malloc(size + 8);
    *((size_t *) pointer) = size;
    __sync_add_and_fetch(&allocatedMemory, size);
    return pointer + 8;
}

void operator delete(void *pointer) throw () {
    if (pointer == 0) {
        return;
    }

    char *p = (char *) pointer;
    size_t size = *((size_t *) (p - 8));
    __sync_sub_and_fetch(&allocatedMemory, size);
    free(p - 8);
}

