    {
        {
            Sptr<DerivedClass> sp(new DerivedClass);
            Sptr<BaseClass1> sp2;
            sp2 = sp;
            sp2 = sp2;
            sp.reset();
            sp = new DerivedClass;
            Sptr<BaseClass1> sp3(sp2);
        }
        {
            Sptr<DerivedClass> sp(new DerivedClass);
            char *buffer = (char *) ::operator new(sizeof(Sptr<BaseClass1>));
            Sptr<BaseClass1> &sp2 = *(new (buffer) Sptr<BaseClass1>());
            sp2 = sp;
            sp2 = sp2;
            sp.reset();
            sp2.reset();
            ::operator delete(buffer);
        }
    }

    // Test dereference operator.
    {
        Sptr<DerivedClass> sp(new DerivedClass);
        (*sp).value = 1234;

