        Sptr<DerivedClass> sp(new DerivedClass);
        Sptr<BaseClass1> sp2(sp);
        Sptr<DerivedClass> sp3(static_pointer_cast<DerivedClass>(sp2));
    }

    // Test dynamic_pointer_cast.
    {
