        Sptr<DerivedClassPolymorphic> sp3(dynamic_pointer_cast<DerivedClassPolymorphic>(sp2));
        Sptr<DerivedClassPolymorphic> sp4(static_pointer_cast<DerivedClassPolymorphic>(sp2));
        Sptr<AnotherDerivedClassPolymorphic> sp5(dynamic_pointer_cast<AnotherDerivedClassPolymorphic>(sp2));
        assert(!sp5);
