/* Threaded Test * ============================================================================== */

time_t startTime;
const int tableSize = 100;

class TestObject {
public:
    TestObject() {}
    TestObject(int value) : a(value) {}
    int a;
};

struct TableEntry {
    TableEntry();
    ~TableEntry();
    pthread_mutex_t lock;
    Sptr<TestObject> *ptr;
} *table;

TableEntry::TableEntry() : ptr(0) {
    int errorCode;
    errorCode = pthread_mutex_init(&lock, 0);
    assert(errorCode == 0);
}

TableEntry::~TableEntry() {
    int errorCode;
    errorCode = pthread_mutex_destroy(&lock);
    assert(errorCode == 0);
    if (ptr != 0) {
        delete ptr;
        ptr = 0;
    }
}

void *runThread(void *threadId) {
    RandomGenerator random((unsigned long) threadId);

    pthread_t tid = pthread_self();
    int errorCode;
    struct OperationCounters {
        unsigned long assignmentNew, assignment, reset, newDefault, newCopy, deletion;
    } counters = {0, 0, 0, 0, 0, 0};

    while (time(NULL) < startTime + runDuration) {
        int action = random(0, 4);
        switch (action) {
            case 0: // Assign new TestObject to ptr
            {
                int index = random(0, tableSize - 1);
                errorCode = pthread_mutex_lock(&table[index].lock); 
                assert(errorCode == 0);
                if (table[index].ptr != 0) {
                    *table[index].ptr = new TestObject; 
                    counters.assignmentNew++;
                }
                errorCode = pthread_mutex_unlock(&table[index].lock); 
                assert(errorCode == 0);
                break;
            }
            case 1: // Set ptr to NULL
            {
                int index = random(0, tableSize - 1);
                errorCode = pthread_mutex_lock(&table[index].lock); 
                assert(errorCode == 0);
                if (table[index].ptr != 0) {
                    table[index].ptr->reset();
                    counters.reset++;
                }
                errorCode = pthread_mutex_unlock(&table[index].lock); 
                assert(errorCode == 0);
                break;
            }
            case 2: // Assign ptr from another ptr
            {
                int index1 = random(0, tableSize - 1);
                int index2 = random(0, tableSize - 1);

                if (index1 <= index2) {
                    errorCode = pthread_mutex_lock(&table[index1].lock); 
                    assert(errorCode == 0);
                    if (index1 != index2) {
                        errorCode = pthread_mutex_lock(&table[index2].lock); 
                        assert(errorCode == 0);
                    }
                } else {
                    errorCode = pthread_mutex_lock(&table[index2].lock); 
                    assert(errorCode == 0);
                    errorCode = pthread_mutex_lock(&table[index1].lock); 
                    assert(errorCode == 0);
                }

                if (table[index1].ptr && table[index2].ptr) {
                    *table[index1].ptr = *table[index2].ptr;
                    counters.assignment++;
                }

                errorCode = pthread_mutex_unlock(&table[index1].lock); 
                assert(errorCode == 0);
                if (index1 != index2) {
                    errorCode = pthread_mutex_unlock(&table[index2].lock); 
                    assert(errorCode == 0);
                }
                break;
            }
            case 3: // Create new Sptr
            {
                if (random(0, 1) == 0) {
                    int index = random(0, tableSize - 1);
                    errorCode = pthread_mutex_lock(&table[index].lock); 
                    assert(errorCode == 0);
                    if (!table[index].ptr) {
                        table[index].ptr = new Sptr<TestObject>;
                        counters.newDefault++;
                    }
                    errorCode = pthread_mutex_unlock(&table[index].lock); 
                    assert(errorCode == 0);
                } else {
                    int index1 = random(0, tableSize - 1), index2;
                    do {
                        index2 = random(0, tableSize - 1);
                    } while (index1 == index2);

                    if (index1 < index2) {
                        errorCode = pthread_mutex_lock(&table[index1].lock); 
                        assert(errorCode == 0);
                        errorCode = pthread_mutex_lock(&table[index2].lock); 
                        assert(errorCode == 0);
                    } else {
                        errorCode = pthread_mutex_lock(&table[index2].lock); 
                        assert(errorCode == 0);
                        errorCode = pthread_mutex_lock(&table[index1].lock); 
                        assert(errorCode == 0);
                    }

                    if (!table[index1].ptr && table[index2].ptr) {
                        table[index1].ptr = new Sptr<TestObject>(*table[index2].ptr);
                        counters.newCopy++;
                    }

                    errorCode = pthread_mutex_unlock(&table[index1].lock); 
                    assert(errorCode == 0);
                    errorCode = pthread_mutex_unlock(&table[index2].lock); 
                    assert(errorCode == 0);
                }
                break;
            }
            case 4: // Delete
            {
                int index = random(0, tableSize - 1);
                errorCode = pthread_mutex_lock(&table[index].lock); 
                assert(errorCode == 0);
                if (table[index].ptr) {
                    delete table[index].ptr;
                    table[index].ptr = 0;
                    counters.deletion++;
                }
                errorCode = pthread_mutex_unlock(&table[index].lock); 
                assert(errorCode == 0);
                break;
            }
            default:
                fprintf(stderr, "Invalid action: %d\n", action);
                abort();
                break;
        }
    }

    double duration = runDuration;
    printf("%10lu: assignmentNew=%lu ops, assignment=%lu ops, reset=%lu ops, newDefault=%lu ops, newCopy=%lu ops, delete=%lu ops\n"
           "    rates: assignmentNew=%.0f ops/sec, assignment=%.0f ops/sec, reset=%.0f ops/sec, newDefault=%.0f ops/sec, newCopy=%.0f ops/sec, delete=%.0f ops/sec\n",
           (unsigned long) tid,
           counters.assignmentNew, counters.assignment, counters.reset, counters.newDefault, counters.newCopy, counters.deletion,
           counters.assignmentNew / duration, counters.assignment / duration, counters.reset / duration, counters.newDefault / duration, counters.newCopy / duration, counters.deletion / duration);

    return NULL;
}

void runThreadedTest() {
    int errorCode;
    size_t initialAllocatedMemory = allocatedMemory;

    table = new TableEntry[tableSize];

    printf("Running threaded test for %d seconds.\n", runDuration);

    startTime = time(NULL);
    pthread_t thread1, thread2, thread3, thread4;
    errorCode = pthread_create(&thread1, 0, runThread, (void *) 1); 
    assert(errorCode == 0);
    errorCode = pthread_create(&thread2, 0, runThread, (void *) 2); 
    assert(errorCode == 0);
    errorCode = pthread_create(&thread3, 0, runThread, (void *) 3); 
    assert(errorCode == 0);
    errorCode = pthread_create(&thread4, 0, runThread, (void *) 3); 
    assert(errorCode == 0);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);
    pthread_join(thread3, NULL);
    pthread_join(thread4, NULL);

    delete [] table;

    if (initialAllocatedMemory != allocatedMemory) {
        printf("Leaked %zu bytes in threaded test.\n", allocatedMemory - initialAllocatedMemory);
        abort();
    }
}

#include <iostream>
