using namespace std;

class LinkedList
{
private:
    class Node
    {
    public:
        float amount;
        int date; // Simplified representation of a date
        string description;
        Node* next;
        Node* prev;

        Node() {}

        Node(float amt, int dt, string desc, Node* p, Node* n) 
            : amount(amt), date(dt), description(desc), prev(p), next(n) {}

        Node(float amt, int dt, string desc)
            : amount(amt), date(dt), description(desc) {}
    };

    Node* head;

public:
    LinkedList()
    {
        head = new Node(); // Initialize head node
    }

    // Adds a new node to the front of the list
    void addFront(int date, float price, string desc)
    {
        Node* newNode = new Node(price, date, desc);
        newNode->next = head->next; // Link new node to the current first node
        if (head->next != nullptr) {
            head->next->prev = newNode; // Update previous link of the current first node
        }
        head->next = newNode; // Set new node as the first node
        newNode->prev = head; // Link head to the new first node
    }

    // Displays all nodes in the list
    void displayList()
    {
        Node* currentNode = head->next; // Start from the first actual node
        while (currentNode != nullptr)
        {
            cout << currentNode->amount << ", on " << currentNode->date 
                 << " name: " << currentNode->description << endl;
            currentNode = currentNode->next; // Move to the next node
        }
    }
};

int main(int argc, char* argv[])
{
    LinkedList theList;

    theList.addFront(1, 19.95, "soap");
    theList.displayList();

    return 0;
}

