using namespace std;

class LinkedList {
private:
    class Node {
    public:
        float amount;
        int date; // Placeholder for date representation
        string description;
        int position; // Marker for node position in the list
        Node *next, *prev;

        Node() {}

        Node(float amt, int dt, string desc, Node* previous, Node* nextNode) 
            : amount(amt), date(dt), description(desc), prev(previous), next(nextNode) {}

        Node(float amt, int dt, string desc) 
            : amount(amt), date(dt), description(desc) {}
    };

    Node *head;
    int nodeCount;

public:
    LinkedList() {
        head = new Node();
    }

    void addFront(int date, float price, string desc) {
        Node *newNode = new Node(price, date, desc);
        newNode->next = head->next;
        head->next = newNode;
    }

    void addManyGenericNodes(int count) {
        this->nodeCount = count;
        Node *placeholderNode = new Node(0, 0, "blank");

        while (nodeCount > 0) { 
            cout << nodeCount << endl;
            Node *newNode = placeholderNode; // Implicit copy constructor
            PRINT_TOKEN(newNode);

            newNode->next = head->next;
            head->next = newNode;
            cout << newNode << endl;
            nodeCount--;
        }
    }

    void addBack(int date, float price, string desc) {
        int positionIndex = 1;
        Node *current = head;
        Node *newNode = new Node(price, date, desc);

        while (current->next != nullptr) { // Traverse to the tail node
            current = current->next;
            current->position = positionIndex++;
        }
        current->next = newNode;
    }

    void displayList() {
        Node *current = head;
        while (current->next != nullptr) {
            current = current->next;
            cout << "Element " << current->position << ", cost " << current->amount 
                 << ", on " << current->date << ", name: " << current->description << endl;
        }
    }
};

int determineByteOrder() {
    short int word = 0x0001; // 16-bit integer
    char *byte = (char *)&word; // Pointer to the first byte of the integer
    return (byte[0] ? 1 : 0); // Return 1 for Little-Endian, 0 for Big-Endian
}

int main(int argc, char *argv[]) {
    LinkedList *dynamicList = new LinkedList(); // Dynamic allocation on heap
    dynamicList->addFront(1, 19.95, "soap");
    dynamicList->addFront(4, 12.95, "paint");
    dynamicList->addFront(4, 13.95, "sand paper");
    dynamicList->addFront(5, 14.95, "carrots");
    dynamicList->addBack(5, 14.95, "end");
    dynamicList->displayList();

    LinkedList stackList; // Automatic allocation on stack
    stackList.addFront(1, 19.95, "2soap");
    stackList.addFront(4, 12.95, "2paint");
    stackList.addFront(4, 13.95, "2sand paper");
    stackList.addFront(5, 14.95, "2carrots");
    stackList.addBack(5, 14.95, "2end");
    stackList.addBack(5, 14.95, "2end2");
    stackList.addManyGenericNodes(8);

    cout << "1 is LittleEndian, 0 is BigEndian: " << determineByteOrder() << endl;

    return 0;
}

