#include <stdio.h>
#include <typeinfo>

class Base {
public:
    Base() {}
};

class Action {
public:
    void apply(Base* target);
};

class Registry {
public:
    void registerAction(const std::type_info& typeInfo, Action* action);
    void apply(Base* target);
private:
    // Internal storage for registered actions
};

class MyClass1 : public Base {
    // Derived class from Base
};

class Action1 : public Action {
public:
    void apply(Base* target) override;
};

Registry registry; // Singleton instance for action registry

int main(int argc, char* argv[]) {
    MyClass1 instance; // Instance of MyClass1
    static Action1 actionInstance; // Static instance of Action1
    registry.registerAction(typeid(instance), &actionInstance); // Register action for MyClass1
    registry.apply(&instance); // Apply Action1 to MyClass1 instance

    return 0;
}

#include <stdio.h>

class ValueHolder
{
public:
    // Constructor to initialize the value
    ValueHolder(int initialValue) : value(initialValue) {}

    // Assignment operator to copy value from another instance
    const ValueHolder& operator=(const ValueHolder& other)
    {
        value = other.value;
        return *this;
    }

    // Set the value
    void setValue(int newValue) { value = newValue; }

    // Get the current value
    int getValue() const { return value; }

private:
    int value; // Holds the integer value
};

int main() {
    ValueHolder first(1), second(2), third(3);

    // Chain assignment to copy the value of 'third' to 'second' and then to 'first'
    first = second = third;

    // Update the value of 'first'
    first.setValue(5);

    // Output the values of each instance
    printf("First Value: %d\n", first.getValue());
    printf("Second Value: %d\n", second.getValue());
    printf("Third Value: %d\n", third.getValue());
}

