    int endPosition = sentence.find("from") - 1;

    sentence.replace(sentence.begin() + position, sentence.begin() + endPosition, replacement2);
    cout << "Sentence is: " << sentence << endl;

    // Replace 'Dennis' with 'alexander'
    cout << "Replacing 'Dennis' with 'alexander'" << endl;
    int startPosition = sentence.find('D'); // Search for 'Dennis'
    int spacePosition = sentence.find(' ', startPosition + 1); // Space after 'Dennis'
    int startIndex = replacement3.find("alex"); // Search for 'alex'
    int length = strlen("alexander");

    sentence.replace(startPosition, spacePosition - startPosition, replacement3, startIndex, length);
    cout << "Sentence is: " << sentence << endl;

    // Replace 'from' with 'by'
    cout << "Replacing 'from' with 'by'" << endl;
    char charArray[] = "bytes";
    position = sentence.find("from");

    // Replace using iterators
    sentence.replace(position, 4, charArray, 2);
    cout << "Sentence is: " << sentence << endl;

    // Replace 'a' with 'A' in 'alexander'
    cout << "Replacing 'a' with 'A' in 'alexander'" << endl;
    position = sentence.find("alexander");
    sentence.replace(position, 1, 1, 'A');
    cout << "Sentence is: " << sentence << endl;

    // Replace 'Ritchie' with 'Stepanov'
    cout << "Replacing 'Ritchie' with 'Stepanov'" << endl;
    startPosition = sentence.find('R');
