// Abstract base class for password policies
class Policy {
protected:
    bool isChecked;

public:
    virtual void check(const string& password) = 0;

    bool isValid() const {
        return isChecked;
    }
};

// Policy to enforce length constraints on the password
class LengthPolicy : public Policy {
private:
    unsigned short minLength;
    unsigned short maxLength;

public:
    LengthPolicy(unsigned short minLen) {
        minLength = minLen;
        maxLength = 255; // Default maximum length
    }

    LengthPolicy(unsigned short minLen, unsigned short maxLen) {
        minLength = minLen;
        maxLength = maxLen;
    }

    void check(const string& password) override {
        isChecked = (password.size() >= minLength && password.size() <= maxLength);
    }
};

// Policy to enforce character class requirements in the password
class ClassPolicy : public Policy {
private:
    unsigned short requiredClassCount;

public:
    ClassPolicy(unsigned short minClassCount) {
        requiredClassCount = minClassCount;
    }

    void check(const string& password) override {
        unsigned classCount = 0;
        bool hasDigit = false, hasUpper = false, hasLower = false, hasSpecial = false;

        for (char ch : password) {
            if (isdigit(ch)) hasDigit = true;
            else if (isupper(ch)) hasUpper = true;
            else if (islower(ch)) hasLower = true;
            else hasSpecial = true;
        }

        if (hasDigit) classCount++;
        if (hasUpper) classCount++;
        if (hasLower) classCount++;
        if (hasSpecial) classCount++;

        isChecked = (classCount >= requiredClassCount);
    }
};

// Policy to require the inclusion of a specific character type in the password
class IncludePolicy : public Policy {
private:
    char requiredCharacterType;

public:
    IncludePolicy(char charType) {
        requiredCharacterType = charType;
    }

    void check(const string& password) override {
        for (char ch : password) {
            if ((isdigit(ch) && isdigit(requiredCharacterType)) ||
                (isupper(ch) && isupper(requiredCharacterType)) ||
                (islower(ch) && islower(requiredCharacterType)) ||
                (!isalnum(ch) && !isalnum(requiredCharacterType))) {
                isChecked = true;
                return;
            }
        }
        isChecked = false;
    }
};

// Policy to prohibit the inclusion of a specific character type in the password
class NotIncludePolicy : public Policy {
private:
    char prohibitedCharacterType;

public:
    NotIncludePolicy(char charType) {
        prohibitedCharacterType = charType;
    }

    void check(const string& password) override {
        for (char ch : password) {
            if ((isdigit(ch) && isdigit(prohibitedCharacterType)) ||
                (isupper(ch) && isupper(prohibitedCharacterType)) ||
                (islower(ch) && islower(prohibitedCharacterType)) ||
                (!isalnum(ch) && !isalnum(prohibitedCharacterType))) {
                isChecked = false;
                return;
            }
        }
        isChecked = true;
    }
};

// Policy to limit consecutive identical characters in the password
class RepetitionPolicy : public Policy {
private:
    unsigned short maxRepetitions;

public:
    RepetitionPolicy(unsigned short maxCount) {
        maxRepetitions = maxCount;
    }

    void check(const string& password) override {
        unsigned currentCount = 0;
        unsigned maxCount = 0;

        for (size_t i = 1; i < password.size(); i++) {
            if (password[i] == password[i - 1]) {
                currentCount++;
                if (currentCount > maxCount) {
                    maxCount = currentCount;
                }
            } else {
                currentCount = 1; // Reset count for new character
            }
        }

        isChecked = (maxCount <= maxRepetitions);
    }
};

// Policy to limit consecutive characters in the password
class ConsecutivePolicy : public Policy {
private:
    unsigned short maxConsecutive;

public:
    ConsecutivePolicy(unsigned short maxCount) {
        maxConsecutive = maxCount;
    }

    void check(const string& password) override {
        unsigned currentCount = 0;
        unsigned maxCount = 0;

        for (size_t i = 1; i < password.size(); i++) {
            if (password[i] == password[i - 1] + 1) {
                currentCount++;
                if (currentCount > maxCount) {
                    maxCount = currentCount;
                }
            } else {
                currentCount = 1; // Reset count for new character
            }
        }

        isChecked = (maxCount <= maxConsecutive);
    }
};

// Function to validate the password against a set of policies
string validatePassword(const string& password, const vector<Policy*>& policies) {
    bool isValid = true;

    for (const auto& policy : policies) {
        policy->check(password);
        isValid = (isValid && policy->isValid());
    }

    return isValid ? "OK" : "NOK";
}

int main() {
    vector<Policy*> policies;
    unsigned policyCount;
    string policyName;
    bool isReadingString = false;

    inputFile >> policyCount;

    for (unsigned i = 0; i < policyCount; i++) {
        if (!isReadingString) {
            inputFile >> policyName;
        } else {
            isReadingString = false;
        }

        if (policyName == "length") {
            int minLength;
            inputFile >> minLength;

            string maxLengthStr;
            inputFile >> maxLengthStr;
            unsigned maxLength;

            try {
                maxLength = stoi(maxLengthStr);
            } catch (exception&) {
                isReadingString = true;
                policyName = maxLengthStr;
                policies.push_back(new LengthPolicy(minLength));
                continue;
            }

            policies.push_back(new LengthPolicy(minLength, maxLength));
        } else {
            if (policyName == "class") {
                unsigned classCount;
                inputFile >> classCount;
                policies.push_back(new ClassPolicy(classCount));
            } else if (policyName == "include") {
                char charType;
                inputFile >> charType;
                policies.push_back(new IncludePolicy(charType));
            } else if (policyName == "ninclude") {
                char charType;
                inputFile >> charType;
                policies.push_back(new NotIncludePolicy(charType));
            } else if (policyName == "repetition") {
                unsigned repetitionCount;
                inputFile >> repetitionCount;
                policies.push_back(new RepetitionPolicy(repetitionCount));
            } else if (policyName == "consecutive") {
                unsigned consecutiveCount;
                inputFile >> consecutiveCount;
                policies.push_back(new ConsecutivePolicy(consecutiveCount));
            }
        }
    }

    string password;
    while (inputFile >> password) {
        cout << validatePassword(password, policies) << endl;
    }

    return 0;
}

