#include <iostream>
using namespace std;

const int MAX_SIZE = 1000;

struct Pair {
    int maximum;
    int position;
};

class Vector {
private:
    int size; // kích thước của vector
    int elements[MAX_SIZE]; // mảng chứa các phần tử của vector
public:
    Vector(int dimension = 0, int value = 0);
    Vector(const Vector& other);
    ~Vector();

    friend ostream& operator<<(ostream& output, const Vector& vec);
    friend istream& operator>>(istream& input, Vector& vec);

    Vector& operator=(const Vector& other);
    void update(int dimension, int value);
    int sumElements();
    Pair findMaxPosition();
    void sort();
    int operator*(const Vector& other);
};

Vector::Vector(int dimension, int value) {
    size = dimension;
    for (int i = 0; i < dimension; i++) {
        elements[i] = value;
    }
}

Vector::Vector(const Vector& other) {
    size = other.size;
    for (int i = 0; i < other.size; i++) {
        elements[i] = other.elements[i];
    }
}

Vector::~Vector() {
    size = 0;
}

ostream& operator<<(ostream& output, const Vector& vec) {
    output << "=[";
    for (int i = 0; i < vec.size; i++) {
        output << vec.elements[i];
        if (i != vec.size - 1) {
            output << ", ";
        }
    }
    output << "]" << endl;
    return output;
}

istream& operator>>(istream& input, Vector& vec) {
    cout << "Kích thước: ";
    input >> vec.size;
    cout << "Các phần tử: ";
    for (int j = 0; j < vec.size; j++) {
        input >> vec.elements[j];
    }
    return input;
}

Vector& Vector::operator=(const Vector& other) {
    size = other.size;
    for (int i = 0; i < other.size; i++) {
        elements[i] = other.elements[i];
    }
    return *this;
}

void Vector::update(int dimension, int value) {
    if (dimension <= MAX_SIZE) { // kiểm tra kích thước hợp lệ
        size = dimension;
        for (int i = 0; i < size; i++) {
            elements[i] = value;
        }
    }
}

int Vector::sumElements() {
    int total = 0;
    for (int i = 0; i < size; i++) {
        total += elements[i];
    }
    return total;
}

Pair Vector::findMaxPosition() {
    Pair maxPair;
    maxPair.maximum = elements[0];
    maxPair.position = 0;

    for (int i = 1; i < size; i++) {
        if (elements[i] > maxPair.maximum) {
            maxPair.maximum = elements[i];
            maxPair.position = i;
        }
    }
    return maxPair;
}

void Vector::sort() {
    for (int i = 0; i < size - 1; i++) {
        for (int j = i + 1; j < size; j++) {
            if (elements[i] > elements[j]) {
                swap(elements[i], elements[j]);
            }
        }
    }
}

int Vector::operator*(const Vector& other) {
    int product = 0;
    if (other.size != size) return 0; // kiểm tra kích thước tương thích
    for (int i = 0; i < size; i++) {
        product += other.elements[i] * elements[i];
    }
    return product;
}

int main() {
    Vector a; // khởi tạo vector

    cin >> a; // đọc dữ liệu cho vector

    cout << "a" << a; // hiển thị vector

    Vector a1(10, 1); // khởi tạo vector với tham số
    cout << "Vector khởi tạo từ tham số a1 " << a1;

    Vector b(a); // khởi tạo vector từ vector khác
    cout << "b" << b;

    Vector c;
    c = a; // gán vector
    cout << "c" << c;

    b.update(5, 10); // cập nhật vector
    cout << "b đã được cập nhật " << b;

    cout << "Tổng các phần tử trong vector a là " << a.sumElements() << endl; // tính tổng

    Pair maxInfo = a.findMaxPosition(); // tìm giá trị lớn nhất và vị trí
    cout << "Giá trị lớn nhất là " << maxInfo.maximum << " tại vị trí " << maxInfo.position << endl;

    a.sort(); // sắp xếp vector
    cout << "a sau khi sắp xếp" << a;

    int scalarProduct = a * c; // tính tích vô hướng
    cout << "Tích vô hướng giữa a đã sắp xếp và c là " << scalarProduct;

    return 0;
}

#ifndef _AVERAGE_H
#define _AVERAGE_H

#if (ARDUINO >= 100) 
# include <Arduino.h>
#else
# include <WProgram.h>
#endif

#include <math.h>

inline static float square(float value) {
    return value * value;
}

template <class T>
class Average {
private:
    T *_dataStore;                                    // Circular buffer for storing values
    T _totalSum;                                      // Cumulative sum for mean calculation
    uint32_t _currentIndex;                           // Current index for circular buffer
    uint32_t _elementCount;                           // Total number of elements added
    uint32_t _bufferSize;                             // Size of the circular buffer

public:
    Average(uint32_t size);
    ~Average();
    float addEntry(T entry);
    void pushEntry(T entry);
    float calculateMean();
    T calculateMode();
    T findMinimum();
    T findMinimum(int *index);
    T findMaximum();
    T findMaximum(int *index);
    float calculateStdDev();
    T retrieve(uint32_t index);
    void performLeastSquares(float &slope, float &intercept, float &correlation);
    int getElementCount();
    T predictValue(int x);
    T calculateSum();
    void reset();
    Average<T> &operator=(Average<T> &other);
};

template <class T>
int Average<T>::getElementCount() {
    return _elementCount;
}

template <class T>
Average<T>::Average(uint32_t size) {
    _bufferSize = size;
    _elementCount = 0;
    _dataStore = (T *)malloc(sizeof(T) * size);
    _currentIndex = 0;                               // Initialize index for circular storage
    _totalSum = 0;                                   // Initialize sum for fast mean calculation
    for (uint32_t i = 0; i < size; i++) {
        _dataStore[i] = 0;
    }
}

template <class T>
Average<T>::~Average() {
    free(_dataStore);
}

template <class T>
void Average<T>::pushEntry(T entry) {
    if (_elementCount < _bufferSize) {               // Adding new values to the buffer
        _elementCount++;                              // Increment count of stored values
    } else {                                          // Overwriting oldest values
        _totalSum -= _dataStore[_currentIndex];      // Subtract the oldest value from the sum
    }
    _dataStore[_currentIndex] = entry;               // Store the new value
    _totalSum += entry;                              // Update the total sum
    _currentIndex = (_currentIndex + 1) % _bufferSize; // Move to the next index in a circular manner
}

template <class T>
float Average<T>::addEntry(T entry) {
    pushEntry(entry);
    return calculateMean();
}

template <class T>
float Average<T>::calculateMean() {
    if (_elementCount == 0) {
        return 0;
    }
    return static_cast<float>(_totalSum) / _elementCount; // Calculate mean from total sum
}

template <class T>
T Average<T>::calculateMode() {
    uint32_t outerIndex, innerIndex;
    T modeValue;
    uint32_t modeCount;
    T currentValue;
    uint32_t currentCount;

    if (_elementCount == 0) {
        return 0;
    }

    modeValue = retrieve(0);
    modeCount = 1;
    for (outerIndex = 0; outerIndex < _elementCount; outerIndex++) {
        currentValue = retrieve(outerIndex);
        currentCount = 1;
        for (innerIndex = outerIndex + 1; innerIndex < _elementCount; innerIndex++) {
            if (retrieve(innerIndex) == currentValue) {
                currentCount++;
            }
        }
        if (currentCount > modeCount) {
            modeValue = currentValue;
            modeCount = currentCount;
        }
        if (_elementCount - outerIndex < modeCount) {
            break; // Early exit if no larger count can be found
        }
    }
    return modeValue;
}

template <class T>
T Average<T>::findMinimum() {
    return findMinimum(nullptr);
}

template <class T>
T Average<T>::findMinimum(int *index) {
    T minValue;

    if (index != nullptr) {
        *index = 0;
    }

    if (_elementCount == 0) {
        return 0;
    }

    minValue = retrieve(0);

    for (uint32_t i = 0; i < _elementCount; i++) {
        if (retrieve(i) < minValue) {
            minValue = retrieve(i);
            if (index != nullptr) {
                *index = i;
            }
        }
    }
    return minValue;
}

template <class T>
T Average<T>::findMaximum() {
    return findMaximum(nullptr);
}

template <class T>
T Average<T>::findMaximum(int *index) {
    T maxValue;

    if (index != nullptr) {
        *index = 0;
    }

    if (_elementCount == 0) {
        return 0;
    }

    maxValue = retrieve(0);

    for (uint32_t i = 0; i < _elementCount; i++) {
        if (retrieve(i) > maxValue) {
            maxValue = retrieve(i);
            if (index != nullptr) {
                *index = i;
            }
        }
    }
    return maxValue;
}

template <class T>
float Average<T>::calculateStdDev() {
    float squareDiff;
    float sumOfSquares = 0;
    float meanValue = calculateMean();

    if (_elementCount == 0) {
        return 0;
    }

    for (uint32_t i = 0; i < _elementCount; i++) {
        squareDiff = meanValue - static_cast<float>(retrieve(i));
        sumOfSquares += squareDiff * squareDiff;
    }
    return sqrt(sumOfSquares / _elementCount);
}

template <class T>
T Average<T>::retrieve(uint32_t index) {
    if (index >= _elementCount) {
        return -1; // Error case
    }

    int32_t startIndex = _currentIndex - _elementCount;
    if (startIndex < 0) startIndex += _bufferSize;
    int32_t circularIndex = startIndex + index;
    if (circularIndex >= _bufferSize) circularIndex -= _bufferSize;
    return _dataStore[circularIndex];
}

template <class T>
void Average<T>::performLeastSquares(float &slope, float &intercept, float &correlation) {
    float sumX = 0.0;
    float sumX2 = 0.0;
    float sumXY = 0.0;
    float sumY = 0.0;
    float sumY2 = 0.0;

    for (uint32_t i = 0; i < _elementCount; i++) {
        sumX += i;
        sumX2 += square(i);
        sumXY += i * retrieve(i);
        sumY += retrieve(i);
        sumY2 += square(retrieve(i));
    }

    float denominator = (_elementCount * sumX2 - square(sumX));
    if (denominator == 0) {
        slope = 0;
        intercept = 0;
        correlation = 0;
        return; // Singular matrix, cannot solve
    }

    slope = -(_elementCount * sumXY - sumX * sumY) / denominator;
    intercept = (sumY * sumX2 - sumX * sumXY) / denominator;
    correlation = (sumXY - sumX * sumY / _elementCount) / sqrt((sumX2 - square(sumX) / _elementCount) * (sumY2 - square(sumY) / _elementCount));
}

template <class T>
T Average<T>::predictValue(int x) {
    float slope, intercept, correlation;
    performLeastSquares(slope, intercept, correlation); // y = mx + c;

    T predictedValue = slope * x + intercept;
    return predictedValue;
}

template <class T>
T Average<T>::calculateSum() {
    return _totalSum;
}

template <class T>
void Average<T>::reset() {
    _elementCount = 0;
    _totalSum = 0;
    _currentIndex = 0;
}

template <class T>
Average<T> &Average<T>::operator=(Average<T> &other) {
    reset();
    for (int i = 0; i < other.getElementCount(); i++) {
        pushEntry(other.retrieve(i));
    }
    return *this;
}

