    cin >> inputString;
    newAccount->setAccountDoB(inputString);

    cout << "\nEnter Account Email Id\n";
    cin >> inputString;
    newAccount->setAccountEmailId(inputString);

    cout << "\nEnter Account Phone Number\n";
    cin >> inputString;
    if (newAccount->checkForCharacterInNumericField(inputString) && newAccount->checkForValidPhoneNumber(inputString)) {
        newAccount->setAccountPhoneNumber(inputString);
    } else {
        cout << "\nInvalid input. Either characters were entered or entered phone number is not of 10 digits.\n";
        return false;
    }

    cout << "\nEnter Account Address\n";
    cin >> inputString;
    newAccount->setAccountAddress(inputString);

    return true;
}

