class SeatSelection {
private:
    int selectedSeat;

public:
    void selectSeat() {
        int isValid = 0;
        while (isValid == 0) {
            cout << "\nEnter seat number: ";
            cin >> selectedSeat;
            if (selectedSeat >= 51) {
                isValid = 0;
                cout << "\n   Invalid seat number. Choose another.";
            } else {
                selectedSeat -= 1; // Adjust for zero-based index
                isValid = 1;
            }
        }
        while (seatStatus[selectedSeat] == 'X') {
            cout << "   Sorry, seat occupied. Please choose another seat.\n";
            selectSeat();
        }
    }

    friend void displaySelectedSeat(SeatSelection seat);
};

void displaySelectedSeat(SeatSelection seat) {
