    seatCount++;    
    displaySeatLayout();
}

class DateSelection {
public:
    int currentDate, currentMonth, currentYear;
    int inputDate, inputMonth, inputYear;
    char timeSlots[5][10] = {"10:10", "14:40", "17:20", "18:45", "22:50"};
    char selectedTime[10];

    void selectDateTime() {
        time_t currentTime = time(NULL);
        tm* timePtr = localtime(&currentTime);
        currentDate = timePtr->tm_mday;
        currentMonth = timePtr->tm_mon + 1;
        currentYear = timePtr->tm_year + 1900;

        while (true) {
            cout << "\nEnter date: ";
            cin >> inputDate;
            if (inputDate > 31 || inputDate < currentDate) {
                cout << "\nSorry, movie not screened on this date. Please enter again.";
            } else {
                break;
            }
        }

        while (true) {
            cout << "\nEnter month: ";
            cin >> inputMonth;
            if (inputMonth != currentMonth) {
                cout << "\nSorry, movie not screened in this month. Please enter again.";
            } else {
                break;
            }
        }

        while (true) {
            cout << "\nEnter year: ";
            cin >> inputYear;
            if (inputYear != currentYear) {
                cout << "\nSorry, movie not screened in this year. Please enter again.";
            } else {
                break;
            }
        }

        cout << inputDate << "-" << inputMonth << "-" << inputYear;
        cout << "\n\nMovie timings";
        for (int i = 0; i < 5; i++) {
            cout << "\n     " << (i + 1) << ". " << timeSlots[i];
        }

        while (true) {
            cout << "\nEnter preferred movie timing: ";
            cin >> inputDate;
            if (inputDate >= 1 && inputDate <= 5) {
                strcpy(selectedTime, timeSlots[inputDate - 1]);
                break;
            } else {
                cout << "\nInvalid option. Enter again:";
            }
        }
        cout << selectedTime;
    }
};

