#include <iostream>

using namespace std;

class Rational {

private:
    int numerator;
    int denominator;

public:
    // Default constructor initializes the rational number to 0/1
    Rational() : numerator(0), denominator(1) {}

    // Constructor initializes the rational number to i/1
    Rational(int i) : numerator(i), denominator(1) {}

    // Constructor initializes the rational number to i/j
    Rational(int i, int j) : numerator(i), denominator(j) {}

    // Set the numerator of the rational number
    void setNumerator(int i) {
        numerator = i;
    }

    // Set the denominator of the rational number
    void setDenominator(int i) {
        denominator = i;
    }

    // Get the numerator of the rational number
    int getNumerator() const {
        return numerator;
    }

    // Get the denominator of the rational number
    int getDenominator() const {
        return denominator;
    }

    // Overload the addition operator for rational numbers
    Rational operator+(const Rational& r) {
        Rational result;
        result.numerator = numerator * r.denominator + denominator * r.numerator;
        result.denominator = denominator * r.denominator;
        normalize(result);
        return reduceToLowestTerm(result);
    }

    // Overload the subtraction operator for rational numbers
    Rational operator-(const Rational& r) {
        Rational result;
        result.numerator = numerator * r.denominator - denominator * r.numerator;
        result.denominator = denominator * r.denominator;
        normalize(result);
        return reduceToLowestTerm(result);
    }

    // Overload the multiplication operator for rational numbers
    Rational operator*(const Rational& r) {
        Rational result;
        result.numerator = numerator * r.numerator;
        result.denominator = denominator * r.denominator;
        normalize(result);
        return reduceToLowestTerm(result);
    }

    // Overload the division operator for rational numbers
    Rational operator/(const Rational& r) {
        Rational result;
        result.numerator = numerator * r.denominator;
        result.denominator = denominator * r.numerator;
        normalize(result);
        return reduceToLowestTerm(result);
    }

    // Calculate the greatest common divisor using Euclid's algorithm
    int gcd(int a, int b) const {
        return (b == 0) ? a : gcd(b, a % b);
    }

    // Normalize the rational number to ensure proper representation
    void normalize(Rational& r) {
        if (r.numerator == 0 || r.denominator == 0) {
            r.numerator = 0;
            r.denominator = 1;
        }
        if (r.denominator < 0) {
            r.numerator = -r.numerator;
            r.denominator = -r.denominator;
        }
    }

    // Reduce the rational number to its lowest terms
    Rational reduceToLowestTerm(const Rational& r) {
        Rational result;
        int divisor = gcd(r.numerator, r.denominator);
        result.numerator = r.numerator / divisor;
        result.denominator = r.denominator / divisor;
        return result;
    }

    // Overload the output stream operator for rational numbers
    friend ostream& operator<<(ostream& os, const Rational& r);

    // Overload the input stream operator for rational numbers
    friend istream& operator>>(istream& is, Rational& r);
};

// Output the rational number in a human-readable format
ostream& operator<<(ostream& os, const Rational& r) {
    if (r.numerator > r.denominator) {
        if (r.denominator == 1) {
            os << r.numerator << endl;
        } else if (r.denominator < 0) {
            os << -r.numerator << "/" << -r.denominator << endl;
        } else {
            os << r.numerator / r.denominator << " " << r.numerator % r.denominator << "/" << r.denominator << endl;
        }
    } else {
        os << r.numerator << "/" << r.denominator << endl;
    }
    return os;
}

// Input the rational number from the user
istream& operator>>(istream& is, Rational& r) {
    is >> r.numerator >> r.denominator;
    return is;
}

int main() {
    Rational x(1, 2), y(2, 3), z;
    z = x + y;
    cout << z << endl;

    x.setNumerator(3);
    y.setDenominator(2);
    z = x + y;
    cout << z;

    cin >> x;
    cout << x;
    z = x + 5;
    cout << z;

    return 0;
}

