using namespace std;

// Class representing a bank account with essential operations
class Account {
    int accountNumber;
    char accountHolderName[50];
    int balance;
    char accountType;

public:
    void createAccount();  // Collects data from user to create a new account
    void showAccount() const;  // Displays account details
    void modify();  // Updates account information
    void deposit(int amount);  // Adds amount to the account balance
    void withdraw(int amount);  // Deducts amount from the account balance
    void report() const;  // Displays account details in a tabular format
    int getAccountNumber() const;  // Returns account number
    int getBalance() const;  // Returns current balance
    char getAccountType() const;  // Returns account type
};

// Function to create a new account and save it to a file
void Account::createAccount() {
    cout << "Enter The account No.: ";
    cin >> accountNumber;
    cout << "Enter The Name of The account Holder: ";
    cin.ignore();
    cin.getline(accountHolderName, 50);
    cout << "Enter Type of The account (C/S): ";
    cin >> accountType;
    accountType = toupper(accountType);
    cout << "Enter The Initial amount (>=500 for Saving and >=1000 for Current): ";
    cin >> balance;
    cout << "Account Created..";
}

// Function to display account details
void Account::showAccount() const {
    cout << "Account No.: " << accountNumber << endl;
    cout << "Account Holder Name: " << accountHolderName << endl;
    cout << "Type of Account: " << accountType << endl;
    cout << "Balance amount: " << balance << endl;
}

// Function to modify existing account details
void Account::modify() {
    cout << "Account No.: " << accountNumber << endl;
    cout << "Modify Account Holder Name: ";
    cin.ignore();
    cin.getline(accountHolderName, 50);
    cout << "Modify Type of Account: ";
    cin >> accountType;
    accountType = toupper(accountType);
    cout << "Modify Balance amount: ";
    cin >> balance;
}

// Function to deposit an amount into the account
void Account::deposit(int amount) {
    balance += amount;
}

// Function to withdraw an amount from the account
void Account::withdraw(int amount) {
    balance -= amount;
}

// Function to display account details in a tabular format
void Account::report() const {
    cout << accountNumber << setw(10) << " " << accountHolderName << setw(10) << " " << accountType << setw(6) << balance << endl;
}

// Function to return the account number
int Account::getAccountNumber() const {
    return accountNumber;
}

// Function to return the current balance
int Account::getBalance() const {
    return balance;
}

// Function to return the account type
char Account::getAccountType() const {
    return accountType;
}

