using namespace std;

namespace w3 {

    class Text {
        string* lines; // Pointer to dynamically allocated array of strings
        size_t lineCount; // Number of lines in the text

    public:
        // Returns the number of records of text data
        size_t size() const {
            return lineCount;
        }

        // Prints each line with its corresponding index
        void print() const {
            for (size_t i = 0; i < lineCount; i++) {
                cout << i + 1 << ":-->" << lines[i] << "<--\n";
            }
        }

        // Default constructor initializes an empty Text object
        Text() : lineCount(0), lines(nullptr) {}

        // Destructor releases allocated memory
        ~Text() {
            delete[] lines;
        }

        // Constructor that reads lines from a specified file
        Text(const char* filename) : lineCount(0), lines(nullptr) {
            fstream fileStream(filename, ios::in);
            if (fileStream.is_open()) {
                string line;
                while (getline(fileStream, line)) {
                    lineCount++;
                }

                lines = new string[lineCount];

                // Reset file stream to read lines into the array
                fileStream.clear();
                fileStream.seekg(0, ios_base::beg);

                for (size_t i = 0; i < lineCount; i++) {
                    getline(fileStream, lines[i]);
                    auto carriageReturnPos = lines[i].find('\r');
                    if (carriageReturnPos != string::npos) {
                        lines[i].erase(carriageReturnPos);
                    }
                }

                fileStream.close();
            } else {
                cerr << "Cannot open file -->" << filename << "<--\n";
                exit(1);
            }
        }

        // Copy constructor for deep copying
        Text(const Text& other) : lineCount(0), lines(nullptr) {
            *this = other;
        }

        // Copy assignment operator for deep copying
        Text& operator=(const Text& other) {
            if (this != &other) {
                delete[] lines;
                lineCount = other.lineCount;
                lines = new string[lineCount];
                for (size_t i = 0; i < lineCount; i++) {
                    lines[i] = other.lines[i];
                }
            }
            return *this;
        }

        // Move constructor for transferring ownership
        Text(Text&& other) noexcept : lineCount(0), lines(nullptr) {
            *this = move(other);
        }

        // Move assignment operator for transferring ownership
        Text& operator=(Text&& other) noexcept {
            if (this != &other) {
                delete[] lines;
                lineCount = other.lineCount;
                lines = other.lines;
                other.lineCount = 0;
                other.lines = nullptr;
            }
            return *this;
        }
    };
}

