using namespace std;

template <typename KeyType, typename ValueType, int MaxSize>
class KeyValueList {
    size_t entryCount;
    vector<KeyType> keys;
    vector<ValueType> values;

public:
    // Initializes an empty key-value list
    KeyValueList() : entryCount(0) {}

    // Returns the number of entries in the key-value list
    size_t size() const { return entryCount; }

    // Returns an unmodifiable reference to the key of element at index i
    const KeyType& key(int index) const {
        if (index >= 0 && index < entryCount) {
            return keys.at(index);
        }
    }

    // Returns an unmodifiable reference to the value of element at index i
    const ValueType& value(int index) const {
        if (index >= 0 && index < entryCount) {
            return values.at(index);
        }
    }

    // Adds a new key-value pair to the list if space is available
    // Returns a reference to the current object
    KeyValueList& add(const KeyType& newKey, const ValueType& newValue) {
        if (entryCount < MaxSize) {
            keys.push_back(newKey);
            values.push_back(newValue);
            entryCount++;
        }
        return *this;
    }

    // Finds the index of the first element with a matching key
    // Returns 0 if no match is found
    int find(const KeyType& searchKey) const {
        int index = 0;
        for (auto it = keys.begin(); it != keys.end(); ++it, ++index) {
            if ((*it) == searchKey) {
                return index;
            }
        }
        return 0; // Default return if not found
    }

    // Replaces the element at index with the provided key and value
    // Returns a reference to the current object
    KeyValueList& replace(int index, const KeyType& newKey, const ValueType& newValue) {
        if (index >= 0 && index < entryCount) {
            keys.at(index) = newKey;
            values.at(index) = newValue;
        }
        return *this;
    }
}; // class KeyValueList

