using namespace std;

class Grades {
    string* studentNumbers; // Array to hold student numbers
    double* studentMarks;   // Array to hold student marks
    int totalStudents;       // Count of students

public:
    // Default Constructor
    Grades() : studentNumbers(nullptr), studentMarks(nullptr), totalStudents(0) {}

    // Constructor that initializes from a file containing grade information
    Grades(const char* filename) {
        try {
            ifstream inputFile(filename);
            if (!inputFile) {
                throw "Cannot open the file"; // Exception if the file cannot be opened
            }

            if (inputFile.is_open()) {
                string line;
                totalStudents = 0;

                // Count the number of lines (students) in the file
                while (getline(inputFile, line)) {
                    totalStudents++;
                }

                // Reset the file stream to the beginning for reading data
                inputFile.clear();
                inputFile.seekg(0, ios_base::beg);

                // Dynamically allocate memory for student data
                studentNumbers = new string[totalStudents];
                studentMarks = new double[totalStudents];

                // Read student numbers and marks from the file
                for (int i = 0; i < totalStudents; i++) {
                    inputFile >> studentNumbers[i];
                    inputFile >> studentMarks[i];
                }
                inputFile.close();
            }
        } catch (ifstream::failure& fail) {
            cerr << "Cannot open the file"; // Handle file opening failure
        }
    }

    // Destructor to free allocated memory
    ~Grades() {
        delete[] studentNumbers;
        delete[] studentMarks;
    }

    // Displays student grades along with their letter grades
    template<typename GradeFunction>
    void displayGrades(ostream& outputStream, GradeFunction gradeFunc) const {
        for (int i = 0; i < totalStudents; i++) {
            outputStream << studentNumbers[i] << " " << studentMarks[i] << "0 " << gradeFunc(studentMarks[i]) << "\n";
        }
    }

    // Prevent copying and moving of Grades objects
    Grades(const Grades&) = delete;
    Grades(Grades&&) = delete;
    Grades& operator=(const Grades&) = delete;
    Grades& operator=(Grades&&) = delete;
};

