#include <iostream>
#include <iomanip>

using namespace std;

namespace w8 {

    template <class T>
    class DataTable {
        vector<T> independentValues; // Independent variable values
        vector<T> dependentValues;   // Dependent variable values
        int fieldWidth;              // Field width for display
        int decimalPrecision;        // Number of decimal places for display

    public:
        // Initializes the DataTable with values from the provided file stream
        DataTable(ifstream& file, int fw, int nd) : fieldWidth(fw), decimalPrecision(nd) {
            T x, y;

            if (file.is_open()) {
                while (file >> x >> y) {
                    independentValues.push_back(x);
                    dependentValues.push_back(y);
                }
                file.close();
            } else {
                cerr << "Cannot open the data file\n";
                exit(1);
            }
        }

        // Calculates the mean of the dependent variable values
        T mean() const {
            T sum = accumulate(dependentValues.begin(), dependentValues.end(), static_cast<T>(0));
            T count = dependentValues.size();
            return sum / count;
        }

        // Calculates the standard deviation of the dependent variable values
        T sigma() const {
            T meanValue = mean(); // Mean of all values in the data set
            T count = dependentValues.size(); // Number of values in the data set
            T sumSquaredDifferences = 0.0; // Sum of squared differences

            for (int i = 0; i < count; ++i) {
                sumSquaredDifferences += (dependentValues[i] - meanValue) * (dependentValues[i] - meanValue);
            }

            return sqrt(sumSquaredDifferences / (count - 1));
        }

        // Calculates the median of the dependent variable values
        T median() const {
            T count = dependentValues.size();
            vector<T> sortedValues = dependentValues;
            sort(sortedValues.begin(), sortedValues.end());

            return sortedValues[count / 2];
        }

        // Calculates the slope and intercept for the linear regression of the data set
        void regression(T& slope, T& yIntercept) const {
            T count = dependentValues.size(); // Number of values in the data set
            T sumX = accumulate(independentValues.begin(), independentValues.end(), static_cast<T>(0)); // Sum of independent values
            T sumY = accumulate(dependentValues.begin(), dependentValues.end(), static_cast<T>(0)); // Sum of dependent values
            T sumX2 = 0; // Sum of squares of independent values
            T sumXY = 0; // Sum of the product of independent and dependent values

            for (int i = 0; i < count; i++) {
                sumXY += independentValues[i] * dependentValues[i];
                sumX2 += independentValues[i] * independentValues[i];
            }

            slope = (count * sumXY - sumX * sumY) / (count * sumX2 - sumX * sumX);
            yIntercept = (sumY - slope * sumX) / count;
        }

        // Displays the data pairs in a formatted manner
        void display(std::ostream& os) const {
            os << fixed << setprecision(decimalPrecision);
            os << setw(fieldWidth) << right << "x" << setw(fieldWidth) << "y\n";
            for (int i = 0; i < independentValues.size(); i++) {
                os << setw(fieldWidth) << right << independentValues[i] << setw(fieldWidth) << dependentValues[i] << "\n";
            }
        }
    };

    // Overloads the output stream operator to display the DataTable
    template <typename T>
    std::ostream& operator<<(std::ostream& os, const DataTable<T>& dataTable) {
        dataTable.display(os);
        return os;
    }

} // namespace w8

