#ifndef RAPIDXML_ITERATORS_HPP_INCLUDED
#define RAPIDXML_ITERATORS_HPP_INCLUDED

#include "rapidxml.hpp"

namespace rapidxml
{

    //! Iterator for traversing child nodes of an xml_node
    template<class Ch>
    class NodeIterator
    {
    public:
        using value_type = xml_node<Ch>;
        using reference = xml_node<Ch>&;
        using pointer = xml_node<Ch>*;
        using difference_type = std::ptrdiff_t;
        using iterator_category = std::bidirectional_iterator_tag;

        NodeIterator()
            : m_currentNode(nullptr)
        {
        }

        NodeIterator(xml_node<Ch>* node)
            : m_currentNode(node->first_node())
        {
        }

        reference operator*() const
        {
            assert(m_currentNode);
            return *m_currentNode;
        }

        pointer operator->() const
        {
            assert(m_currentNode);
            return m_currentNode;
        }

        NodeIterator& operator++()
        {
            assert(m_currentNode);
            m_currentNode = m_currentNode->next_sibling();
            return *this;
        }

        NodeIterator operator++(int)
        {
            NodeIterator temp = *this;
            ++(*this);
            return temp;
        }

        NodeIterator& operator--()
        {
            assert(m_currentNode && m_currentNode->previous_sibling());
            m_currentNode = m_currentNode->previous_sibling();
            return *this;
        }

        NodeIterator operator--(int)
        {
            NodeIterator temp = *this;
            --(*this);
            return temp;
        }

        bool operator==(const NodeIterator<Ch>& rhs) const
        {
            return m_currentNode == rhs.m_currentNode;
        }

        bool operator!=(const NodeIterator<Ch>& rhs) const
        {
            return m_currentNode != rhs.m_currentNode;
        }

    private:
        xml_node<Ch>* m_currentNode;
    };

    //! Iterator for traversing child attributes of an xml_node
    template<class Ch>
    class AttributeIterator
    {
    public:
        using value_type = xml_attribute<Ch>;
        using reference = xml_attribute<Ch>&;
        using pointer = xml_attribute<Ch>*;
        using difference_type = std::ptrdiff_t;
        using iterator_category = std::bidirectional_iterator_tag;

        AttributeIterator()
            : m_currentAttribute(nullptr)
        {
        }

        AttributeIterator(xml_node<Ch>* node)
            : m_currentAttribute(node->first_attribute())
        {
        }

        reference operator*() const
        {
            assert(m_currentAttribute);
            return *m_currentAttribute;
        }

        pointer operator->() const
        {
            assert(m_currentAttribute);
            return m_currentAttribute;
        }

        AttributeIterator& operator++()
        {
            assert(m_currentAttribute);
            m_currentAttribute = m_currentAttribute->next_attribute();
            return *this;
        }

        AttributeIterator operator++(int)
        {
            AttributeIterator temp = *this;
            ++(*this);
            return temp;
        }

        AttributeIterator& operator--()
        {
            assert(m_currentAttribute && m_currentAttribute->previous_attribute());
            m_currentAttribute = m_currentAttribute->previous_attribute();
            return *this;
        }

        AttributeIterator operator--(int)
        {
            AttributeIterator temp = *this;
            --(*this);
            return temp;
        }

        bool operator==(const AttributeIterator<Ch>& rhs) const
        {
            return m_currentAttribute == rhs.m_currentAttribute;
        }

        bool operator!=(const AttributeIterator<Ch>& rhs) const
        {
            return m_currentAttribute != rhs.m_currentAttribute;
        }

    private:
        xml_attribute<Ch>* m_currentAttribute;
    };

}

#endif

#ifndef RAPIDXML_UTILS_HPP_INCLUDED

#define RAPIDXML_UTILS_HPP_INCLUDED

#include "rapidxml.hpp"
#include <vector>
#include <string>
#include <fstream>
#include <stdexcept>

namespace rapidxml
{

    //! Class to manage file loading and data storage
    template<class Ch = char>
    class FileLoader
    {
    public:
        //! Constructs a FileLoader by loading data from a specified file
        //! \param filename The name of the file to load
        FileLoader(const char *filename)
        {
            using namespace std;

            // Open the file stream in binary mode
            basic_ifstream<Ch> fileStream(filename, ios::binary);
            if (!fileStream)
                throw runtime_error(string("Cannot open file: ") + filename);
            fileStream.unsetf(ios::skipws);

            // Determine the size of the file
            fileStream.seekg(0, ios::end);
            size_t fileSize = fileStream.tellg();
            fileStream.seekg(0);

            // Load data into memory and append a null terminator
            m_data.resize(fileSize + 1);
            fileStream.read(&m_data.front(), static_cast<streamsize>(fileSize));
            m_data[fileSize] = 0;
        }

        //! Constructs a FileLoader by loading data from a provided input stream
        //! \param stream The input stream to read data from
        FileLoader(std::basic_istream<Ch> &stream)
        {
            using namespace std;

            // Load data from the stream and append a null terminator
            stream.unsetf(ios::skipws);
            m_data.assign(istreambuf_iterator<Ch>(stream), istreambuf_iterator<Ch>());
            if (stream.fail() || stream.bad())
                throw runtime_error("Error reading from stream");
            m_data.push_back(0);
        }

        //! Retrieves the loaded file data
        //! \return Pointer to the file data
        Ch *data()
        {
            return &m_data.front();
        }

        //! Retrieves the loaded file data
        //! \return Pointer to the file data
        const Ch *data() const
        {
            return &m_data.front();
        }

        //! Retrieves the size of the loaded file data
        //! \return Size of the file data in characters
        std::size_t size() const
        {
            return m_data.size();
        }

    private:
        std::vector<Ch> m_data; // Container for file data
    };

    //! Counts the number of child nodes for a given XML node
    //! \return The total number of child nodes
    template<class Ch>
    inline std::size_t countChildren(xml_node<Ch> *node)
    {
        xml_node<Ch> *childNode = node->first_node();
        std::size_t childCount = 0;

        // Iterate through child nodes
        while (childNode)
        {
            ++childCount;
            childNode = childNode->next_sibling();
        }
        return childCount;
    }

    //! Counts the number of attributes for a given XML node
    //! \return The total number of attributes
    template<class Ch>
    inline std::size_t countAttributes(xml_node<Ch> *node)
    {
        xml_attribute<Ch> *attribute = node->first_attribute();
        std::size_t attributeCount = 0;

        // Iterate through attributes
        while (attribute)
        {
            ++attributeCount;
            attribute = attribute->next_attribute();
        }
        return attributeCount;
    }

}

#endif

