#ifndef LINKEDLIST_H_
#define LINKEDLIST_H_

#include <iostream>
#include <string>
#include "MyClass.h"
#include "Node.h"

using namespace std;

template <typename T>
class LinkedList : public Node<T> {
public:
    Node<T>* head;

    // Khởi tạo danh sách liên kết rỗng
    LinkedList() : head(nullptr) {}

    // Khởi tạo danh sách với một nút đầu tiên chứa dữ liệu
    LinkedList(T data) {
        head = new Node<T>(data);
    }

    // Lấy dữ liệu của nút đầu tiên khớp với giá trị so sánh
    T getNodeData(T datacompare) {
        Node<T>* currentNode = head;
        while (currentNode != nullptr) {
            if (currentNode->data == datacompare) {
                return currentNode->data;
            }
            currentNode = currentNode->next;
        }
    }

    // Thêm nút mới vào danh sách theo thứ tự
    Node<T>* addNode(T adddata) {
        Node<T>* currentNode = head;
        Node<T>* newNode = new Node<T>(adddata);

        while (currentNode != nullptr) {
            // Xử lý trường hợp danh sách rỗng hoặc nút đầu tiên
            if (currentNode->prev == nullptr && currentNode->next == nullptr) {
                if (currentNode->data < adddata) {
                    newNode->prev = currentNode;
                    currentNode->next = newNode;
                    return newNode;
                } else {
                    currentNode->prev = newNode;
                    newNode->next = currentNode;
                    head = newNode;
                    return newNode;
                }
            } else {
                // Chèn nút mới vào vị trí thích hợp
                if (adddata < currentNode->data) {
                    Node<T>* previousNode = currentNode->prev;
                    currentNode->prev = newNode;
                    newNode->next = currentNode;

                    if (previousNode == nullptr) {
                        newNode->prev = nullptr;
                        head = newNode;
                    } else {
                        previousNode->next = newNode;
                        newNode->prev = previousNode;
                    }
                    return newNode;
                }
            }
            currentNode = currentNode->next;
        }

        // Thêm nút mới vào cuối danh sách
        currentNode = head;
        while (currentNode->next != nullptr) {
            currentNode = currentNode->next;
        }
        currentNode->next = newNode;
        newNode->prev = currentNode;
        return newNode;
    }

    // Xóa nút chứa dữ liệu đã cho
    void deleteNode(T deletedata) {
        Node<T>* currentNode = head;
        while (currentNode != nullptr) {
            if (currentNode->data == deletedata) {
                // Xử lý trường hợp nút đầu tiên
                if (currentNode->prev == nullptr) {
                    Node<T>* nodeToDelete = currentNode;
                    currentNode->next->prev = nullptr;
                    head = currentNode->next;
                    delete nodeToDelete;
                    return;
                }
                // Xử lý trường hợp nút cuối cùng
                else if (currentNode->next == nullptr) {
                    Node<T>* nodeToDelete = currentNode;
                    currentNode->prev->next = nullptr;
                    delete nodeToDelete;
                    return;
                }
                // Xử lý trường hợp nút ở giữa
                else {
                    Node<T>* nodeToDelete = currentNode;
                    currentNode->prev->next = nodeToDelete->next;
                    currentNode->next->prev = nodeToDelete->prev;
                    delete nodeToDelete;
                    return;
                }
            }
            currentNode = currentNode->next;
        }
    }

    // In ra tất cả dữ liệu trong danh sách
    void print() {
        Node<T>* currentNode = head;
        while (currentNode != nullptr) {
            cout << currentNode->data << "  ";
            currentNode = currentNode->next;
        }
        cout << endl;
    }

    // Giải phóng bộ nhớ khi danh sách bị hủy
    virtual ~LinkedList() {
        Node<T>* currentNode = head;
        while (currentNode != nullptr) {
            Node<T>* nextNode = currentNode->next;
            delete currentNode;
            currentNode = nextNode;
        }
    }
};

#endif

