#ifndef NODE_H_
#define NODE_H_

#include <iostream>
#include <string>

using namespace std;

template <typename T>
class Node {
public:
    Node<T>* previous; // Pointer to the previous node
    Node<T>* next;     // Pointer to the next node
    T value;          // Data stored in the node

    // Default constructor
    Node() : previous(nullptr), next(nullptr) {}

    // Parameterized constructor
    Node(T inputValue) : previous(nullptr), next(nullptr), value(inputValue) {}

    virtual ~Node() {}

    // Set the next node pointer
    void setNext(Node<T>* currentNode, Node<T>* nextNode) {
        currentNode->next = nextNode;
    }

    // Set the previous node pointer
    void setPrev(Node<T>* currentNode, Node<T>* prevNode) {
        currentNode->previous = prevNode;
    }

    // Retrieve the next node
    Node<T>* getNext(Node<T>* currentNode) {
        return currentNode->next;
    }

    // Retrieve the previous node
    Node<T>* getPrev(Node<T>* currentNode) {
        return currentNode->previous;
    }

    // Retrieve the data stored in the current node
    T getValue(Node<T>* currentNode) {
        return currentNode->value;
    }
};

#endif

