void Library::updateBookQuantity(char bookId[], int branch, int operation) {
    int index = 0, count = 0;
    fstream bookFile("Booksdata.txt", ios::in | ios::out | ios::ate | ios::binary);
    bookFile.seekg(0);
    bookFile.read((char*)this, sizeof(*this));

    while (!bookFile.eof()) {
        for (index = 0; branch == branchId && publication[index] != '\0' && bookId[index] != '\0' && bookId[index] == publication[index]; index++);

        if (publication[index] == '\0' && bookId[index] == '\0') {
            count++;
            if (operation == 1)
                quantity--;
            else
                quantity++;
            bookFile.seekp(bookFile.tellp() - sizeof(*this));
            bookFile.write((char*)this, sizeof(*this));
            break;
        }
        bookFile.read((char*)this, sizeof(*this));
    }

    if (count == 0) {
        cout << "\n\t\t\tBook Not Found!\n\t\t\t";
        system("PAUSE");
        system("cls");
        issueBook();
    }

    bookFile.close();
}

void Library::calculateFine(int day, int month, int year, int returnDay, int returnMonth, int returnYear) {
    long int totalDays1, totalDays2;
    int years, leapDays, i;
    const int monthDays[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    totalDays1 = year * 365 + day;
    for (i = 0; i < month - 1; i++)
        totalDays1 += monthDays[i];

    years = year;
    if (month <= 2)
        years--;

    leapDays = years / 4 - years / 100 + years / 400;
    totalDays1 += leapDays;

    totalDays2 = returnYear * 365 + returnDay;
    for (i = 0; i < returnMonth - 1; i++)
        totalDays2 += monthDays[i];

    years = returnYear;
    if (returnMonth <= 2)
        years--;

    leapDays = years / 4 - years / 100 - years / 400;
    totalDays2 += leapDays;

    totalDays1 = totalDays2 - totalDays1;
    totalDays2 = totalDays1 - 15;

    if (totalDays2 > 0)
        cout << "\n\t\t\tTotal fine is: " << totalDays2 << endl;
}

