bool Book::CheckISBN(const string& ISBN) {
    if (IsEmpty(ISBN)) {
        return false;
    }

    if (ISBN.length() != 13) {
        cerr << "\nMa ISBN gom 13 chu so !";
        return false;
    }

    string prefix = ISBN.substr(0, 3);
    if (prefix != _EAN_13 && prefix != EAN_13) {
        cerr << "\nMa ISBN-13 bat dau bang 978 hoac 979 !";
        return false;
    }

    for (char digit : ISBN) {
        if (digit < '0' || digit > '9') {
            cerr << "\nMa ISBN phai la nhung chu so 0-9 !";
            return false;
        }
    }
    return true;
}

bool Book::CheckBookCode(const string& code) {
    for (char digit : code) {
        if (digit < '0' || digit > '9') {
            cerr << "\nMa Sach phai la nhung chu so 0-9 !";
            return false;
        }
    }
    return true;
}

bool Book::IsVNBook(const string& ISBN) {
    return CheckISBN(ISBN) && (ISBN.substr(3, 3) == ISBN_VN);
}

