#include "Date.h"

// Class representing a date with day, month, and year attributes.
Date::Date() {
    d = 1;
    m = 1;
    y = 1900;
}

// Constructor that initializes the date with specified day, month, and year.
Date::Date(int day, int month, int year) {
    d = day;
    m = month;
    y = year;
    validateAndFixDate();
}

// Copy constructor for creating a date from another date instance.
Date::Date(const Date& date) {
    d = date.d;
    m = date.m;
    y = date.y;
}

// Checks if the current year is a leap year.
bool Date::isLeapYear() {
    if (y % 4 == 0) {
        if (y % 100 == 0) {
            return (y % 400 == 0);
        }
        return true;
    }
    return false;
}

// Validates and corrects the date attributes if they are out of range.
bool Date::validateAndFixDate() {
    bool isValid = true;

    if (y < 1900) {
        y = 1900;
        isValid = false;
    }

    if (m < 1 || m > 12) {
        m = 1;
        isValid = false;
    }

    if (d < 1 || d > 31) {
        d = 1;
        isValid = false;
    } else {
        switch (m) {
            case 2:
                if (isLeapYear()) {
                    if (d > 29) {
                        d = 29;
                        isValid = false;
                    }
                } else {
                    if (d > 28) {
                        d = 28;
                        isValid = false;
                    }
                }
                break;
            case 4: case 6: case 9: case 11:
                if (d > 30) {
                    d = 30;
                    isValid = false;
                }
                break;
            default:
                break;
        }
    }

    return isValid;
}

// Overload input stream operator to read date from input.
istream& operator >> (istream& is, Date& date) {
    char separator;
    is >> date.d;
    if (is.fail())
        throw "Input data is not a number";
    is >> separator;
    is >> date.m;
    if (is.fail())
        throw "Input data is not a number";
    is >> separator;
    is >> date.y;
    if (is.fail())
        throw "Input data is not a number";
    return is;
}

// Overload output stream operator to display date.
ostream& operator << (ostream& os, const Date& date) {
    os << date.d << "/" << date.m << "/" << date.y;
    return os;
}

// Overload prefix increment operator to move to the next day.
Date& Date::operator ++ () {
    d++;
    switch (m) {
        case 2:
            if (isLeapYear()) {
                if (d > 29) {
                    d = 1;
                    ++m;
                }
            } else {
                if (d > 28) {
                    d = 1;
                    ++m;
                }
            }
            break;
        case 4: case 6: case 9: case 11:
            if (d > 30) {
                d = 1;
                ++m;
            }
            break;
        default:
            if (d > 31) {
                d = 1;
                ++m;
            }
            break;
    }
    if (m > 12) {
        m = 1;
        ++y;
    }
    return *this;
}

// Overload prefix decrement operator to move to the previous day.
Date& Date::operator -- () {
    d--;
    if (d == 0) {
        --m;
        switch (m) {
            case 2:
                d = isLeapYear() ? 29 : 28;
                break;
            case 4: case 6: case 9: case 11:
                d = 30;
                break;
            default:
                d = 31;
                break;
        }
    }

    if (m == 0) {
        m = 12;
        --y;
    }
    return *this;
}

// Overload addition assignment operator to add days to the date.
Date& Date::operator += (int daysToAdd) {
    for (int i = 0; i < daysToAdd; ++i)
        ++(*this);
    return *this;
}

// Overload subtraction assignment operator to subtract days from the date.
Date& Date::operator -= (int daysToSubtract) {
    for (int i = 0; i < daysToSubtract; ++i)
        --(*this);
    return *this;
}

// Overload greater than operator to compare two dates.
bool Date::operator > (const Date& date) {
    if (y > date.y)
        return true;
    if (y == date.y) {
        if (m > date.m)
            return true;
        if (m == date.m) {
            return d > date.d;
        }
    }
    return false;
}

// Overload greater than or equal operator to compare two dates.
bool Date::operator >= (const Date& date) {
    return (*this > date) || (*this == date);
}

// Overload less than operator to compare two dates.
bool Date::operator < (const Date& date) {
    return !(*this >= date);
}

// Overload less than or equal operator to compare two dates.
bool Date::operator <= (const Date& date) {
    return !(*this > date);
}

// Overload equality operator to check if two dates are equal.
bool operator== (const Date& d1, const Date& d2) {
    return d1.d == d2.d && d1.m == d2.m && d1.y == d2.y;
}

// Overload subtraction operator to calculate the difference in days between two dates.
int operator- (Date d1, Date d2) {
    if (d1 == d2)
        return 0;

    int daysCount = 1;
    if (d1 > d2) {
        while (true) {
            --d1;
            if (d1 == d2)
                return daysCount;
            ++daysCount;
        }
    } else {
        while (true) {
            --d2;
            if (d1 == d2)
                return daysCount;
            ++daysCount;
        }
    }
}

