#include <iostream>
using namespace std;

class ComplexNumber {
public:
    float realPart, imaginaryPart;

    ComplexNumber operator+(const ComplexNumber& other);
    ComplexNumber operator-(const ComplexNumber& other);
    ComplexNumber operator*(const ComplexNumber& other);
    ComplexNumber operator/(const ComplexNumber& other);
    void display() const;
};

// Adds two complex numbers
ComplexNumber ComplexNumber::operator+(const ComplexNumber& other) {
    ComplexNumber result;
    result.realPart = realPart + other.realPart;
    result.imaginaryPart = imaginaryPart + other.imaginaryPart;
    return result;
}

// Subtracts one complex number from another
ComplexNumber ComplexNumber::operator-(const ComplexNumber& other) {
    ComplexNumber result;
    result.realPart = realPart - other.realPart;
    result.imaginaryPart = imaginaryPart - other.imaginaryPart;
    return result;
}

// Multiplies two complex numbers
ComplexNumber ComplexNumber::operator*(const ComplexNumber& other) {
    ComplexNumber result;
    result.realPart = realPart * other.realPart - imaginaryPart * other.imaginaryPart;
    result.imaginaryPart = realPart * other.imaginaryPart + other.realPart * imaginaryPart;
    return result;
}

// Divides one complex number by another
ComplexNumber ComplexNumber::operator/(const ComplexNumber& other) {
    ComplexNumber result, temp;
    int denominator;
    temp.realPart = realPart * other.realPart - imaginaryPart * other.imaginaryPart;
    temp.imaginaryPart = realPart * other.imaginaryPart + other.realPart * imaginaryPart;
    denominator = other.realPart * other.realPart + other.imaginaryPart * other.imaginaryPart;
    result.realPart = temp.realPart / denominator;
    result.imaginaryPart = temp.imaginaryPart / denominator;
    return result;
}

// Displays the complex number in the format a + bi
void ComplexNumber::display() const {
    cout << realPart << "+i" << imaginaryPart << "\n";
}

int main() {
    int repeatChoice, operationChoice;
    ComplexNumber firstComplex, secondComplex, resultComplex;

    do {
        cout << "Enter first complex number (real and imaginary parts):\n";
        cin >> firstComplex.realPart >> firstComplex.imaginaryPart;
        cout << "Enter second complex number (real and imaginary parts):\n";
        cin >> secondComplex.realPart >> secondComplex.imaginaryPart;

        do {
            cout << "Select operation:\n1. Add\n2. Subtract\n3. Multiply\n4. Divide\n";
            cin >> operationChoice;

            switch (operationChoice) {
                case 1: 
                    resultComplex = firstComplex + secondComplex;
                    resultComplex.display();
                    break;
                case 2: 
                    resultComplex = firstComplex - secondComplex;
                    resultComplex.display();
                    break;
                case 3: 
                    resultComplex = firstComplex * secondComplex;
                    resultComplex.display();
                    break;
                case 4: 
                    resultComplex = firstComplex / secondComplex;
                    resultComplex.display();
                    break;
                default: 
