#include <iostream>
#include <cmath>

using namespace std;

class QuadraticEquation {
    int coefficientA, coefficientB, coefficientC, inputX;

public:
    QuadraticEquation() : coefficientA(0), coefficientB(0), coefficientC(0) {}

    QuadraticEquation(int a, int b, int c) : coefficientA(a), coefficientB(b), coefficientC(c) {}

    friend ostream& operator<<(ostream& out, const QuadraticEquation& equation);
    friend istream& operator>>(istream& in, QuadraticEquation& equation);
    QuadraticEquation operator+(const QuadraticEquation& other);
    void evaluate();
    void calculateRoots();
};

ostream& operator<<(ostream& out, const QuadraticEquation& equation) {
    out << "\nQuadratic equation is: ";
    out << equation.coefficientA << " X^2 + " << equation.coefficientB << " X + " << equation.coefficientC;
    return out;
}

istream& operator>>(istream& in, QuadraticEquation& equation) {
    cout << "\nEnter values for coefficients a, b, c of the quadratic equation:\n";
    in >> equation.coefficientA >> equation.coefficientB >> equation.coefficientC;
    return in;
}

void QuadraticEquation::evaluate() {
    cout << "\nEnter value for x:\n";
    cin >> inputX;
    int result = (coefficientA * inputX * inputX) + (coefficientB * inputX) + coefficientC;
    cout << "\nFor x = " << inputX << ", the result is: " << result << endl;
}

void QuadraticEquation::calculateRoots() {
    int discriminant = (coefficientB * coefficientB) - (4 * coefficientA * coefficientC);

    if (discriminant > 0) {
        float root1 = (-coefficientB + sqrt(discriminant)) / (2.0f * coefficientA);
        float root2 = (-coefficientB - sqrt(discriminant)) / (2.0f * coefficientA);
        cout << "\nRoots are real and different.";
        cout << "\nRoot 1 = " << root1;
        cout << "\nRoot 2 = " << root2;
    } else if (discriminant == 0) {
        cout << "\nRoots are real and equal.";
        float equalRoot = (-coefficientB + sqrt(discriminant)) / (2.0f * coefficientA);
        cout << "\nEqual Roots = " << equalRoot;
    } else {
        cout << "\nRoots are complex and different." << endl;
        float realPart = -coefficientB / (2 * coefficientA);
        float imaginaryPart = sqrt(-discriminant) / (2 * coefficientA);
        cout << "Root 1 = " << realPart << " + " << imaginaryPart << "i" << endl;
        cout << "Root 2 = " << realPart << " - " << imaginaryPart << "i" << endl;
    }
}

QuadraticEquation QuadraticEquation::operator+(const QuadraticEquation& other) {
    return QuadraticEquation(coefficientA + other.coefficientA, 
                             coefficientB + other.coefficientB, 
                             coefficientC + other.coefficientC);
}

int main() {
    QuadraticEquation equation1, equation2, equation3;
    cin >> equation1;
    cin >> equation2;
    equation3 = equation1 + equation2;

    cout << "\nQuadratic equation 1, its roots and evaluation:\n";
    cout << equation1;
    equation1.calculateRoots();
    equation1.evaluate();

    cout << "\nQuadratic equation 2, its roots and evaluation:\n";
    cout << equation2;
    equation2.calculateRoots();
    equation2.evaluate();

    cout << "\nQuadratic equation 3, its roots and evaluation:\n";
    equation3.calculateRoots();
    equation3.evaluate();

    return 0;
}

#ifndef VECTOR_H

#define VECTOR_H

#include <iostream>
#include <fstream>
#include <stdexcept>
#include <vector>

/**
 * A vector class for managing a 1D array of doubles.
 * Inherits from std::vector to leverage its functionality while exposing only necessary operations.
 * 
 * The Vector class provides:
 * - Constructors for creating a vector from another vector or initializing an empty vector of a specified size.
 * - Input and output operations using >> and << operators for keyboard and file interactions.
 * - Basic operations including element access, assignment, and comparison.
 */
class Vector : public std::vector<double> {
    using BaseVector = std::vector<double>;

public:
    // CONSTRUCTORS

    /**
     * Default constructor. Initializes an empty Vector object.
     */
    Vector();

    /**
     * Explicit constructor that initializes a Vector object of a specified size.
     * @param size Size of the vector.
     * @exception std::invalid_argument if the size is negative.
     */
    explicit Vector(int size);

    /**
     * Copy constructor. Initializes a Vector object with another Vector object.
     * @param other Vector to copy from.
     */
    Vector(const Vector& other);

    // OVERLOADED OPERATORS

    /**
     * Overloaded assignment operator.
     * @param other Vector to assign from.
     * @return Reference to the current object.
     */
    Vector& operator=(const Vector& other);

    /**
     * Overloaded comparison operator.
     * Compares two vectors for equality within a specified tolerance.
     * @param other Vector to compare with.
     * @return true if vectors are equal within tolerance, false otherwise.
     * @exception std::invalid_argument if vector sizes are incompatible.
     */
    bool operator==(const Vector& other) const;

    // ACCESSOR METHODS

    /**
     * Returns the size of the vector.
     * @return Size of the vector.
     */
    int getSize() const;

    // NORM CALCULATIONS

    /**
     * Calculates and returns the L1 norm of the vector.
     * @return L1 norm of the vector.
     */
    double one_norm();

    /**
     * Calculates and returns the L2 norm of the vector.
     * @return L2 norm of the vector.
     */
    double two_norm();

    /**
     * Calculates and returns the L_max norm of the vector.
     * @return L_max norm of the vector.
     * @exception std::out_of_range if the vector is empty.
     */
    double uniform_norm();

    // INPUT AND OUTPUT OPERATORS

    /**
     * Overloaded input operator for keyboard input.
     * Prompts user for vector values or initializes size if the vector is empty.
     * @param is Input stream for user input.
     * @param v Vector to populate with input values.
     * @return Input stream object.
     * @exception std::invalid_argument if the input size is negative.
     */
    friend std::istream& operator>>(std::istream& is, Vector& v);

    /**
     * Overloaded output operator for displaying vector values.
     * @param os Output stream for displaying vector.
     * @param v Vector to read from.
     * @return Output stream object.
     */
    friend std::ostream& operator<<(std::ostream& os, const Vector& v);

    /**
     * Overloaded input operator for file input.
     * Reads vector values from a file.
     * @param ifs Input file stream.
     * @param v Vector to populate with input values.
     * @return Input file stream object.
     * @exception std::invalid_argument if the input size is negative.
     */
    friend std::ifstream& operator>>(std::ifstream& ifs, Vector& v);

    /**
     * Overloaded output operator for file output.
     * Writes vector values to a file.
     * @param ofs Output file stream.
     * @param v Vector to write to the file.
     * @return Output file stream object.
     */
    friend std::ofstream& operator<<(std::ofstream& ofs, const Vector& v);
};

#endif

