// Setters and Getters for date components
void Date::setDate(short unsigned int dayValue) {
    date = dayValue;
}

void Date::setMonth(short unsigned int monthValue) {
    month = monthValue;
}

void Date::setYear(short unsigned int yearValue) {
    year = yearValue;
}

short unsigned int Date::getDate() const {
    return date;
}

short unsigned int Date::getMonth() const {
    return month;
}

short unsigned int Date::getYear() const {
    return year;
}

std::string Date::getDay() const {
    return day;
}

// Calculate the day of the week based on the current date
void Date::calculateDay() {
    time_t currentTime;
    time(&currentTime);

    tm currentTimeStruct;
    currentTimeStruct = *(localtime(&currentTime));
    short unsigned int currentDayOfWeek = currentTimeStruct.tm_wday;
    sanitize(currentTimeStruct);

    tm storedTimeStruct;
    convertToStruct(storedTimeStruct);

    short unsigned int dayDifference;
    short int dayOfWeek;

    if (mktime(&currentTimeStruct) >= mktime(&storedTimeStruct)) {
        dayDifference = static_cast<short unsigned int>(difftime(mktime(&currentTimeStruct), mktime(&storedTimeStruct)) / (60 * 60 * 24));
        dayOfWeek = currentDayOfWeek - (dayDifference % 7);
        if (dayOfWeek < 0) {
            dayOfWeek += 7;
        }
    } else {
        dayDifference = static_cast<short unsigned int>(difftime(mktime(&storedTimeStruct), mktime(&currentTimeStruct)) / (60 * 60 * 24));
        dayOfWeek = currentDayOfWeek + (dayDifference % 7);
        if (dayOfWeek > 6) {
            dayOfWeek -= 7;
        }
    }

    // Map the day of the week to its string representation
    switch (dayOfWeek) {
        case 0: day = "Sunday"; break;
        case 1: day = "Monday"; break;
        case 2: day = "Tuesday"; break;
        case 3: day = "Wednesday"; break;
        case 4: day = "Thursday"; break;
        case 5: day = "Friday"; break;
        case 6: day = "Saturday"; break;
    }
}

// Convert the day string to an integer representation
short unsigned int Date::getDayAsInt() const {
    if (day == "Monday") return 0;
    if (day == "Tuesday") return 1;
    if (day == "Wednesday") return 2;
    if (day == "Thursday") return 3;
    if (day == "Friday") return 4;
    if (day == "Saturday") return 5;
    if (day == "Sunday") return 6;
    return 7; // Invalid day
}

// Sanitize the tm structure by resetting unnecessary fields
void Date::sanitize(tm& timeStruct) {
    timeStruct.tm_sec = timeStruct.tm_min = timeStruct.tm_hour = timeStruct.tm_wday = timeStruct.tm_yday = timeStruct.tm_isdst = 0;
    timeStruct.tm_gmtoff = 0;
    timeStruct.tm_zone = "";
}

// Set the current date to today's date
void Date::setToday() {
    time_t currentTime;
    time(&currentTime);

    tm currentTimeStruct;
    currentTimeStruct = *(localtime(&currentTime));

    convertFromStruct(currentTimeStruct);
    calculateDay();
}

// Convert the date components to a tm structure
void Date::convertToStruct(tm& timeStruct) {
    timeStruct.tm_mday = date;
    timeStruct.tm_mon = month - 1;
    timeStruct.tm_year = year - 1900;

    sanitize(timeStruct);
}

// Convert a tm structure back to date components
void Date::convertFromStruct(const tm& timeStruct) {
    date = timeStruct.tm_mday;
    month = timeStruct.tm_mon + 1;
    year = timeStruct.tm_year + 1900;
}

// Write the date information to a file
void Date::writeToFile(std::ofstream& outputFile) {
    outputFile << std::endl << day << std::endl << date << std::endl << month << std::endl << year;
}

// Read the date information from a file
void Date::readFromFile(std::ifstream& inputFile) {
    getline(inputFile, day);
    inputFile >> date; inputFile.get();
    inputFile >> month; inputFile.get();
    inputFile >> year; inputFile.get();
}

// Compare two Date objects for equality
bool Date::operator==(const Date& other) const {
    return (date == other.date) && (month == other.month) && (year == other.year);
}

// Compare if the current date is less than another date
bool Date::operator<(const Date& other) const {
    if (year < other.year) return true;
    if (year == other.year && month < other.month) return true;
    return (year == other.year && month == other.month && date < other.date);
}

// Compare if the current date is greater than another date
bool Date::operator>(const Date& other) const {
    if (year > other.year) return true;
    if (year == other.year && month > other.month) return true;
    return (year == other.year && month == other.month && date > other.date);
}

// Compare if the current date is less than or equal to another date
bool Date::operator<=(const Date& other) const {
    return (*this < other || *this == other);
}

// Compare if the current date is greater than or equal to another date
bool Date::operator>=(const Date& other) const {
    return (*this > other || *this == other);
}

// Increment the date by one day
Date Date::operator++() {
    date++;

    if (month == 2 && ((year % 4 && date == 29) || (!(year % 4) && date == 30))) {
        date = 1;
        month++;
    } else if ((month == 4 || month == 6 || month == 9 || month == 11) && date == 31) {
        date = 1;
        month++;
    } else if ((month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12) && date == 32) {
        date = 1;
        month++;
    }

    if (month == 13) {
        month = 1;
        year++;
    }

    calculateDay();
    return *this;
}

