#pragma once
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

class CreateCommand : public Useful, RemoveSpaces, Parse, DataManipCommands {
    string commandInput = "";
    string newCommand;
    char* columnName = nullptr;
    char* tableName = nullptr;
    int tableNameSize = 0;
    char* indexName = nullptr;
    char* columnList = nullptr;
    int defaultIntValue;
    float defaultFloatValue;
    char* defaultTextValue = nullptr;
    string dataType = "";
    string columnDataList = "";
    static const int minTableNameLength;
    bool tableExists = false;
    int currentColumnIndex;
    int totalColumns;

public:
    // Verifies if the specified table exists
    bool verifyTableExists(char* tableName) {
        bool exists = this->Useful::verifyIfExists(this->tableName);
        cout << "Searching for the table...";
        return exists;
    }

    // Removes spaces from the command input
    void trimSpaces(string newCommand) {
        this->RemoveSpaces::removeSpaces(this->newCommand);
        cout << "Spaces removed.";
    }

    // Writes the command data to a file
    void writeToFile() {
        string fileName = string(this->tableName) + ".txt";
        ofstream outputFile(fileName, ios::out | ios::app);
        if (outputFile.is_open()) {
            string delimiters{ "()," };
            int startPos, currentPos = 0, columnCount = 1;

            while ((startPos = this->columnDataList.find_first_not_of(delimiters, currentPos)) != string::npos) {
                if (columnCount <= 4) {
                    currentPos = this->columnDataList.find_first_of(delimiters, startPos + 1);
                    outputFile << this->columnDataList.substr(startPos, currentPos - startPos);
                    if (columnCount < 4) {
                        outputFile << " ";
                    }
                    columnCount++;
                }
                if (columnCount == 5 && this->currentColumnIndex < this->totalColumns) {
                    columnCount = 1;
                    outputFile << endl;
                }
            }
        } else {
            cout << endl << "The file was not created";
        }
        outputFile.close();
    }

    // Saves the table names to a report file
    void saveTableNames() {
        ofstream report("listOfTables.txt", ios::app);
        if (report.is_open()) {
            report << this->tableName << '\n';
            report.close();
        } else {
            cout << "The file was not created.";
        }
    }

    // Default constructor
    CreateCommand() {
        this->defaultTextValue = nullptr;
        this->columnName = nullptr;
        this->tableName = nullptr;
        this->tableNameSize = 0;
        this->indexName = nullptr;
        this->columnList = nullptr;
    }

    // Parameterized constructor for table and index creation
    CreateCommand(const char* tableName, int tableNameSize, const char* indexName, const char* columnList) {
        this->tableName = nullptr;
        this->indexName = nullptr;

        if (strlen(indexName) > 1) {
            this->setIndexName(indexName);
            if (strcmp(tableName, "") == 0) {
                this->commandInput = " new CREATE INDEX command";
            }
        } else {
            if (strlen(tableName) > CreateCommand::minTableNameLength) {
                this->setTableName(tableName);
                this->commandInput = " new CREATE TABLE command";
            }
        }
    }

    // Sets the table name with validation
    void setTableName(const char* tableName) {
        if (CreateCommand::minTableNameLength <= strlen(tableName)) {
            if (this->tableName != nullptr) {
                delete[] this->tableName;
            }
            this->tableName = new char[strlen(tableName) + 1];
            strcpy(this->tableName, tableName);
        } else {
            cout << "You need to enter a valid table name" << endl;
        }
    }

    // Sets the index name with validation
    void setIndexName(const char* indexName) {
        if (strlen(indexName) >= CreateCommand::minTableNameLength) {
            if (this->indexName != nullptr) {
                delete[] this->indexName;
            }
            this->indexName = new char[strlen(indexName) + 1];
            strcpy(this->indexName, indexName);
        } else {
            cout << "You need to enter a valid index name" << endl;
        }
    }

    // Sets the column list with validation
    void setColumnList(const char* columnList) {
        if (strlen(columnList) > 1) {
            if (this->columnList != nullptr) {
                delete[] this->columnList;
            }
            this->columnList = new char[strlen(columnList) + 1];
            strcpy(this->columnList, columnList);
        } else {
            cout << "You need to enter a valid column list" << endl;
        }
    }

    // Receives and processes the command input
    void receiveCommand(string command) {
        this->newCommand = command;
        this->commandInput = command;
        parseCommand();
    }

    // Parses the command to extract table or index information
    void parseCommand() {
        int commandSize = this->newCommand.size();
        this->newCommand = this->newCommand.substr(7, commandSize - 7);

        if (this->newCommand.find("TABLE") == 0) {
            commandSize = this->newCommand.size();
            this->newCommand = this->newCommand.substr(6, commandSize - 6);
            commandSize = this->newCommand.size();
            this->tableNameSize = this->newCommand.find_first_of("(") - 1;

            if (this->tableNameSize < 0 || this->tableNameSize >= commandSize || this->tableNameSize < CreateCommand::minTableNameLength) {
                cout << endl << "You need to add the columns";
            } else {
                this->tableName = new char[tableNameSize + 1];
                this->tableName = strcpy(this->tableName, this->newCommand.substr(0, tableNameSize).c_str());
                bool isValid = true;

                for (int i = 0; i < tableNameSize && isValid; i++) {
                    if ((this->tableName[i] < 'a' && this->tableName[i] != '_' && (this->tableName[i] < 48 || this->tableName[i] > 57)) || this->tableName[i] > 'z') {
                        isValid = false;
                        break;
                    }
                }

                if (!isValid) {
                    cout << "The name you entered isn't correct";
                } else {
                    if (verifyTableExists(this->tableName)) {
                        cout << "This table already exists";
                    } else {
                        string name = string(this->tableName);
                        this->newCommand = this->newCommand.substr(tableNameSize + 1, commandSize);
                        trimSpaces(this->newCommand);

                        int rightParenthesisPos = this->newCommand.find_last_of(")");
                        int backslashPos = 0;

                        if (this->newCommand.find('\r') != string::npos) {
                            backslashPos = this->newCommand.find('\r');
                            this->newCommand = this->newCommand.substr(0, backslashPos);
                        }

                        if (rightParenthesisPos < this->newCommand.size() - 1) {
                            this->newCommand = this->newCommand.substr(0, rightParenthesisPos);
                        }

                        this->columnList = new char[this->newCommand.size() + 1];
                        strcpy(this->columnList, this->newCommand.c_str());

                        int leftParenthesisCount = 0;
                        int rightParenthesisCount = 0;
                        int commaCount = 0;

                        for (int i = 1; i < strlen(this->columnList) - 1; i++) {
                            if (this->columnList[i] == ',') {
                                commaCount++;
                            }
                            if (this->columnList[i] == '(') {
                                leftParenthesisCount++;
                            }
                            if (this->columnList[i] == ')') {
                                rightParenthesisCount++;
                            }
                        }

                        if (leftParenthesisCount == rightParenthesisCount && ((commaCount + 1) % rightParenthesisCount == 0) && this->columnList[0] == '(' && this->columnList[strlen(this->columnList) - 2] == ')') {
                            if (this->columnList[0] == '(' && this->columnList[strlen(this->columnList) - 1] == ')') {
                                this->columnList[strlen(this->columnList) - 1] = '\0';
                                this->columnList = this->columnList + 1;
                            }

                            string parameters = "";
                            bool invalidInput = true;
                            bool isLastColumn = false;
                            this->totalColumns = strlen(this->columnList) + 1;
                            this->currentColumnIndex = 1;

                            while (invalidInput) {
                                this->columnDataList = string(this->columnList);
                                int firstLeftParenthesis = this->columnDataList.find_first_of('(');
                                int firstRightParenthesis = this->columnDataList.find_first_of(')');
                                int lastRightParenthesis = this->columnDataList.find_last_of(')');

                                if (firstLeftParenthesis == 0) {
                                    parameters = this->columnDataList.substr(1, firstRightParenthesis - 1);
                                }

                                int firstComma = parameters.find_first_of(',');
                                if (this->columnName) {
                                    delete[] this->columnName;
                                }
                                this->columnName = new char[firstComma + 1];
                                strcpy(this->columnName, parameters.substr(0, firstComma).c_str());

                                isValid = true;
                                for (int i = 0; i < strlen(this->columnName) && isValid; i++) {
                                    if ((this->columnName[i] < 'a' && this->columnName[i] != '_' && (this->columnName[i] < 48 || this->columnName[i] > 57)) || this->columnName[i] > 'z') {
                                        isValid = false;
                                        break;
                                    }
                                }

                                if (!isValid) {
                                    cout << "The name you entered for the column isn't correct";
                                    invalidInput = false;
                                } else {
                                    parameters = parameters.substr(firstComma + 1, parameters.size() - firstComma - 1);
                                    firstComma = parameters.find_first_of(',');
                                    this->dataType = parameters.substr(0, firstComma);

                                    if (this->dataType != "text" && this->dataType != "integer" && this->dataType != "float") {
                                        cout << "Wrong type" << endl;
                                        invalidInput = false;
                                    } else {
                                        int length = stoi(parameters.substr(firstComma + 1, parameters.size() - firstComma - 1));
                                        if (this->dataType == "integer") {
                                            parameters = parameters.substr(firstComma + 1, parameters.size() - firstComma - 1);
                                            this->defaultIntValue = stoi(parameters);
                                            this->columnDataList = this->columnDataList.substr(0, lastRightParenthesis + 1);
                                            this->currentColumnIndex += this->columnDataList.size();
                                            this->writeToFile();

                                            if (strlen(this->columnList + lastRightParenthesis + 1) > 0) {
                                                this->currentColumnIndex++;
                                                this->columnList = this->columnList + lastRightParenthesis + 2;

                                                if (this->currentColumnIndex >= length) {
                                                    isLastColumn = true;
                                                }
                                            } else {
                                                this->columnList = nullptr;
                                            }
                                        } else if (this->dataType == "float") {
                                            parameters = parameters.substr(firstComma + 1, parameters.size() - firstComma - 1);
                                            this->defaultFloatValue = stof(parameters);
                                            this->columnDataList = this->columnDataList.substr(0, lastRightParenthesis + 1);
                                            this->currentColumnIndex += this->columnDataList.size();
                                            this->writeToFile();

                                            if (strlen(this->columnList + lastRightParenthesis + 1) > 0) {
                                                this->currentColumnIndex++;
                                                this->columnList = this->columnList + lastRightParenthesis + 2;

                                                if (this->currentColumnIndex >= length) {
                                                    isLastColumn = true;
                                                }
                                            } else {
                                                this->columnList = nullptr;
                                            }
                                        } else if (this->dataType == "text") {
                                            parameters = parameters.substr(firstComma + 1, parameters.size() - firstComma - 1);
                                            if (this->defaultTextValue != nullptr) {
                                                delete[] this->defaultTextValue;
                                            }
                                            this->defaultTextValue = new char[parameters.size() + 1];
                                            strcpy(this->defaultTextValue, parameters.c_str());
                                            this->columnDataList = this->columnDataList.substr(0, lastRightParenthesis + 1);
                                            this->currentColumnIndex += this->columnDataList.size();
                                            this->writeToFile();

                                            if (strlen(this->columnList + lastRightParenthesis + 1) > 0) {
                                                this->columnList = this->columnList + lastRightParenthesis + 2;
                                                this->currentColumnIndex++;

                                                if (this->currentColumnIndex >= this->totalColumns) {
                                                    isLastColumn = true;
                                                }
                                            } else {
                                                this->columnList = nullptr;
                                            }
                                        } else {
                                            cout << "Wrong input";
                                            invalidInput = false;
                                        }

                                        if (this->columnList == nullptr) {
                                            invalidInput = false;
                                            saveTableNames();
                                        } else {
                                            parameters = string(this->columnList);
                                            parameters = parameters.substr(1, parameters.size() - 1);
                                        }
                                    }
                                }
                            }
                        } else {
                            cout << "Wrong column list, try again";
                        }
                    }
                }
            }
        } else if (this->newCommand.find("INDEX") == 0) {
            this->newCommand = this->newCommand.substr(6, commandSize - 6);
            commandSize = newCommand.size();
            this->tableNameSize = this->newCommand.find("ON") - 1;

            if (this->tableNameSize < 0 || this->tableNameSize >= commandSize) {
                cout << endl << "You need to add the column";
            } else {
                this->indexName = new char[this->tableNameSize + 1];
                strcpy(this->indexName, this->newCommand.substr(0, this->tableNameSize).c_str());

                bool isValid = true;
                for (int i = 0; i < this->tableNameSize && isValid; i++) {
                    if ((this->indexName[i] < 'a' && this->indexName[i] != '_' && (this->indexName[i] < 48 || this->indexName[i] > 57)) || this->indexName[i] > 'z') {
                        isValid = false;
                        break;
                    }
                }

                if (!isValid) {
                    cout << "The index name you entered isn't correct";
                } else {
                    cout << this->indexName << endl << "ON" << endl;

                    this->newCommand = this->newCommand.substr(tableNameSize + 4, commandSize);
                    this->tableNameSize = this->newCommand.find("(") - 1;
                    commandSize = this->newCommand.size();

                    if (this->tableNameSize < 0 || this->tableNameSize >= commandSize) {
                        cout << endl << "You need to add the columns";
                    } else {
                        this->tableName = new char[this->tableNameSize + 1];
                        this->tableName = strcpy(this->tableName, this->newCommand.substr(0, this->tableNameSize).c_str());

                        bool isValid = true;
                        for (int i = 0; i < this->tableNameSize && isValid; i++) {
                            if ((this->tableName[i] < 'a' && this->tableName[i] != '_' && (this->tableName[i] < 48 || this->tableName[i] > 57)) || this->tableName[i] > 'z') {
                                isValid = false;
                                break;
                            }
                        }

                        if (!isValid) {
                            cout << "The table name you entered isn't correct";
                        } else {
                            cout << this->tableName << endl;
                            this->newCommand = this->newCommand.substr(this->tableNameSize + 1, commandSize);
                            commandSize = this->newCommand.size();
                            this->columnList = new char[commandSize - 1];
                            strcpy(this->columnList, this->newCommand.substr(1, commandSize - 2).c_str());

                            bool isValid = true;
                            for (int j = 0; (j < (commandSize - 2) && isValid); j++) {
                                if ((this->columnList[j] < 'a' && this->columnList[j] != '_' && (this->columnList[j] < 48 || this->columnList[j] > 57)) || this->columnList[j] > 'z') {
                                    isValid = false;
                                    break;
                                }
                            }

                            if (!isValid) {
                                cout << "The column name you entered isn't correct";
                            } else {
                                if (this->newCommand.find(")") != string::npos) {
                                    cout << this->newCommand << endl;
                                }
                            }
                        }
                    }
                }
            }
        } else {
            cout << "Enter a valid command";
        }
    }

    // Destructor to clean up dynamically allocated memory
    ~CreateCommand() {
        if (this->tableName) {
            delete[] this->tableName;
        }
        if (this->indexName) {
            delete[] this->indexName;
        }
        if (this->columnName) {
            delete[] this->columnName;
        }
        if (this->defaultTextValue) {
            delete[] this->defaultTextValue;
        }
    }

    // Copy constructor
    CreateCommand(const CreateCommand& create) {
        this->tableName = nullptr;
        this->indexName = nullptr;
        this->columnName = nullptr;
        this->defaultTextValue = nullptr;

        if (strcmp(create.tableName, "") != 0) {
            this->setTableName(create.tableName);
        } else if (strcmp(create.indexName, "") != 0) {
            this->setIndexName(create.indexName);
        }

        if (strcmp(create.columnList, "") != 0) {
            this->setColumnList(create.columnList);
        }
    }

    // Overloaded input operator for command input
    friend void operator>>(istream& input, CreateCommand& command);
    // Overloaded output operator for command display
    friend ostream& operator<<(ostream& console, CreateCommand& create);
    // Overloaded equality operator
    friend bool operator==(CreateCommand cc1, CreateCommand cc2);
    // Overloaded greater than or equal operator
    friend bool operator>=(CreateCommand cc1, CreateCommand cc2);

    // Overloaded subscript operator for accessing table name characters
    char& operator[](int index) {
        if (index >= 0 && index < strlen(this->tableName)) {
            return this->tableName[index];
        } else {
            cout << "The index is wrong";
        }
    }

    // Overloaded logical NOT operator to compare table name length
    bool operator!() {
        return strlen(this->tableName) > 12;
    }

    // Overloaded addition assignment operator
    CreateCommand& operator+=(CreateCommand& name) {
        int currentLength = strlen(this->tableName);
        char* temp = new char[currentLength + 1];
        strcpy(temp, this->tableName);

        if (this->tableName) {
            delete[] this->tableName;
        }

        this->tableName = new char[currentLength + strlen(name.tableName) + 1];
        strcpy(this->tableName, temp);
        strcat(this->tableName, name.tableName);
        delete[] temp;

        return *this;
    }

    // Overloaded cast operator to return table name length
    explicit operator int() {
        return strlen(this->tableName);
    }
};

const int CreateCommand::minTableNameLength = 2;

// Overloaded input operator implementation
void operator>>(istream& input, CreateCommand& command) {
    cout << endl << "What would you like to create?" << endl;
    cout << "[ 1 ] table" << endl << "[ 2 ] index" << endl;
    int option;
    cin >> option;

    switch (option) {
        case 1: {
            cout << "Now please enter the name of the table" << endl;
            char buffer[1000];
            input >> buffer;
            if (strlen(buffer) > 1) {
                command.setTableName(buffer);
            }
            cout << "Enter the column list" << endl;
            input >> buffer;
            if (strlen(buffer) > 1) {
                command.setColumnList(buffer);
            }
            cout << "Table created" << endl;
            break;
        }
        case 2: {
            cout << "Now please enter the name of the index" << endl;
            char buffer[1000];
            input >> buffer;
            if (strlen(buffer) > 1) {
                command.setIndexName(buffer);
            }
            cout << "In which table would you like to create the index?" << endl;
            input >> buffer;
            if (strlen(buffer) > 1) {
                command.setTableName(buffer);
            }
            cout << "On which column should the index be placed?" << endl;
            input >> buffer;
            if (strlen(buffer) > 1) {
                command.setColumnList(buffer);
            }
            cout << "Index created" << endl;
            break;
        }
        default: {
            cout << "Please enter a valid option" << endl;
            break;
        }
    }
}

// Overloaded output operator implementation
ostream& operator<<(ostream& console, CreateCommand& create) {
    console << endl << "-------------------------------------";

    if (create.commandInput.find("TABLE") != string::npos && create.tableName != nullptr) {
        console << endl << "The name of the table you have created is: " << create.tableName << endl;
    } else if (create.commandInput.find("INDEX") != string::npos && create.indexName != nullptr) {
        console << endl << "The name of the index you have created is: " << create.indexName << endl;
    }
    return console;
}

// Overloaded equality operator implementation
bool operator==(CreateCommand cc1, CreateCommand cc2) {
    return strcmp(cc1.tableName, cc2.tableName) == 0;
}

// Overloaded greater than or equal operator implementation
bool operator>=(CreateCommand cc1, CreateCommand cc2) {
    return strlen(cc1.tableName) >= strlen(cc2.tableName);
}

#pragma once
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

class DeleteCommand : public Useful, public Parse, public DataManipCommands
{
    char* columnName;
    string initialCommand;
    static const int minTableNameLength;
    char* value;

public:
    // Verifies if the specified table exists
    bool verifyIfExists(char* tableName) {
        bool exists = this->Useful::verifyIfExists(this->tableName);
        cout << "Searching for the table...";
        return exists;
    }

    // Deletes entries from the specified table based on the given criteria
    void deleteFrom() {
        string fileName = string(this->tableName) + ".bin";
        ifstream inputFile(fileName, ios::in | ios::binary);
        ofstream tempFile("temp.bin", ios::out | ios::binary);
        bool entryFound = false;
        int position = 0;
        string textBuffer[1000];
        int intBuffer[1000];
        float floatBuffer[1000];
        int textLengthBuffer[1000];

        if (inputFile.is_open()) {
            inputFile.seekg(0, inputFile.end);
            int fileLength = inputFile.tellg();
            inputFile.seekg(0, inputFile.beg);

            while (position < fileLength) {
                ifstream schemaFile(string(this->tableName) + ".txt", ios::in);
                if (schemaFile.is_open()) {
                    int intIndex = 0, textIndex = 0, floatIndex = 0, bufferIndex = 0;

                    while (!schemaFile.eof() && schemaFile.is_open() && position < fileLength) {
                        char buffer[1000];
                        schemaFile.getline(buffer, 1000);
                        this->currentColumn = string(buffer);
                        this->currentType = string(buffer);
                        this->currentColumn = this->currentColumn.substr(0, this->currentColumn.find_first_of(" "));
                        int typeStartIndex = this->currentType.find_first_of(" ");
                        this->currentType = this->currentType.substr(typeStartIndex + 1, this->currentType.size() - typeStartIndex);
                        this->currentType = this->currentType.substr(0, this->currentType.find_first_of(" "));

                        // Process based on data type
                        if (this->currentType == "integer") {
                            int currentInt;
                            inputFile.read(reinterpret_cast<char*>(&currentInt), sizeof(int));
                            intBuffer[intIndex++] = currentInt;
                            if (this->value == to_string(currentInt)) {
                                entryFound = true;
                            }
                            position += sizeof(currentInt);
                        } else if (this->currentType == "float") {
                            float currentFloat;
                            inputFile.read(reinterpret_cast<char*>(&currentFloat), sizeof(float));
                            floatBuffer[floatIndex++] = currentFloat;
                            if (this->value == to_string(currentFloat)) {
                                entryFound = true;
                            }
                            position += sizeof(currentFloat);
                        } else if (this->currentType == "text") {
                            int currentTextLength;
                            string text;
                            inputFile.read(reinterpret_cast<char*>(&currentTextLength), sizeof(int));
                            char textBuffer[100];
                            inputFile.read(textBuffer, currentTextLength * sizeof(char));
                            textBuffer[currentTextLength] = '\0';
                            text = string(textBuffer);
                            textLengthBuffer[bufferIndex++] = currentTextLength;
                            textBuffer[textIndex++] = text;
                            if (strcmp(this->value, textBuffer) == 0) {
                                entryFound = true;
                            }
                            position += sizeof(char) * currentTextLength + sizeof(int);
                        }
                    }
                    schemaFile.close();

                    // If no matching entry was found, copy existing entries to the temp file
                    if (!entryFound) {
                        schemaFile.open(string(this->tableName) + ".txt", ios::in);
                        if (schemaFile.is_open()) {
                            int intIndex = 0, textIndex = 0, floatIndex = 0, bufferIndex = 0;

                            while (!schemaFile.eof() && schemaFile.is_open()) {
                                char buffer[1000];
                                schemaFile.getline(buffer, 1000);
                                this->currentColumn = string(buffer);
                                this->currentType = string(buffer);
                                this->currentColumn = this->currentColumn.substr(0, this->currentColumn.find_first_of(" "));
                                int typeStartIndex = this->currentType.find_first_of(" ");
                                this->currentType = this->currentType.substr(typeStartIndex + 1, this->currentType.size() - typeStartIndex);
                                this->currentType = this->currentType.substr(0, this->currentType.find_first_of(" "));

                                // Write data to temp file based on type
                                if (this->currentType == "integer") {
                                    int currentInt = intBuffer[intIndex++];
                                    tempFile.write(reinterpret_cast<char*>(&currentInt), sizeof(int));
                                } else if (this->currentType == "float") {
                                    float currentFloat = floatBuffer[floatIndex++];
                                    tempFile.write(reinterpret_cast<char*>(&currentFloat), sizeof(float));
                                } else if (this->currentType == "text") {
                                    int currentTextLength = textLengthBuffer[bufferIndex];
                                    string text = textBuffer[textIndex++];
                                    tempFile.write(reinterpret_cast<char*>(&currentTextLength), sizeof(int));
                                    tempFile.write(text.c_str(), sizeof(char) * currentTextLength);
                                }
                            }
                            schemaFile.close();
                        }
                    }

                    // Clean up and finalize deletion
                    if (entryFound) {
                        entryFound = false;
                    }
                    columnBinary.clear();
                }

                if (position == fileLength) {
                    inputFile.close();
                    tempFile.close();
                    remove(fileName.c_str());
                    rename("temp.bin", fileName.c_str());
                }
            }
        }
    }

    DeleteCommand() : tableName(nullptr), sizeTableName(0), columnName(nullptr), value(nullptr) {}

    DeleteCommand(const char* tableName, int sizeTableName, const char* columnName, const char* value) {
        this->columnName = nullptr;
        this->tableName = nullptr;
        this->value = nullptr;
        cout << "New DELETE FROM command" << endl;

        if (tableName != nullptr) {
            this->setTableName(tableName);
            this->sizeTableName = sizeTableName;
            this->setColumnName(columnName);
            this->setValue(value);
        } else {
            cout << "Please enter valid values" << endl;
        }
    }

    void setTableName(const char* tableName) {
        if (minTableNameLength <= strlen(tableName)) {
            delete[] this->tableName;
            this->tableName = new char[strlen(tableName) + 1];
            strcpy(this->tableName, tableName);
        } else {
            cout << "You need to enter a valid table name" << endl;
        }
    }

    void setColumnName(const char* columnName) {
        if (columnName != nullptr) {
            delete[] this->columnName;
            this->columnName = new char[strlen(columnName) + 1];
            strcpy(this->columnName, columnName);
        } else {
            cout << "You need to enter a valid column name" << endl;
        }
    }

    void setValue(const char* value) {
        if (value != nullptr) {
            delete[] this->value;
            this->value = new char[strlen(value) + 1];
            strcpy(this->value, value);
        } else {
            cout << "You need to enter a valid value" << endl;
        }
    }

    void receiveCommand(string command) {
        this->initialCommand = command;
        if (this->initialCommand.find('\r') != string::npos) {
            int carriageReturnIndex = this->initialCommand.find('\r');
            this->initialCommand = this->initialCommand.substr(0, carriageReturnIndex);
        }
        createParse();
    }

    void createParse() {
        int commandSize = this->initialCommand.size();
        this->initialCommand = this->initialCommand.substr(7, commandSize - 7);

        if (initialCommand.find("FROM") == 0) {
            commandSize = this->initialCommand.size();
            this->initialCommand = this->initialCommand.substr(5, commandSize - 5);
            commandSize = this->initialCommand.size();

            this->sizeTableName = initialCommand.find_first_of("WHERE") - 1;
            if (this->sizeTableName < 0 || this->sizeTableName >= commandSize) {
                cout << endl << "You forgot the WHERE clause";
            } else {
                this->tableName = new char[this->sizeTableName + 1];
                strcpy(this->tableName, initialCommand.substr(0, this->sizeTableName).c_str());
                bool isValid = true;

                for (int i = 0; i < this->sizeTableName && isValid; i++) {
                    if ((this->tableName[i] < 'a' && this->tableName[i] != '_' && (this->tableName[i] < 48 || this->tableName[i] > 57)) || this->tableName[i] > 'z') {
                        isValid = false;
                        break;
                    }
                }

                if (!isValid) {
                    cout << "The name you entered isn't correct";
                } else {
                    this->initialCommand = this->initialCommand.substr(this->sizeTableName + 7, commandSize);
                    commandSize = this->initialCommand.size();
                    int columnNameSize = this->initialCommand.find("=") - 1;

                    if (columnNameSize > 0 && columnNameSize <= commandSize) {
                        this->columnName = new char[columnNameSize + 1];
                        strcpy(this->columnName, this->initialCommand.substr(0, columnNameSize).c_str());
                        isValid = true;

                        for (int i = 0; i < columnNameSize && isValid; i++) {
                            if ((this->columnName[i] < 'a' && this->columnName[i] != '_' && (this->columnName[i] < 48 || this->columnName[i] > 57)) || this->columnName[i] > 'z') {
                                isValid = false;
                                break;
                            }
                        }

                        if (!isValid) {
                            cout << "The column name you entered isn't correct";
                        } else {
                            this->initialCommand = this->initialCommand.substr(columnNameSize + 3, commandSize - columnNameSize - 3);
                            if (this->value != nullptr) {
                                delete[] this->value;
                            }
                            this->value = new char[this->initialCommand.size() + 1];
                            strcpy(this->value, this->initialCommand.c_str());

                            if (verifyIfExists(this->tableName)) {
                                this->deleteFrom();
                            }

                            cout << "Delete is successful";
                        }
                    } else {
                        cout << "Please reenter the command." << endl;
                    }
                }
            }
        } else {
            cout << endl << "Please enter a valid command";
        }
    }

    ~DeleteCommand() {
        delete[] this->tableName;
        delete[] this->columnName;
        delete[] this->value;
    }

    DeleteCommand(const DeleteCommand& other) {
        this->value = nullptr;
        if (other.tableName != nullptr) {
            this->setTableName(other.tableName);
        }
        if (other.columnName != nullptr) {
            this->setColumnName(other.columnName);
        }
        if (other.value != nullptr) {
            this->setValue(other.value);
        }
        this->sizeTableName = other.sizeTableName;
    }

    friend ostream& operator<<(ostream& console, DeleteCommand& dlt);
    friend void operator>>(istream& input, DeleteCommand& del1);
    friend bool operator==(DeleteCommand del1, DeleteCommand del2);
    friend bool operator>=(DeleteCommand del1, DeleteCommand del2);

    // Overloading operator "!" to check the length of the tableName
    bool operator!() {
        return strlen(this->tableName) > 12;
    }

    // Overloading operator "+=" to concatenate table names
    DeleteCommand& operator+=(DeleteCommand& other) {
        int currentLength = strlen(this->tableName);
        char* temp = new char[currentLength + 1];
        strcpy(temp, this->tableName);
        delete[] this->tableName;

        this->tableName = new char[currentLength + strlen(other.tableName) + 1];
        strcpy(this->tableName, temp);
        strcat(this->tableName, other.tableName);
        delete[] temp;

        return *this;
    }

    // Overloading cast to int
    explicit operator int() {
        return strlen(this->tableName);
    }
};

const int DeleteCommand::minTableNameLength = 2;

ostream& operator<<(ostream& console, DeleteCommand& dlt) {
    console << endl << "\n-------------------------------------";
    if (dlt.tableName != nullptr) {
        console << endl << "The name of the table you have deleted from is: " << dlt.tableName << endl;
    }
    return console;
}

