using namespace std;

class DisplayCommand : public Useful, public Parse, public DataManipCommands {
protected:
    string commandInput;
    char* tableName;
    static const int minTableNameLength;
    bool tableExists = false;

public:
    // Verifies if the specified table exists
    bool verifyIfExists(char* tableName) {
        bool exists = this->Useful::verifyIfExists(this->tableName);
        cout << "Searching for the table...";
        return exists;
    }

    // Opens the specified table file and displays its contents
    virtual void openTableFile() {
        string fileName = string(this->tableName) + ".txt";
        ifstream inputFile(fileName, ios::in);
        ofstream outputFile("Display.txt", ios::out | ios::app);

        if (inputFile.is_open()) {
            cout << endl << "----------------------------------" << endl;
            outputFile << endl << "\n You are displaying the table: " << this->tableName << endl;
            outputFile << "----------------------------" << endl;

            while (!inputFile.eof()) {
                string columnName;
                char buffer[1000];
                inputFile.getline(buffer, 1000);
                columnName = string(buffer);
                cout << columnName << endl;

                if (outputFile.is_open()) {
                    outputFile << columnName << endl;
                }
            }

            inputFile.close();
            outputFile.close();
        }
    }

    DisplayCommand() {
        this->tableName = nullptr;
    }

    DisplayCommand(const char* tableName) {
        this->tableName = nullptr;
        if (tableName != nullptr) {
            this->setTableName(tableName);
        }
    }

    void setTableName(const char* tableName) {
        if (DisplayCommand::minTableNameLength <= strlen(tableName)) {
            if (this->tableName != nullptr) {
                delete[] this->tableName;
            }
            this->tableName = new char[strlen(tableName) + 1];
            strcpy(this->tableName, tableName);
        }
    }

    void receiveCommand(string command) {
        this->commandInput = command;
        parseCommand();
    }

    void parseCommand() {
        int commandSize = this->commandInput.size();
        this->commandInput = this->commandInput.substr(8, commandSize - 8);
        int carriageReturnIndex = 0;

        if (this->commandInput.find('\r') != string::npos) {
            carriageReturnIndex = this->commandInput.find('\r');
            this->commandInput = this->commandInput.substr(0, carriageReturnIndex);
        }

        if (this->commandInput.find("TABLE") == 0) {
            commandSize = this->commandInput.size();
            if (this->tableName != nullptr) {
                delete[] this->tableName;
            }
            this->tableName = new char[commandSize + 1];
            this->commandInput = this->commandInput.substr(6, commandSize - 6);
            strcpy(this->tableName, this->commandInput.c_str());

            int i;
            for (i = 0; i < strlen(this->tableName); i++) {
                if ((this->tableName[i] < 'a' && this->tableName[i] != '_' && (this->tableName[i] < 48 || this->tableName[i] > 57)) || this->tableName[i] > 'z') {
                    break;
                }
            }

            if (i != strlen(this->tableName)) {
                cout << "Please reenter the command with a valid table name";
            } else {
                this->tableExists = this->verifyIfExists(this->tableName);
                if (this->tableExists) {
                    this->openTableFile();
                }
            }
        } else {
            cout << "Please enter a valid command";
        }
    }

    ~DisplayCommand() {
        if (this->tableName) {
            delete[] this->tableName;
        }
    }

    DisplayCommand(const DisplayCommand& display) {
        this->tableName = nullptr;
        if (display.tableName != nullptr) {
            this->setTableName(display.tableName);
        }
    }

    friend void operator>>(istream& input, DisplayCommand& displayCommand);
    friend ostream& operator<<(ostream& console, DisplayCommand& display);
    friend bool operator==(DisplayCommand display1, DisplayCommand display2);
    friend bool operator>=(DisplayCommand display1, DisplayCommand display2);

    // Overloading operator "!" to check table name length
    bool operator!() {
        return strlen(this->tableName) > 12;
    }

    // Overloading operator "+=" to concatenate table names
    DisplayCommand& operator+=(DisplayCommand& other) {
        int currentLength = strlen(this->tableName);
        char* temp = new char[currentLength + 1];
        strcpy(temp, this->tableName);

        if (this->tableName) {
            delete[] this->tableName;
        }

        this->tableName = new char[currentLength + strlen(other.tableName) + 1];
        strcpy(this->tableName, temp);
        strcat(this->tableName, other.tableName);
        delete[] temp;

        return *this;
    }

    // Overloading cast operator to return table name length
    explicit operator int() {
        return strlen(this->tableName);
    }
};

const int DisplayCommand::minTableNameLength = 2;

ostream& operator<<(ostream& console, DisplayCommand& display) {
    console << endl << "-------------------------------------";
    if (display.tableName != nullptr) {
        console << endl << "The name of the table you have displayed is: " << display.tableName << endl;
    }
    return console;
}

