#include <iostream>
#include <fstream>
#include <cstring>

using namespace std;

class DropCommand : public Useful, public Parse, public DataManipCommands {
    string commandInput;
    char* indexName;
    char* tableName;
    string initialCommand;
    bool exists;
    static const int minTableNameLength;

public:
    // Verifies if the specified table exists in the database.
    bool verifyIfExists(char* tableName) {
        bool existsInDatabase = this->Useful::verifyIfExists(this->tableName);
        cout << "Searching for the table...";
        return existsInDatabase;
    }

    // Deletes the files associated with the existing table.
    void deleteExistingFile() {
        string textFileName = string(this->tableName) + ".txt";
        string binaryFileName = string(this->tableName) + ".bin";
        remove(textFileName.c_str());
        remove(binaryFileName.c_str());
    }

    // Updates the list of tables by removing the dropped table from the record.
    void deleteTrace() {
        string oldListName = "listofNewTables.txt";
        string newListName = "listofTables.txt";
        fstream report("listOfTables.txt");

        if (report.is_open()) {
            while (!report.eof()) {
                string existingTableName;
                char buffer[1000];
                report.getline(buffer, 1000);
                existingTableName = string(buffer);

                if (existingTableName.find(this->tableName) != string::npos) {
                    this->exists = true;
                } else {
                    ofstream newReport("listOfNewTables.txt", ios::app);
                    if (newReport.is_open() && !existingTableName.empty()) {
                        newReport << existingTableName << '\n';
                        newReport.close();
                    }
                }
            }
            report.close();
            remove(newListName.c_str());
            rename(oldListName.c_str(), newListName.c_str());
        } else {
            cout << "The file was not created.";
        }
    }

    DropCommand() : indexName(nullptr), tableName(nullptr) {}

    DropCommand(const char* indexName, const char* tableName) : indexName(nullptr), tableName(nullptr) {
        cout << "New DROP COMMAND";
        if (strlen(indexName) > 1) {
            this->setIndexName(indexName);
            if (strcmp(tableName, "") == 0) {
                this->initialCommand = "New DROP INDEX command";
            }
        } else if (strlen(tableName) >= DropCommand::minTableNameLength) {
            this->setTableName(tableName);
            this->initialCommand = "New DROP TABLE command";
        }
    }

    void setTableName(const char* tableName) {
        if (DropCommand::minTableNameLength <= strlen(tableName)) {
            delete[] this->tableName;
            this->tableName = new char[strlen(tableName) + 1];
            strcpy(this->tableName, tableName);
        } else {
            cout << "You need to enter a valid table name" << endl;
        }
    }

    void setIndexName(const char* indexName) {
        if (DropCommand::minTableNameLength <= strlen(indexName)) {
            delete[] this->indexName;
            this->indexName = new char[strlen(indexName) + 1];
            strcpy(this->indexName, indexName);
        } else {
            cout << "You need to enter a valid index name" << endl;
        }
    }

    void receiveCommand(string command) {
        this->commandInput = command;
        this->initialCommand = command;
        createParse();
    }

    void createParse() {
        int commandSize = this->commandInput.size();
        this->commandInput = this->commandInput.substr(5, commandSize - 5);
        int carriageReturnIndex = this->commandInput.find('\r');

        if (carriageReturnIndex != string::npos) {
            this->commandInput = this->commandInput.substr(0, carriageReturnIndex);
        }

        if (this->commandInput.find("TABLE") == 0) {
            commandSize = this->commandInput.size();
            this->tableName = new char[commandSize + 1];
            this->commandInput = this->commandInput.substr(6, commandSize - 6);
            strcpy(this->tableName, this->commandInput.c_str());

            if (!isValidName(this->tableName)) {
                cout << "Please reenter the command with a valid table name";
            } else if (verifyIfExists(this->tableName)) {
                this->deleteExistingFile();
                cout << "Drop is successful" << endl;
                this->deleteTrace();
                string binaryFileName = string(this->tableName) + ".bin";
                ifstream binaryFile(binaryFileName);
                if (binaryFile.is_open()) {
                    remove(binaryFileName.c_str());
                }
            } else {
                cout << "This table doesn't exist";
            }
        } else if (this->commandInput.find("INDEX") == 0) {
            this->commandInput = this->commandInput.substr(6, commandSize - 6);
            commandSize = commandInput.size();
            this->indexName = new char[commandSize + 1];
            strcpy(this->indexName, this->commandInput.c_str());

            if (!isValidName(this->indexName)) {
                cout << "Please reenter the command with a valid index name";
            } else {
                cout << "You have dropped the index: " << this->indexName << endl;
            }
        } else {
            cout << "Please enter a valid command";
        }
    }

    bool isValidName(const char* name) {
        for (int i = 0; i < strlen(name); i++) {
            if ((name[i] < 'a' && name[i] != '_' && (name[i] < 48 || name[i] > 57)) || name[i] > 'z') ) {
                return false;
            }
        }
        return true;
    }

    ~DropCommand() {
        delete[] indexName;
        delete[] tableName;
    }

    DropCommand(const DropCommand& drop) : indexName(nullptr), tableName(nullptr) {
        if (drop.tableName != nullptr) {
            this->setTableName(drop.tableName);
        } else if (drop.indexName != nullptr) {
            this->setIndexName(drop.indexName);
        }
    }

    friend ostream& operator<<(ostream& console, DropCommand& drop);
    friend void operator>>(istream& input, DropCommand& dr1);
    friend bool operator==(DropCommand dr1, DropCommand dr2);
    friend bool operator>=(DropCommand dr1, DropCommand dr2);

    bool operator!() {
        return strlen(this->indexName) > 12;
    }

    DropCommand& operator+=(DropCommand& name) {
        int currentLength = strlen(this->indexName);
        char* temp = new char[currentLength + 1];
        strcpy(temp, this->indexName);
        delete[] this->indexName;
        this->indexName = new char[currentLength + strlen(name.indexName) + 1];
        strcpy(this->indexName, temp);
        strcat(this->indexName, name.indexName);
        delete[] temp;
        return *this;
    }

    explicit operator int() {
        return strlen(this->indexName);
    }
};

const int DropCommand::minTableNameLength = 2;

void operator>>(istream& input, DropCommand& dr1) {
    cout << endl << "What would you like to drop?" << endl;
    cout << "[ 1 ] table" << endl << "[ 2 ] index" << endl;
    int option;
    cin >> option;

    switch (option) {
        case 1: {
            cout << "Now please enter the name of the table" << endl;
            char buffer[1000];
            input >> buffer;
            if (strlen(buffer) > 1) {
                dr1.setTableName(buffer);
