    InsertCSVCommand() : tableName(nullptr), tableNameSize(999), values(nullptr) {}

    InsertCSVCommand(const char* tableName, int tableNameSize, const char* values) : tableName(nullptr), values(nullptr) {
        if (strlen(tableName) > 1) {
            setTableName(tableName);
            this->tableNameSize = tableNameSize;
            if (values != nullptr) {
                setValues(values);
            }
        }
    }

    void setTableName(const char* tableName) {
        if (InsertCSVCommand::minTableNameLength <= strlen(tableName)) {
            if (this->tableName != nullptr) {
                delete[] this->tableName;
            }
            this->tableName = new char[strlen(tableName) + 1];
            strcpy(this->tableName, tableName);
        }
    }

    void setValues(const char* values) {
        if (values != nullptr) {
            if (this->values) {
                delete[] this->values;
            }
            this->values = new char[strlen(values) + 1];
            strcpy(this->values, values);
        }
    }

    void display(string command) {
        this->commandBuffer = command;
        parseCommand();
    }

    void parseCommand() {
        int newSize = this->commandBuffer.size();
        this->commandBuffer = this->commandBuffer.substr(7, newSize - 7);
        newSize = this->commandBuffer.size();
        this->tableNameSize = this->commandBuffer.find_first_of(" ") - 1;
        if (this->tableNameSize < 0 || this->tableNameSize >= newSize) {
            cout << endl << "You forgot to add the table name";
        } else {
            this->tableName = new char[this->tableNameSize + 1];
            strcpy(this->tableName, this->commandBuffer.substr(0, this->tableNameSize + 1).c_str());
            bool isValid = true;
            for (int i = 0; i < this->tableNameSize && isValid; i++) {
                if ((this->tableName[i] < 'a' && tableName[i] != '_' && (tableName[i] < 48 || tableName[i] > 57)) || tableName[i] > 'z') {
                    isValid = false;
                    break;
                }
            }
            if (!isValid) {
                cout << "The name you entered isn't correct";
            } else {
                checkIfTableExists();
                if (!this->tableExists) {
                    cout << "This table doesn't exist";
                } else {
                    this->commandBuffer = this->commandBuffer.substr(this->tableNameSize + 2, newSize - this->tableNameSize - 1);
                    this->csvFileName = this->commandBuffer;
                    readCommandsFromCSV();
                }
            }
        }
    }

    InsertCSVCommand(const InsertCSVCommand& insert) : tableName(nullptr), values(nullptr), currentValue(nullptr) {
        if (insert.tableName != nullptr) {
            setTableName(insert.tableName);
        }
        this->tableNameSize = insert.tableNameSize;
        if (insert.values != nullptr) {
            setValues(insert.values);
        }
