    // Default constructor
    InsertCommand() {
        this->tableName = nullptr;
        this->tableNameSize = 999;
        this->values = nullptr;
    }

    // Parameterized constructor
    InsertCommand(const char* tableName, int tableNameSize, const char* values) {
        this->tableName = nullptr;
        this->values = nullptr;
        if (strlen(tableName) > 1) {
            this->setTableName(tableName);
            this->tableNameSize = tableNameSize;
            if (values != nullptr) {
                this->setValues(values);
            }
        }
    }

    // Sets the table name
    void setTableName(const char* tableName) {
        if (InsertCommand::minTableNameLength <= strlen(tableName)) {
            if (this->tableName != nullptr) {
                delete[] this->tableName;
            }
            this->tableName = new char[strlen(tableName) + 1];
            strcpy(this->tableName, tableName);
        }
    }

    // Sets the values to be inserted
    void setValues(const char* values) {
        if (values != nullptr) {
            if (this->values) {
                cout << this->values;
                delete[] this->values;
            }
            this->values = new char[strlen(values) + 1];
            strcpy(this->values, values);
        }
    }

    // Receives the command for processing
    void receiveCommand(string command) {
        this->command = command;
        createParse();
    }

    // Parses the command to extract relevant information
    void createParse() {
        int newSize = this->command.size();
        this->command = this->command.substr(7, newSize - 7);
        int rightParenthesisIndex = this->command.find_last_of(")");
        int carriageReturnIndex = 0;

        if (this->command.find('\r') != string::npos) {
            carriageReturnIndex = this->command.find('\r');
            this->command = this->command.substr(0, carriageReturnIndex);
        }

        if (rightParenthesisIndex < this->command.size() - 1) {
            this->command = this->command.substr(0, rightParenthesisIndex);
        }

        if (this->command.find("INTO") == 0) {
            newSize = this->command.size();
            this->command = this->command.substr(5, newSize - 5);
            this->tableNameSize = this->command.find("VALUES") - 1;

            if (this->tableNameSize < 0 || this->tableNameSize >= newSize) {
                cout << endl << "You forgot to add the table name";
            } else {
                this->tableName = new char[this->tableNameSize + 1];
                strcpy(this->tableName, this->command.substr(0, this->tableNameSize).c_str());
                bool isValid = true;

                for (int i = 0; i < this->tableNameSize && isValid; i++) {
                    if ((this->tableName[i] < 'a' && tableName[i] != '_' && (tableName[i] < 48 || tableName[i] > 57)) || tableName[i] > 'z') {
                        isValid = false;
                        break;
                    }
                }

                if (!isValid) {
                    cout << "The name you entered isn't correct";
                } else {
                    if (!verifyIfExists(this->tableName)) {
                        cout << "This table doesn't exist";
                    } else {
                        this->command = this->command.substr(this->tableNameSize + 8, newSize);
                        removeSpaces(this->command);
                        this->lastParenthesis = this->command.find(")");

                        if (this->lastParenthesis > -2) {
                            if (this->values != nullptr) {
                                delete[] values;
                            }
                            this->values = new char[this->command.size() + 1];
                            strcpy(this->values, this->command.c_str());

                            this->column = string(this->values);
                            this->column = this->column.substr(1, this->column.size() - 2);
                            this->printAsInFile();
                        } else {
                            cout << endl << "You need to enter the values" << endl;
                        }
                    }
                }
            }
        } else {
            cout << endl << "Please enter a valid command" << endl;
        }
    }

    // Copy constructor
    InsertCommand(const InsertCommand& insert) {
        this->tableName = nullptr;
        this->values = nullptr;
        this->currentValue = nullptr;

        if (insert.tableName != nullptr) {
            this->setTableName(insert.tableName);
        }
        this->tableNameSize = insert.tableNameSize;

        if (insert.values != nullptr) {
            this->setValues(insert.values);
        }
    }

    // Destructor
    ~InsertCommand() {
        if (this->tableName) {
            delete[] this->tableName;
        }
        if (this->values) {
            delete[] this->values;
        }
        if (this->currentValue) {
            delete[] this->currentValue;
        }
    }

    friend ostream& operator<<(ostream& console, InsertCommand& insert);
    friend void operator>>(istream& input, InsertCommand& ins);
    friend bool operator==(InsertCommand ins1, InsertCommand ins2);
    friend bool operator>=(InsertCommand ins1, InsertCommand ins2);

    // Overloading operator "!" to check table name length
    bool operator!() {
        return strlen(this->tableName) > 12;
    }

    // Overloading operator "+="
    InsertCommand& operator+=(InsertCommand& name) {
        int currentLength = strlen(this->tableName);
        char* temp = new char[currentLength + 1];
        strcpy(temp, this->tableName);

        if (this->tableName) {
            delete[] this->tableName;
        }

        this->tableName = new char[currentLength + strlen(name.tableName) + 1];
        strcpy(this->tableName, temp);
        strcat(this->tableName, name.tableName);
        delete[] temp;

        return *this;
    }

    // Overloading cast operator to int
    explicit operator int() {
        return strlen(this->tableName);
    }

    // Overloading operator "++" for pre-increment
    InsertCommand operator++() {
        this->tableNameSize += 1;
        return *this;
    }
};

