                isCorresponding = true;
            } else {
                cout << "You haven't entered enough values";
            }

            inputFile.close();
        }

        if (isCorresponding) {
            valueCount++;
            string binaryFileName = string(this->tableName) + ".bin";
            ofstream outputFile(binaryFileName, ios::app | ios::binary);
            if (outputFile.is_open()) {
                ifstream inputFile(textFileName, ios::in);
                if (inputFile.is_open()) {
                    string const delimiter{ ", " };
                    int start, position = 0;

                    while ((start = this->column.find_first_not_of(delimiter, position)) != string::npos) {
                        position = this->column.find_first_of(delimiter, start);

                        if (this->currentValue) {
                            delete[] this->currentValue;
                        }

                        if (position == -1 && start >= 0) {
                            int length = this->column.size();
                            this->currentValue = new char[length - start + 1];
                            strcpy(this->currentValue, this->column.substr(start, length - start).c_str());
                        } else {
                            this->currentValue = new char[position - start + 1];
                        }
                        strcpy(this->currentValue, this->column.substr(start, position - start).c_str());

                        string type;
                        char buffer[1000];
                        inputFile.getline(buffer, 1000);
                        type = string(buffer);
                        if (type.find_first_of(" ") != string::npos) {
                            type = type.substr(type.find_first_of(" ") + 1);
                        }
                        if (type.find_first_of(" ") != string::npos) {
                            type = type.substr(0, type.find_first_of(" "));
                        }

                        // Write the current value to the binary file based on its type
                        if (type == "integer") {
                            int number = atoi(this->currentValue);
                            outputFile.write((char*)&number, sizeof(int));
                            counter++;
                        } else if (type == "float") {
                            float number = atof(this->currentValue);
                            outputFile.write((char*)&number, sizeof(float));
                            counter++;
                        } else if (type == "text") {
                            int length = strlen(this->currentValue);
                            outputFile.write((char*)&length, sizeof(int));
                            outputFile.write(this->currentValue, sizeof(char) * length);
                            counter++;
                        }
                    }
                    cout << endl << "You have successfully inserted " << counter << " values.";
                    inputFile.close();
                } else {
                    cout << endl << "The file was not created";
                }
                outputFile.close();
            }
        }
    }
};

// Overloading operator "==" to compare two InsertCommand objects
bool operator==(InsertCommand ins1, InsertCommand ins2) {
    return strcmp(ins1.tableName, ins2.tableName) == 0;
}

// Overloading operator ">=" to compare the lengths of two table names
bool operator>=(InsertCommand ins1, InsertCommand ins2) {
    return strlen(ins1.tableName) >= strlen(ins2.tableName);
}

