class CommandFileProcessor : public DataManipCommands {
public:
    CommandFileProcessor() {}

    void processCommandsFromFile(const char* filename) {
        readCommandsFromFile(filename);
    }

private:
    void readCommandsFromFile(const char* filename) {
        fstream inputFile;
        inputFile.open(filename, ios::in);

        if (inputFile.is_open()) {
            string command;

            while (getline(inputFile, command)) {
                if (command.find("CREATE TABLE") != string::npos) {
                    CreateCommand createCommand;
                    createCommand.receiveCommand(command);
                    cout << createCommand;
                } else if (command.find("INSERT INTO") != string::npos) {
                    InsertCommand insertCommand;
                    insertCommand.receiveCommand(command);
                } else if (command.find("SELECT") != string::npos) {
                    SelectCommand selectCommand;
                    selectCommand.receiveCommand(command);
                } else if (command.find("DISPLAY") != string::npos) {
                    DisplayCommand displayCommand;
                    displayCommand.receiveCommand(command);
                } else if (command.find("DROP") != string::npos) {
                    DropCommand dropCommand;
                    dropCommand.receiveCommand(command);
                } else if (command.find("UPDATE") != string::npos) {
                    UpdateCommand updateCommand;
                    updateCommand.receiveCommand(command);
                } else if (command.find("DELETE FROM") != string::npos) {
                    DeleteCommand deleteCommand;
                    deleteCommand.receiveCommand(command);
                }
            }
            inputFile.close();
        } else {
            cout << endl << "File not opened";
        }
    }

    ~CommandFileProcessor() {}
};

