    friend bool operator>=(SelectCommand sel1, SelectCommand sel2);

    // Overloading operator "!" to check the length of the table name
    bool operator!() {
        return strlen(this->tableName) > 12;
    }

    // Overloading operator "+="
    SelectCommand& operator+=(SelectCommand& name) {
        int currentLength = strlen(this->tableName);
        char* temp = new char[currentLength + 1];
        strcpy(temp, this->tableName);

        if (this->tableName) {
            delete[] this->tableName;
        }

        this->tableName = new char[currentLength + strlen(name.tableName) + 1];
        strcpy(this->tableName, temp);
        strcat(this->tableName, name.tableName);
        delete[] temp;

        return *this;
    }

    // Overloading cast operator to return the length of the table name
    explicit operator int() {
        return strlen(this->tableName);
    }
