                int typeStart = this->currentType.find_first_of(" ") + 1;
                this->currentType = this->currentType.substr(typeStart, this->currentType.size() - typeStart);
                this->currentType = this->currentType.substr(0, this->currentType.find_first_of(" "));

                if (this->currentType == "integer") {
                    int currentInt;
                    input.read(reinterpret_cast<char*>(&currentInt), sizeof(int));
                    intBuffer[intIndex++] = currentInt;
                    if (this->value2 == to_string(currentInt)) {
