                    this->currentType = this->currentType.substr(typeStart, this->currentType.size() - typeStart);
                    this->currentType = this->currentType.substr(0, this->currentType.find_first_of(" "));

                    if (this->currentType == "integer") {
                        int currentInt = intBuffer[intIndex++];
                        temp.write(reinterpret_cast<char*>(&currentInt), sizeof(int));
                    } else if (this->currentType == "float") {
                        float currentFloat = floatBuffer[floatIndex++];
                        temp.write(reinterpret_cast<char*>(&currentFloat), sizeof(float));
                    } else if (this->currentType == "text") {
                        int currentTextLength = textLengthBuffer[bufferIndex++];
                        string text = textBuffer[textIndex++];
                        temp.write(reinterpret_cast<char*>(&currentTextLength), sizeof(int));
                        temp.write(text.c_str(), sizeof(char) * currentTextLength);
                    }
                }
            } else {
                // If record found, update the specified column
                schemaFile.clear();
                schemaFile.seekg(0, ios::beg);
                while (!schemaFile.eof()) {
                    char buffer[1000];
                    schemaFile.getline(buffer, 1000);
