                    cout << endl << "Please enter a WHERE clause";
                }
            } else {
                cout << endl << "Please enter a valid command";
            }
        } else {
            cout << endl << "Please enter a valid command";
        }
    }

    UpdateCommand(const UpdateCommand& other) {
        this->columnName1 = nullptr;
        this->columnName2 = nullptr;
        this->value1 = nullptr;
        this->value2 = nullptr;

        if (other.tableName != nullptr) {
            this->setTableName(other.tableName);
        }

        if (other.columnName1 != nullptr) {
            this->setColumnName1(other.columnName1);
        }

        if (other.columnName2 != nullptr) {
            this->setColumnName2(other.columnName2);
        }

        if (other.value1 != nullptr) {
            this->setValue1(other.value1);
        }

        if (other.value2 != nullptr) {
            this->setValue2(other.value2);
        }

        this->sizeTableName = other.sizeTableName;
    }

    friend void operator>>(istream& input, UpdateCommand& upd);
    friend ostream& operator<<(ostream& console, UpdateCommand& updt);
    friend bool operator==(const UpdateCommand& updt1, const UpdateCommand& updt2);
    friend bool operator>=(const UpdateCommand& updt1, const UpdateCommand& updt2);

    bool operator!() const {
        return strlen(this->tableName) > 12;
    }

    UpdateCommand& operator+=(const UpdateCommand& other) {
        int currentLength = strlen(this->tableName);
        char* temp = new char[currentLength + 1];
        strcpy(temp, this->tableName);

        delete[] this->tableName;
        this->tableName = new char[currentLength + strlen(other.tableName) + 1];
        strcpy(this->tableName, temp);
        strcat(this->tableName, other.tableName);
        delete[] temp;

        return *this;
    }

    explicit operator int() const {
        return strlen(this->tableName);
    }
};

const int UpdateCommand::minTableNameLength = 2;

ostream& operator<<(ostream& console, const UpdateCommand& updt) {
    console << endl << "-------------------------------------";
    if (updt.tableName != nullptr) {
        console << endl << "The name of the table you have updated is: " << updt.tableName;
    }
    return console;
}

void operator>>(istream& input, UpdateCommand& upd) {
    cout << "Which table would you like to update?" << endl;
    char buffer[1000];
    input >> buffer;
    if (strlen(buffer) > 1) {
        upd.setTableName(buffer);
    }

    cout << "What column would you like to update?" << endl;
    input >> buffer;
    if (strlen(buffer) > 1) {
        upd.setColumnName1(buffer);
    }

    cout << "What value would you like this column to take?" << endl;
    input >> buffer;
    if (strlen(buffer) > 1) {
        upd.setValue1(buffer);
    }

    cout << "What column would you like to take as a pivot?" << endl;
    input >> buffer;
    if (strlen(buffer) > 1) {
        upd.setColumnName2(buffer);
    }

    cout << "What value would you like to search for?" << endl;
    input >> buffer;
    if (strlen(buffer) > 1) {
        upd.setValue2(buffer);
    }
}

bool operator==(const UpdateCommand& updt1, const UpdateCommand& updt2) {
    return strcmp(updt1.tableName, updt2.tableName) == 0;
}

bool operator>=(const UpdateCommand& updt1, const UpdateCommand& updt2) {
    return strlen(updt1.tableName) >= strlen(updt2.tableName);
}

