// Class responsible for verifying the existence of a table in a predefined list
class TableVerifier {
public:
    TableVerifier() {}

    // Checks if a table with the given name exists in the list
    virtual bool doesTableExist(const char* tableName) {
        bool exists = false;
        fstream tableList("listOfTables.txt");

        if (tableList.is_open()) {
            while (!tableList.eof()) {
                string existingTableName;
                char buffer[1000];
                tableList.getline(buffer, 1000);
                existingTableName = string(buffer);

                // Check if the table name is found within the existing table names
                if (existingTableName.find(tableName) != string::npos) {
                    exists = true;
                    break; // Exit loop early if found
                }
            }
            tableList.close();
        }
        return exists;
    }
};

// Class for removing unnecessary spaces from a command string
class SpaceRemover {
public:
    SpaceRemover() {}

    // Removes all spaces from the provided command string
    virtual void trimSpaces(string& command) {
        string trimmedCommand;
        const string delimiter{ " " };
        int startPos, currentPos = 0;

        while ((startPos = command.find_first_not_of(delimiter, currentPos)) != string::npos) {
            currentPos = command.find_first_of(delimiter, startPos);
            if (currentPos == string::npos) {
                trimmedCommand.append(command.substr(startPos));
            } else {
                trimmedCommand.append(command.substr(startPos, currentPos - startPos));
            }
        }
        command = trimmedCommand; // Update the original command with trimmed version
    }
};

