#include <iostream>
using namespace std;

// Abstract base class representing a geometric shape
class Shape {
public:
    virtual double area() const = 0; // Pure virtual function to calculate area
};

// Class representing a circle
class Circle : public Shape {
public:
    Circle(double radius) : radius(radius) {}

    virtual double area() const override {
        return 3.14159 * radius * radius; // Calculate area of the circle
    }

protected:
    double radius; // Radius of the circle
};

// Class representing a rectangle
class Rectangle : public Shape {
public:
    Rectangle(double width, double height) : width(width), height(height) {}

    virtual double area() const override {
        return width * height; // Calculate area of the rectangle
    }

protected:
    double width;   // Width of the rectangle
    double height;  // Height of the rectangle
};

// Class representing a triangle
class Triangle : public Shape {
public:
    Triangle(double width, double height) : width(width), height(height) {}

    virtual double area() const override {
        return 0.5 * width * height; // Calculate area of the triangle
    }

protected:
    double width;   // Base width of the triangle
    double height;  // Height of the triangle
};

// Function to print the area of a shape
void printArea(const Shape &shape) {
    cout << shape.area() << endl; // Output the calculated area
}

int main() {
    Circle circle(12.6);
    cout << "Area of circle = ";
    printArea(circle);

    Rectangle rectangle(4.5, 8.4);
    cout << "Area of rectangle = ";
    printArea(rectangle);

    Triangle triangle(4.5, 8.4);
    cout << "Area of triangle = ";
    printArea(triangle);

    return 0;
}

#include <iostream>
using namespace std;

// Abstract base class representing a geometric shape
class Shape {
public:
    virtual double area() const = 0; // Pure virtual function for calculating area
};

// Class representing a circle
class Circle : public Shape {
public:
    Circle(double radius) : radius(radius) {}

    virtual double area() const override {
        return 3.14159 * radius * radius; // Calculate area of the circle
    }

protected:
    double radius; // Radius of the circle
};

// Class representing a square
class Square : public Shape {
public:
    Square(double side) : side(side) {}

    virtual double area() const override {
        return side * side; // Calculate area of the square
    }

protected:
    double side; // Side length of the square
};

// Class representing a rectangle
class Rectangle : public Shape {
public:
    Rectangle(double width, double height) : width(width), height(height) {}

    virtual double area() const override {
        return width * height; // Calculate area of the rectangle
    }

protected:
    double width; // Width of the rectangle
    double height; // Height of the rectangle
};

// Class representing a trapezoid
class Trapezoid : public Shape {
public:
    Trapezoid(double top, double bottom, double height) : top(top), bottom(bottom), height(height) {}

    virtual double area() const override {
        return 0.5 * (top + bottom) * height; // Calculate area of the trapezoid
    }

protected:
    double top; // Length of the top base
    double bottom; // Length of the bottom base
    double height; // Height of the trapezoid
};

// Class representing a triangle
class Triangle : public Shape {
public:
    Triangle(double width, double height) : width(width), height(height) {}

    virtual double area() const override {
        return 0.5 * width * height; // Calculate area of the triangle
    }

protected:
    double width; // Base width of the triangle
    double height; // Height of the triangle
};

int main() {
    Circle circle(12.6);
    Square square(3.5);
    Rectangle rectangle(4.5, 8.4);
    Trapezoid trapezoid(2.0, 4.5, 3.2);
    Triangle triangle(4.5, 8.4);

    Shape* shapes[5] = { &circle, &square, &rectangle, &trapezoid, &triangle };
    double totalArea = 0.0;

    // Calculate the total area of all shapes
    for (int i = 0; i < 5; i++) {
        totalArea += shapes[i]->area();
    }

    cout << "Total area of all shapes = " << totalArea << endl;
    return 0;
}

