bool caseInsensitiveCompare(unsigned char a, unsigned char b) {
    return tolower(a) == tolower(b);
}

bool stringsEqualIgnoreCase(const string& a, const string& b) {
    if (a.length() == b.length()) {
        return equal(b.begin(), b.end(), a.begin(), caseInsensitiveCompare);
    }
    return false;
}

