                        cout << "\n\n\tBook deposited after number of days: ";
                        cin >> daysOverdue;
                        if (daysOverdue > 15) {
                            fine = (daysOverdue - 15) * 1;
                            cout << "\n\n\tFine to be deposited: Rs. " << fine;
                        }
                        studentInstance.returnBook();
                        int position = -1 * static_cast<int>(sizeof(Student));
                        fileStream.seekp(position, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&studentInstance), sizeof(Student));
                        cout << "\n\tBook deposited successfully.";
                    }
                }
                if (bookFound == 0) {
                    cout << "\tBook number does not exist.";
                }
            } else {
                cout << "\tNo book is issued. Please check!";
            }
        }
    }
    if (studentFound == 0) {
        cout << "\tStudent record does not exist!!!";
    }
    cin.get();
    waitForUserInput();
    fileStream.close();
    tempFileStream.close();
}

