    std::string freeRoomNumber;
    std::string startDay, startMonth, startYear;
    std::string endDay, endMonth, endYear;
    std::string reservedBy = ""; // Empty if not reserved
    OfferState currentState;
    float price;

public:
    // Constructor to initialize an offer with its details
    Offer(const std::string& ownerUsername,
          const std::string& hotelName,
          const std::string& freeRoomNumber,
          const std::string& startDay, const std::string& startMonth, const std::string& startYear,
          const std::string& endDay, const std::string& endMonth, const std::string& endYear,
          const std::string& reservedBy,
          OfferState currentState, float price) 
        : ownerUsername(ownerUsername), hotelName(hotelName), freeRoomNumber(freeRoomNumber),
          startDay(startDay), startMonth(startMonth), startYear(startYear),
          endDay(endDay), endMonth(endMonth), endYear(endYear),
