        return reservedBy;
    }

    // Retrieve the username of the offer owner
    std::string getOwnerUsername() const {
        return ownerUsername;
    }

    // Retrieve the current state of the offer
    OfferState getCurrentState() const {
        return currentState;
    }

    // Get a string representation of the offer's state
    std::string getCurrentStateString() const {
        switch (currentState) {
            case Free: return "available";
            case Reserved: return "reserved";
            case Sold: return "sold";
            default: return "unknown";
        }
