        return startMonth;
    }

    std::string getStartYear() const {
        return startYear;
    }

    // Retrieve the end date of the offer
    std::string getEndDay() const {
        return endDay;
    }

    std::string getEndMonth() const {
        return endMonth;
    }

    std::string getEndYear() const {
        return endYear;
    }

    // Set the username of the person who reserved the offer
    void setReservedBy(const std::string& username) {
        reservedBy = username;
    }

    // Retrieve the price of the offer
    float getPrice() const {
        return price;
    }

    // Convert the offer details to a string representation
