#ifndef LISTBASE_H
#define LISTBASE_H

#include <iostream>
using namespace std;

template <typename T>
class ListBase
{
protected:
    int _size;
    T* type;

public:
    ListBase() : _size(0) {}
    virtual ~ListBase() {}

    bool isEmpty() const { return (_size == 0); }
    int getLength() const { return _size; }
    virtual bool insert(int index, T& newItem) = 0;
    virtual bool remove(int index) = 0;
    virtual bool retrieve(int index, T& dataItem) = 0;
    virtual T returnItem(int i) { return T(); }
    virtual void copy(T*& tempType) {}
};

template <typename T>
class ListDLL : public ListBase<T>
{
private:
    struct ListNode
    {
        T item;
        ListNode* prev;
        ListNode* next;
    };

    ListNode* head;

    ListNode* traverseTo(int index)
    {
        if ((index < 1) || (index > this->getLength()))
            return nullptr;

        ListNode* current = head;
        for (int skip = 0; skip < index - 1; ++skip)
            current = current->next;

        return current;
    }

public:
    ListDLL() : ListBase<T>(), head(nullptr) {}
    ~ListDLL() {}

    bool insert(int userIdx, T& newItem) override
    {
        int newLength = this->getLength() + 1;
        if ((userIdx < 1) || (userIdx > newLength))
            return false;

        ListNode* newPtr = new ListNode{ newItem, nullptr, nullptr };
        this->_size = newLength;

        if (userIdx == 1)
        {
            if (this->_size == 1)
            {
                newPtr->next = newPtr;
                newPtr->prev = newPtr;
                head = newPtr;
            }
            else
            {
                newPtr->prev = head->prev;
                newPtr->next = head;
                newPtr->prev->next = newPtr;
                newPtr->next->prev = newPtr;
                head = newPtr;
            }
        }
        else
        {
            ListNode* previous = traverseTo(userIdx - 1);
            newPtr->next = previous->next;
            newPtr->prev = previous;
            previous->next = newPtr;
            newPtr->next->prev = newPtr;
        }

        return true;
    }

    bool remove(int userIdx) override
    {
        if ((userIdx < 1) || (userIdx > this->getLength()))
            return false;

        --this->_size;
        ListNode* current;

        if (userIdx == 1)
        {
            current = head;
            current->prev->next = current->next;
            current->next->prev = current->prev;
            head = head->next;
        }
        else
        {
            ListNode* previous = traverseTo(userIdx - 1);
            current = previous->next;
            previous->next = current->next;
            current->next->prev = previous;
        }

        delete current;
        return true;
    }

    bool retrieve(int userIdx, T& dataItem) override
    {
        if ((userIdx < 1) || (userIdx > this->getLength()))
            return false;

        ListNode* current = traverseTo(userIdx);
        dataItem = current->item;
        return true;
    }

    T returnItem(int i) override
    {
        ListNode* myPtr = traverseTo(i);
        return myPtr->item;
    }
};

template <typename T>
class ListArr : public ListBase<T>
{
private:
    T* _items;
    int _maxList;

    void recopy()
    {
        _maxList *= 2;
        T* temp = new T[_maxList];
        for (int i = 0; i < this->_size; i++)
        {
            temp[i] = _items[i];
        }
        delete[] _items;
        _items = temp;
    }

public:
    ListArr(int n) : _maxList(n), _items(new T[_maxList]) 
    {
        this->_size = 0;
    }

    bool insert(int userIndex, T& newItem) override
    {
        int index = userIndex - 1;

        if (_size == _maxList / 2)
        {
            recopy();
        }

        if (_size >= _maxList || (index < 0) || (index >= _size + 1))
            return false;

        for (int pos = _size - 1; pos >= index; pos--)
        {
            _items[pos + 1] = _items[pos];
        }
        _items[index] = newItem;
        this->_size++;
        return true;
    }

    bool remove(int userIndex) override
    {
        int index = userIndex - 1;
        if ((index < 0) || (index >= this->_size))
            return false;

        for (int pos = index; pos < this->_size - 1; pos++)
        {
            _items[pos] = _items[pos + 1];
        }
        this->_size--;
        return true;
    }

    bool retrieve(int userIndex, T& dataItem) override
    {
        int index = userIndex - 1;
        if ((index < 0) || (index >= this->_size))
            return false;

        dataItem = _items[index];
        return true;
    }

    T returnItem(int i) override
    {
        return _items[i - 1];
    }

    int getLength() const override { return this->_size; }
};

template <typename T>
class ListLL : public ListBase<T>
{
private:
    struct ListNode
    {
        T item;
        ListNode* next;
    };

    ListNode* _head;

    ListNode* traverseTo(int index)
    {
        if ((index < 1) || (index > this->getLength()))
            return nullptr;

        ListNode* current = _head;
        for (int skip = 1; skip < index; ++skip)
            current = current->next;

        return current;
    }

public:
    ListLL() : _head(nullptr) { this->_size = 0; }
    ~ListLL() {}

    bool insert(int userIdx, T& newItem) override
    {
        int newLength = this->getLength() + 1;
        if ((userIdx < 1) || (userIdx > newLength))
            return false;

        ListNode* newPtr = new ListNode{ newItem, nullptr };
        this->_size = newLength;

        if (userIdx == 1)
        {
            newPtr->next = _head;
            _head = newPtr;
        }
        else
        {
            ListNode* prev = traverseTo(userIdx - 1);
            newPtr->next = prev->next;
            prev->next = newPtr;
        }

        return true;
    }

    bool remove(int userIdx) override
    {
        if ((userIdx < 1) || (userIdx > this->getLength()))
            return false;

        --this->_size;
        ListNode* current;

        if (userIdx == 1)
        {
            current = _head;
            _head = _head->next;
        }
        else
        {
            ListNode* prev = traverseTo(userIdx - 1);
            current = prev->next;
            prev->next = current->next;
        }

        delete current;
        return true;
    }

    bool retrieve(int userIdx, T& dataItem) override
    {
        if ((userIdx < 1) || (userIdx > this->getLength()))
            return false;

        ListNode* current = traverseTo(userIdx);
        dataItem = current->item;
        return true;
    }

    T returnItem(int i) override
    {
        ListNode* ptr = traverseTo(i);
        return ptr->item;
    }

    void copy(T*& tempType) override
    {
        tempType = new T[this->_size];
        ListNode* ptr = _head;
        for (int i = 0; i < this->_size; i++)
        {
            tempType[i] = ptr->item;
            ptr = ptr->next;
        }
    }
};

#endif

