class Railways;
class Station;

class Station {
    string name_;

public:
    Station(string stationName) : name_(stationName) {}

    bool operator==(const Station& other) const {
        return name_ == other.name_;
    }

    Station& operator=(const Station& other) {
        if (this != &other) {
            name_ = other.name_;
        }
        return *this;
    }

    string GetName() const {
        return name_;
    }

    int GetDistance(const Station& other, const vector<tuple<Station, Station, int>>& distanceData) const {
        for (const auto& eachStation : distanceData) {
            Station curr, dest;
            int dist = 0;
            tie(curr, dest, dist) = eachStation;

            if ((*this == curr && other == dest) || (*this == dest && other == curr)) {
                return dist;
            }
        }
        return -1; // Distance not found
    }
};

class Railways {
public:
    static vector<tuple<Station, Station, int>> sDistStations;
    static vector<Station> sStations;

    int GetDistance(const Station& src, const Station& dst) const {
        for (const auto& eachStation : sDistStations) {
            Station curr, next;
            int dist;
            tie(curr, next, dist) = eachStation;

            if (curr == src && next == dst) {
                return dist;
            }
        }
        return -1; // Distance not found
    }
};

