class Passenger {};

class Booking {
    static int sNextPNR;
    const Station fromStation_;
    const Station toStation_;
    const int pnr_ = ++sNextPNR;
    const bool bookingStatus_ = true;
    const string bookingMessage_ = "BOOKING SUCCEEDED";
    const Passenger* human;
    const Date bookingDate;
    const BookingClass* bookingClass;

public:
    static vector<Booking*> sBookings;

    int ComputeFare() const {
        Railways rail;
        double distance = rail.GetDistance(fromStation_, toStation_);
        double baseFare = BookingClass::sBaseFarePerKM;
        BookingClass* bookingClassPtr = const_cast<BookingClass*>(bookingClass);
        bool isAC = bookingClassPtr->IsAC();
        bool isLuxury = bookingClassPtr->IsLuxury();
        double loadFactor = bookingClassPtr->GetLoadFactor();

        int price = static_cast<int>((distance * baseFare * loadFactor + isAC * 50) * (1 + (isLuxury ? 0.25 : 0)) + 0.5);
        return price;
    }

    Booking(const Station& src, const Station& dest, const Date& now, BookingClass* b, Passenger* human = nullptr)
        : fromStation_(src), toStation_(dest), bookingDate(now), human(human), bookingClass(b) {
        sBookings.push_back(this);
    }

    ~Booking() {}

    friend ostream& operator<<(ostream& out, const Booking& booking);
};

ostream& operator<<(ostream& out, const Booking& booking) {
    out << booking.bookingMessage_ << ":" << endl;
    out << "PNR Number: " << booking.pnr_ << endl;
    out << "From Station: " << booking.fromStation_.GetName() << endl;
    out << "To Station: " << booking.toStation_.GetName() << endl;
    out << "Travel Date: " << booking.bookingDate << endl;
    out << *(const_cast<BookingClass*>(booking.bookingClass));
    out << "Fare: " << booking.ComputeFare() << endl << endl;
    return out;
}

