int userChoice; // Global variable to manage user choices for banking services.
char continueTransaction; // Variable to control transaction flow.

long int transactionHistory[4]; // Array to store transaction history for the client.

using namespace std;

// Class representing a bank account with various functionalities.
class BankAccount {
private:
    long int balance; // Current balance of the account.
    string passcode; // Password for account access.
    string accountHolder; // Name of the account holder.
    string username; // Username for account access.

public:
    void displayMenu(); // Displays the banking menu.
    void registerAccount(); // Handles account registration.
    void login(); // Manages user login.
    void deposit(); // Handles deposit transactions.
    void withdraw(); // Handles withdrawal transactions.
    void checkBalance(); // Displays the current balance.
    void transferMoney(); // Manages money transfer between accounts.
    void viewMiniStatement(); // Displays a mini statement of transactions.
};

int main() {
    BankAccount account;
    account.registerAccount();
    account.login();

    do {
        account.displayMenu();
        switch (userChoice) {
            case 1:
                account.deposit();
                break;
            case 2:
                account.withdraw();
                break;
            case 3:
                account.checkBalance();
                break;
            case 4:
                account.transferMoney();
                break;
            case 5:
                account.viewMiniStatement();
                break;
            default:
                cout << "Invalid choice, please try again!" << endl;
                break;
        }
    } while (continueTransaction == 'y' || continueTransaction == 'Y');

    getch();
    return 0;
}

// Function to register a new bank account.
void BankAccount::registerAccount() {
    string name;
    string account;
    string password;

    cout << "WELCOME TO E-Banking Developed by H.Emmanuel\n\n";
    cout << "Enter your username: ";
    cin >> name;
    cout << "Enter an Account: ";
    cin >> account;
    cout << "Choose Password: ";
    cin >> password;

    username = name;
    accountHolder = account;
    passcode = password;

    cout << "Registration successful! Welcome to E-Banking [" << username << "]" << endl;
}

// Function to log in to the bank account.
void BankAccount::login() {
    string password;

    do {
        cout << "Login (Password): ";
        cin >> password;

        if (password == passcode) {
            cout << "Successfully logged in as [" << username << "]" << endl << endl;
            cout << "Enjoy our E-Banking services! Here is the menu below:\n\n";
            break;
        } else {
            cout << "Incorrect password, please try again." << endl;
        }
    } while (true);
}

// Function to deposit money into the account.
void BankAccount::deposit() {
    string password;
    long int amount;

    do {
        cout << "Provide Password: ";
        cin >> password;

        if (password == passcode) {
            cout << "\nEnter Amount to Deposit: ";
            cin >> amount;

            balance += amount;
            transactionHistory[0] = balance;

            cout << "Thank you, you have deposited: " << amount << " RwF\n\n";
            cout << "Do you want to perform another transaction? (y/Y for yes, n/N for no): ";
            cin >> continueTransaction;
            break;
        } else {
            cout << "Incorrect password, please try again!" << endl;
        }
    } while (true);
}

// Function to withdraw money from the account.
void BankAccount::withdraw() {
    long int amount;
    string password;

    do {
        cout << "Provide Password: ";
        cin >> password;

        if (password == passcode) {
            cout << "Enter Amount to Withdraw: ";
            cin >> amount;

            if (amount > 0 && amount <= balance) {
                balance -= amount;
                transactionHistory[1] = balance;

                cout << "Thank you, you have successfully withdrawn: " << amount << " RwF\n\n";
            } else {
                cout << "Transaction failed: Invalid withdrawal amount." << endl;
            }

            cout << "Do you want to perform another transaction? (y/Y for yes, n/N for no): ";
            cin >> continueTransaction;
            break;
        } else {
            cout << "Incorrect password, please try again!" << endl;
        }
    } while (true);
}

// Function to check the current balance of the account.
void BankAccount::checkBalance() {
    string password;

    do {
        cout << "Provide Password: ";
        cin >> password;

        if (password == passcode) {
            cout << "Your current balance is: " << balance << " RWF" << endl;
            cout << "\nThank you for banking with us!\n\n";
            cout << "Do you want to perform another transaction? (y/Y for yes, n/N for no): ";
            cin >> continueTransaction;
            break;
        } else {
            cout << "Incorrect password, please try again!" << endl;
        }
    } while (true);
}

// Function to transfer money to another account.
void BankAccount::transferMoney() {
    long int amount;
    string recipientAccount;
    string password;

    do {
        cout << "Provide Password: ";
        cin >> password;

        if (password == passcode) {
            cout << "Enter Amount to Transfer: ";
            cin >> amount;

            if (amount > 0 && amount <= balance) {
                cout << "Enter Recipient Account Number: ";
                cin >> recipientAccount;

                balance -= amount;
                transactionHistory[2] = balance;

                cout << "You have successfully transferred: " << amount << " RwF to [" << recipientAccount << "]" << endl;
                cout << "\nThank you for banking with us!\n";
            } else {
                cout << "Transaction failed: Invalid transfer amount." << endl;
            }

            cout << "Do you want to perform another transaction? (y/Y for yes, n/N for no): ";
            cin >> continueTransaction;
            break;
        } else {
            cout << "Incorrect password, please try again!" << endl;
        }
    } while (true);
}

// Function to view a mini statement of transactions.
void BankAccount::viewMiniStatement() {
    cout << "Retrieved transaction information:" << endl;
    for (int index = 0; index < 3; index++) {
        cout << transactionHistory[index] << endl;
    }
    cout << "\nThank you for banking with us!\n";
    cout << "Do you want to perform another transaction? (y/Y for yes, n/N for no): ";
    cin >> continueTransaction;
}

