istream& operator>>(istream& is, Date& date) {
    try {
        do {
            cout << "Nhap ngay: ";
            is >> date._day;
            if (is.fail())
                throw "Ngay nhap vao khong dung";
            cout << "Nhap thang: ";
            is >> date._month;
            if (is.fail())
                throw "Thang nhap vao khong dung";
            cout << "Nhap nam (bat dau tu nam 1900): ";
            is >> date._year;
            if (is.fail())
                throw "Nam nhap vao khong dung";
            cout << endl;
        } while (!date.IsValidDate(date._day, date._month, date._year));

        return is;
    } catch (const char* error) {
        cerr << error << endl;
        exit(-2);
    }
}

// Overloaded output operator for displaying date
ostream& operator<<(ostream& os, const Date& date) {
    os << date._day << "/" << date._month << "/" << date._year;
    return os;
}

// Function to read date from file input stream
istream& inputDateFromFile(istream& is, Date& date) {
    try {
        char delimiter;
        do {
            is >> date._day;
            if (is.fail())
                throw "Ngay nhap vao khong dung";

            is >> delimiter;

            is >> date._month;
            if (is.fail())
                throw "Thang nhap vao khong dung";

            is >> delimiter;

            is >> date._year;
            if (is.fail())
                throw "Nam nhap vao khong dung";
        } while (!date.IsValidDate(date._day, date._month, date._year));

        return is;
    } catch (const char* error) {
        cerr << error << endl;
        exit(-2);
    }
}

// Check if a given year is a leap year
bool Date::IsLeapYear(int year) const {
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

// Validate the date based on day, month, and year
bool Date::IsValidDate(int day, int month, int year) const {
    if (year < 1900)
        return false;

    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return (day > 0 && day <= 31);
        case 4: case 6: case 9: case 11:
            return (day > 0 && day <= 30);
        case 2:
            return (IsLeapYear(year) ? (day > 0 && day <= 29) : (day > 0 && day <= 28));
        default:
            return false;
    }
}

// Return the number of days in a given month of a specific year
int Date::DaysInMonth(int month, int year) const {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return IsLeapYear(year) ? 29 : 28;
        default:
            return 0;
    }
}

// Calculate the previous day given the current day, month, and year
void Date::PreviousDay(int& day, int& month, int& year) const {
    if (IsValidDate(day, month, year)) {
        day--;
        if (day == 0) {
            month--;
            if (month == 0) {
                year--;
                month = 12;
                day = 31;
            } else {
                day = DaysInMonth(month, year);
            }
        }
    }
}

// Count the number of days between the current date and another date
int Date::CountDaysUntil(const Date& targetDate) const {
    int count = 0;
    int d = _day;
    int m = _month;
    int y = _year;

    if (IsValidDate(d, m, y)) {
        while (d != targetDate._day || m != targetDate._month || y != targetDate._year) {
            PreviousDay(d, m, y);
            count++;
        }
    }
    return count;
}

