#ifndef CSV_HANDLER_H
#define CSV_HANDLER_H

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <cinttypes>
#include <initializer_list>

#ifdef _MSC_VER
#define _CRT_SECURE_NO_WARNINGS
#endif

#define REAL_EPSILON 1e-6
#define STRING_BUFFER_SIZE 256
#define Integer int
#define LongLong long long
#define Character char
#define CharPointer char*
#define DoublePrecision double

namespace Csv
{
    // Copies the string 'from' to 'to' dynamically, ensuring sufficient memory allocation.
    inline void copy_string(const CharPointer from, CharPointer& to)
    {
        to = (CharPointer)malloc(strlen(from) + 1);
        for (CharPointer p = to; (*p = *from) != '\0'; ++p, ++from);
    }

    // Represents a value that can be of multiple types.
    class MultiType
    {
    private:
        union Value
        {
            Integer intValue;
            LongLong longValue;
            Character charValue;
            CharPointer stringValue;
            DoublePrecision doubleValue;
        } value;
        CharPointer typeName;

    public:
        // Default constructor initializes to unknown type.
        MultiType()
        {
            initialize();
        }

        // Constructors for various types.
        MultiType(const Integer e) { assign(e); }
        MultiType(const LongLong e) { assign(e); }
        MultiType(const Character e) { assign(e); }
        MultiType(const CharPointer e) { assign(e); }
        MultiType(const DoublePrecision e) { assign(e); }
        MultiType(const MultiType& e) { assign(e); }

        // Resets the MultiType to its default state.
        void initialize()
        {
            copy_string("unknown", typeName);
        }

        // Assignment functions for different types.
        void assign(const Integer e)
        {
            copy_string("int", typeName);
            value.intValue = e;
        }

        void assign(const LongLong e)
        {
            copy_string("long", typeName);
            value.longValue = e;
        }

        void assign(const Character e)
        {
            copy_string("char", typeName);
            value.charValue = e;
        }

        void assign(const CharPointer e)
        {
            copy_string("str", typeName);
            copy_string(e, value.stringValue);
        }

        void assign(const DoublePrecision e)
        {
            copy_string("double", typeName);
            value.doubleValue = e;
        }

        void assign(const MultiType& e)
        {
            copy_string(e.get_type(), typeName);
            if (e.is_type("int")) value.intValue = e.to_int();
            else if (e.is_type("long")) value.longValue = e.to_long();
            else if (e.is_type("char")) value.charValue = e.to_char();
            else if (e.is_type("str")) copy_string(e.to_string(), value.stringValue);
            else if (e.is_type("double")) value.doubleValue = e.to_double();
        }

        MultiType& operator= (const Integer e) { assign(e); return *this; }
        MultiType& operator= (const LongLong e) { assign(e); return *this; }
        MultiType& operator= (const Character e) { assign(e); return *this; }
        MultiType& operator= (const CharPointer e) { assign(e); return *this; }
        MultiType& operator= (const DoublePrecision e) { assign(e); return *this; }
        MultiType& operator= (const MultiType& e) { assign(e); return *this; }

        // Appends the string representation of 'e' to this MultiType, changing its type to "str".
        MultiType& append(const MultiType& e)
        {
            Character* currentString = to_string();
            Character* appendString = e.to_string();
            Character* resultString = new Character[strlen(currentString) + strlen(appendString) + 1];
            Integer j = 0;
            for (Integer i = 0; i < (Integer)strlen(currentString); resultString[j++] = currentString[i++]);
            for (Integer i = 0; i < (Integer)strlen(appendString); resultString[j++] = appendString[i++]);
            resultString[j] = '\0';
            assign(resultString);
            return *this;
        }

        // Returns the type of the current value as a string.
        CharPointer get_type() const
        {
            return typeName;
        }

        // Checks if the current value matches the specified type.
        bool is_type(const CharPointer e) const
        {
            return strcmp(typeName, e) == 0;
        }

        // Checks if the value has not been set yet.
        bool is_unknown() const
        {
            return is_type("unknown");
        }

        // Converts the current value to an integer.
        Integer to_int() const
        {
            if (is_type("int")) return value.intValue;
            if (is_type("long")) return value.longValue;
            if (is_type("char")) return value.charValue >= '0' && value.charValue <= '9' ? (value.charValue - '0') : (Integer)value.charValue;
            if (is_type("str"))
            {
                bool isNegative = value.stringValue[0] == '-';
                Integer result = 0;
                for (Integer i = isNegative; i < (Integer)strlen(value.stringValue); ++i)
                    if (value.stringValue[i] >= '0' && value.stringValue[i] <= '9')
                        result = result * 10 + value.stringValue[i] - '0';
                    else
                        break;
                return isNegative ? -result : result;
            }
            if (is_type("double")) return (Integer)value.doubleValue;
            return 0;
        }

        // Converts the current value to a long long.
        LongLong to_long() const
        {
            if (is_type("int")) return value.intValue;
            if (is_type("long")) return value.longValue;
            if (is_type("char")) return value.charValue >= '0' && value.charValue <= '9' ? (value.charValue - '0') : (LongLong)value.charValue;
            if (is_type("str"))
            {
                bool isNegative = value.stringValue[0] == '-';
                LongLong result = 0;
                for (Integer i = isNegative; i < (Integer)strlen(value.stringValue); ++i)
                    if (value.stringValue[i] >= '0' && value.stringValue[i] <= '9')
                        result = result * 10 + value.stringValue[i] - '0';
                    else
                        break;
                return isNegative ? -result : result;
            }
            if (is_type("double")) return (LongLong)value.doubleValue;
            return 0;
        }

        // Converts the current value to a character.
        Character to_char() const
        {
            if (is_type("int"))
            {
                Character buffer[2];
                snprintf(buffer, 2, "%d", value.intValue);
                return buffer[0];
            }
            if (is_type("char")) return value.charValue;
            if (is_type("str")) return value.stringValue[0];
            if (is_type("double"))
            {
                Character buffer[2];
                snprintf(buffer, 2, "%f", value.doubleValue);
                return buffer[0];
            }
            return 0;
        }

        // Converts the current value to a string.
        CharPointer to_string() const
        {
            if (is_type("int"))
            {
                CharPointer buffer = new Character[STRING_BUFFER_SIZE];
                snprintf(buffer, STRING_BUFFER_SIZE, "%d", value.intValue);
                return buffer;
            }
            if (is_type("long"))
            {
                CharPointer buffer = new Character[STRING_BUFFER_SIZE];
                snprintf(buffer, STRING_BUFFER_SIZE, "%" PRId64, value.longValue);
                return buffer;
            }
            if (is_type("char"))
            {
                CharPointer buffer = new Character[2];
                buffer[0] = value.charValue;
                return buffer;
            }
            if (is_type("str")) return value.stringValue;
            if (is_type("double"))
            {
                CharPointer buffer = new Character[STRING_BUFFER_SIZE];
                snprintf(buffer, STRING_BUFFER_SIZE, "%.15f", value.doubleValue);

                // Trim trailing zeroes
                char* p = strchr(buffer, '.');
                int count;

                if (p != NULL)
                {
                    count = 10;
                    while (count >= 0)
                    {
                        --count;
                        if (*p == '\0') break;
                        ++p;
                    }
                    *p-- = '\0';
                    while (*p == '0') *p-- = '\0';
                    if (*p == '.') *p = '\0';
                }
                return buffer;
            }
            CharPointer buffer = new Character[1]; buffer[0] = '\0';
            return buffer;
        }

        // Converts the current value to a double.
        DoublePrecision to_double() const
        {
            if (is_type("int")) return (DoublePrecision)value.intValue;
            if (is_type("long")) return (DoublePrecision)value.longValue;
            if (is_type("char"))
            {
                if (value.charValue >= '0' && value.charValue <= '9')
                    return value.charValue - '0';
            }
            if (is_type("str"))
            {
                bool isNegative = value.stringValue[0] == '-';
                DoublePrecision result = 0;
                Integer i = isNegative;
                for (; i < (Integer)strlen(value.stringValue); ++i)
                    if (value.stringValue[i] >= '0' && value.stringValue[i] <= '9')
                        result = result * 10 + value.stringValue[i] - '0';
                    else
                        break;
                if (i < (Integer)strlen(value.stringValue) && value.stringValue[i++] == '.')
                {
                    for (DoublePrecision j = 0.1; i < (Integer)strlen(value.stringValue); ++i, j /= 10)
                        if (value.stringValue[i] >= '0' && value.stringValue[i] <= '9')
                            result += j * (value.stringValue[i] - '0');
                        else
                            break;
                }
                return isNegative ? -result : result;
            }
            if (is_type("double")) return value.doubleValue;

            #ifdef NAN
            return NAN;
            #elif defined INFINITY
            return INFINITY;
            #else
            return 0;
            #endif
        }

        // Compares two MultiTypes, converting values to the same logical type if necessary.
        bool equals(const MultiType& e) const
        {
            if (is_type(e.get_type())) return strict_equals(e);
            if (is_type("str") || e.is_type("str")) return strcmp(to_string(), e.to_string()) == 0;
            if (is_type("double") || e.is_type("double")) return fabs(to_double() - e.to_double()) < REAL_EPSILON;
            return to_long() == e.to_long();
        }

        // Strict comparison without type conversion.
        bool strict_equals(const MultiType& e) const
        {
            if (!is_type(e.get_type())) return false;
            if (is_type("int")) return value.intValue == e.to_int();
            if (is_type("long")) return value.longValue == e.to_long();
            if (is_type("char")) return value.charValue == e.to_char();
            if (is_type("str")) return strcmp(value.stringValue, e.to_string()) == 0;
            if (is_type("double")) return fabs(value.doubleValue - e.to_double()) < REAL_EPSILON;
            return false;
        }
    };

    // A linked list implementation with basic operations.
    template<typename T>
    class List
    {
    private:
        struct Node
        {
            Node* next;
            T value;
        } *head;
        Integer size;

        void destroy_util(Node* root)
        {
            if (root->next == nullptr) return;
            destroy_util(root->next);
            delete[] root->next;
            root->next = nullptr;
            --size;
        }

    public:
        // Constructor initializes the list with a specified number of elements.
        List(Integer num_elements = 0)
        {
            head = new Node();
            size = 0;
            for (Integer i = 0; i < num_elements; ++i)
                push_back(T());
        }

        List(std::initializer_list<MultiType> elements)
        {
            head = new Node();
            size = 0;
            for (MultiType item : elements)
                push_back(item);
        }

        // Adds an element to the end of the list.
        void push_back(const T& e)
        {
            Node* current = head;
            while (current->next != nullptr)
                current = current->next;
            current->next = new Node();
            current->next->value = e;
            ++size;
        }

        // Adds an element to the front of the list.
        void push_front(const T& e)
        {
            Node* newNode = new Node();
            newNode->next = head->next;
            newNode->next->value = e;
            head->next = newNode;
            ++size;
        }

        // Removes and returns the last element of the list.
        T pop_back()
        {
            if (empty()) return T();
            Node* current = head;
            while (current->next->next != nullptr)
                current = current->next;
            T value = current->next->value;
            delete[] current->next;
            current->next = nullptr;
            --size;
            return value;
        }

        // Removes and returns the first element of the list.
        T pop_front()
        {
            if (empty()) return T();
            Node* nextNode = head->next->next;
            T value = head->next->value;
            delete[] head->next;
            head->next = nextNode;
            --size;
            return value;
        }

        // Inserts an element at the specified position.
        void insert(Integer pos, const T& e)
        {
            Node* current = head;
            while (pos-- && current->next != nullptr)
                current = current->next;
            Node* newNode = new Node();
            newNode->next = current->next;
            newNode->next->value = e;
            current->next = newNode;
            ++size;
        }

        // Destroys the list, deleting all elements.
        void destroy()
        {
            destroy_util(head);
        }

        // Checks if the list is empty.
        bool empty() const
        {
            return head->next == nullptr;
        }

        // Returns the size of the list.
        Integer get_size() const
        {
            return size;
        }

        // Returns the value at the specified position.
        T& at(Integer pos)
        {
            if (pos < 0 || pos >= size) return *new T();
            Node* current = head;
            while (pos-- && current->next != nullptr)
                current = current->next;
            return current->next != nullptr ? current->next->value : *new T();
        }

        T at(Integer pos) const
        {
            if (pos < 0 || pos >= size) return T();
            Node* current = head;
            while (pos-- && current->next != nullptr)
                current = current->next;
            return current->next != nullptr ? current->next->value : T();
        }

        // Removes the element at the specified position.
        void delete_at(Integer pos)
        {
            if (pos < 0 || pos >= size) return;
            Node* current = head;
            while (pos-- && current->next != nullptr)
                current = current->next;
            Node* nextNode = current->next != nullptr ? current->next->next : nullptr;
            delete[] current->next;
            current->next = nextNode;
            --size;
        }

        // Creates a copy of the list.
        List<T> copy() const
        {
            List<T> result;
            for (int i = 0; i < size; ++i)
                result.push_back(at(i));
            return result;
        }
    };

    // Main database handler for the project.
    class Table
    {
    private:
        struct RowList
        {
            RowList* next;
            List<MultiType> value;
        } *rows;
        List<MultiType> keys;

        Integer num_rows;

    public:
        // Constructor initializes the table.
        Table()
        {
            rows = new RowList();
            num_rows = 0;
        }

        // Adds a new column with the specified name to the table.
        void add_key(const MultiType& e)
        {
            if (has_key(e)) return;
            keys.push_back(e);
            RowList* current = rows;
            while (current->next != nullptr)
            {
                current->next->value.push_back(MultiType());
                current = current->next;
            }
        }

        // Removes a column with the specified name from the table.
        void remove_key(const MultiType& e)
        {
            for (Integer i = 0; i < keys.get_size(); ++i)
                if (e.strict_equals(keys.at(i)))
                {
                    keys.delete_at(i);
                    RowList* current = rows;
                    while (current->next != nullptr)
                    {
                        current->next->value.delete_at(i);
                        current = current->next;
                    }
                    return;
                }
        }

        // Returns the index of the specified column name.
        Integer get_key(const MultiType& e) const
        {
            for (Integer i = 0; i < keys.get_size(); ++i)
                if (e.strict_equals(keys.at(i)))
                    return i;
            return -1;
        }

        // Checks if the table contains a column with the specified name.
        bool has_key(const MultiType& e) const
        {
            return get_key(e) != -1;
        }

        // Returns a copy of the list of all column names.
        List<MultiType> get_keys() const
        {
            return keys.copy();
        }

        // Fixes the table keys to match a specified list of keys.
        void fix_keys(List<MultiType> newKeys)
        {
            List<MultiType> currentKeys = get_keys();
            for (Integer i = 0; i < currentKeys.get_size(); ++i)
            {
                bool exists = false;
                for (Integer j = 0; j < newKeys.get_size(); ++j)
                    if (currentKeys.at(i).equals(newKeys.at(j)))
                        exists = true;
                if (!exists) remove_key(currentKeys.at(i));
            }
            for (Integer i = 0; i < newKeys.get_size(); ++i)
                add_key(newKeys.at(i));

            // Sort the columns
            for (Integer i = 0; i < newKeys.get_size(); ++i)
                for (Integer j = i + 1; j < newKeys.get_size(); ++j)
                {
                    Integer key_i = get_key(newKeys.at(i)),
                            key_j = get_key(newKeys.at(j));
                    if (key_i > key_j)
                    {
                        for (Integer k = 0; k < num_rows(); ++k)
                        {
                            MultiType temp = get_row(k).at(key_i);
                            get_row(k).at(key_i).assign(get_row(k).at(key_j));
                            get_row(k).at(key_j).assign(temp);
                        }
                        MultiType temp = newKeys.at(i);
                        newKeys.at(i) = newKeys.at(j);
                        newKeys.at(j) = temp;
                        temp = keys.at(key_i);
                        keys.at(key_i) = keys.at(key_j);
                        keys.at(key_j) = temp;
                    }
                }
        }

        // Adds a new row to the table.
        void add_row()
        {
            RowList* current = rows;
            while (current->next != nullptr)
                current = current->next;
            current->next = new RowList();
            current->next->value = List<MultiType>(keys.get_size());
            ++num_rows;
        }

        // Removes the specified row from the table.
        void remove_row(Integer row)
        {
            if (row < 0 || row >= num_rows) return;
            RowList* current = rows;
            while (row-- && current->next != nullptr)
                current = current->next;
            RowList* nextRow = current->next != nullptr ? current->next->next : nullptr;
            delete[] current->next;
            current->next = nextRow;
            --num_rows;
        }

        // Returns the number of rows in the table.
        Integer num_rows() const
        {
            return num_rows;
        }

        // Returns the specified row.
        List<MultiType>& get_row(Integer row)
        {
            if (row < 0 || row >= num_rows) return *new List<MultiType>();
            RowList* current = rows;
            while (row-- && current->next != nullptr)
                current = current->next;
            return current->next != nullptr ? current->next->value : *new List<MultiType>();
        }

        List<MultiType> get_row(Integer row) const
        {
            if (row < 0 || row >= num_rows) return List<MultiType>();
            RowList* current = rows;
            while (row-- && current->next != nullptr)
                current = current->next;
            return current->next != nullptr ? current->next->value.copy() : List<MultiType>();
        }

        // Returns the row where the specified column has the given value.
        List<MultiType>& get_row_where(const MultiType& key_search, const MultiType& e, bool strict = false)
        {
            Integer key_id = get_key(key_search);
            if (key_id == -1) return *new List<MultiType>();
            RowList* current = rows;
            while (current->next != nullptr)
            {
                if (strict ? current->next->value.at(key_id).strict_equals(e) : current->next->value.at(key_id).equals(e))
                    return current->next->value;
                current = current->next;
            }
            return *new List<MultiType>();
        }

        List<MultiType> get_row_where(const MultiType& key_search, const MultiType& e, bool strict = false) const
        {
            Integer key_id = get_key(key_search);
            if (key_id == -1) return List<MultiType>();
            RowList* current = rows;
            while (current->next != nullptr)
            {
                if (strict ? current->next->value.at(key_id).strict_equals(e) : current->next->value.at(key_id).equals(e))
                    return current->next->value.copy();
                current = current->next;
            }
            return List<MultiType>();
        }

        // Returns the value of the specified column in the specified row.
        MultiType& get(Integer row, const MultiType& key)
        {
            if (row < 0 || row >= num_rows) return *new MultiType("bad_access");
            RowList* current = rows;
            while (row-- && current->next != nullptr)
                current = current->next;
            Integer pos = get_key(key);
            return pos == -1 ? (*new MultiType("bad_access")) : (current->next != nullptr ? current->next->value.at(pos) : *new MultiType());
        }

        MultiType get(Integer row, const MultiType& key) const
        {
            if (row < 0 || row >= num_rows) return MultiType("bad_access");
            RowList* current = rows;
            while (row-- && current->next != nullptr)
                current = current->next;
            Integer pos = get_key(key);
            return pos == -1 ? (*new MultiType("bad_access")) : (current->next != nullptr ? current->next->value.at(pos) : MultiType());
        }

        // Returns the value of the specified column in the row where the specified column has the given value.
        MultiType& get_where(const MultiType& key_search, const MultiType& e, const MultiType& key_get, bool strict = false)
        {
            Integer key_sid = get_key(key_search), key_gid = get_key(key_get);
            if (key_sid == -1 || key_gid == -1) return *new MultiType("bad_access");
            RowList* current = rows;
            while (current->next != nullptr)
            {
                if (strict ? current->next->value.at(key_sid).strict_equals(e) : current->next->value.at(key_sid).equals(e))
                    return current->next->value.at(key_gid);
                current = current->next;
            }
            return *new MultiType("bad_access");
        }

        MultiType get_where(const MultiType& key_search, const MultiType& e, const MultiType& key_get, bool strict = false) const
        {
            Integer key_sid = get_key(key_search), key_gid = get_key(key_get);
            if (key_sid == -1 || key_gid == -1) return MultiType("bad_access");
            RowList* current = rows;
            while (current->next != nullptr)
            {
                if (strict ? current->next->value.at(key_sid).strict_equals(e) : current->next->value.at(key_sid).equals(e))
                    return current->next->value.at(key_gid);
                current = current->next;
            }
            return MultiType("bad_access");
        }

        // Deletes the first row where the specified column has the given value.
        bool remove_row_where(const MultiType& key_search, const MultiType& e, bool strict = false)
        {
            Integer key_sid = get_key(key_search);
            if (key_sid == -1) return false;
            RowList* current = rows;
            while (current->next != nullptr)
            {
                if (strict ? current->next->value.at(key_sid).strict_equals(e) : current->next->value.at(key_sid).equals(e))
                {
                    RowList* nextRow = current->next->next;
                    delete[] current->next;
                    current->next = nextRow;
                    --num_rows;
                    return true;
                }
                current = current->next;
            }
            return false;
        }

        // Creates a new table based on the current one using a filter function.
        table filter(bool(*filter_func)(MultiType, List<MultiType>, Table)) const
        {
            int numKeys = get_keys().get_size(), numRows = num_rows();
            bool* markRow = new bool[numRows], *markCol = new bool[numKeys];
            memset(markRow, 0, numRows * sizeof(bool));
            memset(markCol, 0, numKeys * sizeof(bool));
            for (int i = 0; i < numRows; ++i)
                for (int j = 0; j < numKeys; ++j)
                    if (filter_func(get_keys().at(j), get_row(i), (*this)))
                        markRow[i] = markCol[j] = true;
            Table new_table;
            for (int i = 0; i < numKeys; ++i)
                if (markCol[i])
                    new_table.add_key(get_keys().at(i));
            for (int i = 0; i < numRows; ++i)
                if (markRow[i])
                {
                    new_table.add_row();
                    for (int j = 0; j < numKeys; ++j)
                        new_table.get(new_table.num_rows() - 1, get_keys().at(j)) = get_row(i).at(j);
                }
            return new_table;
        }
    };

    // CSV file reader/writer class.
    class CsvHandler
    {
    private:
        Table tableInstance;
        CharPointer filename;
        FILE* filePointer;

        List<Character> csvString;
        bool blankLineFlag = false;

        Character read_csv_char()
        {
            if (filePointer == nullptr || feof(filePointer)) return '\0';
            Integer ch = fgetc(filePointer);
            if (ch == EOF)
            {
                if (!blankLineFlag) return '\n';
                blankLineFlag = true;
                return '\0';
            }
            if (ch >= 32 && ch <= 126) csvString.push_back((Character)ch);
            return ch;
        }

        Character break_csv_line()
        {
            if (filePointer == nullptr || feof(filePointer)) return '\0';
            while (true)
            {
                Integer ch = fgetc(filePointer);
                if (ch == EOF) return '\0';
                if (ch == '\n') return '\n';
            }
            return '\0';
        }

        CharPointer export_csv_string()
        {
            CharPointer result = new Character[csvString.get_size() + 1];
            Integer i = 0;
            for (; !csvString.empty(); ++i)
                result[i] = csvString.pop_front();
            result[i] = '\0';
            return result;
        }

    public:
        // Constructor initializes the CSV handler with the specified filename.
        CsvHandler(const CharPointer _filename)
        {
            tableInstance = Table();
            copy_string(_filename, filename);
            filePointer = nullptr;
        }

        // Opens the CSV file for reading.
        bool init_read()
        {
            blankLineFlag = false;
            return (filePointer = fopen(filename, "r")) != nullptr;
        }

        // Opens the CSV file for writing.
        bool init_write()
        {
            return (filePointer = fopen(filename, "w")) != nullptr;
        }

        // Reads the CSV file into the table.
        void read_and_terminate(const Character delimiter = ',')
        {
            if (filePointer == nullptr) return;
            while (!csvString.empty()) csvString.pop_back();
            Character ch;

            // Read table header
            do
            {
                ch = read_csv_char();
                if (ch == delimiter) csvString.pop_back();
                if (ch == delimiter || ch == '\n') tableInstance.add_key(export_csv_string());
            }
            while (ch != '\n');

            // Read table rows
            bool flag = true;
            for (Integer i = 0; flag; ++i)
            {
                tableInstance.add_row();
                Integer j = 0;
                while (j < tableInstance.get_keys().get_size())
                {
                    Character ch = read_csv_char();
                    if (ch == '\0')
                    {
                        flag = false;
                        break;
                    }
                    if (ch == '\n')
                    {
                        tableInstance.get_row(i).at(j++).assign(export_csv_string());
                        break;
                    }
                    if (ch == delimiter)
                    {
                        csvString.pop_back();
                        tableInstance.get_row(i).at(j++).assign(export_csv_string());
                        if (j == tableInstance.get_keys().get_size()) break_csv_line();
                    }
                }
            }

            // Remove trailing invalid rows
            for (Integer i = tableInstance.num_rows() - 1; i >= 0; --i)
            {
                bool hasUnknown = false;
                List<MultiType> row = tableInstance.get_row(i);
                for (Integer j = 0; j < row.get_size(); ++j)
                    hasUnknown |= row.at(j).is_unknown();
                if (hasUnknown) tableInstance.remove_row(i);
            }

            terminate();
        }

        // Exports the table to the CSV file.
        void write_and_terminate(const Character delimiter = ',')
        {
            if (filePointer == nullptr) return;

            // Write header
            Integer numHeads = tableInstance.get_keys().get_size();
            for (Integer i = 0; i < numHeads; ++i)
                if (i == numHeads - 1)
                    fprintf(filePointer, "%s", tableInstance.get_keys().at(i).to_string());
                else
                    fprintf(filePointer, "%s%c", tableInstance.get_keys().at(i).to_string(), delimiter);
            fprintf(filePointer, "\n");

            // Write rows
            for (Integer i = 0; i < tableInstance.num_rows(); ++i)
            {
                Integer numCols = tableInstance.get_row(i).get_size();
                for (Integer j = 0; j < numCols; ++j)
                    if (j == numCols - 1)
                        fprintf(filePointer, "%s", tableInstance.get_row(i).at(j).to_string());
                    else
                        fprintf(filePointer, "%s%c", tableInstance.get_row(i).at(j).to_string(), delimiter);
                fprintf(filePointer, "\n");
            }

            terminate();
        }

        // Closes the file stream.
        void terminate()
        {
            fclose(filePointer);
        }

        // Returns the table instance.
        Table& get_table()
        {
            return tableInstance;
        }

        Table get_table() const
        {
            return tableInstance;
        }
    };
};

