#ifndef __FLEX_LEXER_H
#define __FLEX_LEXER_H

#include <iostream>

extern "C++" {

struct BufferState;
typedef int StateType;

class FlexLexer
{
public:
  virtual ~FlexLexer() { }

  const char* GetText() const { return textBuffer; }
  int GetLength() const { return length; }

  virtual void SwitchToBuffer(BufferState* newBuffer) = 0;
  virtual BufferState* CreateBuffer(std::istream* inputStream, int size) = 0;
  virtual BufferState* CreateBuffer(std::istream& inputStream, int size) = 0;
  virtual void DeleteBuffer(BufferState* buffer) = 0;
  virtual void Restart(std::istream* inputStream) = 0;
  virtual void Restart(std::istream& inputStream) = 0;

  virtual int Lex() = 0;

  // Call Lex with new input/output sources.
  int Lex(std::istream& newInput, std::ostream& newOutput)
  {
    SwitchStreams(newInput, newOutput);
    return Lex();
  }

  int Lex(std::istream* newInput, std::ostream* newOutput = nullptr)
  {
    SwitchStreams(newInput, newOutput);
    return Lex();
  }

  // Switch to new input/output streams. A nullptr stream pointer
  // indicates "keep the current one".
  virtual void SwitchStreams(std::istream* newInput, std::ostream* newOutput) = 0;
  virtual void SwitchStreams(std::istream& newInput, std::ostream& newOutput) = 0;

  int GetLineNumber() const { return lineNumber; }

  int IsDebugEnabled() const { return debugFlag; }
  void SetDebug(int flag) { debugFlag = flag; }

protected:
  char* textBuffer;
  int length;
  int lineNumber;       // only maintained if you use %option yylineno
  int debugFlag;       // only has effect with -d or "%option debug"
};

}

