  // Input and output streams default to cin and cout, but
  // assignments are made during initialization in Lex().
  yyFlexLexer(std::istream& inputStream, std::ostream& outputStream);
  yyFlexLexer(std::istream* inputStream = nullptr, std::ostream* outputStream = nullptr);
private:
  void CommonConstructor();

public:
  virtual ~yyFlexLexer();

  void SwitchToBuffer(BufferState* newBuffer);
  BufferState* CreateBuffer(std::istream* inputStream, int size);
  BufferState* CreateBuffer(std::istream& inputStream, int size);
  void DeleteBuffer(BufferState* buffer);
  void Restart(std::istream* inputStream);
  void Restart(std::istream& inputStream);

  void PushBufferState(BufferState* newBuffer);
  void PopBufferState();

  virtual int Lex();
  virtual void SwitchStreams(std::istream& newInput, std::ostream& newOutput);
  virtual void SwitchStreams(std::istream* newInput = nullptr, std::ostream* newOutput = nullptr);
  virtual int Wrap();

protected:
  virtual int Input(char* buffer, int maxSize);
  virtual void Output(const char* buffer, int size);
  virtual void Error(const char* message);

  void Unput(int character, char* bufferPointer);
  int Input();

  void LoadBufferState();
  void InitBuffer(BufferState* buffer, std::istream& inputStream);
  void FlushBuffer(BufferState* buffer);

  int startStackPointer;
  int startStackDepth;
  int* startStack;

  void PushState(int newState);
  void PopState();
  int TopState();

  StateType GetPreviousState();
  StateType TryNULTransition(StateType currentState);
  int GetNextBuffer();

  std::istream inputStream;  // input source for default Input
  std::ostream outputStream; // output sink for default Output

  char holdCharacter; // holds the character lost when textBuffer is formed.

  int numCharsRead; // Number of characters read into charBuffer.
  char* currentBufferPointer; // Points to current character in buffer.

  int needsInitialization; // whether we need to initialize
  int startState; // start state number

  // Flag to allow Wrap() to perform buffer switches instead of setting up a fresh inputStream.
  int didBufferSwitchOnEOF;

  size_t bufferStackTop; /**< index of top of stack. */
  size_t bufferStackMax; /**< capacity of stack. */
  BufferState** bufferStack; /**< Stack as an array. */
  void EnsureBufferStack();

  // The following are not always needed, but may be depending
  // on use of certain flex features (like REJECT or yymore()).

  StateType lastAcceptingState;
  char* lastAcceptingPosition;

  StateType* stateBuffer;
  StateType* statePointer;

  char* fullMatch;
  int* fullState;
  int fullMatchPosition;

  int matchPosition;
  int lookingForTrailBegin;

  int moreFlag;
  int moreLength;
  int moreOffset;
  int previousMoreOffset;
};

