// Node structure for Binary Search Tree and AVL Tree
class TreeNode {
public:
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;
    int height;  // Used for AVL Tree balancing

    TreeNode(int val) : value(val), leftChild(nullptr), rightChild(nullptr), height(1) {}
};

// Binary Search Tree implementation
class BinarySearchTree {
private:
    TreeNode* rootNode;

    TreeNode* insertNode(TreeNode* currentNode, int val) {
        if (!currentNode) {
            return new TreeNode(val);
        }
        if (val < currentNode->value) {
            currentNode->leftChild = insertNode(currentNode->leftChild, val);
        } else if (val > currentNode->value) {
            currentNode->rightChild = insertNode(currentNode->rightChild, val);
        }
        return currentNode;
    }

    TreeNode* findMinimum(TreeNode* currentNode) {
        while (currentNode && currentNode->leftChild) {
            currentNode = currentNode->leftChild;
        }
        return currentNode;
    }

    TreeNode* deleteNode(TreeNode* currentNode, int val) {
        if (!currentNode) {
            return currentNode;
        }
        if (val < currentNode->value) {
            currentNode->leftChild = deleteNode(currentNode->leftChild, val);
        } else if (val > currentNode->value) {
            currentNode->rightChild = deleteNode(currentNode->rightChild, val);
        } else {
            if (!currentNode->leftChild) {
                TreeNode *temp = currentNode->rightChild;
                delete currentNode;
                return temp;
            } else if (!currentNode->rightChild) {
                TreeNode *temp = currentNode->leftChild;
                delete currentNode;
                return temp;
            }
            TreeNode *temp = findMinimum(currentNode->rightChild);
            currentNode->value = temp->value;
            currentNode->rightChild = deleteNode(currentNode->rightChild, temp->value);
        }
        return currentNode;
    }

    void inorderTraversal(TreeNode* currentNode) {
        if (currentNode) {
            inorderTraversal(currentNode->leftChild);
            std::cout << currentNode->value << ' ';
            inorderTraversal(currentNode->rightChild);
        }
    }

    void clearTree(TreeNode* currentNode) {
        if (currentNode) {
            clearTree(currentNode->leftChild);
            clearTree(currentNode->rightChild);
            delete currentNode;
        }
    }

public:
    BinarySearchTree() : rootNode(nullptr) {}

    ~BinarySearchTree() {
        clearTree(rootNode);
    }

    void insert(int val) {
        rootNode = insertNode(rootNode, val);
    }

    void remove(int val) {
        rootNode = deleteNode(rootNode, val);
    }

    bool search(int val) {
        TreeNode *currentNode = rootNode;
        while (currentNode) {
            if (currentNode->value == val) {
                return true;
            } else if (val < currentNode->value) {
                currentNode = currentNode->leftChild;
            } else {
                currentNode = currentNode->rightChild;
            }
        }
        return false;
    }

    void inorder() {
        inorderTraversal(rootNode);
        std::cout << '\n';
    }
};

// AVL Tree implementation
class AVLTree {
private:
    TreeNode* rootNode;

    int getNodeHeight(TreeNode* currentNode) {
        return currentNode ? currentNode->height : 0;
    }

    int calculateBalance(TreeNode* currentNode) {
        return currentNode ? getNodeHeight(currentNode->leftChild) - getNodeHeight(currentNode->rightChild) : 0;
    }

    TreeNode* rightRotate(TreeNode* y) {
        TreeNode *x = y->leftChild;
        y->leftChild = x->rightChild;
        x->rightChild = y;
        y->height = 1 + std::max(getNodeHeight(y->leftChild), getNodeHeight(y->rightChild));
        x->height = 1 + std::max(getNodeHeight(x->leftChild), getNodeHeight(x->rightChild));
        return x;
    }

    TreeNode* leftRotate(TreeNode* x) {
        TreeNode *y = x->rightChild;
        x->rightChild = y->leftChild;
        y->leftChild = x;
        x->height = 1 + std::max(getNodeHeight(x->leftChild), getNodeHeight(x->rightChild));
        y->height = 1 + std::max(getNodeHeight(y->leftChild), getNodeHeight(y->rightChild));
        return y;
    }

    TreeNode* insertNode(TreeNode* currentNode, int val) {
        if (!currentNode) {
            return new TreeNode(val);
        }
        if (val < currentNode->value) {
            currentNode->leftChild = insertNode(currentNode->leftChild, val);
        } else {
            currentNode->rightChild = insertNode(currentNode->rightChild, val);
        }
        currentNode->height = 1 + std::max(getNodeHeight(currentNode->leftChild), getNodeHeight(currentNode->rightChild));

        int balance = calculateBalance(currentNode);

        if (balance > 1) {
            if (val < currentNode->leftChild->value) {
                return rightRotate(currentNode);
            }
            currentNode->leftChild = leftRotate(currentNode->leftChild);
            return rightRotate(currentNode);
        } else if (balance < -1) {
            if (val > currentNode->rightChild->value) {
                return leftRotate(currentNode);
            }
            currentNode->rightChild = rightRotate(currentNode->rightChild);
            return leftRotate(currentNode);
        }
        return currentNode;
    }

    void inorderTraversal(TreeNode* currentNode) {
        if (currentNode) {
            inorderTraversal(currentNode->leftChild);
            std::cout << currentNode->value << ' ';
            inorderTraversal(currentNode->rightChild);
        }
    }

    void clearTree(TreeNode* currentNode) {
        if (currentNode) {
            clearTree(currentNode->leftChild);
            clearTree(currentNode->rightChild);
            delete currentNode;
        }
    }

public:
    AVLTree() : rootNode(nullptr) {}

    ~AVLTree() {
        clearTree(rootNode);
    }

    void insert(int val) {
        rootNode = insertNode(rootNode, val);
    }

    void inorder() {
        inorderTraversal(rootNode);
        std::cout << '\n';
    }

    bool isBalanced() {
        int balance = calculateBalance(rootNode);
        return abs(balance) <= 1;
    }
};

// Testing function - DO NOT MODIFY
void testTrees() {
    std::cout << "Testing Binary Search Tree:\n";
    BinarySearchTree bst;

    bst.insert(50);
    bst.insert(30);
    bst.insert(70);
    bst.insert(20);
    bst.insert(40);

    std::cout << "Inorder traversal: ";
    bst.inorder();

    std::cout << "Search 30: " << (bst.search(30) ? "Found" : "Not found") << std::endl;
    std::cout << "Search 90: " << (bst.search(90) ? "Found" : "Not found") << std::endl;

    bst.remove(30);
    std::cout << "After removing 30, inorder traversal: ";
    bst.inorder();

    std::cout << "\nTesting AVL Tree:\n";
    AVLTree avl;

    avl.insert(10);
    avl.insert(20);
    avl.insert(30);
    avl.insert(40);
    avl.insert(50);

    std::cout << "Inorder traversal: ";
    avl.inorder();

    std::cout << "Is tree balanced? " << (avl.isBalanced() ? "Yes" : "No") << std::endl;
}

int main() {
    testTrees();
    return 0;
}

