// Abstract base class representing consumable items
class Consumable
{
protected:
    bool unopened;

public:
    virtual void readLabel() const = 0; // Display item label information
    virtual void consume(int amount) = 0; // Consume a specified amount
    virtual int quantity() const = 0; // Get the current quantity
};

// Class representing edible items
class Eatable : public Consumable
{
private:
    int weight; // Weight of the item
    int pieces; // Number of pieces available

public:
    Eatable(int itemWeight, int itemPieces) : weight(itemWeight), pieces(itemPieces) {}

    void consume(int amount) override
    {
        pieces -= amount; // Decrease the number of pieces by the consumed amount
    }

    int quantity() const override
    {
        return pieces; // Return the number of remaining pieces
    }

    void readLabel() override
    {
        cout << "Weight per piece: " << weight << endl;
        cout << "Pieces: " << pieces << endl; // Display weight and pieces
    }
};

// Class representing drinkable items
class Drinkable : public Consumable
{
private:
    int volume; // Volume of the drink

public:
    Drinkable(int itemVolume) : volume(itemVolume) {}

    void consume(int amount) override
    {
        if (amount <= volume)
            volume -= amount; // Decrease volume if sufficient
    }

    int quantity() const override
    {
        return volume; // Return the remaining volume
    }

    void readLabel() override
    {
        cout << "Volume: " << volume << endl; // Display volume
    }
};

