// Abstract base class representing a mathematical formula
class Formula
{
public:
    virtual double value() const = 0; // Calculate the value of the formula
    virtual void print() const = 0;    // Print the formula
    virtual void clear() = 0;           // Clear resources used by the formula
};

// Class representing a constant value in a formula
class Constant : public Formula
{
    int value;

public:
    Constant(int value)
    {
        this->value = value;
    }

    double value() const override
    {
        return static_cast<double>(value);
    }

    void print() const override
    {
        cout << value;
    }

    void clear() override
    {
        // No resources to clear for a constant
    }
};

// Class representing a binary operation between two formulas
class BinaryOperation : public Formula
{
    Formula* leftOperand;
    Formula* rightOperand;
    char operation;

    void clear() override
    {
        leftOperand->clear();
        rightOperand->clear();
        delete leftOperand;
        delete rightOperand;
    }

public:
    BinaryOperation(Formula* left, Formula* right, char op)
    {
        leftOperand = left;
        rightOperand = right;
        operation = op;
    }

    double value() const override
    {
        switch (operation)
        {
        case '+': return leftOperand->value() + rightOperand->value();
        case '-': return leftOperand->value() - rightOperand->value();
        case '*': return leftOperand->value() * rightOperand->value();
        case '/': return leftOperand->value() / rightOperand->value();
        }
        return 0; // Default case, should not occur
    }

    void print() const override
    {
        cout << "(";
        leftOperand->print();
        cout << " " << operation << " ";
        rightOperand->print();
        cout << ")";
    }
};

// Function to parse a mathematical expression and construct the corresponding formula
Formula* parseFormula(char* expression, int length, int& index)
{
    if (index >= length)
        return nullptr;

    if (isdigit(expression[index]))
    {
        return new Constant(expression[index++] - '0');
    }
    else if (expression[index] == '(')
    {
        index++;
        Formula* left = parseFormula(expression, length, index);
        char op = expression[index++];
        Formula* right = parseFormula(expression, length, index);
        index++; // Skip closing parenthesis
        return new BinaryOperation(left, right, op);
    }

    return nullptr; // Invalid expression
}

int main()
{
    Formula* formula;
    int index = 0;
    char* expression = "(((1+2)*3)*(6+7))";

    formula = parseFormula(expression, strlen(expression), index);
    formula->print();
    cout << endl << formula->value();
    formula->clear();
    delete formula;

    return 0;
}

