// Template class representing a named entity with associated data
template <typename T>
class Named
{
protected:
    T data;
    char* name;

public:
    Named()
    {
        data = T();
        name = nullptr;
    }

    Named(T _data, const char* _name)
    {
        data = _data;
        name = new char[strlen(_name) + 1];
        strcpy(name, _name);
    }

    Named(const Named& other)
    {
        data = other.data;
        name = new char[strlen(other.name) + 1];
        strcpy(name, other.name);
    }

    Named& operator=(const Named& other)
    {
        if (this != &other)
        {
            delete[] name;

            data = other.data;
            name = new char[strlen(other.name) + 1];
            strcpy(name, other.name);
        }
        return *this;
    }

    ~Named()
    {
        delete[] name;
    }

    template <typename U>
    friend ostream& operator<<(ostream&, const Named<U>&);

    template <typename U>
    friend istream& operator>>(istream&, const Named<U>&);
};

// Overloaded output stream operator for Named class
template <typename T>
ostream& operator<<(ostream& os, const Named<T>& namedEntity)
{
    os << "Name: " << namedEntity.name << "\nData: " << namedEntity.data;
    return os;
}

// Overloaded input stream operator for Named class
template <typename T>
istream& operator>>(istream& is, const Named<T>& namedEntity)
{
    is >> namedEntity.name >> namedEntity.data;
    return is;
}

