// Template class representing a variable with a name and associated data
template <typename T>
class Variable : public Named<T>
{
public:
    Variable(T data, const char* name) : Named<T>(data, name) {}

    T operator*() const
    {
        return this->data;
    }

    void operator=(const Variable& other)
    {
        this->data = other.data;
    }

    bool operator==(const Variable& other) const
    {
        return (this->data == other.data && strcmp(this->name, other.name) == 0);
    }

    bool operator!=(const Variable& other) const
    {
        return !(*this == other);
    }
};

