class Shop
{
    Product* products[MAX_SHOP_CAPACITY];
    int currentIndex;

public:
    Shop() : currentIndex(-1) {}

    Shop& operator+=(Product* product)
    {
        if (currentIndex < MAX_SHOP_CAPACITY - 1)
        {
            products[++currentIndex] = product;
        }
        else
        {
            cout << "The shop is full!";
        }
        return *this;
    }

    Shop& operator-=(Product* product)
    {
        if (currentIndex >= 0)
        {
            for (int i = 0; i <= currentIndex; i++)
            {
                if (strcmp(products[i]->getName(), product->getName()) == 0)
                {
                    products[i] = products[currentIndex--];
                    break;
                }
            }
        }
        else
        {
            cout << "The shop is empty!";
        }
        return *this;
    }

    double calculateIncome() const
    {
        double totalIncome = 0;
        for (int i = 0; i <= currentIndex; i++)
        {
            totalIncome += products[i]->getPrice();
        }
        return totalIncome;
    }

    Product* findMinNicotine() const
    {
        double minNicotine = 100;
        Product* minNicotineProduct = nullptr;

        for (int j = 0; j <= currentIndex; j++)
        {
            if (products[j]->isAlcohol() == false)
            {
                double nicotine = static_cast<Tobacco*>(products[j])->getNicotineContent();
                if (nicotine < minNicotine)
                {
                    minNicotine = nicotine;
                    minNicotineProduct = products[j];
                }
            }
        }
        return minNicotineProduct;
    }

    Product* findMaxAlcohol() const
    {
        double maxAlcohol = 0;
        Product* maxAlcoholProduct = nullptr;

        for (int j = 0; j <= currentIndex; j++)
        {
            if (products[j]->isAlcohol())
            {
                double alcohol = static_cast<Alcohol*>(products[j])->getAlcoholPercentage();
                if (alcohol > maxAlcohol)
                {
                    maxAlcohol = alcohol;
                    maxAlcoholProduct = products[j];
                }
            }
        }
        return maxAlcoholProduct;
    }
};

template <typename KeyType, typename ValueType>
class Pair
{
protected:
    KeyType key;
    ValueType value;

public:
    Pair(KeyType _key = KeyType(), ValueType _value = ValueType())
        : key(_key), value(_value) {}

    bool operator==(const Pair& other) const
    {
        return key == other.key && value == other.value;
    }

    ValueType getValue(KeyType searchKey) const
    {
        return (key == searchKey) ? value : ValueType();
    }
};

template <typename KeyType, typename ValueType>
class Dictionary
{
    Pair<KeyType, ValueType> pairs[MAX_DICT_CAPACITY];
    int currentSize;

public:
    Dictionary() : currentSize(-1) {}

    void add(const Pair<KeyType, ValueType>& pair)
    {
        if (currentSize < MAX_DICT_CAPACITY - 1)
        {
            pairs[++currentSize] = pair;
        }
        else
        {
            cout << "Dictionary is full!";
        }
    }

    void remove(const Pair<KeyType, ValueType>& pair)
    {
        for (int i = 0; i <= currentSize; i++)
        {
            if (pairs[i] == pair)
            {
                pairs[i] = pairs[currentSize--];
                break;
            }
        }
    }

    ValueType find(KeyType searchKey) const
    {
        for (int i = 0; i <= currentSize; i++)
        {
            ValueType value = pairs[i].getValue(searchKey);
            if (value != ValueType())
            {
                return value;
            }
        }
        return ValueType();
    }
};

void testDictionary()
{
    Pair<int, string> firstPair(1, "First");
    Pair<int, string> secondPair(2, "Second");
    Pair<int, string> thirdPair(3, "Third");

    Dictionary<int, string> dictionary;
    dictionary.add(firstPair);
    dictionary.add(secondPair);
    dictionary.add(thirdPair);

    cout << dictionary.find(3);

    dictionary.remove(thirdPair);

    cout << dictionary.find(3);
}

int main()
{
    testDictionary();
    return 0;
}

