    }
};

class Inventory
{
    Rune* runes;
    int currentIndex; 
    int capacity; 

    // Initializes the inventory by copying data from another inventory instance
    void copy(const Inventory& other)
    {
        currentIndex = other.currentIndex;
        capacity = other.capacity;

        runes = new Rune[capacity];
        for (int i = 0; i <= currentIndex; i++)
            runes[i] = other.runes[i];
    }

    // Deallocates memory used for the runes array
    void remove()
    {
        delete[] runes;
    }

    // Doubles the capacity of the runes array to accommodate more runes
    void resize()
    {
        capacity *= 2;
        Rune* newRunes = new Rune[capacity];
        for (int i = 0; i <= currentIndex; i++)
        {
            newRunes[i] = runes[i];
        }
        delete[] runes;
        runes = newRunes;
    }

public:
    // Constructs an empty inventory with initial capacity
    Inventory()
    {
        currentIndex = -1;
        capacity = 10;
        runes = new Rune[capacity];
    }

    // Adds a new rune to the inventory, resizing if necessary
    void add(const Rune& rune)
    {
        if (currentIndex == capacity - 1)
        {
            resize();
        }

        currentIndex++;
        runes[currentIndex] = rune;
    }

    // Copy constructor for deep copying another inventory instance
    Inventory(const Inventory& other)
    {
        copy(other);
    }

    // Assignment operator for deep copying another inventory instance
    Inventory& operator=(const Inventory& other)
    {
        if (this != &other)
        {
            remove();
            copy(other);
        }

        return *this;
    }

    // Destructor to clean up resources
    ~Inventory()
    {
        remove();
    }
};

