class BullsAndCows
{
private:
    int* numberSequence;
    int sequenceSize;
    int guessCount;

public:
    BullsAndCows()
    {
        sequenceSize = 4;
        numberSequence = new int[sequenceSize];
        for (int i = 1; i <= sequenceSize; ++i) {
            numberSequence[i - 1] = i;
        }
        guessCount = 0;
    }

    BullsAndCows(int size)
    {
        if (size == 2 || size == 3 || size == 4) {
            sequenceSize = size;
            numberSequence = new int[sequenceSize];
            guessCount = 0;
        } else {
            cout << "Invalid value!" << endl;
            sequenceSize = 4;
            numberSequence = new int[sequenceSize];
            for (int i = 1; i <= sequenceSize; ++i) {
                numberSequence[i - 1] = i;
            }
            guessCount = 0;
        }
    }

    BullsAndCows(int numbers[], int size)
    {
        bool isValid = true;
        if (size == 2 || size == 3 || size == 4) {
            numberSequence = new int[size];
            for (int i = 0; i < size; i++) {
                numberSequence[i] = numbers[i];
                for (int j = i + 1; j < size; ++j) {
                    if (numbers[i] == numbers[j]) {
                        isValid = false;
                    }
                }
            }
            sequenceSize = size;
            guessCount = 0;
            if (!isValid) {
                for (int i = 1; i <= size; ++i) {
                    numberSequence[i - 1] = i;
                }
            }
        } else {
            sequenceSize = 4;
            numberSequence = new int[sequenceSize];
            for (int i = 1; i <= sequenceSize; ++i) {
                numberSequence[i - 1] = i;
            }
            guessCount = 0;
        }
    }

    void SetContainerSize(int newSize)
    {
        if (sequenceSize >= newSize) {
            sequenceSize = newSize;
        } else {
            int* temp = new int[sequenceSize];
            for (int i = 0; i < sequenceSize; ++i) {
                temp[i] = numberSequence[i];
            }
            delete[] numberSequence;
            numberSequence = new int[newSize];
            for (int i = 0; i < sequenceSize; ++i) {
                numberSequence[i] = temp[i];
            }
            for (int i = sequenceSize; i < newSize; ++i) {
                srand(static_cast<unsigned int>(time(NULL)));
                bool isUnique = false;
                int currentSize = sequenceSize;
                while (!isUnique) {
                    isUnique = true;
                    int randomValue = rand() % 10;
                    for (int j = 0; j < currentSize; ++j) {
                        if (randomValue == numberSequence[j]) {
                            isUnique = false;
                        }
                    }
                }
                numberSequence[currentSize++] = randomValue;
            }
            sequenceSize = newSize;
            delete[] temp;
        }
    }

    void SetContainer(int* container)
    {
        bool isValid = true;
        for (int i = 0; i < sequenceSize; i++) {
            for (int j = i + 1; j < sequenceSize; ++j) {
                if (container[i] == container[j]) {
                    isValid = false;
                }
            }
        }
        delete[] numberSequence;
        if (container[0] == 0) {
            cout << "The first number can't be 0!" << endl;
        } else if (!isValid) {
            cout << "Invalid input!" << endl;
        } else {
            numberSequence = new int[sequenceSize];
            for (int i = 0; i < sequenceSize; i++) {
                numberSequence[i] = container[i];
            }
        }
    }

    bool IsInsideContainer(int number) const
    {
        for (int i = 0; i < sequenceSize; i++) {
            if (number == numberSequence[i]) {
                return true;
            }
        }
        return false;
    }

    bool IsCow(int* guessArray, int position, int value) const
    {
        for (int i = sequenceSize - 1; i >= 0; i--) {
            if (i != position && guessArray[i] == value) {
                return true;
            }
        }
        return false;
    }

    bool IsBull(int* guessArray, int position, int value) const
    {
        return guessArray[position] == value;
    }

    const char* TryToGuess(int userGuess)
    {
        int cows = 0, bulls = 0;
        for (int i = sequenceSize - 1; i >= 0; i--) {
            int currentGuess = userGuess % 10;
            if (IsCow(numberSequence, i, currentGuess)) {
                cows++;
            }
            if (IsBull(numberSequence, i, currentGuess)) {
                bulls++;
            }
            userGuess /= 10;
        }
        guessCount++;
        if (bulls == sequenceSize) {
            return "Congratulations! You made the right guess!";
        } else {
            cout << "Cows: " << cows << "    Bulls: " << bulls << endl;
            return nullptr;
        }
    }

    void Start()
    {
        cout << "                COWS AND BULLS" << endl;
        cout << "The sequence contains " << sequenceSize << " numbers." << endl;
        int guess;
        cout << "Make your guess: ";
        cin >> guess;
        const char* result = TryToGuess(guess);
        while (result == nullptr) {
            cout << "Make your guess: ";
            cin >> guess;
            result = TryToGuess(guess);
        }
        cout << result << endl;
        cout << "You made " << guessCount << " guesses!" << endl;
    }

    ~BullsAndCows()
    {
        delete[] numberSequence;
    }
};

int main()
{
    int initialNumbers[4] = {6, 7, 8, 4};
    BullsAndCows game(initialNumbers, 4);
    game.Start();
    return 0;
}

#include <iostream>
using namespace std;

class Fraction {
private:
    int numerator, denominator;

    // Computes the greatest common divisor (GCD) of two integers
    int computeGCD(int a, int b) {
        if (a <= 0 || b <= 0) {
            return 1;
        }
        while (a != b) {
            if (a > b) {
                a -= b;
            } else {
                b -= a;
            }
        }
        return a;
    }

public:
    // Default constructor initializes fraction to 1/1
    Fraction() : numerator(1), denominator(1) {}

    // Parameterized constructor with validation
    Fraction(int n, int d) {
        numerator = n;
        denominator = d;
        if (denominator == 0) {
            cout << "ERROR! Denominator cannot be zero." << endl;
            denominator = 1;
        }
        if (numerator != 0) {
            int gcd = computeGCD(numerator, denominator);
            numerator /= gcd;
            denominator /= gcd;
        } else {
            denominator = 1;
        }
    }

    // Copy constructor
    Fraction(const Fraction& other) {
        numerator = other.numerator;
        denominator = other.denominator;
    }

    int getNumerator() const { return numerator; }

    int getDenominator() const { return denominator; }

    // Prints the fraction in the format "numerator/denominator"
    void display() const {
        cout << getNumerator() << '/' << getDenominator() << endl;
    }

    // Assignment operator overload
    const Fraction& operator=(const Fraction& other) {
        if (this != &other) {
            numerator = other.numerator;
            denominator = other.denominator;
        }
        return *this;
    }

    // Addition operator overload
    Fraction operator+(const Fraction& other) {
        return Fraction(getNumerator() * other.getDenominator() + 
                        getDenominator() * other.getNumerator(),
                        getDenominator() * other.getDenominator());
    }

    // Subtraction operator overload
    Fraction operator-(const Fraction& other) {
        return Fraction(getNumerator() * other.getDenominator() - 
                        getDenominator() * other.getNumerator(),
                        getDenominator() * other.getDenominator());
    }

    // Multiplication operator overload
    Fraction operator*(const Fraction& other) {
        return Fraction(getNumerator() * other.getNumerator(),
                        getDenominator() * other.getDenominator());
    }

    // Division operator overload
    Fraction operator/(const Fraction& other) {
        return Fraction(getNumerator() * other.getDenominator(),
                        getDenominator() * other.getNumerator());
    }

    // Conversion operator to double
    operator double() const {
        return static_cast<double>(numerator) / static_cast<double>(denominator);
    }

    // Input stream operator overload for reading fractions
    friend istream& operator>>(istream& in, Fraction& fraction) {
        in >> fraction.numerator;
        in >> fraction.denominator;
        return in;
    }

    // Output stream operator overload for printing fractions
    friend ostream& operator<<(ostream& out, const Fraction& fraction) {
        out << fraction.numerator << "/" << fraction.denominator << endl;
        return out;
    }
};

