    Fraction result;
    cin >> result;
    cout << result;

    Fraction a(1, 2), b(1, 3);
    result = a + b;
    result.display();

    result = a - b;
    result.display();

    result = a * b;
    result.display();

    result = a / b;
    result.display();
}

class Buff
{
    int capacity;
    int remaining;

public:
    // Initializes a buff with default capacity and remaining count
    Buff() : capacity(5), remaining(0) {}

    // Initializes a buff with specified capacity and remaining count
    Buff(int initialCapacity, int initialRemaining) : capacity(initialCapacity), remaining(initialRemaining) {}

    // Copy constructor for buff
    Buff(const Buff& other) : capacity(other.capacity), remaining(other.remaining) {}

    // Set the maximum capacity of the buff
    void setCapacity(int newCapacity) {
        capacity = newCapacity;
    }

    // Set the current remaining buffs
    void setRemaining(int newRemaining) {
        remaining = newRemaining;
    }

    // Get the maximum capacity of the buff
    int getCapacity() const {
        return capacity;
    }

    // Get the current remaining buffs
    int getRemaining() const {
        return remaining;
    }

    // Increase the maximum capacity of the buff by a specified amount
    void increaseCapacity(int additionalCapacity) {
        capacity += additionalCapacity;
    }

    // Gain a buff if there is capacity available
    void gainBuff() {
        if (remaining < capacity) {
            remaining++;
        }
    }

    // Use a buff if any are available
    void useBuff() {
        if (remaining > 0) {
            remaining--;
        }
    }

    // Output the current state of the buff
    friend std::ostream& operator<<(std::ostream& os, const Buff& buff) {
        os << "Remaining " << buff.remaining << " buffs of " << buff.capacity << " possible" << std::endl;
        return os;
    }
};

