class Rational {

private:
    int numerator, denominator; // Represents a rational number as a fraction

    // Computes the greatest common divisor (GCD) of two integers
    int gcd(int x, int y) {
        if (x <= 0 || y <= 0) {
            return 1; // GCD is defined as 1 for non-positive inputs
        }
        while (x != y) {
            if (x > y) {
                x -= y;
            } else {
                y -= x;
            }
        }
        return x; // Returns the GCD
    }

public:
    // Default constructor initializes the fraction to 1/1
    Rational() : numerator(1), denominator(1) {}

    // Parameterized constructor initializes the fraction with given values
    Rational(int n, int d) {
        numerator = n;
        denominator = d;
        if (denominator == 0) { // Denominator cannot be zero
            cout << "ERROR!";
            denominator = 1; // Default to 1 to avoid division by zero
        }
        if (numerator != 0) {
            int g = gcd(numerator, denominator);
            numerator /= g; // Simplify the fraction
            denominator /= g;
        } else { // If the numerator is zero, represent the fraction as 0/1
            denominator = 1;
        }
    }

    // Copy constructor
    Rational(const Rational& other) : numerator(other.numerator), denominator(other.denominator) {}

    // Accessor for the numerator
    int getNumerator() const { return numerator; }

    // Accessor for the denominator
    int getDenominator() const { return denominator; }

    // Prints the fraction in the format "numerator/denominator"
    void print() const {
        cout << getNumerator() << '/' << getDenominator() << endl;
    }

    // Assignment operator
    const Rational& operator=(const Rational& other) {
        if (this != &other) {
            numerator = other.numerator;
            denominator = other.denominator;
        }
        return *this;
    }

    // Addition operator
    Rational operator+(const Rational& other) {
        return Rational(getNumerator() * other.getDenominator() + getDenominator() * other.getNumerator(),
                        getDenominator() * other.getDenominator());
    }

    // Subtraction operator
    Rational operator-(const Rational& other) {
        return Rational(getNumerator() * other.getDenominator() - getDenominator() * other.getNumerator(),
                        getDenominator() * other.getDenominator());
    }

    // Multiplication operator
    Rational operator*(const Rational& other) {
        return Rational(getNumerator() * other.getNumerator(),
                        getDenominator() * other.getDenominator());
    }

    // Division operator
    Rational operator/(const Rational& other) {
        return Rational(getNumerator() * other.getDenominator(),
                        getDenominator() * other.getNumerator());
    }

    // Conversion operator to double
    operator double() const {
        return static_cast<double>(numerator) / static_cast<double>(denominator);
    }

    // Input stream operator
    friend istream& operator>>(istream& in, Rational& rational) {
        in >> rational.numerator >> rational.denominator;
        return in;
    }

    // Output stream operator
    friend ostream& operator<<(ostream& out, const Rational& rational) {
        out << rational.numerator << "/" << rational.denominator << endl;
        return out;
    }

    // Equality operator
    bool operator==(const Rational& other) const {
        return (numerator == other.numerator && denominator == other.denominator);
    }

    // Greater than operator
    bool operator>(const Rational& other) const {
        return (numerator * other.denominator > other.numerator * denominator);
    }

    // Greater than or equal to operator
    bool operator>=(const Rational& other) const {
        return (numerator * other.denominator >= other.numerator * denominator);
    }

    // Less than operator
    bool operator<(const Rational& other) const {
        return (other > *this);
    }

    // Less than or equal to operator
    bool operator<=(const Rational& other) const {
        return (other >= *this);
    }

    // Compound addition assignment operator
    const Rational& operator+=(const Rational& other) {
        *this = *this + other;
        return *this;
    }

    // Compound subtraction assignment operator
    const Rational& operator-=(const Rational& other) {
        *this = *this - other;
        return *this;
    }

    // Compound multiplication assignment operator
    const Rational& operator*=(const Rational& other) {
        *this = *this * other;
        return *this;
    }

    // Compound division assignment operator
    const Rational& operator/=(const Rational& other) {
        *this = *this / other;
        return *this;
    }
};

