class Inventory
{
    Rune* runes;
    int current; // Current number of runes in the inventory
    int capacity; // Maximum capacity of the runes array

    // Helper function to copy data from another Inventory
    void copy(const Inventory& other)
    {
        current = other.current;
        capacity = other.capacity;
        runes = new Rune[capacity];
        for (int i = 0; i <= current; i++)
            runes[i] = other.runes[i];
    }

    // Helper function to release allocated memory for runes
    void remove()
    {
        delete[] runes;
    }

    // Resize the runes array to double its current capacity
    void resize()
    {
        capacity *= 2;
        Rune* newRunes = new Rune[capacity];
        for (int i = 0; i <= current; i++)
        {
            newRunes[i] = runes[i];
        }
        delete[] runes;
        runes = newRunes;
    }

public:
    // Default constructor initializes the inventory with a default capacity
    Inventory()
        : current(-1), capacity(10)
    {
        runes = new Rune[capacity];
    }

    // Function to add a new Rune to the inventory
    void add(const Rune& rune)
    {
        if (current == capacity - 1)
        {
            resize(); // Resize if the inventory is full
        }
        current++;
        runes[current] = rune;
    }

    // Copy constructor for creating a new Inventory from an existing one
    Inventory(const Inventory& other)
    {
        copy(other);
    }

    // Assignment operator for copying attributes from another Inventory
    Inventory& operator=(const Inventory& other)
    {
        if (this != &other)
        {
            remove(); // Release current resources
            copy(other); // Copy new data
        }
        return *this;
    }

    // Destructor to release allocated memory
    ~Inventory()
    {
        remove();
    }

    // Output stream operator for displaying all Runes in the inventory
    friend std::ostream& operator<<(std::ostream& os, const Inventory& inv)
    {
        for (int i = 0; i <= inv.current; i++)
            os << inv.runes[i];
        return os;
    }
};

