#include <iostream>
#include <string>
using namespace std;

#define QUEUE_SIZE 10

// Class representing a queue of strings
class StringQueue {
public:
    int inputIndex, outputIndex; // Indices for input and output operations
    string elements[QUEUE_SIZE];

    StringQueue() {
        inputIndex = -1;
        outputIndex = -1;
        for (int i = 0; i < QUEUE_SIZE; i++)
            elements[i] = "";
    }

    // Prints the elements in the queue
    void Print() {
        if (!IsEmpty()) {
            int currentIndex = outputIndex;
            while (currentIndex != inputIndex) {
                if (currentIndex == QUEUE_SIZE - 1) {
                    cout << endl << elements[currentIndex];
                    currentIndex = 0;
                } else {
                    cout << endl << elements[currentIndex++];
                }
            }
            cout << endl << elements[currentIndex++];
        } else {
            cout << " empty";
        }
    }

    // Checks if the queue is empty
    bool IsEmpty() {
        return outputIndex == -1;
    }

    // Checks if the queue is full
    bool IsFull() {
        return ((inputIndex + 1) % QUEUE_SIZE == outputIndex);
    }

    // Clears the queue
    void Clear() {
        inputIndex = outputIndex = -1;
    }

    // Adds an element to the queue
    void Enqueue(string element) {
        if (!IsFull()) {
            if (inputIndex == -1 || inputIndex == QUEUE_SIZE - 1) {
                elements[0] = element;
                inputIndex = 0;
                if (outputIndex == -1)
                    outputIndex = 0;
            } else {
                inputIndex = (inputIndex + 1);
                elements[inputIndex] = element;
            }
        } else {
            cout << " Queue is Full";
        }
    }

    // Removes and returns an element from the queue
    string Dequeue() {
        if (!IsEmpty()) {
            string element = elements[outputIndex];
            if (inputIndex == outputIndex) {
                inputIndex = -1;
                outputIndex = -1;
            } else if (outputIndex == QUEUE_SIZE - 1) {
                outputIndex = 0;
            } else {
                outputIndex++;
            }
            return element;
        } else {
            return "";
        }
    }
};

// Class representing a book
class Book {
public:
    int id, copyCount;
    float price;
    string title, genre;
    StringQueue demandQueue;
    string authorNames[10];
    unsigned int authorCount;

    Book() {
        authorCount = 10;
        id = 0;
        title = "";
        for (int i = 0; i < authorCount; i++) {
            authorNames[i] = "";
        }
        genre = "";
        copyCount = 0;
        price = 0;
    }

    // Collects book details from user input
    void CollectDetails() {
        cin.ignore(1);
        cout << "\nEnter Book Name: ";
        getline(cin, title);
        cout << endl;

    retryAuthors:
        cout << "Enter total number of authors: ";
        cin >> authorCount;
        if (authorCount > 10) {
            cout << "\nAuthors cannot be more than 10\nRe-enter: ";
            goto retryAuthors;
        }
        cin.ignore(1);
        for (int i = 0; i < authorCount; i++) {
            cout << "\nEnter Author " << i + 1 << " Name: ";
            getline(cin, authorNames[i]);
        }
        cout << "\nEnter Book Genre: ";
        getline(cin, genre);
        cout << "\nEnter Number of Copies: ";
        cin >> copyCount;
        cout << "\nEnter Price: ";
        cin >> price;
    }

    // Displays book details
    void Display() {
        int idSpacing = (id < 10) ? 8 : (id < 100) ? 7 : (id < 1000) ? 6 : 5;
        int titleSpacing = 24 - title.length();
        int authorSpacing = 16 - authorNames[0].length();
        int genreSpacing = 11 - genre.length();
        int copySpacing = (copyCount < 10) ? 14 : (copyCount < 100) ? 13 : (copyCount < 1000) ? 12 : 10;

        cout << "\n-----------------------------------------------------------------------------";
        cout << "\n" << id;
        PrintSpaces(idSpacing);
        cout << title;
        PrintSpaces(titleSpacing);
        cout << authorNames[0];
        PrintSpaces(authorSpacing);
        cout << genre;
        PrintSpaces(genreSpacing);
        cout << copyCount;
        PrintSpaces(copySpacing);
        cout << price;

        for (int i = 1; i < authorCount; i++) {
            cout << endl;
            PrintSpaces(32);
            cout << authorNames[i];
        }
    }

private:
    // Prints spaces for formatting
    void PrintSpaces(int count) {
        for (int i = 0; i < count; i++)
            cout << " ";
    }
};

