    BookNode* leftChild;
    BookNode* rightChild;

    BookNode() {
        id = 0;
        authorCount = 10;
        title = "";
        for (int i = 0; i < authorCount; i++)
            authorNames[i] = "";
        genre = "";
        copyCount = 0;
