class BookShop {
private:
    BookNode* root;
    bool isCounterSet; // Tracks if the counter has been initialized
    int counter;       // Counter for assigning unique IDs
    bool isLoaded;     // Indicates if the data has been loaded from file

    // Helper functions for managing the book nodes
    void initializeCounter();
    void assignID(BookNode* bookNode);
    bool isEmpty() const;
    void linkBook(BookNode* bookNode);
    bool isDuplicate(BookNode* bookNode) const;
    void displayBooks(BookNode* bookNode) const;
    void promptForLoading();

    // Search and display functions
    void searchAndDisplayById();
    void searchAndDisplayByName();
    void searchAndDisplayByType();
    void searchAndDisplayByAuthor();

    void clear(BookNode* bookNode);
    void deleteNodeWithNoChild(BookNode* bookNode);
    void deleteNodeWithOneChild(BookNode* bookNode);
    BookNode* searchById(BookNode* bookNode, int id) const;
    BookNode* searchByName(BookNode* bookNode, const string& name) const;
    BookNode* searchParent(BookNode* parent, BookNode* child) const;

public:
    BookShop();
    void deleteBook(const string& bookName);
    void printQueue();
    void search();
    void save();
    ~BookShop();
    void display() const;
    void load();
    void insert();
    void buy(int bookId);
    void read();
    void increaseCopy(int bookId, int copyCount);
    void changePrice(int bookId, int newPrice);
};

BookShop::BookShop() : root(nullptr), counter(0), isCounterSet(false), isLoaded(false) {}

bool BookShop::isEmpty() const {
    return root == nullptr;
}

void BookShop::assignID(BookNode* bookNode) {
    bookNode->id = ++counter;
}

void BookShop::linkBook(BookNode* bookNode) {
    BookNode* existingNode = searchById(root, bookNode->id);
    if (existingNode != nullptr) {
        delete bookNode; // Duplicate ID, discard the new node
    } else {
        bookNode->left = bookNode->right = nullptr;
        if (isEmpty()) {
            root = bookNode;
        } else {
            BookNode* current = root;
            BookNode* parent = nullptr;
            while (current != nullptr) {
                parent = current;
                if (bookNode->bname < current->bname) {
                    current = current->left;
                } else if (bookNode->bname > current->bname) {
                    current = current->right;
                } else {
                    cout << "\nBook " << bookNode->bname << " already exists in stock.";
                    delete bookNode; // Duplicate book name, discard the new node
                    return;
                }
            }
            if (bookNode->bname < parent->bname) {
                parent->left = bookNode;
            } else {
                parent->right = bookNode;
            }
        }
    }
}

void BookShop::deleteBook(const string& bookName) {
    if (!isEmpty()) {
        BookNode* bookNode = searchByName(root, bookName);
        if (bookNode != nullptr) {
            if (bookNode->left == nullptr && bookNode->right == nullptr) {
                deleteNodeWithNoChild(bookNode);
            } else if ((bookNode->left == nullptr) ^ (bookNode->right == nullptr)) {
                deleteNodeWithOneChild(bookNode);
            } else {
                BookNode* rightmost = bookNode->left;
                while (rightmost->right != nullptr) {
                    rightmost = rightmost->right;
                }
                rightmost->right = bookNode->right;
                bookNode->right = nullptr;
                deleteNodeWithOneChild(bookNode);
            }
        } else {
            cout << "\nBook not found, cannot be deleted.";
        }
    }
}

void BookShop::displayBooks(BookNode* bookNode) const {
    if (bookNode != nullptr) {
        displayBooks(bookNode->left);
        bookNode->show();
        displayBooks(bookNode->right);
    }
}

void BookShop::display() const {
    if (!isEmpty()) {
        cout << "\nID\tName\t\t\tAuthors\t\tType\t Copies\t\tPrice";
        displayBooks(root);
    } else {
        cout << "\nBook List is empty.";
    }
}

BookShop::~BookShop() {
    save(); // Save all data before destruction
    clear(root);
}

void BookShop::load() {
    ifstream file("shop.txt", ios::binary);
    if (file.good()) {
        BookNode* bookNode = new BookNode;
        file.read(reinterpret_cast<char*>(bookNode), sizeof(BookNode));
        while (!file.eof()) {
            if (bookNode->id > counter) {
                counter = bookNode->id;
            }
            linkBook(bookNode);
            bookNode = new BookNode();
            file.read(reinterpret_cast<char*>(bookNode), sizeof(BookNode));
        }
        isCounterSet = true;
        file.close();
        cout << (root != nullptr ? "\nLoad Successfully\n" : "\nFile is empty\n");
        isLoaded = true;
    } else {
        file.close();
        cout << "\nFile cannot be loaded. Please insert some data, then save and load.";
    }
}

void BookShop::insert() {
    if (!isCounterSet) {
        initializeCounter(); // Initialize counter if not set
    }
    BookNode* bookNode = new BookNode();
    assignID(bookNode);
    bookNode->get();
    linkBook(bookNode);
}

void BookShop::initializeCounter() {
    ifstream file("shop.txt", ios::binary);
    if (file.good()) {
        BookNode* bookNode = new BookNode;
        file.read(reinterpret_cast<char*>(bookNode), sizeof(BookNode));
        while (!file.eof()) {
            if (bookNode->id > counter) {
                counter = bookNode->id;
            }
            file.read(reinterpret_cast<char*>(bookNode), sizeof(BookNode));
        }
        delete bookNode;
    }
    file.close();
    isCounterSet = true;
}

void BookShop::save() {
    if (!isLoaded) {
        ifstream file("shop.txt", ios::binary);
        if (file.good()) {
            BookNode* bookNode = new BookNode;
            file.read(reinterpret_cast<char*>(bookNode), sizeof(BookNode));
            while (!file.eof()) {
                if (bookNode->id > counter) {
                    counter = bookNode->id;
                }
                linkBook(bookNode);
                bookNode = new BookNode();
                file.read(reinterpret_cast<char*>(bookNode), sizeof(BookNode));
            }
            isCounterSet = true;
            delete bookNode;
        }
        file.close();
    }

    ofstream outputFile("shop.txt", ios::out);
    outputFile.close();

    if (root != nullptr) {
        ofstream binaryFile("shop.txt", ios::binary);
        DynamicQueue<BookNode*> queue;
        queue.Enqueue(root);
        while (!queue.IsEmpty()) {
            BookNode* currentNode = queue.Dequeue();
            if (currentNode->left != nullptr) queue.Enqueue(currentNode->left);
            if (currentNode->right != nullptr) queue.Enqueue(currentNode->right);
            binaryFile.write(reinterpret_cast<char*>(currentNode), sizeof(BookNode));
        }
        cout << "\nSave Successfully\n";
        binaryFile.close();
    }
}

void BookShop::promptForLoading() {
    char choice;
