}

void BookShop::search() {
    char choice;
    promptForLoading();
    cout << "\nEnter choice for method of searching or any other key to go to main menu ";
    cout << "\n1- Search by ID ";
    cout << "\n2- Search by Book Name ";
    cout << "\n3- Search by Author Name ";
    cout << "\n4- Search by Type ";
    choice = getche();
    switch (choice) {
        case '1': searchAndDisplayById(); break;
        case '2': searchAndDisplayByName(); break;
        case '3': searchAndDisplayByAuthor(); break;
        case '4': searchAndDisplayByType(); break;
    }
}

BookNode* BookShop::searchById(BookNode* bookNode, int id) const {
    if (bookNode != nullptr) {
        if (id == bookNode->id) return bookNode;
        BookNode* foundNode = searchById(bookNode->left, id);
        return foundNode != nullptr ? foundNode : searchById(bookNode->right, id);
    }
    return nullptr;
}

void BookShop::searchAndDisplayById() {
    int id;
    cout << "\nEnter ID of book to search: ";
    cin >> id;
    if (!isEmpty()) {
        BookNode* bookNode = searchById(root, id);
        cout << "\nID\tName\t\t\tAuthors\t\tType\t Copies\t\tPrice";
        if (bookNode != nullptr) {
            bookNode->show();
        } else {
            cout << "\n\t\tNo record found.";
        }
    }
}

void BookShop::buy(int bookId) {
    if (root != nullptr) {
        BookNode* bookNode = searchById(root, bookId);
        if (bookNode != nullptr && bookNode->id == bookId) {
            if (bookNode->copy > 0) {
                int quantity = 0;
                cout << "\nEnter number of copies of \"" << bookNode->bname << "\" you want to purchase: ";
                cin >> quantity;
                if (quantity > bookNode->copy) quantity = bookNode->copy;
                cout << "\nTotal bill for " << quantity << " copies is " << (bookNode->price * quantity);
                bookNode->copy -= quantity;
            } else {
                cin.ignore(1);
                cout << "\nBook is out of stock. Enter name of customer to insert in queue: ";
                string customerName;
                getline(cin, customerName);
                cout << "\nUser name entered: " << customerName;
                bookNode->demand.Enqueue(customerName);
            }
        } else {
            cout << "\nBook does not exist.";
        }
    } else {
        cout << "\nBook Shop is empty or file is not loaded.";
    }
}

