void BookShop::read() {
    initializeCounter();
    cout << "\nPress 1 to know input pattern or any key to continue: ";
    char choice = getche();
    if (choice == '1') {
        cout << "\nInput pattern, file name should be read.txt ";
        cout << "\nBook(1):Author1,A2,...A10,:Type:Copies:Price;";
        cout << "\nBook(2):Author1,A2,...A10,:Type:Copies:Price;";
        cout << "\n...\nBook(n):Author1,A2,...A10,:Type:Copies:Price;";
    }
    int bookCount = 0;
    ifstream file("read.txt");
    if (file.good()) {
        char ch;
        while (!file.eof()) {
            BookNode* bookNode = new BookNode;
            ch = file.get();
            while (ch != ';') {
                while (ch != ':') {
                    bookNode->bname += ch;
                    ch = file.get();
                }
                bookNode->authors = 0;
                ch = file.get();
                while (ch != ':') {
                    while (ch != ',') {
                        bookNode->aname[bookNode->authors] += ch;
                        ch = file.get();
                    }
                    bookNode->authors++;
                    ch = file.get();
                }
                ch = file.get();
                while (ch != ':') {
                    bookNode->type += ch;
                    ch = file.get();
                }
                int copyCount = 0;
                ch = file.get();
                while (ch != ':') {
                    copyCount = copyCount * 10 + (ch - '0');
                    ch = file.get();
                }
                bookNode->copy = copyCount;

                int price = 0;
                ch = file.get();
                while (ch != ':') {
                    price = price * 10 + (ch - '0');
                    ch = file.get();
                }
                bookNode->price = price;
                ch = file.get();
            }
            if (!isDuplicate(bookNode)) {
                assignID(bookNode);
                linkBook(bookNode);
                bookCount++;
            } else {
                cout << endl << bookNode->bname << " book already exists in the book shop.";
                delete bookNode;
            }
        }
        cout << "\nReading finished. ";
        if (bookCount > 0) {
            cout << bookCount << (bookCount == 1 ? " book" : " books") << " added successfully.";
        } else {
            cout << "No book added.";
        }
    }
    file.close();
}

bool BookShop::isDuplicate(BookNode* newBook) const {
    bool duplicateFlags[3] = { false, false, false };
    if (root != nullptr) {
        BookNode* currentNode = root;
        DynamicQueue<BookNode*> queue;
        queue.Enqueue(currentNode);
        while (!queue.IsEmpty()) {
            currentNode = queue.Dequeue();
            if (currentNode->left != nullptr) queue.Enqueue(currentNode->left);
            if (currentNode->right != nullptr) queue.Enqueue(currentNode->right);
            if (newBook->bname == currentNode->bname) {
                duplicateFlags[0] = true;
            }
            if (newBook->authors == currentNode->authors) {
                for (int i = 0; i < newBook->authors; i++) {
                    if (newBook->aname[i] == currentNode->aname[i]) {
                        duplicateFlags[1] = true;
                    } else {
                        duplicateFlags[1] = false;
                        break;
                    }
                }
            }
            if (newBook->type == currentNode->type) {
                duplicateFlags[2] = true;
            }
            if (duplicateFlags[0] && duplicateFlags[1] && duplicateFlags[2]) {
                return true;
            }
        }
    }
    if (!isLoaded) {
        ifstream file("shop.txt", ios::binary);
        if (file.good()) {
            BookNode* currentNode = new BookNode;
            file.read(reinterpret_cast<char*>(currentNode), sizeof(BookNode));
            while (!file.eof()) {
                for (int i = 0; i < 3; i++) duplicateFlags[i] = false;
                if (newBook->bname == currentNode->bname) {
                    duplicateFlags[0] = true;
                }
                if (newBook->authors == currentNode->authors) {
                    for (int i = 0; i < newBook->authors; i++) {
                        if (newBook->aname[i] == currentNode->aname[i]) {
                            duplicateFlags[1] = true;
                        } else {
                            duplicateFlags[1] = false;
                            break;
                        }
                    }
                }
                if (newBook->type == currentNode->type) {
                    duplicateFlags[2] = true;
                }
                if (duplicateFlags[0] && duplicateFlags[1] && duplicateFlags[2]) {
                    delete currentNode;
                    return true;
                }
                file.read(reinterpret_cast<char*>(currentNode), sizeof(BookNode));
            }
            delete currentNode;
        }
    }
    return false;
}

void BookShop::increaseCopy(int bookId, int copyCount) {
    BookNode* bookNode = searchById(root, bookId);
    if (bookNode != nullptr && bookId == bookNode->id) {
        bookNode->copy += copyCount;
        cout << "\nNow total copies of book " << bookNode->bname << " are " << bookNode->copy;
    } else {
        cout << "\nBook does not exist in stock.";
        if (!isLoaded) {
            cout << " or not loaded from file.";
        }
    }
}

void BookShop::changePrice(int bookId, int newPrice) {
    cin.ignore();
    BookNode* bookNode = searchById(root, bookId);
    if (bookNode != nullptr && bookId == bookNode->id) {
        cout << "\nCurrent price of book " << bookNode->bname << " is " << bookNode->price;
        bookNode->price = newPrice;
        cout << "\nNew price of book " << bookNode->bname << " is " << bookNode->price;
    } else {
        cout << "\nBook does not exist in stock.";
        if (!isLoaded) {
            cout << " or not loaded from file.";
        }
    }
}

void BookShop::deleteNodeWithOneChild(BookNode* bookNode) {
    if (bookNode != nullptr && ((bookNode->left != nullptr && bookNode->right == nullptr) || (bookNode->left == nullptr && bookNode->right != nullptr))) {
        if (bookNode == root) {
            root = (root->left != nullptr) ? root->left : root->right;
            delete bookNode;
        } else {
            BookNode* parent = searchParent(root, bookNode);
            if (parent->left == bookNode && bookNode->left != nullptr) {
                parent->left = bookNode->left;
            } else if (parent->right == bookNode && bookNode->right != nullptr) {
                parent->right = bookNode->right;
            } else if (parent->left == bookNode && bookNode->right != nullptr) {
                parent->left = bookNode->right;
            } else if (parent->right == bookNode && bookNode->left != nullptr) {
                parent->right = bookNode->left;
            }
            delete bookNode;
        }
    }
}

void BookShop::deleteNodeWithNoChild(BookNode* bookNode) {
    if (bookNode->left == nullptr && bookNode->right == nullptr) {
        if (bookNode == root) {
            delete root;
            root = nullptr;
        } else {
            BookNode* parent = searchParent(root, bookNode);
            if (bookNode == parent->left) {
                parent->left = nullptr;
            } else if (bookNode == parent->right) {
                parent->right = nullptr;
            }
            delete bookNode;
        }
    }
}

BookNode* BookShop::searchParent(BookNode* parent, BookNode* child) const {
    if (child == root || parent == nullptr || child == nullptr) return nullptr;
    while (child != parent->left && child != parent->right) {
        if (child->bname < parent->bname) {
            parent = parent->left;
        } else if (child->bname > parent->bname) {
            parent = parent->right;
        }
    }
    return (child == parent->left || child == parent->right) ? parent : nullptr;
}

BookNode* BookShop::searchByName(BookNode* bookNode, const string& name) const {
    while (bookNode != nullptr && name != bookNode->bname) {
        bookNode = (name < bookNode->bname) ? bookNode->left : bookNode->right;
    }
    return bookNode;
}

void BookShop::clear(BookNode* bookNode) {
    if (bookNode != nullptr) {
        clear(bookNode->left);
        clear(bookNode->right);
        delete bookNode;
    }
}

#include <iostream>
using namespace std;

template<class T>
class Node {
public:
    T data; // Node's data
    Node<T>* next; // Pointer to the next node

    Node() : next(nullptr) {} // Default constructor initializes next to nullptr
    Node(T value, Node* nextNode = nullptr) : data(value), next(nextNode) {} // Constructor with parameters
};

template <class T>
class DynamicQueue {
    Node<T>* rear; // Pointer to the last node
    Node<T>* front; // Pointer to the first node

public:
    DynamicQueue() : rear(nullptr), front(nullptr) {} // Constructor initializes pointers to nullptr
    ~DynamicQueue(); // Destructor to clean up the queue

    void Clear(); // Clears the queue
    void Enqueue(T value); // Adds an element to the end of the queue
    T Dequeue(); // Removes and returns the element from the front of the queue
    bool IsEmpty(); // Checks if the queue is empty
};

template <class T>
DynamicQueue<T>::~DynamicQueue() {
    Clear(); // Clear the queue upon destruction
}

template <class T>
void DynamicQueue<T>::Clear() {
    Node<T>* temp = front; // Temporary pointer for traversal
    while (front != nullptr) {
        temp = front; // Store current front
        front = front->next; // Move to the next node
        delete temp; // Delete the current node
    }
    front = rear = nullptr; // Reset pointers to nullptr
}

template <class T>
bool DynamicQueue<T>::IsEmpty() {
    return front == nullptr; // Return true if the queue is empty
}

template <class T>
void DynamicQueue<T>::Enqueue(T value) {
    Node<T>* newNode = new Node<T>(value); // Create a new node
    if (IsEmpty()) {
        front = rear = newNode; // If queue is empty, set both front and rear to the new node
    } else {
        rear->next = newNode; // Link the new node at the end of the queue
        rear = newNode; // Update the rear pointer
    }
}

template<class T>
T DynamicQueue<T>::Dequeue() {
    if (!IsEmpty()) {
        T returnValue = front->data; // Store the data to return
        Node<T>* temp = front; // Temporary pointer for deletion
        front = front->next; // Move front to the next node
        delete temp; // Delete the old front node
        return returnValue; // Return the dequeued value
    } else {
        cout << "\nDynamic Queue is empty, returning zero.";
        return T(); // Return default value of T
    }
}

#include <iostream>
using namespace std;

class Bonus;

class Patmarks {
    int registrationNumber;
    int marks[4];
    int totalMarks = 0;

public:
    // Collects registration number and marks, calculates total marks
    void collectData() {
        cin >> registrationNumber;
        for (int i = 0; i < 4; i++) {
            cin >> marks[i];
            totalMarks += marks[i];
        }
    }

    friend void calculateFinalScore(Patmarks, Bonus);
};

class Bonus {
    int registrationNumber;
    int bonusMarks;

public:
    // Collects registration number and bonus marks
    void collectBonusData() {
        cin >> registrationNumber;
        cin >> bonusMarks;
    }

    friend void calculateFinalScore(Patmarks, Bonus);
};

// Calculates and displays the final score based on total marks and bonus
void calculateFinalScore(Patmarks studentMarks, Bonus studentBonus) {
    cout << studentMarks.registrationNumber << endl;
    int finalScore = studentMarks.totalMarks + studentBonus.bonusMarks;

    if (finalScore > 40) {
        cout << 60 << endl;
    } else {
        cout << (finalScore * 60 / 50) << endl;
    }
}

int main() {
    Patmarks student;
    Bonus bonus;

    student.collectData();
    bonus.collectBonusData();
    calculateFinalScore(student, bonus);

    return 0;
}

#include <iostream>
#include <exception>
#include <string>
using namespace std;

// Template function to count occurrences of a specified value in a collection of elements
template<class T, class S>
int countOccurrences(T *data, int size, S searchValue);

class Book {
    int id;
    string title;
    string author;
    float price;

public:
    void inputDetails();
    // Overload the '==' operator to compare book title with a given string
    bool operator==(const string& otherTitle) const;
};

void Book::inputDetails() {
    cin >> id >> title >> author >> price;
}

bool Book::operator==(const string& otherTitle) const {
    return title.compare(otherTitle) == 0;
}

template<class T, class S>
int countOccurrences(T *data, int size, S searchValue) {
    int occurrenceCount = 0;
    // Iterate through the collection to count matches
    for (int i = 0; i < size; i++) {
        if (data[i] == searchValue) {
            occurrenceCount++;
        }
    }
