};

class MobileNetwork {
    int numberOfTowers;
    list<Point> towerLocations;
    Point mobileLocation;

public:
    void inputNetworkDetails();
    Point findFarthestTower() const;
};

void Point::inputDetails() {
    cin >> name >> xCoordinate >> yCoordinate;
}

int Point::calculateSquaredDistance(const Point& other) const {
    if (xCoordinate % 2 != 0 || yCoordinate % 2 != 0 || other.xCoordinate % 2 != 0 || other.yCoordinate % 2 != 0) {
        cout << "Invalid input";
        exit(0);
    }
    return pow(xCoordinate - other.xCoordinate, 2) + pow(yCoordinate - other.yCoordinate, 2);
}

