void MobileNetwork::inputNetworkDetails() {
    cin >> numberOfTowers;
    Point tempPoint;
    for (int i = 0; i < numberOfTowers; i++) {
        tempPoint.inputDetails();
        towerLocations.push_back(tempPoint);
    }
    mobileLocation.inputDetails();
}

Point MobileNetwork::findFarthestTower() const {
    Point farthestTower;
    int maxDistance = -1;

    for (const auto& tower : towerLocations) {
        int currentDistance = mobileLocation.calculateSquaredDistance(tower);
        if (currentDistance > maxDistance) {
            maxDistance = currentDistance;
            farthestTower = tower;
        }
    }
    return farthestTower;
}

