class CharVector {
    vector<char> characterVector;

public:
    // Initializes the character vector from a given string
    void initializeVector(const string& inputString);

    // Duplicates the current vector by appending its content to the end
    void duplicateVector();

    // Appends the reverse of the current vector to the end
    void duplicateReverseVector();

    // Prints the content of the vector using iterators
    void print() const;
};

void CharVector::initializeVector(const string& inputString) {
    for (char character : inputString) {
        characterVector.push_back(character);
    }
}

void CharVector::duplicateVector() {
    size_t currentSize = characterVector.size();
    for (size_t i = 0; i < currentSize; ++i) {
        characterVector.push_back(characterVector[i]);
    }
}

void CharVector::duplicateReverseVector() {
    size_t currentSize = characterVector.size();
    for (size_t i = currentSize; i > 0; --i) {
        characterVector.push_back(characterVector[i - 1]);
    }
}

void CharVector::print() const {
    for (auto it = characterVector.begin(); it != characterVector.end(); ++it) {
        cout << *it;
    }
}

