int gcd(int a, int b) {
    a = abs(a);
    b = abs(b);

    while (b != 0) {
        int remainder = a % b;
        a = b;
        b = remainder;
    }
    return a;
}

class Fraction {
private: 
    int numerator;
    int denominator;
public: 
    Fraction(int num, int denom) : numerator(num), denominator(denom) {}

    Fraction(int num) : Fraction(num, 1) {}

    Fraction() : Fraction(0, 1) {}

    void display() const {
        cout << numerator << "/" << denominator << endl;
    }

    void simplify() {
        int commonDivisor = gcd(abs(numerator), abs(denominator));
        numerator /= commonDivisor;
        denominator /= commonDivisor;
    }

    Fraction operator-(const Fraction& other) const {
        Fraction result;
        result.numerator = numerator * other.denominator - denominator * other.numerator;
        result.denominator = denominator * other.denominator;
        result.simplify();
        return result;
    }

    friend Fraction operator+(const Fraction& a, const Fraction& b);
};

Fraction operator+(const Fraction& a, const Fraction& b) {
    Fraction result;
    result.numerator = a.numerator * b.denominator + a.denominator * b.numerator;
    result.denominator = a.denominator * b.denominator;
    result.simplify();
    return result;
}

