        Time result;
        int totalSeconds = 60 * (hours * 60 + minutes) + seconds + secondsToAdd;

        result.seconds = totalSeconds % 60;
        result.minutes = (totalSeconds / 60) % 60;
        result.hours = totalSeconds / 3600;
        return result;
    }

    int operator-(const Time& other) const {
        int thisTotalSeconds = 60 * (hours * 60 + minutes) + seconds;
        int otherTotalSeconds = 60 * (other.hours * 60 + other.minutes) + other.seconds;
        return thisTotalSeconds - otherTotalSeconds;
    }

    friend ostream& operator<<(ostream&, const Time&);
    friend istream& operator>>(istream&, Time&);
};

