    void Output();
    bool IsLeapYear();
    void NextDay();
    int MaxDaysInMonth();
};

// Nhập thông tin ngày tháng năm từ người dùng
void Date::Input() {
    cout << "Nhap ngay: ";
    cin >> day;
    cout << "Nhap thang: ";
    cin >> month;
    cout << "Nhap nam: ";
    cin >> year;
}

// Xuất thông tin ngày tháng năm ra màn hình
void Date::Output() {
    cout << day << "/" << month << "/" << year;
}

// Kiểm tra năm nhuận
bool Date::IsLeapYear() {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// Trả về số ngày tối đa trong tháng hiện tại
int Date::MaxDaysInMonth() {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return IsLeapYear() ? 29 : 28;
        default:
            return 0; // Tháng không hợp lệ
    }
}

// Tính toán ngày kế tiếp
void Date::NextDay() {
    if (year <= 0 || month < 1 || month > 12 || day < 1 || day > MaxDaysInMonth()) {
        cout << "Ngay thang nam khong hop le !!!\n";
        return;
    }

    day++;

    if (day > MaxDaysInMonth()) {
        day = 1;
        month++;
        if (month > 12) {
            month = 1;
            year++;
        }
    }
    cout << "\nNgay ke tiep la: " << day << "/" << month << "/" << year << endl;
}

int main() {
    Date date;

    date.Input();

    cout << endl;
    date.Output();

    date.NextDay();

    return 0;
}

