    void DisplayNextDay();
    void DisplayDayOfWeek();
    int GetMaxDaysInMonth();
};

// Input the day, month, and year from the user
void Date::Input() {
    cout << "Nhap ngay: ";
    cin >> day;
    cout << "Nhap thang: ";
    cin >> month;
    cout << "Nhap nam: ";
    cin >> year;
}

// Output the date in the format day/month/year
void Date::Output() {
    cout << day << "/" << month << "/" << year;
}

// Check if the year is a leap year
bool Date::IsLeapYear() {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// Get the maximum number of days in the current month
int Date::GetMaxDaysInMonth() {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return IsLeapYear() ? 29 : 28;
        default:
            return 0; // Invalid month
    }
}

// Display the day of the week for the current date
void Date::DisplayDayOfWeek() {
    if (year <= 0 || month < 1 || month > 12 || day < 1 || day > GetMaxDaysInMonth()) {
        cout << "Ngay thang nam khong hop le !!!\n";
        return;
    }

    static int monthOffsets[] = {0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4};
    const char* weekDays[] = {"Chu Nhat", "Thu Hai", "Thu Ba", "Thu Tu", "Thu Nam", "Thu Sau", "Thu Bay"};

    if (month < 3)
        year--;
    int result = (year + year / 4 - year / 100 + year / 400 + monthOffsets[month - 1] + day) % 7;
    cout << "\nHom nay la: " << weekDays[result] << endl;
}

int main() {
    Date currentDate;

    currentDate.Input();

    cout << endl;
    currentDate.Output();
    currentDate.DisplayDayOfWeek();

    return 0;
}

