	int calculateGCD(int a, int b) {
		int result = min(a, b);
		while (result > 1) {
			if (a % result == 0 && b % result == 0)
				break;
			result--;
		}
		return result;
	}

	void simplifyFraction(int &numerator, int &denominator) {
		int gcdValue; 
		while (calculateGCD(numerator, denominator) != 1) {
			gcdValue = calculateGCD(numerator, denominator);
			numerator /= gcdValue;
			denominator /= gcdValue;
		}
	}

