class Circle {
private:
    float perimeter, area;

public:
    // Constructor to initialize the circle's perimeter and area based on the radius
    Circle(float radius) {
        perimeter = 2 * 3.14 * radius;
        area = 3.14 * radius * radius;
    }

    float getPerimeter() {
        return perimeter;
    }

    float getArea() {
        return area;
    }
};

class Distance {
private:
    float x1, y1, x2, y2;

public:
    // Constructor to initialize the coordinates of two points
    Distance(float x1, float y1, float x2, float y2) {
        this->x1 = x1;
        this->y1 = y1;
        this->x2 = x2;
        this->y2 = y2;
    }

    // Calculate the distance between the two points
    float getDistance() {
        return sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
    }
};

class Array {
private:
    vector<int> elements;
    int size;
    int targetElement;

public:
    // Constructor to initialize the array with random values within a specified range
    Array(int size, long int minVal = -25062006, long int maxVal = 25062006, int targetElement = NULL) {
        this->size = size;
        elements.resize(size);
        for (int i = 0; i < size; i++) {
            elements[i] = rand() % (maxVal - minVal + 1) + minVal;
        }
        if (targetElement != NULL) {
            this->targetElement = targetElement;
        }
    }

    // Display the elements of the array
    void display() {
        cout << "Array: ";
        for (int i = 0; i < size; i++) {
            cout << elements[i] << " ";
        }
        cout << endl;
    }

    // Get the minimum value in the array
    int getMin() {
        return *min_element(elements.begin(), elements.end());
    }

    // Check the frequency of the target element in the array
    void frequency() {
        if (targetElement == NULL) {
            cout << "Target element not provided to check frequency in the array.\n";
            return;
        }
        map<int, int> frequencyMap;
        for (int i = 0; i < size; i++) {
            frequencyMap[elements[i]]++;
        }
        cout << "Frequency of " << targetElement << " in the array:\n" << frequencyMap[targetElement] << endl;
    }

    // Check if the array is in descending order
    bool isDescending() {
        for (int i = 0; i < size - 1; i++) {
            if (elements[i] < elements[i + 1]) {
                return false;
            }
        }
        return true;
    }

    // Sort the array in ascending order
    void sortAscending() {
        sort(elements.begin(), elements.end());
    }
};

