class ComplexNumber {
private:
    float realPart, imaginaryPart;

public:
    // Constructor to initialize the complex number
    ComplexNumber(int realPart = 0, int imaginaryPart = 0) {
        cout << "Enter the real and imaginary parts of the complex number:\n";
        cin >> realPart >> imaginaryPart;
        this->realPart = realPart;
        this->imaginaryPart = imaginaryPart;
    }

    // Overload the addition operator
    ComplexNumber operator+(const ComplexNumber& other) {
        return ComplexNumber(realPart + other.realPart, imaginaryPart + other.imaginaryPart);
    }

    // Overload the subtraction operator
    ComplexNumber operator-(const ComplexNumber& other) {
        return ComplexNumber(realPart - other.realPart, imaginaryPart - other.imaginaryPart);
    }

    // Overload the multiplication operator
    ComplexNumber operator*(const ComplexNumber& other) {
        return ComplexNumber(realPart * other.realPart - imaginaryPart * other.imaginaryPart,
                             realPart * other.imaginaryPart + imaginaryPart * other.realPart);
    }

    // Display the complex number in standard form
    void display() {
        if (imaginaryPart >= 0) {
            cout << realPart << " + " << imaginaryPart << "i" << endl;
        } else {
            cout << realPart << " - " << -imaginaryPart << "i" << endl;
        }
    }

    // Update the complex number's values
    void update(float realPart, float imaginaryPart) {
        this->realPart = realPart;
        this->imaginaryPart = imaginaryPart;
    }

    // Get the real and imaginary parts as a pair
    pair<float, float> getComplexNumber() {
        return make_pair(realPart, imaginaryPart);
    }

    // Add another complex number to this one and display the result
    void add(ComplexNumber& other) {
        realPart += other.realPart;
        imaginaryPart += other.imaginaryPart;
        cout << "After addition, the complex number is: ";
        display();
    }
};

