#include <bits/stdc++.h>
using namespace std;

class Fraction {
private:
    int numerator;
    int denominator;

public:
    Fraction(int num = 0, int denom = 1) : numerator(num), denominator(denom) {}
    ~Fraction() {}

    friend ostream& operator<<(ostream& os, const Fraction& frac);
    friend istream& operator>>(istream& is, Fraction& frac);

    bool operator>(const Fraction &other) const {
        return (numerator * other.denominator) > (other.numerator * denominator);
    }

    bool isPrime() const {
        if (numerator <= 1) return false;
        for (int i = 2; i <= sqrt(numerator); i++) {
            if (numerator % i == 0) return false;
        }
        return true;
    }
};

ostream& operator<<(ostream& os, const Fraction& frac) {
    return os << frac.numerator << "/" << frac.denominator;
}

istream& operator>>(istream& is, Fraction& frac) {
    cout << "Nhap tu so: ";
    is >> frac.numerator;
    cout << "Nhap mau so: ";
    is >> frac.denominator;
    return is;
}

class FractionArray {
private:
    Fraction *fractions;
    int size;

public:
    FractionArray(int arraySize = 0) : size(arraySize) {
        if (size > 0) {
            fractions = new Fraction[size];
        } else {
            fractions = nullptr;
        }
    }

    ~FractionArray() {
        delete[] fractions;
    }

    void input() {
        cout << "Nhap so phan tu cua mang phan so: ";
        cin >> size;
        if (fractions != nullptr) {
            delete[] fractions;
            fractions = nullptr;
        }
        fractions = new Fraction[size];
        for (int i = 0; i < size; i++) {
            cout << "Nhap phan so thu " << i + 1 << ": ";
            cin >> fractions[i];
        }
    }

    void output() const {
        cout << "Cac phan so trong mang la: \n";
        for (int i = 0; i < size; i++) {
            cout << "Phan so " << i + 1 << ": ";
            cout << fractions[i] << endl;
        }
        cout << endl;
    }

    void generateRandomFractions() {
        if (fractions != nullptr) {
            delete[] fractions;
            fractions = nullptr;
        }
        fractions = new Fraction[size];
        srand(static_cast<unsigned int>(time(0)));
        for (int i = 0; i < size; i++) {
            int num = rand();
            int denom = rand() + 1; // Ensure denominator is not zero
            fractions[i] = Fraction(num, denom);
        }
    }

    void findMaxFraction() const {
        if (size == 0) {
            cout << "Mang rong!" << endl;
            return;
        }
        Fraction maxFraction = fractions[0];
        for (int i = 1; i < size; i++) {
            if (fractions[i] > maxFraction) {
                maxFraction = fractions[i];
            }
        }
        cout << "Phan so lon nhat trong mang la: " << maxFraction << endl;
    }

    void countPrimeNumerators() const {
        int count = 0;
        for (int i = 0; i < size; i++) {
            if (fractions[i].isPrime()) {
                count++;
            }
        }
        cout << "So luong tu so nguyen to trong mang la: " << count << endl;
    }

    void sortFractions() {
        for (int i = 0; i < size - 1; i++) {
            for (int j = i + 1; j < size; j++) {
                if (fractions[i] > fractions[j]) {
                    swap(fractions[i], fractions[j]);
                }
            }
        }
        cout << "Mang phan so sau khi sap xep la: \n";
        output();
    }
};

int main() {
    FractionArray fractionArray;
    fractionArray.input();
    fractionArray.output();
    fractionArray.findMaxFraction();
    fractionArray.countPrimeNumerators();
    fractionArray.sortFractions();

    return 0;
}

#include <iostream>
using namespace std;

class Polynomial {
    int *degree;
    int *coefficients;

public:
    Polynomial(int deg = 0) {
        degree = new int(deg);
        coefficients = new int[deg + 1]();
    }

    ~Polynomial() {
        delete[] coefficients;
        delete degree;
    }

    // Adds two polynomials and returns the result
    Polynomial operator+(const Polynomial &other) {
        Polynomial result(*degree);
        for (int i = 0; i <= *degree; i++) {
            int coeffA = (i <= *degree) ? coefficients[i] : 0;
            int coeffB = (i <= *(other.degree)) ? other.coefficients[i] : 0;
            result.coefficients[i] = coeffA + coeffB;
        }
        return result;
    }

    // Subtracts two polynomials and returns the result
    Polynomial operator-(const Polynomial &other) {
        Polynomial result(*degree);
        for (int i = 0; i <= *degree; i++) {
            int coeffA = (i <= *degree) ? coefficients[i] : 0;
            int coeffB = (i <= *(other.degree)) ? other.coefficients[i] : 0;
            result.coefficients[i] = coeffA - coeffB;
        }
        return result;
    }

    friend ostream &operator<<(ostream &os, const Polynomial &poly);
    friend istream &operator>>(istream &is, Polynomial &poly);
};

ostream &operator<<(ostream &os, const Polynomial &poly) {
    for (int i = *poly.degree; i >= 0; i--) {
        if (poly.coefficients[i] != 0) {
            if (i != 0) {
                os << poly.coefficients[i] << "x^" << i << " + ";
            } else {
                os << poly.coefficients[i];
            }
        }
    }
    return os;
}

istream &operator>>(istream &is, Polynomial &poly) {
    for (int i = 0; i <= *poly.degree; i++) {
        cout << "Coefficient of degree " << i << ": ";
        is >> poly.coefficients[i];
    }
    return is;
}

