    cout << "Enter polynomial a: " << endl;
    cin >> a;

    cout << "Enter polynomial b: " << endl;
    cin >> b;

    Polynomial sum = a + b;
    cout << "Sum of polynomials c = a + b: ";
    cout << sum << endl;

    Polynomial difference = a - b;
    cout << "Difference of polynomials d = a - b: ";
    cout << difference << endl;

    return 0;
}

