#include <iostream>
#include <unordered_map>
#include <algorithm>
#include <ctime>

using namespace std;

class DynamicArray {
private:
    int* elements;
    int size;

public:
    // Constructor to initialize the array with a given size
    DynamicArray(int initialSize = 0) {
        size = initialSize;
        elements = (size > 0) ? new int[size] : nullptr;
    }

    // Destructor to free allocated memory
    ~DynamicArray() {
        delete[] elements;
    }

    // Method to input array elements from user
    void inputElements() {
        cout << "Nhap so phan tu cua mang: ";
        cin >> size;
        delete[] elements; // Free existing memory if any
        elements = new int[size];
        for (int i = 0; i < size; i++) {
            cout << "Nhap phan tu thu " << i + 1 << ": ";
            cin >> elements[i];
        }
    }

    // Method to output array elements
    void displayElements() const {
        cout << "Cac phan tu trong mang la: ";
        for (int i = 0; i < size; i++) {
            cout << elements[i] << " ";
        }
        cout << endl;
    }

    // Method to fill the array with random values
    void fillWithRandomValues() {
        delete[] elements; // Free existing memory if any
        elements = new int[size];
        srand(static_cast<unsigned int>(time(0)));
        for (int i = 0; i < size; i++) {
            elements[i] = rand();
        }
    }

    // Method to calculate and display frequency of each element
    void displayElementFrequency() const {
        unordered_map<int, int> frequencyMap;
        for (int i = 0; i < size; i++) {
            frequencyMap[elements[i]]++;
        }
        cout << "Tan suat xuat hien cua cac phan tu trong mang:\n";
        for (const auto& entry : frequencyMap) {
            cout << "Phan tu " << entry.first << " xuat hien " << entry.second << " lan\n";
        }
    }

    // Method to check if the array is sorted in increasing order
    void checkIfIncreasing() const {
        bool isIncreasing = true;
        for (int i = 1; i < size; i++) {
            if (elements[i] < elements[i - 1]) {
                isIncreasing = false;
                break;
            }
        }
        cout << (isIncreasing ? "Mang la tang dan." : "Mang khong phai la tang dan.") << endl;
    }

    // Method to find the smallest odd element in the array
    void findSmallestOdd() const {
        int smallestOdd = INT_MAX;
        for (int i = 0; i < size; i++) {
            if (elements[i] % 2 != 0 && elements[i] < smallestOdd) {
                smallestOdd = elements[i];
            }
        }
        if (smallestOdd != INT_MAX) {
            cout << "Phan tu le nho nhat trong mang la: " << smallestOdd << endl;
        } else {
            cout << "Khong co phan tu le trong mang." << endl;
        }
    }

    // Method to sort the array in ascending order
    void sortArray() {
        sort(elements, elements + size);
    }
};

int main() {
    DynamicArray array;
    array.inputElements();
    array.displayElements();
    array.displayElementFrequency();
    array.checkIfIncreasing();
    array.findSmallestOdd();
    array.sortArray();
    array.displayElements();
    array.fillWithRandomValues();
    array.displayElements();
    return 0;
}

