class Fraction {
private:
    int numerator, denominator;

public:
    Fraction(int num = 0, int denom = 1) : numerator(num), denominator(denom) {}
    Fraction(const Fraction& frac) : numerator(frac.numerator), denominator(frac.denominator) {}

    int GetNumerator() const { return numerator; }
    int GetDenominator() const { return denominator; }
    void SetNumerator(int num) { numerator = num; }
    void SetDenominator(int denom) { denominator = denom; }

    void Input() {
        cout << "Nhap tu so: ";
        cin >> numerator;
        cout << "Nhap mau so: ";
        cin >> denominator;
    }

    void Output() const {
        cout << numerator << "/" << denominator;
    }

    bool operator>(const Fraction& frac) const {
        return (numerator * frac.denominator) > (frac.numerator * denominator);
    }

    Fraction operator+(const Fraction& frac) const {
        Fraction result;
        result.numerator = numerator * frac.denominator + frac.numerator * denominator;
        result.denominator = denominator * frac.denominator;
        return result;
    }

    Fraction operator-(const Fraction& frac) const {
        Fraction result;
        result.numerator = numerator * frac.denominator - frac.numerator * denominator;
        result.denominator = denominator * frac.denominator;
        return result;
    }
};

class FractionList {
private:
    Fraction* fractions;
    int count;

public:
    FractionList(int size = 0) : count(size), fractions((size == 0) ? nullptr : new Fraction[size]) {}

    ~FractionList() {
        delete[] fractions;
    }

    friend istream& operator>>(istream& is, FractionList& fracList);
    friend ostream& operator<<(ostream& os, const FractionList& fracList);

    Fraction FindMax() const {
        Fraction maxFraction = fractions[0];
        for (int i = 1; i < count; i++) {
            if (fractions[i] > maxFraction) {
                maxFraction = fractions[i];
            }
        }
        return maxFraction;
    }

    Fraction Sum() const {
        Fraction total;
        for (int i = 0; i < count; i++) {
            total = total + fractions[i];
        }
        return total;
    }
};

istream& operator>>(istream& is, FractionList& fracList) {
