#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

// Structure to represent a large integer
struct BigInteger {
    char sign;  // Sign indicator: '1' for positive, '0' for negative
    string value;  // The numeric part of the large integer
};

// Compares two large number strings
int compareBigInteger(const string &a, const string &b) {
    if (a.length() != b.length()) 
        return a.length() - b.length();  // Compare lengths first
    return a.compare(b);  // If lengths are equal, compare lexicographically
}

// Adds two large number strings
string addBigInteger(const string &a, const string &b) {
    string result;
    int carry = 0;  
    int i = a.length() - 1;  
    int j = b.length() - 1;  
    while (i >= 0 || j >= 0 || carry) {  
        int digitA = (i >= 0) ? a[i--] - '0' : 0;  
        int digitB = (j >= 0) ? b[j--] - '0' : 0;  
        int sum = digitA + digitB + carry;  
        result += (sum % 10 + '0');  
        carry = sum / 10;  
    }
    while (result.length() > 1 && result.back() == '0') 
        result.pop_back();  // Remove leading zeros
    reverse(result.begin(), result.end());  // Reverse the result
    return result;
}

// Subtracts two large number strings
string subtractBigInteger(const string &a, const string &b) {
    string result;
    int carry = 0;
    int i = a.length() - 1;
    int j = b.length() - 1;
    while (i >= 0) {
        int digitA = (i >= 0) ? a[i--] - '0' : 0;  
        int digitB = (j >= 0) ? b[j--] - '0' : 0;  
        int difference = digitA - digitB - carry;  
        if (difference < 0) {
            difference += 10;
            carry = 1;
        } else {
            carry = 0;
        }
        result += (difference + '0');  
    }
    while (result.length() > 1 && result.back() == '0') 
        result.pop_back();  // Remove leading zeros
    reverse(result.begin(), result.end());  // Reverse the result
    return result;
}

// Multiplies two large number strings
string multiplyBigInteger(const string &a, const string &b) {
    int lenA = a.length();
    int lenB = b.length();
    string result(lenA + lenB, '0');  
    for (int i = lenA - 1; i >= 0; i--) {
        int carry = 0;
        for (int j = lenB - 1; j >= 0; j--) {
            int product = (result[i + j + 1] - '0') + (a[i] - '0') * (b[j] - '0') + carry;
            result[i + j + 1] = (product % 10 + '0');  
            carry = product / 10;  
        }
        result[i] += carry;  // Add any remaining carry
    }
    size_t pos = result.find_first_not_of('0');
    return (pos == string::npos) ? "0" : result.substr(pos);  // Remove leading zeros
}

// Converts a string to a BigInteger
BigInteger stringToBigInteger(const string& s) {
    BigInteger bigInt;
    bigInt.sign = s[0];  
    bigInt.value = s.substr(1);  
    if (bigInt.value.empty()) {
        bigInt.value = "0";
        bigInt.sign = '1';  // Default to positive if empty
    }
    return bigInt;
}

// Overloads the + operator for BigInteger
BigInteger operator + (BigInteger a, BigInteger b) {
    BigInteger result;
    if (a.sign == b.sign) {  
        result.sign = a.sign;
        result.value = addBigInteger(a.value, b.value); 
    } else {  
        if (compareBigInteger(a.value, b.value) >= 0) {
            result.sign = a.sign;
            result.value = subtractBigInteger(a.value, b.value);
        } else {
            result.sign = b.sign;
            result.value = subtractBigInteger(b.value, a.value);
        }
    }
    if (result.value == "0") 
        result.sign = '1';  // Treat zero as positive
    return result;
}

// Overloads the - operator for BigInteger
BigInteger operator - (BigInteger a, BigInteger b) {
    b.sign = (b.sign == '1' ? '0' : '1');  // Flip the sign of b for subtraction
    return a + b;
}

// Overloads the * operator for BigInteger
BigInteger operator * (BigInteger a, BigInteger b) {
    BigInteger result;
    result.sign = (a.sign == b.sign ? '1' : '0');  
    result.value = multiplyBigInteger(a.value, b.value);
    if (result.value == "0") 
        result.sign = '1';  // Treat zero as positive
    return result;
}

// Overloads the * operator for BigInteger and integer
BigInteger operator * (BigInteger a, int n) {
    BigInteger b;
    b.sign = '1';  
    b.value = to_string(n);  
    return a * b;
}

int main() {
    cout << "Pham Duc Manh - 20235155" << endl; 

    string inputA, inputB;
    cin >> inputA >> inputB;  // Input two large numbers

    BigInteger a = stringToBigInteger(inputA);  // Convert string to BigInteger
    BigInteger b = stringToBigInteger(inputB);

    BigInteger result = a * b - a * 3 + b * 4;  // Calculate the expression

    cout << result.sign << result.value;  // Output the result

    return 0;
}

