void displayIntro();
void createNewAccount();
void displayAccount(int accountNumber);
void displayAllAccounts();
void modifyAccount(int accountNumber);
void deleteAccount(int accountNumber);
void handleDepositOrWithdrawal(int accountNumber, int option);

int main() {
    int accountNumber, choice;
    displayIntro();
    do {
        cout << "\tMenu" << endl;
        cout << "1. Create account" << endl;
        cout << "2. Deposit amount" << endl;
        cout << "3. Withdraw amount" << endl;
        cout << "4. Check balance" << endl;
        cout << "5. Display details of all accounts" << endl;
        cout << "6. Close an account" << endl;
        cout << "7. Update account details" << endl;
        cout << "8. Quit" << endl;
        cout << "Choose an option." << endl;
        cin >> choice;

        switch (choice) {
            case 1:
                createNewAccount();
                break;
            case 2:
                cout << "Enter account number:" << endl;
                cin >> accountNumber;
                handleDepositOrWithdrawal(accountNumber, 1);
                break;
            case 3:
                cout << "Enter account number:" << endl;
                cin >> accountNumber;
                handleDepositOrWithdrawal(accountNumber, 2);
                break;
            case 4:
                cout << "Enter account number:" << endl;
                cin >> accountNumber;
                displayAccount(accountNumber);
                break;
            case 5:
                displayAllAccounts();
                break;
            case 6:
                cout << "Enter account number:" << endl;
                cin >> accountNumber;
                deleteAccount(accountNumber);
                break;
            case 7:
                cout << "Enter account number:" << endl;
                cin >> accountNumber;
                modifyAccount(accountNumber);
                break;
            case 8:
                cout << "-> Exiting the banking system" << endl << "Thank you for using the banking system" << endl;
                break;
            default:
                cout << "Invalid choice" << endl;
        }
    } while (choice != 8);
    return 0;
}

void createNewAccount() {
    Account newAccount;
    ofstream outputFile;
    outputFile.open("account.dat", ios::binary | ios::app);
    newAccount.createAccount();
    outputFile.write(reinterpret_cast<char*>(&newAccount), sizeof(Account));
    outputFile.close();
}

void displayAccount(int accountNumber) {
    Account account;
    bool accountFound = false;
    ifstream inputFile;
    inputFile.open("account.dat", ios::binary);
    if (!inputFile) {
        cout << "Unable to open file - press any key" << endl;
        return;
    }
    while (inputFile.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccountDetails();
            accountFound = true;
            break;
        }
    }
    inputFile.close();
    if (!accountFound) {
        cout << "Account number does not exist" << endl;
    }
}

void modifyAccount(int accountNumber) {
    bool accountFound = false;
    Account account;
    fstream file;
    file.open("account.dat", ios::binary | ios::in | ios::out);
    if (!file) {
        cout << "Unable to open file - press any key to continue" << endl;
        return;
    }
    while (file.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccountDetails();
            cout << "Modifying account details." << endl;
            account.modifyAccountDetails();
            file.seekp(-static_cast<int>(sizeof(Account)), ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            cout << "Record updated successfully" << endl;
            accountFound = true;
            break;
        }
    }
    file.close();
    if (!accountFound) {
        cout << "\n\n Record Not Found ";
    }
}

void deleteAccount(int accountNumber) {
    Account account;
    ifstream inputFile;
    ofstream outputFile;
    inputFile.open("account.dat", ios::binary);
    if (!inputFile) {
