void handleDepositOrWithdrawal(int accountNumber, int option) {
    int amount;
    bool accountFound = false;
    Account account;
    fstream file;
    file.open("account.dat", ios::binary | ios::in | ios::out);
    if (!file) {
        cout << "Unable to open file, press any key to continue." << endl;
        return;
    }
    while (file.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccountDetails();
            if (option == 1) {
                cout << "Enter amount to be deposited into the account" << endl;
                cin >> amount;
                account.deposit(amount);
            } else if (option == 2) {
                cout << "Enter amount to be withdrawn from the account" << endl;
                cin >> amount;
                int newBalance = account.getBalance() - amount;
                if ((newBalance < 500 && account.getAccountType() == 'S') || 
                    (newBalance < 1000 && account.getAccountType() == 'C')) {
                    cout << "Balance insufficient" << endl;
                } else {
                    account.withdraw(amount);
                }
            }
            file.seekp(-static_cast<int>(sizeof(Account)), ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            cout << "Balance successfully updated" << endl;
            accountFound = true;
            break;
        }
    }
    file.close();
    if (!accountFound) {
        cout << "\tRecord not found." << endl;
    }
}

