void issueBook() {
    char studentAdmissionNumber[6], bookNumber[6];
    bool studentFound = false, bookFound = false;
    system("cls");
    cout << "\n\nBOOK ISSUE ...";
    cout << "\n\n\tEnter The Student's Admission Number: ";
    cin >> studentAdmissionNumber;
    fileStream.open("student.dat", ios::in | ios::out);
    fstream bookFileStream;
    bookFileStream.open("book.dat", ios::in | ios::out);
    while (fileStream.read(reinterpret_cast<char*>(&student), sizeof(Student)) && !studentFound) {
        if (strcasecmp(student.getAdmissionNumber(), studentAdmissionNumber) == 0) {
            studentFound = true;
            if (student.getToken() == 0) {
                cout << "\n\n\tEnter the Book Number: ";
                cin >> bookNumber;
                while (bookFileStream.read(reinterpret_cast<char*>(&book), sizeof(Book)) && !bookFound) {
                    if (strcasecmp(book.getBookNumber(), bookNumber) == 0) {
                        book.showBook();
                        bookFound = true;
                        student.issueBook();
                        student.setIssuedBookNumber(book.getBookNumber());
                        int position = -1 * sizeof(student);
                        fileStream.seekp(position, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&student), sizeof(Student));
                        cout << "\n\n\t Book issued successfully\n\nPlease Note: Write the current date on the backside of the book and submit within 15 days. Fine Rs. 1 for each day after the 15-day period.";
                    }
                }
                if (!bookFound)
                    cout << "Book number does not exist";
            } else {
                cout << "You have not returned the last book.";
            }
        }
    }
    if (!studentFound)
        cout << "Student record does not exist...";
    getch();
    fileStream.close();
    bookFileStream.close();
}

void depositBook() {
    char studentAdmissionNumber[6], bookNumber[6];
    bool studentFound = false, bookFound = false;
    int days, fine;
    system("cls");
    cout << "\n\nBOOK DEPOSIT ...";
    cout << "\n\n\tEnter The Student’s Admission Number: ";
    cin >> studentAdmissionNumber;
    fileStream.open("student.dat", ios::in | ios::out);
    fstream bookFileStream;
    bookFileStream.open("book.dat", ios::in | ios::out);
    while (fileStream.read(reinterpret_cast<char*>(&student), sizeof(Student)) && !studentFound) {
        if (strcasecmp(student.getAdmissionNumber(), studentAdmissionNumber) == 0) {
            studentFound = true;
            if (student.getToken() == 1) {
                while (bookFileStream.read(reinterpret_cast<char*>(&book), sizeof(Book)) && !bookFound) {
                    if (strcasecmp(book.getBookNumber(), student.getIssuedBookNumber()) == 0) {
                        book.showBook();
                        bookFound = true;
                        cout << "\n\nBook deposited in number of days: ";
                        cin >> days;
                        if (days > 15) {
                            fine = (days - 15) * 1;
                            cout << "\n\nFine to be deposited: Rs. " << fine;
                        }
                        student.returnBook();
                        int position = -1 * sizeof(student);
                        fileStream.seekp(position, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&student), sizeof(Student));
                        cout << "\n\n\t Book deposited successfully";
                    }
                }
                if (!bookFound)
                    cout << "Book number does not exist";
            } else {
                cout << "No book is issued. Please check!";
            }
        }
    }
    if (!studentFound)
        cout << "Student record does not exist...";
    getch();
    fileStream.close();
    bookFileStream.close();
}

