#include <iostream>
#include <fstream>
#include <cstdlib>
#include <vector>
#include <map>

using namespace std;

#define MIN_BALANCE 500

class InsufficientFunds {};

class Account {
private:
    long accountNumber;
    string firstName;
    string lastName;
    float balance;
    static long nextAccountNumber;

public:
    Account() {}
    Account(string fname, string lname, float initialBalance);

    long getAccountNumber() const { return accountNumber; }
    string getFirstName() const { return firstName; }
    string getLastName() const { return lastName; }
    float getBalance() const { return balance; }

    void deposit(float amount);
    void withdraw(float amount);
    static void setLastAccountNumber(long accountNumber);
    static long getLastAccountNumber();

    friend ofstream& operator<<(ofstream& ofs, const Account& acc);
    friend ifstream& operator>>(ifstream& ifs, Account& acc);
    friend ostream& operator<<(ostream& os, const Account& acc);
};

long Account::nextAccountNumber = 0;

class Bank {
private:
    map<long, Account> accounts;

public:
    Bank();
    Account openAccount(string fname, string lname, float initialBalance);
    Account balanceEnquiry(long accountNumber);
    Account deposit(long accountNumber, float amount);
    Account withdraw(long accountNumber, float amount);
    void closeAccount(long accountNumber);
    void showAllAccounts();
    ~Bank();
};

int main() {
    Bank bank;
    Account account;

    int choice;
    string firstName, lastName;
    long accountNumber;
    float initialBalance;
    float amount;

    cout << "*** Banking System ***" << endl;

    do {
        cout << "\n\tSelect one option below ";
        cout << "\n\t1. Open an Account";
        cout << "\n\t2. Balance Enquiry";
        cout << "\n\t3. Deposit";
        cout << "\n\t4. Withdrawal";
        cout << "\n\t5. Close an Account";
        cout << "\n\t6. Show All Accounts";
        cout << "\n\t7. Quit";
        cout << "\nEnter your choice: ";
        cin >> choice;

        switch (choice) {
            case 1:
                cout << "Enter First Name: ";
                cin >> firstName;
                cout << "Enter Last Name: ";
                cin >> lastName;
                cout << "Enter Initial Balance: ";
                cin >> initialBalance;
                account = bank.openAccount(firstName, lastName, initialBalance);
                cout << endl << "Congratulations! Account is Created" << endl;
                cout << account;
                break;

            case 2:
                cout << "Enter Account Number: ";
                cin >> accountNumber;
                account = bank.balanceEnquiry(accountNumber);
                cout << endl << "Your Account Details" << endl;
                cout << account;
                break;

            case 3:
                cout << "Enter Account Number: ";
                cin >> accountNumber;
                cout << "Enter Amount to Deposit: ";
                cin >> amount;
                account = bank.deposit(accountNumber, amount);
                cout << endl << "Amount Deposited" << endl;
                cout << account;
                break;

            case 4:
                cout << "Enter Account Number: ";
                cin >> accountNumber;
                cout << "Enter Amount to Withdraw: ";
                cin >> amount;
                account = bank.withdraw(accountNumber, amount);
                cout << endl << "Amount Withdrawn" << endl;
                cout << account;
                break;

            case 5:
                cout << "Enter Account Number: ";
                cin >> accountNumber;
                bank.closeAccount(accountNumber);
                cout << endl << "Account is Closed" << endl;
                break;

            case 6:
                bank.showAllAccounts();
                break;

            case 7:
                break;

            default:
                cout << "\nEnter a correct choice";
                exit(0);
        }
    } while (choice != 7);

    return 0;
}

Account::Account(string fname, string lname, float initialBalance) {
    nextAccountNumber++;
    accountNumber = nextAccountNumber;
    firstName = fname;
    lastName = lname;
    balance = initialBalance;
}

void Account::deposit(float amount) {
    balance += amount;
}

void Account::withdraw(float amount) {
    if (balance - amount < MIN_BALANCE) {
        throw InsufficientFunds();
    }
    balance -= amount;
}

void Account::setLastAccountNumber(long accountNumber) {
    nextAccountNumber = accountNumber;
}

long Account::getLastAccountNumber() {
    return nextAccountNumber;
}

ofstream& operator<<(ofstream& ofs, const Account& acc) {
    ofs << acc.accountNumber << endl;
    ofs << acc.firstName << endl;
    ofs << acc.lastName << endl;
    ofs << acc.balance << endl;
    return ofs;
}

ifstream& operator>>(ifstream& ifs, Account& acc) {
    ifs >> acc.accountNumber;
    ifs >> acc.firstName;
    ifs >> acc.lastName;
    ifs >> acc.balance;
    return ifs;
}

ostream& operator<<(ostream& os, const Account& acc) {
    os << "First Name: " << acc.getFirstName() << endl;
    os << "Last Name: " << acc.getLastName() << endl;
    os << "Account Number: " << acc.getAccountNumber() << endl;
    os << "Balance: " << acc.getBalance() << endl;
    return os;
}

Bank::Bank() {
    Account account;
    ifstream infile("Bank.data");

    if (!infile) {
        return;
    }

    while (!infile.eof()) {
        infile >> account;
        accounts.insert(pair<long, Account>(account.getAccountNumber(), account));
    }

    Account::setLastAccountNumber(account.getAccountNumber());
    infile.close();
}

Account Bank::openAccount(string fname, string lname, float initialBalance) {
    ofstream outfile;
    Account account(fname, lname, initialBalance);
    accounts.insert(pair<long, Account>(account.getAccountNumber(), account));

    outfile.open("Bank.data", ios::trunc);
    for (const auto& entry : accounts) {
        outfile << entry.second;
    }
    outfile.close();
    return account;
}

Account Bank::balanceEnquiry(long accountNumber) {
    auto itr = accounts.find(accountNumber);
    return itr->second;
}

Account Bank::deposit(long accountNumber, float amount) {
    auto itr = accounts.find(accountNumber);
    itr->second.deposit(amount);
    return itr->second;
}

Account Bank::withdraw(long accountNumber, float amount) {
    auto itr = accounts.find(accountNumber);
    itr->second.withdraw(amount);
    return itr->second;
}

void Bank::closeAccount(long accountNumber) {
    auto itr = accounts.find(accountNumber);
    cout << "Account Deleted: " << itr->second;
    accounts.erase(accountNumber);
}

void Bank::showAllAccounts() {
    for (const auto& entry : accounts) {
        cout << "Account " << entry.first << endl << entry.second << endl;
    }
}

Bank::~Bank() {
    ofstream outfile("Bank.data", ios::trunc);
    for (const auto& entry : accounts) {
        outfile << entry.second;
    }
    outfile.close();
}

