EmployeeNode* mergeSortedLists(EmployeeNode* a, EmployeeNode* b);
void splitList(EmployeeNode* source, EmployeeNode** frontRef, EmployeeNode** backRef);

void mergeSort(EmployeeNode** headRef) {
    EmployeeNode* head = *headRef;
    EmployeeNode* a;
    EmployeeNode* b;

    if ((head == nullptr) || (head->next == nullptr)) {
        return;
    }

    splitList(head, &a, &b);
    mergeSort(&a);
    mergeSort(&b);
    *headRef = mergeSortedLists(a, b);
}

EmployeeNode* mergeSortedLists(EmployeeNode* a, EmployeeNode* b) {
    EmployeeNode* result = nullptr;

    if (a == nullptr) return b;
    else if (b == nullptr) return a;

    if (a->firstName <= b->firstName) {
        result = a;
        result->next = mergeSortedLists(a->next, b);
    } else {
        result = b;
        result->next = mergeSortedLists(a, b->next);
    }
    return result;
}

void splitList(EmployeeNode* source, EmployeeNode** frontRef, EmployeeNode** backRef) {
    EmployeeNode* fast;
    EmployeeNode* slow;
    slow = source;
    fast = source->next;

    while (fast != nullptr) {
        fast = fast->next;
        if (fast != nullptr) {
            slow = slow->next;
            fast = fast->next;
        }
    }

    *frontRef = source;
    *backRef = slow->next;
    slow->next = nullptr;
}

