void irc::log::initialize()
{
	const auto &options(get_opts());
	if (!options.get<bool>("logging"))
		return;

	const int result(mkdir(options["logdir"].c_str(), 0777));
	if (result && errno != EEXIST)
		throw Internal("Failed to create specified logfile directory [") << options["logdir"] << "]";
}

bool irc::log::logMessage(const Msg &message, const Chan &channel, const User &user)
try
{
	const auto &options(get_opts());
	if (!options.get<bool>("logging"))
		return false;

	Log logFile(get_log_path(channel.get_name()));
	logFile(message, channel, user);
	return true;
}
catch (const Internal &exception)
{
	std::cerr << exception << std::endl;
	return false;
}

bool irc::log::exists(const std::string &name, const Filter &filter)
{
	return !for_each(name, [&filter](const ClosureArgs &args)
	{
		return !filter(args);
	});
}

bool irc::log::atLeast(const std::string &name, const Filter &filter, const size_t &count)
{
	size_t matchedCount(0);
	return !count || !for_each(name, [&filter, &matchedCount, &count](const ClosureArgs &args)
	{
		matchedCount += filter(args);
		return matchedCount < count;
	});
}

size_t irc::log::count(const std::string &name, const Filter &filter)
{
	size_t matchedCount(0);
	for_each(name, [&filter, &matchedCount](const ClosureArgs &args)
	{
		matchedCount += filter(args);
		return true;
	});

	return matchedCount;
}

bool irc::log::for_each(const std::string &name, const Filter &filter, const Closure &closure)
{
	return for_each(name, [&filter, &closure](const ClosureArgs &args)
	{
		if (!filter(args))
			return true;

		return closure(args);
	});
}

bool irc::log::for_each(const std::string &name, const Closure &closure)
try
{
	std::ifstream file;
	file.exceptions(std::ios_base::badbit);
	file.open(get_log_path(name), std::ios_base::in);

	while (true)
	{
		char buffer[64] alignas(16);
		file.getline(buffer, sizeof(buffer));
		const size_t length = strlen(buffer);
		std::replace(buffer, buffer + length, ' ', '\0');
		if (!length)
			return true;

		size_t index(0);
		const char *ptr(buffer), *const end(buffer + length);
		std::array<const char *, Log::_NUM_FIELDS> fields;
		while (ptr < end)
		{
			fields[index++] = ptr;
			ptr += strlen(ptr) + 1;
		}

		while (index < fields.size())
			fields[index++] = nullptr;

		if (__builtin_expect((!fields[Log::VERS] || *fields[Log::VERS] != '0'), 0))
			throw Assertive("Log file corruption detected. Aborting...");

		const ClosureArgs args
		{
			atoll(fields[Log::TIME]),
			fields[Log::ACCT],
			fields[Log::NICK],
			fields[Log::TYPE],
		};

		if (!closure(args))
			return false;
	}
}
catch (const std::ios_base::failure &exception)
{
	throw Exception(exception.what());
}

std::string irc::log::get_log_path(const std::string &name)
{
	const auto &options(get_opts());
	return options["logdir"] + "/" + name;
}

///////////////////////////////////////////////////////////////////////////////
//
// Log class for handling log file operations
//

irc::log::Log::Log(const std::string &path)
try :
	path(path)
{
	file.exceptions(std::ios_base::badbit | std::ios_base::failbit);
	file.open(path, std::ios_base::app);
}
catch (const std::exception &exception)
{
	throw Internal("Failed opening Log [") << path << "]";
}

irc::log::Log::~Log() noexcept try
{
	flush();
	file.close();
}
catch (const std::exception &exception)
{
	std::cerr << "Failed closing Log [" << get_log_path() << "]" << std::endl;
}

void irc::log::Log::flush()
try
{
	file.flush();
}
catch (const std::ios_base::failure &failure)
{
	throw Internal("Failed flushing log [") << get_log_path() << "]: " << failure.what();
}

void irc::log::Log::operator()(const Msg &message, const Chan &channel, const User &user)
try
{
	static const uint VERSION(0);
	const time_t currentTime(std::time(nullptr));
	const std::string &account(user.is_logged_in() ? user.get_acct() : "*");
	const std::string &nickname(user.get_nick());
	const std::string &type(!message.get_code() ? message.get_name().substr(0, 3) : lex_cast(message.get_code()));
	file << VERSION
	     << ' '
	     << currentTime
	     << ' '
	     << account
	     << ' '
	     << nickname
	     << ' '
	     << type
	     << '\n';
}
catch (const std::ios_base::failure &failure)
{
	throw Internal("Failed appending log [") << get_log_path() << "]: " << failure.what();
}

