bool irc::log::FilterAny::operator()(const ClosureArgs &args) const
{
	return std::any_of(this->begin(), this->end(), [&args](const auto &filter)
	{
		return filter(args);
	});
}

bool irc::log::FilterAll::operator()(const ClosureArgs &args) const
{
	return std::all_of(this->begin(), this->end(), [&args](const auto &filter)
	{
		return filter(args);
	});
}

bool irc::log::FilterNone::operator()(const ClosureArgs &args) const
{
	return std::none_of(this->begin(), this->end(), [&args](const auto &filter)
	{
		return filter(args);
	});
}

namespace irc {
namespace log {

struct ClosureArguments
{
	const time_t &timestamp;
	const char *const &accountName;
	const char *const &nickname;
	const char *const &eventType;
};

using ClosureFunction = std::function<bool (const ClosureArguments &)>;

class Filter : protected std::vector<ClosureFunction>
{
  public:
	virtual bool operator()(const ClosureArguments &args) const = 0;

  protected:
	template<class... Args> Filter(Args&&... args): std::vector<ClosureFunction>{std::forward<Args>(args)...} {}
};

class AnyFilter : public Filter
{
	bool operator()(const ClosureArguments &args) const override;

  public:
	template<class... Args> AnyFilter(Args&&... args): Filter(std::forward<Args>(args)...) {}
};

class AllFilter : public Filter
{
	bool operator()(const ClosureArguments &args) const override;

  public:
	template<class... Args> AllFilter(Args&&... args): Filter(std::forward<Args>(args)...) {}
};

class NoneFilter : public Filter
{
	bool operator()(const ClosureArguments &args) const override;

  public:
	template<class... Args> NoneFilter(Args&&... args): Filter(std::forward<Args>(args)...) {}
};

class Logger
{
	std::string logFilePath;
	std::ofstream logFileStream;

  public:
	enum LogField
	{
		VERSION     = 0,     // Version/format of this log entry
		TIMESTAMP   = 1,     // Epoch time in seconds
		ACCOUNT     = 2,     // NickServ account name
		NICKNAME    = 3,     // Nickname
		EVENT_TYPE  = 4,     // Type of event

		NUM_FIELDS
	};

	auto &getLogFilePath() const                          { return logFilePath;     }
	auto &getLogFileStream() const                        { return logFileStream;   }

	void operator()(const Msg &message, const Chan &channel, const User &user);
	void flush();

	Logger(const std::string &filePath);
	~Logger() noexcept;
};

