class Schedule
{
    std::deque<std::tuple<id_t, time_t>> scheduleQueue;

    void sortSchedule();

public:
    static constexpr time_t maxTime() { return std::numeric_limits<int32_t>::max(); }

    bool isEmpty() const { return scheduleQueue.empty(); }
    auto getSize() const { return scheduleQueue.size(); }
    id_t getNextId() const { return !isEmpty() ? std::get<id_t>(scheduleQueue.at(0)) : 0; }
    time_t getNextAbsoluteTime() const { return !isEmpty() ? std::get<time_t>(scheduleQueue.at(0)) : maxTime(); }
    time_t getNextRelativeTime() const { return !isEmpty() ? getNextAbsoluteTime() - time(NULL) : maxTime(); }

    void addSchedule(const id_t &id, const time_t &absoluteTime);
    id_t removeNext();
};


