Book::Book(const std::vector<Person>& personList, const std::string& mode, const std::string& info)
    : pBook(personList), queryMode(mode), queryInf(info), rBook(getMembers()) {}

std::vector<Person> Book::getMembers() {
    // Retrieve members based on the specified query mode
    if (queryMode == "1") {
        queryByName();
    } else if (queryMode == "2") {
        queryByGender();
    } else if (queryMode == "3") {
        queryByNumber();
    }
    return rBook;
}

void Book::queryByName() {
    // Clear previous results and search by name
    rBook.clear();
    for (const Person& person : pBook) {
        if (person.getName() == queryInf) {
            rBook.push_back(person);
        }
    }
}

void Book::queryByGender() {
    // Clear previous results and search by gender
    rBook.clear();
    for (const Person& person : pBook) {
        if (person.getGender() == queryInf) {
            rBook.push_back(person);
        }
    }
}

void Book::queryByNumber() {
    // Clear previous results and search by telephone number
    rBook.clear();
    for (const Person& person : pBook) {
        if (person.getNumber() == queryInf) {
            rBook.push_back(person);
        }
    }
}

std::ostream& operator<<(std::ostream& output, const Book& book) {
    // Output the results to both console and file
    std::vector<Person> results = book.rBook;
    std::ofstream fout("result.txt");

    while (!results.empty()) {
        const Person& person = results.back();
        fout << person.getName() << " " << person.getGender() << " " << person.getNumber() << std::endl;
        output << person.getName() << " " << person.getGender() << " " << person.getNumber() << std::endl;
        results.pop_back();
    }

    fout.close();
    return output;
}

