// Class representing a collection of books and associated queries
class Book {
private:
    vector<Person> members; // List of members in the book
    vector<Person> results; // Query results
    string mode; // Current query mode
    string information; // Query information

public:
    // Constructor to initialize the book with members, mode, and information
    Book(vector<Person> members, string mode, string information);

    // Retrieve the list of members
    vector<Person> getMembers();

    // Query members by name
    void queryByName();

    // Query members by gender
    void queryByGender();

    // Query members by number
    void queryByNumber();

