#pragma once
#include "dNode.h"

template <class T>
class dList {
private:
	dNode<T>* head; // Pointer to the first node
	dNode<T>* tail; // Pointer to the last node
	int count; // Number of elements in the list

	// Utility functions for internal use
	static dNode<T>* copy(dNode<T>*, dNode<T>*&);
	static bool lexicographicCompare(dNode<T>*, dNode<T>*);
	static void destroy(dNode<T>* head_node);

public:
	class const_iterator {
		friend class dList;
	private:
		dNode<T>* current; // Pointer to the current node
		const_iterator(dNode<T>* node = nullptr) : current(node) {}

	public:
		const_iterator& operator++() // Increment to the next node
		{
			if (current != nullptr) {
				current = current->next;
			}
			return *this;
		}
		bool operator==(const const_iterator& other) const // Check for equality
		{
			return current == other.current;
		}
		bool operator!=(const const_iterator& other) const // Check for inequality
		{
			return current != other.current;
		}
		T& operator*() const // Dereference to access value
		{
			return current->info;
		}
		T* operator->() const // Access member of the value
		{
			return &(current->info);
		}
	};

	const_iterator begin() const {
		return const_iterator(head);
	}
	const_iterator end() const {
		return const_iterator();
	}

	dList(const dList& other) :
		head(copy(other.head, tail)), // Copy nodes from another list
		count(other.count)
	{}
	~dList() {
		destroy(head); // Clean up allocated memory
	}

	dList& operator=(const dList& other); // Assignment operator
	bool operator<(const dList&) const; // Lexicographic comparison

	void insertFront(const T& value); // Insert value at the front
	void insertBack(const T& value); // Insert value at the back
	int getSize() const; // Get the number of elements

	dList(int numElements = 0, const T& value = T()) :
		head(nullptr),
		tail(nullptr),
		count(0)
	{
		for (int i = 0; i < numElements; i++) {
			insertFront(value); // Initialize list with specified number of elements
		}
	}
};

template <class T>
dNode<T>* dList<T>::copy(dNode<T>* source, dNode<T>*& tailNode)
{
	if (source == nullptr) {
		tailNode = nullptr;
		return nullptr;
	}

	dNode<T>* newNode = new dNode<T>(source->info);
	dNode<T>* tempNode = newNode;

	while (source->next != nullptr) {
		tempNode->next = new dNode<T>(source->next->info, tempNode);
		tempNode = tempNode->next;
		source = source->next;
	}

	tailNode = tempNode; // Set tail to the last node of the new list
	return newNode; // Return the head of the new list
}

template <class T>
bool dList<T>::lexicographicCompare(dNode<T>* list1, dNode<T>* list2) {
	if (list1 == nullptr && list2 == nullptr) {
		return true; // Both lists are empty
	}

	if (list2 == nullptr) {
		return false; // Only list1 has elements
	}

	if (list1->info < list2->info) {
		return true; // list1 is lexicographically smaller
	}
	if (list1->info > list2->info) {
		return false; // list1 is lexicographically larger
	}

	return lexicographicCompare(list1->next, list2->next); // Compare next nodes
}

template <class T>
void dList<T>::destroy(dNode<T>* head_node) {
	while (head_node != nullptr) {
		dNode<T>* temp = head_node;
		head_node = head_node->next;
		delete temp; // Free memory for each node
	}
}

template <class T>
dList<T>& dList<T>::operator=(const dList& other)
{
	if (this != &other) { // Prevent self-assignment
		destroy(head); // Clean up current list
		head = copy(other.head, tail); // Copy nodes from the other list
		count = other.count; // Update size
	}

	return *this;
}

template <class T>
bool dList<T>::operator<(const dList<T>& other) const
{
	return lexicographicCompare(head, other.head); // Compare lists lexicographically
}

template <class T>
void dList<T>::insertFront(const T& value) {
	if (head == nullptr) {
		head = tail = new dNode<T>(value); // Initialize head and tail
	} else {
		head = new dNode<T>(value, nullptr, head); // Create new head node
		head->next->prev = head; // Update previous pointer of the old head
	}

	count++; // Increment size
}

template <class T>
void dList<T>::insertBack(const T& value) {
	if (head == nullptr) {
		head = tail = new dNode<T>(value); // Initialize head and tail
	} else {
		tail = new dNode<T>(value, tail); // Create new tail node
		tail->prev->next = tail; // Update next pointer of the old tail
	}

	count++; // Increment size
}

template <class T>
int dList<T>::getSize() const {
	return count; // Return the number of elements
}

#pragma once

// Forward declaration of the doubly linked list class
template <class T>
class dList;

template <class T>
class dNode {
	friend class dList<T>;

private:
	// Data stored in the node
	T data;
	dNode *previous, *nextNode;

	// Constructor to initialize node with data and optional pointers to previous and next nodes
	dNode(const T& value, dNode* prevNode = nullptr, dNode* nextNodePtr = nullptr) :
		data(value),
		previous(prevNode),
		nextNode(nextNodePtr)
	{}

public:
	// Destructor to recursively delete the next node in the list
	~dNode() {
		if (nextNode != nullptr) {
			delete nextNode;
		}
	}
};

