		void clearError();

		// Checks if the date object is in a valid state
		bool isValid() const;

		// Adds a specified number of days to the date
		Date& operator+=(int days);

		// Increments the date by one day (prefix)
		Date& operator++();

		// Increments the date by one day (postfix)
		Date operator++(int);

		// Returns a new date that is the result of adding days to the current date
		Date operator+(int days) const;

		// Compares if two date objects represent the same date
		bool operator==(const Date& rhs) const;

		// Compares if two date objects represent different dates
		bool operator!=(const Date& rhs) const;

		// Checks if the current date is before the date in rhs
		bool operator<(const Date& rhs) const;

		// Checks if the current date is after the date in rhs
		bool operator>(const Date& rhs) const;

		// Checks if the current date is before or equal to the date in rhs
		bool operator<=(const Date& rhs) const;

		// Checks if the current date is after or equal to the date in rhs
		bool operator>=(const Date& rhs) const;

		// Reads a date from an input stream in the format YYYY?MM?DD
		Date read(std::istream& is);

		// Writes the date to an output stream in the format YYYY/MM/DD
		std::ostream& write(std::ostream& os) const;
	};

