#ifndef COLLEGE_H
#define COLLEGE_H

#include <iostream>
#include <vector>
#include "Placement.h"

using namespace std;

class College {
    string name;
    string location;
    vector<string> companies;
    vector<Placement> placementRecords;
    int studentCount;
    int serialNumber = 1;

public:
    College(string collegeName, string collegeLocation, int totalStudents) {
        name = collegeName;
        location = collegeLocation;
        studentCount = totalStudents;
        initializeCompanies();
        initializePlacements();
    }

    // Initializes the list of companies that have visited the college
    void initializeCompanies() {
        companies = {"Google", "RedHat", "Uber", "IBM", "Flipkart"};
    }

    // Initializes the placement records with predefined data
    void initializePlacements() {
        placementRecords = {
            Placement(2018, 10, 42, 1950, 2000),
            Placement(2019, 11, 50, 1700, 1800),
            Placement(2020, 10, 42, 1900, 2200)
        };
    }

    string getName() const {
        return name;
    }

    void setName(string collegeName) {
        name = collegeName;
    }

    void setLocation(string collegeLocation) {
        location = collegeLocation;
    }

    void setStudentCount(int totalStudents) {
        studentCount = totalStudents;
    }

    int getStudentCount() const {
        return studentCount;
    }

    string getLocation() const {
        return location;
    }

    // Adds new placement statistics based on user input
    void addPlacementStatistics() {
        double averageSalary, highestPackage;
        int year, totalPlaced, totalAppeared;

        cout << "Enter the year for which you want to enter the placement stats: ";
        cin >> year;
        cout << "Enter the average salary of all the students placed in year " << year << ": ";
        cin >> averageSalary;
        cout << "Enter the highest package offered in the year " << year << ": ";
        cin >> highestPackage;
        cout << "Enter the total number of candidates placed in year " << year << ": ";
        cin >> totalPlaced;
        cout << "Enter the total number of candidates appeared in year " << year << ": ";
        cin >> totalAppeared;

        Placement newPlacement(year, averageSalary, highestPackage, totalPlaced, totalAppeared);
        placementRecords.push_back(newPlacement);
    }

    // Deletes placement statistics for a specified year
    void deletePlacementStatistics() {
        int year;
        cout << "Enter the year for which you want to delete the placement statistics: ";
        cin >> year;

        auto it = remove_if(placementRecords.begin(), placementRecords.end(),
                            [year](const Placement& placement) { return placement.year == year; });
        if (it != placementRecords.end()) {
            placementRecords.erase(it, placementRecords.end());
            cout << "Deleted the placement stat of the year " << year << " successfully." << endl;
        } else {
            cout << "No placement statistics found for the year " << year << "." << endl;
        }
    }

    // Displays placement statistics for a specified year
    void showPlacementStatistics() const {
        int year;
        cout << "Enter the year for which you want to see the placement stat: ";
        cin >> year;

        cout << "\n\n\t\t=======================================================================================================\n\n";
        cout << "\t\t\t\t\t\t\t || PLACEMENT STAT ||\n\n";
        cout << "\t\t=======================================================================================================\n\n";

        for (const auto& placement : placementRecords) {
            if (placement.year == year) {
                cout << "\t\tAverage Salary" << "    |    ";
                cout << "Highest Package Offered" << "    |    ";
                cout << "Candidates Appeared" << "    |";
                cout << "\tCandidates Placed" << "     |\n\n";
                cout << "\t\t-------------------------------------------------------------------------------------------------------\n\n";
                cout << "\t\t" << placement.average << " LPA\t\t\t   " << placement.highest << " LPA\t\t\t "
                     << placement.totalAppeared << "\t\t\t    " << placement.totalPlaced << endl;
                return;
            }
        }
        cout << "No placement statistics found for the year " << year << "." << endl;
    }

    // Adds a new company to the list of companies that have visited the college
    void addCompany() {
        string newCompany;
        cout << "Enter the company name: ";
        cin >> newCompany;
        companies.push_back(newCompany);
        cout << "Successfully added new company to records." << endl;
    }

    // Displays the list of companies that have visited the college
    void showCompanies() const {
        cout << "\t\t\t\t\t\t\t|| LIST OF COMPANIES ||\n\n";
        cout << "\t\t\t-------------------------------------------------------------------------------------------------------\n\n";

        int index = 1;
        for (const auto& company : companies) {
            cout << "\t\t\t" << index++ << ". " << company << endl;
        }
    }

    // Sorts the placement records by year
    void displayPlacementHistory() const {
        cout << endl << "\t\t\t\t\t      || PLACEMENT HISTORY ||\n" << endl;
        cout << "\t======================================================================================================================\n\n";
        cout << "\t|  YEAR" << "    |    ";
        cout << "Average Salary" << "    |    ";
        cout << "Highest Package Offered" << "    |    ";
        cout << "Candidates Appeared" << "    |";
        cout << "\tCandidates Placed" << "     |\n\n";
        cout << "\t-----------------------------------------------------------------------------------------------------------------------\n\n";

        for (auto it = placementRecords.rbegin(); it != placementRecords.rend(); ++it) {
            cout << "\t   " << it->year << "\t\t  " << it->average << " LPA\t\t\t  "
                 << it->highest << " LPA\t\t\t  " << it->totalAppeared << "\t\t\t    " << it->totalPlaced << endl;
        }
        cout << endl;
    }

    friend ostream& operator<<(ostream& out, const College& college);
};

ostream& operator<<(ostream& out, const College& college) {
    out << "\t\t\t\t\t   || COLLEGE DETAILS ||\n";
    out << "  Serial No.: " << college.serialNumber++ << endl;
    out << "  College Name: " << college.name << endl;
    out << "  Location: " << college.location << endl;
    out << "  Companies that visited: " << college.name << ":\n";

    int serialNo = 1;
    for (const auto& company : college.companies) {
        out << "   " << serialNo++ << ". " << company << endl;
    }
    return out;
}

