class Student {

private:
    string rollNumber;
    string fullName;
    int age;
    string collegeName;
    string courseName;
    int courseDuration;
    double cgpa;
    int enrolledProgramCount;
    vector<Program*> enrolledPrograms;

public:
    // Constructor to initialize student details
    Student(string rollNum, string name, int studentAge, string college, string course, int duration, double gpa, int programCount, Program *program) {
        rollNumber = rollNum;
        fullName = name;
        age = studentAge;
        collegeName = college;
        courseName = course;
        courseDuration = duration;
        cgpa = gpa;
        enrolledProgramCount = programCount;
        enrolledPrograms.push_back(program);
    }

    // Setters for student details
    void setRollNumber(string rollNum) {
        rollNumber = rollNum;
    }
    void setFullName(string name) {
        fullName = name;
    }
    void setCollegeName(string college) {
        collegeName = college;
    }
    void setCourseName(string course) {
        courseName = course;
    }
    void setAge(int studentAge) {
        age = studentAge;
    }
    void setCourseDuration(int duration) {
        courseDuration = duration;
    }
    void setEnrolledProgramCount(int programCount) {
        enrolledProgramCount = programCount;
    }
    void setCgpa(double gpa) {
        cgpa = gpa;
    }

    // Getters for student details
    string getRollNumber() const {
        return rollNumber;
    }
    string getFullName() const {
        return fullName;
    }
    string getCollegeName() const {
        return collegeName;
    }
    string getCourseName() const {
        return courseName;
    }
    int getAge() const {
        return age;
    }
    int getCourseDuration() const {
        return courseDuration;
    }
    int getEnrolledProgramCount() const {
        return enrolledProgramCount;
    }
    double getCgpa() const {
        return cgpa;
    }

    // Method to add programs to the student's enrollment
    void addPrograms() {
        bool continueAdding = true;
        string programName, programType; 
        int totalSeats, duration;
        char choice;

        cout << "  Enter the program details you want to add:" << endl;

        while (continueAdding) {
            cout << "  Enter the program name: ";
            cin >> programName;
            cout << "  Enter the program type: ";
            cin >> programType;
            cout << "  Enter total number of seats available: ";
            cin >> totalSeats;
            cout << "  Enter the duration of the program: ";
            cin >> duration;
            cout << "  Do you want to add more programs? (y/n): ";
            cin >> choice;

            Program *newProgram = new Program(programName, programType, totalSeats, duration);
            enrolledPrograms.push_back(newProgram);

            if (choice == 'n') {
                continueAdding = false;
            }
        }
    }

    // Method to display the programs the student is enrolled in
    void showPrograms() const {
        cout << endl << "\t\t\t\t\t\t|| PROGRAM DETAILS ||\n" << endl;
        cout << "\t\t=================================================================================================" << endl << endl;
        cout << "\t\t|   Program Name\t|\tProgram Type\t|\tTotal Seats\t|    Program Duration   |" << endl;
        cout << "\t\t-------------------------------------------------------------------------------------------------" << endl;

        for (const auto& program : enrolledPrograms) {
            cout << "\t\t       " << program->name << "\t\t\t      " << program->type << "\t\t  ";
            cout << program->seats << "\t\t\t    ";
            cout << program->duration << endl;
        }
    }

    friend void deleteStudent(vector<Student> &students, const string &roll);
    friend ostream &operator<<(ostream &out, const Student &student);
    friend bool operator>(const Student &student1, const Student &student2);
    friend void displayStudents(const vector<Student> &students);
};

ostream &operator<<(ostream &out, const Student &student) {
    out << "\t\t\t==================================================================" << endl;
    out << "\t\t\t\t\t\t|| STUDENT DETAILS ||" << endl << endl;
    out << "  Name: " << student.fullName << endl;
    out << "  Roll Number: " << student.rollNumber << endl;
    out << "  College: " << student.collegeName << endl;
    out << "  Course: " << student.courseName << endl;
    out << "  Course Duration: " << student.courseDuration << endl;
    out << "  CGPA: " << student.cgpa << endl;
    out << "  Number of programs enrolled: " << student.enrolledProgramCount << endl;
    return out;
}

bool operator>(const Student &student1, const Student &student2) {
    // Compare based on CGPA
    if (student1.cgpa > student2.cgpa) {
        return true;
    } else if (student1.cgpa < student2.cgpa) {
        return false;
    }

    // Compare based on number of programs enrolled
    if (student1.enrolledProgramCount > student2.enrolledProgramCount) {
        return true;
    } else if (student1.enrolledProgramCount < student2.enrolledProgramCount) {
        return false;
    }

    // Compare based on course duration
    if (student1.courseDuration < student2.courseDuration) {
        return true;
    } else if (student1.courseDuration > student2.courseDuration) {
        return false;
    }

    // Compare based on age
    return student1.age > student2.age;
}

void deleteStudent(vector<Student> &students, const string &roll) {
    for (size_t i = 0; i < students.size(); i++) {
        if (students[i].rollNumber == roll) {
            students.erase(students.begin() + i);
            cout << "  Deleted the records of student successfully" << endl;
            return;
        }
    }
}

