// Function to issue a book to a student
void issueBook() {
    char studentAdmissionNumber[6], bookNumber[6];
    bool studentFound = false, bookFound = false;
    cout << "\nBOOK ISSUE...";
    cout << "\nEnter The student's admission number: ";
    cin >> studentAdmissionNumber;
    fileStream.open("student.dat", ios::in | ios::out);
    fileStream1.open("book.dat", ios::in | ios::out);
    while (fileStream.read(reinterpret_cast<char*>(&studentInstance), sizeof(Student)) && !studentFound) {
        if (strcasecmp(studentInstance.getAdmissionNumber(), studentAdmissionNumber) == 0) {
            studentFound = true;
            if (studentInstance.getToken() == 0) {
                cout << "\nEnter the book number: ";
                cin >> bookNumber;
                while (fileStream1.read(reinterpret_cast<char*>(&bookInstance), sizeof(Book)) && !bookFound) {
                    if (strcasecmp(bookInstance.getBookNumber(), bookNumber) == 0) {
                        bookInstance.showBook();
                        bookFound = true;
                        studentInstance.issueBook();
                        studentInstance.setIssuedBookNumber(bookInstance.getBookNumber());
                        int position = -1 * sizeof(studentInstance);
                        fileStream.seekp(position, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&studentInstance), sizeof(Student));
                        cout << "\nBook issued successfully. Please note: Write the current date on the backside of your book and submit within 15 days. Fine Rs. 1 for each day after 15 days.";
                    }
                }
                if (!bookFound) {
                    cout << "Book number does not exist.";
                }
            } else {
                cout << "You have not returned the last book.";
            }
        }
    }
    if (!studentFound) {
        cout << "Student record does not exist.";
    }
    cin.get();
    fileStream.close();
    fileStream1.close();
}

// Function to deposit a book from a student
void depositBook() {
    char studentAdmissionNumber[6], bookNumber[6];
    bool studentFound = false, bookFound = false;
    int days, fine;
    cout << "\nBOOK DEPOSIT...";
    cout << "\nEnter The student’s admission number: ";
    cin >> studentAdmissionNumber;
    fileStream.open("student.dat", ios::in | ios::out);
    fileStream1.open("book.dat", ios::in | ios::out);
    while (fileStream.read(reinterpret_cast<char*>(&studentInstance), sizeof(Student)) && !studentFound) {
        if (strcasecmp(studentInstance.getAdmissionNumber(), studentAdmissionNumber) == 0) {
            studentFound = true;
            if (studentInstance.getToken() == 1) {
                while (fileStream1.read(reinterpret_cast<char*>(&bookInstance), sizeof(Book)) && !bookFound) {
                    if (strcasecmp(bookInstance.getBookNumber(), studentInstance.getIssuedBookNumber()) == 0) {
                        bookInstance.showBook();
                        bookFound = true;
                        cout << "\nBook deposited in number of days: ";
                        cin >> days;
                        if (days > 15) {
                            fine = (days - 15) * 1;
                            cout << "\nFine to be deposited: Rs. " << fine;
                        }
                        studentInstance.returnBook();
                        int position = -1 * sizeof(studentInstance);
                        fileStream.seekp(position, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&studentInstance), sizeof(Student));
                        cout << "\nBook deposited successfully.";
                    }
                }
                if (!bookFound) {
                    cout << "Book number does not exist.";
                }
            } else {
                cout << "No book is issued. Please check!";
            }
        }
    }
    if (!studentFound) {
        cout << "Student record does not exist.";
    }
    cin.get();
    fileStream.close();
    fileStream1.close();
}

