    ifstream infile("record.bank", ios::binary);
    if (!infile) {
        cout << "\nError in opening! File Not Found!!" << endl;
        return;
    }

    infile.seekg(0, ios::end);
    int totalRecords = infile.tellg() / sizeof(*this);
    cout << "\n There are " << totalRecords << " records in the file";
    cout << "\n Enter Record Number to Delete: ";
    cin >> recordNumber;

    fstream tempFile("tmpfile.bank", ios::out | ios::binary);
    infile.seekg(0);
    for (int i = 0; i < totalRecords; i++) {
        infile.read(reinterpret_cast<char*>(this), sizeof(*this));
        if (i == (recordNumber - 1)) {
            continue; // Skip the record to be deleted
        }
        tempFile.write(reinterpret_cast<char*>(this), sizeof(*this));
    }

    infile.close();
    tempFile.close();
    remove("record.bank");
    rename("tmpfile.bank", "record.bank");
}

