class Point
{
private:
    int xCoordinate, yCoordinate;

    // Tính bình phương của một số
    int calculateSquare(int value) {
        return value * value;
    }

public:
    // Khởi tạo tọa độ điểm
    Point(int x, int y) : xCoordinate(x), yCoordinate(y) {}

    // Tính khoảng cách Euclid đến điểm khác
    double calculateDistance(const Point& otherPoint) const {
        int deltaX = otherPoint.xCoordinate - xCoordinate;
        int deltaY = otherPoint.yCoordinate - yCoordinate;
        return sqrt(calculateSquare(deltaX) + calculateSquare(deltaY));
    }
};

class Time {

private:
    int hours, minutes, seconds;

public:
    // Khởi tạo thời gian với giá trị mặc định là 00:00:00
    Time() : hours(0), minutes(0), seconds(0) {}

    // Khởi tạo thời gian với giá trị cụ thể
    Time(int hours, int minutes, int seconds) {
        this->hours = hours;
        this->minutes = minutes; 
        this->seconds = seconds;
    }

    // Hiển thị thời gian theo định dạng HH:MM:SS
    void Display() const {
        cout << hours << ":" << minutes << ":" << seconds << endl; 
    }

    // Trả về giờ
    int getHours() const { return this->hours; }

    // Trả về phút
    int getMinutes() const { return this->minutes; }

    // Trả về giây
    int getSeconds() const { return this->seconds; }

    // Cộng hai đối tượng Time và lưu kết quả vào đối tượng hiện tại
    void Add(const Time& t1, const Time& t2) {
        int totalHours = 0, totalMinutes = 0, totalSeconds = 0;

        // Tính tổng giây và chuyển đổi thành phút nếu cần
        totalMinutes += (t1.seconds + t2.seconds) / 60;
        totalSeconds += (t1.seconds + t2.seconds) % 60;

        // Tính tổng phút và chuyển đổi thành giờ nếu cần
        totalMinutes += (t1.minutes + t2.minutes) / 60;
        totalMinutes += (t1.minutes + t2.minutes) % 60;

        // Tính tổng giờ
        totalHours += t1.hours + t2.hours;

        // Cập nhật thời gian hiện tại
        this->hours = totalHours;
        this->minutes = totalMinutes;
        this->seconds = totalSeconds;
    }
};

