class Checker {
private:
    string testFileName;
    string compilerCommand;
    string currentWorkingDirectory;

    // Retrieves the current working directory
    std::string getCurrentWorkingDirectory() {
        char buffer[1000];
        return (getcwd(buffer, sizeof(buffer)) ? std::string(buffer) : std::string(""));
    }

public:
    explicit Checker(string test) {
        testFileName = move(test);
        currentWorkingDirectory = getCurrentWorkingDirectory();
        compilerCommand = "g++";
    }

    // Compiles the test file and returns the compilation result
    Compilation compile() {
        std::string command = compilerCommand + " " + currentWorkingDirectory + "/" + testFileName + " -o " + currentWorkingDirectory + "/test";
        int compilationResult = system(command.c_str());
        return (compilationResult) ? Compilation::FAILED : Compilation::SUCCESS;
    }

    // Executes the compiled test and returns the test result
    Test test() {
        std::string command = "./test";
        int executionResult = system(command.c_str());
        system("rm ./test"); // Clean up the test binary after execution
        return (executionResult == 0) ? Test::SUCCESS : Test::FAILED;
    }
};

