template <typename T>
std::string convertToString(const T& value) {
    std::ostringstream stream;
    stream << value;
    return stream.str();
}

bool doesPathExist(const std::string &path) {
    struct stat buffer;
    return (stat(path.c_str(), &buffer) == 0);
}

class Exercise {
private:
    int startNumber;
    int endNumber;
    std::string exerciseFolderTemplate;

    void createExerciseDirectory() {
        if (!doesPathExist("exercises/")) 
            system("mkdir exercises/");

        chdir("exercises/");
        std::string command = "mkdir " + exerciseFolderTemplate + convertToString(startNumber);

        if (system(command.c_str()) == 0) {
            std::string fileCreationCommands =
                "cd " + exerciseFolderTemplate + convertToString(startNumber) + "/ &&"
                "echo '#include \"solution.cpp\"' > tester.cpp &&"
                "echo '# Exercise " + convertToString(startNumber) + "' > README.md &&"
                "touch solution.cpp && cd ..";
            system(fileCreationCommands.c_str());

            std::cout << exerciseFolderTemplate << startNumber << " created!" << std::endl;
            std::cout << "\tCreated solution.cpp" << std::endl
                      << "\tCreated tester.cpp" << std::endl
                      << "\tCreated README.md" << std::endl;
        }
    }

public:
    Exercise() {
        exerciseFolderTemplate = "exercise-";
        startNumber = endNumber = calculateNextExerciseNumber("exercises/");
    }

    Exercise(int number) {
        startNumber = endNumber = number;
    }

    Exercise(int from, int to) {
        if (from > to)
            std::swap(from, to);
        startNumber = from;
        endNumber = to;
    }

    bool isExerciseDirectory(const std::string &directoryName) {
        if (directoryName.size() <= exerciseFolderTemplate.size()) return false;
        for (size_t i = 0; i < exerciseFolderTemplate.size(); i++) {
            if (exerciseFolderTemplate[i] != directoryName[i]) return false;
        }
        return true;
    }

    int calculateNextExerciseNumber(const char *path) {
        struct dirent *entry;
        DIR *directory = opendir(path);

        if (directory == NULL) {
            return 1;
        }

        int maxExerciseNumber = 0;
        while ((entry = readdir(directory)) != NULL) {
            std::string fileName(entry->d_name);
            if (isExerciseDirectory(fileName)) {
                std::string exerciseNumber = fileName.substr(exerciseFolderTemplate.size(), fileName.size());
                maxExerciseNumber = std::max(maxExerciseNumber, atoi(exerciseNumber.c_str()));
            }
        }
        closedir(directory);
        return maxExerciseNumber + 1;
    }

    void createExercises() {
        while (startNumber <= endNumber) {
            createExerciseDirectory();
            startNumber++;
        }
    }
};

