// Represents a node in the linked list, holding share information.
class ShareNode {
    friend class StockAccount;
    friend class ShareList;

public:
    unsigned long shareCount;  // Number of shares
    double totalValue;         // Total value of shares (Price per share * Number of shares)
    string shareSymbol;        // Symbol of the share
    ShareNode* next;           // Pointer to the next node

    // Constructor to initialize a share node with its details.
    ShareNode(string symbol, unsigned long count, double pricePerShare) {
        shareSymbol = symbol;
        shareCount = count;
        totalValue = pricePerShare * count;
        next = nullptr;
    }
};

