using namespace std;

// Class representing a bank account
class BankAccount {
private:
    int accountNumber;
    char accountHolderName[30];
    long accountBalance;

public:
    // Initializes a new bank account with user input
    void OpenAccount() {
        cout << "Enter Account Number: ";
        cin >> accountNumber;
        cout << "Enter Name: ";
        cin >> accountHolderName;
        cout << "Enter Balance: ";
        cin >> accountBalance;
    }

    // Displays the account information
    void ShowAccount() {
        cout << "Account Number: " << accountNumber << endl;
        cout << "Name: " << accountHolderName << endl;
        cout << "Balance: " << accountBalance << endl;
    }

    // Deposits an amount into the account
    void Deposit() {
        long amount;
        cout << "Enter Amount You Want To Deposit: ";
        cin >> amount;
        accountBalance += amount;
    }

    // Withdraws an amount from the account if sufficient balance exists
    void Withdrawal() {
        long amount;
        cout << "Enter Amount You Want To Withdraw: ";
        cin >> amount;
        if (amount <= accountBalance) {
            accountBalance -= amount;
        } else {
            cout << "You Don't Have Enough Balance!" << endl;
        }
    }

    // Searches for an account by account number and displays it if found
    int Search(int accountNum) {
        if (accountNumber == accountNum) {
            ShowAccount();
            return 1;
        }
        return 0;
    }
};

// Main function to manage bank accounts
int main() {
    BankAccount accounts[3];
    int found = 0, accountNum, choice, i;

    // Open accounts for three users
    for (i = 0; i < 3; i++) {
        accounts[i].OpenAccount();
    }

    do {
        // Display menu options
        cout << "\n\n 1: Display All \n 2: Check Balance \n 3: Deposit Amount \n 4: Withdraw Amount \n 5: Exit" << endl;

        // Get user choice
        cout << "Please input your choice (1-5): ";
        cin >> choice;

        switch (choice) {
            case 1: // Displaying all account information
                for (i = 0; i < 3; i++) {
                    accounts[i].ShowAccount();
                }
                break;

            case 2: // Searching for an account to check balance
                cout << "Account Number? ";
                cin >> accountNum;
                for (i = 0; i < 3; i++) {
                    found = accounts[i].Search(accountNum);
                    if (found) break;
                }
                if (!found) {
                    cout << "Record Not Found" << endl;
                }
                break;

            case 3: // Deposit operation
                cout << "Enter Account Number To Deposit Amount: ";
                cin >> accountNum;
                for (i = 0; i < 3; i++) {
                    found = accounts[i].Search(accountNum);
                    if (found) {
                        accounts[i].Deposit();
                        break;
                    }
                }
                if (!found) {
                    cout << "Record Not Found" << endl;
                }
                break;

            case 4: // Withdraw operation
                cout << "Account Number To Withdraw Amount? ";
                cin >> accountNum;
                for (i = 0; i < 3; i++) {
                    found = accounts[i].Search(accountNum);
                    if (found) {
                        accounts[i].Withdrawal();
                        break;
                    }
                }
                if (!found) {
                    cout << "Record Not Found" << endl;
                }
                break;

            case 5: // Exit message
                cout << "Have a nice day" << endl;
                break;

            default:
                cout << "Wrong Option" << endl;
        }
    } while (choice != 5);

    return 0;
}

