Attribute::Attribute(int value, bool primary, const std::string& attrName) 
    : int_val(value), is_primary(primary), name(attrName), length(-1) {}

Attribute::Attribute(const std::string& value, bool primary, const std::string& attrName, int attrLength) 
    : string_val(value), is_primary(primary), name(attrName), length(attrLength) {}

bool Attribute::operator==(const Attribute& other) const {
    // So sánh các thuộc tính của hai đối tượng Attribute
    if (this->is_Int() && 
        this->int_val == other.int_val && 
        this->is_primary == other.is_primary && 
        this->name == other.name) {
        return true;
    }

    if (this->is_Varchar() && 
        this->string_val == other.string_val && 
        this->is_primary == other.is_primary && 
        this->name == other.name && 
        this->length == other.length) {
        return true;
    }

    return false;
}

bool Attribute::operator!=(const Attribute& other) const {
    // Kiểm tra sự khác biệt giữa hai đối tượng Attribute
    return !(*this == other);
}

void Attribute::show() const {
    // Hiển thị giá trị của thuộc tính
    if (this->is_Int()) {
        std::cout << int_val;
    } else {
        std::cout << string_val;
    }
}

bool Attribute::is_Primary() const {
    // Kiểm tra xem thuộc tính có phải là khóa chính không
    return is_primary;
}

bool Attribute::is_Int() const {
    // Xác định xem thuộc tính có kiểu số nguyên hay không
    return (this->length == -1);
}

bool Attribute::is_Varchar() const {
    // Xác định xem thuộc tính có kiểu chuỗi không
    return !this->is_Int();
}

std::string Attribute::get_Name() const {
    // Trả về tên của thuộc tính
    return name;
}

