// Base class for entities that hold function pointers.
template <typename Return_Type, typename... Tparams>
entity_base<Return_Type, Tparams...>::~entity_base() {}

// Entity class for free functions.
template <typename Return_Type, typename... Tparams>
entity<Return_Type (*)(Tparams...)>::entity(function func) : function_(func) {}

template <typename Return_Type, typename... Tparams>
entity<Return_Type (*)(Tparams...)>::entity() : function_(nullptr) {}

template <typename Return_Type, typename... Tparams>
entity<Return_Type (*)(Tparams...)>::~entity() { function_ = nullptr; }

// Register a new function to the entity.
template <typename Return_Type, typename... Tparams>
inline void entity<Return_Type (*)(Tparams...)>::register_entity(function func) {
    function_ = func;
}

// Retrieve the destination slot of the entity.
template <typename Return_Type, typename... Tparams>
inline Slot* entity<Return_Type (*)(Tparams...)>::getdest() const {
    return reinterpret_cast<Slot*>(function_);
}

// Get the member function pointer (not applicable for free functions).
template <typename Return_Type, typename... Tparams>
inline void* entity<Return_Type (*)(Tparams...)>::getmemfunPtr() const {
    return nullptr;
}

// Emit the signal with the provided parameters.
template <typename Return_Type, typename... Tparams>
Return_Type entity<Return_Type (*)(Tparams...)>::emitSignal(Tparams const&... params) {
    return function_(params...);
}

// Entity class for member functions.
template <typename Class_Type, typename Return_Type, typename... Tparams>
entity<Return_Type (Class_Type::*)(Tparams...)>::entity(Class_Type* class_ptr, function func)
    : class_(class_ptr), function_(func) {}

template <typename Class_Type, typename Return_Type, typename... Tparams>
entity<Return_Type (Class_Type::*)(Tparams...)>::entity() : class_(nullptr), function_(nullptr) {}

template <typename Class_Type, typename Return_Type, typename... Tparams>
entity<Return_Type (Class_Type::*)(Tparams...)>::~entity() {
    class_ = nullptr;
    function_ = nullptr;
}

// Register a new member function to the entity.
template <typename Class_Type, typename Return_Type, typename... Tparams>
inline void entity<Return_Type (Class_Type::*)(Tparams...)>::register_entity(Class_Type* class_ptr, function func) {
    class_ = class_ptr;
    function_ = func;
}

// Retrieve the destination class of the entity.
template <typename Class_Type, typename Return_Type, typename... Tparams>
inline Slot* entity<Return_Type (Class_Type::*)(Tparams...)>::getdest() const {
    return class_;
}

// Get the member function pointer.
template <typename Class_Type, typename Return_Type, typename... Tparams>
inline void* entity<Return_Type (Class_Type::*)(Tparams...)>::getmemfunPtr() const {
    return reinterpret_cast<void*>(function_);
}

// Emit the signal for the member function.
template <typename Class_Type, typename Return_Type, typename... Tparams>
Return_Type entity<Return_Type (Class_Type::*)(Tparams...)>::emitSignal(Tparams const&... params) {
    return (class_->*function_)(params...);
}

// Base class for signals.
template <typename Return_Type, typename... Tparams>
Signal_base<Return_Type, Tparams...>::~Signal_base() {
    disconnect_all();
}

// Disconnect all connected slots and functions.
template <typename Return_Type, typename... Tparams>
void Signal_base<Return_Type, Tparams...>::disconnect_all() {
    auto it = m_connected_slots.begin();
    auto itEnd = m_connected_slots.end();

    while (it != itEnd) {
        if ((*it)->getdest()) {
            (*it)->getdest()->signal_disconnect(this);
        }
        delete *it;
        ++it;
    }
    m_connected_slots.clear();

    it = Signal_base<Return_Type, Tparams...>::m_connected_funptr.begin();
    itEnd = Signal_base<Return_Type, Tparams...>::m_connected_funptr.end();

    while (it != itEnd) {
        delete *it;
        it = m_connected_funptr.erase(it);
    }
}

// Disconnect a specific slot from the signal.
template <typename Return_Type, typename... Tparams>
void Signal_base<Return_Type, Tparams...>::disconnect(Slot* slot) {
    auto it = m_connected_slots.begin();
    auto itEnd = m_connected_slots.end();

    while (it != itEnd) {
        if ((*it)->getdest() == slot) {
            delete *it;
            it = m_connected_slots.erase(it);
            slot->signal_disconnect(this);
        } else {
            ++it;
        }
    }
}

// Disconnect a specific function pointer from the signal.
template <typename Return_Type, typename... Tparams>
template <typename R, typename... T>
void Signal_base<Return_Type, Tparams...>::disconnect(R (*function)(T...)) {
    auto it = m_connected_funptr.begin();
    auto itEnd = m_connected_funptr.end();

    while (it != itEnd) {
        if (reinterpret_cast<Slot*>(function) == (*it)->getdest()) {
            m_connected_funptr.erase(it);
            return;
        }
        ++it;
    }
}

// Disconnect a specific slot from the signal.
template <typename Return_Type, typename... Tparams>
void Signal_base<Return_Type, Tparams...>::slot_disconnect(Slot* slot) {
    auto it = m_connected_slots.begin();
    auto itEnd = m_connected_slots.end();

    while (it != itEnd) {
        if ((*it)->getdest() == slot) {
            delete *it;
            it = m_connected_slots.erase(it);
        } else {
            ++it;
        }
    }
}

// Slot class implementation.
Slot::~Slot() {
    disconnect_all();
}

// Disconnect all signals associated with the slot.
void Slot::disconnect_all() {
    const_iterator it = m_signal.begin();
    const_iterator itEnd = m_signal.end();

    while (it != itEnd) {
        (*it)->slot_disconnect(this);
        ++it;
    }
    m_signal.clear();
}

// Connect the slot to a signal.
void Slot::signal_connect(_Signal_base* signal) {
    m_signal.insert(signal);
}

// Disconnect the slot from a signal.
void Slot::signal_disconnect(_Signal_base* signal) {
    m_signal.erase(signal);
}

// Signal class implementation.
template <typename Return_Type, typename... Tparams>
template <typename Class_Type>
connect_result Signal<Return_Type, Tparams...>::connect(Class_Type* class_ptr, Return_Type (Class_Type::*member_function)(Tparams...)) {
    auto memfun_entity = new entity<Return_Type (Class_Type::*)(Tparams...)>(class_ptr, member_function);
    Signal_base<Return_Type, Tparams...>::m_connected_slots.push_back(memfun_entity);
    class_ptr->signal_connect(this);
    return SUCCESS;
}

// Connect a free function to the signal.
template <typename Return_Type, typename... Tparams>
connect_result Signal<Return_Type, Tparams...>::connect(Return_Type (*function)(Tparams...)) {
    auto function_entity = new entity<Return_Type (*)(Tparams...)>(function);
    Signal_base<Return_Type, Tparams...>::m_connected_funptr.push_back(function_entity);
    return SUCCESS;
}

// Emit the signal and return the results.
template <typename Return_Type, typename... Tparams>
typename Signal<Return_Type, Tparams...>::Rv_Vector_Set_Sp Signal<Return_Type, Tparams...>::operator()(Tparams... params) {
    auto it = Signal_base<Return_Type, Tparams...>::m_connected_slots.begin();
    auto itEnd = Signal_base<Return_Type, Tparams...>::m_connected_slots.end();

    std::vector<std::shared_ptr<rv_set<Return_Type>>> return_values;
    while (it != itEnd) {
        auto rv_set_ptr = std::make_shared<rv_set<Return_Type>>();
        rv_set_ptr->function_ = (*it)->getmemfunPtr();
        rv_set_ptr->class_ = (*it)->getdest();
        rv_set_ptr->value = (*it)->emitSignal(params...);
        return_values.push_back(rv_set_ptr);
        ++it;
    }

    it = Signal_base<Return_Type, Tparams...>::m_connected_funptr.begin();
    itEnd = Signal_base<Return_Type, Tparams...>::m_connected_funptr.end();

    while (it != itEnd) {
        auto rv_set_ptr = std::make_shared<rv_set<Return_Type>>();
        rv_set_ptr->function_ = (*it)->getdest();
        rv_set_ptr->class_ = nullptr;
        rv_set_ptr->value = (*it)->emitSignal(params...);
        return_values.push_back(rv_set_ptr);
        ++it;
    }

    return return_values;
}

