#ifndef __ITERATOR_H__
#define __ITERATOR_H__

namespace CT {

    // Class representing a forward iterator for character arrays.
    class Iterator {
    private:
        char* currentPosition;

    public:
        Iterator(char* initialLocation = nullptr) : currentPosition(initialLocation) {}

        // Pre-increment operator to advance the iterator.
        Iterator& operator++() {
            ++currentPosition;
            return *this;
        }

        // Post-increment operator to advance the iterator and return the old state.
        Iterator operator++(int) {
            Iterator previousState(*this);
            ++currentPosition;
            return previousState;
        }

        // Pre-decrement operator to move the iterator backward.
        Iterator& operator--() {
            --currentPosition;
            return *this;
        }

        // Post-decrement operator to move the iterator backward and return the old state.
        Iterator operator--(int) {
            Iterator previousState(*this);
            --currentPosition;
            return previousState;
        }

        // Addition operator to move the iterator forward by n positions.
        Iterator operator+(size_t offset) {
            Iterator previousState(*this);
            currentPosition += offset;
            return previousState;
        }

        // Assignment operator for iterator.
        Iterator& operator=(const Iterator& rhs) {
            currentPosition = rhs.currentPosition;
            return *this;
        }

        // Equality comparison operator.
        bool operator==(const Iterator& rhs) const {
            return currentPosition == rhs.currentPosition;
        }

        // Inequality comparison operator.
        bool operator!=(const Iterator& rhs) const {
            return currentPosition != rhs.currentPosition;
        }

        // Dereference operator to access the character at the current position.
        char& operator*() {
            return *currentPosition;
        }

        // Arrow operator to access members of the character at the current position.
        char* operator->() {
            return currentPosition;
        }
    };

    // Class representing a constant forward iterator for character arrays.
    class ConstIterator {
    private:
        char* currentPosition;

    public:
        ConstIterator(char* initialLocation = nullptr) : currentPosition(initialLocation) {}

        // Pre-increment operator to advance the iterator.
        ConstIterator& operator++() {
            ++currentPosition;
            return *this;
        }

        // Post-increment operator to advance the iterator and return the old state.
        ConstIterator operator++(int) {
            ConstIterator previousState(*this);
            ++currentPosition;
            return previousState;
        }

        // Pre-decrement operator to move the iterator backward.
        ConstIterator& operator--() {
            --currentPosition;
            return *this;
        }

        // Post-decrement operator to move the iterator backward and return the old state.
        ConstIterator operator--(int) {
            ConstIterator previousState(*this);
            --currentPosition;
            return previousState;
        }

        // Dereference operator to access the character at the current position.
        const char& operator*() {
            return *currentPosition;
        }

        // Arrow operator to access members of the character at the current position.
        const char* operator->() {
            return currentPosition;
        }

        // Equality comparison operator.
        bool operator==(const ConstIterator& rhs) const {
            return currentPosition == rhs.currentPosition;
        }

        // Inequality comparison operator.
        bool operator!=(const ConstIterator& rhs) const {
            return currentPosition != rhs.currentPosition;
        }
    };

    // Class representing a reverse iterator for character arrays.
    class ReverseIterator {
    private:
        char* currentPosition;

    public:
        ReverseIterator(char* initialLocation = nullptr) : currentPosition(initialLocation) {}

        // Pre-increment operator to move the iterator backward.
        ReverseIterator& operator++() {
            --currentPosition;
            return *this;
        }

        // Post-increment operator to move the iterator backward and return the old state.
        ReverseIterator operator++(int) {
            ReverseIterator previousState(*this);
            --currentPosition;
            return previousState;
        }

        // Pre-decrement operator to advance the iterator forward.
        ReverseIterator& operator--() {
            ++currentPosition;
            return *this;
        }

        // Post-decrement operator to advance the iterator forward and return the old state.
        ReverseIterator operator--(int) {
            ReverseIterator previousState(*this);
            ++currentPosition;
            return previousState;
        }

        // Equality comparison operator.
        bool operator==(const ReverseIterator& rhs) const {
            return currentPosition == rhs.currentPosition;
        }

        // Inequality comparison operator.
        bool operator!=(const ReverseIterator& rhs) const {
            return currentPosition != rhs.currentPosition;
        }

        // Dereference operator to access the character at the current position.
        char& operator*() {
            return *currentPosition;
        }

        // Arrow operator to access members of the character at the current position.
        char* operator->() {
            return currentPosition;
        }
    };

    // Class representing a constant reverse iterator for character arrays.
    class ConstReverseIterator {
    private:
        char* currentPosition;

    public:
        ConstReverseIterator(char* initialLocation = nullptr) : currentPosition(initialLocation) {}

        // Pre-increment operator to move the iterator backward.
        ConstReverseIterator& operator++() {
            --currentPosition;
            return *this;
        }

        // Post-increment operator to move the iterator backward and return the old state.
        ConstReverseIterator operator++(int) {
            ConstReverseIterator previousState(*this);
            --currentPosition;
            return previousState;
        }

        // Pre-decrement operator to advance the iterator forward.
        ConstReverseIterator& operator--() {
            ++currentPosition;
            return *this;
        }

        // Post-decrement operator to advance the iterator forward and return the old state.
        ConstReverseIterator operator--(int) {
            ConstReverseIterator previousState(*this);
            ++currentPosition;
            return previousState;
        }

        // Dereference operator to access the character at the current position.
        const char& operator*() {
            return *currentPosition;
        }

        // Arrow operator to access members of the character at the current position.
        const char* operator->() {
            return currentPosition;
        }

        // Equality comparison operator.
        bool operator==(const ConstReverseIterator& rhs) const {
            return currentPosition == rhs.currentPosition;
        }

        // Inequality comparison operator.
        bool operator!=(const ConstReverseIterator& rhs) const {
            return currentPosition != rhs.currentPosition;
        }
    };
