/* Function to insert a new student record into the file */
void insertStudent() {
    CLS();
    Student newStudent, existingStudent;
    char confirmation;
    bool duplicateFound = false;

    cout << "Enter Details for New Student:\n";
    newStudent.inputDetails();

    fstream studentFile(STUDENT_FILE, ios::in | ios::binary);
    ofstream outputFile;

    if (!studentFile) { // Create new file if it doesn't exist
        outputFile.open(STUDENT_FILE, ios::out | ios::binary);
        outputFile.write(reinterpret_cast<char*>(&newStudent), sizeof(newStudent));
        outputFile.close();
        cout << "Record successfully inserted!\n";
        return;
    }

    while (!studentFile.eof()) {
        studentFile.read(reinterpret_cast<char*>(&existingStudent), sizeof(existingStudent));
        if (studentFile.eof()) {
            break;
        }
        if (newStudent.getRollNo() == existingStudent.getRollNo()) { // Check for duplicate roll number
            cout << "Record with the same Roll No. already exists:\n";
            existingStudent.displayDetails();
            cout << "Insertion Aborted!\n";
            return;
        } else if (strcmpi(newStudent.getName(), existingStudent.getName()) == 0) {
            if (!duplicateFound) {
                cout << "Warning: Record with the same name exists:\n";
            }
            existingStudent.displayDetails();
            cout << '\n';
            duplicateFound = true;
        }
    }

    if (duplicateFound) {
        cout << "Do you still wish to insert the record (Y/N)? ";
        do {
            cin >> confirmation;
            confirmation = toupper(confirmation);
        } while (confirmation != 'Y' && confirmation != 'N');
        if (confirmation == 'N') {
            cout << "Insertion Aborted!\n";
            return;
        }
    }

    outputFile.open(STUDENT_FILE, ios::out | ios::app | ios::binary);
    outputFile.seekp(0, ios::end);
    outputFile.write(reinterpret_cast<char*>(&newStudent), sizeof(newStudent));
    outputFile.close();
    cout << "Record Inserted successfully!\n";
}

/* Function to display all student records */
int displayStudentRecords() {
    CLS();
    Student student;
    int recordsFound = 0;

    fstream studentFile(STUDENT_FILE, ios::in | ios::binary);
    if (!studentFile) {
        cout << "No Records Found!\n";
        return 0;
    }

    while (!studentFile.eof()) {
        studentFile.read(reinterpret_cast<char*>(&student), sizeof(student));
        if (studentFile.eof()) {
            break;
        }
        recordsFound = 1;
        student.displayDetails();
        RULE('-');
    }
    studentFile.close();

    if (!recordsFound) {
        cout << "No Records Found!\n";
    }
    return recordsFound;
}

/* Function to search for a student by roll number */
int searchByRollNo(int option) {
    CLS();
    int rollNumber;
