/* Function to delete a student record */
void deleteStudentRecord() {
    CLS();
    Student student;
    bool recordDeleted = false;
    int rollNumber;
    char confirmation;

    cout << "\nEnter Roll No. to delete: ";
    cin >> rollNumber;

    fstream studentFile(STUDENT_FILE, ios::in | ios::binary);
    fstream tempFile("temp.dat", ios::out | ios::binary);

    while (!studentFile.eof()) {
        studentFile.read(reinterpret_cast<char*>(&student), sizeof(student));
        if (studentFile.eof()) {
            break;
        }
        if (rollNumber == student.getRollNo()) {
            cout << "Record to be deleted:\n\n";
            student.displayDetails();
            cout << "Do you wish to continue? (Y/N): ";
            do {
                cin >> confirmation;
                confirmation = toupper(confirmation);
            } while (confirmation != 'N' && confirmation != 'Y');

            if (confirmation == 'N') {
                cout << "Deletion Aborted!\n";
                studentFile.close();
                tempFile.close();
                remove("temp.dat");
                return;
            }
            recordDeleted = true;
            continue; // Skip writing this record to the temp file
        }
        tempFile.write(reinterpret_cast<char*>(&student), sizeof(student));
    }

    studentFile.close();
    tempFile.close();
    remove(STUDENT_FILE);
    rename("temp.dat", STUDENT_FILE);

    if (recordDeleted) {
        cout << "Record Successfully Deleted!\n";
    } else {
        cout << "No Such Record Exists!\n";
    }
}

