void Library::viewBooks(int flag) {
    int serialNum = 0;
    CLS();
    int category = selectBookCategory(flag);
    CLS();

    const char* fileNames[] = {
        "csBooks.txt", "eceBooks.txt", "elecBooks.txt", "mechBooks.txt", "civilBooks.txt", "yearOneBooks.txt"
    };

    ifstream fin(fileNames[category - 1], ios::in);
    if (!fin) {
        cout << "\n\t\tFile Not Found.";
    } else {
        cout << "\t\t\t\t\t********** LIST OF BOOKS **********\n\n";
        while (fin.getline(book, 100)) {
            fin.getline(author, 100);
            fin.getline(publication, 100);
            fin >> id >> price >> quantity;
            serialNum++;
            cout << "\n\t\t\t##### " << serialNum << " #####\n";
            displayData();
            fin.ignore(); // Ignore the newline character after reading quantity
        }
    }
    fin.close();
    cout << "\n\n\n\t\tPress any key to continue";
    (void)_getch();
    CLS();
    if (flag == 1) {
        studentMenu();
    } else {
        staffMenu();
    }
}

void Library::removeBook() {
    CLS();
    int category = selectBookCategory(2);
    CLS();
    char delBook[100];

    const char* fileNames[] = {
        "csBooks.txt", "eceBooks.txt", "elecBooks.txt", "mechBooks.txt", "civilBooks.txt", "yearOneBooks.txt"
    };

    ifstream fin(fileNames[category - 1], ios::in);
    ofstream fout("tempFile.txt", ios::app);
    if (!fin) {
        cout << "\n\t\tFile Not Found.";
    } else {
        cout << "\n\n\t\t\tEnter Book's Name: ";
        cin.ignore();
        cin.getline(delBook, 100);
        while (fin.getline(book, 100)) {
            fin.getline(author, 100);
            fin.getline(publication, 100);
            fin >> id >> price >> quantity;
            if (strcmp(delBook, book) != 0) {
                fout << book << endl << author << endl << publication << endl << id << endl << price << endl << quantity;
            }
        }
    }
    fout.close();
    fin.close();
    remove(fileNames[category - 1]);
    rename("tempFile.txt", fileNames[category - 1]);

    cout << "\n\n\t\t\tBook Deleted Successfully.";
    cout << "\n\n\t\t\tPress any key to continue";
    (void)_getch();
    modifyBookList();
}

void Library::searchBook(int flag) {
    CLS();
    int category = selectBookCategory(2);
    CLS();
    int choice;
    char bookName[100], bookID[20];
    bool found = false;

    cout << "\t\t\t\t\t********** SEARCH BOOK **********\n\n";
    cout << "\t\t\t\t\t>> Choose any option\n\n";
    cout << "\t\t\t\t\t1. Search by name\n\n";
    cout << "\t\t\t\t\t2. Search by ID\n\n";
    cout << "\t\t\t\t\t3. Go Back\n\n";
    cout << "\t\t\t\t\tEnter choice: ";
    cin >> choice;
    cout << endl << endl;

    const char* fileNames[] = {
        "csBooks.txt", "eceBooks.txt", "elecBooks.txt", "mechBooks.txt", "civilBooks.txt", "yearOneBooks.txt"
    };

    switch (choice) {
        case 1: {
            ifstream fin(fileNames[category - 1], ios::in);
            if (!fin) {
                cout << "\n\t\tFile Not Found.";
            } else {
                cout << "\n\t\tEnter Book's Name: ";
                cin.ignore();
                cin.getline(bookName, 100);
                while (fin.getline(book, 100)) {
                    fin.getline(author, 100);
                    fin.getline(publication, 100);
                    fin >> id >> price >> quantity;
                    if (strcmp(bookName, book) == 0) {
                        cout << "\n\n\t\t##### SEARCH RESULTS #####\n";
                        displayData();
                        found = true;
                    }
                }
                fin.close();
            }
            if (!found) {
                cout << "\n\n\t\t\tBOOK NOT FOUND";
            }
            break;
        }
        case 2: {
            ifstream fin(fileNames[category - 1], ios::in);
            if (!fin) {
                cout << "\n\t\tFile Not Found.";
            } else {
                cout << "\n\t\tEnter Book's ID: ";
                cin.ignore();
                cin >> bookID;
                while (fin.getline(book, 100)) {
                    fin.getline(author, 100);
                    fin.getline(publication, 100);
                    fin >> id >> price >> quantity;
                    if (strcmp(bookID, id) == 0) {
                        cout << "\n\n\t\t##### SEARCH RESULTS #####\n";
                        displayData();
                        found = true;
                    }
                }
                fin.close();
            }
            if (!found) {
                cout << "\n\n\t\t\tBOOK NOT FOUND";
            }
            break;
        }
        case 3:
            CLS();
            if (flag == 1) {
                studentMenu();
            } else {
                staffMenu();
            }
            break;
        default:
            cout << "\n\t\t\t\t\tInvalid choice.\n\n";
            cout << "\n\n\t\t\t\t\tPress any key to enter a valid choice\n\n";
            (void)_getch();
            CLS();
            searchBook(flag);
    }

    cout << "\n\n\n\t\tPress any key to continue";
    (void)_getch();
    if (flag == 1) {
        studentMenu();
    } else {
        staffMenu();
    }
}

