// Class representing a Teacher */
class Teacher {
    int sectionCount;
    int phone;
    string name;
    string sections[10];
    string subject;

public:
    void input();
    void display() const;
    int getPhone() const;
    int getSectionCount() const;
    string getName() const;
    string getSubject() const;
    string getSection(int index) const;
};

void Teacher::input() {
    cout << "\n\t\t\t\t\tEnter teacher name: ";
    cin.ignore();
    getline(cin, name);
    cout << "\n\t\t\t\t\tEnter subject: ";
    getline(cin, subject);
    cout << "\n\t\t\t\t\tEnter the phone number: ";
    cin >> phone;

    do {
        cout << "\n\t\t\t\t\tEnter the number of sections taught: ";
        cin >> sectionCount;
        if (sectionCount <= 0) {
            cout << "\n\t\t\t\t\tSections taught cannot be less than or equal to zero\n";
        }
    } while (sectionCount <= 0);

    cout << "\n\t\t\t\t\tThe section(s) (press enter after giving each section name): ";
    cin.ignore();
    for (int i = 0; i < sectionCount; i++) {
        cin >> sections[i];
    }
}

void Teacher::display() const {
    cout << "\n\t\t\t\t\tTeacher name: " << name << "\n";
    cout << "\n\t\t\t\t\tSubject: " << subject << "\n";
    cout << "\n\t\t\t\t\tPhone number: " << phone << "\n";
    cout << "\n\t\t\t\t\tSections taught:\n";
    for (int i = 0; i < sectionCount; i++) {
        cout << "\n\t\t\t\t\t" << sections[i] << "\n";
    }
}

int Teacher::getPhone() const {
    return phone;
}

int Teacher::getSectionCount() const {
    return sectionCount;
}

string Teacher::getName() const {
    return name;
}

string Teacher::getSubject() const {
    return subject;
}

string Teacher::getSection(int index) const {
    return sections[index];
}

/* Function to create a new teacher record */
void createTeacherRecord() {
    system("CLS");
    char continueChoice = 'y';
    fileStream.open("teacher.dat", ios::out | ios::binary);
    Teacher teacher;

    while (continueChoice == 'y' || continueChoice == 'Y') {
        teacher.input();
        fileStream.write(reinterpret_cast<char*>(&teacher), sizeof(teacher));
        cout << "\n\t\t\t\t\tWant to Continue (Y/N): ";
        cin >> continueChoice;
    }
    fileStream.close();
}

