/* Function to search for a teacher by section */
void searchBySection() {
    system("CLS");
    fileStream.open("teacher.dat", ios::in | ios::binary);
    if (!fileStream) {
        cout << "\n\t\t\t\t\tFile not created\n";
        exit(0);
    }

    Teacher teacher;
    fileStream.read(reinterpret_cast<char*>(&teacher), sizeof(teacher));
    if (fileStream.eof()) {
        cout << "\n\t\t\t\t\tNo records present.\n";
        return;
    }

    string searchSection;
    cout << "\n\t\t\t\t\tEnter the section to be searched: ";
    cin.ignore();
    getline(cin, searchSection);

    int foundCount = 0;
    while (!fileStream.eof()) {
        for (int j = 0; j < teacher.getSectionCount(); j++) {
            if (searchSection == teacher.getSection(j)) {
                foundCount++;
                if (foundCount == 1) {
                    cout << "\n\t\t\t\t\tFaculty found, here are the details:\n";
                }
                teacher.display();
                cout << "\n";
                fileStream.read(reinterpret_cast<char*>(&teacher), sizeof(teacher));
                if (!fileStream.eof()) {
                    j = -1; // Reset section index
                }
            }
        }
        fileStream.read(reinterpret_cast<char*>(&teacher), sizeof(teacher));
    }
    if (foundCount == 0) {
        cout << "\n\t\t\t\t\tFaculty does not exist.\n";
    }
}

/* Function to delete a teacher record */
void deleteTeacherRecord() {
    system("CLS");
    string searchName;
    fstream tempFile;

    tempFile.open("copy.dat", ios::out | ios::binary);
    fileStream.open("teacher.dat", ios::in | ios::binary);
    if (!fileStream) {
        cout << "\n\t\t\t\t\tFile not created\n";
        return;
    }

    cout << "\n\t\t\t\t\tEnter the name of the teacher whose record is to be deleted: ";
    cin.ignore();
    getline(cin, searchName);

    Teacher teacher;
    fileStream.read(reinterpret_cast<char*>(&teacher), sizeof(teacher));
    while (!fileStream.eof()) {
        if (searchName != teacher.getName()) {
            tempFile.write(reinterpret_cast<char*>(&teacher), sizeof(teacher));
        }
        fileStream.read(reinterpret_cast<char*>(&teacher), sizeof(teacher));
    }

    fileStream.close();
    tempFile.close();
    remove("teacher.dat");
    rename("copy.dat", "teacher.dat");
}

