// Class representing a book entry in the application
class AddBook : public QMainWindow
{
    Q_OBJECT

public:
    int bookId, price, isbnNumber, publicationYear, editionNumber;
    std::string bookName, bookKey, publication, author, bookFormat, bookType, department, status;

public:
    explicit AddBook(QWidget *parent = nullptr);
    ~AddBook();

private slots:
    void onAddButtonClicked();
    int validateInput();
    void onAddBookButtonClicked();

private:
    Ui::AddBook *ui;

public:
    // Initializes book details and formats strings for storage
    void setBookDetails(int id, const std::string &name, const std::string &key, const std::string &pub, 
                        const std::string &auth, int price, const std::string &format, 
                        const std::string &type, const std::string &dept, int isbn, 
                        int year, int edition, const std::string &status) 
    {
        bookId = id;
        bookName = name;
        std::replace(bookName.begin(), bookName.end(), ' ', '_');

        bookKey = key;
        std::replace(bookKey.begin(), bookKey.end(), ' ', '_');

        publication = pub;
        std::replace(publication.begin(), publication.end(), ' ', '_');

        author = auth;
        std::replace(author.begin(), author.end(), ' ', '_');

        price = price;
        bookFormat = format;
        std::replace(bookFormat.begin(), bookFormat.end(), ' ', '_');

        bookType = type;
        std::replace(bookType.begin(), bookType.end(), ' ', '_');

        department = dept;
        std::replace(department.begin(), department.end(), ' ', '_');

        isbnNumber = isbn;
        publicationYear = year;
        editionNumber = edition;
        status = status;
    }

    // Overloaded output stream operator for displaying book details
    friend std::ostream &operator<<(std::ostream &out, const AddBook &book) 
    {
        out << book.bookId << "\t" << book.bookName << "\t" << book.bookKey << "\t" 
            << book.publication << "\t" << book.author << "\t" << book.price << "\t" 
            << book.bookFormat << "\t" << book.bookType << "\t" << book.department << "\t" 
            << book.isbnNumber << "\t" << book.publicationYear << "\t" 
            << book.editionNumber << "\t" << book.status << std::endl;
        return out;
    }

    // Overloaded input stream operator for reading book details
    friend std::istream &operator>>(std::istream &in, AddBook &book) 
    {
        in >> book.bookId >> book.bookName >> book.bookKey >> book.publication 
           >> book.author >> book.price >> book.bookFormat >> book.bookType 
           >> book.department >> book.isbnNumber >> book.publicationYear 
           >> book.editionNumber >> book.status;
        return in;
    }
};

#endif // ADD_BOOK_H

