                            }
                            remove("ACC.DAT");
                            accountCount = BankAccount::getCustomerAccountCount();
                            for (int j = 0; j < accountCount; j++) {
                                account.loadFromCustomerDisk(j);
                                account.saveToDisk();
                            }
                            remove("CACC.DAT");
                            cout << "\n\tDetail's UPDATED";
                            getch();
                        }
                    }
                    break;

                case 5:
                    system("CLS");
                    int balanceAccountNumber;
                    cout << "\n\tEnter the Account Number: ";
                    cin >> balanceAccountNumber;
                    bool found = false;
                    accountCount = BankAccount::getAccountCount();
                    for (i = 0; i < accountCount; i++) {
                        account.loadFromDisk(i);
                        if (account.accountNumber == balanceAccountNumber) {
                            account.displayAccountDetails();
                            found = true;
                            getch();
                        }
                    }
                    if (!found) {
                        system("CLS");
                        cout << "\n\tSorry...! There is No Account with this Number";
                        getch();
                    }
                    break;

                case 6:
                    system("CLS");
                    char deleteConfirmation;
                    cout << "\n\tEnter Account Number: ";
                    cin >> withdrawAccountNumber;
                    accountCount = BankAccount::getAccountCount();
                    for (i = 0; i < accountCount; i++) {
                        account.loadFromDisk(i);
                        if (account.accountNumber == withdrawAccountNumber) {
                            account.displayAccountDetails();
                            cout << "\n\tDo you want to Delete Account (y/n)? ";
                            cin >> deleteConfirmation;
                            if (deleteConfirmation == 'y') {
                                for (int j = 0; j < accountCount; j++) {
                                    if (j != i) {
                                        account.loadFromDisk(j);
                                        account.saveToCustomerDisk();
                                    } else {
                                        account.loadFromDisk(i);
                                        cout << account.name << endl;
                                        _sleep(2000);
                                        cout << "\t\tDeleting File......";
                                    }
                                }
                                remove("ACC.DAT");
                                accountCount = BankAccount::getCustomerAccountCount();
                                for (int j = 0; j < accountCount; j++) {
                                    account.loadFromCustomerDisk(j);
                                    account.saveToDisk();
                                }
                                remove("CACC.DAT");
                            }
                        }
                    }
                    break;

                case 7:
                    main();
                    break;

                default:
                    break;
            }
        }
    } else {
        cout << "Invalid Input";
        adminLogin();
    }
}

void customerLogin() {
    BankAccount account;
    while (true) {
        int loginAccountNumber, flag = 0, operation, withdrawAmount;
        char enteredPassword[5];

        cout << "\n\t******CUSTOMER LOGIN******";
        cout << "\n\t Login ID: ";
        cin >> loginAccountNumber;
        cout << "\n\t Password: ";
        char ch = getch();
        int i = 0;
        int accountCount = BankAccount::getAccountCount();

        while (ch != '\r') {
            enteredPassword[i] = ch;
            cout << '*';
            i++;
            ch = getch();
        }

        for (i = 0; i < accountCount; i++) {
            account.loadFromDisk(i);
            if ((loginAccountNumber == account.accountNumber) && (strcmp(enteredPassword, account.password) == 0)) {
                while (true) {
                    system("CLS");
                    flag = 1;
                    cout << "\n\t******WELCOME " << account.name << " TO SBI ONLINE******";
                    cout << "\n\t 1. Balance Enquiry";
                    cout << "\n\t 2. Withdraw Amount";
                    cout << "\n\t 3. Exit";
                    cout << "\n\t****************************";
                    cout << "\n\t Enter Your Option: ";
                    cin >> operation;

                    switch (operation) {
                        case 1:
                            system("CLS");
                            account.displayAccountDetails();
                            getch();
                            break;

                        case 2:
                            system("CLS");
                            account.displayAccountDetails();
                            cout << "\n\tEnter the Amount Withdraw: ";
                            cin >> withdrawAmount;
                            account.amount -= withdrawAmount;
                            account.saveToDisk();
                            accountCount = BankAccount::getAccountCount();
                            for (int j = 0; j < accountCount; j++) {
                                if (j != i) {
                                    account.loadFromDisk(j);
                                    account.saveToCustomerDisk();
                                }
                            }
                            remove("ACC.DAT");
                            accountCount = BankAccount::getCustomerAccountCount();
                            for (int j = 0; j < accountCount; j++) {
                                account.loadFromCustomerDisk(j);
                                account.saveToDisk();
                            }
                            remove("CACC.DAT");
                            cout << "\n\tDetail's UPDATED";
                            getch();
                            break;

                        case 3:
                            main();
                            break;
                    }
                }
            }
        }

        if (flag == 0) {
            system("CLS");
            cout << "\n\tINVALID LOGIN ID or PASSWORD";
        }
    }
}

