// Class to handle movie search and booking
class MovieSearch {
    friend class Movie;
    friend class Theater;
    friend class Time;

    string selectedMovie, selectedTheater;
    int selectedTime;

public:
    // Search for the movie and handle the booking process
    void searchAndBook(Time movies[3]) {
        int movieIndex = -1, timeIndex = -1, seatCount, comboChoice;
        float totalCost = 0, mealCost = 0, finalCost;

        string customerName;
        long long customerPhone;
        char selectedSeats[10][2];

        cout << "\nEnter Movie You Want To See:\n";
        cin >> selectedMovie;

        cout << "\nMovie Available in Theater:\n";
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 2; j++) {
                if (selectedMovie == movies[i].movies[j]) {
                    cout << movies[i].theaterName << endl;
                    movieIndex = i;
                }
            }
        }

        cout << "\nSelect Theater: ";
        cin >> selectedTheater;

        cout << "\nEnter Name: ";
        cin >> customerName;

        cout << "\nEnter Mobile Number: ";
        cin >> customerPhone;

        movies[movieIndex].displayTimings();

        cout << "\nSelect time:\n";
        cin >> selectedTime;

        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 4; j++) {
                if (selectedTime == movies[i].timings[j]) {
                    timeIndex = i;
                }
            }
        }

        // Seat selection display
        cout << "\n\n";
        cout << "  1 2 3 4 5 6 7 8 9\n";
        cout << "-----RECLINERS-----\n";
        cout << "A * * * * * * * * *\n";
        cout << "-------ROYAL-------\n";
        cout << "B * * * * * * * * *\n";
        cout << "C * * * * * * * * *\n";
        cout << "D * * * * * * * * *\n";
        cout << "-----EXECUTIVE-----\n";
        cout << "E * * * * * * * * *\n";
        cout << "F * * * * * * * * *\n";
        cout << "G * * * * * * * * *\n";
        cout << "____________________\n";
        cout << "       SCREEN       \n";

        cout << "\nNOTE:\n";
        cout << "EXECUTIVE: Rs. 110\n";
        cout << "ROYAL: Rs. 160\n";
        cout << "RECLINERS: Rs. 200\n";
        cout << "Number of Seats: ";
        cin >> seatCount;

        cout << "Select Seat:\n";
        for (int i = 0; i < seatCount; i++) {
            for (int j = 0; j < 2; j++) {
                cin >> selectedSeats[i][j];
            }
        }

        // Calculate total cost based on selected seats
        for (int i = 0; i < seatCount; i++) {
            switch (selectedSeats[i][0]) {
                case 'A':
                    totalCost += 200;
                    break;
                case 'B':
                case 'C':
                case 'D':
                    totalCost += 160;
                    break;
                case 'E':
                case 'F':
                case 'G':
                    totalCost += 110;
                    break;
                default:
                    cout << "Invalid INPUT!";
                    break;
            }
        }

        cout << "\nWould you like to have any meal Combo:\n1. YES 0. NO" << endl;
        cin >> comboChoice;

        if (comboChoice == 1) {
            int mealChoice = selectMealCombo();
            switch (mealChoice) {
                case 1:
                    cout << "Classic Combo (Medium Popcorn + Medium soft drink)";
                    mealCost += 110;
                    break;
                case 2:
                    cout << "French Combo (Fries + Medium soft drink)";
                    mealCost += 150;
                    break;
                case 3:
                    cout << "American Combo (Burger + Medium soft drink)";
                    mealCost += 180;
                    break;
                case 4:
                    cout << "Pure Popcorn (Large Popcorn)";
                    mealCost += 90;
                    break;
                case 5:
                    cout << "Only Soft Drink (Large soft drink)";
                    mealCost += 80;
                    break;
                default:
                    cout << "ERROR!";
                    break;
            }
        } else {
            cout << "\nNO Meal.\n";
        }

        finalCost = mealCost + totalCost;
        cout << "\nMEAL COST: Rs." << mealCost << endl;
        cout << "TICKET COST: Rs." << totalCost << endl;
        cout << "FINAL COST (including tax 6%): Rs." << (finalCost + (finalCost * 0.06)) << endl;
        cout << "           SGST 3% (Rs." << (finalCost * 0.03) << ")\n";
        cout << "           CGST 3% (Rs." << (finalCost * 0.03) << ")\n";
        cout << "*****************************************************";
    }
};

