    int UpdateOccupancyStatus(int capacity);

    // Adjusts the room rate based on the season
    void SetRoomRate(double rate);

    // Reserves the specified hotel room
    void ReserveRoom(HotelRoom& hotelRoom);

    // Modifies room details based on the season
    void UpdateRoomDetails(HotelRoom& hotelRoom, string season);

    // Displays the details of the room
    void DisplayRoomDetails();

    // Constructor to initialize room attributes
    HotelRoom(int roomNumber, int capacity, double roomRate);

private:
    int roomNumber;
    int roomCapacity;
    int occupancyStatus;
    double dailyRate;
};

