    room1.DisplayRoomDetails();
    room2.DisplayRoomDetails();
    room3.DisplayRoomDetails();

    return 0;
}

void HotelRoom::DisplayRoomDetails() {
    cout << "Room Number: " << roomNumber << endl; // Display room number
    cout << "Capacity: " << roomCapacity << endl; // Display room capacity
    cout << "Rate: " << dailyRate << endl; // Display room rate
    cout << "Season: " << (occupancyStatus > 0 ? "Occupied" : "Available") << endl; // Display occupancy status
}

int HotelRoom::GetRoomNumber() {
    return roomNumber;
}

int HotelRoom::GetRoomCapacity() {
    return roomCapacity;
}

int HotelRoom::GetRoomStatus() {
    return occupancyStatus;
}

double HotelRoom::GetRoomRate() {
    return dailyRate;
}

int HotelRoom::UpdateOccupancyStatus(int capacity) {
    // Check if the requested capacity exceeds the room capacity
    if (capacity > roomCapacity) {
        return -1; // Indicate failure
    }
    occupancyStatus = capacity; // Update occupancy status
    return 1; // Indicate success
}

void HotelRoom::SetRoomRate(double rate) {
    dailyRate = rate; // Update the daily room rate
}

HotelRoom::HotelRoom(int roomNumber, int capacity, double roomRate) 
    : roomNumber(roomNumber), roomCapacity(capacity), dailyRate(roomRate), occupancyStatus(0) {
}

