    available_train_tickets = 0;
    available_plane_tickets = 0;
}

Flight::Flight(string flight_number_param, string departure_param, string place_of_arrival_param, 
               string hour_departure_time_param, string hour_arrival_time_param, 
               int car_tickets, int train_tickets, int plane_tickets) 
{
    flight_number = flight_number_param;
    departure = departure_param;
    place_of_arrival = place_of_arrival_param;
    hour_departure_time = hour_departure_time_param;
    hour_arrival_time = hour_arrival_time_param;
    available_car_tickets = car_tickets;
    available_train_tickets = train_tickets;
    available_plane_tickets = plane_tickets;
}

// Decrease the count of available car tickets by one.
void Flight::decrement_car_tickets() 
{ 
    available_car_tickets--; 
}

// Decrease the count of available train tickets by one.
void Flight::decrement_train_tickets() 
{ 
    available_train_tickets--; 
}

// Decrease the count of available plane tickets by one.
void Flight::decrement_plane_tickets() 
{ 
    available_plane_tickets--; 
}

// Cancel the booking and reset ticket availability.
void Flight::cancel_booking() 
{
    hour_departure_time = "Sorry, flight postponed";
    hour_arrival_time = "Sorry, flight postponed";
    available_car_tickets = 0;
    available_train_tickets = 0;
    available_plane_tickets = 0;
}

// Overload assignment operator for Flight class.
Flight& Flight::operator=(const Flight& other) 
{
    flight_number = other.flight_number;
    departure = other.departure;
    place_of_arrival = other.place_of_arrival;
    hour_departure_time = other.hour_departure_time;
    hour_arrival_time = other.hour_arrival_time;
    available_car_tickets = other.available_car_tickets;
    available_train_tickets = other.available_train_tickets;
    available_plane_tickets = other.available_plane_tickets;
    return *this;
}

// Overload output stream operator for Flight class.
ostream& operator<<(ostream& output_stream, const Flight& flight) 
{
    output_stream << "Flight number: " << flight.flight_number << endl;
    output_stream << "Departure: " << flight.departure << endl;
    output_stream << "Place of arrival: " << flight.place_of_arrival << endl;
    output_stream << "Hour departure time: " << flight.hour_departure_time << endl;
    output_stream << "Hour arrival time: " << flight.hour_arrival_time << endl;

    if (flight.available_car_tickets > 0) 
    {
        output_stream << "Tickets for the car: " << flight.available_car_tickets << endl;
    }
    if (flight.available_train_tickets > 0) 
    {
        output_stream << "Tickets for the train: " << flight.available_train_tickets << endl;
    }
    if (flight.available_plane_tickets > 0) 
    {
        output_stream << "Tickets for the plane: " << flight.available_plane_tickets << endl;
    }
    output_stream << endl;
    return output_stream;
}

