#include <iostream>
#include <cmath>

using namespace std;

class Rectangle {
private: 
    float width, height;

public:
    // Constructor to initialize rectangle dimensions
    Rectangle(float width, float height) : width(width), height(height) {}

    // Copy constructor that creates a rectangle based on the diagonal of another rectangle
    Rectangle(Rectangle &other) {
        float diagonal = sqrt(pow(other.getWidth(), 2) + pow(other.getHeight(), 2));
        width = diagonal;
        height = diagonal;
    }

    // Accessor for width
    float getWidth() const {
        return width;
    }

    // Accessor for height
    float getHeight() const {
        return height;
    }

    // Prints the type and dimensions of the rectangle
    void print() const {
        if (width == height) {
            cout << "Square with side=" << width << endl;
        } else {
            cout << "Rectangle with width=" << width << " and height=" << height << endl;
        }
    }

    ~Rectangle() {}
};

int main() {
    Rectangle rectA(12, 3);
    Rectangle rectB(rectA);

    rectA.print();
    rectB.print();

    system("pause");
    return 0;
}

#pragma once

class Prism : public Triangle {
private:
	int prismHeight;
	double prismArea, prismVolume;

public:
	// Constructor initializes the prism with a triangle base and height
	Prism(Triangle baseTriangle, int height) : Triangle(baseTriangle.getLength(), baseTriangle.getHeight()) {
		cout << "Creating a prism..." << endl << endl;
		prismHeight = height;
		prismArea = 2 * baseTriangle.getArea() + height * baseTriangle.getPerimeter();
		prismVolume = baseTriangle.getArea() * height;
	}

	// Returns the surface area of the prism
	double getArea() const {
		return prismArea;
	}

	// Returns the volume of the prism
	double getVolume() const {
		return prismVolume;
	}

	// Outputs the properties of the prism
	void printIt() const {
		cout << "This is a prism." << endl
			<< "It's volume, V = " << getVolume() << endl
			<< "It's area, S = " << getArea() << endl << endl;
	}

	~Prism() {}
};

