class Segment {
protected:
	int length; // Chiều dài của đoạn thẳng

public:
	Segment() = default; // Khởi tạo mặc định

	// Khởi tạo với giá trị chiều dài
	Segment(int initialLength) {
		cout << "Creating a segment..." << endl;
		setLength(initialLength); // Sử dụng phương thức để đảm bảo tính hợp lệ
	}

	// Thiết lập chiều dài nếu giá trị hợp lệ
	void setLength(int newLength) {
		if (newLength > 0) {
			length = newLength;
		}
	}

	// Lấy chiều dài của đoạn thẳng
	int getLength() const {
		return length;
	}

	// In thông tin về đoạn thẳng
	void printIt() const {
