			<< "It's length, L = " << getLength() << endl << endl;
	}

	~Segment() = default; // Hủy đối tượng
};

#pragma once

class Triangle : public Segment {
protected:
    int userDefinedHeight; 
    double calculatedArea, calculatedPerimeter;

public:
    // Constructor initializes the triangle with a side and height, calculating area and perimeter
    Triangle(Segment side, int height) : Segment(side.getLength()) {
        cout << "Creating a triangle..." << endl;
        userDefinedHeight = height;
        calculatedArea = 0.5 * getLength() * height;

        // Calculate the length of the triangle's ribs using the Pythagorean theorem
        double ribLength = sqrt(pow((getLength() / 2), 2) + pow(height, 2));
        calculatedPerimeter = getLength() + 2 * ribLength;
    }

    // Retrieve the area of the triangle
    double getArea() const {
        return calculatedArea;
    }

    // Retrieve the perimeter of the triangle
    double getPerimeter() const {
        return calculatedPerimeter;
    }

    // Retrieve the height of the triangle
    double getHeight() const {
        return userDefinedHeight;
    }

    // Print the triangle's properties
    void printIt() const {
        cout << "This is a triangle." << endl
             << "It's perimeter, P = " << getPerimeter() << endl
             << "It's area, S = " << getArea() << endl << endl;
    }
};

