void writeAccount()
{
    Account newAccount;
    ofstream outFile;
    outFile.open("account.dat", ios::binary | ios::app);
    newAccount.createAccount();
    outFile.write(reinterpret_cast<char*>(&newAccount), sizeof(Account));
    outFile.close();
}

//***************************************************************
//     Function to Display Specific Account Details
//****************************************************************

void displaySingleAccount(int accountNumber)
{
    Account existingAccount;
    bool found = false;
    ifstream inFile;
    inFile.open("account.dat", ios::binary);
    if (!inFile)
    {
        cout << "File could not be opened! Press any key...";
        return;
    }
    cout << "\nBALANCE DETAILS\n";

    while (inFile.read(reinterpret_cast<char*>(&existingAccount), sizeof(Account)))
    {
        if (existingAccount.getAccountNumber() == accountNumber)
        {
            existingAccount.displayAccount();
            found = true;
        }
    }
    inFile.close();
    if (!found)
        cout << "\n\nAccount number does not exist";
}

//***************************************************************
//     Function to Modify Account Record in File
//****************************************************************

void modifyAccount(int accountNumber)
{
    bool found = false;
    Account existingAccount;
    fstream file;
    file.open("account.dat", ios::binary | ios::in | ios::out);
    if (!file)
    {
        cout << "File could not be opened! Press any key...";
        return;
    }
    while (!file.eof() && !found)
    {
        file.read(reinterpret_cast<char*>(&existingAccount), sizeof(Account));
        if (existingAccount.getAccountNumber() == accountNumber)
        {
            existingAccount.displayAccount();
            cout << "\n\nEnter The New Details of account" << endl;
            existingAccount.updateAccount();
            int position = (-1) * static_cast<int>(sizeof(Account));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&existingAccount), sizeof(Account));
            cout << "\n\n\t Record Updated";
            found = true;
        }
    }
    file.close();
    if (!found)
        cout << "\n\n Record Not Found ";
}

//***************************************************************
//     Function to Delete Account Record from File
//****************************************************************

void deleteAccount(int accountNumber)
{
    Account existingAccount;
    ifstream inFile;
    ofstream outFile;
    inFile.open("account.dat", ios::binary);
    if (!inFile)
    {
        cout << "File could not be opened! Press any key...";
        return;
    }
    outFile.open("Temp.dat", ios::binary);
    inFile.seekg(0, ios::beg);
    while (inFile.read(reinterpret_cast<char*>(&existingAccount), sizeof(Account)))
    {
        if (existingAccount.getAccountNumber() != accountNumber)
        {
            outFile.write(reinterpret_cast<char*>(&existingAccount), sizeof(Account));
        }
    }
    inFile.close();
    outFile.close();
    remove("account.dat");
    rename("Temp.dat", "account.dat");
    cout << "\n\n\tRecord Deleted ..";
}

