//***************************************************************
//     Function to Handle Deposit and Withdraw Operations
//****************************************************************

void handleDepositWithdraw(int accountNumber, int operation)
{
    int amount;
    bool found = false;
    Account existingAccount;
    fstream file;
    file.open("account.dat", ios::binary | ios::in | ios::out);
    if (!file)
    {
        cout << "File could not be opened! Press any key...";
        return;
    }
    while (!file.eof() && !found)
    {
        file.read(reinterpret_cast<char*>(&existingAccount), sizeof(Account));
        if (existingAccount.getAccountNumber() == accountNumber)
        {
            existingAccount.displayAccount();
            if (operation == 1) // Deposit
            {
                cout << "\n\n\tTO DEPOSIT AMOUNT ";
                cout << "\n\nEnter The amount to be deposited: ";
                cin >> amount;
                existingAccount.deposit(amount);
            }
            if (operation == 2) // Withdraw
            {
                cout << "\n\n\tTO WITHDRAW AMOUNT ";
                cout << "\n\nEnter The amount to be withdrawn: ";
                cin >> amount;
                int newBalance = existingAccount.getBalance() - amount;
                if ((newBalance < 500 && existingAccount.getAccountType() == 'S') || 
                    (newBalance < 1000 && existingAccount.getAccountType() == 'C'))
                {
                    cout << "Insufficient balance";
                }
                else
                {
                    existingAccount.withdraw(amount);
                }
            }
            int position = (-1) * static_cast<int>(sizeof(existingAccount));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&existingAccount), sizeof(Account));
            cout << "\n\n\t Record Updated";
            found = true;
        }
    }
    file.close();
    if (!found)
        cout << "\n\n Record Not Found ";
}

