std::string EncryptString(const std::string& str) {
    std::string encrypted = str;
    for (size_t i = 0; (i < 100 && encrypted[i] != '\0'); i++) {
        encrypted[i] += 2;
    }
    return encrypted;
}

bool IsCharacter(char c) {
    return ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'));
}

bool IsDigit(char c) {
    return (c >= '0' && c <= '9');
}

bool IsValidEmail(const std::string& email) {
    if (!IsCharacter(email[0])) {
        return false;
    }

    int atIndex = -1, dotIndex = -1;
    for (size_t i = 0; i < email.length(); i++) {
        if (email[i] == '@') {
            atIndex = i;
        } else if (email[i] == '.') {
            dotIndex = i;
        }
    }

    if (atIndex == -1 || dotIndex == -1 || atIndex > dotIndex || dotIndex >= (email.length() - 1)) {
        return false;
    }
    return true;
}

