bool LoginSuccessful(const std::string& username, const std::string& password) {
    try {
        int index = -1;
        std::string query = "SELECT * FROM users";
        const char* queryStr = query.c_str();
        std::vector<std::string> usernames, passwords;

        queryState = mysql_query(connection, queryStr);
        if (!queryState) {
            result = mysql_store_result(connection);
            while (row = mysql_fetch_row(result)) {
                usernames.push_back(row[1]);
                passwords.push_back(row[2]);
            }
        } else {
            std::cout << "Error: " << mysql_errno(connection) << std::endl;
            system("PAUSE");
        }

        for (size_t i = 0; i < usernames.size(); i++) {
            if (username == usernames[i]) {
                index = i;
                break;
            }
        }

        if (index != -1) {
            std::string encryptedPassword = passwords[index];
            std::string decryptedPassword = DecryptString(encryptedPassword);

            if (decryptedPassword == password) {
                std::string userQuery = "SELECT * FROM users WHERE username ='" + username + "'";
                const char* userQueryStr = userQuery.c_str();
                queryState = mysql_query(connection, userQueryStr);

                if (!queryState) {
