void writeAccount(short accountType) {
    std::ofstream outFileClient("Client.dat", std::ios::binary | std::ios::app);
    Client client;
    client.addClient();
    outFileClient.write(reinterpret_cast<char*>(&client), sizeof(Client));
    outFileClient.close();

    std::ofstream outFile;
    switch (accountType) {
        case 1: {
            DebitAccount debitAccount;
            outFile.open("Account.dat", std::ios::binary | std::ios::app);
            debitAccount.createAccount(accountType, client.getId(), client.getClientClass());
            outFile.write(reinterpret_cast<char*>(&debitAccount), sizeof(Account));
            outFile.close();
            break;
        }
        case 2: {
            CreditAccount creditAccount;
            outFile.open("Account.dat", std::ios::binary | std::ios::app);
            creditAccount.createAccount(client.getId(), client.getClientClass());
            outFile.write(reinterpret_cast<char*>(&creditAccount), sizeof(Account));
            outFile.close();
            break;
        }
        case 3: {
            BusinessAccount businessAccount;
            outFile.open("Account.dat", std::ios::binary | std::ios::app);
            businessAccount.createAccount(accountType, client.getId(), client.getClientClass());
            outFile.write(reinterpret_cast<char*>(&businessAccount), sizeof(Account));
            outFile.close();
            break;
        }
        case 4: {
            SavingAccount savingAccount;
            outFile.open("Account.dat", std::ios::binary | std::ios::app);
            savingAccount.createAccount(accountType, client.getId(), client.getClientClass());
            outFile.write(reinterpret_cast<char*>(&savingAccount), sizeof(Account));
            outFile.close();
            break;
        }
        default:
            std::cout << "Invalid choice";
    }
}

