void updateAccount(int accountNumber) {
    bool found = false;
    Account account;
    std::fstream file("Account.dat", std::ios::binary | std::ios::in | std::ios::out);
    if (!file) {
        std::cout << "File could not be opened! Press any key...";
        return;
    }
    while (file.read(reinterpret_cast<char*>(&account), sizeof(Account)) && !found) {
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
