    int atmPin[4], cardParts[4][4];
    char separator;

    AccountNode* newAccount = new AccountNode();

    cout << "\t\t\t  ACCOUNT NUMBER             : ";
    cin >> newAccount->accountNumber;
    cout << "\t\t\t  ACCOUNT HOLDER NAME        : ";
    cin.ignore();
    cin.getline(newAccount->accountHolderName, 50);
    cout << "\t\t\t  DATE OF BIRTH [dd/mm/yyyy]  : ";
    cin >> newAccount->birthDay >> separator >> newAccount->birthMonth >> separator >> newAccount->birthYear;
    cout << "\t\t\t  13-DIGIT CNIC NUMBER       : ";
    cin >> newAccount->cnicNumber;
    cout << "\t\t\t  CITY                       : ";
    cin >> newAccount->city;
    cout << "\t\t\t  PHONE NUMBER [+92]         : ";
    cin >> newAccount->mobileNumber;
    cout << "\t\t\t  OPENING BALANCE            : Rs ";
    cin >> newAccount->balance;

    cout << "\t\t\t  YOUR DEBIT CARD NUMBERS IS : ";
    srand(static_cast<unsigned int>(time(0)));
    for (int i = 0; i < 4; i++) {
        cardParts[i][0] = (rand() % 9) + 1;
        cardParts[i][1] = (rand() % 9) + 1;
        cardParts[i][2] = (rand() % 9) + 1;
        cardParts[i][3] = (rand() % 9) + 1;
        cout << cardParts[i][0] << cardParts[i][1] << cardParts[i][2] << cardParts[i][3] << " ";
    }

    cout << "\n\t\t\t  SET 4-DIGIT ATM CARD PIN   : ";
    for (int i = 0; i < 4; i++) {
        atmPin[i] = getch();
        printf("*");
        atmPin[i] = (atmPin[i] - 49) + 1;
        newAccount->pin[i] = atmPin[i];
    }

    newAccount->serviceStatus = 1;

    for (int i = 0; i < 4; i++) {
        newAccount->cardNumberPart1[i] = cardParts[i][0];
        newAccount->cardNumberPart2[i] = cardParts[i][1];
        newAccount->cardNumberPart3[i] = cardParts[i][2];
        newAccount->cardNumberPart4[i] = cardParts[i][3];
    }

    newAccount->next = nullptr;

    if (head == nullptr) {
        newAccount->previous = nullptr;
        head = newAccount;
    } else {
        AccountNode* current = head;
        while (current->next != nullptr) {
            current = current->next;
        }
        current->next = newAccount;
        newAccount->previous = current;
    }

    cout << "\n\n\t\t\t  Bank Account Successfully Added !!!! \n";
}

