    void enter() {
        system("Cls");
        displayHeader();
        int check = 0;
        int atmPin[4];
        AccountNode* current = new AccountNode();

        if (head == nullptr) {
            cout << "\a\n\t\t\t  No Account Found !!!!";
            return;
        }

        cout << "\n\n\t\t\t\t     ENTER ACCOUNT NUMBER   :     ";
        cin >> accountNumber;
        current = head;

        while (current != nullptr) {
            if (current->accountNumber == accountNumber) {
                check = 1;
                if (current->serviceStatus == 1) {
                    check = 2;
                    int attempts = 0;

                    while (attempts != 3) {
                        current = head;
                        cout << "\t\t\t\t     ENTER PIN              :     ";
                        for (int i = 0; i < 4; i++) {
                            atmPin[i] = getch();
                            printf("*");
                            atmPin[i] = (atmPin[i] - 49) + 1;
                        }
                        check = 3;

                        while (current != nullptr) {
                            if (current->accountNumber == accountNumber) {
                                if (current->pin[0] == atmPin[0] && current->pin[1] == atmPin[1] &&
                                    current->pin[2] == atmPin[2] && current->pin[3] == atmPin[3]) {
                                    clearStatus = 1;
                                    cout << "\n\n\t\t\t  PRESS ENTER TO CONTINUE.... ";
                                    cin.ignore();
                                    cin.get();
                                    return;
                                }

                                if (check == 3 && clearStatus == 0) {
                                    cout << "\n\a\t\t\t\t INCORRECT PIN ...!!!\n";
                                }
                            }
                            current = current->next;
                        }
                        attempts++;

                        if (attempts == 3) {
                            current = head;
                            while (current != nullptr) {
                                if (current->accountNumber == accountNumber) {
                                    current->serviceStatus = 0;
                                    cout << "\n\a\t\t\t\t YOUR CARD HAS BEEN CAPTURED...!!!\n";
                                    cout << "\t\t\t\t CONTACT YOUR BRANCH...!!!\n";
                                    return;
                                }
                            }
                        }
                    }
                }
            }
