// Abstract class representing a seat type
class Seat {
    LONG_LONG amount;

public:
    virtual void displayType() = 0;
    LONG_LONG getFinalAmount() const {
        return amount;
    }

    void setAmount(LONG_LONG value) {
        amount = value;
    }
};

// Template function to check availability
template<class T>
bool isAvailable(int requestedTickets, T* seatType) {
    return seatType->total >= requestedTickets;
}

// Template function to update available tickets
template<class T>
void updateAvailableTickets(int bookedTickets, T* seatType) {
    seatType->total -= bookedTickets;
}

// Class representing VIP box seats
class VIPBox : public Seat {
