    Test(int A, int B, int C); // Constructor with three parameters
};

// Default constructor initializes member variables to zero
Test::Test() : a(0), b(0), c(0) {
    cout << "Constructor with NO parameter" << endl;
}

// Destructor outputs a message indicating destruction order
Test::~Test() {
    printf("Constructor created last is destructing first here\n");
}

