}

// Constructor with three parameters initializes a, b, and c, outputs their sum
Test::Test(int A, int B, int C) : a(A), b(B), c(C) {
    printf("Constructor with triple parameter adding a+b+c: ");
    cout << a + b + c << endl;
}

// Validates if all member variables are initialized to zero
int Test::validateInitialization() {
    if (a == 0 && b == 0 && c == 0) {
        printf("Constructor initialized all three variables successfully\n");
    } else {
        printf("Something isn't right\n");
    }
    return 0;
}

