using namespace std;

int globalCounter = 1;

class PointerHandler {
public:
    int displayCounter();
};

inline int PointerHandler::displayCounter() {
    // Increment and display the global counter for a fixed number of iterations
    for (int iteration = 0; iteration < 5; iteration++, globalCounter++) {
        cout << globalCounter << " " << endl;
    }

    // Reset the counter if it reaches a specific value
    if (globalCounter == 26) {
        globalCounter = 1;
    }

    printf("\n");
}

int main() {
    PointerHandler objects[3]; // Array of PointerHandler objects

    // Display counter values using the object array
    for (int index = 0; index < 5; index++) {
        objects[index].displayCounter();
    }

    PointerHandler* pointerToObjects = objects; // Assigning the address of the first object to a pointer

    printf("Pointer to object: \n");

    // Display counter values using the pointer to the object array
    for (int index = 0; index < 5; index++) {
        (pointerToObjects + index)->displayCounter();
    }

    return 0;
}

