#include <bits/stdc++.h>

using namespace std;

class Screen 
{
    int totalRows, rowSize;
    vector<string> seatingArrangement; // Each row represented as a string of 'E', 'A', 'R'

public:
    // Initializes the screen with the given configuration
    Screen(vector<string> configuration)
    {
        string emptyRow = string(rowSize, 'E'); // Initialize an empty row
        totalRows = stoi(configuration[2]);
        rowSize = stoi(configuration[3]);

        // Mark aisles in the row
        for (int i = 4; i < configuration.size(); i++) 
        {
            emptyRow[stoi(configuration[i]) - 1] = 'A'; // Set aisle positions
        }

        // Populate the seating arrangement with initialized rows
        for (int i = 0; i < totalRows; i++) 
        {
            seatingArrangement.push_back(emptyRow);
        }

        cout << "success" << endl;
    }

    // Reserves seats based on the provided input
    string reserve_seat(vector<string> request) 
    {
        bool canReserve = true;
        int rowNumber = stoi(request[2]) - 1;

        // Check if requested seats are available
        for (int i = 3; i < request.size(); i++) 
        {
            int seatNumber = stoi(request[i]) - 1;
            if (seatingArrangement[rowNumber][seatNumber] == 'R') 
            {
                canReserve = false;
                break;
            }
        }

        if (!canReserve) return "failure";

        // Mark the seats as reserved
        for (int i = 3; i < request.size(); i++) 
        {
            int seatNumber = stoi(request[i]) - 1;
            seatingArrangement[rowNumber][seatNumber] = 'R';
        }

        return "success";
    }

    // Retrieves unreserved seats in a specified row
    vector<int> get_unreserved(int rowNumber)
    {
        vector<int> availableSeats;

        // Collect indices of unreserved seats
        for (int i = 0; i < rowSize; i++) 
        {
            if (seatingArrangement[rowNumber][i] != 'R') 
            {
                availableSeats.push_back(i + 1);
            }
        }

        return availableSeats;
    }

    // Suggests contiguous seats based on the request
    vector<int> suggest_seats(int numberOfSeats, int rowNumber, int preferredSeat)
    {
        string currentRow = seatingArrangement[rowNumber];
        vector<int> suggestedSeats;
        bool isAvailable = true;

        // Check left side of the preferred seat
        for (int i = preferredSeat - numberOfSeats + 1; i <= preferredSeat; i++) 
        {
            if (i < 0 || currentRow[i] == 'R' || (i > preferredSeat - numberOfSeats + 1 && currentRow[i - 1] == 'A' && currentRow[i] == 'A')) 
            {
                isAvailable = false;
                break;
            }
        }

        if (isAvailable) 
        {
            for (int i = preferredSeat - numberOfSeats + 1; i <= preferredSeat; i++) 
            {
                suggestedSeats.push_back(i + 1);
            }
            return suggestedSeats;
        }

        isAvailable = true;

        // Check right side of the preferred seat
        for (int i = preferredSeat; i < preferredSeat + numberOfSeats; i++) 
        {
            if (currentRow[i] == 'R' || (i > preferredSeat && currentRow[i - 1] == 'A' && currentRow[i] == 'A')) 
            {
                isAvailable = false;
                break;
            }
        }

        if (isAvailable) 
        {
            for (int i = preferredSeat; i < preferredSeat + numberOfSeats; i++) 
            {
                suggestedSeats.push_back(i + 1);
            }
            return suggestedSeats;
        }

        return suggestedSeats; // Return empty if no suggestions
    }
};

// Splits a string into words based on spaces
vector<string> words(string input) 
{ 
    stringstream stream(input);
    string token;
    vector<string> result;

    while (getline(stream, token, ' ')) 
    {
        if (!token.empty()) 
        {
            result.push_back(token);
        }
    }

    return result;
}

int main() 
{
    int numberOfScreens;
    unordered_map<string, Screen*> screenMap;
    cin >> numberOfScreens;
    cin.ignore(); // Ignore the newline after the integer input

    for (int i = 0; i <= numberOfScreens; i++) 
    {
        string command;
        getline(cin, command);
        vector<string> parsedCommand = words(command);

        if (parsedCommand.empty()) continue;

        string screenName = parsedCommand[1];

        if (parsedCommand[0] == "add-screen") 
        {
            screenMap[screenName] = new Screen(parsedCommand);   
        } 
        else if (parsedCommand[0] == "reserve-seat") 
        {
            string result;
            if (screenMap.find(screenName) != screenMap.end()) 
            {
                result = screenMap[screenName]->reserve_seat(parsedCommand);
            } 
            else 
            {
                result = "failure";
            }
            cout << result << endl;
        } 
        else if (parsedCommand[0] == "get-unreserved-seats") 
        {
            if (screenMap.find(screenName) != screenMap.end()) 
            {
                vector<int> unreservedSeats = screenMap[screenName]->get_unreserved(stoi(parsedCommand[2]) - 1);
                for (int seat : unreservedSeats) 
                {
                    cout << seat << " ";
                }
            } 
            else 
            {
                cout << "failure";
            }
            cout << endl;
        } 
        else if (parsedCommand[0] == "suggest-contiguous-seats") 
        {
            if (screenMap.find(screenName) != screenMap.end()) 
            {
                vector<int> suggestedSeats = screenMap[screenName]->suggest_seats(stoi(parsedCommand[2]), stoi(parsedCommand[3]) - 1, stoi(parsedCommand[4]) - 1);
                if (suggestedSeats.empty()) 
                {
                    cout << "none" << endl;
                } 
                else 
                {
                    for (int seat : suggestedSeats) 
                    {
                        cout << seat << " ";
                    }
                    cout << endl;
                }
            } 
            else 
            {
                cout << "failure" << endl;
            }
        }
    }

    return 0;
}

