// Node structure for linked list representing bank account information
struct AccountNode {
    string cnic; // CNIC of the account holder
    string name; // Name of the account holder
    double balance; // Total amount in the account
    int accountNumber; // Randomly generated account number
    AccountNode* next; // Pointer to the next node in the linked list
};

AccountNode* head = nullptr; // Pointer to the head of the linked list

// Class to manage bank account operations using a linked list
class BankAccountManager {
public:
    void createAccount() {
        AccountNode* newAccount = new AccountNode;
        cout << "Please Enter Your CNIC No.: ";
        cin >> newAccount->cnic;
        cout << "Please Enter Your Name: ";
        cin >> newAccount->name;
        cout << "Enter Your Initial Amount: ";
        cin >> newAccount->balance;

        newAccount->accountNumber = generateAccountNumber();
        cout << "YOU HAVE BEEN ASSIGNED ACCOUNT NO: " << newAccount->accountNumber << endl;
        newAccount->next = nullptr;

        if (head == nullptr) {
            head = newAccount;
        } else {
            AccountNode* temp = head;
            while (temp->next != nullptr) {
                temp = temp->next;
            }
            temp->next = newAccount;
        }
        saveAccountToFile(newAccount);
    }

    void enqueue() {
        createAccount();
    }

    void dequeue() {
        if (head == nullptr) {
            cout << "FIRST OPEN AN ACCOUNT" << endl;
            return;
        }
        AccountNode* tempPtr = head;
        head = head->next;
        delete tempPtr;
        cout << "The account has been deleted." << endl;
    }

    void depositMoney() {
        if (head == nullptr) {
            cout << "Please open your account first to deposit cash." << endl;
            return;
