            if (temp->cnic == cnic) {
                int depositAmount;
                cout << "Enter the amount you want to deposit: ";
                cin >> depositAmount;
                temp->balance += depositAmount;
                printDepositSlip(temp, depositAmount);
                return;
            }
            temp = temp->next;
        }
    }

    void withdrawMoney() {
        if (head == nullptr) {
            cout << "FIRST CREATE AN ACCOUNT" << endl;
            return;
        }
        string cnic;
        cout << "Enter your CNIC No.: ";
        cin >> cnic;

        AccountNode* temp = head;
        while (temp != nullptr) {
            if (temp->cnic == cnic) {
                int withdrawAmount;
                cout << "Enter the amount you want to withdraw: ";
                cin >> withdrawAmount;
                if (withdrawAmount > temp->balance) {
                    cout << "YOU DON'T HAVE SUFFICIENT MONEY IN YOUR ACCOUNT" << endl;
                } else {
                    temp->balance -= withdrawAmount;
                    printWithdrawSlip(temp, withdrawAmount);
                }
                return;
            }
            temp = temp->next;
        }
