// Stack class for managing employee salaries
class SalaryStack {
public:
    SalaryStack(int size) {
        data = new int[size];
        capacity = size;
        top = 0;
    }

    bool isFull() {
        return top == capacity;
    }

    void push(int salary) {
        if (!isFull()) {
            data[top++] = salary;
        } else {
            cout << "Stack is full." << endl;
        }
    }

    bool isEmpty() {
        return top == 0;
    }

    int pop() {
        if (!isEmpty()) {
            return data[--top];
        } else {
            cout << "Stack is empty." << endl;
            return -1; // Return an invalid value
        }
    }

private:
    int* data; // Array to hold salary data
    int capacity; // Maximum capacity of the stack
    int top; // Current top index of the stack
};

