void writeAccount() {
    Account account;
    ofstream file;
    file.open("info.dat", ios::binary | ios::app);
    account.createAccount();
    file.write(reinterpret_cast<char*>(&account), sizeof(Account));
    file.close();
}

void depositWithdraw(int accountNumber, int option) {
    int amount;
    bool found = false;
    Account account;
    fstream file;
    file.open("info.dat", ios::binary | ios::in | ios::out);

    if (!file) {
        cout << "File could not be opened! Press any key...";
        return;
    }

    while (!file.eof() && !found) {
        file.read(reinterpret_cast<char*>(&account), sizeof(Account));
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();

            if (option == 1) {
                cout << "\n\n\tTO DEPOSIT AMOUNT ";
                cout << "\n\nEnter The amount to be deposited: ";
                cin >> amount;
                account.deposit(amount);
            }

            if (option == 2) {
                cout << "\n\n\tTO WITHDRAW AMOUNT ";
                cout << "\n\nEnter The amount to be withdrawn: ";
                cin >> amount;
                int newBalance = account.getBalance() - amount;

                if ((newBalance < 500 && account.getAccountType() == 'S') || (newBalance < 1000 && account.getAccountType() == 'C')) {
                    cout << "Insufficient balance";
                } else {
                    account.withdraw(amount);
                }
            }

            int position = (-1) * static_cast<int>(sizeof(Account));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            cout << "\n\n\tRecord Updated";
            found = true;
        }
    }
    file.close();

    if (!found) {
        cout << "\n\nRecord Not Found";
    }
}

void displaySingleAccount(int accountNumber) {
    Account account;
    bool found = false;
    ifstream file;
    file.open("info.dat", ios::binary);

    if (!file) {
        cout << "File could not be opened! Press any key to exit...";
        return;
    }

    cout << "\nBALANCE DETAILS\n";

    while (file.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            found = true;
        }
    }
    file.close();

    if (!found) {
        cout << "\n\nAccount number does not exist";
    }
}

void modifyAccount(int accountNumber) {
    bool found = false;
    Account account;
    fstream file;
    file.open("info.dat", ios::binary | ios::in | ios::out);

    if (!file) {
        cout << "File could not be opened! Press any key...";
        return;
    }

    while (!file.eof() && !found) {
        file.read(reinterpret_cast<char*>(&account), sizeof(Account));
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            cout << "\n\nEnter The New Details of account" << endl;
            account.modifyAccount();

            int position = (-1) * static_cast<int>(sizeof(Account));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            cout << "\n\n\tRecord Updated";
            found = true;
        }
    }
    file.close();

    if (!found) {
        cout << "\n\nRecord Not Found";
    }
}

void deleteAccount(int accountNumber) {
    Account account;
    ifstream inputFile;
    ofstream outputFile;
    inputFile.open("info.dat", ios::binary);

    if (!inputFile) {
        cout << "File could not be opened! Press any key...";
        return;
    }

    outputFile.open("Temp.dat", ios::binary);
    inputFile.seekg(0, ios::beg);

    while (inputFile.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() != accountNumber) {
            outputFile.write(reinterpret_cast<char*>(&account), sizeof(Account));
        }
    }

    inputFile.close();
    outputFile.close();
    remove("info.dat");
    rename("Temp.dat", "info.dat");
    cout << "\n\n\tRecord Deleted ..";
}

void displayAllAccounts() {
    Account account;
    ifstream file;
