#pragma once
#include <iostream>
#include <cstring>
#include <conio.h>

class MyString {
    int length; // Number of characters in the string
    char* data;
    static const int npos = -1;

public:
    MyString();
    MyString(const char* str);
    MyString(const MyString& str);
    ~MyString();
    MyString& operator=(const MyString& str);

    // ITERATORS
    class iterator {
    public:
        typedef char value_type;
        typedef char& reference;
        typedef std::forward_iterator_tag iterator_category;
        typedef int difference_type;

        iterator(char* ptr) : pointer(ptr) { }
        iterator operator++(int) { iterator temp = *this; pointer++; return temp; }
        iterator operator++() { pointer++; return *this; }
        reference operator*() { return *pointer; }
        char* operator->() { return pointer; }
        bool operator==(const iterator& rhs) const { return pointer == rhs.pointer; }
        bool operator!=(const iterator& rhs) const { return pointer != rhs.pointer; }

    private:
        char* pointer;
    };

    class const_iterator {
    public:
        typedef char value_type;
        typedef const char& reference;
        typedef int difference_type;

        const_iterator(const char* ptr) : pointer(ptr) { }
        const_iterator operator++(int) { const_iterator temp = *this; pointer++; return temp; }
        const_iterator operator++() { pointer++; return *this; }
        const reference operator*() const { return *pointer; }
        const char* operator->() const { return pointer; }
        bool operator==(const const_iterator& rhs) const { return pointer == rhs.pointer; }
        bool operator!=(const const_iterator& rhs) const { return pointer != rhs.pointer; }

    private:
        const char* pointer;
    };

    class reverse_iterator {
    public:
        typedef char value_type;
        typedef char& reference;
        typedef std::random_access_iterator_tag iterator_category;
        typedef int difference_type;

        reverse_iterator(char* ptr) : pointer(ptr) { }
        reverse_iterator operator--(int) { reverse_iterator temp = *this; pointer--; return temp; }
        reverse_iterator operator--() { pointer--; return *this; }
        reference operator*() { return *pointer; }
        char* operator->() { return pointer; }
        bool operator==(const reverse_iterator& rhs) const { return pointer == rhs.pointer; }
        bool operator!=(const reverse_iterator& rhs) const { return pointer != rhs.pointer; }

    private:
        char* pointer;
    };

    class const_reverse_iterator {
    public:
        typedef char value_type;
        typedef const char& reference;
        typedef std::random_access_iterator_tag iterator_category;
        typedef int difference_type;

        const_reverse_iterator(const char* ptr) : pointer(ptr) { }
        const_reverse_iterator operator--(int) { const_reverse_iterator temp = *this; pointer--; return temp; }
        const_reverse_iterator operator--() { pointer--; return *this; }
        reference operator*() const { return *pointer; }
        const char* operator->() const { return pointer; }
        bool operator==(const const_reverse_iterator& rhs) const { return pointer == rhs.pointer; }
        bool operator!=(const const_reverse_iterator& rhs) const { return pointer != rhs.pointer; }

    private:
        const char* pointer;
    };

    iterator begin() { return iterator(data); }
    iterator end() { return iterator(data + length); }
    reverse_iterator rbegin() { return reverse_iterator(data + length - 1); }
    reverse_iterator rend() { return reverse_iterator(data - 1); }
    const_iterator cbegin() const { return const_iterator(data); }
    const_iterator cend() const { return const_iterator(data + length); }
    const_iterator crbegin() const { return const_iterator(data + length - 1); }
    const_iterator crend() const { return const_iterator(data - 1); }

    // CAPACITY
    void clear();
    bool empty() const;
    int length() const;
    int size() const;
    MyString resize(int newSize);
    void Input();
    void Output();

    // ELEMENT ACCESS
    char operator[](int index) const;
    char at(int index) const;
    char back() const;
    char front() const;

    // MODIFIERS
    MyString operator+=(const MyString& str);
    MyString& operator+=(const char* s);
    MyString& operator+=(char c);

    void push_back(char c);
    MyString append(const MyString& str);
    MyString& replace(size_t pos, size_t len, char c);
    MyString replace(int pos, int len, const MyString& str);
    MyString replace(int pos, int len, const char* s);
    MyString insert(int pos, char c);
    MyString insert(int pos, const MyString& str);
    void pop_back();
    void swap(MyString& str);
    void assign(char x, int i); // Assign character x to index i
    MyString erase(int pos, int len);
    MyString erase(int pos); // Remove character at index pos

    // STRING OPERATIONS
    const char* c_str() const;
    const char* data() const;
    int copy(char*& s, int len, int pos = 0);
    int find(char c, int pos = 0) const;
    int find(const MyString& str, int pos = 0) const;
    int find(const char* s, size_t pos = 0) const;
    size_t rfind(const MyString& str, size_t pos = npos) const;
    size_t find_first_of(char c, size_t pos = 0) const;
    size_t find_first_of(const MyString& str, size_t pos = 0) const;
    size_t find_first_of(const char* s, size_t pos = 0) const;
    size_t find_last_of(char c, size_t pos = npos) const;
    size_t find_last_of(const MyString& str, size_t pos = npos) const;
    size_t find_last_of(const char* s, size_t pos = npos) const;
    size_t find_first_not_of(char c, size_t pos = 0) const;
    size_t find_first_not_of(const MyString& str, size_t pos = 0) const;
    size_t find_first_not_of(const char* s, size_t pos = 0) const;
    size_t find_last_not_of(char c, size_t pos = npos) const;
    size_t find_last_not_of(const MyString& str, size_t pos = npos) const;
    size_t find_last_not_of(const char* s, size_t pos = npos) const;
    char compare(const MyString& str) const;
    MyString substr(size_t pos = 0, size_t len = npos) const;

    // NON-MEMBER FUNCTION OVERLOADS
    MyString operator+(const MyString& str) const;
    bool operator>(const MyString& str) const;
    bool operator>=(const MyString& str) const;
    bool operator<(const MyString& str) const;
    bool operator<=(const MyString& str) const;
    bool operator==(const MyString& str) const;
    bool operator!=(const MyString& str) const;

    friend void swap(MyString& x, MyString& y);
    friend std::istream& operator>>(std::istream& is, MyString& str);
    friend std::ostream& operator<<(std::ostream& os, const MyString& str);
    friend std::istream& getline(std::istream& is, MyString& str);
    friend std::istream& getline(std::istream& is, MyString& str, char delim);
};

