    if (startPtr == nullptr) {
        cerr << "Cannot delete from an empty list.\n";
        return;
    }

    if (startPtr->receiptNumber == receiptNumber) {
        OrderNode* temp = startPtr;
        startPtr = startPtr->next;
        delete temp;
        cout << "The Receipt is Deleted Successfully" << endl;
        return;
    }

    while (currentOrder != nullptr && !found) {
        if (currentOrder->receiptNumber == receiptNumber) {
            found = true;
        } else {
            previousOrder = currentOrder;
            currentOrder = currentOrder->next;
        }
    }

    if (found) {
        previousOrder->next = currentOrder->next;
        delete currentOrder;
        cout << "The Receipt is Deleted Successfully" << endl;
    } else {
        cout << "Item to be deleted is not in the list." << endl;
    }
}

