void MovieBooking::bookTickets(int movieIndex, int showTimeIndex, int mode) {
    char rowLabel;
    int columnIndex;
    cout << "\n\n\t\t\t\t\tENTER THE SEAT NUMBER: ";
    cin >> rowLabel >> columnIndex;
    int rowIndex = rowLabel - 'A';
    columnIndex--;

    if (seatAvailability[selectedHallIndex][movieIndex][showTimeIndex][rowIndex][columnIndex] == 0) {
        seatAvailability[selectedHallIndex][movieIndex][showTimeIndex][rowIndex][columnIndex] = 1;
    } else {
        while (seatAvailability[selectedHallIndex][movieIndex][showTimeIndex][rowIndex][columnIndex] != 0) {
            if (mode == 100) {
                cout << "\n\n\t\t\t\t\tADMIN, THIS SEAT IS ALREADY BOOKED. ENTER A NEW SEAT: ";
            } else {
                cout << "\n\n\t\t\t\t\tTHE SEAT YOU SELECTED IS ALREADY OCCUPIED. ENTER A NEW SEAT: ";
            }
            cin >> rowLabel >> columnIndex;
            rowIndex = rowLabel - 'A';
            columnIndex--;
        }
        seatAvailability[selectedHallIndex][movieIndex][showTimeIndex][rowIndex][columnIndex] = 1;
    }
}

void MovieBooking::reserveSeat(int movieIndex, int showTimeIndex) {
    int numberOfSeats;
    cout << "\n\n\t\t\t\t\tENTER THE NUMBER OF SEATS TO BE BOOKED: ";
    cin >> numberOfSeats;

    for (ticketCount = 0; ticketCount < numberOfSeats; ticketCount++) {
        bookTickets(movieIndex, showTimeIndex, 20);
        system("cls");
        displaySeatMatrix(movieIndex, showTimeIndex);
    }
    cout << "\n\n\t\t\t\t\tPRESS ANY KEY TO CONTINUE\n";
    system("cls");
}

