int MovieBooking::verifyPassword() {
    cout << "\n\n\t\t\t\t\t\t\tENTER YOUR USER ID\n";
    cin >> customerId;

    ifstream userFile("database1.csv");
    string user, password;
    while (getline(userFile, user, ',') && getline(userFile, user, ',') && getline(userFile, user, ',') && getline(userFile, password, '\n')) {
        if (user == customerId) {
            foundUser++;
            cout << "\n\n\t\t\t\t\t\t\tUSER ID FOUND\n";
            break;
        }
    }

    if (foundUser == 0) {
        cout << "\n\n\t\t\t\t\t\t\tUSER ID NOT FOUND\n";
        userFile.close();
        return 0;
    } else {
        cout << "\n\n\t\t\t\t\t\t\tENTER YOUR USER PASSWORD\n";
        cin >> customerPassword;

        userFile.clear();
        userFile.seekg(0, ios::beg);
        while (getline(userFile, user, ',') && getline(userFile, user, ',') && getline(userFile, user, ',') && getline(userFile, password, '\n')) {
