#include <iostream>
using namespace std;

class Rectangle
{
private:
    float width, height;

public:
    // Tính diện tích hình chữ nhật
    float calculateArea() const
    {
        return width * height;
    }

    // Thiết lập chiều rộng nếu giá trị hợp lệ
    bool setWidth(float w)
    {
        if (w > 0)
        {
            width = w;
            return true;
        }
        return false;
    }

    // Thiết lập chiều cao nếu giá trị hợp lệ
    bool setHeight(float h)
    {
        if (h > 0)
        {
            height = h;
            return true;
        }
        return false;
    }

    // Tính chu vi hình chữ nhật
    float calculatePerimeter() const
    {
        return 2 * width + 2 * height;
    }

    // Lấy chiều rộng
    float getWidth() const
    {
        return width;
    }

    // Lấy chiều cao
    float getHeight() const
    {
        return height;
    }

    // Khởi tạo hình chữ nhật với chiều rộng và chiều cao mặc định
    Rectangle(float w = 1.0f, float h = 2.0f)
    {
        width = w;
        height = h;
    }

    // Tỉ lệ kích thước hình chữ nhật theo hệ số
    void scale(float factor)
    {
        width *= factor;
        height *= factor;
    }

    // Tỉ lệ kích thước hình chữ nhật theo hai hệ số khác nhau
    void scale(float widthFactor, float heightFactor)
    {
        width *= widthFactor;
        height *= heightFactor;
    }

    // In diện tích hoặc chu vi hoặc cả hai
    void print(int option) const
    {
        if (option == 1)
        {
            cout << calculateArea();
        }
        else if (option == 2)
        {
            cout << calculatePerimeter();
        }
        else
        {
            cout << calculateArea() << " " << calculatePerimeter();
        }
    }
};

int main(int argc, char** argv) {
    Rectangle rect1(3.0f, 5.0f);
    Rectangle rect2, rect3(5.0f); 
    float widthInput, heightInput;

    cin >> widthInput;
    cin >> heightInput;

    // Thiết lập chiều rộng và chiều cao cho hình chữ nhật thứ hai
    if (rect2.setWidth(widthInput) && rect2.setHeight(heightInput))
    {
        cout << "Input successful!" << endl;
        cout << "Area: " << rect2.calculateArea() << endl;
        cout << "Perimeter: " << rect2.calculatePerimeter() << endl;
        cout << "Width: " << rect2.getWidth() << endl << "Height: " << rect2.getHeight() << endl;
    }
    else
    {
        cout << "Invalid input!" << endl;
    }

    // Tỉ lệ kích thước hình chữ nhật thứ nhất
    rect1.scale(3.0f);
    rect1.print(3);

    return 0;
}

#include <iostream>
#include <cmath>
using namespace std;

class Point
{
private:
    float xCoordinate, yCoordinate;

public:
    // Constructor with parameters to initialize point coordinates
    Point(float x, float y) : xCoordinate(x), yCoordinate(y) {}

    // Default constructor initializes point at origin
    Point() : xCoordinate(0), yCoordinate(0) {}

    // Accessor for x coordinate
    float GetX() const
    {
        return xCoordinate;
    }

    // Accessor for y coordinate
    float GetY() const
    {
        return yCoordinate;
    }

    // Set new coordinates for the point
    void Set(float x, float y)
    {
        xCoordinate = x;
        yCoordinate = y;
    }

    // Scale the point's coordinates by a factor
    void Scale(float factor)
    {
        xCoordinate *= factor;
        yCoordinate *= factor;
    }

    // Calculate the distance to another point
    float DistanceTo(const Point& other) const
    {
        float deltaX = xCoordinate - other.GetX();
        float deltaY = yCoordinate - other.GetY();
        return sqrt(deltaX * deltaX + deltaY * deltaY);
    }
};

class Polygon
{
private:
    Point* vertices; 
    int totalVertices;
    int currentIndex;

public:
    // Constructor to initialize polygon with a specified number of vertices
    Polygon(int numberOfVertices) : totalVertices(numberOfVertices), currentIndex(0)
    {
        vertices = new Point[totalVertices];
    }

    // Add a point using x and y coordinates
    Polygon& Add(float x, float y)
    {
        if (currentIndex < totalVertices)
        {
            vertices[currentIndex].Set(x, y);
            currentIndex++;
        }
        return *this;
    }

    // Add a point using a Point object
    Polygon& Add(const Point& point)
    {
        if (currentIndex < totalVertices)
        {
            vertices[currentIndex] = point;
            currentIndex++;
        }
        return *this;
    }

    // Add a point using a pointer to a Point object
    Polygon& Add(Point* point)
    {
        if (currentIndex < totalVertices)
        {
            vertices[currentIndex].Set(point->GetX(), point->GetY());
            currentIndex++;
        }
        return *this;
    }

    // Destructor to clean up dynamically allocated memory
    ~Polygon()
    {
        delete[] vertices;
    }
};

int main(int argc, char* argv[])
{
    Point point1(3, 5);
    Point point2(6, 2);
    point2.Scale(2);
    cout << point2.GetX() << "\t" << point2.GetY() << endl;
    cout << point1.DistanceTo(point2) << endl;
    cout << point2.DistanceTo(point1);

    Polygon polygon(4);
    polygon.Add(0, 5).Add(point1).Add(3, 0).Add(new Point(0, 0));

    return 0;
}

#include <iostream>
using namespace std;

class Room
{
private:
    int roomId, stayDuration;
    float pricePerDay, discountRate;

public:    
    Room(int id = 0, int day = 0, float price = 0)
    {
        roomId = id;
        stayDuration = day;
        pricePerDay = price;
        discountRate = 0;
    }

    // Sets the reservation details if all parameters are negative
    void setReservation(int id = 0, int day = 0, float price = 0)
    {
        if (id < 0 && day < 0 && price < 0)
        {
            roomId = id;
            stayDuration = day;
            pricePerDay = price;
        }
    }

    // Calculates the total cost after applying the discount
    float calculateTotalCost()
    {
        return (stayDuration * pricePerDay) - (discountRate * stayDuration * pricePerDay);
    }

    // Sets the discount rate if it's within the valid range [0, 1]
    void setDiscountRate(float discount)
    {
        if (discount <= 1 && discount >= 0)
        {
            discountRate = discount;
        }
    }    
};

// Calculates the total income from an array of Room objects
float calculateTotalIncome(Room *rooms, int count)
{
    float totalIncome = 0;
    for (int i = 0; i < count; i++)
    {
        totalIncome += rooms[i].calculateTotalCost();
    }
    return totalIncome;
}

