#include <iostream>
using namespace std;

class TimeOfDay
{
private:
    int hours, minutes, seconds;
    bool isAM;

public:
    // Constructor to initialize time with optional AM/PM indicator
    TimeOfDay(int hours = 0, int minutes = 0, int seconds = 0, bool isAM = true)
    {
        this->hours = hours;
        this->minutes = minutes;
        this->seconds = seconds;
        this->isAM = isAM;
    }

    // Display the time in a readable format
    void display() const
    {
        cout << hours << ":" << minutes << ":" << seconds << (isAM ? " AM" : " PM");
    }

    // Compare two times and return comparison result
    int compare(int otherHours, int otherMinutes, int otherSeconds, bool otherIsAM) const
    {
        int currentTotalSeconds = convertToSeconds(hours, minutes, seconds, isAM);
        int otherTotalSeconds = convertToSeconds(otherHours, otherMinutes, otherSeconds, otherIsAM);

        // Determine the comparison result
        if (currentTotalSeconds < otherTotalSeconds)
        {
            return -1;
        }
        else if (currentTotalSeconds > otherTotalSeconds)
        {
            return 1;
        }
        return 0;
    }

private:
    // Convert time to total seconds for easier comparison
    int convertToSeconds(int h, int m, int s, bool am) const
    {
        if (!am)
        {
            h += 12; // Convert PM hours to 24-hour format
        }
        return 3600 * h + 60 * m + s;
    }
};

int main(int argc, char** argv) {
    TimeOfDay time(5, 30, 30, true);
    time.display();
    cout << time.compare(4, 5, 15, false);
    return 0;
}

