/*
  Structure for storing room information.
*/
struct Room {
    int roomNumber;
    char status;
} roomInfo;

/*
  Structure for storing food item information.
*/
struct FoodItem {
    char name[20];
    float cost;
} food;

/*
  Allocates a room number for a customer.
*/
int allocateRoom() {
    fstream roomFile;
    int roomNumber = 0;
    roomFile.open("rallot.dat", ios::in | ios::binary | ios::out);

    while (roomFile.read((char*)&roomInfo, sizeof(roomInfo))) {
        int position = roomFile.tellg() - sizeof(roomInfo);
        if (roomInfo.status == 'e') {
            roomNumber = roomInfo.roomNumber;
            roomInfo.status = 'f';
            roomFile.seekg(position);
            roomFile.write((char*)&roomInfo, sizeof(roomInfo));
            break;
        }
    }
    roomFile.close();
    return roomNumber;
}

/*
  Calculates the total food bill for a given room number.
*/
long double calculateFoodBill(int roomNumber) {
    float total = 0;
    char roomFileName[20], extension[] = ".txt";

    sprintf(roomFileName, "%d", roomNumber);
    strcat(roomFileName, extension);

    fstream itemFile(roomFileName, ios::out | ios::in);

    while (itemFile.read((char*)&food, sizeof(food))) {
        total += food.cost;
    }

    return total;
}

/*
  Clears the room after a customer checks out.
*/
void clearRoom(int roomNumber) {
    fstream roomFile("rallot.dat", ios::in | ios::binary | ios::out);
    char roomFileName[20], extension[] = ".txt";

    sprintf(roomFileName, "%d", roomNumber);
    strcat(roomFileName, extension);
    remove(roomFileName);

    while (roomFile.read((char*)&roomInfo, sizeof(roomInfo))) {
        int position = roomFile.tellg() - sizeof(roomInfo);
        if (roomInfo.roomNumber == roomNumber) {
            roomInfo.status = 'e';
            roomFile.seekg(position);
            roomFile.write((char*)&roomInfo, sizeof(roomInfo));
            break;
        }
    }
    roomFile.close();
}

/*
  Calculates the number of days between two dates.
*/
int calculateDays(int startDate[], int endDate[]) {
    int monthDays[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int totalDaysStart = 0, totalDaysEnd = 0;

    for (int i = 0; i < (startDate[1] - 1); i++)
        totalDaysStart += monthDays[i];

    long double startDays = (startDate[2] * 365) + totalDaysStart + startDate[0];

    for (int i = 0; i < (endDate[1] - 1); i++)
        totalDaysEnd += monthDays[i];

    long double endDays = (endDate[2] * 365) + totalDaysEnd + endDate[0];

    return endDays - startDays;
}

