                                        getch();
                                        break;
                                    } else break;
                                }
                            }
                            break;
                    }
                    if (foodMenuOption == 16) break;
                }
                break;

            // Customer services menu
            case 12: 
                while (1) {
                    customerServiceFlag = 0;
                    customerMenuOption = 11;
                    while (customerServiceFlag != 1) {
                        displayCustomerMenu();
                        handleCustomerMenuInput();
                        delay(200);
                    }

                    switch (customerMenuOption) {
                        case 11: 
                            while (1) {
                                vacantRoomFlag = 0;
                                customerService.checkIn();
                                if (vacantRoomFlag == 0) {
                                    cout << "\nDo you want to add another record? (y/n): ";
                                    char choice[5]; gets(choice);
                                    if (choice[0] == 'y') continue;
                                    else break;
                                } else break;
                            }
                            break;

                        case 12: 
                            while (1) {
                                customerService.displayCustomerDetails();
                                cout << "\n\nDo you want to view another record? (y/n): ";
                                char choice[5]; gets(choice);
                                if (choice[0] == 'y') continue;
