class Room {
    int roomNumber;
    char status;

public:
    // Adds a new room with its status
    void add() {
        int inputRoomNumber;
        char inputStatus;

        std::cout << "Enter room number: ";
        std::cin >> inputRoomNumber;
        std::cout << "Enter status: ";
        std::cin >> inputStatus;

        status = inputStatus;
        roomNumber = inputRoomNumber;
    }

    // Displays the room number and its status
    void show() const {
        std::cout << roomNumber << "\t" << status;
    }
};

int main() {
    std::fstream file;

    // Remove existing data file and create a new one
    remove("room_allocation.dat");
    file.open("room_allocation.dat", std::ios::out | std::ios::binary);

    // Loop to add multiple rooms
    while (true) {
        system("cls"); // Clear the console
        Room room;
        room.add();
        file.write(reinterpret_cast<char*>(&room), sizeof(room));

        std::cout << "Do you want to add more items? (y/n): ";
        char userResponse[5];
        std::cin >> userResponse;

        if (userResponse[0] == 'n') {
            break;
        }
    }

    file.close();

    // Open the file to read and display room data
    file.open("room_allocation.dat", std::ios::in);
    Room room;
    while (file.read(reinterpret_cast<char*>(&room), sizeof(room))) {
        room.show();
        std::cout << std::endl;
    }

    file.close();
    return 0;
}

