void showStudent(int scholarNumber) {
    studentFile.open("stu.txt", ios::in);
    while (studentFile.read(reinterpret_cast<char*>(&student), sizeof(Student))) {
        if (student.getScholarNumber() == scholarNumber) {
            student.displayDetails();
            break;
        }
    }
    studentFile.close();
}

void showBook(int bookNumber) {
    bookFile.open("book.txt", ios::in);
    while (bookFile.read(reinterpret_cast<char*>(&book), sizeof(BookInfo))) {
        if (book.getBookNumber() == bookNumber) {
            book.displayDetails();
            break;
        }
    }
    bookFile.close();
}

int checkIssueLimit(int scholarNumber) {
    int issuedScholarNumber, issuedBookNumber;
    int count = 0;
    issueFile.open("issue.txt", ios::in);
    while (issueFile >> issuedScholarNumber && issueFile.ignore() && issueFile >> issuedBookNumber) {
        if (scholarNumber == issuedScholarNumber) {
            count++;
        }
    }
    issueFile.close();
    return count < 3;
}

void issueBook() {
    int scholarNumber, bookNumber;
    cout << "Enter scholar number: ";
    cin >> scholarNumber;
    if (checkIssueLimit(scholarNumber)) {
        outputFile.open("issue.txt", ios::out | ios::app);
        outputFile << scholarNumber << ":";
        cout << "Enter book number: ";
        cin >> bookNumber;
        outputFile << bookNumber << endl;
        cout << "Successful" << endl;
        outputFile.close();
    } else {
        cout << "Sorry! It exceeds the limit." << endl;
    }
}

void depositBook(int scholarNumber, int bookNumber) {
    int issuedScholarNumber, issuedBookNumber;
    issueFile.open("issue.txt", ios::in);
    outputFile.open("temp.txt", ios::out | ios::app);
    while (issueFile >> issuedScholarNumber && issueFile.ignore() && issueFile >> issuedBookNumber) {
        if (issuedScholarNumber == scholarNumber && issuedBookNumber == bookNumber) {
            showStudent(scholarNumber);
            showBook(bookNumber);
        } else {
            outputFile << issuedScholarNumber << ":" << issuedBookNumber << endl;
        }
    }
    issueFile.close();
    outputFile.close();
    remove("issue.txt");
    rename("temp.txt", "issue.txt");
}

void modifyStudent(int scholarNumber) {
    long position;
    studentFile.open("stu.txt", ios::in);
    studentTempFile.open("stu.txt", ios::out | ios::app);
    while (studentFile.read(reinterpret_cast<char*>(&student), sizeof(Student))) {
        position = studentFile.tellg();
        if (scholarNumber == student.getScholarNumber()) {
            student.modifyDetails();
            studentTempFile.seekp(position);
            studentTempFile.write(reinterpret_cast<char*>(&student), sizeof(Student));
            break;
        }
    }
    studentFile.close();
    studentTempFile.close();
}

void modifyBook(int bookNumber) {
    int position;
    bookFile.open("book.txt", ios::in);
    bookTempFile.open("book.txt", ios::out | ios::app);
    while (bookFile.read(reinterpret_cast<char*>(&book), sizeof(BookInfo))) {
        position = bookFile.tellg();
        if (bookNumber == book.getBookNumber()) {
            book.modifyDetails();
            bookTempFile.seekp(position);
            bookTempFile.write(reinterpret_cast<char*>(&book), sizeof(BookInfo));
            break;
        }
    }
    bookFile.close();
    bookTempFile.close();
}

