// Struct representing a book with its attributes
struct Book {
    int isbn;
    string title;
    string author;
    double price;
    int year;
    string subject;
    string language;

    Book() {}

    Book(int isbn, string title, string author, double price, int year, string subject, string language) 
        : isbn(isbn), title(title), author(author), price(price), year(year), subject(subject), language(language) {}

    // Concatenates title and author for display purposes
    string getAuthorAndTitle() const {
        return title + ", " + author;
    }
};

// Comparator for sorting books by price
struct PriceComparator {
    bool operator()(const Book& b1, const Book& b2) const {
        return b1.price < b2.price;
    }
};

// Comparator for sorting books by title and author
struct TitleAuthorComparator {
    bool operator()(const Book& b1, const Book& b2) const {
        return b1.getAuthorAndTitle() < b2.getAuthorAndTitle();
    }
};

// Function prototypes
void displayMenu(int& flag);
void addBooks(vector<Book>& books, int numBooks);
void inputSearchISBN(int& isbnSearch);
void inputSearchTitle(string& titleSearch);
void searchBookByISBN(int id, const vector<Book>& books);
void searchBookByTitle(const string& title, const vector<Book>& books);
void displayBooks(const vector<Book>& books);
void loadOldBooks(vector<Book>& oldBooks, const vector<Book>& books);
void displayOldBooks(const vector<Book>& oldBooks);

int main() {
    int numBooks = 0;
    int isbnSearch;
    string titleSearch;
    int flag = 0;

    cout << "Please enter the number of books you want to add to the library: ";
    cin >> numBooks;

    vector<Book> books;
    vector<Book> oldBooks;

    do {
        displayMenu(flag);
        switch (flag) {
            case 1:
                addBooks(books, numBooks);
                break;
            case 2:
                inputSearchISBN(isbnSearch);
                searchBookByISBN(isbnSearch, books);
                break;
            case 3:
                inputSearchTitle(titleSearch);
                searchBookByTitle(titleSearch, books);
                break;
            case 4:
                displayBooks(books);
                break;
            case 5:
                cout << "\nSorting books by title and author...\n";
                sort(books.begin(), books.end(), TitleAuthorComparator());
                displayBooks(books);
                break;
            case 6:
                cout << "\nSorting books by price...\n";
                sort(books.begin(), books.end(), PriceComparator());
                displayBooks(books);
                break;
            case 7:
                loadOldBooks(oldBooks, books);
                break;
            case 8:
                displayOldBooks(oldBooks);
                break;
            case 9:
                break;
        }
    } while (flag < 9);

    system("pause");
    return 0;
}

