// Overloaded input operator for Book
istream& operator>>(istream& inStream, Book& aBook) {
    cout << "\nPlease enter the following information about the book: ";
    cout << "\nISBN: ";
    inStream >> aBook.isbn;
    inStream.ignore();

    cout << "\nTitle: ";
    getline(inStream, aBook.title);

    cout << "\nAuthor: ";
    getline(inStream, aBook.author);

    cout << "\nPrice: ";
    inStream >> aBook.price;

    cout << "\nYear: ";
    inStream >> aBook.year;
    inStream.ignore();

    cout << "\nSubject: ";
    getline(inStream, aBook.subject);

    cout << "\nLanguage: ";
    getline(inStream, aBook.language);

    return inStream;
}

// Overloaded output operator for Book
ostream& operator<<(ostream& outStream, const Book& aBook) {
    outStream << "ISBN: " << aBook.isbn <<
              "\nTitle: " << aBook.title <<
              "\nAuthor: " << aBook.author <<
              "\nPrice: " << aBook.price <<
              "\nYear: " << aBook.year <<
              "\nSubject: " << aBook.subject <<
              "\nLanguage: " << aBook.language;
    return outStream;
}

// Adds books to the library
void addBooks(vector<Book>& books, int numBooks) {
    system("cls");
    for (int i = 0; i < numBooks; ++i) {
        Book newBook;
        cin >> newBook;
        books.push_back(newBook);
    }
}

// Prompts user for ISBN search input
void inputSearchISBN(int& isbnSearch) {
    cout << "\nPlease enter the book's ISBN: ";
    cin >> isbnSearch;
}

// Prompts user for title search input
void inputSearchTitle(string& titleSearch) {
    cout << "\nPlease enter the book's title: ";
    cin.ignore();
    getline(cin, titleSearch);
}

// Searches for a book by its ISBN
void searchBookByISBN(int id, const vector<Book>& books) {
    auto it = find_if(books.begin(), books.end(), [id](const Book& book) { return book.isbn == id; });

    if (it != books.end()) {
        cout << *it << endl;
    } else {
        cout << "Record NOT FOUND, please try with another ISBN." << endl;
    }
    system("pause");
}

// Searches for a book by its title
void searchBookByTitle(const string& title, const vector<Book>& books) {
    auto it = find_if(books.begin(), books.end(), [&title](const Book& book) { return book.title == title; });

    if (it != books.end()) {
        cout << *it << endl;
    } else {
        cout << "Title NOT FOUND, please try with another one." << endl;
    }
    system("pause");
}

// Displays all books in the library
void displayBooks(const vector<Book>& books) {
    system("cls");
    for (const auto& book : books) {
        cout << book << endl;
    }
    system("pause");
}

// Loads books published in 2014 or earlier into a separate collection
void loadOldBooks(vector<Book>& oldBooks, const vector<Book>& books) {
    for (const auto& book : books) {
        if (book.year < 2015) {
            oldBooks.push_back(book);
        }
    }
    cout << "\nThe new room has been created for old books." << endl;
}

// Displays all old books
void displayOldBooks(const vector<Book>& oldBooks) {
    for (const auto& book : oldBooks) {
        cout << book << endl;
    }
    system("pause");
}

