#include <iostream>
#include <array>
#include <memory>
#include <algorithm>

using namespace std;

template <class T>
class Matrix
{
    array<int, 2> dimensions; // Two dimensions of the matrix
    T* elements;              // Pointer to the elements of type T

public:
    Matrix() : dimensions{{0, 0}}, elements{new T[0]} {}

    Matrix(int rows, int cols) : dimensions{{rows, cols}}, elements{new T[rows * cols]}
    {
        cout << "Matrix constructor" << endl;
    }

    int size() const { return dimensions[0] * dimensions[1]; }

    // Copy constructor
    Matrix(const Matrix& other) : dimensions(other.dimensions), elements(new T[other.size()])
    {
        uninitialized_copy(other.elements, other.elements + other.size(), elements);
        cout << "Copy constructor" << endl;
    }

    // Copy assignment operator
    Matrix& operator=(const Matrix& other)
    {
        Matrix temp{other}; // Create a copy using the copy constructor

        if (dimensions[0] != other.dimensions[0] || dimensions[1] != other.dimensions[1])
        {
            throw runtime_error("Incompatible sizes in Matrix assignment");
        }

        swap(temp.dimensions, dimensions);
        copy(other.elements, other.elements + other.size(), elements);

        cout << "Copy assignment" << endl;
        return *this;
    }

    // Move constructor
    Matrix(Matrix&& other) noexcept : dimensions(other.dimensions), elements(other.elements)
    {
        other.dimensions = {0, 0};
        other.elements = nullptr;
        cout << "Move constructor" << endl;
    }

    // Move assignment operator
    Matrix& operator=(Matrix&& other) noexcept
    {
        swap(dimensions, other.dimensions);
        swap(elements, other.elements);
        cout << "Move assignment" << endl;
        return *this;
    }

    // Generic swap function
    template<class R>
    void swap(R& a, R& b)
    {
        R temp = std::move(a);
        a = std::move(b);
        b = std::move(temp);
    }

    ~Matrix()
    {
        delete[] elements; // Clean up allocated memory
    }
};

int main()
{
    Matrix<int> matrix(7, 10);
    cout << "Matrix1 has " << matrix.size() << " elements\n" << endl;

    Matrix<int> matrix2(matrix);
    cout << "Matrix2 has " << matrix2.size() << " elements\n" << endl;

    Matrix<int> matrix4 = matrix2;
    cout << "Matrix4 has " << matrix4.size() << " elements\n" << endl;

    Matrix<int> matrix3(7, 10);
    matrix3 = matrix2;
    cout << "Matrix3 has " << matrix3.size() << " elements\n" << endl;

    return 0;
}

#include <iostream>

using namespace std;

// Abstract base class that defines an interface for derived classes
class Base {
public:
    Base() { cout << "+ Constructor from Base class" << endl; }
    virtual ~Base() { cout << "- Destructor from Base class" << endl; }

    // Pure virtual function to be implemented by derived classes
    virtual void name() = 0;
};

// Derived class that implements the Base interface
class Derived : public Base {
public:
    Derived() : Base() { cout << "+ Constructor from Derived class" << endl; }
    ~Derived() { cout << "- Destructor from Derived class" << endl; }

    // Implementation of the pure virtual function from Base
    virtual void name() { cout << "Class name: Derived" << endl; }
};

int main() {
    // Base class cannot be instantiated due to the abstract method
    // Base* b1 = new Base(); // Uncommenting this line will cause a compilation error

    cout << endl;

    // Create an instance of the Derived class and invoke its method
    Derived* d1 = new Derived();
    d1->name();

    // Clean up the allocated memory
    delete d1;

    return 0;
}

#include <iostream>
#include <typeinfo>
#include <vector>

using namespace std;

class Circle;
class Triangle;

// Abstract base class representing a geometric shape
class Shape {
public:
    virtual bool intersect(const Shape&) const = 0;
    virtual bool intersect(const Circle&) const = 0;
    virtual bool intersect(const Triangle&) const = 0;
};

// Class representing a circle shape
class Circle : public Shape {
public:
    bool intersect(const Shape&) const override { return true; }
    bool intersect(const Circle&) const override { return true; }
    bool intersect(const Triangle&) const override { return true; }
};

// Class representing a triangle shape
class Triangle : public Shape {
public:
    bool intersect(const Shape&) const override { return true; }
    bool intersect(const Circle&) const override { return true; }
    bool intersect(const Triangle&) const override { return true; }
};

// Function to test intersection between shapes
void testIntersection(Triangle& triangle, Circle& circle) {
    vector<pair<Shape*, Shape*>> shapePairs = { {&triangle, &triangle}, {&triangle, &circle}, {&circle, &circle} };

    // Iterate through each pair of shapes to check for intersection
    for (const auto& shapePair : shapePairs) {
        if (shapePair.first->intersect(*shapePair.second)) {
            cout << typeid(shapePair.first).name() << " intersects with " << typeid(shapePair.second).name() << endl;
        }
    }
}

int main() {
    Triangle triangle;
    Circle circle;
    testIntersection(triangle, circle);

    return 0;
}

