#include <iostream>

using namespace std;

struct ConvertibleA
{
    ConvertibleA(int) {} // Constructor for single integer parameter
    ConvertibleA(int, int) {} // Constructor for two integer parameters (C++11)
    operator int() const { return 0; } // Conversion operator to int
};

struct ExplicitB
{
    explicit ExplicitB(int) {} // Explicit constructor for single integer parameter
    explicit ExplicitB(int, int) {} // Explicit constructor for two integer parameters
    explicit operator int() const { return 0; } // Explicit conversion operator to int
};

class String
{
public:
    explicit String(int d) { std::cout << "Constructor with int parameter" << std::endl; }
    String(const char* ptr) { std::cout << "Constructor with char* parameter" << std::endl; }
};

int main()
{
    ConvertibleA instanceA1 = 1; // OK: copy-initialization selects ConvertibleA::ConvertibleA(int)
    ConvertibleA instanceA2(2); // OK: direct-initialization selects ConvertibleA::ConvertibleA(int)
    ConvertibleA instanceA3 {4, 5}; // OK: direct-list-initialization selects ConvertibleA::ConvertibleA(int, int)
    ConvertibleA instanceA4 = {4, 5}; // OK: copy-list-initialization selects ConvertibleA::ConvertibleA(int, int)
    int numberA1 = instanceA1; // OK: copy-initialization selects ConvertibleA::operator int()
    int numberA2 = static_cast<int>(instanceA1); // OK: static_cast performs direct-initialization
    ConvertibleA instanceA5 = (ConvertibleA)1; // OK: explicit cast performs static_cast

//  ExplicitB instanceB1 = 1; // Error: copy-initialization does not consider ExplicitB::ExplicitB(int)
    ExplicitB instanceB2(2); // OK: direct-initialization selects ExplicitB::ExplicitB(int)
    ExplicitB instanceB3 {4, 5}; // OK: direct-list-initialization selects ExplicitB::ExplicitB(int, int)
//  ExplicitB instanceB4 = {4, 5}; // Error: copy-list-initialization does not consider ExplicitB::ExplicitB(int,int)
//  int numberB1 = instanceB2; // Error: copy-initialization does not consider ExplicitB::operator int()
    int numberB2 = static_cast<int>(instanceB2); // OK: static_cast performs direct-initialization
    ExplicitB instanceB5 = (ExplicitB)1; // OK: explicit cast performs static_cast

    String stringInstance = (const char*)'x'; // Implicit conversion from char to const char*
    // Without the explicit keyword, the compiler would convert 'x' to an integer value
    // This is known as direct initialization
}

