#include <iostream>
#include <memory>

using namespace std;

// Class representing a value box with a defined range and change tracking
class ValueBox {
protected:
    int value;
    int lowerBound, upperBound;
    bool isChanged{false};

    void markAsChanged(bool state) { isChanged = state; }

public:
    ValueBox(int lower, int upper) : value{lower}, lowerBound{lower}, upperBound{upper} {}

    virtual void displayPrompt() { cout << "Base class ValueBox" << endl; }

    virtual ~ValueBox() {}
};

// Class representing a slider that inherits from ValueBox
class ValueSlider : public ValueBox {
public:
    ValueSlider(int lower, int upper) : ValueBox(lower, upper) {}
    ~ValueSlider() {}

    virtual void displayPrompt() {
        cout << "ValueSlider()" << endl; 
        markAsChanged(true);
    }
};

// Function to interact with a ValueBox object
void interact(ValueBox* valueBox) {
    valueBox->displayPrompt();
}

int main() {
    // Use smart pointers for memory management
    unique_ptr<ValueBox> boxPtr{new ValueBox{0, 5}};
    interact(boxPtr.get());

    unique_ptr<ValueSlider> sliderPtr{new ValueSlider{0, 5}};
    interact(sliderPtr.get());

    return 0;
}

