#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Association 
{
    vector<pair<string, int>> entries;

    int defaultValue;

    // Overload the indexing operator to access or create entries
    int& operator[](const string& key) 
    {
        for (const auto& entry : entries)
        {
            if (key == entry.first)
            {
                defaultValue = entry.second;
                return defaultValue;   
            }
        }

        entries.emplace_back(key, 0);
        return entries.back().second;
    }
};

struct Accumulator
{
    int total = 10;

    // Overload the function call operator to accumulate values
    void operator()(int value)
    {
        total += value;
    }
};

class Measurement
{
private:
    int feet;   // Feet component of the distance
    int inches; // Inches component of the distance

public:
    // Default constructor initializes distance to zero
    Measurement()
    {
        feet = 0;
        inches = 0;
    }

    // Parameterized constructor for custom distance
    Measurement(int f, int i)
    {
        feet = f;
        inches = i;
    }

    // Overload the function call operator for custom distance calculation
    Measurement operator()(int a, int b, int c)
    {
        Measurement result;
        result.feet = a + c + 10; // Example calculation for feet
        result.inches = b + c + 100; // Example calculation for inches
        return result;
    }

    // Method to display the distance
    void display() const
    {
        cout << "Feet: " << feet << " Inches: " << inches << endl;
    }
};

int main()
{
    Association valueCounter;
    string input;

    // Read input and count occurrences
    while (cin >> input)
        ++valueCounter[input];

    // Display counted values
    for (const auto& entry : valueCounter.entries)
        cout << '{' << entry.first << ',' << entry.second << "}\n";

    vector<int> numbers = {1, 2, 3};

    Accumulator accumulator = std::for_each(numbers.begin(), numbers.end(), Accumulator());

    // Display accumulated values
    for (const auto& number : numbers)
        cout << number << endl;

    Measurement distance1(11, 10), distance2;

    cout << "First Distance: ";
    distance1.display();

    distance2 = distance1(10, 10, 10); // Invoke operator()
    cout << "Second Distance: ";
    distance2.display();

    return 0;
}

#include <iostream>

using namespace std;

// Represents an entity with a unique identifier.
class Entity
{
public:
    // Constructor initializes the entity with a given ID.
    Entity(int id) : id_(id)
    {
        cout << "Constructor called" << endl;
    }

    // Overloads the addition operator to combine two entities based on their IDs.
    Entity operator+(const Entity& other)
    {
        cout << "Addition operator called" << endl;
        int combinedId = id_ + other.id_;
        return Entity(combinedId);
    }

    // Overloads the compound assignment operator to add another entity's ID to this entity's ID.
    Entity& operator+=(const Entity& other)
    {
        cout << "Compound assignment operator called" << endl;
        id_ += other.getId();
        return *this;
    }

    // Overloads the output stream operator for displaying entity information.
    friend ostream& operator<<(ostream& out, const Entity& entity)
    {
        out << "\n----------------------" << endl;
        out << " ID value = " << entity.getId() << endl;
        out << "----------------------" << endl;
        return out;
    }

    // Retrieves the ID of the entity.
    inline int getId() const { return id_; }

private:
    int id_; // Unique identifier for the entity.
};

int main()
{
    Entity firstEntity(1);
    Entity secondEntity(4);
    Entity resultEntity = firstEntity + secondEntity;

    cout << resultEntity << endl;
    resultEntity += secondEntity;
    cout << resultEntity << endl;

    return 0;
}

