#include <iostream>

using namespace std;

// Abstract base class representing a generic type with polymorphic behavior
class AbstractType
{
public:
    AbstractType()
    {
        cout << "AbstractType initialized" << endl;
    }

    // Pure virtual function to return the derived type
    virtual AbstractType* getType() = 0;

    // Overloaded method to test two integer values
    int test(int firstValue, int secondValue)
    {
        cout << "Testing two integer values" << endl;
        return 0;
    }

    // Overloaded method to test three integer values
    int test(int firstValue, int secondValue, int thirdValue)
    {
        cout << "Testing three integer values" << endl;
        return 0;
    }

    // Overloaded method to test two float values
    int test(float firstValue, float secondValue)
    {
        cout << "Testing two float values" << endl;
        return 0;
    }
};

// Derived class implementing the abstract base class
class ConcreteType : public AbstractType
{
public:
    ConcreteType()
    {
        cout << "ConcreteType initialized" << endl;
    }

    // Inline method to retrieve the identifier
    inline int getIdentifier() { return identifier; }

    // Override to return an instance of the derived class
    ConcreteType* getType() override
    {
        cout << "Returning from derived class" << endl;
        return new ConcreteType();
    }

private:
    int identifier;
};

int main()
{
    AbstractType* instance = new ConcreteType();
    instance->getType();
    instance->test(1, 2);
    instance->test(1, 3, 3);
    instance->test(1.0f, 1.2f);

    delete instance; // Clean up allocated memory
    return 0;
}

