#include <iostream>
#include <typeinfo>
#include <vector>

using namespace std;

class ShapeVisitor;
class Shape;
class Circle;
class Triangle;

class ShapeVisitor
{
public:
    virtual bool intersect(const Shape&) const = 0;
    virtual bool intersect(const Circle&) const = 0;
    virtual bool intersect(const Triangle&) const = 0;
};

class Shape : public ShapeVisitor
{
public:
    // Base class for all shapes, implements the visitor pattern
};

class Circle : public Shape
{
public:
    // Check intersection with different shapes
    virtual bool intersect(const Shape&) const override { return true; }
    virtual bool intersect(const Circle&) const override { return true; }
    virtual bool intersect(const Triangle&) const override { return true; }
};

class Triangle : public Shape
{
public:
    // Check intersection with different shapes
    virtual bool intersect(const Shape&) const override { return true; }
    virtual bool intersect(const Circle&) const override { return true; }
    virtual bool intersect(const Triangle&) const override { return true; }
};

void testIntersection(Triangle& triangle, Circle& circle)
{
    // Prepare pairs of shapes to test for intersection
    vector<pair<Shape*, Shape*>> shapePairs { {&triangle, &triangle}, {&triangle, &circle}, {&circle, &circle} };

    // Evaluate intersection for each pair of shapes
    for (const auto& shapePair : shapePairs)
    {
        if (shapePair.first->intersect(*shapePair.second))
        {
            cout << typeid(shapePair.first).name() << " intersects with " << typeid(shapePair.second).name() << endl;
        }
    }
}

int main()
{
    Triangle triangle;
    Circle circle;
    testIntersection(triangle, circle);
    return 0;
}

