#include <iostream>
#include <string>
#include <fstream>
#include <cstdlib>

namespace NPuzzle
{
    using std::string;
    using std::cout;
    using std::cin;

    class AbstractBoard
    {
        public:
            // Default constructor
            AbstractBoard(void);

            // Print the current state of the board
            void print(void) const;

            // Read board configuration from a file
            void readFromFile(const string& filename);
            // Write board configuration to a file
            void writeToFile(const string& filename);

            // Reset the board to its initial state
            void reset(void);
            // Set the dimensions of the board
            virtual void setSize(const int& width, const int& height);

            // Move a tile in the specified direction
            bool move(const char& direction);
            // Check if the board is in a solved state
            bool isSolved(void) const;

            // Access elements of the board
            virtual int& operator()(int x, int y) = 0;
            virtual const int& operator()(int x, int y) const = 0;

            // Compare two boards for equality
            bool operator==(const AbstractBoard& other) const;

            // Get the total number of board instances
            static int NumberOfBoards(void);

            // Get the number of moves made
            inline int numberOfMoves(void) const { return moveCount; }
            // Get the last move made
            inline char lastMove(void) const { return lastMove; }

            // Accessors for board dimensions and blank representation
            inline int getWidth(void) const { return width; }
            inline int getHeight(void) const { return height; }
            inline int getBlankRepresentation(void) const { return blankRepresentation; }

            // Virtual destructor
            virtual ~AbstractBoard();

        protected:
            // Increment the count of board instances
            inline void incrementBoardCount(void) { ++boardCount; }

        private:
            int width, height;               // Dimensions of the board
            int blankTileX, blankTileY;     // Position of the blank tile
            int blankRepresentation;          // Representation of the blank tile

            static int boardCount;            // Total number of board instances
            char lastMove;                    // Last move made
            int moveCount;                    // Total number of moves made

            // Private helper functions for tile movement
            bool setBlankTilePosition(void);
            bool moveTileRight(void);
            bool moveTileLeft(void);
            bool moveTileUp(void);
            bool moveTileDown(void);
    };
}

