    using std::make_shared;
    using std::shared_ptr;
    using std::cout;
    using std::cerr;
    using std::endl;

    template<typename T>
    class GTUContainerDerived : public GTUContainer<T>
    {
        public:
            GTUContainerDerived();
            GTUContainerDerived(const GTUContainerDerived<T>& other);
            GTUContainerDerived<T>& operator=(const GTUContainerDerived<T>& other);
            ~GTUContainerDerived();

            bool empty() const override;
            unsigned int size() const override;
            unsigned int max_size() const override;

            GTUIterator<T> erase(const GTUIterator<T> iterPos) override;
            void clear() override;
            GTUIterator<T> begin() override;
            GTUIterator<T> end() override;

        protected:
            unsigned int currentSize;
            shared_ptr<Node<T>> headPtr;
            const unsigned int maxCapacity = 5000;
            shared_ptr<Node<T>> nullNodePtr = nullptr;
    };

    template<typename T>
    GTUContainerDerived<T>::GTUContainerDerived()
        : headPtr(nullptr), currentSize(0)
    {
        nullNodePtr = make_shared<Node<T>>(nullptr, nullptr);
    }

    template<typename T>
    GTUContainerDerived<T>::GTUContainerDerived(const GTUContainerDerived<T>& other)
        : currentSize(other.size())
    {
        shared_ptr<Node<T>> tempHead = nullptr;
        shared_ptr<Node<T>> tempOther = nullptr;
        nullNodePtr = make_shared<Node<T>>(nullptr, nullptr);

        if (!other.empty())
        {
            tempOther = other.headPtr;

            headPtr = make_shared<Node<T>>(nullptr, nullptr);
            tempHead = headPtr;
            tempHead->data = tempOther->data;

            for (int i = 0; i < other.size() - 1; ++i)
            {   
                tempHead->next = make_shared<Node<T>>(nullptr, tempHead);
                tempHead = tempHead->next;
                tempOther = tempOther->next;
                tempHead->data = tempOther->data;
            }

            tempHead->next = nullNodePtr;
            nullNodePtr->previos = tempHead;
        }
    }

    template<typename T>
    GTUContainerDerived<T>& GTUContainerDerived<T>::operator=(const GTUContainerDerived<T>& other)
    {
        shared_ptr<Node<T>> tempHead = nullptr;
        shared_ptr<Node<T>> tempOther = nullptr;

        if (this == &other)
            return *this;

        if (this->size() != other.size())
        {
            this->clear();

            currentSize = other.size();
            tempOther = other.headPtr;

            headPtr = make_shared<Node<T>>(nullptr, nullptr);
            tempHead = headPtr;
            tempHead->data = tempOther->data;

            for (int i = 0; i < other.size() - 1; ++i)
            {
                tempHead->next = make_shared<Node<T>>(nullptr, tempHead);
                tempHead = tempHead->next;
                tempOther = tempOther->next;

                tempHead->data = tempOther->data;
            }

            tempHead->next = nullNodePtr;
            nullNodePtr->previos = tempHead;

            return *this;
        }
        else
        {
            tempHead = headPtr;
            tempOther = other.headPtr;

            for (int i = 0; i < other.size(); ++i)
            {
                tempHead->data = tempOther->data;

                tempHead = tempHead->next;
                tempOther = tempOther->next;
            }

            tempHead->next = nullNodePtr;
            nullNodePtr->previos = tempHead;

            return *this;
        }
    }

    template<typename T>
    GTUContainerDerived<T>::~GTUContainerDerived()
    {
    }

    template<typename T>
    bool GTUContainerDerived<T>::empty() const 
    {
        return headPtr == nullptr;
    }

    template<typename T>
    unsigned int GTUContainerDerived<T>::size() const 
    {
        return currentSize;
    }

    template<typename T>
    unsigned int GTUContainerDerived<T>::max_size() const 
    {
        return maxCapacity;
    }

    template<typename T>
    GTUIterator<T> GTUContainerDerived<T>::erase(const GTUIterator<T> iterPos)
    {
        bool isFound = true;
        unsigned int nodeIndex = 0;
        GTUIterator<T> iterator = this->begin();
        shared_ptr<Node<T>> currentNode = headPtr;
        shared_ptr<Node<T>> previousNode = nullptr;
        shared_ptr<Node<T>> nextNode = nullptr;

        while (isFound)
        {
            ++nodeIndex;
            if (iterator == iterPos)
                isFound = false;
            else
            {
                currentNode = currentNode->next;
                ++iterator;
            }
        }

        if (nodeIndex > this->size())
            throw Exceptions("Member end() could not be erased, Error: erase()");

        if (nodeIndex == 1)
        {
            headPtr = headPtr->next;
            headPtr->previos = nullptr;

            currentNode->next = nullptr;
            currentNode->previos = nullptr;
            currentNode = nullptr;
        }
        else
        {
            if (nodeIndex > this->size())
                --nodeIndex;

            nextNode = headPtr;
            iterator = this->begin();

            for (int i = 0; i < nodeIndex; ++i)
            {
                if (i == nodeIndex - 2)
                    previousNode = nextNode;

                nextNode = nextNode->next;
            }

            previousNode->next = nextNode;
            nextNode->previos = previousNode;
        }

        --currentSize;
        iterator = this->begin();

        return iterator;
    }

    template<typename T>
    void GTUContainerDerived<T>::clear()
    {
        shared_ptr<Node<T>> tempNode = nullptr;

        for (int i = 0; i < currentSize; ++i)
        {
            tempNode = headPtr;
            headPtr = headPtr->next;

            tempNode->next = nullptr;
            tempNode->previos = nullptr;
        }

        headPtr = nullptr;
        currentSize = 0;
    }

    template<typename T>
    GTUIterator<T> GTUContainerDerived<T>::begin()
    {
        return GTUIterator<T>(headPtr);
    }

    template<typename T>
    GTUIterator<T> GTUContainerDerived<T>::end()
    {
        return GTUIterator<T>(nullNodePtr);
    }
}

