namespace GTU_171044024
{
    using std::shared_ptr;
    using std::make_shared;
    using std::cout;
    using std::cerr;
    using std::endl;

    template <typename T>
    class ConstIterator
    {
        public:
            // Constructor initializes the iterator with a shared pointer to a node
            ConstIterator(shared_ptr<Node<T>>& nodePtr) : currentNodePtr(nodePtr) {}

            // Dereference operator to access the data of the current node
            inline const T& operator*() const
            {
                return currentNodePtr->data;
            }

            // Arrow operator to access the data of the current node
            inline const T* operator->() const
            {
                return &(currentNodePtr->data);
            }

            // Prefix increment operator to move to the next node
            inline ConstIterator operator++()
            {
                if (currentNodePtr->next != nullptr)
                {
                    currentNodePtr = currentNodePtr->next;
                    return *this;
                }

                throw Exceptions("Const Attempt to reach out of vector! Error: ++()");
            }

            // Postfix increment operator to move to the next node
            inline ConstIterator operator++(int)
            {
                ConstIterator tempIter(currentNodePtr);

                if (currentNodePtr->next != nullptr)
                {
                    currentNodePtr = currentNodePtr->next;
                    return tempIter;
                }

                throw Exceptions("Const Attempt to reach out of vector! Error: ++(int)");
            }

            // Prefix decrement operator to move to the previous node
            inline ConstIterator operator--()
            {
                if (currentNodePtr->previous != nullptr)
                {
                    currentNodePtr = currentNodePtr->previous;
                    return *this;
                }

                throw Exceptions("Const Attempt to reach out of vector! Error: --()");
            }

            // Postfix decrement operator to move to the previous node
            inline ConstIterator operator--(int)
            {
                ConstIterator tempIter(currentNodePtr);

                if (currentNodePtr->previous != nullptr)
                {
                    currentNodePtr = currentNodePtr->previous;
                    return tempIter;
                }

                throw Exceptions("Const Attempt to reach out of vector! Error: --(int)");
            }

            // Equality operator to compare two iterators
            inline bool operator==(const ConstIterator& other) const
            {
                return currentNodePtr == other.currentNodePtr;
            }

            // Inequality operator to compare two iterators
            inline bool operator!=(const ConstIterator& other) const
            {
                return currentNodePtr != other.currentNodePtr;
            }

        private:
            shared_ptr<Node<T>> currentNodePtr; // Pointer to the current node in the iteration
    };
}

