    template<typename T>
    class GTUSet : public GTUContainerDerived<T>
    {
        public:
            GTUSet();
            GTUSet(const GTUSet<T>& other);
            GTUSet<T>& operator=(const GTUSet<T>& other);
            ~GTUSet();

            GTUIterator<T> insert(const T& value) throw(bad_pafram) override;

            void printSetInfo() const;
            void displaySetProperties() const;

        private:
            bool doesDataExist(const T& data) const;
    };

    template<typename T>
    GTUSet<T>::GTUSet()
        : GTUContainerDerived<T>()
    {
        this->curSize = 0;
    }

    template<typename T>
    GTUSet<T>::GTUSet(const GTUSet<T>& other)
        : GTUContainerDerived<T>(other)
    {
    }

    template<typename T>
    GTUSet<T>& GTUSet<T>::operator=(const GTUSet<T>& other)
    {
        if (this == &other)
            return *this;

        GTUContainerDerived<T>::operator=(other);
        return *this;
    }

    template<typename T>
    GTUSet<T>::~GTUSet()
    {
        this->clear();
    }

    template<typename T>
    GTUIterator<T> GTUSet<T>::insert(const T& data) throw(bad_pafram)
    {
        if (this->max_size() == this->size())
            throw bad_pafram("Max size exceeded!");
        if (doesDataExist(data))
            throw bad_pafram("Data already exists in the set.");

        GTUIterator<T> iteratorHead = this->_shared_nullptr;
        shared_ptr<Node<T>> currentNode = this->ptrHead;
        shared_ptr<Node<T>> newNode = make_shared<Node<T>>(nullptr, nullptr);
        newNode->data = data;

        if (currentNode != nullptr)
        {
            while (currentNode->next != nullptr)
                currentNode = currentNode->next;

            currentNode->next = newNode;
            newNode->previous = currentNode;
        }

        newNode->next = this->_shared_nullptr;
        this->_shared_nullptr->previous = newNode;

        if (this->curSize == 0)
            this->ptrHead = newNode;

        ++this->curSize;
        iteratorHead = this->begin();

        return iteratorHead;
    }

    template<typename T>
    bool GTUSet<T>::doesDataExist(const T& data) const
    {
        shared_ptr<Node<T>> currentNode = this->ptrHead;

        if (currentNode == nullptr)
            return false;

        while (currentNode->next != nullptr)
        {
            if (currentNode->data == data)
                return true;

            currentNode = currentNode->next;
        }

        return false;
    }

