#include "Exceptions.h"

namespace GTU_171044024
{
    using std::shared_ptr;
    using std::make_shared;
    using std::cout;
    using std::cerr;
    using std::endl;
    using std::bad_pafram;

    template<typename T>
    class GTUVector : public GTUContainerDerived<T>
    {
        public:
            GTUVector(unsigned int initialSize = 0);
            GTUVector(const GTUVector<T>& other);
            GTUVector<T>& operator=(const GTUVector<T>& other);
            ~GTUVector();

            T& operator[](int index);
            const T& operator[](int index) const;

            GTUIterator<T> insert(const GTUIterator<T> position, const T& value) throw(bad_pafram);
            GTUIterator<T> insert(const T& value) throw(bad_pafram) override;

            void printVectorProperties() const;
            void printGTUVectorInfo() const;

        private:
            void createInitialList(const unsigned int size);
    };

    // Constructor initializes the vector with a specified size
    template<typename T>
    GTUVector<T>::GTUVector(unsigned int initialSize)
        : GTUContainerDerived<T>()
    {
        createInitialList(initialSize);
    }

    // Copy constructor
    template<typename T>
    GTUVector<T>::GTUVector(const GTUVector<T>& other)
        : GTUContainerDerived<T>(other)
    {
        /* Intentionally left blank */
    }

    // Assignment operator
    template<typename T>
    GTUVector<T>& GTUVector<T>::operator=(const GTUVector<T>& other)
    {
        if (this == &other)
            return *this;

        GTUContainerDerived<T>::operator=(other);
        return *this;
    }

    // Destructor clears the vector
    template<typename T>
    GTUVector<T>::~GTUVector()
    {
        this->clear();
    }

    // Access element at a specific index
    template<typename T>
    T& GTUVector<T>::operator[](int index)
    {
        if (index < 0 || index >= this->curSize)
            throw Exceptions("Invalid index input, Error Code: operator[]!");

        shared_ptr<Node<T>> currentNode = this->ptrHead;
        for (int i = 0; i < index; ++i)
            currentNode = currentNode->next;

        return currentNode->data;
    }

    // Access element at a specific index (const version)
    template<typename T>
    const T& GTUVector<T>::operator[](int index) const
    {
        if (index < 0 || index >= this->curSize)
            throw Exceptions("Invalid index input, Error Code: const operator[]!");

        shared_ptr<Node<T>> currentNode = this->ptrHead;
        for (int i = 0; i < index; ++i)
            currentNode = currentNode->next;

        return currentNode->data;
    }

    // Insert value at a specified iterator position
    template<typename T>
    GTUIterator<T> GTUVector<T>::insert(const GTUIterator<T> position, const T& data) throw(bad_pafram)
    {
        if (this->max_size() == this->size())
            throw("Max size has been exceeded!");

        GTUIterator<T> iterator = this->begin();
        shared_ptr<Node<T>> currentNode = this->ptrHead;
        shared_ptr<Node<T>> newNode = nullptr;
        shared_ptr<Node<T>> previousNode = nullptr;

        while (true)
        {
            if (iterator == position)
                break;

            currentNode = currentNode->next;
            ++iterator;
        }

        previousNode = currentNode->previos;
        newNode = make_shared<Node<T>>(currentNode, previousNode);
        newNode->data = data;

        currentNode->previos = newNode;

        if (previousNode != nullptr)
            previousNode->next = newNode;
        else
            this->ptrHead = newNode;

        ++this->curSize;
        return this->begin();
    }

    // Insert value at the end of the vector
    template<typename T>
    GTUIterator<T> GTUVector<T>::insert(const T& data) throw(bad_pafram)
    {
        if (this->max_size() == this->size())
            throw bad_pafram("Max size exceeded!");

        shared_ptr<Node<T>> currentNode = this->ptrHead;
        shared_ptr<Node<T>> newNode = make_shared<Node<T>>(nullptr, nullptr);
        newNode->data = data;

        if (currentNode != nullptr)
        {
            while (currentNode->next != nullptr)
                currentNode = currentNode->next;

            currentNode->next = newNode;
            newNode->previos = currentNode;
            newNode->next = this->_shared_nullptr;
            this->_shared_nullptr->previos = newNode;
        }
        else
        {
            newNode->next = this->_shared_nullptr;
            this->_shared_nullptr->previos = newNode;
            this->ptrHead = newNode;
        }

        ++(this->curSize);
        return this->begin();
    }

    // Create initial linked list structure based on the specified size
    template<typename T>
    void GTUVector<T>::createInitialList(const unsigned int size)
    {
        this->curSize = size;

        if (this->curSize != 0)
        {
            this->ptrHead = make_shared<Node<T>>(nullptr, nullptr);
            shared_ptr<Node<T>> currentNode = this->ptrHead;

            for (int i = 0; i < this->curSize - 1; ++i)
            {
                this->ptrHead->next = make_shared<Node<T>>(nullptr, this->ptrHead);
                this->ptrHead = this->ptrHead->next;
            }

            this->ptrHead->next = this->_shared_nullptr;
            this->_shared_nullptr->previos = this->ptrHead;

            this->ptrHead = currentNode;
        }
    }

    // Print properties of the vector
    void GTUVector<T>::printVectorProperties() const
    {
        shared_ptr<Node<T>> currentNode = this->ptrHead;

        if (currentNode == nullptr)
            return;

        cout << "**********************************************" << endl;
        cout << "Vector Configuration: \n";

        for (unsigned int i = 0; i < this->curSize; ++i)
        {
            cout << currentNode->data << " ";
            currentNode = currentNode->next;
        }
        cout << endl;
        cout << "**********************************************" << endl;
    }

    // Print information about the GTUVector class
    void GTUVector<T>::printGTUVectorInfo() const
    {
        cout << endl << "****GTUVector_INFO********" << endl;
        cout << "Constructors: " << endl;
        cout << "GTUVector()       -> Create a vector with size zero" << endl;
        cout << "GTUVector(size)   -> Create a vector with specified size" << endl << endl;

        cout << "Copy constructor and assignment operator are available." << endl;
        cout << "Destructor is available." << endl;
        cout << "Operator [] is available." << endl << endl;

        cout << "Class Functions: " << endl << endl;
        cout << "bool               empty(void)" << endl;
        cout << "unsigned int       size(void)" << endl;
        cout << "unsigned int       max_size(void)" << endl;
        cout << "GTUIterator<T>     erase(const GTUIterator<T> iterPos)" << endl;
        cout << "void               clear(void)" << endl;
        cout << "GTUIterator<T>     insert(const GTUIterator<T> iterPos, const T& value) throw(bad_pafram)" << endl;
