// Toán tử trừ để hủy đặt phòng
int Hotel::operator-(Reservation* reservation) {
    if (reservation == nullptr) {
        cout << "There is no reservation with this code." << endl;
        return 2;
    }

    int roomIndex = -1;
    for (size_t i = 0; i < roomList.size(); i++) {
        for (int day = 0; day < DAYSOFMONTH; day++) {
            if (roomList[i]->getAvailabilityArray()[day] != nullptr &&
                roomList[i]->getAvailabilityArray()[day]->getCode() == reservation->getCode()) {
                roomIndex = i;
                break;
            }
        }
        if (roomIndex != -1) break;
    }

    if (roomIndex != -1) {
        if (roomList[roomIndex]->cancel(reservation->getCode())) {
            for (size_t i = 0; i < reservationList.size(); i++) {
                if (reservation->getCode() == reservationList[i]->getCode()) {
                    reservationList.erase(reservationList.begin() + i);
                    cout << "The reservation with code " << reservation->getCode() << " was cancelled." << endl;
                    return 0;
                }
            }
        }
        cout << "The reservation could not be deleted." << endl;
        return 1;
    }
    return 2;
}

// Toán tử cộng để thêm đặt phòng vào khách sạn
int Hotel::operator+(Reservation* reservation) {
    for (size_t i = 0; i < roomList.size(); i++) {
        if (roomList[i]->addReservation(reservation)) {
            reservationList.push_back(reservation);
            return roomList[i]->getRoomCode();
        }
    }
    return 0;
}

// Toán tử cộng để thêm phòng vào khách sạn
void Hotel::operator+(Room* room) {
    roomList.push_back(room);
}

