class RoomTypeD;

int Room::codeCounter = 1; // Counter for generating unique room codes

Room::Room(int maxCapacity, double pricePerPerson) : maxCapacity(maxCapacity), pricePerPerson(pricePerPerson) {
    roomCode = codeCounter++;
    // Initialize availability array to NULL for all days of the month
    for (int i = 0; i < Hotel::DAYSOFMONTH; i++) {
        availabilityArray[i] = nullptr;
    }
}

bool Room::addReservation(Reservation* reservation) {
    bool isReservationSuccessful = false;
    int freeDays = 0;

    // Check for available days for the reservation
    for (int day = 0; day < Hotel::DAYSOFMONTH; day++) {
        if ((day >= reservation->getArrival()) && 
            (day < (reservation->getArrival() + reservation->getDays())) && 
            (availabilityArray[day] == nullptr)) {
            freeDays++;
        }

        // If enough free days are found and capacity is sufficient
        if ((freeDays == reservation->getDays()) && 
            (reservation->getPeople() <= maxCapacity)) {
            isReservationSuccessful = true;

            // Mark the days as reserved
            for (int j = reservation->getArrival(); j < (reservation->getDays() + reservation->getArrival()); j++) {
                availabilityArray[j] = reservation;
            }
            reservation->setRoom(this);
            break;
        } else {
            isReservationSuccessful = false;
        }
    }
    return isReservationSuccessful;
}

double Room::setPrice() {
    double totalCost = 0;

    // Calculate total cost based on reservations
    for (int day = 0; day < Hotel::DAYSOFMONTH; day++) {
        if (availabilityArray[day] != nullptr) {
            totalCost += pricePerPerson * availabilityArray[day]->getPeople();
        }
    }
    return totalCost;
}

bool Room::cancel(int reservationCode) {
    // Cancel the reservation by setting the corresponding days to NULL
    for (int day = 0; day < Hotel::DAYSOFMONTH; day++) {
        if (availabilityArray[day] != nullptr && 
            availabilityArray[day]->getCode() == reservationCode) {
            availabilityArray[day] = nullptr;
        }
    }
    return true;
}

double Room::fullness() {
    float occupiedDays = 0;

    // Count occupied days to calculate fullness percentage
    for (int day = 0; day < Hotel::DAYSOFMONTH; day++) {
        if (availabilityArray[day] != nullptr) {
            occupiedDays++;
        }
    }
    return (occupiedDays / Hotel::DAYSOFMONTH) * 100;
}

