/** Represents a location in the simulation, defining its weather, treasure, and port status. */
class Location {
private:
    int weather = 0;
    int treasure = 0;
    bool hasTreasure = false;
    bool isPort = false;
    bool hasShip = false;

public:
    /** Initializes a location with random weather and treasure status. */
    Location() {
        srand(static_cast<unsigned int>(time(0))); // Seed the random number generator
        weather = rand() % 10 + 1; // Assign random weather value [1,10]

        if (rand() % 9 == 1) { // 1/8 chance to have treasure
            hasTreasure = true;
            treasure = rand() % 101 + 50; // Assign random treasure value [50,150]
        }

        isPort = (rand() % 10 == 1); // 10% chance to be a port
        Sleep(1000); // Delay to change the seed for randomness
    }

    /** Updates the weather at the end of each round. */
    void updateWeather() {
        srand(static_cast<unsigned int>(time(0)));
        if ((rand() % 2 == 1) && (weather < 10)) {
            setWeather(weather + 1);
        } else if ((rand() % 2 == 0) && (weather > 1)) {
            setWeather(weather - 1);
        } else if (weather == 10) {
            setWeather(9);
        } else if (weather == 1) {
            setWeather(2);
        }
    }

    /** Checks if the location is empty (not a port and has no ship). */
    bool isEmpty() const {
        return !isPort && !hasShip;
    }

    /** Displays information about the location, including treasure, weather, ship, and port status. */
    void displayInfo() const {
        cout << "Treasure: " << treasure << endl;
        cout << "Weather: " << weather << endl;
        cout << "Has Ship: " << (hasShip ? "Yes" : "No") << endl;
        cout << "Has Port: " << (isPort ? "Yes" : "No") << endl;
    }

    /** Getters and setters for private member variables. */
    int getWeather() const {
        return weather;
    }

    void setWeather(int newWeather) {
        weather = newWeather;
    }

    int getTreasure() const {
        return treasure;
    }

    void setTreasure(int newTreasure) {
        treasure = newTreasure;
    }

    bool hasTreasureStatus() const {
        return hasTreasure;
    }

    void setTreasureStatus(bool treasureStatus) {
        hasTreasure = treasureStatus;
    }

    bool isPortStatus() const {
        return isPort;
    }

    void setPortStatus(bool portStatus) {
        isPort = portStatus;
    }

    void setShipStatus(bool shipStatus) {
        hasShip = shipStatus;
    }

    bool hasShipStatus() const {
        return hasShip;
    }
};

