/** 
 * Sorts ships based on selected criteria using the bubble sort algorithm.
 * 
 * @param ships: Vector containing pointers to ships.
 * @param sortCriteria: Defines the sorting criteria (1: treasure, 2: current resistance, 3: type).
 */
void BubbleSort(std::vector<Ship*> ships, int sortCriteria) {
    if (ships.empty()) {
        std::cout << "Cannot sort due to lack of ships !!" << std::endl;
        return;
    }

    Ship* tempShip = nullptr; // Temporary variable for swapping ships

    for (size_t i = 0; i < ships.size() - 1; ++i) {
        for (size_t j = 0; j < ships.size() - 1 - i; ++j) {
            bool shouldSwap = false;

            switch (sortCriteria) {
                case 1: // Sort by treasure
                    shouldSwap = ships[j + 1]->operator>(ships[j]);
                    break;
                case 2: // Sort by current resistance
                    shouldSwap = ships[j]->getCurResistance() < ships[j + 1]->getCurResistance();
                    break;
                case 3: // Sort by type
                    shouldSwap = ships[j]->getType() < ships[j + 1]->getType();
                    break;
            }

            if (shouldSwap) {
                tempShip = ships[j + 1];
                ships[j + 1] = ships[j];
                ships[j] = tempShip;
            }
        }
    }

    // Print sorted results
    for (const auto& ship : ships) {
        std::cout << "Ship " << ship->getPositionInVector() << " --> ";
        switch (sortCriteria) {
            case 1:
                std::cout << "Treasure : " << ship->getTreasure() << std::endl;
                break;
            case 2:
                std::cout << "Current Resistance : " << ship->getCurResistance() << std::endl;
                break;
            case 3:
                std::cout << "Type : " << ship->getType() << std::endl;
                break;
        }
        std::cout << std::endl;
    }
}

/** 
 * Visualizes the simulation by graphing ships, ports, weather, and treasure.
 * 
 * @param map: The map of the simulation.
 * @param ships: Vector containing pointers to ships.
 * @param graphChoice: User's choice of what to graph.
 */
void graph(Map* map, std::vector<Ship*> ships, int graphChoice) {
    for (int i = 0; i < ARRAYSIZEX; i++) {
        for (int k = 0; k < 2 * ARRAYSIZEX + 1; k++)
            std::cout << "-";
        std::cout << std::endl;
        std::cout << "|";

        switch (graphChoice) {
            case 1: // Graph ships
                for (int j = 0; j < ARRAYSIZEY; j++) {
                    if (map->locations[i][j].getHasShip()) {
                        Ship* ship = new Ship();
                        ship = ship->findShip(i, j, ships);
                        std::cout << ship->getPositionInVector();
                    } else {
                        std::cout << " ";
                    }
                    std::cout << "|";
                }
                break;
            case 2: // Graph ports
                for (int j = 0; j < ARRAYSIZEY; j++) {
                    std::cout << (map->locations[i][j].getIsPort() ? "*" : " ") << "|";
                }
                break;
            case 3: // Graph weather
                for (int j = 0; j < ARRAYSIZEY; j++) {
                    std::cout << map->locations[i][j].getWeather() << "|";
                }
                break;
            case 4: // Graph treasure
                for (int j = 0; j < ARRAYSIZEY; j++) {
                    std::cout << (map->locations[i][j].getHasTreasure() ? map->locations[i][j].getTreasure() : " ") << "|";
                }
                break;
        }
        std::cout << std::endl;
    }
    for (int j = 0; j < 2 * ARRAYSIZEX + 1; j++)
        std::cout << "-";
    std::cout << std::endl;
}

