    std::cout << "1 : Continue Simulation" << std::endl;
    std::cout << "2 : Get Information about a ship" << std::endl;
    std::cout << "3 : Get Information about a position on the map" << std::endl;
    std::cout << "4 : Get Information about a type of ship" << std::endl;
    std::cout << "5 : General Information" << std::endl;
    std::cout << "6 : Add / Remove a Ship" << std::endl;
    std::cout << "7 : Modify a position on the map" << std::endl;
    std::cout << "8 : Graph" << std::endl;
    std::cout << "9 : Sort Ships" << std::endl;
    std::cout << "10 : End Game" << std::endl;
    std::cin >> actionChoice;

    switch (actionChoice) {
        case 1: // Continue simulation
            for (int i = 0; i < ARRAYSIZEX; i++) {
                for (int j = 0; j < ARRAYSIZEY; j++) {
                    if (map->locations[i][j].getWeather() > 7) {
                        if (map->locations[i][j].getHasShip()) {
                            Ship* ship = ship->findShip(i, j, ships);
                            ship->operator--(DAMAGEWEATHER); // Decrease ship's resistance

                            // Update damage based on ship type
                            switch (ship->getType()) {
                                case 1: PirateDamage += DAMAGEWEATHER; break;
                                case 2: MerchantDamage += DAMAGEWEATHER; break;
                                case 3: RepairDamage += DAMAGEWEATHER; break;
                                case 4: ExplorationDamage += DAMAGEWEATHER; break;
                                case 5: NavalDamage += DAMAGEWEATHER; break;
                                case 6: SubMarineDamage += DAMAGEWEATHER; break;
                            }
                        }
                    }

                    if (map->locations[i][j].getHasTreasure()) {
                        if (map->locations[i][j].getHasShip()) {
                            Ship* ship = ship->findShip(i, j, ships);
                            ship->setTreasure(ship->getTreasure() + map->locations[i][j].getTreasure());
                            Ship::treasureAmount += map->locations[i][j].getTreasure();
                            std::cout << "Ship " << ship->getPositionInVector() << " gathered treasure ( " << map->locations[i][j].getTreasure() << " coins) !!" << std::endl;
                        }
                    }

                    // Check for interaction with nearby ships
                    bool foundShip = false;
                    for (int dx = -1; dx <= 1; dx++) {
                        for (int dy = -1; dy <= 1; dy++) {
                            if (abs(dx) + abs(dy) == 1 && map->locations[i + dx][j + dy].getHasShip()) {
                                Ship* ship = ship->findShip(i + dx, j + dy, ships);
                                foundShip = true;
                                if (ship->getType() == 1) { // Pirate ship
                                    ship->setCurResistance(ship->getCurResistance() - DAMAGEPORT);
                                    ship->setTotalDamage(ship->getTotalDamage() + DAMAGEPORT);
                                    PirateDamage += DAMAGEPORT;
                                    std::cout << "Ship " << ship->getPositionInVector() << " has been damaged due to an attempted approach to a port" << std::endl;
                                } else { // Non-pirate ship
                                    if (ship->getCurResistance() + (double)HEALPORT * ship->getCurResistance() <= ship->getMaxResistance()) {
                                        ship->operator+(HEALPORT); // Heal ship
                                    } else {
                                        ship->setCurResistance(ship->getMaxResistance());
                                    }
                                    std::cout << "Ship " << ship->getPositionInVector() << " has been repaired in a port (new Resistance :" << ship->getCurResistance() << ")" << std::endl;
                                }
                            }
                        }
                    }
                }
            }

            // Update movement and operations for each ship
            for (auto& ship : ships) {
                ship->movement(ship->getX(), ship->getY(), ship->getSpeed(), map);
                ship->operation(ship->getX(), ship->getY(), map, ships);
            }

            // Remove ships with zero resistance
            for (size_t i = 0; i < ships.size(); i++) {
                if (ships[i]->getCurResistance() <= 0) {
                    map->locations[ships[i]->getX()][ships[i]->getY()].setHasShip(false);
                    map->locations[ships[i]->getX()][ships[i]->getY()].setHasTreasure(true);
                    map->locations[ships[i]->getX()][ships[i]->getY()].setTreasure(ships[i]->getTreasure());
                    delete ships[i];
                    ships.erase(ships.begin() + i);
                    i--; // Adjust index after removal
                }
            }

            // Reset bad weather counter
            map->setBadWeather(0);
            for (int i = 0; i < ARRAYSIZEX; i++) {
                for (int j = 0; j < ARRAYSIZEY; j++) {
                    map->locations[i][j].weatherChange();
                    if (map->locations[i][j].getWeather() > 7) {
                        map->setBadWeather(map->getBadWeather() + 1);
                    }
                }
            }

            if (ships.empty()) {
                std::cout << "End of simulation due to lack of ships!!" << std::endl;
                return true;
            }

            // Check if any ship has reached the treasure target
            std::vector<Ship*> tempShips = ships;
            std::sort(tempShips.begin(), tempShips.end(), [](Ship* a, Ship* b) {
                return a->getTreasure() < b->getTreasure();
            });

            if (tempShips.back()->getTreasure() >= TARGET) {
                std::cout << "\nShip " << tempShips.back()->getPositionInVector() << " has won!! (treasure = " << tempShips.back()->getTreasure() << ")" << std::endl;
                tempShips.back()->printInfo();
                switch (tempShips.back()->getType()) {
                    case 1: std::cout << "Total damage caused : " << static_cast<PirateShip*>(tempShips.back())->getCausedDamage() << std::endl; break;
                    case 2: std::cout << "Total treasure gathered from ports : " << static_cast<MerchantShip*>(tempShips.back())->getPortTreasure() << std::endl; break;
                    case 3: std::cout << "Total treasure gathered from healing : " << static_cast<RepairShip*>(tempShips.back())->getTotalHeal() << std::endl; break;
                }
                return true;
            }
            return false;

        case 2: // Get information about a ship
            std::cout << "Enter the number of the ship whose information are to be shown or -1 to print info about all the ships" << std::endl;
            std::cin >> userChoice;

            if (userChoice == -1) {
                for (const auto& ship : ships) {
                    std::cout << ship;
                    switch (ship->getType()) {
                        case 1: std::cout << "Total damage caused : " << static_cast<PirateShip*>(ship)->getCausedDamage() << std::endl; break;
                        case 2: std::cout << "Total treasure gathered from ports : " << static_cast<MerchantShip*>(ship)->getPortTreasure() << std::endl; break;
                        case 3: std::cout << "Total treasure gathered from healing : " << static_cast<RepairShip*>(ship)->getTotalHeal() << std::endl; break;
                    }
                    std::cout << std::endl;
                }
            } else {
                for (const auto& ship : ships) {
                    if (ship->getPositionInVector() == userChoice) {
                        std::cout << ship;
                        switch (ship->getType()) {
                            case 1: std::cout << "Total damage caused : " << static_cast<PirateShip*>(ship)->getCausedDamage() << std::endl; break;
                            case 2: std::cout << "Total treasure gathered from ports : " << static_cast<MerchantShip*>(ship)->getPortTreasure() << std::endl; break;
                            case 3: std::cout << "Total treasure gathered from healing : " << static_cast<RepairShip*>(ship)->getTotalHeal() << std::endl; break;
                        }
                        std::cout << std::endl;
                        return false;
                    }
                }
            }
            std::cout << "Ship not found!" << std::endl;
            return false;

        case 3: // Get information about a position on the map
            std::cout << "Enter the x position of the ship : ";
            std::cin >> x;
            std::cout << "Enter the y position of the ship : ";
            std::cin >> y;
            std::cout << std::endl;

            if (x >= 0 && x < ARRAYSIZEX && y >= 0 && y < ARRAYSIZEY) {
                map->locations[x][y].printInfo();
            } else {
                std::cout << "Index out of bounds" << std::endl;
            }
            return false;

        case 4: // Get information about a type of ship
            std::cout << "Enter the type of the ship whose information are to be shown" << std::endl;
            std::cout << "   1 ---> PirateShip " << std::endl;
            std::cout << "   2 ---> MerchantShip" << std::endl;
            std::cout << "   3 ---> RepairShip" << std::endl;
            std::cout << "   4 ---> ExplorationShip" << std::endl;
            std::cout << "   5 ---> NavalShip" << std::endl;
            std::cout << "   6 ---> Submarine" << std::endl;
            std::cin >> userChoice;

            if (userChoice > 0 && userChoice < 7) {
                for (const auto& ship : ships) {
                    if (ship->getType() == userChoice) {
                        std::cout << ship << std::endl;
                    }
                }
                // Print total damage by ship type
                switch (userChoice) {
                    case 1: std::cout << "Total damage of pirate ships : " << PirateDamage << std::endl; break;
                    case 2: std::cout << "Total damage of merchant ships : " << MerchantDamage << std::endl; break;
                    case 3: std::cout << "Total damage of repair ships : " << RepairDamage << std::endl; break;
                    case 4: std::cout << "Total damage of exploration ships : " << ExplorationDamage << std::endl; break;
                    case 5: std::cout << "Total damage of naval ships : " << NavalDamage << std::endl; break;
                    case 6: std::cout << "Total damage of submarines : " << SubMarineDamage << std::endl; break;
                }
            } else {
                std::cout << "Choice not available! " << std::endl;
            }
            return false;

        case 5: // General information about the simulation
            std::cout << "1 : Number of locations with bad weather conditions " << std::endl;
            std::cout << "2 : Number of locations with ports" << std::endl;
            std::cout << "3 : Total amount of gathered treasure" << std::endl;
            std::cin >> userChoice;

            if (userChoice == 3) {
                std::cout << Ship::treasureAmount << std::endl;
            } else if (userChoice == 2) {
                std::cout << map->getNumberOfPorts() << std::endl;
            } else if (userChoice == 1) {
                std::cout << map->getBadWeather() << std::endl;
            } else {
                std::cout << "Not Available Choice!" << std::endl;
            }
            return false;

        case 6: // Add or remove a ship
            system("cls");
            std::cout << "1 : Add Ship" << std::endl;
            std::cout << "2 : Remove Ship" << std::endl;
            std::cout << "3 : Remove All Ships" << std::endl;
            std::cin >> userChoice;

            if (userChoice == 1) {
                do {
                    std::cout << "Enter the Type of the ship to be added" << std::endl;
                    std::cout << "   1 ---> PirateShip" << std::endl;
                    std::cout << "   2 ---> MerchantShip" << std::endl;
                    std::cout << "   3 ---> RepairShip" << std::endl;
                    std::cout << "   4 ---> ExplorationShip" << std::endl;
                    std::cout << "   5 ---> NavalShip" << std::endl;
                    std::cout << "   6 ---> Submarine" << std::endl;
                    std::cin >> userChoice;
                } while (userChoice < 1 || userChoice > 6);

                Ship* newShip = nullptr;
                switch (userChoice) {
                    case 1: newShip = new PirateShip(); break;
                    case 2: newShip = new MerchantShip(); break;
                    case 3: newShip = new RepairShip(); break;
                    case 4: newShip = new ExplorationShip(); break;
                    case 5: newShip = new NavalShip(); break;
                    case 6: newShip = new Submarine(); break;
                }
                ships.push_back(newShip);
                Ship::NumberOfShips++;
                newShip->setLocation(map);
                newShip->setPositionInVector(Ship::NumberOfShips - 1);
            } else if (userChoice == 2) {
                std::cout << "Choose Ship to be destroyed!" << std::endl;
                std::cin >> userChoice;
                bool shipFound = false;

                for (size_t i = 0; i < ships.size(); i++) {
                    if (userChoice == ships[i]->getPositionInVector()) {
                        map->locations[ships[i]->getX()][ships[i]->getY()].setHasShip(false);
                        map->locations[ships[i]->getX()][ships[i]->getY()].setHasTreasure(true);
                        map->locations[ships[i]->getX()][ships[i]->getY()].setTreasure(ships[i]->getTreasure());
                        delete ships[i];
                        ships.erase(ships.begin() + i);
                        shipFound = true;
                        break;
                    }
                }
                if (!shipFound) {
                    std::cout << "Ship not found!" << std::endl;
                }
            } else if (userChoice == 3) {
                for (auto& ship : ships) {
                    map->locations[ship->getX()][ship->getY()].setHasShip(false);
                    map->locations[ship->getX()][ship->getY()].setHasTreasure(true);
                    map->locations[ship->getX()][ship->getY()].setTreasure(ship->getTreasure());
                }
                ships.clear(); // Clear all ships from the vector
            }
            return false;

        case 7: // Modify a position on the map
            system("cls");
            do {
                std::cout << "Enter x position : ";
                std::cin >> x;
            } while (x < 0 || x >= ARRAYSIZEX);
            do {
                std::cout << "Enter y position : ";
                std::cin >> y;
            } while (y < 0 || y >= ARRAYSIZEY);
            std::cout << std::endl;

            std::cout << "1 : Add Port" << std::endl;
            std::cout << "2 : Remove Port" << std::endl;
            std::cout << "3 : Add Treasure" << std::endl;
            std::cout << "4 : Remove Treasure" << std::endl;
            std::cin >> actionChoice;

            switch (actionChoice) {
                case 1: // Add port
                    if (map->locations[x][y].getIsPort()) {
                        std::cout << "Port already exists there" << std::endl;
                    } else {
                        map->locations[x][y].setIsPort(true);
                        map->setNumberOfPorts(map->getNumberOfPorts() + 1);
                    }
                    break;
                case 2: // Remove port
                    if (!map->locations[x][y].getIsPort()) {
                        std::cout << "Port doesn't exist there" << std::endl;
                    } else {
                        map->locations[x][y].setIsPort(false);
                        map->setNumberOfPorts(map->getNumberOfPorts() - 1);
                    }
                    break;
                case 3: // Add treasure
                    do {
                        std::cout << "Enter amount of treasure to be added: ";
                        std::cin >> treasureAmount;
                    } while (treasureAmount < 0);
                    if (map->locations[x][y].getHasTreasure()) {
                        map->locations[x][y].setTreasure(map->locations[x][y].getTreasure() + treasureAmount);
                    } else {
                        map->locations[x][y].setHasTreasure(true);
                        map->locations[x][y].setTreasure(treasureAmount);
                    }
                    break;
                case 4: // Remove treasure
                    do {
                        std::cout << "Enter amount of treasure to be removed: ";
                        std::cin >> treasureAmount;
                    } while (treasureAmount < 0);
                    if (map->locations[x][y].getHasTreasure()) {
                        if (map->locations[x][y].getTreasure() - treasureAmount > 0) {
                            map->locations[x][y].setTreasure(map->locations[x][y].getTreasure() - treasureAmount);
                        } else {
                            map->locations[x][y].setTreasure(0);
                        }
                    } else {
                        map->locations[x][y].setHasTreasure(true);
                        map->locations[x][y].setTreasure(0);
                    }
                    break;
            }
            return false;

        case 8: // Graph
            do {
                std::cout << "1 : Graph Ships" << std::endl;
                std::cout << "2 : Graph Ports" << std::endl;
                std::cout << "3 : Graph Weather" << std::endl;
                std::cout << "4 : Graph Treasure" << std::endl;
                std::cin >> actionChoice;
            } while (actionChoice < 1 || actionChoice > 4);
            graph(map, ships, actionChoice);
            return false;

        case 9: // Sort ships
            do {
                std::cout << "Sort ships by" << std::endl;
                std::cout << "1 : Treasure" << std::endl;
                std::cout << "2 : Current Resistance " << std::endl;
                std::cout << "3 : Type" << std::endl;
                std::cin >> actionChoice;
            } while (actionChoice < 1 || actionChoice > 3);
            BubbleSort(ships, actionChoice);
            return false;

        case 10: // End game
            return true;

        default:
            std::cout << "Option not available!" << std::endl;
            return false;
    }
}

int main() {
    char playAgain;

    do {
        std::cout << "Please wait while the map and the ships are being initialized!" << std::endl;
        Map* map = new Map();
        std::vector<Ship*> ships;
        srand(static_cast<unsigned int>(time(NULL)));

        for (int i = 0; i < NUMBEROFSHIPS; i++) {
            Ship* newShip = nullptr;
            if (i <= 1) newShip = new PirateShip();
            else if (i <= 3) newShip = new MerchantShip();
            else if (i <= 5) newShip = new ExplorationShip();
            else if (i <= 7) newShip = new RepairShip();
            else if (i <= 9) newShip = new NavalShip();
            else newShip = new Submarine();

            ships.push_back(newShip);
            newShip->setLocation(map);
        }

        std::random_shuffle(ships.begin(), ships.end());
        for (size_t i = 0; i < ships.size(); i++) {
            ships[i]->setPositionInVector(i);
            Ship::NumberOfShips++;
        }

        system("cls");
        bool isSimulationRunning = true;

        while (isSimulationRunning) {
            isSimulationRunning = menu(map, ships);
        }

        std::cout << "Play again (y / n)? ";
        std::cin >> playAgain;

        // Clean up dynamically allocated ships
        for (auto& ship : ships) {
            delete ship;
        }
        delete map;

    } while (playAgain == 'y');

    return 0;
}

#ifndef MAP_INFO_H
#define MAP_INFO_H

#include "Location.h"

constexpr int ARRAY_SIZE_X = 9;         // Size of the array along the x-axis
constexpr int ARRAY_SIZE_Y = 9;         // Size of the array along the y-axis
constexpr int NUMBER_OF_SHIPS = 12;     // Total number of ships in the simulation
constexpr int WIDTH = 100;
constexpr int DAMAGE_WEATHER = 30;      // Damage caused by adverse weather conditions
constexpr int TARGET = 500;              // Target value for the simulation
constexpr int DAMAGE_PORT = 30;          // Damage inflicted by a port on pirate ships
constexpr double HEAL_PORT = 0.1;        // Healing effect of a port on nearby ships

/** Class representing the map for the simulation */
class Map {
private:
    int portCount = 0;                   // Count of ports created
    int badWeatherCount = 0;             // Count of locations with severe weather

public:
    Location** locations = new Location*[ARRAY_SIZE_X]; // Dynamic 2D array of locations

    /** Default constructor for the Map */
    Map() {
        for (int i = 0; i < ARRAY_SIZE_X; i++) {
            locations[i] = new Location[ARRAY_SIZE_Y];
        }

        // Count ports and bad weather locations
        for (int i = 0; i < ARRAY_SIZE_X; i++) {
            for (int j = 0; j < ARRAY_SIZE_Y; j++) {
                if (locations[i][j].getIsPort()) {
                    setPortCount(portCount + 1); // Increment port count
                }
                if (locations[i][j].getWeather() > 7) {
                    setBadWeatherCount(badWeatherCount + 1); // Increment bad weather count
                }
            }
        }
    }

    /*******************************************************************************/
    /***** Getter and Setter methods for private variables *****/
    /*******************************************************************************/

    int getPortCount() const {
        return portCount;
    }

    void setPortCount(int count) {
        portCount = count;
    }

    int getBadWeatherCount() const {
        return badWeatherCount;
    }

    void setBadWeatherCount(int count) {
        badWeatherCount = count;
    }

    /*********************************/
    /***** End of getter/setter methods *****/
    /*******************************/
};

#endif // MAP_INFO_H

#ifndef SHIP_HEADER
#define SHIP_HEADER

#include <iostream>
#include <cstdlib>
#include <ctime>
#include <vector>
#include "Map.h"

using namespace std;

int totalPirateDamage = 0;        // Tracks total damage inflicted by Pirate Ships
int totalMerchantDamage = 0;      // Tracks total damage inflicted by Merchant Ships
int totalExplorationDamage = 0;   // Tracks total damage inflicted by Exploration Ships
int totalRepairDamage = 0;        // Tracks total damage inflicted by Repair Ships
int totalNavalDamage = 0;         // Tracks total damage inflicted by Naval Ships
int totalSubmarineDamage = 0;     // Tracks total damage inflicted by Submarines

/** Class representing a generic ship */
class Ship {
private:
    int maxResistance = 0;          // Maximum resistance of the ship
    int currentResistance = 0;      // Current resistance of the ship
    int speed = 0;                  // Speed of the ship in blocks per round
    int treasure = 0;               // Amount of treasure collected by the ship
    int positionX = 0;              // Ship's position on the x-axis
    int positionY = 0;              // Ship's position on the y-axis
    int vectorIndex = -1;           // Index of the ship in the vector of ships
    int shipType = 0;               // Type of the ship (1: Pirate, 2: Merchant, etc.)
    int blocksMoved = 0;            // Total blocks moved since the start
    int totalDamageTaken = 0;       // Total damage suffered by the ship

public:
    static int totalTreasure;       // Tracks total treasure gathered by all ships
    static int shipCount;            // Tracks the number of ships created

    Ship() {}                        // Default constructor

    ~Ship() {
        cout << "Ship " << getVectorIndex() << " has been destructed !!" << endl;
    }

    /** Operator Overloading **/

    void operator--(int damage) {   // Decrease resistance due to damage
        cout << "Ship " << getVectorIndex() << " has been damaged due to bad weather" << endl;
        setCurrentResistance(getCurrentResistance() - damage);
        setTotalDamageTaken(getTotalDamageTaken() + damage);
    }

    void operator+(double percentage) { // Heal the ship by a percentage of current resistance
        setCurrentResistance(getCurrentResistance() + (percentage * getCurrentResistance()));
    }

    friend void operator<<(ostream &os, Ship* ship) { // Print ship information
        ship->printInfo();
    }

    bool operator>(Ship* otherShip) { // Compare treasure with another ship
        return getTreasure() > otherShip->getTreasure();
    }

    /** Set the ship's location on the map */
    void setLocation(Map*& map) {
        bool locationSet = false; // Flag to check if location is successfully set
        while (!locationSet) {
            srand(static_cast<unsigned int>(time(0)));
            int x = rand() % ARRAYSIZEX;
            int y = rand() % ARRAYSIZEY;
            if (map->locations[x][y].isEmpty()) {
                map->locations[x][y].setHasShip(true);
                setX(x);
                setY(y);
                locationSet = true;
            }
        }
    }

    /** Print the ship's location */
    void printLocation() {
        cout << "The ship's location is (" << getX() << "," << getY() << ")" << endl;
    }

    /** Print detailed information about the ship */
    void printInfo() {
        cout << "Ship " << getVectorIndex() << " : " << endl;
        cout << "Maximum Resistance : " << getMaxResistance() << endl;
        cout << "Current Resistance : " << getCurrentResistance() << endl;
        cout << "Speed : " << getSpeed() << endl;
        cout << "Treasure : " << getTreasure() << endl;
        cout << "Blocks Moved : " << getBlocksMoved() << endl;
        cout << "Total Damage : " << getTotalDamageTaken() << endl;
        printLocation();
        printType();
    }

    /** Move the ship on the map */
    void movement(int x, int y, int speed, Map* map) {
        if (getCurrentResistance() > 0) {
            srand(static_cast<unsigned int>(time(0)));
            int attempts = 0; // Counter for movement attempts
            bool moved = false; // Flag to indicate successful movement
            int direction = rand() % 4; // Random direction to move

            while (!moved) {
                switch (direction) {
                    case 0: // Move up
                        if ((x - speed) >= 0 && map->locations[x - speed][y].isEmpty()) {
                            map->locations[x][y].setHasShip(false);
                            setX(x - speed);
                            map->locations[x - speed][y].setHasShip(true);
                            moved = true;
                            setBlocksMoved(getBlocksMoved() + speed);
                        } else {
                            attempts++;
                            direction++;
                        }
                        break;
                    case 1: // Move right
                        if ((y + speed) <= (ARRAYSIZEY - 1) && map->locations[x][y + speed].isEmpty()) {
                            map->locations[x][y].setHasShip(false);
                            setY(y + speed);
                            map->locations[x][y + speed].setHasShip(true);
                            moved = true;
                            setBlocksMoved(getBlocksMoved() + speed);
                        } else {
                            attempts++;
                            direction++;
                        }
                        break;
                    case 2: // Move down
                        if ((x + speed) <= (ARRAYSIZEX - 1) && map->locations[x + speed][y].isEmpty()) {
                            map->locations[x][y].setHasShip(false);
                            setX(x + speed);
                            map->locations[x + speed][y].setHasShip(true);
                            moved = true;
                            setBlocksMoved(getBlocksMoved() + speed);
                        } else {
                            attempts++;
                            direction++;
                        }
                        break;
                    case 3: // Move left
                        if ((y - speed) >= 0 && map->locations[x][y - speed].isEmpty()) {
                            map->locations[x][y].setHasShip(false);
                            setY(y - speed);
                            map->locations[x][y - speed].setHasShip(true);
                            moved = true;
                            setBlocksMoved(getBlocksMoved() + speed);
                        } else {
                            attempts++;
                            direction = 0; // Reset direction
                        }
                        break;
                }
                if (attempts >= 4) {
                    break; // Exit if all directions have been tried
                }
            }
        }
    }

    /** Print the type of the ship */
    void printType() {
        switch (getType()) {
            case 1: cout << "Type : Pirate Ship" << endl; break;
            case 2: cout << "Type : Merchant Ship" << endl; break;
            case 3: cout << "Type : Repair Ship" << endl; break;
            case 4: cout << "Type : Exploration Ship" << endl; break;
            case 5: cout << "Type : Naval Ship" << endl; break;
            case 6: cout << "Type : Submarine" << endl; break;
        }
    }

    /** Virtual method for ship-specific operations */
    virtual void operation(int x, int y, Map* map, vector<Ship*> ships) {}

    /** Find a ship at the specified coordinates */
    Ship* findShip(int x, int y, vector<Ship*> ships) {
        for (unsigned int i = 0; i < ships.size(); i++) {
            if (ships[i]->getX() == x && ships[i]->getY() == y) {
                return ships[i];
            }
        }
        return nullptr;
    }

    /** Getters and Setters **/
    void setVectorIndex(int index) { vectorIndex = index; }
    int getVectorIndex() { return vectorIndex; }
    void setMaxResistance(int resistance) { maxResistance = resistance; }
    int getMaxResistance() { return maxResistance; }
    void setCurrentResistance(int resistance) { currentResistance = resistance; }
