};

/** Class representing Pirate Ships, inheriting from Ship */
class PirateShip : public Ship {
private:
    int attackDamage = 20;          // Damage inflicted by the pirate ship
    int totalDamageCaused = 0;      // Total damage caused by this pirate ship

public:
    PirateShip() {
        setTreasure(50);
        setMaxResistance(500);
        setCurrentResistance(getMaxResistance());
        setSpeed(1);
        setType(1);
    }

    /** Execute the operation of the pirate ship */
    virtual void operation(int x, int y, Map* map, vector<Ship*> ships) {
        if (getCurrentResistance() > 0) {
            Ship* target = nullptr; // Target ship to attack
            bool targetFound = false; // Flag to indicate if a target is found

            // Check surrounding positions for a target ship
            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    if (abs(dx) + abs(dy) == 1) { // Only check adjacent positions
                        if (x + dx >= 0 && x + dx < ARRAYSIZEX && y + dy >= 0 && y + dy < ARRAYSIZEY) {
                            if (map->locations[x + dx][y + dy].getHasShip()) {
                                target = findShip(x + dx, y + dy, ships);
                                if (target && target->getCurrentResistance() > 0) {
                                    targetFound = true;
                                    break;
                                }
                            }
                        }
                    }
                }
                if (targetFound) break;
            }

            // If a target ship is found, attack it
            if (targetFound) {
                target->setCurrentResistance(target->getCurrentResistance() - attackDamage);
                totalDamageCaused += attackDamage;
                int treasureLost = target->getTreasure();
                target->setTreasure(treasureLost * 0.8); // Target loses 20% of its treasure
                setTreasure(getTreasure() + treasureLost * 0.2); // Pirate gains 20% of the target's treasure
                target->setTotalDamageTaken(target->getTotalDamageTaken() + attackDamage);

                // Update global damage counters based on target type
                switch (target->getType()) {
                    case 1: totalPirateDamage += attackDamage; break;
                    case 2: totalMerchantDamage += attackDamage; break;
                    case 3: totalRepairDamage += attackDamage; break;
                    case 4: totalExplorationDamage += attackDamage; break;
                    case 5: totalNavalDamage += attackDamage; break;
                    case 6: totalSubmarineDamage += attackDamage; break;
                }

                cout << "Ship " << target->getVectorIndex() << " has been damaged due to a battle with Ship " << getVectorIndex() << endl;
                cout << "Ship " << target->getVectorIndex() << " has lost " << treasureLost * 0.2 << " coins due to a battle with Ship " << getVectorIndex() << endl;
                cout << "Ship " << getVectorIndex() << " has gained " << treasureLost * 0.2 << " coins due to a battle with Ship " << target->getVectorIndex() << endl;
            }
        }
    }

    /** Getters and Setters **/
    void setAttackDamage(int damage) { attackDamage = damage; }
    int getAttackDamage() { return attackDamage; }
    void setTotalDamageCaused(int damage) { totalDamageCaused = damage; }
    int getTotalDamageCaused() { return totalDamageCaused; }
};

