/** Class representing Repair Ships, inheriting from Ship */
class RepairShip : public Ship {
private:
    int totalHealing = 0;           // Total healing performed by this repair ship

public:
    RepairShip() {
        setTreasure(50);
        setMaxResistance(250);
        setCurrentResistance(getMaxResistance());
        setSpeed(2);
        setType(3);
    }

    /** Execute the operation of the repair ship */
    virtual void operation(int x, int y, Map* map, vector<Ship*> ships) {
        Ship* target = nullptr; // Target ship to repair
        bool targetFound = false; // Flag to indicate if a target is found

        if (getCurrentResistance() > 0) {
            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    if (abs(dx) + abs(dy) == 1) { // Only check adjacent positions
                        if (x + dx >= 0 && x + dx < ARRAYSIZEX && y + dy >= 0 && y + dy < ARRAYSIZEY) {
                            if (map->locations[x + dx][y + dy].getHasShip()) {
                                target = findShip(x + dx, y + dy, ships);
                                if (target && target->getCurrentResistance() < target->getMaxResistance()) {
                                    targetFound = true;
                                    break;
                                }
                            }
                        }
                    }
                }
                if (targetFound) break;
            }

            // If a target ship is found, repair it
            if (targetFound) {
                int damage = target->getMaxResistance() - target->getCurrentResistance();
                if (damage > 0) {
                    if (damage < target->getTreasure()) {
                        target->setCurrentResistance(target->getMaxResistance());
                        target->setTreasure(target->getTreasure() - damage);
                        totalHealing += damage;
                        cout << "Ship " << target->getVectorIndex() << " has been repaired by Ship " << getVectorIndex() << endl;
                        cout << "This action has cost to Ship " << target->getVectorIndex() << " , " << damage << " coins" << endl;
                    } else {
                        totalHealing += target->getTreasure();
                        target->setCurrentResistance(target->getMaxResistance());
                        target->setTreasure(0);
                        cout << "Ship " << target->getVectorIndex() << " has been repaired by Ship " << getVectorIndex() << endl;
                        cout << "This action has cost to Ship " << target->getVectorIndex() << " , all of its treasure" << endl;
                    }
                }
            }
        }
    }

    /** Getters and Setters **/
    int getTotalHealing() { return totalHealing; }
    void setTotalHealing(int healing) { totalHealing = healing; }
};

/** Class representing Exploration Ships, inheriting from Ship */
class ExplorationShip : public Ship {
public:
    ExplorationShip() {
        setTreasure(80);
        setMaxResistance(300);
        setCurrentResistance(getMaxResistance());
        setSpeed(5);
        setType(4);
    }

    /** Execute the operation of the exploration ship */
    virtual void operation(int x, int y, Map* map, vector<Ship*> ships) {
        bool moved = false; // Flag to track if movement has occurred

        if (getCurrentResistance() > 0) {
            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    if (abs(dx) + abs(dy) == 1) { // Only check adjacent positions
                        if (x + dx >= 0 && x + dx < ARRAYSIZEX && y + dy >= 0 && y + dy < ARRAYSIZEY) {
                            if (map->locations[x + dx][y + dy].getHasShip() || map->locations[x + dx][y + dy].getWeather() >= 7) {
                                movement(dx, map); // Move in the opposite direction
                                cout << "Ship " << getVectorIndex() << " has moved to avoid danger." << endl;
                                moved = true;
                                break;
                            }
                        }
                    }
                }
                if (moved) break;
            }
        }
    }

    /** Move the exploration ship */
    void movement(int direction, Map* map) {
        int x = getX();
        int y = getY();
        int speed = 1; // Default speed for exploration ships

        switch (direction) {
            case 0: // Up
                if (x - speed >= 0 && map->locations[x - speed][y].isEmpty()) {
                    map->locations[x][y].setHasShip(false);
                    setX(x - speed);
                    map->locations[x - speed][y].setHasShip(true);
                    setBlocksMoved(getBlocksMoved() + speed);
                }
                break;
            case 1: // Right
                if (y + speed <= (ARRAYSIZEY - 1) && map->locations[x][y + speed].isEmpty()) {
                    map->locations[x][y].setHasShip(false);
                    setY(y + speed);
                    map->locations[x][y + speed].setHasShip(true);
                    setBlocksMoved(getBlocksMoved() + speed);
                }
                break;
            case 2: // Down
                if (x + speed <= ARRAYSIZEX - 1 && map->locations[x + speed][y].isEmpty()) {
                    map->locations[x][y].setHasShip(false);
                    setX(x + speed);
                    map->locations[x + speed][y].setHasShip(true);
                    setBlocksMoved(getBlocksMoved() + speed);
                }
                break;
            case 3: // Left
                if (y - speed >= 0 && map->locations[x][y - speed].isEmpty()) {
                    map->locations[x][y].setHasShip(false);
                    setY(y - speed);
                    map->locations[x][y - speed].setHasShip(true);
                    setBlocksMoved(getBlocksMoved() + speed);
                }
                break;
        }
    }
};

