        setSpeed(1);
        setType(5);
    }

    /** Execute the operation of the naval ship */
    virtual void operation(int x, int y, Map* map, vector<Ship*> ships) {
        Ship* target = nullptr; // Target ship to attack
        bool targetFound = false; // Flag to indicate if a target is found

        if (getCurrentResistance() > 0) {
            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    if (abs(dx) + abs(dy) == 1) { // Only check adjacent positions
                        if (x + dx >= 0 && x + dx < ARRAYSIZEX && y + dy >= 0 && y + dy < ARRAYSIZEY) {
                            if (map->locations[x + dx][y + dy].getHasShip()) {
                                target = findShip(x + dx, y + dy, ships);
                                if (target && target->getCurrentResistance() > 0) {
                                    targetFound = true;
                                    break;
                                }
                            }
                        }
                    }
                }
                if (targetFound) break;
            }

            // If a target ship is found, attack it
            if (targetFound) {
                if (target->getType() == 1) { // If the target is a pirate ship
                    int damage = target->getCurrentResistance() - getCurrentResistance();
                    if (damage > 0) {
                        totalPirateDamage += getCurrentResistance();
                        target->setCurrentResistance(damage);
                        target->setTotalDamageTaken(target->getTotalDamageTaken() + damage);
                        setCurrentResistance(0); // Naval ship is destroyed
                        cout << "Ship " << getVectorIndex() << " has dealt " << damage << " damage to Ship " << target->getVectorIndex() << endl;
                    } else {
                        totalPirateDamage += target->getCurrentResistance();
                        setCurrentResistance(-damage);
                        setTotalDamageTaken(getTotalDamageTaken() + damage);
                        cout << "Ship " << getVectorIndex() << " has dealt " << target->getCurrentResistance() << " damage to Ship " << target->getVectorIndex() << endl;
                        target->setCurrentResistance(0); // Target is destroyed
                    }
                }
            }
        }
    }
