/** Class representing Submarines, inheriting from PirateShip */
class Submarine : public PirateShip {
private:
    int kills = 0; // Number of ships destroyed by this submarine

public:
    Submarine() {
        setTreasure(50);
        setMaxResistance(300);
        setCurrentResistance(getMaxResistance());
        setSpeed(1);
        setType(6);
    }

    /** Execute the operation of the submarine */
    virtual void operation(int x, int y, Map* map, vector<Ship*> ships) {
        if (getCurrentResistance() > 0) {
            Ship* target = nullptr; // Target ship to attack
            bool targetFound = false; // Flag to indicate if a target is found

            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    if (abs(dx) + abs(dy) == 1) { // Only check adjacent positions
                        if (x + dx >= 0 && x + dx < ARRAYSIZEX && y + dy >= 0 && y + dy < ARRAYSIZEY) {
                            if (map->locations[x + dx][y + dy].getHasShip()) {
                                target = findShip(x + dx, y + dy, ships);
                                if (target && target->getCurrentResistance() > 0) {
                                    targetFound = true;
                                    break;
                                }
                            }
                        }
                    }
                }
                if (targetFound) break;
            }

            // If a target ship is found, attack it
            if (targetFound) {
                if (kills < 3) { // Check if the submarine has already destroyed 3 ships
                    switch (target->getType()) {
                        case 1: totalPirateDamage += target->getCurrentResistance(); break;
                        case 2: totalMerchantDamage += target->getCurrentResistance(); break;
                        case 3: totalRepairDamage += target->getCurrentResistance(); break;
                        case 4: totalExplorationDamage += target->getCurrentResistance(); break;
                        case 5: totalNavalDamage += target->getCurrentResistance(); break;
                        case 6: totalSubmarineDamage += target->getCurrentResistance(); break;
                    }
                    kills++; // Increment kill count
                    target->setTotalDamageTaken(target->getTotalDamageTaken() + target->getCurrentResistance());
                    target->setCurrentResistance(0); // Target is destroyed
                    setTreasure(target->getTreasure() + getTreasure()); // Gain target's treasure
                    target->setTreasure(0); // Target's treasure is set to 0
                    cout << "Ship " << target->getVectorIndex() << " has been damaged due to a battle with Ship " << getVectorIndex() << endl;
                    cout << "Ship " << getVectorIndex() << " has acquired all the treasure of Ship " << target->getVectorIndex() << endl;
                } else {
                    totalSubmarineDamage += getCurrentResistance();
                    setTotalDamageTaken(getTotalDamageTaken() + getCurrentResistance());
                    setCurrentResistance(0); // Submarine is destroyed
                    target->setTreasure(getTreasure() + target->getTreasure()); // Target gains submarine's treasure
                    setTreasure(0); // Submarine's treasure is set to 0
                    cout << "Ship " << target->getVectorIndex() << " has acquired all the treasure of Ship " << getVectorIndex() << endl;
                }
            }
        }
    }

    /** Getters and Setters **/
    int getKills() { return kills; }
    void setKills(int killCount) { kills = killCount; }
};

