class Account {
    int accountNumber;
    char accountHolderName[50];
    char accountType;
    int balanceAmount;

public:
    void createAccount();    
    void displayAccount() const;    
    void modifyAccount();    
    void depositAmount(int);    
    void withdrawAmount(int);    
    void generateReport() const;    
    int getAccountNumber() const;    
    int getBalanceAmount() const;    
    char getAccountType() const;    
};         

void Account::createAccount() {
    cin >> accountNumber;
    cin.ignore();
    cin.getline(accountHolderName, 50);
    cin >> accountType;
    accountType = toupper(accountType);
    cin >> balanceAmount;
    cout << "\n\n\nAccount Created..";
}

void Account::displayAccount() const {
    cout << "\nAccount No. : " << accountNumber;
    cout << "\nAccount Holder Name : " << accountHolderName;
    cout << "\nAccount Type : " << accountType;
    cout << "\nBalance Amount : " << balanceAmount;
}

void Account::depositAmount(int amount) {
    balanceAmount += amount;
}

void Account::withdrawAmount(int amount) {
    balanceAmount -= amount;
}

void Account::modifyAccount() {
    cout << "\nAccount No. : " << accountNumber;
    cout << "\nModify Account Holder Name : ";
    cin.ignore();
    cin.getline(accountHolderName, 50);
    cout << "\nModify Account Type : ";
    cin >> accountType;
    accountType = toupper(accountType);
    cout << "\nModify Balance Amount : ";
    cin >> balanceAmount;
}

int Account::getAccountNumber() const {
    return accountNumber;
}

int Account::getBalanceAmount() const {
    return balanceAmount;
}

char Account::getAccountType() const {
    return accountType;
}

void Account::generateReport() const {
    cout << accountNumber << setw(10) << " " << accountHolderName << setw(10) << " " << accountType << setw(6) << balanceAmount << endl;
}

