using namespace std;

class User {
protected:
    char *firstName, *lastName, *city, *state, *address, *pancard;
    double mobileNumber, birthDay, birthMonth, birthYear;

public:
    long double balance;

    User() {}

    User(char *fName, char *lName, char *addr, char *cty, char *st, char *pc, double day, double month, double year, double mobile) {
        firstName = new char[strlen(fName) + 1];
        lastName = new char[strlen(lName) + 1];
        city = new char[strlen(cty) + 1];
        state = new char[strlen(st) + 1];
        address = new char[strlen(addr) + 1];
        pancard = new char[strlen(pc) + 1];

        strcpy(firstName, fName);
        strcpy(lastName, lName);
        strcpy(city, cty);
        strcpy(state, st);
        strcpy(address, addr);
        strcpy(pancard, pc);

        birthDay = day;
        birthMonth = month;
        birthYear = year;
        mobileNumber = mobile;
    }
};

class NewUser : public User {
public:
    double accountNumber;

    NewUser(char *fName, char *lName, char *addr, char *cty, char *st, char *pc, double day, double month, double year, double mobile)
        : User(fName, lName, addr, cty, st, pc, day, month, year, mobile) {}

    void generateAccountNumber() {
        long double tempBalance;
        string userString;
        fstream file;

        file.open("data.txt");
        while (!file.eof()) {
            cout << "Reading file";
            file >> firstName >> lastName >> mobileNumber >> birthDay >> birthMonth >> birthYear >> pancard >> address >> city >> state >> tempBalance >> userString >> accountNumber;
        }
        file.close();

        accountNumber += 1;
        cout << "\nYour Account No is: " << accountNumber;
    }

    void displayUserInfo() {
        cout << "Account holder name: " << firstName << " " << lastName;
        cout << "\nMobile No: " << mobileNumber;
        cout << "\nBirth Date: " << birthDay << "-" << birthMonth << "-" << birthYear;
        cout << "\nPancard No: " << pancard;
        cout << "\nAddress: " << address;
        cout << "\nCity: " << city;
        cout << "\nState: " << state;
    }

    virtual void displayDetails() {}
};

class SavingAccount : public NewUser {
    string username;

public:
    SavingAccount(string user, char *fName, char *lName, char *addr, char *cty, char *st, char *pc, double day, double month, double year, double mobile)
        : NewUser(fName, lName, addr, cty, st, pc, day, month, year, mobile), username(user) {}

    void displayDetails() override {
        cout << "**Account details**";
        cout << "\nThis account is a Saving Account";
        displayUserInfo();
        generateAccountNumber();
    }
};

class CurrentAccount : public NewUser {
    string username;

public:
    CurrentAccount(string user, char *fName, char *lName, char *addr, char *cty, char *st, char *pc, double day, double month, double year, double mobile)
        : NewUser(fName, lName, addr, cty, st, pc, day, month, year, mobile), username(user) {}

    void displayDetails() override {
        cout << "**Account details**";
        cout << "\nThis account is a Current Account";
        displayUserInfo();
        generateAccountNumber();
    }
};

class ExistingUser : public User {
    long double balance;

public:
    double accountNumber;
    int status;

    ExistingUser(double bal, double accNum, char *fName, char *lName, char *addr, char *cty, char *st, char *pc, double day, double month, double year, double mobile)
        : User(fName, lName, addr, cty, st, pc, day, month, year, mobile), balance(bal), accountNumber(accNum) {}

    void displayDetails(long double currentBalance) {
        balance = currentBalance;
        cout << "Account holder name: " << firstName << " " << lastName;
        cout << "\nAccount No: " << accountNumber;
        cout << "\nBirth Date: " << birthDay << "-" << birthMonth << "-" << birthYear;
        cout << "\nMobile No: " << mobileNumber;
        cout << "\nPancard No: " << pancard;
        cout << "\nAddress: " << address;
        cout << "\nCity: " << city;
        cout << "\nState: " << state;
        cout << "\nYour current Balance is: " << balance;
    }

    int checkBalance(long double amount) {
        return (balance == amount) ? 1 : 0;
    }
};

class Transaction {
    long double amount;
    User *user;

public:
    Transaction(long double amt, User *usr) : amount(amt), user(usr) {}

    void withdraw(long double amt) {
        user->balance -= amt;
        cout << "Transaction Done!!";
        cout << "\nUpdated Balance is: " << user->balance;
    }

    void deposit(long double amt) {
        user->balance += amt;
        cout << "Transaction Done!!";
        cout << "\nUpdated Balance is: " << user->balance;
    }
};

void saveUserData(char *firstName, char *lastName, double mobile, double day, double month, double year, char *pancard, char *address, char *city, char *state, long double balance, string username, double accountNumber) {
    fstream myfile;
    myfile.open("data.txt", ios_base::app);
    myfile << firstName << " " << lastName << " " << mobile << " " << day << " " << month << " " << year << " " << pancard << " " << address << " " << city << " " << state << " " << balance << " " << username << " " << accountNumber << "\n";
    myfile.close();
}

void saveUserCredentials(string username, string password) {
    fstream userFile;
    userFile.open("uid.txt", ios_base::app);
    userFile << username << "\n";
    userFile.close();

    fstream passFile;
    passFile.open("pass.txt", ios_base::app);
    passFile << username << " " << password << "\n";
    passFile.close();
}

