#include <iostream>
#include <tr1/unordered_map>

using std::tr1::unordered_map;

class SeqNumManager {
public:
    // Initializes the sequence number manager with a maximum sequence number.
    SeqNumManager(short maxSeqNum) 
        : maxSequenceNumber(maxSeqNum) {}; 

    // Increments the sequence number for a given MAC address or initializes it for unseen MAC addresses.
    void increment(short macAddress);

    // Retrieves the sequence number for a given MAC address.
    // Returns the sequence number or -1 if the address is not in the list.
    short getSeqNum(short macAddress);

private:
    unordered_map<short, short> macAddressMap; // Maps MAC addresses to their sequence numbers
    short maxSequenceNumber; // Maximum allowable sequence number
};

inline
void SeqNumManager::increment(short macAddress) {
    short currentSeqNum; // Holds the current sequence number

    // Check if the MAC address already exists in the map
    if (macAddressMap.count(macAddress)) {
        if (macAddressMap[macAddress] < maxSequenceNumber) {
            currentSeqNum = macAddressMap[macAddress] + 1; // Increment the existing sequence number
            macAddressMap.erase(macAddress);  // Remove the old entry
            macAddressMap[macAddress] = currentSeqNum; // Update with the new incremented value
        } else {
            macAddressMap.erase(macAddress);  // Remove the old entry
            macAddressMap[macAddress] = 0; // Reset sequence number to zero due to rollover
        }
    } else {
        macAddressMap[macAddress] = 0; // Initialize entry for a new MAC address
    }
}

inline
short SeqNumManager::getSeqNum(short macAddress) {
    // Check if the MAC address exists and return its sequence number
    if (macAddressMap.count(macAddress)) {
        return macAddressMap[macAddress];  
    } else {
        return -1;  // Return -1 if the address does not exist
    }
}

