#ifndef CASTLE_H
#define CASTLE_H

#include <iostream>
#include <fstream>
#include <string>
#include <vector>

using std::cin;
using std::cout;
using std::string;
using std::vector;

#include "room.h"
#include "norroom.h"

typedef Room* RoomPointer; 
typedef vector<RoomPointer> RoomCollection;

class Castle {

public:
    // Constructor initializes the castle with a name and a layout from a file.
    Castle(const string& castleName, const string& layoutFile) : name(castleName) {
        int roomIndex = 0;
        string line;
        ifstream inputFile(layoutFile);
        inputFile >> line;
        this->width = line.size();

        // Read the layout line by line to create rooms.
        while (!inputFile.eof()) {
            for (int i = 0; i < line.size(); i++) {
                string roomType = determineRoomType(line[i]);
                RoomPointer room = new NorRoom(to_string(roomIndex) + "Room", roomType);
                rooms.push_back(room);

                if (roomType == "lobbry") {
                    startingRoom = room;
                }

                roomIndex++;
            }

            this->height++;
            inputFile >> line;
        }

        // Establish connections between rooms based on their positions.
        connectRooms();

        cout << "The castle came, game start." << endl;
    }

    // Destructor cleans up allocated room objects.
    virtual ~Castle() {
        for (RoomCollection::iterator it = rooms.begin(); it != rooms.end(); ++it) {
            delete *it;
        }
        cout << "The castle disappeared." << endl;
    }

private:
    string name;
    RoomCollection rooms;
    RoomPointer startingRoom;
    int height = 0, width = 0;

    static vector<string> directions;

    // Determines the type of room based on the character representation.
    string determineRoomType(char roomChar) {
        switch (roomChar) {
            case '-': return "normal";
            case '^': return "lobbry";
            case '$': return "princess";
            case '*': return "monster";
            default: return "locked";
        }
    }

    // Connects rooms by setting doors between adjacent rooms.
    void connectRooms() {
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                int roomIndex = i * width + j;
                RoomPointer currentRoom = rooms[roomIndex];

                if (currentRoom->isType("locked")) {
                    continue;
                }

                connectNorth(roomIndex, currentRoom);
                connectWest(roomIndex, currentRoom);
            }
        }
    }

    // Connects the current room to the room to the north if possible.
    void connectNorth(int roomIndex, RoomPointer currentRoom) {
        int northIndex = roomIndex - width;
        if (northIndex >= 0 && northIndex < height * width) {
            RoomPointer northRoom = rooms[northIndex];
            if (!northRoom->isType("locked")) {
                currentRoom->setDoor("north", northRoom);
                northRoom->setDoor("south", currentRoom);
            }
        }
    }

    // Connects the current room to the room to the west if possible.
    void connectWest(int roomIndex, RoomPointer currentRoom) {
        int westIndex = roomIndex - 1;
        if (westIndex >= 0 && roomIndex % width != 0) {
            RoomPointer westRoom = rooms[westIndex];
            if (!westRoom->isType("locked")) {
                currentRoom->setDoor("west", westRoom);
                westRoom->setDoor("east", currentRoom);
            }
        }
    }

public:
    // Main game loop where the player navigates the castle.
    void run() {
        bool princessCaptured = false; 
        RoomPointer currentRoom = startingRoom;

        while (true) {
            currentRoom->showInfo(directions);

            if (currentRoom->isType("monster")) {
                cout << "You die. Game over!" << endl;
                break;
            } else if (currentRoom->isType("princess")) {
                if (!princessCaptured) {
                    princessCaptured = true;
                    cout << "You get the princess. Come back" << endl;
                }
            } else if (currentRoom->isType("lobbry")) {
                if (princessCaptured) {
                    cout << "You win!" << endl;
                    break;
                }
            }

            cout << ">>> ";
            string command;
            cin >> command;
            if (currentRoom->existDoor(command)) {
                currentRoom = currentRoom->getDoor(command);
            } else {
                cout << "You input a wrong direction." << endl;
            }
        }
    }
};

vector<string> Castle::directions = {
    "north", "south",
    "west", "east"
};

#endif //CASTLE_H

