using std::string;
using std::vector;
using std::map;

typedef class Room* RoomPtr;
typedef map<string, RoomPtr> DoorMap;

class Room {
public:
    // Constructor to initialize the room with a name
    Room(const string& roomName) : name(roomName) {}

    virtual ~Room() {}

private:
    string name; // Name of the room
    DoorMap doors; // Mapping of doors to connected rooms

public:
    // Retrieve the name of the room
    string getName() const {
        return name;
    }

    // Set a door leading to another room
    void setDoor(const string& direction, RoomPtr connectedRoom) {
        doors[direction] = connectedRoom;
    }

    // Get the room connected by a specific door
    RoomPtr getDoor(const string& direction) {
        return existDoor(direction) ? doors[direction] : nullptr;
    }

    // Check if a door exists in the specified direction
    bool existDoor(const string& direction) const {
        return doors.find(direction) != doors.end();
    }

    // Abstract method to display room information
    virtual void showInfo(vector<string>) const = 0;

    // Abstract method to check the type of the room (e.g., princess, monster, lobby)
    virtual bool isType(const string&) const = 0;
};

#endif // ROOM_H

