// Function to handle user choice for menu navigation
int UserInfo::getChoice() {
    int currentIndex = 0;
    int end = 0;

    do {
        int key = getch();
        switch (key) {
            case 80: // Down arrow key
                switch (currentIndex) {
                    case 0:
                        setfillstyle(1, 2);
                        bar3d(300, 180, 500, 230, 4, 1);
                        setcolor(0);
                        outtextxy(320, 110, "  Access account");
                        setfillstyle(1, 3);
                        bar3d(300, 100, 500, 150, 4, 1);
                        setcolor(6);
                        outtextxy(303, 190, " Create new account");
                        currentIndex++;
                        break;
                    case 1:
                        setfillstyle(1, 3);
                        bar3d(300, 100, 500, 150, 4, 1);
                        setcolor(6);
                        outtextxy(320, 110, "  Access account");
                        setfillstyle(1, 2);
                        bar3d(300, 265, 500, 310, 4, 1);
                        setcolor(0);
                        outtextxy(380, 275, "Exit");
                        currentIndex++;
                        break;
                }
                break;
            case 72: // Up arrow key
                switch (currentIndex) {
                    case 1:
                        setfillstyle(1, 3);
                        bar3d(300, 180, 500, 230, 4, 1);
                        setcolor(6);
                        outtextxy(303, 190, " Create new account");
                        setcolor(0);
                        setfillstyle(1, 2);
                        bar3d(300, 100, 500, 150, 4, 1);
                        outtextxy(320, 110, "  Access account");
                        currentIndex--;
                        break;
                    case 2:
                        setfillstyle(1, 3);
                        bar3d(300, 265, 500, 310, 4, 1);
                        setcolor(6);
                        outtextxy(380, 275, "Exit");
                        currentIndex--;
                        break;
                }
                break;
            case 13: // Enter key
                end = 1;
                break;
        }
    } while (end != 1);

    return currentIndex;
}

