// Function to insert account details
void UserInfo::insertAccountDetails(int page) {
    date* currentDate;
    getdate(currentDate);
    std::fstream infoFile, masterFile;

    infoFile.open("info.dat", std::ios::binary | std::ios::app | std::ios::in);
    masterFile.open("master.dat", std::ios::binary | std::ios::app);

    if (!infoFile || !masterFile) {
        std::cerr << "File doesn't open";
        getch();
        exit(0);
    }

    std::fstream banFile;
    if (page == 1) {
        banFile.open("ban.dat", std::ios::app | std::ios::binary);
        if (!banFile) {
            std::cerr << "Ban file doesn't open";
            getch();
            exit(0);
        }
    }

    // Input fields for account creation
    char tempBuffer[50];
    int index = 0;

    // Input for name
    do {
        outtextxy(250, 135, "_");
        while ((tempBuffer[index] = getch()) != 13) {
            outtextxy(250, 135, tempBuffer);
            index++;
        }
        tempBuffer[index] = '\0';
        if (tempBuffer[0] == '\0') {
            outtextxy(2, 410, "FILL NAME FIELD");
            index = 0; // Reset index for re-entry
        }
    } while (tempBuffer[0] == '\0');

    // Input for password
    index = 0;
    char passwordBuffer[50];
    do {
        outtextxy(250, 135, "_");
        while ((passwordBuffer[index] = getche()) != 13) {
            outtextxy(250, 135, "*");
            index++;
        }
        passwordBuffer[index] = '\0';
        if (index < 5) {
            outtextxy(2, 425, "Password length short");
            index = 0; // Reset index for re-entry
        }
    } while (index < 5);

    // Input for gender
    index = 0;
    do {
        outtextxy(250, 170, "_");
        while ((gender[index] = getch()) != 13) {
            outtextxy(250, 170, gender);
            index++;
        }
        gender[index] = '\0';
    } while (index == 0);

    // Input for address
    index = 0;
    do {
        outtextxy(250, 205, "_");
        while ((address[index] = getche()) != 13) {
            outtextxy(250, 205, address);
            index++;
        }
        address[index] = '\0';
    } while (index == 0);

    // Input for city
    index = 0;
    do {
        outtextxy(250, 240, "_");
        while ((city[index] = getche()) != 13) {
            outtextxy(250, 240, city);
            index++;
        }
        city[index] = '\0';
    } while (index == 0);

    // Input for state
    index = 0;
    do {
        outtextxy(250, 275, "_");
        while ((state[index] = getche()) != 13) {
            outtextxy(250, 275, state);
            index++;
        }
        state[index] = '\0';
    } while (index == 0);

    // Input for pin code
    index = 0;
    do {
        outtextxy(250, 310, "_");
        while ((pinCode[index] = getche()) != 13) {
            outtextxy(250, 310, pinCode);
            index++;
        }
        pinCode[index] = '\0';
    } while (index == 0);

    // Input for mobile number
    index = 0;
    do {
        outtextxy(250, 345, "_");
        while ((mobile[index] = getche()) != 13) {
            outtextxy(250, 345, mobile);
            index++;
        }
        mobile[index] = '\0';
    } while (index == 0);

    // Input for email ID
    index = 0;
    do {
        outtextxy(250, 380, "_");
        while ((email[index] = getche()) != 13) {
            outtextxy(250, 380, email);
            index++;
        }
        email[index] = '\0';
    } while (index == 0);

    // Input for deposit amount
    do {
        outtextxy(250, 415, "_");
        std::cin >> depositAmount;
        if (depositAmount < 1000) {
            outtextxy(2, 440, "Minimum deposit is 1000");
        }
    } while (depositAmount < 1000);

    // Generate account number
    unsigned long accountNumber = 1000 + (infoFile.tellg() / sizeof(UserInfo));
    currentBalance = depositAmount;

    // Write account details to files
    infoFile.write((char*)this, sizeof(UserInfo));
    banFile.write((char*)&accountNumber, sizeof(unsigned long));
    masterFile.write((char*)&accountNumber, sizeof(unsigned long));

    // Display success message
    setfillstyle(1, 15);
    bar3d(160, 8, 632, 455, 4, 1);
    setcolor(6);
    settextstyle(0, 0, 3);
