// Function to handle back key navigation
int UserInfo::handleBackKey() {
    int currentIndex = 0;
    int end = 0;

    setfillstyle(6, 3);
    fillellipse(550, 400, 50, 30);
    outtextxy(510, 390, "EXIT");
    setfillstyle(6, 9);
    fillellipse(250, 400, 50, 30);
    outtextxy(210, 390, "BACK");

    do {
        int key = getch();
        switch (key) {
            case 77: // Right arrow key
                switch (currentIndex) {
                    case 1:
                        setfillstyle(6, 3);
                        fillellipse(550, 400, 50, 30);
                        outtextxy(510, 390, "EXIT");
                        setfillstyle(6, 9);
                        fillellipse(250, 400, 50, 30);
                        outtextxy(210, 390, "BACK");
                        currentIndex--;
                        break;
                    case 0:
                        setfillstyle(6, 9);
                        fillellipse(550, 400, 50, 30);
                        outtextxy(510, 390, "EXIT");
                        setfillstyle(6, 3);
                        fillellipse(250, 400, 50, 30);
                        outtextxy(210, 390, "BACK");
                        currentIndex++;
                        break;
                }
                break;
            case 75: // Left arrow key
                switch (currentIndex) {
                    case 1:
                        setfillstyle(6, 3);
                        fillellipse(550, 400, 50, 30);
                        outtextxy(510, 390, "EXIT");
                        setfillstyle(6, 9);
                        fillellipse(250, 400, 50, 30);
                        outtextxy(210, 390, "BACK");
                        currentIndex--;
                        break;
                    case 0:
                        setfillstyle(6, 9);
                        fillellipse(550, 400, 50, 30);
                        outtextxy(510, 390, "EXIT");
                        setfillstyle(6, 3);
                        fillellipse(250, 400, 50, 30);
                        outtextxy(210, 390, "BACK");
                        currentIndex++;
                        break;
                }
                break;
            case 13: // Enter key
                end = 1;
                break;
        }
    } while (end != 1);
    return currentIndex;
}

