void UserInfo::checkAccount() {
    setfillstyle(1, 15);
    bar3d(160, 8, 632, 455, 4, 1);
    setcolor(6);
    settextstyle(8, 0, 2);
    outtextxy(220, 100, "Account no:-");
    outtextxy(220, 150, "Password:-");

    rectangle(400, 105, 600, 130);
    rectangle(400, 155, 600, 180);

    unsigned long tempAccount;
    char tempPassword[50];
    std::fstream masterFile;
    masterFile.open("master.dat", std::ios::binary | std::ios::in);

    if (!masterFile) {
        std::cerr << "File doesn't exist";
        getch();
        exit(0);
    }

    gotoxy(52, 8);
    std::cin >> tempAccount;
    gotoxy(52, 11);
    gets(tempPassword);

    int flag = 0;
    Account account;

    while (masterFile) {
        masterFile.read((char*)&account, sizeof(Account));
        if (tempAccount == account.accountNumber) {
            if (strcmp(tempPassword, account.password) == 0) {
                temporary = tempAccount;
                flag = 2;
                break;
            } else {
                flag = 1;
            }
        } else {
            flag = 1;
        }
    }

    if (flag == 2) {
        displayAccessMenu();
    }
    if (flag == 1) {
        fflush(stdin);
        fflush(stdout);
        outtextxy(200, 400, "Invalid password");
        displayMenu();
    }
    getch();
}

