#include <iostream>
#include <fstream>
#include <cstring>
#include <bcrypt/BCrypt.hpp>

using namespace std;

class HashTable {
public:
    // Computes a simple hash value based on the key
    int computeHash(int key) {
        return key % 10;
    }
};

class UserLogin {
    char username[20];
    char name[20];
    int hashValue;
    char password[50];

public:
    // Collects user details for login
    void collectUserData() {
        cout << "Enter required details" << endl;

        cout << "UserName :\t";
        cin >> username;

        cout << "Name :\t";
        cin >> name;

        cout << "Password :\t";
        cin >> password;

        int usernameLength = strlen(username);
        HashTable hashTable;
        hashValue = hashTable.computeHash(usernameLength);
    }

    // Displays a welcome message to the user
    void displayWelcomeMessage() {
        cout << "--------------------------------------------------" << endl;
        cout << "Welcome! " << name << endl;
        cout << "--------------------------------------------------" << endl;
    }

    // Returns the hash value for the user
    int getHashValue() {
        return hashValue;
    }

    // Validates the provided password against the stored hash
    int validatePassword(string inputPassword) {
        BCrypt bcrypt;
        string hashedPassword = bcrypt.generateHash(password);
        if (bcrypt.validatePassword(inputPassword, hashedPassword) == 0) {
            cout << "Wrong password" << endl;
            return 0;
        }
        return 1;
    }
};

// Deletes a user record based on the hash value
void removeUserRecord(int hashValue) {
    int recordFound = 0;
    UserLogin user;
    ifstream inputFile("login.dat", ios::binary);
    ofstream outputFile("temp.dat", ios::out | ios::binary);

    while (inputFile.read(reinterpret_cast<char*>(&user), sizeof(user))) {
        if (user.getHashValue() != hashValue) {
            outputFile.write(reinterpret_cast<char*>(&user), sizeof(user));
            recordFound = 1;
        }
    }

    inputFile.close();
    outputFile.close();

    remove("login.dat");
    rename("temp.dat", "login.dat");

    if (recordFound == 0) {
        cout << "No database found" << endl;
    } else {
        cout << "Record Deleted" << endl;
    }
}

// Writes a new user record to the file
void saveUserRecord() {
    ofstream outputFile("login.dat", ios::binary | ios::app);
    UserLogin user;
    user.collectUserData();
    outputFile.write(reinterpret_cast<char*>(&user), sizeof(user));
    outputFile.close();
}

// Searches for a user record based on the hash value
void findUser(int hashValue) {
    int recordFound = 0;
    char inputPassword[50];
    ifstream inputFile("login.dat", ios::binary);
    cout << "Enter password" << endl;
    cin >> inputPassword;
    UserLogin user;

    while (inputFile.read(reinterpret_cast<char*>(&user), sizeof(user))) {
        if (user.getHashValue() == hashValue) {
            if (user.validatePassword(inputPassword)) {
                user.displayWelcomeMessage();
            }
            recordFound = 1;
        }
    }

    if (recordFound == 0) {
        cout << "No database found" << endl;
    }
    inputFile.close();
}

int main() {
    HashTable hashTable;
    int usernameLength;
    char username[20];
    int userChoice;
    char continueOperation;

    do {
        cout << "Enter\n1.Sign in\n2.Log in" << endl;
        cin >> userChoice;
        switch (userChoice) {
            case 1:
                saveUserRecord();
                break;

            case 2:
                cout << "Enter your username" << endl;
                cin >> username;
                usernameLength = strlen(username);
                usernameLength = hashTable.computeHash(usernameLength);
                findUser(usernameLength);
                break;

            default:
                cout << "Invalid input" << endl;
        }
        cout << "Any further operations? (y/n)" << endl;
        cin >> continueOperation;
    } while (continueOperation == 'y');

    return 0;
}

