    tax = 0.04 * salary;
    DA = 1.20 * salary;
    PF = 0.12 * salary;
    HRA = salary * 0.27;
    mealAllowance = 300;
    medicalAllowance = 300;
    transportAllowance = 300;
    loanDebit = salary * 0.09;

    if (loanDebit > loanBalance) {
        loanBalance = 0;
        loanDebit = loanBalance;
    }

    employees[index].salary = salary;
    employees[index].DA = DA;
    employees[index].tax = tax;
    employees[index].PF = PF;
    employees[index].HRA = HRA;
    employees[index].mealAllowance = mealAllowance;
    employees[index].medicalAllowance = medicalAllowance;
    employees[index].transportAllowance = transportAllowance;
    employees[index].loanBalance = loanBalance - loanDebit;
    employees[index].hasLoan = loan;
    employees[index].loanDebit = loanDebit;
    employees[index].grossPay = (salary + mealAllowance + medicalAllowance + transportAllowance + HRA + DA) - (PF + tax + loanDebit);

    getch();
}

