#include <iostream>
using namespace std;

class Test {
    int value;

public:
    // Initializes the value to zero
    Test() : value(0) {}

    // Initializes the value with a given integer
    Test(int initialValue) : value(initialValue) {}

    // Copy constructor to create a new instance from an existing one
    Test(const Test& source) : value(source.value) {}

    // Outputs the current value
    void display() const {
        cout << value << endl;
    }
};

int main() {
    Test instanceA, instanceB(10);
    instanceA.display();  // Outputs: 0
    instanceB.display();  // Outputs: 10

    // Using the copy constructor to create a copy of instanceB
    instanceA = Test(instanceB);
    instanceA.display();  // Outputs: 10
    instanceB.display();  // Outputs: 10

    return 0;
}

#include <iostream>
using namespace std;

class Test {
    int value;

public:
    // Default constructor initializing value to zero
    Test() : value(0) {}

    // Constructor that initializes value with a given integer
    Test(int n) : value(n) {}

    // Overloaded binary plus operator to add two Test objects
    Test operator+(Test other) {
        Test result;
        result.value = value + other.value;
        return result;
    }

    // Method to print the value of the Test object
    void print() {
        cout << value << endl;
    }
};

int main() {
    // Creating Test objects with initial values
    Test firstObject(10), secondObject(2), resultObject;

    // Display initial values of the objects
    firstObject.print();  // 10
    secondObject.print(); // 2
    resultObject.print(); // 0

    // Adding two Test objects using the overloaded operator
    resultObject = firstObject + secondObject;

    // Display values after addition
    firstObject.print();  // 10
    secondObject.print(); // 2
    resultObject.print(); // 12

    return 0;
}

#include <iostream>
using namespace std;

class Test {
    int value;

public:
    Test() : value(0) {}

    Test(int initialValue) : value(initialValue) {}

    // Overload the binary minus operator to enable subtraction of Test objects
    Test operator-(Test other) {
        Test result;
        result.value = value - other.value;
        return result;
    }

    void print() const {
        cout << value << endl;
    }
};

int main() {
    Test firstObject(10), secondObject(2), resultObject;

    firstObject.print();   // Output: 10
    secondObject.print();  // Output: 2
    resultObject.print();  // Output: 0

    // Perform subtraction using the overloaded operator
    resultObject = firstObject - secondObject;

    firstObject.print();   // Output: 10
    secondObject.print();  // Output: 2
    resultObject.print();  // Output: 8 

    return 0;
}

#include <iostream>
using namespace std;

class DecrementTest {
    int value;

public:
    DecrementTest() : value(0) {}

    DecrementTest(int initialValue) : value(initialValue) {}

    // Handles prefix decrement operation
    DecrementTest operator--() {
        value--;
        return DecrementTest(value);
    }

    // Handles postfix decrement operation
    DecrementTest operator--(int) {
        DecrementTest temp(value);
        value--;
        return temp;
    }

    void display() const {
        cout << value << endl;
    }
};

