#include <iostream>
using namespace std;

class Counter {
    int value;

public:
    Counter() : value(0) {}

    Counter(int initialValue) : value(initialValue) {}

    // Implements the prefix increment operator
    Counter operator++() {
        value++;
        return Counter(value);
    }

    // Implements the postfix increment operator
    Counter operator++(int) {
        Counter temp(value);
        value++;
        return temp;
    }

    void display() const {
        cout << value << endl;
    }
};

int main() {
    Counter counter1, counter2;
    counter1.display(); // Output: 0
    counter2.display(); // Output: 0

    // Perform prefix increment
    counter2 = ++counter1;
    counter1.display(); // Output: 1
    counter2.display(); // Output: 1

    // Perform postfix increment
    counter2 = counter1++;
    counter1.display(); // Output: 2
    counter2.display(); // Output: 1

    return 0;
}

#include <iostream>
using namespace std;

// Class representing a complex number with integer components
class Complex {
private:
    int realPart, imaginaryPart;

public:
    // Default constructor initializing components to zero
    Complex() : realPart(0), imaginaryPart(0) {}

    // Constructor with parameters to initialize components
    Complex(int real, int imaginary) : realPart(real), imaginaryPart(imaginary) {}

    // Method to print the complex number
    void print() const {
        cout << "x : " << realPart << " y : " << imaginaryPart << endl;
    }

    // Overload unary minus operator
    Complex operator-() {
        return Complex(-realPart, -imaginaryPart);
    }

    // Overload postfix decrement operator
    Complex operator--(int) {
        Complex oldValue(realPart, imaginaryPart);
        realPart--;
        imaginaryPart--;
        return oldValue;
    }

    // Overload postfix increment operator
    Complex operator++(int) {
        Complex oldValue(realPart, imaginaryPart);
        realPart++;
        imaginaryPart++;
        return oldValue;
    }

    // Overload prefix decrement operator
    Complex operator--() {
        realPart--;
        imaginaryPart--;
        return Complex(realPart, imaginaryPart);
    }

    // Overload prefix increment operator
    Complex operator++() {
        realPart++;
        imaginaryPart++;
        return Complex(realPart, imaginaryPart);
    }

    // Overload binary addition operator
    Complex operator+(const Complex& other) const {
        return Complex(realPart + other.realPart, imaginaryPart + other.imaginaryPart);
    }

    // Overload binary subtraction operator
    Complex operator-(const Complex& other) const {
        return Complex(realPart - other.realPart, imaginaryPart - other.imaginaryPart);
    }

    // Overload left shift operator
    Complex operator<<(int shift) {
        realPart <<= shift;
        imaginaryPart <<= shift;
        return *this;
    }

    // Overload right shift operator
    Complex operator>>(int shift) {
        realPart >>= shift;
        imaginaryPart >>= shift;
        return *this;
    }
};

// Main function to demonstrate the functionality of the Complex class
int main() {
    Complex C(10, 20), D(1, 3), E, F, G(1, 1);

    cout << "Initial Value Of C & D" << endl;
    C.print();
    D.print();

    // Demonstrate unary minus operator
    D = -C;
    cout << "Value of C & D After Unary Minus C and assign to D" << endl;
    C.print();
    D.print();

    // Demonstrate increment and decrement operations
    cout << "Initial Value Of E & F" << endl;
    E.print();
    F.print();

    // Post-increment demonstration
    F = E++;
    cout << "Value of E & F After Post-Increment E and assign to F" << endl;
    E.print();
    F.print();

    // Post-decrement demonstration
    F = E--;
    cout << "Value of E & F After Post-Decrement and assign to F" << endl;
    E.print();
    F.print();

    // Pre-increment demonstration
    F = ++E;
    cout << "Value of E & F After Pre-Increment E and assign to F" << endl;
    E.print();
    F.print();

    // Pre-decrement demonstration
    F = --E;
    cout << "Value of E & F After Pre-Decrement and assign to F" << endl;
    E.print();
    F.print();

    // Binary addition demonstration
    cout << "Add D & E and assign to F" << endl;
    F = D + E;
    D.print();
    E.print();
    F.print();

    // Binary subtraction demonstration
    cout << "Subtract D & E and assign to F" << endl;
    F = D - E;
    D.print();
    E.print();
    F.print();

    // Left shift demonstration
    cout << "Left Shift G" << endl;
    G << 2;
