// Function to display details of a single account
void displaySingleAccount(int accountNumber) {
    Account account;
    bool accountFound = false;
    ifstream inFile("account.txt", ios::binary);

    if (!inFile) {
        cout << "File could not be opened !! Press any Key...";
        return;
    }

    cout << "\n\t\t\tBALANCE DETAILS\n";
    while (inFile.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            accountFound = true;
        }
    }
    inFile.close();

    if (!accountFound) {
        cout << "\n\n\t\t\tAccount number does not exist";
    }
}

// Function to modify an existing account
void modifyAccount(int accountNumber) {
    bool accountFound = false;
    Account account;
    fstream file("account.txt", ios::binary | ios::in | ios::out);

    if (!file) {
        cout << "File could not be opened !! Press any Key...";
        return;
    }

    while (!file.eof() && !accountFound) {
        file.read(reinterpret_cast<char*>(&account), sizeof(Account));
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            cout << "\n\n\t\t\tEnter The New Details of account" << endl;
            account.modifyAccount();
            int position = (-1) * static_cast<int>(sizeof(Account));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            cout << "\n\n\t\t\tRecord Updated";
            accountFound = true;
        }
    }
    file.close();

    if (!accountFound) {
        cout << "\n\n\t\t\tRecord Not Found ";
    }
}

// Function to delete an account
void deleteAccount(int accountNumber) {
    Account account;
    ifstream inFile("account.txt", ios::binary);
    if (!inFile) {
        cout << "File could not be opened !! Press any Key...";
        return;
    }

    ofstream outFile("Temp.txt", ios::binary);
    inFile.seekg(0, ios::beg);

    while (inFile.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() != accountNumber) {
            outFile.write(reinterpret_cast<char*>(&account), sizeof(Account));
        }
    }

    inFile.close();
    outFile.close();
    remove("account.txt");
    rename("Temp.txt", "account.txt");
    cout << "\n\nRecord Deleted ...";
}

