// Function to handle deposit and withdrawal operations
void depositOrWithdraw(int accountNumber, int option) {
    int amount;
    bool accountFound = false;
    Account account;
    fstream file("account.txt", ios::binary | ios::in | ios::out);

    if (!file) {
        cout << "File could not be opened !! Press any Key...";
        return;
    }

    while (!file.eof() && !accountFound) {
        file.read(reinterpret_cast<char*>(&account), sizeof(Account));
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            if (option == 1) {
                cout << "\n\n\t\t\tTO DEPOSIT AMOUNT";
                cout << "\n\n\t\t\tEnter The amount to be deposited: ";
                cin >> amount;
                account.deposit(amount);
            }
            if (option == 2) {
                cout << "\n\n\t\t\tTO WITHDRAW AMOUNT";
                cout << "\n\n\t\t\tEnter The amount to be withdrawn: ";
                cin >> amount;
                int newBalance = account.getBalance() - amount;
                if (newBalance < 0) {
                    cout << "Insufficient balance";
                } else {
                    account.withdraw(amount);
                }
            }
            int position = (-1) * static_cast<int>(sizeof(Account));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            cout << "\n\n\t\t\tRecord Updated";
            accountFound = true;
        }
    }
    file.close();

    if (!accountFound) {
        cout << "\n\n\t\t\tRecord Not Found ";
    }
}

