    fileStream1.open("book.dat", ios::in | ios::out);
    while (fileStream.read(reinterpret_cast<char*>(&student), sizeof(Student)) && studentFound == 0) {
        if (strcmpi(student.getAdmissionNumber(), studentNumber) == 0) {
            studentFound = 1;
            if (student.getToken() == 0) {
                cout << "\n\n\tEnter the Book Number: ";
                cin >> bookNumber;
                while (fileStream1.read(reinterpret_cast<char*>(&book), sizeof(Book)) && bookFound == 0) {
                    if (strcmpi(book.getBookNumber(), bookNumber) == 0) {
                        book.showBook();
                        bookFound = 1;
                        student.issueBook();
                        student.setIssuedBookNumber(book.getBookNumber());
                        int position = -1 * sizeof(student);
                        fileStream.seekp(position, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&student), sizeof(Student));
                        cout << "\n\n\tBook issued successfully. Please return within 15 days to avoid a fine of Rs. 1 for each day after 15 days.";
                    }
                }
                if (bookFound == 0) {
                    cout << "Book number does not exist.";
                }
            } else {
                cout << "You have not returned the last book.";
            }
        }
    }
    if (studentFound == 0) {
        cout << "Student record does not exist.";
    }
    getch();
    fileStream.close();
    fileStream1.close();
}

void depositBook() {
    char studentNumber[6], bookNumber[6];
    int studentFound = 0, bookFound = 0, days, fine;
    cout << "\n\nBOOK DEPOSIT ...";
    cout << "\n\n\tEnter The Student's Admission Number: ";
    cin >> studentNumber;
    fileStream.open("student.dat", ios::in | ios::out);
    fileStream1.open("book.dat", ios::in | ios::out);
    while (fileStream.read(reinterpret_cast<char*>(&student), sizeof(Student)) && studentFound == 0) {
        if (strcmpi(student.getAdmissionNumber(), studentNumber) == 0) {
