#include <bits/stdc++.h>

using namespace std;

class Screen {
    int totalRows, totalSeats;
    char* seatStatus;

public:
    // Constructor initializes the screen with the given configuration
    Screen(vector<string> configuration) {
        totalRows = stoi(configuration[2]);
        totalSeats = stoi(configuration[3]) * totalRows;
        seatStatus = new char[totalSeats];

        // Initialize all seats as empty
        fill(seatStatus, seatStatus + totalSeats, 'E');

        // Mark booked seats as 'A'
        for (int i = 4; i < configuration.size(); i++) {
            seatStatus[stoi(configuration[i]) - 1] = 'A';
        }

        cout << "Screen added." << endl;
    }

    // Display all vacant seats
    void displayVacantSeats() {
        cout << "Vacant seats are given below: \n" << endl;

        for (int i = 0; i < totalSeats; i++) {
            cout << seatStatus[i] << " ";
            if ((i + 1) % totalRows == 0) {
                cout << "\n";
            }
        }

        cout << "\n";
    }

    // Attempt to book a specified number of consecutive seats
    void bookSeats(int numberOfSeats) {
        int consecutiveEmptySeats = 0;

        for (int i = 0; i < totalSeats; i++) {
            if (seatStatus[i] == 'E') {
                consecutiveEmptySeats++;
                if (consecutiveEmptySeats == numberOfSeats) {
                    // Mark the seats as booked
                    while (numberOfSeats > 0) {
                        seatStatus[i--] = 'B';
                        numberOfSeats--;
                    }
                    cout << "Seats booked." << endl;
                    return;
                }
            } else {
                consecutiveEmptySeats = 0;
            }
        }

        cout << "Not available." << endl;
    }
};

// Split a string into words based on spaces
vector<string> splitStringIntoWords(string input) {
    string currentWord = "";
    vector<string> wordsList;

    for (auto character : input) {
        if (character == ' ') {
            wordsList.push_back(currentWord);
            currentWord = "";
        } else {
            currentWord += character;
        }
    }
    wordsList.push_back(currentWord);
    return wordsList;
}

int main() {
    int numberOfScreens;
    map<string, Screen*> screenMap;
    vector<string> commandLine;
    string inputLine;

    getline(cin, inputLine);
    numberOfScreens = stoi(inputLine);

    for (int i = 0; i < numberOfScreens; i++) {
        getline(cin, inputLine);
        commandLine = splitStringIntoWords(inputLine);

        if (commandLine[0] == "add-screen") {
            screenMap[commandLine[1]] = new Screen(commandLine);
        } else if (commandLine[0] == "vacant") {
            screenMap[commandLine[1]]->displayVacantSeats();
        } else if (commandLine[0] == "book-seat") {
            screenMap[commandLine[1]]->bookSeats(stoi(commandLine[2]));
        }
    }

    return 0;
}

