    } while (choice != 7);

    return 0;
}

Account::Account(string firstName, string lastName, long double initialBalance) {
    nextAccountNumber++;
    this->accountNumber = nextAccountNumber;
    this->firstName = firstName;
    this->lastName = lastName;

    if (initialBalance < MIN_BALANCE) {
        throw InsufficientFunds();
    }
    this->balance = initialBalance;
}

void Account::deposit(long double amount) {
    balance += amount;
}

void Account::withdraw(long double amount) {
    if (balance - amount < MIN_BALANCE) {
        throw InsufficientFunds();
    }
    balance -= amount;
}

void Account::setLastAccountNumber(long long accountNumber) {
    nextAccountNumber = accountNumber;
}

long long Account::getLastAccountNumber() {
    return nextAccountNumber;
}

