Bank::Bank() {
    Account account;
    ifstream ifs("accountDetails.txt");

    if (!ifs.is_open()) {
        return;
    }

    while (!ifs.eof()) {
        ifs >> account;
        accounts.insert({ account.getAccountNumber(), account });
    }

    Account::setLastAccountNumber(account.getAccountNumber());
    ifs.close();
}

Account Bank::openAccount(string firstName, string lastName, long double initialBalance) {
    try {
        Account account(firstName, lastName, initialBalance);
        accounts.insert({ account.getAccountNumber(), account });

        ofstream ofs("accountDetails.txt", ios::trunc);
        for (const auto& entry : accounts) {
            ofs << entry.second;
        }
        ofs.close();
        return account;
    } catch (InsufficientFunds& e) {
        e.displayMessage();
    }
}

Account Bank::balanceEnquiry(long long accountNumber) {
