    return account;
}

Account Bank::withdraw(long long accountNumber, long double amount) {
    Account& account = accounts.at(accountNumber);
    try {
        account.withdraw(amount);
        return account;
    } catch (InsufficientFunds& e) {
        e.displayMessage();
    }
}

