// Sets the current date to the provided pointers for day, month, and year
void setCurrentDate(int* day, int* month, int* year) {
    time_t now = time(0);
    tm* localTime = localtime(&now);
    *day = localTime->tm_mday;
    *month = 1 + localTime->tm_mon;
    *year = 1900 + localTime->tm_year;
}

const int daysInMonth[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

// Counts the number of leap years up to the given date
int countLeapYears(int day, int month, int year) {
    int totalYears = year;

    if (month <= 2) {
        totalYears--;
    }

    return totalYears / 4 - totalYears / 100 + totalYears / 400;
}

// Calculates the difference in days between two dates
int calculateDateDifference(int day2, int month2, int year2, int day1, int month1, int year1) {
    long int totalDays1 = 365 * year1 + day1;
    for (int i = 0; i < month1 - 1; i++) {
        totalDays1 += daysInMonth[i];
    }
    totalDays1 += countLeapYears(day1, month1, year1);

    long int totalDays2 = 365 * year2 + day2;
    for (int i = 0; i < month2 - 1; i++) {
        totalDays2 += daysInMonth[i];
    }
    totalDays2 += countLeapYears(day2, month2, year2);

    return totalDays2 - totalDays1;
}

