int extractYearFromRollNumber(char rollNumber[]) {
    int year = 0;
    for (int i = 0; i < 4; i++) {
        year = year * 10 + (rollNumber[i] - '0');
    }
    return year;
}

char* extractBranchFromRollNumber(char rollNumber[]) {
    char branchCode[3];
    branchCode[0] = rollNumber[5];
    branchCode[1] = rollNumber[6];
    branchCode[2] = '\0';

    if (strcmpi(branchCode, "CO") == 0) return "COMPUTER SCIENCE";
    if (strcmpi(branchCode, "IT") == 0) return "INFORMATION TECHNOLOGY";
    if (strcmpi(branchCode, "BT") == 0) return "BIO-TECHNOLOGY";
    if (strcmpi(branchCode, "EC") == 0) return "ELECTRONICS AND COMMUNICATION";
    if (strcmpi(branchCode, "IC") == 0) return "INSTRUMENTATION AND CONTROL";
    if (strcmpi(branchCode, "ME") == 0) return "MECHANICAL";

    return "BRANCH NOT DEFINED";
}

