#include <type_traits>
#include <boost/optional.hpp>
#include <map>
#include <list>

template<class T>
struct Cacheable {
   virtual ~Cacheable() { }
   virtual void purge() = 0;
   virtual bool operator ==(T const&) const = 0;
   virtual bool operator <(T const&) const = 0;
   bool operator !=(T const&) const;
   bool operator >(T const&) const;
   bool operator <=(T const&) const;
   bool operator >=(T const&) const;
};

using CacheSizeType = uint64_t;

template<class T>
struct Cache {
   // Ensure that T is derived from Cacheable<T> for proper functionality
   static_assert(std::is_base_of<Cacheable<T>, T>::value,
         "Cache<T>: T must be derived from Cacheable<T>");

   Cache(CacheSizeType maxSize);
   ~Cache();

   // Retrieve an item from the cache if it exists
   boost::optional<T> find(T const&) const;

   // Insert an item into the cache
   void insert(T const&) const;

   // Remove an item from the cache
   void remove(T const&) const;

private:
   Cache(Cache<T> const&) = delete; // Prevent copying
   Cache<T>& operator =(Cache<T> const&) = delete; // Prevent assignment

   CacheSizeType m_maxSize; // Maximum size of the cache
   mutable std::map<T, typename std::list<T>::iterator> m_map; // Map for fast access
   mutable std::list<T> m_list; // List to maintain order of items
};

#include "cache_impl.h"

template<class T>
bool Cacheable<T>::operator !=(T const& other) const { 
    return !(*this == other); 
}

template<class T>
bool Cacheable<T>::operator >(T const& other) const { 
    return other < *this; 
}

template<class T>
bool Cacheable<T>::operator <=(T const& other) const { 
    return !(*this > other); 
}

template<class T>
bool Cacheable<T>::operator >=(T const& other) const { 
    return !(*this < other); 
}

template<class T>
Cache<T>::Cache(cachesize_t maxSize) : m_maxSize(maxSize) { }

template<class T>
Cache<T>::~Cache() {
    // Purge all elements in the cache upon destruction
    for(auto iterator = m_list.begin(); iterator != m_list.end(); ++iterator) {
        iterator->purge();
    }
}

template<class T>
boost::optional<T> Cache<T>::find(T const& value) const {
    auto mapIterator = m_map.find(value);
    if(mapIterator == m_map.end()) return boost::optional<T>();

    T result = mapIterator->first;
    // Move the accessed element to the front of the list for LRU optimization
    m_list.erase(mapIterator->second);
    m_list.push_front(result);
    mapIterator->second = m_list.begin();

    return boost::optional<T>(result);
}

template<class T>
void Cache<T>::insert(T const& value) const {
    // Remove the least recently used element if the cache is full
    if(m_list.size() == m_maxSize) remove(m_list.back());
    m_list.push_front(value);
    m_map.insert(make_pair(value, m_list.begin()));
}

template<class T>
void Cache<T>::remove(T const& value) const {
    auto mapIterator = m_map.find(value);
    if(mapIterator == m_map.end()) return;

    T result = mapIterator->first;
    m_list.erase(mapIterator->second);
    m_map.erase(mapIterator);
    result.purge();
}

