#include <iostream>

using namespace std;

class Date {
private:
    int day, month, year;

public:
    bool isLeapYear();
    int getDaysInMonth();
    Date operator++(); // Prefix increment
    Date operator++(int); // Postfix increment
    friend istream& operator>>(istream&, Date&);
    friend ostream& operator<<(ostream&, Date);
};

// Check if the year is a leap year
bool Date::isLeapYear() {
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

// Retrieve the number of days in the current month
int Date::getDaysInMonth() {
    if (month == 2) {
        return isLeapYear() ? 29 : 28;
    }
    if (month == 4 || month == 6 || month == 9 || month == 11) {
        return 30;
    }
    return 31;
}

// Increment the date (prefix)
Date Date::operator++() {
    int daysInCurrentMonth = getDaysInMonth();
    if (day == daysInCurrentMonth) {
        day = 1;
        if (month == 12) {
            month = 1;
            year++;
        } else {
            month++;
        }
    } else {
        day++;
    }
    return *this;
}

// Increment the date (postfix)
Date Date::operator++(int) {
    Date temp = *this;
    ++(*this);
    return temp;
}

// Input date from stream
istream& operator>>(istream& is, Date& date) {
    is >> date.day >> date.month >> date.year;
    return is;
}

// Output date to stream
ostream& operator<<(ostream& os, Date date) {
    os << date.day << "/" << date.month << "/" << date.year;
    return os;
}

int main() {
    Date date;
    cin >> date; // Input date
    date++; // Postfix increment
    cout << date << endl; // Output incremented date
    ++date; // Prefix increment
    cout << date << endl; // Output incremented date
    return 0;
}

