// Class representing a date with day, month, and year attributes
class Date {
private:
    int day, month, year;

public:
    Date(); // Default constructor
    Date(int year, int month); // Constructor with year and month
    Date(int year, int month, int day); // Constructor with year, month, and day
    Date(const Date& other); // Copy constructor

    bool operator<(const Date& other); // Comparison operator

    friend istream& operator>>(istream& is, Date& date); // Input operator
    friend ostream& operator<<(ostream& os, const Date& date); // Output operator
};

// Default constructor initializes date to 1/1/1
Date::Date() {
    day = month = year = 1;
}

// Constructor initializes date with specified year and month
Date::Date(int year, int month) {
    day = 1;
    this->month = month;
    this->year = year;
}

// Constructor initializes date with specified year, month, and day
Date::Date(int year, int month, int day) {
    this->day = day;
    this->month = month;
    this->year = year;
}

// Copy constructor for creating a new Date from an existing one
Date::Date(const Date& other) {
    day = other.day;
    month = other.month;
    year = other.year;
}

// Overloaded input operator for reading date from input stream
istream& operator>>(istream& is, Date& date) {
    is >> date.day >> date.month >> date.year;
    return is;
}

// Overloaded output operator for writing date to output stream
ostream& operator<<(ostream& os, const Date& date) {
    os << date.day << "/" << date.month << "/" << date.year;
    return os;
}

// Comparison operator to determine if one date is earlier than another
bool Date::operator<(const Date& other) {
    if (year < other.year) return true;
    if (year > other.year) return false;
    if (month < other.month) return true;
    if (month > other.month) return false;
    return day < other.day;
}

