private:
    float coefficientA, coefficientB, coefficientC;

public:
    QuadraticPolynomial();
    QuadraticPolynomial(float a, float b, float c);
    float Evaluate(int x) const;
    QuadraticPolynomial operator+(const QuadraticPolynomial& other) const;
};

// Default constructor initializing coefficients to zero
QuadraticPolynomial::QuadraticPolynomial() : coefficientA(0), coefficientB(0), coefficientC(0) {}

// Constructor with specified coefficients
QuadraticPolynomial::QuadraticPolynomial(float a, float b, float c) 
    : coefficientA(a), coefficientB(b), coefficientC(c) {}

// Evaluate the polynomial at a given x value
float QuadraticPolynomial::Evaluate(int x) const {
    return coefficientA * x * x + coefficientB * x + coefficientC;
}

// Overload the + operator to add two polynomials
QuadraticPolynomial QuadraticPolynomial::operator+(const QuadraticPolynomial& other) const {
    return QuadraticPolynomial(coefficientA + other.coefficientA, 
                               coefficientB + other.coefficientB, 
                               coefficientC + other.coefficientC);
}

