    int degree;
    int coefficients[100];

public:
    friend istream& operator>>(istream&, Polynomial&);
    friend ostream& operator<<(ostream&, const Polynomial&);
    Polynomial operator+(const Polynomial&);
};

istream& operator>>(istream& inputStream, Polynomial& polynomial) {
    cout << "Nhap so bac: ";
    inputStream >> polynomial.degree;

    for (int i = 0; i <= polynomial.degree; i++) {
        cout << "Nhap he so bac " << i << ": ";
        inputStream >> polynomial.coefficients[i];
    }

    return inputStream;
}

ostream& operator<<(ostream& outputStream, const Polynomial& polynomial) {
    outputStream << polynomial.coefficients[polynomial.degree] << "x^" << polynomial.degree;

    for (int i = polynomial.degree - 1; i >= 0; i--) {
        if (polynomial.coefficients[i] > 0) {
            outputStream << "+" << polynomial.coefficients[i] << "x^" << i;
        } else {
            outputStream << polynomial.coefficients[i] << "x^" << i;
        }
    }

    return outputStream;
}

Polynomial Polynomial::operator+(const Polynomial& other) {
    Polynomial result;
    result.degree = (degree < other.degree) ? degree : other.degree;

    for (int i = 0; i <= result.degree; i++) {
        result.coefficients[i] = coefficients[i] + other.coefficients[i];
    }

    return result;
}

