    Fraction operator+(const Fraction&);
    Fraction operator-(const Fraction&);
    friend istream& operator>>(istream& is, Fraction&);
    friend ostream& operator<<(ostream& os, Fraction);
};

// Adds two fractions and returns the result
Fraction Fraction::operator+(const Fraction& other) {
    Fraction result;
    result.numerator = numerator * other.denominator + denominator * other.numerator;
    result.denominator = denominator * other.denominator;
    return result;
}

// Subtracts one fraction from another and returns the result
Fraction Fraction::operator-(const Fraction& other) {
    Fraction result;
    result.numerator = numerator * other.denominator - denominator * other.numerator;
    result.denominator = denominator * other.denominator;
    return result;
}

// Overloads the input stream operator to read a fraction
istream& operator>>(istream& is, Fraction& fraction) {
    is >> fraction.numerator >> fraction.denominator;
    return is;
}

// Overloads the output stream operator to display a fraction
ostream& operator<<(ostream& os, Fraction fraction) {
    os << fraction.numerator << "/" << fraction.denominator << endl;
    return os;
}

// Main function to demonstrate fraction operations
int main() {
    Fraction firstFraction, secondFraction, result;

    cin >> firstFraction;
    cin >> secondFraction;

    result = firstFraction + secondFraction;
    cout << result;

    result = firstFraction - secondFraction;
    cout << result;

    return 0;
}

#include <iostream>

using namespace std;

class Time {
private:
    int hours, minutes, seconds;

public:
    Time operator++(int);
    Time operator--(int);
    friend istream& operator>>(istream&, Time&);
    friend ostream& operator<<(ostream&, Time);
};

// Increment the time by one second, handling overflow for seconds, minutes, and hours.
Time Time::operator++(int) {
    if (seconds == 59) {
        seconds = 0;
        if (minutes == 59) {
            minutes = 0;
            hours++;
        } else {
            minutes++;
        }
    } else {
        seconds++;
    }
    return *this;
}

// Decrement the time by one second, handling underflow for seconds, minutes, and hours.
Time Time::operator--(int) {
    if (seconds == 0) {
        seconds = 59;
        if (minutes == 0) {
            minutes = 59;
            hours--;
        } else {
            minutes--;
        }
    } else {
        seconds--;
    }
    return *this;
}

// Input time values for hours, minutes, and seconds with validation.
istream& operator>>(istream& is, Time& t) {
    cout << "Nhap gio: ";
    do {
        is >> t.hours;
    } while (t.hours < 0);

    cout << "Nhap phut: ";
    do {
        is >> t.minutes;
    } while (t.minutes < 0 || t.minutes > 59);

    cout << "Nhap giay: ";
    do {
        is >> t.seconds;
    } while (t.seconds < 0 || t.seconds > 59);

    return is;
}

// Output the time in a formatted string.
ostream& operator<<(ostream& os, Time t) {
    os << t.hours << " gio " << t.minutes << " phut " << t.seconds << " giay " << endl;
    return os;
}

