using namespace std;

// Abstract base class representing a type of gate
class Gate {
public:
    virtual void Input() = 0; // Method to input gate parameters
    virtual bool PassThrough(int&) = 0; // Method to check if the gate can be passed
    virtual int GetGateType() = 0; // Method to retrieve the type of gate
};

// Class representing a standard gate with a price and quantity
class StandardGate : public Gate {
private:
    int price; // Price per unit
    int quantity; // Number of units

public:
    void Input() override; // Input method for standard gate
    bool PassThrough(int&) override; // Check if the gate can be passed based on available funds
    int GetGateType() override; // Retrieve the type of gate
};

// Class representing an intelligence gate based on intelligence level
class IntelligenceGate : public Gate {
private:
    int intelligence; // Required intelligence to pass

public:
    void Input() override; // Input method for intelligence gate
    bool PassThrough(int&) override; // Check if the gate can be passed based on intelligence level
    int GetGateType() override { return 2; } // Retrieve the type of gate
};

// Class representing a strength gate based on strength level
class StrengthGate : public Gate {
private:
    int strength; // Required strength to pass

public:
    void Input() override; // Input method for strength gate
    bool PassThrough(int&) override; // Check if the gate can be passed based on strength level
    int GetGateType() override { return 3; } // Retrieve the type of gate
};

// Implementation of input method for standard gate
void StandardGate::Input() {
    cout << "Enter price: ";
    cin >> price;
    cout << "Enter quantity: ";
    cin >> quantity;
}

// Implementation of pass-through method for standard gate
bool StandardGate::PassThrough(int& availableFunds) {
    availableFunds -= price * quantity;
    return availableFunds >= 0; // Return true if funds are sufficient
}

// Implementation of get gate type method for standard gate
int StandardGate::GetGateType() {
    return 1; // Return type identifier for standard gate
}

// Implementation of input method for intelligence gate
void IntelligenceGate::Input() {
    cout << "Enter intelligence level: ";
    cin >> intelligence;
}

// Implementation of pass-through method for intelligence gate
bool IntelligenceGate::PassThrough(int& currentIntelligence) {
    return currentIntelligence >= intelligence; // Return true if intelligence is sufficient
}

// Implementation of input method for strength gate
void StrengthGate::Input() {
    cout << "Enter strength level: ";
    cin >> strength;
}

// Implementation of pass-through method for strength gate
bool StrengthGate::PassThrough(int& currentStrength) {
    currentStrength -= strength;
    return currentStrength >= 0; // Return true if strength is sufficient
}

// Main function to execute the gate passing logic
int main() {
    Gate* gateList[100]; // Array to hold pointers to gate objects
    cout << "Enter the number of gates in the castle: ";
    int numberOfGates;
    cin >> numberOfGates;

    // Input gates based on user selection
    for (int i = 0; i < numberOfGates; i++) {
        cout << "\nEnter details for gate " << i + 1 << endl;
        cout << "Choose 1 for standard gate, 2 for intelligence gate, 3 for strength gate: ";
        int choice;
        cin >> choice;

        switch (choice) {
            case 1: gateList[i] = new StandardGate; break;
            case 2: gateList[i] = new IntelligenceGate; break;
            case 3: gateList[i] = new StrengthGate; break;
        }

        gateList[i]->Input(); // Input parameters for the selected gate
    }

    int availableFunds, currentIntelligence, currentStrength;
    cout << "Enter available funds: ";
    cin >> availableFunds;
    cout << "Enter current intelligence: ";
    cin >> currentIntelligence;
    cout << "Enter current strength: ";
    cin >> currentStrength;

    // Check if the prince can pass through all gates
    int i;
    for (i = 0; i < numberOfGates; i++) {
        if (gateList[i]->GetGateType() == 1) {
            if (!gateList[i]->PassThrough(availableFunds)) break; // Check standard gate
        } else if (gateList[i]->GetGateType() == 2) {
            if (!gateList[i]->PassThrough(currentIntelligence)) break; // Check intelligence gate
        } else {
            if (!gateList[i]->PassThrough(currentStrength)) break; // Check strength gate
        }
    }

    // Output the remaining parameters if all gates are passed
    if (i == numberOfGates) {
        cout << "\nRemaining parameters of the prince are: ";
        cout << "\nFunds: " << availableFunds;
        cout << "\nIntelligence: " << currentIntelligence;
        cout << "\nStrength: " << currentStrength;
    } else {
        cout << "\nThe prince could not pass through the gate.";
    }

    return 0;
}

