void issueBook() {
    string studentNumber, bookNumber;
    bool studentFound = false, bookFound = false;
    system("cls");
    cout << "\n\nBOOK ISSUE ...";
    cout << "\n\n\tEnter The Student's Admission Number: ";
    cin >> studentNumber;

    fileStream.open("student.dat", ios::in | ios::out);
    fstream bookFile;
    bookFile.open("book.dat", ios::in | ios::out);

    while (fileStream.read(reinterpret_cast<char*>(&student), sizeof(Student)) && !studentFound) {
        if (studentNumber == student.getAdmissionNumber()) {
            studentFound = true;
            if (student.getToken() == 0) {
                cout << "\n\n\tEnter the Book Number: ";
                cin >> bookNumber;

                while (bookFile.read(reinterpret_cast<char*>(&book), sizeof(Book)) && !bookFound) {
                    if (bookNumber == book.getBookNumber()) {
                        book.showBook();
                        bookFound = true;
                        student.issueBook();
                        student.setIssuedBookNumber(book.getBookNumber());
                        long pos = -1 * sizeof(Student);
                        fileStream.seekp(pos, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&student), sizeof(Student));
                        cout << "\n\n\t Book issued successfully\n\nPlease Note: Write the current date on the back of the book and submit within 15 days. Fine Rs. 1 for each day after 15 days.";
                    }
                }

                if (!bookFound) {
                    cout << "Book number does not exist";
                }
            } else {
                cout << "You have not returned the last book.";
            }
        }
    }

    if (!studentFound) {
        cout << "Student record does not exist...";
    }
    getch();
    fileStream.close();
    bookFile.close();
}

void depositBook() {
    string studentNumber, bookNumber;
    bool studentFound = false, bookFound = false;
    int days, fine;
    system("cls");
    cout << "\n\nBOOK DEPOSIT ...";
    cout << "\n\n\tEnter The Student's Admission Number: ";
    cin >> studentNumber;

    fileStream.open("student.dat", ios::in | ios::out);
    fstream bookFile;
    bookFile.open("book.dat", ios::in | ios::out);

    while (fileStream.read(reinterpret_cast<char*>(&student), sizeof(Student)) && !studentFound) {
        if (studentNumber == student.getAdmissionNumber()) {
            studentFound = true;
            if (student.getToken() == 1) {
                while (bookFile.read(reinterpret_cast<char*>(&book), sizeof(Book)) && !bookFound) {
                    if (student.getIssuedBookNumber() == book.getBookNumber()) {
                        book.showBook();
                        bookFound = true;
                        cout << "\n\nBook deposited in number of days: ";
                        cin >> days;

                        if (days > 15) {
                            fine = (days - 15) * 1;
                            cout << "\n\nFine to be deposited: Rs. " << fine;
                        }

                        student.returnBook();
                        long pos = -1 * sizeof(Student);
                        fileStream.seekp(pos, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&student), sizeof(Student));
                        cout << "\n\n\t Book deposited successfully";
                    }
                }

                if (!bookFound) {
                    cout << "Book number does not exist";
                }
            } else {
                cout << "No book is issued. Please check!";
            }
        }
    }

    if (!studentFound) {
        cout << "Student record does not exist...";
    }
    getch();
    fileStream.close();
    bookFile.close();
}

