class PatientProfile {
protected:
    int serialNumber = 0;
    string name;
    string address;
    char gender;
    int age;
    string cause;
    int seatNumber;

public:
    void initializeSerialNumber() {
        ifstream file("PatientProfile.dat");
        if (!file.is_open()) {
            cout << "Cannot open file!\n";
            return;
        }
        while (!file.eof()) {
            file >> serialNumber >> name >> address >> gender >> age >> cause >> seatNumber;
        }
        file.close();
        serialNumber++;
    }

    void inputInformation() {
        initializeSerialNumber();
        cout << "Name: ";
        cin >> name;
        cout << "Present Address: ";
        cin >> address;
        cout << "Gender (M/F): ";
        cin >> gender;
        cout << "Age: ";
        cin >> age;
        cout << "Cause: ";
        cin >> cause;
        cout << "Seat Number: ";
        cin >> seatNumber;
    }

    void writeToFile() {
        ofstream file("PatientProfile.dat", ios::out | ios::app);
        if (!file) {
            throw "Cannot open file!\n";
        }
        file << endl << serialNumber << "\t\t" << name << "\t\t" << address << "\t\t" << gender << "\t\t" << age << "\t\t" << cause << "\t\t" << seatNumber;
        file.close();
    }

    friend ostream& operator<<(ostream& output, const PatientProfile& profile) {
        output << endl << endl << "\t\t\t\t\t\t";
        for (int i = 0; i < 20; i++) {
            cout << "-";
        }
        output << "\n\t\t\t\t\t\tSerial Number: " << profile.serialNumber
               << "\n\t\t\t\t\t\tName: " << profile.name
               << "\n\t\t\t\t\t\tAddress: " << profile.address
               << "\n\t\t\t\t\t\tGender: " << profile.gender
               << "\n\t\t\t\t\t\tAge: " << profile.age
               << "\n\t\t\t\t\t\tSeat No: " << profile.seatNumber << endl;
        cout << "\t\t\t\t\t\t";
        for (int i = 0; i < 20; i++) {
            cout << "-";
        }
        cout << endl << endl;
        return output;
    }

    PatientProfile operator++(int) {
        serialNumber++;
    }
};

template<class T>
class PaymentSystem : protected PatientProfile {
protected:
    T serialNumber;
    T amount;

public:
    void checkSerialNumber() {
        system("cls");
        cout << "Enter Serial Number: ";
        cin >> serialNumber;
        int patientFound = 0, billFound = 0;

        ifstream patientFile("PatientProfile.dat"), billFile("BillPayment.dat");
        if (!patientFile.is_open() || !billFile.is_open()) {
            throw "Cannot open file!\n";
        }

        while (!patientFile.eof()) {
            patientFile >> serialNumber >> name >> address >> gender >> age >> cause >> seatNumber;
            if (serialNumber == serialNumber) {
                patientFound = 1;
            }
        }

        while (!billFile.eof()) {
            billFile >> serialNumber >> amount;
            if (serialNumber == serialNumber) {
                billFound = 1;
            }
