class Room {
protected:
    bool isReserved;
    int roomNumber;

public:
    Room() : isReserved(false), roomNumber(0) {}

    virtual void setReservationStatus(bool status) {
        isReserved = status;
    }

    virtual bool isRoomReserved() const {
        return isReserved;
    }

    virtual void setRoomNumber(int number) {
        roomNumber = number;
    }

    virtual int getRoomNumber() const {
        return roomNumber;
    }

    virtual void setDaysOfReservation(int days) {}
    virtual int getDaysOfReservation() const { return 0; }

    virtual void setNumberOfBeds(int beds) {}
    virtual int getNumberOfBeds() const { return 0; }

    virtual void setBedPrice(double price) {}
    virtual double getBedPrice() const { return 0; }

    virtual void setPricePerNight(double price) {}
    virtual double getPricePerNight() const { return 0; }

    virtual void setNumberOfSeats(int seats) {}
    virtual int getNumberOfSeats() const { return 0; }

    virtual void setSeatPrice(double price) {}
    virtual double getSeatPrice() const { return 0; }

    virtual double calculateTotalProfit() const { return 0; }

    virtual void reserve() {
        isReserved = true;
    }

    virtual void displayInfo() const {
        cout << endl;
    }
};

class StandardRoom : public Room {
private:
    int daysOfReservation;
    int numberOfBeds;
    double bedPrice;

public:
    StandardRoom() : daysOfReservation(0), numberOfBeds(0), bedPrice(0) {}

    StandardRoom(int beds, double price, int days, int number) 
        : daysOfReservation(days), numberOfBeds(beds), bedPrice(price) {
        roomNumber = number;
    }

    void setRoomNumber(int number) override {
        roomNumber = number;
    }

    int getRoomNumber() const override {
        return roomNumber;
    }

    void setDaysOfReservation(int days) override {
        daysOfReservation = days;
    }

    int getDaysOfReservation() const override {
        return daysOfReservation;
    }

    void setNumberOfBeds(int beds) override {
        numberOfBeds = beds;
    }

    int getNumberOfBeds() const override {
        return numberOfBeds;
    }

    void setBedPrice(double price) override {
        bedPrice = price;
    }

    double getBedPrice() const override {
        return bedPrice;
    }

    double calculateTotalProfit() const override {
        return daysOfReservation * bedPrice * numberOfBeds;
    }

    void displayInfo() const override {
        cout << "\t*Available Standard Room Details* " << endl;
        cout << "\n\t Room Number: " << getRoomNumber();
        cout << "\n\t Number of Beds: " << getNumberOfBeds();
        cout << "\n\t Price Per Bed: " << getBedPrice() << " $";
        cout << "\n\t Total Profit: " << calculateTotalProfit() << " $" << endl;
    }
};

