class Floor {
public:
    Room** standardRooms;
    Room** sweetRooms;
    Room** conferenceRooms;

private:
    int floorNumber;
    double totalProfit;

public:
    Floor() : floorNumber(0), totalProfit(0) {
        standardRooms = new Room*[numberOfStandardRooms];
        sweetRooms = new Room*[numberOfSweetRooms];
        conferenceRooms = new Room*[numberOfConferenceRooms];

        for (size_t i = 0; i < numberOfStandardRooms; i++) {
            standardRooms[i] = new StandardRoom();
        }
        for (size_t i = 0; i < numberOfSweetRooms; i++) {
            sweetRooms[i] = new SweetRoom();
        }
        for (size_t i = 0; i < numberOfConferenceRooms; i++) {
            conferenceRooms[i] = new ConferenceRoom();
        }
    }

    void setFloorNumber(int number) {
        floorNumber = number;
    }

    int getFloorNumber() const {
        return floorNumber;
    }

    void displayAvailableRooms(int floorNumber) const {
        for (size_t i = 0; i < numberOfStandardRooms; i++) {
            if (detailsOfStandardRooms[i][0] == floorNumber && !standardRooms[i]->isRoomReserved()) {
                standardRooms[i]->displayInfo();
            }
        }
        for (size_t i = 0; i < numberOfSweetRooms; i++) {
            if (detailsOfSweetRooms[i][0] == floorNumber && !sweetRooms[i]->isRoomReserved()) {
                sweetRooms[i]->displayInfo();
            }
        }
        for (size_t i = 0; i < numberOfConferenceRooms; i++) {
            if (detailsOfConferenceRooms[i][0] == floorNumber && !conferenceRooms[i]->isRoomReserved()) {
                conferenceRooms[i]->displayInfo();
            }
        }
    }

    double calculateProfitForFloor(int floorNumber) {
        totalProfit = 0;

        for (size_t i = 0; i < numberOfStandardRooms; i++) {
            if (detailsOfStandardRooms[i][0] == floorNumber && standardRooms[i]->isRoomReserved()) {
                totalProfit += standardRooms[i]->calculateTotalProfit();
            }
        }
        for (size_t i = 0; i < numberOfSweetRooms; i++) {
            if (detailsOfSweetRooms[i][0] == floorNumber && sweetRooms[i]->isRoomReserved()) {
                totalProfit += sweetRooms[i]->calculateTotalProfit();
            }
        }
        for (size_t i = 0; i < numberOfConferenceRooms; i++) {
            if (detailsOfConferenceRooms[i][0] == floorNumber && conferenceRooms[i]->isRoomReserved()) {
                totalProfit += conferenceRooms[i]->calculateTotalProfit();
            }
        }
        return totalProfit;
    }
};

