    cout << "=====================================================\n";
    cout << "|               Total Hotel Profit                  |\n";
    cout << "=====================================================\n";
    for (size_t j = 0; j < numberOfFloors; j++) {
        totalProfit += currentFloor.calculateProfitForFloor(j + 1);
    }
    cout << setw(27) << totalProfit << " $" << endl;
    cin.get();
    cin.get();
    system("cls");
    Check(currentFloor, Menu());
}

vector<string> ReadFromTextFile(const string& filePath) {
    vector<string> fileLines;
    string line;
    ifstream myFile(filePath);
    if (myFile.is_open()) {
        while (getline(myFile, line)) {
            fileLines.push_back(line);
        }
    } else {
        cout << "Unable to open file" << endl;
    }
    return fileLines;
}

void ManipulateData(vector<string>& fileLines) {
    for (size_t i = 0; i < fileLines[0].size(); i++) {
        if (isdigit(fileLines[0][i])) {
            numberOfFloors = (fileLines[0][i] - '0');
        }
    }

    int roomLineIndex = 1;

    for (int i = 0; i < numberOfFloors; i++) {
        for (int j = 0; j < fileLines[roomLineIndex].size() + 1; j++) {
            if (fileLines[roomLineIndex][j] == ' ') {
                numberOfRoomsInEachFloor[i] = fileLines[roomLineIndex][j + 1] - '0';
                roomLineIndex += numberOfRoomsInEachFloor[i] + 1;
                break;
            }
        }
    }

    for (size_t i = 0; i < fileLines.size(); i++) {
        if (fileLines[i].find("Standard") != string::npos) {
            numberOfStandardRooms++;
        } else if (fileLines[i].find("Sweet") != string::npos) {
            numberOfSweetRooms++;
        } else if (fileLines[i].find("Conference") != string::npos) {
            numberOfConferenceRooms++;
        }
    }

    for (int i = 0; i < numberOfStandardRooms; i++) {
        detailsOfStandardRooms[i] = new int[4];
    }
    for (int i = 0; i < numberOfConferenceRooms; i++) {
        detailsOfConferenceRooms[i] = new int[4];
    }
    for (int i = 0; i < numberOfSweetRooms; i++) {
        detailsOfSweetRooms[i] = new int[3];
    }

    int standardCount = 0, sweetCount = 0, conferenceCount = 0;
    for (int i = 0; i < fileLines.size(); i++) {
        if (fileLines[i].find("Standard") != string::npos) {
            detailsOfStandardRooms[standardCount][1] = stoi(fileLines[i].substr(fileLines[i].find_first_of(" "), fileLines[i].find_first_of(",")));
            detailsOfStandardRooms[standardCount][2] = stoi(fileLines[i].substr(fileLines[i].find_first_of(",", fileLines[i].find_first_of(" ")) + 1, fileLines[i].find_last_of(",")));
            detailsOfStandardRooms[standardCount][3] = stoi(fileLines[i].substr(fileLines[i].find_last_of(" "), fileLines[i].find(".")));
            standardCount++;
        } else if (fileLines[i].find("Sweet") != string::npos) {
            detailsOfSweetRooms[sweetCount][1] = stoi(fileLines[i].substr(fileLines[i].find_first_of(" "), fileLines[i].find_last_of(",")));
            detailsOfSweetRooms[sweetCount][2] = stoi(fileLines[i].substr(fileLines[i].find_last_of(" "), fileLines[i].find_last_of("  ")));
            sweetCount++;
        } else if (fileLines[i].find("Conference") != string::npos) {
            detailsOfConferenceRooms[conferenceCount][1] = stoi(fileLines[i].substr(fileLines[i].find_first_of(" "), fileLines[i].find_first_of(",")));
            detailsOfConferenceRooms[conferenceCount][2] = stoi(fileLines[i].substr(fileLines[i].find_first_of(",", fileLines[i].find_first_of(" ")) + 1, fileLines[i].find_last_of(",")));
            detailsOfConferenceRooms[conferenceCount][3] = stoi(fileLines[i].substr(fileLines[i].find_last_of(" "), fileLines[i].find(".")));
            conferenceCount++;
        }
    }

    int* standardRoomsPerFloor = new int[numberOfFloors] {0};
    int* sweetRoomsPerFloor = new int[numberOfFloors] {0};
    int* conferenceRoomsPerFloor = new int[numberOfFloors] {0};
    int lineIndex = 2;

    for (int j = 0; j < numberOfFloors; j++) {
        for (int i = 0; i < numberOfRoomsInEachFloor[j]; i++) {
            if (fileLines[lineIndex].find("Standard") != string::npos) {
                standardRoomsPerFloor[j]++;
            } else if (fileLines[lineIndex].find("Sweet") != string::npos) {
                sweetRoomsPerFloor[j]++;
            } else if (fileLines[lineIndex].find("Conference") != string::npos) {
                conferenceRoomsPerFloor[j]++;
            }
            lineIndex++;
        }
        lineIndex += 1;
    }

    int index = 0;
    for (size_t i = 0; i < numberOfFloors; i++) {
        for (size_t j = 0; j < standardRoomsPerFloor[i]; j++) {
            detailsOfStandardRooms[index++][0] = i + 1;
        }
    }
    index = 0;
    for (size_t i = 0; i < numberOfFloors; i++) {
        for (size_t j = 0; j < sweetRoomsPerFloor[i]; j++) {
            detailsOfSweetRooms[index++][0] = i + 1;
        }
    }
    index = 0;
    for (size_t i = 0; i < numberOfFloors; i++) {
        for (size_t j = 0; j < conferenceRoomsPerFloor[i]; j++) {
            detailsOfConferenceRooms[index++][0] = i + 1;
        }
    }
}

