        cout << "\nPreferred date of journey : ";
        cin >> journeyDate;
        cout << "\nMonth                     : ";
        cin >> journeyMonth;
        cout << "\nYear                      : ";
        cin >> journeyYear;
        cout << "\nAddress                   : ";
        cin.ignore();
        cin.getline(address, sizeof(address));
        cout << "\nContact number            : ";
