    Product(int productId, const string& productName, float productPrice) 
        : id(productId), name(productName), price(productPrice) {
        ofstream outProduct("Products.txt", ios::out | ios::app);
        outProduct << id << ' ' << name << ' ' << price << endl;
        cout << "\n\n\n\tPRODUCT CREATED SUCCESSFULLY";
        getch();
    }

    int getId() const {
        return id;
    }

    string getName() const {
        return name;
    }

    float getPrice() const {
        return price;
    }

    void setId(int productId) {
        id = productId;
    }

    void setName(const string& productName) {
        name = productName;
    }

    void setPrice(float productPrice) {
        price = productPrice;
    }
};

class Bill {
public:
    string date;
    float totalAmount;

    Bill() {
        time_t now = time(0);
        date = ctime(&now);
        totalAmount = 0.0f;
    }
};

class BillItem {
private:
    Product product;
    int quantity;

public:
    void fetchItem(int productCode) {
        ifstream productFile("Products.txt", ios::in);
        int id;
        string name;
        float price;

        while (productFile >> id >> name >> price) {
            if (id == productCode) {
                product.setId(id);
                product.setName(name);
                product.setPrice(price);
                break;
            }
        }
    }

    void setQuantity(int itemQuantity) {
        quantity = itemQuantity;
    }

    float calculateAmount() const {
        return product.getPrice() * quantity;
    }

    void displayItemDetails() const {
        cout << "\t" << setw(14) << product.getId()
             << "\t" << setw(12) << product.getName()
             << "\t" << setw(12) << product.getPrice()
             << "\t" << setw(8) << quantity << "\t";
    }
};

