bool isValidPhoneNumber(const char phoneNumber[]) {
    for (int i = 0; i < 10; i++) {
        if (!(phoneNumber[i] >= '0' && phoneNumber[i] <= '9')) {
            return false;
        }
    }
    return true;
}

void validateNumberOfDays(int days, int month, int year) {
    int maxDays;
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            maxDays = 31;
            break;
        case 4: case 6: case 9: case 11:
            maxDays = 30;
            break;
        case 2:
            maxDays = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0) ? 29 : 28;
            break;
    }
    if (days < 0 || days > maxDays) {
        std::cout << "Invalid number of days. Please input a valid number of days: ";
        int newDays;
        std::cin >> newDays;
        validateNumberOfDays(newDays, month, year);
    }
}

