int generateEmployeeNumber() {
    Employee employee;
    int employeeNumber, length = sizeof(Employee);
    std::ifstream fin("emp.txt");

    if (!fin) {
        employeeNumber = 0;
    } else {
        fin.seekg(0, std::ios::end);
        int recordCount = fin.tellg() / length;
        if (recordCount == 0) {
            employeeNumber = 0;
        } else {
            fin.seekg(length * (recordCount - 1), std::ios::beg);
            fin.read(reinterpret_cast<char*>(&employee), sizeof(employee));
            employeeNumber = employee.getEmployeeNumber();
        }
    }
    fin.close();
    return employeeNumber + 1;
}

class MonthlyPay {
    int employeeNumber;
    char employeeName[35];
    int year;
    int month;
    int daysWorked;
    double basicSalary;
    double dearnessAllowance;
    double houseRentAllowance;
    double conveyance;
    double grossSalary;
    double deductions;
    double netSalary;

public:
    void calculateSalary() {
        double maxDays;
        switch (month) {
            case 1: case 3: case 5: case 7: case 8: case 10: case 12:
                maxDays = 31;
                break;
            case 4: case 6: case 9: case 11:
                maxDays = 30;
                break;
            case 2:
                maxDays = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0) ? 29 : 28;
                break;
        }
        basicSalary *= daysWorked / maxDays;
        dearnessAllowance = 0.55 * basicSalary;
        houseRentAllowance = 0.35 * basicSalary;
        conveyance = 0.15 * basicSalary;
        grossSalary = basicSalary + dearnessAllowance + houseRentAllowance + conveyance;
        deductions = 0;
        netSalary = grossSalary - deductions;
    }

    void inputMonthlyPayDetails() {
        std::cout << "Input Employee Number: ";
        std::cin >> employeeNumber;
        std::cout << "Input Employee Name: ";
        std::cin.ignore();
        std::cin.getline(employeeName, 35);
        std::cout << "Input Month [1-12]: ";
        std::cin >> month;
        std::cout << "Input Year: ";
        std::cin >> year;
        std::cout << "Input Number of Days Worked: ";
        std::cin >> daysWorked;
        validateNumberOfDays(daysWorked, month, year);
        std::cout << "Input Basic Salary: ";
        std::cin >> basicSalary;
        calculateSalary();
    }

    void displaySalarySlip() const {
        std::cout << "--------------------------------------------------" << std::endl;
        std::cout << "Salary Slip for the month of: " << month << " " << year << std::endl;
        std::cout << "Employee No: " << employeeNumber << "                                     ";
        std::cout << "Employee Name: " << employeeName << std::endl;
        std::cout << "--------------------------------------------------" << std::endl;
        std::cout << "Basic         " << basicSalary << "                                ";
        std::cout << "      " << "Deductions    " << deductions << std::endl;
        std::cout << "DA            " << dearnessAllowance << std::endl;
        std::cout << "HRA           " << houseRentAllowance << std::endl;
        std::cout << "Conveyance    " << conveyance << std::endl;
        std::cout << "--------------------------------------------------" << std::endl;
        std::cout << "Gross Pay     " << grossSalary << "                                 ";
        std::cout << "      " << "Net           " << netSalary << std::endl;
    }
};

