    char origin[10];
    char destination[10];
    char seats[8][4][10];

public:
    void selectBus();
    void allocateSeat();
    void initializeSeats();
    void displayBusInfo();
    void showAvailableSeats(int busIndex);
};

BusReservation buses[10];

void drawLine(char character) {
    for (int i = 80; i > 0; i--) {
        cout << character;
    }
}

void BusReservation::selectBus() {
    cout << "Enter bus number: ";
    cin >> buses[busCount].busNumber;

    cout << "\nEnter driver's name: ";
    cin >> buses[busCount].driverName;

    cout << "\nArrival time (24-hour format): ";
    cin >> buses[busCount].arrivalTime;

    cout << "\nDeparture time (24-hour format): ";
    cin >> buses[busCount].departureTime;

    cout << "\nFrom: ";
    cin >> buses[busCount].origin;

    cout << "\nTo: ";
    cin >> buses[busCount].destination;

    buses[busCount].initializeSeats();
    busCount++;
}

void BusReservation::allocateSeat() {
    int seatNumber;
    char busNumberInput[5];

    while (true) {
        cout << "Bus number: ";
        cin >> busNumberInput;

        int busIndex;
        for (busIndex = 0; busIndex < busCount; busIndex++) {
            if (strcmp(buses[busIndex].busNumber, busNumberInput) == 0) {
                break;
            }
        }

        if (busIndex < busCount) {
            while (true) {
                cout << "\nSeat Number: ";
                cin >> seatNumber;

                if (seatNumber > 32) {
                    cout << "\nThere are only 32 seats available in this bus.";
                } else {
                    if (strcmp(buses[busIndex].seats[seatNumber / 4][(seatNumber % 4) - 1], "-") == 0) {
                        cout << "Enter passenger's name: ";
                        cin >> buses[busIndex].seats[seatNumber / 4][(seatNumber % 4) - 1];
                        cout << "You have successfully booked seat number " << seatNumber << " in bus number: " << buses[busIndex].busNumber;
                        break;
                    } else {
                        cout << "The seat number is already reserved.\n";
                    }
                }
            }
            break;
        } else {
            cout << "Enter a correct bus number\n";
        }
    }
}

void BusReservation::initializeSeats() {
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 4; j++) {
            strcpy(buses[busCount].seats[i][j], "-"); // Initialize seats as empty
        }
    }
}

void BusReservation::displayBusInfo() {
    char busNumberInput[5];
    cout << "Enter bus number: ";
    cin >> busNumberInput;

    int busIndex;
    for (busIndex = 0; busIndex < busCount; busIndex++) {
        if (strcmp(buses[busIndex].busNumber, busNumberInput) == 0) {
            break;
        }
    }

    if (busIndex < busCount) {
        drawLine('*');
        cout << "Bus number: " << buses[busIndex].busNumber
             << "\nDriver: " << buses[busIndex].driverName
             << "\tArrival time: " << buses[busIndex].arrivalTime
             << "\tDeparture time: " << buses[busIndex].departureTime
             << "\nFrom: " << buses[busIndex].origin
             << "\tTo: " << buses[busIndex].destination << "\n";
        drawLine('*');
        showAvailableSeats(busIndex);
    } else {
        cout << "Enter a correct bus number: ";
    }
}

void BusReservation::showAvailableSeats(int busIndex) {
    int availableSeatsCount = 0;
    int seatIndex = 0;

    for (int i = 0; i < 8; i++) {
        cout << "\n";
        for (int j = 0; j < 4; j++) {
            seatIndex++;
            if (strcmp(buses[busIndex].seats[i][j], "-") == 0) {
                cout.width(5);
                cout.fill(' ');
                cout << seatIndex << ".";
                cout.width(10);
                cout.fill(' ');
                cout << buses[busIndex].seats[i][j];
                availableSeatsCount++;
            } else {
                cout.width(5);
                cout.fill(' ');
                cout << seatIndex << ".";
                cout.width(10);
                cout.fill(' ');
                cout << buses[busIndex].seats[i][j];
            }
        }
    }
    cout << "\n\nThere are " << availableSeatsCount << " seats empty in Bus No: " << buses[busIndex].busNumber;
}

