using namespace std;

// Class representing a book in the library
class Book {
protected:
    string code, title, author, publisher;
    int quantity;
    bool isLent;

public:
    static int totalBooks; // Total number of books in the library

    Book(string c, string t, string a, string p, int qty) {
        code = c; 
        title = t; 
        author = a; 
        publisher = p; 
        quantity = qty;
        isLent = false;
        totalBooks++;
    }

    Book() : isLent(false) {}

    string getCode() const { return code; }
    string getTitle() const { return title; }
    string getAuthor() const { return author; }
    string getPublisher() const { return publisher; }
    int getQuantity() const { return quantity; }
    bool isBookLent() const { return isLent; }

    void setCode(string c) { code = c; }
    void setTitle(string t) { title = t; }
    void setAuthor(string a) { author = a; }
    void setPublisher(string p) { publisher = p; }
    void setQuantity(int qty) { quantity = qty; }
    void setLentStatus(bool status) { isLent = status; }

    void display() const; // Display book information
    friend istream& operator>>(istream& stream, Book& b);
    friend ostream& operator<<(ostream& stream, const Book& b);
};

void Book::display() const {
    cout << "Index: " << getCode() << '\t' 
         << "Title: " << getTitle() << '\t' 
         << "Author: " << getAuthor() << '\t' 
         << "Publisher: " << getPublisher() << '\t' << endl;
}

ostream& operator<<(ostream& stream, const Book& b) {
    stream << "Index: " << b.code << '\t' 
           << "Title: " << b.title << '\t' 
           << "Author: " << b.author << '\t' 
           << "Publisher: " << b.publisher << '\t' << endl;
    return stream;
}

istream& operator>>(istream& stream, Book& b) {
    cout << "Enter index: "; stream >> b.code;
    cout << "Enter title: "; stream >> b.title;
    cout << "Enter author: "; stream >> b.author;
    cout << "Enter publisher: "; stream >> b.publisher;
    return stream;
}

int Book::totalBooks = 0;

// Class representing a user in the library system
class User {
protected:
    string name;
    string id;
    string password;
    string institute;
    bool isLibrarian, isAdmin, isStudent;

public:
    User(string n, string id, string pwd, string inst) {
        name = n; 
        this->id = id; 
        password = pwd; 
        institute = inst;
        isLibrarian = false; 
        isAdmin = false; 
        isStudent = true;
    }

    User() : isAdmin(false), isStudent(true), isLibrarian(false) {}

    static int totalUsers;

    void setIdentity(bool librarian, bool student, bool admin) {
        isLibrarian = librarian; 
        isStudent = student; 
        isAdmin = admin;
    }

