    return 0;                  // Unknown
}

// Class for managing user login and registration
class Log {
public:
    User currentUser; // Stores the currently logged-in user's information
    int userIndex;
    bool isLoggedIn;

    Log() : userIndex(0), isLoggedIn(false) {}

    void signIn(User* users);
    void login(User* users);
};

void Log::signIn(User* users) {
    string studentID;
    bool isRegistered;

    while (true) {
        isRegistered = false;
        cout << "Enter student ID: ";
        cin >> studentID;

        for (int i = 0; i < User::totalUsers; i++) {
            if (users[i].getID() == studentID) {
                cout << "This student is already registered!" << endl;
                isRegistered = true;
                break;
            }
        }

        if (!isRegistered) break;
    }

    string name, institute, password, confirmPassword;

    while (true) {
        cout << "Enter name: "; cin >> name;
        cout << "Enter institute: "; cin >> institute;
        cout << "Enter password: "; cin >> password;
        cout << "Confirm password: "; cin >> confirmPassword;

        if (password != confirmPassword) {
            cout << "Passwords do not match, please try again." << endl;
        } else {
            break;
        }
    }

    users[User::totalUsers].setIdentity(false, true, false);
    users[User::totalUsers].setName(name);
    users[User::totalUsers].setID(studentID);
    users[User::totalUsers].setPassword(password);
    users[User::totalUsers].setInstitute(institute);

    currentUser = users[User::totalUsers];
    userIndex = User::totalUsers;
    User::totalUsers++;
    cout << "Registration successful!" << endl;
}

void Log::login(User* users) {
    string studentID, password;
    bool isAuthenticated = false;

    cout << "Enter student ID: "; cin >> studentID;
    cout << "Enter password: "; cin >> password;

    for (int i = 0; i < User::totalUsers; i++) {
        if (studentID == users[i].getID() && password == users[i].getPassword()) {
            currentUser = users[i];
            isAuthenticated = true;
            break;
        }
    }

    if (isAuthenticated) {
        isLoggedIn = true;
        cout << "Login successful!" << endl;
    } else {
        cout << "Invalid ID or password." << endl;
        isLoggedIn = false;
    }
}

