    cout << "------- Find Book -------" << endl;
    cout << "Enter book index or title: "; cin >> searchTerm;

    int foundCount = 0;
    for (int i = 0; i < Book::totalBooks; i++) {
        if (searchTerm == books[i].getCode() || searchTerm == books[i].getTitle()) {
            foundCount++;
            cout << books[i];
        }
    }

    if (foundCount == 0) {
        cout << "No books found." << endl;
    } else {
