void Student::displayBorrowInfo() {
    cout << "--------- Borrow Info ---------" << endl;
    cout << "Name: " << getName() << '\t' 
         << "ID: " << getID() << '\t' 
         << "Institute: " << getInstitute() << '\t' 
         << "Max Borrow Limit: " << maxBorrowLimit << '\t' << endl;

    cout << "Current borrowed books:" << endl;
    bool hasBorrowedBooks = false;

    for (int i = 0; i < totalStudents; i++) {
        if (borrowedBooks[i].isBookLent()) {
            hasBorrowedBooks = true;
            borrowedBooks[i].display();
        }
    }

    if (!hasBorrowedBooks) {
        cout << "No borrowed records." << endl;
    }
}

void Student::borrowBook(Book* books) {
    string searchTerm;
    cout << "--------- Borrow Book ---------" << endl;
    cout << "Enter the index or title of the book to borrow: "; cin >> searchTerm;

    int foundIndex = -1;
    for (int i = 0; i < Book::totalBooks; i++) {
        if ((searchTerm == books[i].getCode() || searchTerm == books[i].getTitle()) && !books[i].isBookLent()) {
            foundIndex = i;
            break;
        }
    }

    if (foundIndex == -1) {
        cout << "Book not found or already borrowed!" << endl;
        return;
    }

    int borrowedCount = 0;
    for (int i = 0; i < totalStudents; i++) {
        if (borrowedBooks[i].isBookLent()) {
            borrowedCount++;
        }
    }

    if (borrowedCount >= maxBorrowLimit) {
        throw maxBorrowLimit; // Exceeded maximum borrow limit
    }

    cout << "Borrowing successful!" << endl;
    books[foundIndex].setLentStatus(true);
    borrowedBooks[foundIndex] = books[foundIndex];

    ofstream lendMessage("LendMessage.txt", ios::app);
    if (lendMessage.is_open()) {
        lendMessage << "Name: " << getName() << endl;
        lendMessage << "Borrowed Index: " << borrowedBooks[foundIndex].getCode() << endl;
        lendMessage.close();
    }
}

void Student::returnBook(Book* books) {
    string searchTerm;
    cout << "--------- Return Book ---------" << endl;
    cout << "Enter the index or title of the book to return: "; cin >> searchTerm;

    int foundIndex = -1;
    for (int i = 0; i < Book::totalBooks; i++) {
        if (searchTerm == books[i].getCode() || searchTerm == books[i].getTitle()) {
            foundIndex = i;
            break;
        }
    }

    if (foundIndex == -1) {
        cout << "Book not found!" << endl;
        return;
    }

    if (!borrowedBooks[foundIndex].isBookLent()) {
        cout << "This book was not borrowed." << endl;
        return;
    }

    borrowedBooks[foundIndex].setLentStatus(false);
    books[foundIndex].setLentStatus(false);

    ofstream returnMessage("ReturnMessage.txt", ios::app);
    if (returnMessage.is_open()) {
        returnMessage << "Name: " << getName() << endl;
        returnMessage << "Returned Index: " << borrowedBooks[foundIndex].getCode() << endl;
        returnMessage.close();
    }

    cout << "Return successful!" << endl;
}

