void Admin::modifyBook(Book* books) {
    cout << "------- Modify Book Information -------" << endl;
    string searchTerm;

    if (Book::totalBooks == 0) {
        cout << "No books available, please add books first." << endl;
        return;
    }

    cout << "Enter book index or title: "; cin >> searchTerm;
    int foundIndex = -1;

    for (int i = 0; i < Book::totalBooks; i++) {
        if (searchTerm == books[i].getTitle() || searchTerm == books[i].getCode()) {
            foundIndex = i;
            break;
        }
    }

    if (foundIndex != -1) {
        char confirmation;
        cout << "Found book, Index: " << books[foundIndex].getCode() << '\t' 
             << "Title: " << books[foundIndex].getTitle() << '\t' 
             << "Author: " << books[foundIndex].getAuthor() << '\t' 
             << "Publisher: " << books[foundIndex].getPublisher() << '\t' << endl;
        cout << "Do you want to modify? (y/n): "; cin >> confirmation;

        if (confirmation == 'y') {
            cout << "1 - Modify Index" << endl;
            cout << "2 - Modify Title" << endl;
            cout << "3 - Modify Author" << endl;
            cout << "4 - Modify Publisher" << endl;
            cout << "0 - Exit Modification" << endl;

            int choice;
            cin >> choice;

            switch (choice) {
                case 1: {
                    string newIndex;
                    while (true) {
                        cout << "Enter new index: "; cin >> newIndex;
                        bool exists = false;

                        for (int i = 0; i < Book::totalBooks; i++) {
                            if (books[i].getCode() == newIndex) {
                                exists = true;
                                break;
                            }
                        }

                        if (!exists) {
                            books[foundIndex].setCode(newIndex);
                            cout << "Modification successful!" << endl;
                            break;
                        } else {
                            cout << "This index already exists, please modify!" << endl;
                        }
                    }
                    break;
                }
                case 2: {
                    string newTitle;
                    cout << "Enter new title: "; cin >> newTitle;
                    books[foundIndex].setTitle(newTitle);
                    cout << "Modification successful!" << endl;
                    break;
                }
                case 3: {
                    string newAuthor;
                    cout << "Enter new author: "; cin >> newAuthor;
                    books[foundIndex].setAuthor(newAuthor);
                    cout << "Modification successful!" << endl;
                    break;
                }
                case 4: {
                    string newPublisher;
                    cout << "Enter new publisher: "; cin >> newPublisher;
                    books[foundIndex].setPublisher(newPublisher);
                    cout << "Modification successful!" << endl;
                    break;
                }
                case 0:
                    break;
            }

            ofstream bookMessage("BookMessage.txt", ios::app);
            if (bookMessage.is_open()) {
                bookMessage << "Operation: Modify Book " << endl;
                bookMessage << books[foundIndex] << endl;
                bookMessage.close();
            }
        }
    } else {
