// Test data
Book books[10000] = {
    Book("10000", "Object-Oriented Programming", "Wu Nailin", "Higher Education Press", 2),
    Book("10001", "Random Signal Processing", "Luo Pengfei", "Tsinghua University Press", 3),
    Book("10002", "Digital Signal Processing", "Cheng Peiqing", "Tsinghua University Press", 1)
};

User users[10000];
Student students[10000];
Librarian librarians[100] = { Librarian("A", "8", "123", users) };
Admin admins[100] = { Admin("admin", "123", "123", users) };
Log log;

int main() {
    while (true) {
        mainInterface();
        int choice;
        string input; cin >> input;

        if (input == "1") choice = 1;
        else if (input == "2") choice = 2;
        else if (input == "3") choice = 3;
        else {
            cout << "Please enter a valid option!" << endl;
            continue;
        }

        switch (choice) {
            case 1: {
                cout << "       Student Registration" << endl;
                students[Student::totalStudents].registerStudent(users, log);
                break;
            }
            case 2: {
                cout << "       Login" << endl;
                log.login(users);
                if (!log.isLoggedIn) break;

                switch (log.currentUser.determineUserType()) {
                    case 3: { // Librarian
                        int option = 1;
                        while (option) {
                            librarianInterface();
                            char action; cin >> action;
                            switch (action) {
                                case 'A': librarians[log.userIndex].addBook(books); break;
                                case 'B': librarians[log.userIndex].modifyBook(books); break;
                                case 'C': librarians[log.userIndex].deleteBook(books); break;
                                case 'D': librarians[log.userIndex].findBook(books); break;
                                case 'E': librarians[log.userIndex].addStudent(users, students); break;
                                case 'F': librarians[log.userIndex].deleteStudent(users, students); break;
                                case 'G': librarians[log.userIndex].findStudent(students); break;
                                case 'H': librarians[log.userIndex].lendBookToStudent(students, books); break;
                                case 'I': librarians[log.userIndex].returnBookFromStudent(students, books); break;
                                default: option = 0;
                            }
                        }
                        break;
                    }
                    case 4: { // Student
                        int option = 1;
                        while (option) {
                            studentInterface();
                            char action; cin >> action;
                            switch (action) {
                                case 'A': students[log.userIndex].findBook(books); break;
                                case 'B': 
                                    try {
                                        students[log.userIndex].borrowBook(books);
                                    } catch (int limit) {
                                        cout << "Exceeded maximum borrow limit, borrowing failed." << endl;
                                    }
                                    break;
                                case 'C': students[log.userIndex].returnBook(books); break;
                                case 'D': students[log.userIndex].displayBorrowInfo(); break;
                                case 'E': students[log.userIndex].showBooks(books); break;
                                default: option = 0;
                            }
                        }
                        break;
                    }
                    case 5: { // Admin
                        int option = 1;
                        while (option) {
                            adminInterface();
                            char action; cin >> action;
                            switch (action) {
                                case 'A': admins[log.userIndex].addBook(books); break;
                                case 'B': admins[log.userIndex].modifyBook(books); break;
                                case 'C': admins[log.userIndex].deleteBook(books); break;
                                case 'D': admins[log.userIndex].findBook(books); break;
                                case 'E': admins[log.userIndex].addStudent(users, students); break;
                                case 'F': admins[log.userIndex].deleteStudent(users, students); break;
                                case 'G': admins[log.userIndex].findStudent(students); break;
                                case 'H': admins[log.userIndex].lendBookToStudent(students, books); break;
                                case 'I': admins[log.userIndex].returnBookFromStudent(students, books); break;
                                case 'J': admins[log.userIndex].addLibrarian(users, librarians); break;
                                case 'K': admins[log.userIndex].deleteLibrarian(users, librarians); break;
                                case 'L': admins[log.userIndex].findLibrarian(librarians); break;
                                default: option = 0;
                            }
                        }
                        break;
                    }
                    default: break;
                }
                break;
            }
            case 3: {
                cout << "             System exited" << endl;
                return 0;
            }
            default: break;
        }
        cin.get(); // Consume newline character
    }
    return 0;
}

