void VehicleData::updateData(const char *vehicleNumberInput) {
    FeatureManager featureManager;
    int recordFound = 0;
    fstream file;

    file.open("file1.dat", ios::in | ios::out | ios::ate | ios::binary);
    file.seekg(0);
    file.read(reinterpret_cast<char*>(this), sizeof(*this));
    while (!file.eof()) {
        if (!strcmp(vehicleNumberInput, vehicleNumber)) {
            readData();
            int position = static_cast<int>(file.tellg()) - sizeof(*this);
            file.seekp(position, ios::beg);
            file.write(reinterpret_cast<char*>(this), sizeof(*this));
            recordFound++;
        }
        file.read(reinterpret_cast<char*>(this), sizeof(*this));
    }
    file.close();

    if (recordFound == 0)
        cout << "\n\tUnable to Update";
    else
        cout << "\n\tUpdated Successfully";

    cout << "\n\tPress any key to continue...";
    getch();
    featureManager.recordVehicle();
}

