// Creates a menu for user interaction
int createMenu(const char* title, char options[][50], int optionCount = 0, int step = 3, int start = 6) {
    clrscr();
    createBorders();
    createHorizontalRule(4, '*');
    centerText(title, 2);

    for (int i = 0; i < optionCount; i++) {
        char numberedOption[50] = { i + 49, '.' }; // Numbered list
        strcpy(numberedOption + 2, options[i]);
        centerText(numberedOption, start + (i * step));
    }

    char choice;
    int selectedOption = start;
    alignText("<--", 60, start);
    while (choice != 13) { // Enter key
        choice = getch();
        choice = toupper(choice);
        switch (choice) {
            case 'W':
                if (selectedOption > start) {
                    alignText("   ", 60, selectedOption);
                    selectedOption -= step;
                    alignText("<--", 60, selectedOption);
                }
                break;
            case 'S':
                if (selectedOption < (start + (optionCount - 1) * step)) {
                    alignText("   ", 60, selectedOption);
                    selectedOption += step;
                    alignText("<--", 60, selectedOption);
                }
                break;
            default:
                break;
        }
    }
    return (selectedOption - start) / step;
}

