const int maxLetters = 80; // Maximum letters for the game
const int maxTries = 5;    // Maximum tries for the game

int fillLetters(char guess, char secretWord[], char guessedWord[]);
void displayUnknownWord(char word[], char unknown[]);

// Simple hangman game implementation
void playGame() {
    char letter, unknown[maxLetters], word[maxLetters];
    int wrongGuessCount = 0;
    char words[][maxLetters] = {
        "india", "bahrain", "sweden", "australia", "germany",
        "russia", "france", "mexico", "denmark", "vietnam"
    };
    randomize();
    int randomIndex = random(10);
    strcpy(word, words[randomIndex]);
    displayUnknownWord(word, unknown);
    alignText("Welcome to hangman", 1, 2);
    alignText("Guess the country name", 1, 3);
    alignText("You have 5 guesses left", 1, 4);
    alignText("~~~~~~~~~~~~~~~~~~~~~~~~", 1, 5);

    while (wrongGuessCount < maxTries) {
        gotoxy(1, 6);
        std::cout << std::endl << std::endl << unknown;
        alignText("\n\nGuess a letter: ", 1, 7);
        std::cin >> letter;

        if (fillLetters(letter, word, unknown) == 0) {
            wrongGuessCount++;
            clrscr();
        } else {
            clrscr();
        }

        gotoxy(1, 4);
        std::cout << "You have " << (maxTries - wrongGuessCount) << " guesses left" << std::endl;

        if (strcmp(word, unknown) == 0) {
            gotoxy(1, 8);
            std::cout << word << std::endl;
            alignText("You guessed it right!", 1, 9);
            alignText("Press Any Key To Continue", 27, 15);
            getche();
            exitProgram();
            break;
        }
    }

    if (wrongGuessCount == maxTries) {
        gotoxy(1, 7);
        std::cout << std::endl << "You lose... you've been hanged." << std::endl;
        gotoxy(1, 6);
        std::cout << "The word was: " << word << std::endl;
        dixit(33, 3);
        dixit(47, 3);
        dixit(61, 3);
        alignText("Press Any Key To Continue", 27, 15);
        getche();
        exitProgram();
    }
    getch();
}

// Fills the guessed letters in the unknown word
int fillLetters(char guess, char secretWord[], char guessedWord[]) {
    int matches = 0;
    for (int i = 0; secretWord[i] != '\0'; i++) {
        if (guess == guessedWord[i]) {
            return 0;
        }
        if (guess == secretWord[i]) {
            guessedWord[i] = guess;
            matches++;
        }
    }
    return matches;
}

// Initializes the unknown word with asterisks
void displayUnknownWord(char word[], char unknown[]) {
    for (int i = 0; i < strlen(word); i++) {
        unknown[i] = '*';
    }
    unknown[strlen(word)] = '\0';
}

