// Encrypts the entered word by adding the length of the string to each character
char* encryptPassword(char password[]) {
    for (int i = 0; password[i] != '\0'; i++) {
        password[i] += strlen(password);
    }
    return password;
}

// Function to get password input securely
char* getPassword() {
    static char password[200];
    int index = 0;

    while (true) {
        password[index] = getch();
        if (password[index] == 13) { // Enter key
            password[index] = '\0';
            break;
        } else if (index >= 1 && password[index] == 8) { // Backspace
            index--;
            gotoxy(46 + index, 12);
            std::cout << " ";
            gotoxy(46 + index, 12);
        } else {
            std::cout << '*';
            index++;
        }
    }
    return password;
}

