    std::cout << text;
}

void delay(long duration) {
    for (long a = 0; a < duration; a++) {
        std::cout << "";
    }
}

// Displays the banner from a file
void displayBanner() {
    std::ifstream file("banner.txt");
    if (!file) {
        std::cout << "\nFile Not Found";
        getch();
        return;
    }

    char line[500];
    while (!file.eof()) {
        std::cout << std::endl;
        file.getline(line, 450, '\n');
        for (int i = 0; line[i] != '\0'; i++) {
            std::cout << line[i];
            delay(195);
        }
    }
    getch();
}

// Creates horizontal rule
void createHorizontalRule(int row, char character) {
    for (int j = 0; j < 80; j++) {
        gotoxy(j, row);
        std::cout << character;
    }
}

// Creates vertical rule
void createVerticalRule(int column, char character) {
    for (int j = 0; j < 25; j++) {
        gotoxy(column, j);
        std::cout << character;
    }
}

// Creates borders for the display
void createBorders() {
    char borderChar = '*';
    createHorizontalRule(0, borderChar);
    createHorizontalRule(25, borderChar);
    createVerticalRule(0, borderChar);
    createVerticalRule(81, borderChar);
}

// Centers text on the screen
void centerText(const char* text, int y = 12) {
    int length = strlen(text);
    gotoxy(40.5 - length / 2, y);
    std::cout << text;
}

// Creates output screen with border and heading
void createMenu(const char* title, const char array[][50], int size = 0, int step = 3, int start = 6) {
    clrscr();
    createBorders();
    createHorizontalRule(4, '*');
    centerText(title, 2);
    for (int i = 0; i < size; i++) {
        char numberedItem[50] = { i + 49, '.' };
        for (int j = 2; array[i][j - 2] != '\0'; j++) {
            numberedItem[j] = array[i][j - 2];
        }
        alignText(numberedItem, 30, start + (i * step));
    }
}

// Displays a simple error screen
void displayErrorMessage(const char* errorMessage = "null") {
