// User Class
class User {
    char username[200];
    char password[200];

public:
    void input() {
        alignText("Enter Username: ", 30, 10);
        gets(username);
        alignText("Enter Password: ", 30, 12);
        strcpy(password, getPassword());
        strcpy(password, encryptPassword(password));
    }

    int access(const char enteredUsername[], const char enteredPassword[]) {
        return (strcmp(enteredPassword, password) == 0 && strcmp(enteredUsername, username) == 0) ? 1 : 0;
    }
};

