void Patient::processPayment() {
    float amountPaid;
    start:
    createMenu("PAY BILL");
    alignText("Amount Payable: ", 30, 10);
    std::cout << total;
    alignText("Pay full amount(Y/N): ", 30, 11);
    char choice = toupper(getche());

    if (choice == 'Y') {
        amountPaid = total;
    } else if (choice == 'N') {
        alignText("                              ", 30, 11);
        alignText("Amount Paid: ", 30, 11);
        std::cin >> amountPaid;
    } else {
        goto start;
    }

    if (amountPaid <= 0) {
        displayErrorMessage("Invalid Amount!!!");
        goto start;
    }

    strcpy(treatmentDescription[treatmentCount], "BILL PAID");
    treatmentAmount[treatmentCount] = -amountPaid;
    treatmentQuantity[treatmentCount] = 0;
    treatmentCount++;
    displayMessage("You Have Closed A Payment");
    calculateTotal();
}

float Patient::calculateTotal() {
    total = 0;
    for (int i = 0; i < treatmentCount; i++) {
        total += (treatmentQuantity[i] == 0) ? treatmentAmount[i] : treatmentQuantity[i] * treatmentAmount[i];
    }
    return total;
}

