// Search Patient Function
void searchPatient() {
    while (true) {
        char searchOptions[][50] = { "Search by Name", "Search by CPR" };
        createMenu("Patient Search", searchOptions, ARRAY_SIZE(searchOptions), 4);
        centerText("Enter your option: ", 15);
        char name[20];
        long cpr;
        char choice = getch();
        clrscr();
        createBorders();

        switch (choice) {
            case '1':
                centerText("Enter name: ", 21);
                gets(name);
                break;
            case '2':
                centerText("Enter CPR Number: ", 21);
                std::cin >> cpr;
                break;
            default:
                displayErrorMessage("Invalid Option....");
                continue;
        }

        Patient patient;
        std::ifstream patientFile("patients.dat", std::ios::in | std::ios::binary);
        bool recordFound = false;

        while (patientFile.read(reinterpret_cast<char*>(&patient), sizeof(patient))) {
            if (patient.checkName(name) && choice == '1') {
                patient.display();
                recordFound = true;
                break;
            }
            if (patient.checkCpr(cpr) && choice == '2') {
                patient.display();
                recordFound = true;
                break;
            }
        }

        if (!recordFound) {
            displayErrorMessage("Record Doesn't Exist");
            mainMenu();
        }
    }
}

