void billing() {
    clrscr();
    createBorders();
    Patient patient;
    long cpr = 0;
    createBorders();
    alignText("Enter CPR number: ", 17, 12);
    std::cin >> cpr;

    std::fstream patientFile("patients.dat", std::ios::in | std::ios::binary);
    remove("patients.bak");
    bool recordFound = false;

    while (patientFile.read(reinterpret_cast<char*>(&patient), sizeof(patient))) {
        if (patient.checkCpr(cpr) == 1) {
            recordFound = true;
            break;
        }
    }

    if (!recordFound) {
        displayErrorMessage("CPR No. Doesn't Exist");
        return;
    }

    patientFile.close();
    char billingOptions[][50] = { "Add Treatments", "Pay Bill" };
    createMenu("BILLING", billingOptions, ARRAY_SIZE(billingOptions));
    centerText("Enter your option: ", 18);
    char choice = getch();

    switch (choice) {
        case '1':
            patient.addTreatment();
            break;
        case '2':
            patient.processPayment();
            break;
    }

    std::ofstream outfile("patients.bak", std::ios::out | std::ios::binary);
    std::ifstream infile("patients.dat", std::ios::in | std::ios::binary);

    while (infile.read(reinterpret_cast<char*>(&patient), sizeof(patient))) {
        if (patient.checkCpr(cpr) == 1) {
            outfile.write(reinterpret_cast<char*>(&patient), sizeof(patient));
            getch();
        } else {
            outfile.write(reinterpret_cast<char*>(&patient), sizeof(patient));
        }
    }

    infile.close();
    outfile.close();
    remove("patients.dat");
    rename("patients.bak", "patients.dat");
}

