void removePatient() {
    while (true) {
        createMenu("REMOVE PATIENT");
        long cpr = 0;
        alignText("Enter The CPR No.: ", 30, 7);
        std::cin >> cpr;

        bool recordFound = false;
        std::ifstream infile("patients.dat", std::ios::in | std::ios::binary);
        std::ofstream outfile("temp.dat", std::ios::app | std::ios::binary);
        std::ofstream archive("archive.dat", std::ios::app | std::ios::binary);
        Patient patient;

        while (infile.read(reinterpret_cast<char*>(&patient), sizeof(patient))) {
            if (patient.checkCpr(cpr) && patient.total == 0) {
                recordFound = true;
                alignText("PATIENT DISCHARGED....");
                archive.write(reinterpret_cast<char*>(&patient), sizeof(patient));
                getch();
                continue;
            } else if (patient.checkCpr(cpr) && patient.total != 0) {
                displayMessage("Payment Pending....");
                alignText("Please clear pending bill to continue...", 30, 20);
                patient.generateBill();
                patient.processPayment();
                outfile.write(reinterpret_cast<char*>(&patient), sizeof(patient));
                recordFound = true;
                continue;
            } else {
                outfile.write(reinterpret_cast<char*>(&patient), sizeof(patient));
            }
        }

        if (!recordFound) {
            alignText("Entry not found", 30, 14);
            getch();
        }

        remove("patients.dat");
        rename("temp.dat", "patients.dat");
        archive.close();
        outfile.close();
        infile.close();

        if (recordFound) {
            continue;
        }
        break;
    }
}

