const int MAX_LENGTH = 80; // for game program
const int MAX_TRIES = 5;   // for game program

int fillLetter(char guess, char secretWord[], char guessWord[]);
void displayUnknown(char word[], char unknown[]);

// Simple hangman game
void playGame() {
    char letter, unknown[MAX_LENGTH], word[MAX_LENGTH];
    int wrongGuesses = 0;
    char words[][MAX_LENGTH] = {
        "india", "bahrain", "sweden", "australia", "germany",
        "russia", "france", "mexico", "denmark", "vietnam", "kuwait",
        "china", "japan", "dubai", "spain", "finland", "canada", "argentina"
    };

    randomize();
    int randomIndex = random(17);
    strcpy(word, words[randomIndex]);
    displayUnknown(word, unknown);
    alignText("Welcome to hangman", 1, 2);
    alignText("Guess the country name", 1, 3);
    alignText("You have 5 guesses left", 1, 4);
    alignText("~~~~~~~~~~~~~~~~~~~~~~~~", 1, 5);

    while (wrongGuesses < MAX_TRIES) {
        gotoxy(1, 6);
        std::cout << std::endl << std::endl << unknown;
        alignText("\n\nGuess a letter: ", 1, 7);
        std::cin >> letter;

        if (fillLetter(letter, word, unknown) == 0) {
            wrongGuesses++;
            clrscr();
        } else {
            clrscr();
        }

        gotoxy(1, 4);
        std::cout << "You have " << MAX_TRIES - wrongGuesses << " guesses left" << std::endl;

        if (strcmp(word, unknown) == 0) {
            gotoxy(1, 8);
            std::cout << word << std::endl;
            alignText("You guessed it right!", 1, 9);
            alignText("Press Any Key To Continue", 27, 15);
            getche();
            exitProgram();
            break;
        }
    }

    if (wrongGuesses == MAX_TRIES) {
        gotoxy(1, 7);
        std::cout << std::endl << "You lose... you've been hanged." << std::endl;
        gotoxy(1, 6);
        std::cout << "The word was: " << word << std::endl;
        displayUnknown("¯\\_('_')_/¯", 33, 3);
        displayUnknown("|", 38, 4);
        displayUnknown("|", 38, 5);
        displayUnknown("|", 38, 6);
        displayUnknown("/ \\", 37, 7);
        displayUnknown("_/   \\_", 35, 8);
        alignText("Press Any Key To Continue", 27, 15);
        getche();
        exitProgram();
    }
    getch();
}

int fillLetter(char guess, char secretWord[], char guessWord[]) {
    int matches = 0;
    for (int i = 0; secretWord[i] != '\0'; i++) {
        if (guess == guessWord[i]) {
            return 0;
        }
        if (guess == secretWord[i]) {
            guessWord[i] = guess;
            matches++;
        }
    }
    return matches;
}

void displayUnknown(char word[], char unknown[]) {
    for (int i = 0; i < strlen(word); i++) {
        unknown[i] = '*';
    }
    unknown[strlen(word)] = '\0';
}

