class Library {
public:
    string bookTitles[MAX_BOOKS];
    int bookIds[MAX_BOOKS];
    int bookCount = 0;

    // Adds a new book to the library
    void addBook() {
        cout << "Enter the name of the book: ";
        cin.ignore();
        getline(cin, bookTitles[bookCount]);

        cout << "Enter the ID of the book: ";
        cin >> bookIds[bookCount];
        bookCount++;
    }

    // Deletes a book from the library by title
    void deleteBook() {
        cout << "Enter the book title to delete: ";
        string titleToDelete;
        cin.ignore();
        getline(cin, titleToDelete);

        bool found = false;
        for (int i = 0; i < bookCount; i++) {
            if (bookTitles[i] == titleToDelete) {
                found = true;
                // Shift books to fill the gap
                for (int j = i; j < bookCount - 1; j++) {
                    bookTitles[j] = bookTitles[j + 1];
                    bookIds[j] = bookIds[j + 1];
                }
                bookCount--;
                break;
            }
        }

        if (!found) {
            cout << "Book not found." << endl;
        }
    }

    // Displays all books in the library
    void displayBooks() const {
        cout << "Books in the library:" << endl;
        for (int i = 0; i < bookCount; i++) {
            cout << "Title: " << bookTitles[i] << ", ID: " << bookIds[i] << endl;
        }
    }

    // Shows the menu options for the user
    void showMenu() const {
        cout << "\n1) Add Book\n";
        cout << "2) Delete Book\n";
        cout << "3) Display Books\n";
        cout << "4) Exit\n";
        cout << "Enter your choice: ";
    }
};

int main() {
    Library library;
    while (true) {
        int choice;
        library.showMenu();
        cin >> choice;

        if (choice == 4) {
            cout << "\nSuccessfully exited!\n\n";
            break;
        } else {
            switch (choice) {
                case 1:
                    library.addBook();
                    break;
                case 2:
                    library.deleteBook();
                    break;
                case 3:
                    library.displayBooks();
                    break;
                default:
                    cout << "Please enter a valid choice.\n";
                    break;
            }
        }
    }

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <iomanip>

using namespace std;

class Book {
private:
    string title;
    string author;
    string genre;
    int quantity;

public:
    bool operator==(const Book& other) {
        return (author == other.author || title == other.title || genre == other.genre);
    }

    int inputData();
    void searchByAuthor();
    void displayByCategory();
    int getTotalCount();
};

vector<Book> bookCollection;
vector<string> categories;

int Book::inputData() {
    string inputGenre;
    Book tempBook;
    int additionalCopies;

    cin.ignore();
    cout << "\nEnter name of book: ";
    getline(cin, tempBook.title);

    auto bookIterator = find(bookCollection.begin(), bookCollection.end(), tempBook);

    if (bookIterator == bookCollection.end()) {
        title = tempBook.title;
        cout << "Enter book author's name: ";
        getline(cin, author);
        cout << "Enter category of book: ";
        getline(cin, inputGenre);
        genre = inputGenre;

        auto categoryIterator = find(categories.begin(), categories.end(), genre);
        if (categoryIterator == categories.end()) {
            categories.push_back(genre);
        }

        cout << "Enter the number of copies of the book to add (at least 1): ";
        cin >> quantity;
        return 0;
    } else {
        cout << "Book already exists" << endl;
        cout << "Enter number of copies to add: ";
        cin >> additionalCopies;

        if (additionalCopies >= 0) {
            bookIterator->quantity += additionalCopies;
        } else {
            cout << "Invalid input" << endl;
        }
        return 1;
    }
}

void Book::searchByAuthor() {
    Book searchBook;
    bool found = false;
    bool headerDisplayed = false;

    cin.ignore();
    cout << "\nEnter book author's name: ";
    getline(cin, searchBook.author);

    auto bookIterator = bookCollection.begin();

    while ((bookIterator = find(bookIterator, bookCollection.end(), searchBook)) != bookCollection.end()) {
        found = true;

        if (!headerDisplayed) {
            cout << "\nBooks by author found: " << endl;
            cout << "\n" << setw(25) << "Book Name" << setw(25) << "Category" << setw(15) << "Copies" << endl;
            headerDisplayed = true;
        }
        cout << setw(25) << bookIterator->title << setw(25) << bookIterator->genre << setw(15) << bookIterator->quantity << endl;
        bookIterator++;
    }
    if (!found) {
        cout << "No books found" << endl;
    }
}

void Book::displayByCategory() {
    int totalCopies;

    for (const auto& category : categories) {
        totalCopies = 0;
        cout << "\nCategory: " << category << endl;
        cout << "\n" << setw(25) << "Book Name" << setw(25) << "Author Name" << setw(15) << "Copies" << endl;

        for (const auto& book : bookCollection) {
            if (book.genre == category) {
                cout << setw(25) << book.title << setw(25) << book.author << setw(15) << book.quantity << endl;
                totalCopies += book.quantity;
            }
        }
        cout << setw(61) << "Total: " << setw(4) << totalCopies << endl;
    }
    cout << setw(60) << "Total Books In Library: " << setw(5) << getTotalCount() << endl;
}

int Book::getTotalCount() {
    int totalStock = 0;
    for (const auto& book : bookCollection) {
        totalStock += book.quantity;
    }
    return totalStock;
}

int main() {
    int userChoice;
    Book bookInstance;

    do {
        cout << "\n1. Add book    2. Search    3. View by category    4. Exit" << endl;
        cout << "Enter your choice: ";
        cin >> userChoice;

        switch (userChoice) {
            case 1:
                if (bookInstance.inputData() == 0) {
                    bookCollection.push_back(bookInstance);
                }
                break;
            case 2:
                bookInstance.searchByAuthor();
                break;
            case 3:
                bookInstance.displayByCategory();
                break;
            case 4:
                break;
        }
    } while (userChoice != 4);

    return 0;
}

