struct Node {
    char rowNumber;
    int seatNumber;
    int pin;
    char bookingStatus;
    Node* next;
    Node* prev;
};

class DoublyCircularLinkedList {
public:
    Node* head;

    DoublyCircularLinkedList() {
        head = nullptr;
    }

    // Initializes the seating arrangement with random PINs
    void createSeatingArrangement() {
        Node* newNode;
        Node* currentNode;
        int ticketCount = 1;
        char rowChar = 'A';

        do {
            int seatCount = 1;
            do {
                srand(static_cast<int>(time(0)));
                int randomPin = rand() % 10000 + 1;
                newNode = new Node();
                newNode->next = newNode->prev = nullptr;
                newNode->rowNumber = rowChar;
                newNode->seatNumber = seatCount;
                newNode->pin = randomPin;
                newNode->bookingStatus = 'a';

                if (head == nullptr) {
                    head = newNode;
                    newNode->next = newNode->prev = head;
                } else {
                    currentNode = head;
                    while (currentNode->next != head) {
                        currentNode = currentNode->next;
                    }
                    currentNode->next = newNode;
                    newNode->prev = currentNode;
                    newNode->next = head;
                    head->prev = newNode;
                }
                seatCount++;
            } while (seatCount <= 7);
            ticketCount++;
            rowChar++;
        } while (ticketCount <= 10);
    }

    // Displays the seating arrangement
    void displaySeating() {
        Node* currentNode = head;
        cout << "------------------------------------------------------------------\n";
        cout << "|                            Platinum                            |\n";

        while (currentNode->next != head) {
            if ((currentNode->prev)->rowNumber != currentNode->rowNumber) {
                cout << "| ";
            }
            cout << currentNode->rowNumber << currentNode->seatNumber;
            if (currentNode->bookingStatus == 'a') {
                cout << "\033[32;40m -> a  \033[0m";  // Green text with black background
            } else {
                cout << "\033[1;31;43m -> b  \033[0m";  // Red text
            }
            if ((currentNode->next)->rowNumber != currentNode->rowNumber) {
                cout << "|\n";
            }
            if (currentNode->rowNumber == 'C' && currentNode->seatNumber == 7) {
                cout << "------------------------------------------------------------------\n";
                cout << "|                             Gold                               |\n";
            }
            if (currentNode->rowNumber == 'H' && currentNode->seatNumber == 7) {
                cout << "------------------------------------------------------------------\n";
                cout << "|                            Silver                              |\n";
            }
            currentNode = currentNode->next;
        }
        cout << currentNode->rowNumber << currentNode->seatNumber;
        if (currentNode->bookingStatus == 'a') {
            cout << "\033[32;40m -> a  \033[0m";  // Green text with black background
        } else {
            cout << "\033[1;31;43m -> b  \033[0m";  // Red text
        }
        cout << "|\n";
        cout << "------------------------------------------------------------------\n\n";
        cout << "\033[1;33;49mPLATINUM-> 150              GOLD-> 100                  SILVER->60\033[0m\n";
    }

    // Displays booking confirmation
    void displayBookingConfirmation(Node* bookedSeats[20], int count) {
        if (count != 1) {
            cout << "------------------------------------------------------------------\n";
            cout << "THANK YOU!\nYOU HAVE SUCCESSFULLY BOOKED THE SEATS\n";
            for (int i = 1; i < count; i++) {
                cout << bookedSeats[i]->rowNumber << bookedSeats[i]->seatNumber << "    PIN : " << bookedSeats[i]->pin << "\n";
            }
            cout << "!!!!!!!!!!!!!!!!!!KEEP PIN SAFELY!!!!!!!!!!!!!!!!!!!\n";
            cout << "PINS ARE REQUIRED AT THE TIME OF CANCELLATION OF SEATS\n";
            cout << "------------------------------------------------------------------\n";
        }
    }

    // Handles seat booking process
    void bookSeat() {
        Node* currentNode;
        Node* bookedSeats[20];
        int numberOfTickets, bookedCount = 1;
        char row;
        int seat;
        char choice;

        do {
            bookedCount = 1;
