                while (currentNode->next != head) {
                    if (currentNode->rowNumber == row && currentNode->seatNumber == seat) {
                        if (currentNode->bookingStatus == 'a') {
                            currentNode->bookingStatus = 'b';
                            bookedSeats[bookedCount] = currentNode;
                            bookedCount++;
                        } else {
                            cout << "INVALID CHOICE!\n";
                            cout << currentNode->rowNumber << currentNode->seatNumber << " Seat is already reserved \n";
                        }
                    }
                    currentNode = currentNode->next;
                }

                if (currentNode->rowNumber == row && currentNode->seatNumber == seat) {
                    if (currentNode->bookingStatus == 'a') {
                        currentNode->bookingStatus = 'b';
                        bookedSeats[bookedCount] = currentNode;
