        topIndex = -1;
    }

    // Thêm phần tử vào ngăn xếp
    void push(int value);

    // Lấy phần tử ra khỏi ngăn xếp
    int pop();

    // Kiểm tra ngăn xếp có rỗng không
    bool isEmpty() const {
        return topIndex < 0;
    }

    // Kiểm tra ngăn xếp có đầy không
    bool isFull() const {
        return topIndex >= MAX_STACK_SIZE - 1;
    }

    // In nội dung ngăn xếp
    void print() const;

private:
    int topIndex; // Chỉ số của phần tử trên cùng
    int elements[MAX_STACK_SIZE]; // Mảng chứa các phần tử của ngăn xếp
};

#include "TimeStamp.h"
#include <iostream>
