#include <fstream>
#include <string>

using namespace std;

class Task {
public:
   // Constructor initializes task ID and timestamps
   Task(const string& taskID) {
      initializeTask(taskID);
   }

   Task(const char* taskID) {
      initializeTask(taskID);
   }

   // Destructor logs task details to file
   ~Task() {
      logTaskDetails();
   }

   // Setters and getters for start time
   void setStartTime(time_t startTime = 0) { 
      startTimeStamp.set(startTime); 
   }

   time_t getStartTime() const { 
      return startTimeStamp.get(); 
   }

   string getStartTimeAsString() const { 
      return startTimeStamp.getAsString(); 
   }

   // Setters and getters for finish time
   void setFinishTime(time_t finishTime = 0) { 
      finishTimeStamp.set(finishTime); 
   }

   time_t getFinishTime() const { 
      return finishTimeStamp.get(); 
   }

   string getFinishTimeAsString() const { 
      return finishTimeStamp.getAsString(); 
   }

   // Setters and getters for task ID
   void setID(const string& taskID) { 
      id = taskID; 
   }

   void setID(const char* taskID) { 
      id = taskID; 
   }

   string getID() const { 
      return id; 
   }

   // Calculate duration of the task
   double getDuration() const { 
      return difftime(getFinishTime(), getStartTime()); 
   }

private:
   // Initialize task with ID and default values
   void initializeTask(const string& taskID) {
      setID(taskID);
      logFileName = "log.dat";
      setStartTime();
      finishTimeStamp = startTimeStamp; // No duration yet
   }

   // Log task details to file and console
   void logTaskDetails() {
      // Set finish time if duration is still 0
      if (getFinishTime() == getStartTime()) {
         setFinishTime();
      }

      // Log task statistics to file
      ofstream logFile(logFileName.c_str(), ios::app);
      logFile << "\nID: " << id << '\n';
      logFile << "  Start Time: " << getStartTimeAsString() << endl;
      logFile << "  Finish Time: " << getFinishTimeAsString() << endl;
      logFile << "  Duration: " << getDuration() << endl;
      logFile.close(); // Ensure file is safely closed

      // Output task details to console
      cout << "\nID: " << id << '\n';
      cout << "  Start Time: " << getStartTimeAsString() << endl;
      cout << "  Finish Time: " << getFinishTimeAsString() << endl;
      cout << "  Duration: " << getDuration() << endl;
   }

   Task(); // Default constructor explicitly hidden

   TimeStamp startTimeStamp;
   TimeStamp finishTimeStamp;
   string id;
   string logFileName;
};

