// Case-insensitive string search
bool containsString(const string &source, const string &target) {
    auto it = search(
        source.begin(), source.end(),
        target.begin(), target.end(),
        [](char charA, char charB) { return toupper(charA) == toupper(charB); }
    );
    return (it != source.end());
}

// Comparator for pairs based on the first element
bool comparePairs(const pair<int, string> &a, const pair<int, string> &b) {
    return (a.first > b.first);
}

// Converts a string to uppercase
string toUpperCase(string str) {
    for (char &ch : str) {
        if (islower(ch)) {
            ch = toupper(ch);
        }
    }
    return str;
}

