                } else if (userChoice == 'N' || userChoice == 'n') {
                    if (bookIndex >= totalNovels) {
                        cout << "Invalid Input. Check the Id with search or display all once again.\n";
                        break;
                    }
                    bookFile.open(directoryPath + "/" + novels[bookIndex].fileName, ios::in);
                    bookFile.seekg(novels[bookIndex].start, ios::beg);
                    cout << novels[bookIndex].title;
                    int pageChoice;

                    do {
                        for (int i = 0; i < 50 && !bookFile.eof(); ++i) {
                            getline(bookFile, line);
                            cout << line << endl;
                        }
                        cout << "\nEnter 1: for next page\n-1: to close the book\n: ";
                        cin >> pageChoice;
                    } while (pageChoice == 1);
                    bookFile.close();

                } else {
                    cout << "Invalid book type input. Try again.\n";
                }
                break;

            case 4:
                cout << "Enter the type of book for which you want to analyse:\nEnter N for a Novel or P for a Play: ";
                cin >> userChoice;

                if (userChoice == 'p' || userChoice == 'P') {
                    cout << "Enter the Id of the play that you want to analyse: ";
                    cin >> bookIndex;
                    if (bookIndex >= totalPlays) {
                        cout << "Invalid Input. Check the Id with search or display all once again.\n";
                        break;
                    }
                    cout << "Enter the name of the character that you want to search for: ";
                    string characterName;
                    cin >> characterName;
                    characterName = toUpperCase(characterName);
                    characterName = " " + characterName;

                    bookFile.open(directoryPath + "/" + plays[bookIndex].fileName);
                    bookFile.seekg(plays[bookIndex].start);
                    map<int, set<string>> sceneCharacterMap;
                    string act;
                    vector<string> scenes;
                    set<string> resultCharacters;
                    string characterLine;
                    string previousLine;
                    int sceneNumber = 0;

                    while (getline(bookFile, line)) {
                        if (line.find("ACT") != string::npos) {
                            act = line;
                        }
                        if (line.find("SCENE") != string::npos) {
                            scenes.push_back(act + " " + line);
                            sceneNumber++;
                        }
                        istringstream lineStream(line);
                        lineStream >> characterLine;
                        previousLine = "";

                        if (all_of(characterLine.begin(), characterLine.end(), ::isupper)) {
                            if (characterLine != "SCENE" && characterLine != "ACT") {
                                previousLine += " " + characterLine;
                                lineStream >> characterLine;
                            }
                        }
                        if (characterLine.back() == '.') {
                            characterLine.pop_back();
                            if (all_of(characterLine.begin(), characterLine.end(), ::isupper)) {
                                previousLine += " " + characterLine;
                                sceneCharacterMap[sceneNumber - 1].insert(previousLine);
                            }
                        }
                    }

                    for (int i = 0; i < sceneNumber; i++) {
                        if (sceneCharacterMap[i].find(characterName) != sceneCharacterMap[i].end()) {
                            resultCharacters.insert(sceneCharacterMap[i].begin(), sceneCharacterMap[i].end());
                        }
                    }
                    cout << "The characters that share a scene with " << characterName << " are:\n";
                    for (const auto &character : resultCharacters) {
                        cout << character << endl;
                    }
                    bookFile.close();

                } else if (userChoice == 'n' || userChoice == 'N') {
                    cout << "Enter the Id of the novel that you want to analyse: ";
                    cin >> bookIndex;
                    if (bookIndex >= totalNovels) {
                        cout << "Invalid Input. Check the Id with search or display all once again.\n";
                        break;
                    }
                    cout << "Enter the word that you want to search for: ";
                    string searchWord;
                    cin >> searchWord;
                    bookFile.open(directoryPath + "/" + novels[bookIndex].fileName);
                    bookFile.seekg(novels[bookIndex].start);
                    line = "";
                    int wordCount = 0;
                    int paragraphCount = 0;
                    string previousChapter;
                    priority_queue<pair<int, string>> chapterQueue;
                    priority_queue<pair<int, string>> paragraphQueue;

                    while (getline(bookFile, line)) {
                        int lineLength = line.length();
                        int wordLength = searchWord.length();
                        int remainingLength = lineLength - wordLength;
                        int occurrences = 0;

                        for (int l = 0; l < remainingLength; l++) {
                            if (line.compare(l, wordLength, searchWord) == 0) {
                                wordCount++;
                                occurrences++;
                            }
                        }
                        if (line.find("CHAPTER") != string::npos) {
                            if (chapterQueue.size() > 6) {
                                chapterQueue.pop();
                            }
                            if (line.find("CHAPTER 1") != string::npos) {
                                previousChapter = line;
                            } else {
                                chapterQueue.push(make_pair(-wordCount, previousChapter));
                                wordCount = 0;
                                previousChapter = line;
                            }
                        }
                        paragraphQueue.push(make_pair(-occurrences, line));
                        if (paragraphQueue.size() > 6) {
                            paragraphQueue.pop();
                        }
                    }

                    cout << "Do you want the paragraph or the chapter with the top 5 frequency?\nEnter P for Paragraph or C for Chapter: ";
                    char analysisChoice;
                    cin >> analysisChoice;

                    if (analysisChoice == 'p' || analysisChoice == 'P') {
                        while (paragraphQueue.size() > 5) {
                            paragraphQueue.pop();
                        }
                        for (int i = 5; i > 0; --i) {
                            cout << "At rank " << i << ":\n" << paragraphQueue.top().second << "\nwith " << -paragraphQueue.top().first << " repetitions of " << searchWord << endl;
                            paragraphQueue.pop();
                        }
                    } else if (analysisChoice == 'C' || analysisChoice == 'c') {
                        chapterQueue.pop();
                        for (int i = 5; i > 0; --i) {
                            cout << "At rank " << i << ":\n" << chapterQueue.top().second << "\nwith " << -chapterQueue.top().first << " repetitions of " << searchWord << endl;
                            chapterQueue.pop();
                        }
                    } else {
                        cout << "Invalid Input. Try again\n";
                    }
                    bookFile.close();
                } else {
                    cout << "Invalid book type input. Try again.\n";
                }
                break;

            case -1:
                cout << "Have a nice day!\n";
                break;

            default:
                cout << "Invalid input. Try again\n";
                break;
        }
    } while (userSelection != -1);

    return 0;
}

