#ifndef __MYCOMPLEX__

#define __MYCOMPLEX__

class Complex; 

Complex& AddAssign(Complex* instance, const Complex& value);
Complex& SubtractAssign(Complex* instance, const Complex& value);
Complex& MultiplyAssign(Complex* instance, const Complex& value);

class Complex
{
public:
    Complex(double realPart = 0, double imaginaryPart = 0) : re(realPart), im(imaginaryPart) { }

    Complex& operator += (const Complex&);
    Complex& operator -= (const Complex&);
    Complex& operator *= (const Complex&);
    Complex& operator /= (const Complex&);

    double real() const { return re; }
    double imag() const { return im; }

private:
    double re, im;

    friend Complex& AddAssign(Complex*, const Complex&);
    friend Complex& SubtractAssign(Complex*, const Complex&);
    friend Complex& MultiplyAssign(Complex*, const Complex&);
};

inline Complex& AddAssign(Complex* instance, const Complex& value)
{
    instance->re += value.re;
    instance->im += value.im;
    return *instance;
}

inline Complex& Complex::operator += (const Complex& value)
{
    return AddAssign(this, value);
}

inline Complex& SubtractAssign(Complex* instance, const Complex& value)
{
    instance->re -= value.re;
    instance->im -= value.im;
    return *instance;
}

inline Complex& Complex::operator -= (const Complex& value)
{
    return SubtractAssign(this, value);
}

inline Complex& MultiplyAssign(Complex* instance, const Complex& value)
{
    double realPart = instance->re * value.re - instance->im * value.im;
    instance->im = instance->re * value.im + instance->im * value.re;
    instance->re = realPart;
    return *instance;
}

inline Complex& Complex::operator *= (const Complex& value)
{
    return MultiplyAssign(this, value);
}

inline double imag(const Complex& number)
{
    return number.imag();
}

inline double real(const Complex& number)
{
    return number.real();
}

inline Complex operator + (const Complex& lhs, const Complex& rhs)
{
    return Complex(real(lhs) + real(rhs), imag(lhs) + imag(rhs));
}

inline Complex operator + (const Complex& lhs, double rhs)
{
    return Complex(real(lhs) + rhs, imag(lhs));
}

inline Complex operator + (double lhs, const Complex& rhs)
{
    return Complex(lhs + real(rhs), imag(rhs));
}

inline Complex operator - (const Complex& lhs, const Complex& rhs)
{
    return Complex(real(lhs) - real(rhs), imag(lhs) - imag(rhs));
}

inline Complex operator - (const Complex& lhs, double rhs)
{
    return Complex(real(lhs) - rhs, imag(lhs));
}

inline Complex operator - (double lhs, const Complex& rhs)
{
    return Complex(lhs - real(rhs), -imag(rhs));
}

inline Complex operator * (const Complex& lhs, const Complex& rhs)
{
    return Complex(real(lhs) * real(rhs) - imag(lhs) * imag(rhs),
                   real(lhs) * imag(rhs) + imag(lhs) * real(rhs));
}

inline Complex operator * (const Complex& lhs, double rhs)
{
    return Complex(real(lhs) * rhs, imag(lhs) * rhs);
}

inline Complex operator * (double lhs, const Complex& rhs)
{
    return Complex(lhs * real(rhs), lhs * imag(rhs));
}

Complex operator / (const Complex& lhs, double rhs)
{
    return Complex(real(lhs) / rhs, imag(lhs) / rhs);
}

inline Complex operator + (const Complex& number)
{
    return number;
}

inline Complex operator - (const Complex& number)
{
    return Complex(-real(number), -imag(number));
}

inline bool operator == (const Complex& lhs, const Complex& rhs)
{
    return real(lhs) == real(rhs) && imag(lhs) == imag(rhs);
}

inline bool operator == (const Complex& lhs, double rhs)
{
    return real(lhs) == rhs && imag(lhs) == 0;
}

inline bool operator == (double lhs, const Complex& rhs)
{
    return lhs == real(rhs) && imag(rhs) == 0;
}

inline bool operator != (const Complex& lhs, const Complex& rhs)
{
    return real(lhs) != real(rhs) || imag(lhs) != imag(rhs);
}

inline bool operator != (const Complex& lhs, double rhs)
{
    return real(lhs) != rhs || imag(lhs) != 0;
}

inline bool operator != (double lhs, const Complex& rhs)
{
    return lhs != real(rhs) || imag(rhs) != 0;
}

#include <cmath>

inline Complex polar(double magnitude, double angle)
{
    return Complex(magnitude * cos(angle), magnitude * sin(angle));
}

inline Complex conj(const Complex& number) 
{
    return Complex(real(number), -imag(number));
}

inline double norm(const Complex& number)
{
    return real(number) * real(number) + imag(number) * imag(number);
}

