#ifndef __MYSTRING__

#define __MYSTRING__

class String
{
public:                                 
   // Constructor initializes the string from a C-style string or creates an empty string
   String(const char* cstr = nullptr);                     

   // Copy constructor for deep copying another String object
   String(const String& str);                    

   // Assignment operator for deep copying another String object
   String& operator=(const String& str);         

   // Destructor to free allocated memory
   ~String();                                    

   // Returns the underlying C-style string
   char* get_c_str() const { return m_data; }

private:
   char* m_data; // Pointer to dynamically allocated character array
};

#include <cstring>

inline
String::String(const char* cstr)
{
   if (cstr) {
      // Allocate memory and copy the provided C-style string
      m_data = new char[strlen(cstr) + 1];
      strcpy(m_data, cstr);
   } else {   
      // Allocate memory for an empty string
      m_data = new char[1];
      *m_data = '\0';
   }
}

inline
String::~String()
{
   // Release the allocated memory
   delete[] m_data;
}

inline
String& String::operator=(const String& str)
{
   if (this == &str)
      return *this; // Handle self-assignment

   // Release existing memory and allocate new memory for the copied string
   delete[] m_data;
   m_data = new char[strlen(str.m_data) + 1];
   strcpy(m_data, str.m_data);
   return *this;
}

inline
String::String(const String& str)
{
   // Allocate memory and copy the string from another String object
   m_data = new char[strlen(str.m_data) + 1];
   strcpy(m_data, str.m_data);
}

#include <iostream>
using namespace std;

// Overload the output stream operator for String objects
ostream& operator<<(ostream& os, const String& str)
{
   os << str.get_c_str();
   return os;
}

