#include <iostream>
#include <iomanip>
using namespace std;

class Node {
public:
    int status; // 0 for available, 1 for booked
    Node* next;    
    Node* prev;

    Node() {
        status = 0; // Initialize status to available
        next = nullptr;
        prev = nullptr;
    }

    friend class TicketBookingSystem;
};

class TicketBookingSystem {
    Node* rowHead[10];
    Node* rowLast[10];

public:
    TicketBookingSystem() {
        // Initialize the linked list for each row
        for (int i = 0; i < 10; i++) {
            rowHead[i] = rowLast[i] = nullptr;
            for (int j = 0; j < 7; j++) {
                Node* newNode = new Node();
                if (rowHead[i] == nullptr) {
                    // First node in the list
                    rowHead[i] = newNode;
                    rowLast[i] = newNode;
                    rowHead[i]->next = rowHead[i];
                    rowHead[i]->prev = rowHead[i];
                } else {
                    // Append new node to the end of the list
                    Node* temp = rowHead[i];
                    while (temp->next != rowHead[i]) {
                        temp = temp->next;
                    }
                    temp->next = newNode;
                    newNode->prev = temp;
                    newNode->next = rowHead[i];
                    rowLast[i] = newNode;
                    rowHead[i]->prev = rowLast[i];
                }
            }
        }
    }

    void displayAvailableSeats() {
        cout << "ROW/COL";
        for (int i = 1; i <= 7; i++) {
            cout << setw(8) << i;
        }
        cout << endl;

        for (int i = 0; i < 10; i++) {
            Node* ptr = rowHead[i];
            cout << "ROW-" << setw(3) << (i + 1);
            do {
                cout << setw(8) << (ptr->status == 0 ? "0" : "1");
                ptr = ptr->next;
            } while (ptr != rowHead[i]);
            cout << endl;
        }
    }

    void bookSeat() {
        int row, col;
        cout << "Enter The Row (1-10): ";
        cin >> row;
        cout << "Enter The Col (1-7): ";
        cin >> col;

        if (row < 1 || row > 10 || col < 1 || col > 7) {
            cout << "Invalid Choice!" << endl;
            return;
        }

        Node* ptr = rowHead[row - 1];
        for (int j = 1; j < col; j++) {
            ptr = ptr->next;
        }

        if (ptr->status == 1) {
            cout << "\nTicket Is Already Booked!" << endl;
        } else {
            ptr->status = 1; // Mark as booked
            cout << "\n\nTicket Booked Successfully!\n" << endl;
        }
    }

    void cancelBooking() {
        int row, col;
        cout << "Enter The Row (1-10): ";
        cin >> row;
        cout << "Enter The Col (1-7): ";
        cin >> col;

        if (row < 1 || row > 10 || col < 1 || col > 7) {
            cout << "Invalid Choice!" << endl;
            return;
        }

        Node* ptr = rowHead[row - 1];
        for (int j = 1; j < col; j++) {
            ptr = ptr->next;
        }

        if (ptr->status == 0) {
            cout << "\n\nTicket Is Not Booked Yet!" << endl;
        } else {
            ptr->status = 0; // Mark as available
            cout << "\n\nTicket Cancellation Successfully!\n" << endl;
        }
    }
};

