class BankAccount {
protected:
    string customerName;
    string dateOfBirth;
    int accountNumber;
    int nationalID;

public:
    int withdrawalCount;
    float monthlyTotalInterest;
    float depositAmount;
    float withdrawalAmount;
    float totalWithdrawnAmount;
    float currentBalance;
    int depositDay;
    int depositAmountInt;
    int withdrawalDay;
    int validDays;
    float dailyInterestBeforeWithdrawal;
    float dailyInterestAfterWithdrawal;
    float monthlyInterest;
    float totalBalance;

    void setCustomerDetails(const string& name, const string& dob, int accNo, int natID) {
        customerName = name;
        dateOfBirth = dob;
        accountNumber = accNo;
        nationalID = natID;
    }

    float depositMoney() {
        cout << "Enter the amount to deposit: " << endl;
        cin >> depositAmount;
        return depositAmount;
    }

    float withdrawMoney() {
        cout << "Enter the amount to withdraw: " << endl;
        cin >> withdrawalAmount;
        return withdrawalAmount;
    }

    float checkBalance() {
        currentBalance = depositAmountInt - withdrawalAmount;
        return currentBalance;
    }

    int setDepositDay() {
        cout << "Enter the deposit day: " << endl;
        cin >> depositDay;
        return depositDay;
    }

    int setWithdrawalDay() {
        cout << "Enter the withdrawal day: " << endl;
        cin >> withdrawalDay;
        return withdrawalDay;
    }

    int calculateValidDays() {
        validDays = withdrawalDay - depositDay;
        return validDays;
    }

    float calculateDailyInterestBeforeWithdrawal() {
        dailyInterestBeforeWithdrawal = (depositAmountInt * 0.033) / 100;
        return dailyInterestBeforeWithdrawal;
    }

    float calculateDailyInterestAfterWithdrawal() {
        dailyInterestAfterWithdrawal = (currentBalance * 0.033) / 100;
        return dailyInterestAfterWithdrawal;
    }

    float calculateMonthlyInterest() {
        monthlyInterest = (dailyInterestBeforeWithdrawal * validDays) + 
                          (dailyInterestAfterWithdrawal * ((30 - withdrawalDay) + 1));
        return monthlyInterest;
    }

    float performCalculations() {
        cout << "How many times will you withdraw money? " << endl;
        cin >> withdrawalCount;
        monthlyTotalInterest = 0;
        depositAmountInt = depositAmount;

        for (int i = 0; i < withdrawalCount; ++i) {
            withdrawMoney();
            checkBalance();
            setWithdrawalDay();
            calculateValidDays();
            calculateDailyInterestBeforeWithdrawal();
            calculateDailyInterestAfterWithdrawal();
            calculateMonthlyInterest();
            monthlyTotalInterest += monthlyInterest;
            depositAmountInt = currentBalance;
            depositDay = withdrawalDay;
        }

        totalWithdrawnAmount = depositAmount - currentBalance;
        return totalWithdrawnAmount;
    }

    float calculateTotalBalance() {
        totalBalance = currentBalance + monthlyTotalInterest;
        return totalBalance;
    }
};

