#include "Book.h"

class Book {
    static const int STATE_AVAILABLE = 1; // Indicates the book is available for issue
    static const int STATE_ISSUED = 2;    // Indicates all copies are issued, no claims
    static const int STATE_CLAIMED = 3;    // Indicates there are claims on the book

    long unsigned int book_id;
    int state;
    unsigned int copies;
    string title;
    string author;
    string publisher;

    list<Issue> issue_list;
    list<Claim> claim_list;

public:
    Book() : book_id(0), copies(0), title(""), author(""), publisher("") {}

    Book(int id, string book_title, string book_author, string book_publisher, int num_copies, int current_state = STATE_AVAILABLE, list<Issue> issues = {}, list<Claim> claims = {})
        : book_id(id), title(book_title), author(book_author), publisher(book_publisher), copies(num_copies), state(current_state), issue_list(issues), claim_list(claims) {}

    Book(const Book &original) 
        : book_id(original.book_id), title(original.title), author(original.author), publisher(original.publisher), copies(original.copies), state(original.state), issue_list(original.issue_list), claim_list(original.claim_list) {}

    long unsigned int getBookId() const {
        return book_id;
    }

    void setBookId(long unsigned int id) {
        book_id = id;
    }

    string getTitle() const {
        return title;
    }

    void setTitle(string book_title) {
        title = book_title;
    }

    string getAuthor() const {
        return author;
    }

    void setAuthor(string book_author) {
        author = book_author;
    }

    string getPublisher() const {
        return publisher;
    }

    void setPublisher(string book_publisher) {
        publisher = book_publisher;
    }

    int getState() {
        updateState();
        return state;
    }

    void setState(int current_state) {
        state = current_state;
    }

    unsigned int getCopies() const {
        return copies;
    }

    void setCopies(int num_copies) {
        copies = num_copies;
    }

    list<Issue> getIssueList() const {
        return issue_list;
    }

    void setIssueList(list<Issue> issues) {
        issue_list = issues;
    }

    list<Claim> getClaimList() const {
        return claim_list;
    }

    void setClaimList(list<Claim> claims) {
        claim_list = claims;
    }

    void updateState() {
        if (!claim_list.empty()) {
            state = STATE_CLAIMED;
        } else if (issue_list.size() < copies) {
            state = STATE_AVAILABLE;
        } else {
            state = STATE_ISSUED;
        }
    }

    void display() const {
        cout << book_id << " : " << title << endl;
        cout << "Written by: " << author << endl;
        cout << "Published by: " << publisher << endl;
        cout << "Total number of copies: " << copies << endl;

        switch (state) {
            case STATE_AVAILABLE:
                cout << (copies - issue_list.size()) << " copies are available." << endl;
                if (!issue_list.empty()) {
                    cout << "Users who have issued this book:" << endl;
                    for (const auto& issue : issue_list) {
                        issue.display();
                    }
                }
                break;

            case STATE_ISSUED:
                cout << "Users who have issued this book:" << endl;
                for (const auto& issue : issue_list) {
                    issue.display();
                }
                break;

            case STATE_CLAIMED:
                cout << "Users who have issued this book:" << endl;
                for (const auto& issue : issue_list) {
                    issue.display();
                }
                cout << "Users who have claimed this book:" << endl;
                for (const auto& claim : claim_list) {
                    claim.display();
                }
                break;
        }
    }
};

