class Claim {
    Date claimDate;
    Book associatedBook;
    User claimantUser;

public:
    // Default constructor initializes member variables to null
    Claim() : claimDate(NULL), associatedBook(NULL), claimantUser(NULL) {}

    // Parameterized constructor for initializing with specific values
    Claim(Date claimDate, Book associatedBook, User claimantUser) 
        : claimDate(claimDate), associatedBook(associatedBook), claimantUser(claimantUser) {}

    // Copy constructor for creating a duplicate of an existing Claim object
    Claim(const Claim &original) 
        : claimDate(original.claimDate), associatedBook(original.associatedBook), claimantUser(original.claimantUser) {}

    // Retrieve the claim date
    Date getClaimDate() const {
        return claimDate;
    }

    // Set a new claim date
    void setClaimDate(Date claimDate) {
        this->claimDate = claimDate;
    }

    // Retrieve the associated book
    Book getBook() const {
        return associatedBook;
    }

    // Set a new associated book
    void setBook(Book associatedBook) {
        this->associatedBook = associatedBook;
    }

    // Retrieve the claimant user
    User getUser() const {
        return claimantUser;
    }

    // Set a new claimant user
    void setUser(User claimantUser) {
        this->claimantUser = claimantUser;
    }

    // Check if the claim is still valid based on the current date
    bool isValid() const {
        Date currentDate = Date.getInstance();
        return !(claimDate == NULL || currentDate > claimDate + 4);
    }

    // Display claim details and its status
    void display() const {
        cout << associatedBook.getTitle() << " claimed by " << claimantUser.getName() << endl;

        if (claimDate == NULL) {
            list<Claim> claimList = associatedBook.getClaimList();
            auto it = find(claimList.begin(), claimList.end(), *this);
            int position = distance(claimList.begin(), it) + 1;
            string suffix;

            // Determine the appropriate suffix for the claim position
            switch (position) {
                case 1: suffix = "st"; break;
                case 2: suffix = "nd"; break;
                case 3: suffix = "rd"; break;
                default: suffix = "th"; break;
            }
            cout << "The claim is " + to_string(position) + suffix + " in the queue." << endl;
            return;
        }

        // Display validity status of the claim
        if (isValid()) {
            cout << "The claim is valid for " << (claimDate - Date.getInstance() + 4) << " more days" << endl;
        } else {
            cout << "The claim has expired." << endl;
        }
    }
};

#include "Date.h"
#include <ctime>

class Date {
    unsigned int day;
    unsigned int month;
    unsigned int year;

public:
    // Default constructor initializes the date to zero
    Date() : day(0), month(0), year(0) {}

    // Parameterized constructor for setting specific date values
    Date(unsigned int day, unsigned int month, unsigned int year) : day(day), month(month), year(year) {}

    // Copy constructor for creating a new Date instance from an existing one
    Date(const Date &original) : day(original.day), month(original.month), year(original.year) {}

    // Accessor for day
    unsigned int getDay() const {
        return day;
    }

    // Mutator for day
    void setDay(unsigned int day) {
        this->day = day;
    }

    // Accessor for month
    unsigned int getMonth() const {
        return month;
    }

    // Mutator for month
    void setMonth(unsigned int month) {
        this->month = month;
    }

    // Accessor for year
    unsigned int getYear() const {
        return year;
    }

    // Mutator for year
    void setYear(unsigned int year) {
        this->year = year;
    }

    // Creates a Date instance representing the current date
    static Date getCurrentDate() {
        time_t currentTime = time(0);
        struct tm *now = localtime(&currentTime);
        return Date(now->tm_mday, now->tm_mon + 1, now->tm_year + 1900);
    }

    // Returns the number of days in a given month of a specific year
    static unsigned int getDaysInMonth(unsigned int month, unsigned int year) {
        int daysInMonth = 0;
        switch (month) {
            case 1: case 3: case 5: case 7: case 8: case 10: case 12:
                daysInMonth = 31;
                break;
            case 4: case 6: case 9: case 11:
                daysInMonth = 30;
                break;
            case 2:
                daysInMonth = ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) ? 29 : 28;
                break;
        }
        return daysInMonth;
    }

    // Validates the current date
    bool isValid() const {
        return !(year < 0 || month < 1 || month > 12 || day < 1 || day > getDaysInMonth(month, year));
    }

    // Adjusts the date if it is invalid
    void validate() {
        if (isValid()) return;

        if (day < 0) {
            month = (month == 1) ? 12 : month - 1;
            int daysInPreviousMonth = getDaysInMonth(month, year);
            day += daysInPreviousMonth;
        } else {
            int daysInCurrentMonth = getDaysInMonth(month, year);
            day -= daysInCurrentMonth;
            month = (month == 12) ? 1 : month + 1;
        }
        validate();
    }

    // Adds a number of days to the current date
    Date operator+(unsigned int daysToAdd) const {
        Date newDate(*this);
        newDate.day += daysToAdd;
        newDate.validate();
        return newDate;
    }

    // Subtracts a number of days from the current date
    Date operator-(unsigned int daysToSubtract) const {
        Date newDate(*this);
        newDate.day -= daysToSubtract;
        newDate.validate();
        return newDate;
    }

    // Calculates the difference in days between two dates
    int operator-(const Date &other) const {
        Date currentDate(*this);
        if (currentDate < other) {
            return -1 * (other - currentDate);
        }
        if (currentDate.year == other.year && currentDate.month == other.month) {
            return currentDate.day - other.day;
        }
        int previousMonth = (currentDate.month == 1) ? 12 : currentDate.month - 1;
        int daysInPreviousMonth = getDaysInMonth(previousMonth, currentDate.year);
        return daysInPreviousMonth + ((currentDate - daysInPreviousMonth) - other);
    }

    // Checks if two dates are equal
    bool operator==(const Date &other) const {
        return (year == other.year && month == other.month && day == other.day);
    }

    // Checks if two dates are not equal
    bool operator!=(const Date &other) const {
        return !(*this == other);
    }

    // Checks if the current date is greater than another date
    bool operator>(const Date &other) const {
        if (year > other.year) return true;
        if (year < other.year) return false;
        if (month > other.month) return true;
        if (month < other.month) return false;
        return day > other.day;
    }

    // Checks if the current date is greater than or equal to another date
    bool operator>=(const Date &other) const {
        return (*this == other || *this > other);
    }

    // Checks if the current date is less than another date
    bool operator<(const Date &other) const {
        return !(*this >= other);
    }

    // Checks if the current date is less than or equal to another date
    bool operator<=(const Date &other) const {
        return !(*this > other);
    }
};

