class Issue {
    Date issueDate;
    Date dueDate;
    float fineAmount;
    Book issuedBook;
    User issuingUser;

public:
    // Default constructor initializes member variables to default values
    Issue() 
        : issueDate(), dueDate(), fineAmount(0), issuedBook(), issuingUser() {}

    // Parameterized constructor for initializing with specific values
    Issue(Date issueDate, Date dueDate, float fineAmount, Book issuedBook, User issuingUser) 
        : issueDate(issueDate), dueDate(dueDate), fineAmount(fineAmount), issuedBook(issuedBook), issuingUser(issuingUser) {}

    // Copy constructor for creating a copy of an existing Issue object
    Issue(const Issue &original) 
        : issueDate(original.issueDate), dueDate(original.dueDate), fineAmount(original.fineAmount), issuedBook(original.issuedBook), issuingUser(original.issuingUser) {}

    // Retrieves the issue date of the book
    Date getIssueDate() const {
        return issueDate;
    }

    // Sets the issue date of the book
    void setIssueDate(Date issueDate) {
        this->issueDate = issueDate;
    }

    // Retrieves the due date for returning the book
    Date getDueDate() const {
        return dueDate;
    }

    // Sets the due date for returning the book
    void setDueDate(Date dueDate) {
        this->dueDate = dueDate;
    }

    // Calculates and retrieves the fine amount if applicable
    float getFine() {
        calculateFine();
        return fineAmount;
    }

    // Sets the fine amount directly
    void setFine(float fineAmount) {
        this->fineAmount = fineAmount;
    }

    // Retrieves the book associated with this issue
    Book getBook() const {
        return issuedBook;
    }

    // Sets the book associated with this issue
    void setBook(Book issuedBook) {
        this->issuedBook = issuedBook;
    }

    // Retrieves the user associated with this issue
    User getUser() const {
        return issuingUser;
    }

    // Sets the user associated with this issue
    void setUser(User issuingUser) {
        this->issuingUser = issuingUser;
    }

    // Calculates the fine based on the current date and due date
    void calculateFine() {
        Date currentDate = Date.getInstance();
        if (currentDate <= dueDate) {
            return;
        }
        fineAmount = (currentDate - dueDate) * 5;
    }

    // Displays the details of the issued book and associated user
    void display() const {
        cout << issuedBook.getTitle() << " issued by " << issuingUser.getName() << endl;
        if (issueDate.isValid()) {
            cout << "Issue Date: " << issueDate << endl;
        }
        if (dueDate.isValid()) {
            cout << "Due Date: " << dueDate << endl;
        }
        cout << "Fine: " << fineAmount << " INR" << endl;
    }
};

