        std::cout << "Successfully written to the databases!" << std::endl;
    } else {
        std::cerr << "Error writing to the databases!" << std::endl;
    }
}

// Loads the database into a vector and initializes hashmaps for quick access
bool Library::loadDatabase(const std::string& filename) {
    std::ifstream file(filename);
    if (file.fail()) {
        std::cerr << "Error opening file!" << std::endl;
        exit(1);
    }

    std::string line;
    while (std::getline(file, line)) {
        std::stringstream lineStream(line);
        std::vector<std::string> bookAttributes(kNumberOfAttributesInFile);
        int index = 0;

        // Populate book attributes from the CSV line
        while (std::getline(lineStream, bookAttributes[index], ',')) {
            index++;
        }

        Book book = vectorToBook(bookAttributes);
        books_.push_back(book);

        // Insert into hashmaps for efficient searching
        booksByTitle_.emplace(book.title, book);
        booksByAuthor_.emplace(book.author, book);
        booksByPublisher_.emplace(book.publisher, book);
    }
    file.close();
    return true;
}

// Converts a vector of strings into a Book object
Book Library::vectorToBook(const std::vector<std::string>& bookVector) {
    return Book(std::stoi(bookVector[0]), bookVector[1], bookVector[2], bookVector[3], std::stoi(bookVector[4]), std::stoi(bookVector[5]));
}

// Writes the current state of the database to a file
bool Library::updateDatabase(const std::string& filename) {
    std::ofstream file(filename);
    if (file.fail()) {
        std::cerr << "Error opening the file!" << std::endl;
        exit(1);
    }

    for (const auto& book : books_) {
        file << book.book_id << ',' << book.title << ',' << book.author << ',' 
             << book.publisher << ',' << book.copies << ',' << book.state << std::endl;
    }

    file.close();
    return true;
}

// Searches for a book by author and returns a pointer to it if found
Book* Library::searchBookByAuthor(const std::string& author) {
    auto it = booksByAuthor_.find(author);
    return (it != booksByAuthor_.end()) ? &(it->second) : nullptr;
}

// Searches for a book by book ID and returns a pointer to it if found
Book* Library::searchBookByBookId(unsigned int bookId) {
    return (bookId < books_.size()) ? &books_[bookId] : nullptr;
}

// Searches for a book by title and returns a pointer to it if found
Book* Library::searchBookByTitle(const std::string& title) {
    auto it = booksByTitle_.find(title);
    return (it != booksByTitle_.end()) ? &(it->second) : nullptr;
}

// Searches for a book by publisher and returns a pointer to it if found
Book* Library::searchBookByPublisher(const std::string& publisher) {
    auto it = booksByPublisher_.find(publisher);
    return (it != booksByPublisher_.end()) ? &(it->second) : nullptr;
}

// Adds a book to the database, incrementing copies if it already exists
bool Library::addBook(const std::string& title, const std::string& publisher, const std::string& author) {
    Book* existingBook = searchBookByTitle(title);
    if (existingBook) {
        existingBook->setCopies(existingBook->getCopies() + 1);
    } else {
        books_.emplace_back(Book(title, publisher, author));
        unsigned int newBookId = books_.size();
        books_.back().setBookId(newBookId);
    }
    return true;
}

// Deletes a book by decrementing its copies, if available
bool Library::deleteBook(Book* book) {
    if (book->getCopies() > 0) {
        book->setCopies(book->getCopies() - 1);
        return true;
    }
    std::cerr << "The book has already been removed!" << std::endl;
    return false;
}

