const int monthDays[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

int countLeapYears(const Date& date) {
    int years = date.year;
    if (date.month <= 2) {
        years--;
    }
    return years / 4 - years / 100 + years / 400;
}

int calculateDateDifference(const Date& startDate, const Date& endDate) {
    long int startDays = startDate.year * 365 + startDate.day;
    for (int i = 0; i < startDate.month - 1; i++) {
        startDays += monthDays[i];
    }
    startDays += countLeapYears(startDate);

    long int endDays = endDate.year * 365 + endDate.day;
    for (int i = 0; i < endDate.month - 1; i++) {
        endDays += monthDays[i];
    }
    endDays += countLeapYears(endDate);

    return (endDays - startDays);
}

bool isRollNumberValid(const string& rollNumber) {
    int firstSlashIndex = rollNumber.find('/');
    int secondSlashIndex = rollNumber.find('/', firstSlashIndex + 1);
    int length = rollNumber.length();

    if (firstSlashIndex == string::npos || secondSlashIndex == string::npos || length - secondSlashIndex != 3) {
        cout << "Invalid roll number format. Expected format: <ints<=3>/<dept_code>/<2xint>" << endl;
        return false;
    }

    for (int i = 0; i < firstSlashIndex; i++) {
        if (!isdigit(rollNumber[i])) {
            cout << "Invalid roll number format. Expected format: <ints<=3>/<dept_code>/<2xint>" << endl;
            return false;
        }
    }

    for (int i = firstSlashIndex + 1; i < secondSlashIndex; i++) {
        if (!isupper(rollNumber[i])) {
            cout << "Invalid roll number format. Expected format: <ints<=3>/<dept_code>/<2xint>" << endl;
            return false;
        }
    }

    for (int i = secondSlashIndex + 1; i < length; i++) {
        if (!isdigit(rollNumber[i])) {
            cout << "Invalid roll number format. Expected format: <ints<=3>/<dept_code>/<2xint>" << endl;
            return false;
        }
    }

    if (rollNumber[length - 2] != '1' || rollNumber[length - 1] < '1' || rollNumber[length - 1] > '5') {
        cout << "Invalid year of admission." << endl;
        return false;
    }

    return true;
}

bool isISBNValid(const string& isbn) {
    int length = isbn.length();
    if (length != 10 && length != 13) {
        cout << "Invalid ISBN format. ISBN must be 10 or 13 digits." << endl;
        return false;
    }

    for (char c : isbn) {
        if (!isdigit(c)) {
            cout << "Invalid ISBN format. ISBN must be numeric." << endl;
            return false;
        }
    }

    return true;
}

bool isStringValid(const string& input) {
    for (char c : input) {
        if (!isalpha(c) && c != ' ' && c != '.') {
            cout << "Input can only contain alphabets, spaces, or dots." << endl;
            return false;
        }
    }
    return true;
}

string extractBranchFromRollNumber(const string& rollNumber) {
    int firstSlashIndex = rollNumber.find('/');
    int secondSlashIndex = rollNumber.find('/', firstSlashIndex + 1);
    string branchCode = rollNumber.substr(firstSlashIndex + 1, secondSlashIndex - firstSlashIndex - 1);

    if (branchCode == "CO") return "COE";
    if (branchCode == "EC") return "ECE";
    if (branchCode == "IT") return "IT";
    if (branchCode == "MP") return "MPAE";
    if (branchCode == "IC") return "ICE";
    if (branchCode == "BT") return "BT";

    cout << "Invalid branch code in roll number." << endl;
    return "no";
}

void StudentManager::addStudent() {
    string rollNumber;
    while (true) {
        cout << "Enter student roll number:" << endl;
        cin >> rollNumber;

        if (!isRollNumberValid(rollNumber)) continue;

        string branch = extractBranchFromRollNumber(rollNumber);
        if (branch == "no") continue;

        for (const auto& student : students) {
            if (rollNumber == student.rollNumber) {
                cout << "This roll number already exists. Please try again." << endl;
                continue;
            }
        }

        string name;
        cout << "Enter student name:" << endl;
        cin.ignore();
        getline(cin, name);
        if (!isStringValid(name)) continue;

        Student newStudent;
        newStudent.branch = branch;
        newStudent.name = name;
        newStudent.rollNumber = rollNumber;
        newStudent.issuedBooksCount = 0;
        newStudent.fineAmount = 0;
        newStudent.totalReturns = 0;
        fill(begin(newStudent.issuedBooks), end(newStudent.issuedBooks), nullptr);

        students.push_back(newStudent);
        studentCount++;
        cout << "Student added successfully." << endl;
        break;
    }
}

void StudentManager::deleteStudent() {
    string rollNumber;
    cout << "Enter the roll number of the student you want to delete:" << endl;
    cin >> rollNumber;

    auto it = find_if(students.begin(), students.end(), [&](const Student& student) {
        return student.rollNumber == rollNumber;
    });

    if (it != students.end()) {
        Student& studentToDelete = *it;
        if (studentToDelete.issuedBooksCount == 0 && studentToDelete.fineAmount == 0) {
            cout << "Student has no issued books and has been successfully removed from the database." << endl;
            students.erase(it);
            studentCount--;
        } else if (studentToDelete.fineAmount != 0) {
            cout << "Student has a fine of Rs. " << studentToDelete.fineAmount << ". Please pay the fine before removal." << endl;
        } else {
            cout << "Student has issued books. Please return them before removal." << endl;
        }
    } else {
        cout << "No student with the given roll number is present in the database." << endl;
    }
}

int absoluteValue(int number) {
    return (number < 0) ? -number : number;
}

void Library::addBook() {
    string isbn;
    cout << "Enter the ISBN for the book you want to enter:" << endl;
    cin >> isbn;

    if (!isISBNValid(isbn)) return;

    auto it = find_if(books.begin(), books.end(), [&](const Book& book) {
        return book.isbn == isbn;
    });

    if (it != books.end()) {
        int quantity;
        cout << "How many copies are to be added for this ISBN?" << endl;
        cin >> quantity;

        for (int k = 1; k <= quantity; k++) {
            it->bookIds.insert(it->maxBookId + k);
        }
        it->totalCopies += quantity;
        it->maxBookId += quantity;
        it->availableCopies += quantity;

        cout << "Books added successfully. New book IDs range from " << (it->maxBookId - quantity + 1) << " to " << it->maxBookId << "." << endl;
    } else {
        Book newBook;
        cout << "Please provide the following details:" << endl;
        cout << "Number of authors:" << endl;
        int authorCount;
        cin >> authorCount;
        authorCount = absoluteValue(authorCount);
        newBook.authorCount = authorCount;

        cin.ignore();
        for (int i = 0; i < authorCount; i++) {
            string authorName;
            cout << "Enter author name:" << endl;
            getline(cin, authorName);
            if (!isStringValid(authorName)) return;
            newBook.authors.push_back(authorName);
        }

        while (true) {
            cout << "Please enter the category of the book (1: Literature, 2: Textbook, 3: General awareness, 4: Misc.):" << endl;
            int category;
            cin >> category;
            if (category < 1 || category > 4) {
                cout << "Not a valid category. Please try again." << endl;
                continue;
            }
            newBook.category = category;
            break;
        }

        cout << "Please enter the name of the publication:" << endl;
        cin.ignore();
        string publicationName;
        getline(cin, publicationName);
        if (!isStringValid(publicationName)) return;
        newBook.publication = publicationName;

        cout << "Please enter the title of the book:" << endl;
        string bookTitle;
        getline(cin, bookTitle);
        if (!isStringValid(bookTitle)) return;
        newBook.title = bookTitle;

        cout << "How many copies are to be added for this ISBN?" << endl;
        int quantity;
        cin >> quantity;
        for (int k = 1; k <= quantity; k++) {
            newBook.bookIds.insert(k);
        }
        newBook.totalCopies = newBook.availableCopies = newBook.maxBookId = quantity;
        newBook.isbn = isbn;

        books.push_back(newBook);
        totalBooks++;
        cout << "Books successfully added." << endl;
    }
}

void Library::deleteBook() {
    string isbn;
    cout << "Enter the ISBN of the book you want to delete:" << endl;
    cin >> isbn;

    auto it = find_if(books.begin(), books.end(), [&](const Book& book) {
        return book.isbn == isbn;
    });

    if (it != books.end()) {
        int bookId;
        cout << "Enter the book ID you want to delete:" << endl;
        cin >> bookId;

        auto bookIdIt = it->bookIds.find(bookId);
        if (bookIdIt != it->bookIds.end()) {
            it->bookIds.erase(bookIdIt);
            it->totalCopies--;
            it->availableCopies--;
            cout << "Book has been successfully deleted." << endl;
        } else {
            cout << "The book ID does not exist in the library." << endl;
        }
    } else {
        cout << "Provided ISBN does not exist. Please try again." << endl;
    }
}

void StudentManager::issueBook(Library& library) {
    string rollNumber;
    cout << "Enter the roll number of the student who wants to issue a book:" << endl;
    cin >> rollNumber;

    auto it = find_if(students.begin(), students.end(), [&](const Student& student) {
        return student.rollNumber == rollNumber;
    });

    if (it != students.end()) {
        if (it->issuedBooksCount >= 5) {
            cout << "Student has already issued 5 books. No more books can be issued." << endl;
            return;
        }

        string isbn;
        cout << "Enter the ISBN of the book:" << endl;
        cin >> isbn;

        auto bookIt = find_if(library.books.begin(), library.books.end(), [&](const Book& book) {
            return book.isbn == isbn;
        });

        if (bookIt != library.books.end()) {
            int bookId;
            cout << "Enter the book ID:" << endl;
            cin >> bookId;

            auto bookIdIt = bookIt->bookIds.find(bookId);
            if (bookIdIt != bookIt->bookIds.end()) {
                time_t now = time(0);
                bookIt->availableCopies--;
                bookIt->bookIds.erase(bookIdIt);
                it->issuedBooksCount++;

                int index = 0;
                while (it->issuedBooks[index] != nullptr && index < 5) {
                    index++;
                }

                it->issuedBooks[index] = new IssueReturn;
                it->issuedBooks[index]->issueDate = localtime(&now);
                it->issuedBooks[index]->isbn = bookIt->isbn;
                it->issuedBooks[index]->bookId = bookId;

                cout << "Book successfully issued on " << it->issuedBooks[index]->issueDate->tm_mday << "-" 
                     << it->issuedBooks[index]->issueDate->tm_mon + 1 << "-" 
                     << it->issuedBooks[index]->issueDate->tm_year + 1900 << endl;
            } else {
                cout << "The book ID is not available in the library." << endl;
            }
        } else {
            cout << "No book with the given ISBN is present in the library." << endl;
        }
    } else {
        cout << "No student with this roll number exists." << endl;
    }
}

void StudentManager::returnBook(Library& library) {
    string rollNumber;
    cout << "Enter the roll number of the student returning the book:" << endl;
    cin >> rollNumber;

    auto it = find_if(students.begin(), students.end(), [&](const Student& student) {
        return student.rollNumber == rollNumber;
    });

    if (it != students.end()) {
        if (it->issuedBooksCount == 0) {
            cout << "This student has no books issued." << endl;
            return;
        }

        int issuedBookCount = 0;
        for (int k = 0; k < 5; k++) {
            if (it->issuedBooks[k] != nullptr) {
                issuedBookCount++;
                cout << issuedBookCount << ".) ISBN: " << it->issuedBooks[k]->isbn 
                     << ", Book ID: " << it->issuedBooks[k]->bookId << endl;
            }
        }

        int bookIndex;
        cout << "Enter the index number of the book the student is returning:" << endl;
        cin >> bookIndex;

        if (bookIndex > issuedBookCount || bookIndex <= 0) {
            cout << "Invalid entry. Please try again." << endl;
            return;
        }

        int actualIndex = bookIndex - 1;
        string isbn = it->issuedBooks[actualIndex]->isbn;

        auto bookIt = find_if(library.books.begin(), library.books.end(), [&](const Book& book) {
            return book.isbn == isbn;
        });

        if (bookIt != library.books.end()) {
            time_t now = time(0);
            ReturnRecord returnRecord;
            returnRecord.rollNumber = it->rollNumber;
            returnRecord.bookId = it->issuedBooks[actualIndex]->bookId;
            returnRecord.isbn = bookIt->isbn;
            returnRecord.returnDate = localtime(&now);
            returnRecord.issueDate = it->issuedBooks[actualIndex]->issueDate;

            Date issueDate, returnDate;
            issueDate.day = it->issuedBooks[actualIndex]->issueDate->tm_mday;
            issueDate.month = it->issuedBooks[actualIndex]->issueDate->tm_mon + 1;
            issueDate.year = it->issuedBooks[actualIndex]->issueDate->tm_year + 1900;

            returnDate.day = returnRecord.returnDate->tm_mday;
            returnDate.month = returnRecord.returnDate->tm_mon + 1;
            returnDate.year = returnRecord.returnDate->tm_year + 1900;

            int daysLate = calculateDateDifference(issueDate, returnDate);
            if (bookIt->category == 2) {
                if (daysLate > 20) {
                    returnRecord.fine = (daysLate - 20) * 5;
                    it->fineAmount += returnRecord.fine;
                    cout << "Book returned successfully with a fine of Rs. " << returnRecord.fine << endl;
                } else {
                    returnRecord.fine = 0;
                    cout << "Book returned successfully without any fine." << endl;
                }
            } else {
                if (daysLate > 14) {
                    returnRecord.fine = (daysLate - 14) * 5;
                    it->fineAmount += returnRecord.fine;
                    cout << "Book returned successfully with a fine of Rs. " << returnRecord.fine << endl;
                } else {
                    returnRecord.fine = 0;
                    cout << "Book returned successfully without any fine." << endl;
                }
            }

            bookIt->bookIds.insert(it->issuedBooks[actualIndex]->bookId);
            bookIt->availableCopies++;
            delete it->issuedBooks[actualIndex];
            it->issuedBooks[actualIndex] = nullptr;
            it->issuedBooksCount--;
            it->totalReturns++;
            returnHistory.push_back(returnRecord);
            cout << "Exit" << endl;
        }
    } else {
        cout << "Invalid roll number." << endl;
    }
}

