void StudentManager::searchBook(Library& library) {
    string isbn;
    cout << "Enter the book ISBN code:" << endl;
    cin >> isbn;

    auto bookIt = find_if(library.books.begin(), library.books.end(), [&](const Book& book) {
        return book.isbn == isbn;
    });

    if (bookIt == library.books.end()) {
        cout << "ISBN code didn't match any textbook." << endl;
        return;
    }

    int bookId;
    cout << "Enter the book ID:" << endl;
    cin >> bookId;

    if (bookIt->bookIds.find(bookId) == bookIt->bookIds.end()) {
        auto studentIt = find_if(students.begin(), students.end(), [&](const Student& student) {
            return any_of(begin(student.issuedBooks), end(student.issuedBooks), [&](const IssueReturn* issuedBook) {
                return issuedBook != nullptr && issuedBook->isbn == isbn && issuedBook->bookId == bookId;
            });
        });

        if (studentIt != students.end()) {
            cout << "The book has been issued to: " << studentIt->name << " " << studentIt->rollNumber << endl;
        } else {
            cout << "The book is not part of the library." << endl;
        }
    } else {
        cout << "Book is available in the library." << endl;
    }
}

void StudentManager::payFine() {
    string rollNumber;
    cout << "Enter the roll number of the student you want to view:" << endl;
    cin >> rollNumber;

    auto it = find_if(students.begin(), students.end(), [&](const Student& student) {
        return student.rollNumber == rollNumber;
    });

    if (it != students.end()) {
        cout << "Student has a fine of Rs. " << it->fineAmount << " due. Enter the amount they wish to pay:" << endl;
        int paymentAmount;
        cin >> paymentAmount;

        if (paymentAmount > it->fineAmount) {
            cout << "Amount entered is greater than the fine due. Please try again." << endl;
            return;
        } else if (paymentAmount < 0) {
            cout << "Negative values are not allowed." << endl;
            return;
        } else {
            it->fineAmount -= paymentAmount;
        }
    } else {
        cout << "Roll number entered is not registered." << endl;
    }
}

