void writeStudentRecords(const StudentManager& studentManager, const Library& library) {
    ofstream studentFile("student");
    studentFile << studentManager.studentCount << endl;

    for (const auto& student : studentManager.students) {
        studentFile << student.name << endl;
        studentFile << student.rollNumber << endl;
        studentFile << student.branch << endl;
        studentFile << student.issuedBooksCount << endl;
        studentFile << student.fineAmount << endl;
        studentFile << student.totalReturns << endl;

        for (const auto& issuedBook : student.issuedBooks) {
            if (issuedBook != nullptr) {
                studentFile << issuedBook->isbn << endl;
                studentFile << issuedBook->bookId << endl;
                studentFile << issuedBook->issueDate->tm_mday << endl;
                studentFile << issuedBook->issueDate->tm_mon << endl;
                studentFile << issuedBook->issueDate->tm_year << endl;
            }
        }
    }

    ofstream bookFile("books");
    bookFile << library.books.size() << endl;

    for (const auto& book : library.books) {
        bookFile << book.title << endl;
        bookFile << book.authorCount << endl;
        for (const auto& author : book.authors) {
            bookFile << author << endl;
        }
        bookFile << book.category << endl;
        bookFile << book.publication << endl;
        bookFile << book.isbn << endl;
        bookFile << book.totalCopies << endl;
        bookFile << book.availableCopies << endl;
        bookFile << book.maxBookId << endl;

        for (const auto& bookId : book.bookIds) {
            bookFile << bookId << endl;
        }
    }

    ofstream returnFile("ret");
    returnFile << studentManager.returnHistory.size() << endl;
    for (const auto& returnRecord : studentManager.returnHistory) {
        returnFile << returnRecord.rollNumber << endl;
        returnFile << returnRecord.isbn << endl;
        returnFile << returnRecord.bookId << endl;
        returnFile << returnRecord.fine << endl;
        returnFile << returnRecord.issueDate->tm_mday << endl;
        returnFile << returnRecord.issueDate->tm_mon << endl;
        returnFile << returnRecord.issueDate->tm_year << endl;
        returnFile << returnRecord.returnDate->tm_mday << endl;
        returnFile << returnRecord.returnDate->tm_mon << endl;
        returnFile << returnRecord.returnDate->tm_year << endl;
    }
}

void readFromRecords(Library& library, StudentManager& studentManager) {
    ifstream bookFile("books");
    int bookCount;
    bookFile >> bookCount;

    for (int i = 0; i < bookCount; i++) {
        Book book;
        bookFile.ignore();
        getline(bookFile, book.title);
        bookFile >> book.authorCount;
        bookFile.ignore();

        for (int j = 0; j < book.authorCount; j++) {
            string authorName;
            getline(bookFile, authorName);
            book.authors.push_back(authorName);
        }

        bookFile >> book.category;
        bookFile.ignore();
        getline(bookFile, book.publication);
        getline(bookFile, book.isbn);
        bookFile >> book.totalCopies;
        bookFile >> book.availableCopies;
        bookFile >> book.maxBookId;

        for (int j = 0; j < book.availableCopies; j++) {
            int bookId;
            bookFile >> bookId;
            book.bookIds.insert(bookId);
        }

        library.books.push_back(book);
        library.totalBooks++;
    }

    ifstream studentFile("student");
    int studentCount;
    studentFile >> studentCount;

    for (int i = 0; i < studentCount; i++) {
        Student student;
        studentFile.ignore();
        getline(studentFile, student.name);
        getline(studentFile, student.rollNumber);
        getline(studentFile, student.branch);
        studentFile >> student.issuedBooksCount;
        studentFile >> student.fineAmount;
        studentFile >> student.totalReturns;

        for (int j = 0; j < student.issuedBooksCount; j++) {
            student.issuedBooks[j] = new IssueReturn;
            studentFile.ignore();
            getline(studentFile, student.issuedBooks[j]->isbn);
            studentFile >> student.issuedBooks[j]->bookId;

            student.issuedBooks[j]->issueDate = new tm;
            studentFile >> student.issuedBooks[j]->issueDate->tm_mday;
            studentFile >> student.issuedBooks[j]->issueDate->tm_mon;
            studentFile >> student.issuedBooks[j]->issueDate->tm_year;
        }

        for (int j = student.issuedBooksCount; j < 5; j++) {
            student.issuedBooks[j] = nullptr;
        }

        studentManager.students.push_back(student);
        studentManager.studentCount++;
    }

    ifstream returnFile("ret");
    int returnCount;
    returnFile >> returnCount;

    for (int i = 0; i < returnCount; i++) {
        ReturnRecord returnRecord;
        returnFile.ignore();
        getline(returnFile, returnRecord.rollNumber);
        getline(returnFile, returnRecord.isbn);
        returnFile >> returnRecord.bookId;
        returnFile >> returnRecord.fine;

        returnRecord.issueDate = new tm;
        returnFile >> returnRecord.issueDate->tm_mday;
        returnFile >> returnRecord.issueDate->tm_mon;
        returnFile >> returnRecord.issueDate->tm_year;

        returnRecord.returnDate = new tm;
        returnFile >> returnRecord.returnDate->tm_mday;
        returnFile >> returnRecord.returnDate->tm_mon;
        returnFile >> returnRecord.returnDate->tm_year;

        studentManager.returnHistory.push_back(returnRecord);
    }
}

