#ifndef CIRCULAR_LINKED_LIST_H

#define CIRCULAR_LINKED_LIST_H

#include <iostream>

using namespace std;

/**
 * Represents a node in the circular linked list.
 * @tparam T The type of the data stored in the node.
 */
template<typename T>
class Node {
private:
    T data;
    Node<T>* next;

public:
    Node();
    Node(T data);
    Node(T data, Node<T>* nextNode);

    T getData() const;
    Node<T>* getNext() const;
    void setData(T data);
    void setNext(Node<T>* nextNode);

    template<typename> friend class CircularLinkedList;
};

/**
 * Default constructor for an empty node.
 * @tparam T The type of the data.
 */
template<typename T>
Node<T>::Node() : next(nullptr) {}

/**
 * Constructor that initializes the node with data.
 * @tparam T The type of the data.
 * @param data The data to be stored in the node.
 */
template<typename T>
Node<T>::Node(T data) : data(data), next(nullptr) {}

/**
 * Constructor that initializes the node with data and a pointer to the next node.
 * @tparam T The type of the data.
 * @param data The data to be stored in the node.
 * @param nextNode The pointer to the next node.
 */
template<typename T>
Node<T>::Node(T data, Node<T>* nextNode) : data(data), next(nextNode) {}

/**
 * Retrieves the data stored in the node.
 * @tparam T The type of the data.
 * @return The data stored in the node.
 */
template<typename T>
T Node<T>::getData() const {
    return data;
}

/**
 * Retrieves the pointer to the next node.
 * @tparam T The type of the data.
 * @return The pointer to the next node.
 */
template<typename T>
Node<T>* Node<T>::getNext() const {
    return next;
}

/**
 * Sets the data of the node.
 * @tparam T The type of the data.
 * @param data The new data for the node.
 */
template<typename T>
void Node<T>::setData(T data) {
    this->data = data;
}

/**
 * Sets the pointer to the next node.
 * @tparam T The type of the data.
 * @param nextNode The pointer to the next node.
 */
template<typename T>
void Node<T>::setNext(Node<T>* nextNode) {
    this->next = nextNode;
}

/**
 * Represents a circular linked list.
 * @tparam T The type of the data stored in the list.
 */
template<typename T>
class CircularLinkedList {
private:
    int size;
    Node<T>* tail;

public:
    CircularLinkedList();

    int getSize() const;
    bool isEmpty() const;
    T getFirst() const;
    void addLast(T data);
    void removeFirst();
    void moveForward();
};

/**
 * Constructor for an empty circular linked list.
 * @tparam T The type of the data.
 */
template<typename T>
CircularLinkedList<T>::CircularLinkedList() : size(0), tail(nullptr) {}

/**
 * Retrieves the number of nodes in the list.
 * @tparam T The type of the data.
 * @return The number of nodes in the list.
 */
template<typename T>
int CircularLinkedList<T>::getSize() const {
    return size;
}

/**
 * Checks if the list is empty.
 * @tparam T The type of the data.
 * @return True if the list is empty, otherwise false.
 */
template<typename T>
bool CircularLinkedList<T>::isEmpty() const {
    return (size == 0);
}

/**
 * Retrieves the first value in the list.
 * @tparam T The type of the data.
 * @return The first value in the list.
 * @throws runtime_error if the list is empty.
 */
template<typename T>
T CircularLinkedList<T>::getFirst() const {
    if (tail == nullptr) {
        throw runtime_error("CircularLinkedList.getFirst: The list is empty");
    }
    return tail->next->data;
}

/**
 * Adds a new node with the specified data at the end of the list.
 * @tparam T The type of the data.
 * @param data The data to be stored in the new node.
 */
template<typename T>
void CircularLinkedList<T>::addLast(T data) {
    if (isEmpty()) {
        tail = new Node<T>(data);
        tail->next = tail;
    } else {
        tail->next = new Node<T>(data, tail->next);
        tail = tail->next;
    }
    size++;
}

/**
 * Removes the first node from the list.
 * @tparam T The type of the data.
 * @throws runtime_error if the list is empty.
 */
template<typename T>
void CircularLinkedList<T>::removeFirst() {
    if (tail == nullptr) {
        throw runtime_error("CircularLinkedList.removeFirst: The list is empty");
    }
    Node<T>* firstNode = tail->next;
    tail->next = firstNode->next;
    delete firstNode;
    size--;
}

/**
 * Advances the tail pointer to the next node.
 * @tparam T The type of the data.
 */
template<typename T>
void CircularLinkedList<T>::moveForward() {
    if (tail != nullptr) {
        tail = tail->next;
    }
}

