#include "Date.h"

/**
 * Constructs a Date object from a string representation.
 * @param dateString The string date in the format MM/DD/YYYY.
 */
Date::Date(string dateString) {
    parse(dateString);
}

/**
 * Parses a string date in the format MM/DD/YYYY into a Date object.
 * @param dateString The string date to be parsed.
 */
void Date::parse(string dateString) {
    int delimiterCount = 0;
    string day, month, year;

    // Iterate over each character in the date string
    for (char character : dateString) {
        // Skip the delimiter character
        if (character == DATE_DELIMITER) {
            delimiterCount++;
            continue;
        }

        // Capture month, day, and year based on the delimiter count
        if (delimiterCount == 0) {
            month += character; // Capture month
        } else if (delimiterCount == 1) {
            day += character; // Capture day
        } else {
            year += character; // Capture year
        }
    }

    // Initialize the date structure
    date = {};
    date.tm_year = stoi(year) - 1900; // Adjust year
    date.tm_mon = stoi(month) - 1; // Adjust month
    date.tm_mday = stoi(day); // Set day
    mktime(&date); // Normalize the date structure
}

/**
 * Adds a specified number of days to the current date.
 * @param days The number of days to add.
 */
void Date::addDays(int days) {
    date.tm_mday += days; // Increment the day by the specified number
}

/**
 * Returns the string representation of the date in the format MM/DD/YYYY.
 * @return A string date in the format MM/DD/YYYY.
 */
string Date::getDateString() const {
    return to_string(date.tm_mon + 1) + DATE_DELIMITER +
           to_string(date.tm_mday) + DATE_DELIMITER +
           to_string(date.tm_year + 1900);
}

/**
 * Compares two Date objects to determine if dateA is greater than dateB.
 * @param dateA The first date to compare.
 * @param dateB The second date to compare.
 * @return True if dateA is greater than dateB; otherwise, false.
 */
bool operator>(Date& dateA, Date& dateB) {
    time_t secondsA = mktime(&dateA.date);
    time_t secondsB = mktime(&dateB.date);
    return (secondsA > secondsB);
}

/**
 * Compares two Date objects to determine if dateA is less than dateB.
 * @param dateA The first date to compare.
 * @param dateB The second date to compare.
 * @return True if dateA is less than dateB; otherwise, false.
 */
bool operator<(Date& dateA, Date& dateB) {
    time_t secondsA = mktime(&dateA.date);
    time_t secondsB = mktime(&dateB.date);
    return (secondsA < secondsB);
}

