#ifndef QUEUE_H
#define QUEUE_H

#include "CLL.h"

/**
 * Represents a queue data structure.
 * @tparam T The type of the data stored in the queue.
 */
template<typename T>
class Queue {
private:
    CLL<T> circularLinkedList;

public:
    Queue();
    int getSize() const;
    bool isEmpty() const;
    const T front() const;
    void enqueue(const T item);
    void dequeue();
    void moveForward();
};

/**
 * Initializes an empty queue.
 * @tparam T The type of the data stored in the queue.
 */
template<typename T>
Queue<T>::Queue() {}

/**
 * Retrieves the number of elements in the queue.
 * @tparam T The type of the data stored in the queue.
 * @return The count of elements in the queue.
 */
template<typename T>
int Queue<T>::getSize() const {
    return circularLinkedList.getSize();
}

/**
 * Checks if the queue is empty.
 * @tparam T The type of the data stored in the queue.
 * @return True if the queue is empty, otherwise false.
 */
template<typename T>
bool Queue<T>::isEmpty() const {
    return circularLinkedList.isEmpty();
}

/**
 * Accesses the item at the front of the queue.
 * @tparam T The type of the data stored in the queue.
 * @return A reference to the item at the front of the queue.
 */
template<typename T>
const T Queue<T>::front() const {
    return circularLinkedList.getFirst();
}

/**
 * Adds an element to the rear of the queue.
 * @tparam T The type of the data stored in the queue.
 */
template<typename T>
void Queue<T>::enqueue(const T item) {
    circularLinkedList.addLast(item);
}

/**
 * Removes the front element from the queue.
 * @tparam T The type of the data stored in the queue.
 */
template<typename T>
void Queue<T>::dequeue() {
    circularLinkedList.removeFirst();
}

/**
 * Advances to the next node in the circular linked list.
 * @tparam T The type of the data stored in the queue.
 */
template<typename T>
void Queue<T>::moveForward() {
    circularLinkedList.moveForward();
}

