    if (sightseeing == 1) {
        totalCost += 5000;
    }
    if (cityTour == 1) {
        totalCost += 4500;
    }
    return totalCost;
}

int Access::calculateCost() {
    int totalCost = 0;
    if (pool == 1) {
        totalCost += 4000;
    }
    if (casino == 1) {
        totalCost += 5500;
    }
    if (theatre == 1) {
        totalCost += 6000;
    }
