}

void Package::calculatePrice() {
    totalPrice = 0;
    int duration = Journey::getDuration();
    int mealCost = Food::calculateCost();
    totalPrice = 6000 * duration;
    totalPrice += (duration * mealCost);
    int activityCost = Activities::calculateCost();
    totalPrice += activityCost;
    int accessCost = Access::calculateCost();
    totalPrice += accessCost;
}

void Package::display() {
    cout << "\n\n\n\n\t\tEstimated Cost of Cruise:\n\n";
    cout << "\n\t\tBasic Cost: " << Journey::getDuration() * 6000;
    cout << "\n\t\tMeals: " << Food::calculateCost() * Journey::getDuration();
    cout << "\n\t\tActivities: " << Activities::calculateCost();
    cout << "\n\t\tPrivate Access: " << Access::calculateCost();
    calculatePrice();
    cout << "\n\n\t\tTotal Bill = " << totalPrice;
}

#include <iostream>
