using namespace std;

class ReservationTable {
private:
    string reservations[11][8]; // 11 time slots for reservations, 8 tables per slot
    int tableCount;

public:
    ReservationTable() {
        initializeReservations("empty");
        tableCount = 8;
    }

    ReservationTable(int size) {
        initializeReservations("empty");
        tableCount = size;
    }

    // Initialize all reservation slots with a default status
    void initializeReservations(const string& status) {
        for (int i = 0; i < 11; i++) {
            for (int j = 0; j < 8; j++) {
                reservations[i][j] = status;
            }
        }
    }

    // Check for an available table at a specific time slot
    int findAvailableTable(int timeSlot) {
        for (int i = 0; i < tableCount; i++) {
            if (reservations[timeSlot][i] == "empty") {
                return i;
            }
        }
        return -1; // No available table
    }

    // Count the total number of free tables at a specific time slot
    int countFreeTables(int timeSlot) {
        int freeTableCount = 0;
        for (int i = 0; i < tableCount; i++) {
            if (reservations[timeSlot][i] == "empty") {
                freeTableCount++;
            }
        }
        return freeTableCount;
    }

    // Reserve a specific table at a given time slot under a name
    int reserveTable(int timeSlot, int tableIndex, const string& customerName) {
        reservations[timeSlot][tableIndex] = customerName;
        return 0;
    }
};

int runUnitTest() {
    ReservationTable smallTable(2);
    int timeSlot = 0;
    int availableTableIndex;
    string customerName = "zxc";

    availableTableIndex = smallTable.findAvailableTable(timeSlot);
    if (availableTableIndex != -1) {
        smallTable.reserveTable(timeSlot, availableTableIndex, customerName);
        availableTableIndex = smallTable.findAvailableTable(timeSlot);
        if (availableTableIndex != -1) {
            smallTable.reserveTable(timeSlot, availableTableIndex, customerName);
            availableTableIndex = smallTable.findAvailableTable(timeSlot);
            if (availableTableIndex != -1) {
                return -1; // Test failed
            }
        } else {
            return -1; // Test failed
        }
    } else {
        return -1; // Test failed
    }
    return 1; // Test passed
}

