        cout << "\n\n\t04. BALANCE ENQUIRY";
        cout << "\n\n\t05. ALL ACCOUNT HOLDER LIST";
        cout << "\n\n\t06. CLOSE AN ACCOUNT";
        cout << "\n\n\t07. MODIFY AN ACCOUNT";
        cout << "\n\n\t08. EXIT";
        cout << "\n\n\tSelect from (1-8): ";
        cin >> choice;
        system("cls");

        switch (choice) {
            case '1':
                writeAccount();
                break;
            case '2':
                cout << "\n\n\tEnter The account No.: ";
                cin >> accountNumber;
                depositWithdraw(accountNumber, 1);
                break;
            case '3':
                cout << "\n\n\tEnter The account No.: ";
                cin >> accountNumber;
                depositWithdraw(accountNumber, 2);
                break;
            case '4':
                cout << "\n\n\tEnter The account No.: ";
                cin >> accountNumber;
                displaySingleAccount(accountNumber);
                break;
            case '5':
