void transferFunds(Account userAccount, long recipientAccount, long position) {
    std::ifstream fin("csproj.dat", std::ios::in | std::ios::binary);
    long tempPosition;
    int transferStatus = 3;
    double amount;
    char key;
    Account recipientAccountData;
    while (fin.read((char*)&recipientAccountData, sizeof(recipientAccountData))) {
        if (recipientAccountData.checkAccount(recipientAccount) == 0) {
            tempPosition = (fin.tellg() - sizeof(recipientAccountData));
            gotoxy(18, 12);
            std::cout << "Enter Amount to be Transferred";
            gotoxy(18, 14);
            std::cin >> amount;
            if (amount < 0) {
                transferStatus = 1;
                clrscr();
                gotoxy(18, 16);
                drawDesign();
                std::cout << "INVALID";
                delay(75000000);
                fin.close();
                displayFeatures(userAccount, position);
            } else if (amount >= userAccount.getBalance()) {
                transferStatus = 0;
                gotoxy(18, 16);
                std::cout << "Transfer amount exceeding bank balance";
                fin.close();
                delay(75000000);
                displayFeatures(userAccount, position);
                break;
            } else {
                transferStatus = 2;
                userAccount.withdrawAmount(amount);
                recipientAccountData.depositAmount(amount);
                fin.close();
                break;
            }
        }
    }
    if (transferStatus == 2) {
        gotoxy(18, 16);
        std::ofstream foutTemp("temp.dat", std::ios::out | std::ios::binary | std::ios::app);
        std::cout << "AMOUNT WAS SUCCESSFULLY TRANSFERRED TO ";
        writeToFile(tempAccount, recipientAccountData);
        foutTemp.write((char*)&recipientAccountData, sizeof(recipientAccountData));
        foutTemp.close();
        remove("csproj.dat");
        rename("temp.dat", "csproj.dat");
        gotoxy(18, 18);
        appendToTempFile(userAccount);
        std::cout << "ACCOUNT NUMBER :- ";
        recipientAccountData.displayAccount();
        gotoxy(18, 20);
        std::cout << "NAME :- ";
        recipientAccountData.displayName();
        gotoxy(18, 22);
        std::cout << "Press any key to continue";
        gotoxy(18, 24);
        key = getch();
        key++;
        displayFeatures(userAccount, position);
    }
    if (transferStatus == 3) {
        clrscr();
        drawDesign();
        gotoxy(18, 10);
        std::cout << "INVALID ";
        delay(150000000);
        fin.close();
        displayFeatures(userAccount, position);
    }
}

void writeToFile(Account tempAccount, Account userAccount) {
    std::ifstream fin("csproj.dat", std::ios::in | std::ios::binary);
    std::ofstream foutTemp("temp.dat", std::ios::out | std::ios::binary | std::ios::app);
    while (fin.read((char*)&tempAccount, sizeof(tempAccount))) {
        if (userAccount.checkAccount(tempAccount.getAccountNumber()) != 0) {
            foutTemp.write((char*)&tempAccount, sizeof(tempAccount));
        }
    }
    foutTemp.close();
    fin.close();
}

void appendToTempFile(Account userAccount) {
    std::ofstream foutTemp("temp.dat", std::ios::out | std::ios::binary | std::ios::app);
    foutTemp.write((char*)&userAccount, sizeof(userAccount));
    foutTemp.close();
    remove("csproj.dat");
    rename("temp.dat", "csproj.dat");
}

