            gotoxy(startX, startY);
            std::cout << symbol;
        }
    } else {
        for (int i = 0; i <= 24; i++, startY++) {
            gotoxy(startX, startY);
            std::cout << symbol;
        }
    }
}

void loadScreen() {
    clrscr();
    drawDesign();
    for (int i = 0; i < 5; i++) {
        gotoxy(24, 10);
        std::cout << "PROCESSING REQUEST";
        for (int j = 0; j < 5; j++) {
            std::cout << ".";
            delay(20000000);
        }
        std::cout << "\b\b\b\b\b";
    }
}

void slowDesign() {
    int leftX = 40, rightX = 40, topY = 0;
    while (leftX <= 80) {
        gotoxy(leftX, 0);
        std::cout << "$";
        gotoxy(rightX, 0);
        std::cout << "$";
        leftX--;
        rightX++;
        delay(3000000);
    }
    while (topY <= 24) {
        gotoxy(0, topY);
        std::cout << "$";
        gotoxy(80, topY);
        std::cout << "$";
        delay(3000000);
        topY++;
    }
    leftX = 0;
    rightX = 80;
    while (leftX <= 40) {
        gotoxy(leftX, 24);
        std::cout << "$";
        gotoxy(rightX, 24);
        std::cout << "$";
        delay(3000000);
        leftX++;
        rightX--;
    }
}

void delay(long duration) {
    for (long l = 0; l <= duration; l++) {}
}

void clearScreen(long duration) {
    for (long i = 0; i <= duration; i++) {
        clrscr();
    }
}

void drawDesign() {
    drawPattern(0, 0, '$', 'h');
    drawPattern(0, 24, '$', 'h');
    drawPattern(0, 0, '$', 'v');
    drawPattern(80, 0, '$', 'v');
}

void Account::enterPin() {
    char inputChar;
    int charCount = 0, enterPressed = 0, backspacePressed = 0;
    for (int i = 0, j = 0, k = 0; i >= -2; i++) {
        charCount = 0;
        backspacePressed = 0;
        while (k == 6) {
            inputChar = getch();
            if (inputChar == 8) {
                backspacePressed = 1;
                k = 6;
                inputChar = 8;
                break;
            }
            if (inputChar == '\r') {
                enterPressed = 1;
                break;
            }
        }
        if (enterPressed == 1) break;
        if (backspacePressed == 0) inputChar = getch();
        if (!(k == 0 && inputChar == 8 || inputChar == '\r')) {
            if (inputChar == 8 && i != 0) {
                if (k >= 0) {
                    std::cout << "\b";
                    j--;
                    k--;
                    charCount = 1;
                } else {
                    std::cout << "";
                }
            }
            if (inputChar != 8 && inputChar != '\r' && j != 0) {
                if (k <= 6) {
                    j++;
                    charCount = 1;
                    k++;
                    pinCode[k - 1] = inputChar;
                }
            }
            if (inputChar != 8 && inputChar != '\r' && k <= 6) {
                std::cout << "*";
            }
            if (j == 0 && inputChar != 8) {
                pinCode[k] = inputChar;
            }
            if (inputChar != 8 && j == 0 && charCount == 0 && inputChar != '\r') {
                k++;
            }
        }
    }
    while (enterPressed == 1) {
        if (inputChar == '\r') enterPressed = 0;
    }
}

