void handleDepositWithdraw(int accountNumber, int option) {
    int amount;
    bool found = false;
    Account account;
    fstream file("account.dat", ios::binary | ios::in | ios::out);
    if (!file) {
        cout << "File could not be opened! Press any key...";
        return;
    }
    while (!file.eof() && !found) {
        file.read(reinterpret_cast<char*>(&account), sizeof(Account));
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            if (option == 1) {
                cout << "\n\n\tTO DEPOSIT AMOUNT ";
                cout << "\n\nEnter The amount to be deposited: ";
                cin >> amount;
                account.deposit(amount);
            }
            if (option == 2) {
                cout << "\n\n\tTO WITHDRAW AMOUNT ";
                cout << "\n\nEnter The amount to be withdrawn: ";
                cin >> amount;
                int newBalance = account.getBalance() - amount;
                if ((newBalance < 500 && account.getAccountType() == 'S') || (newBalance < 1000 && account.getAccountType() == 'C')) {
                    cout << "Insufficient balance";
                } else {
                    account.withdraw(amount);
                }
            }
            int position = (-1) * static_cast<int>(sizeof(account));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            cout << "\n\n\t Record Updated";
            found = true;
        }
    }
    file.close();
    if (!found) {
        cout << "\n\n Record Not Found ";
    }
}

