// Function to display all available routes
void displayAllRoutes() {
    string startLocation, endLocation;
    int routeId, distance, haltCount;
    string halts[5];
    int busId;

    string line;
    int routeCount = 0;

    ifstream routeFile("routes.csv");

    while (getline(routeFile, startLocation, ',')) {
        getline(routeFile, endLocation, ',');
        getline(routeFile, line, ',');
        stringstream ss(line);
        ss >> routeId;
        getline(routeFile, line, ',');
        stringstream ssDistance(line);
        ssDistance >> distance;
        getline(routeFile, line, ',');
        stringstream ssHaltCount(line);
        ssHaltCount >> haltCount;
        for (int i = 0; i < 5; i++) {
            getline(routeFile, halts[i], ',');
        }
        getline(routeFile, line, '\n');
        stringstream ssBusId(line);
        ssBusId >> busId;
        routeCount++;

        cout << endl << routeCount << ". From " << startLocation << " to " << endLocation 
             << " | Route ID: " << routeId << " | Distance: " << distance << " km | Halts: ";
        for (const auto& halt : halts) {
            if (halt != "NULL") {
                cout << halt << " , ";
            }
        }
        cout << "Bus ID: " << busId << endl << endl;
    }
    routeFile.close();
}

