Account::Account() {
    time_t currentTime = time(0);
    struct tm *localTime = localtime(&currentTime);
    dateCreated.setDate(
        localTime->tm_mday,
        (localTime->tm_mon + 1),
        (localTime->tm_year + 1900)
    );
    balance = 0.0;
}

Account::Account(const Account &sourceAccount)
    : accNum(sourceAccount.accNum), accountTypeNumber(sourceAccount.accountTypeNumber) {
    balance = sourceAccount.balance;
    dateCreated = sourceAccount.dateCreated;
}

Account &Account::operator=(const Account &sourceAccount) {
    if (this != &sourceAccount) {
        accNum = sourceAccount.accNum;
        accountTypeNumber = sourceAccount.accountTypeNumber;
        dateCreated = sourceAccount.dateCreated;
        balance = sourceAccount.balance;
    }
    return *this;
}

Account::~Account() {}

uint Account::getAccNum() const {
    return accNum;
}

void Account::setAccTypeNum(uint typeNum) {
    accountTypeNumber = typeNum;
}

uint Account::getAccTypeNum() const {
    return accountTypeNumber;
}

double Account::getBalance() const {
    return balance;
}

void Account::deposit(double amount) {
    if (amount >= 0) {
        balance += amount;
    } else {
        cerr << "Cannot deposit negative value\n";
    }
}

bool Account::withdraw(double amount) {
    bool isWithdrawalSuccessful = false;
    if (amount <= balance) {
        balance -= amount;
        isWithdrawalSuccessful = true;
    } else {
        cerr << "Insufficient funds\n";
    }
    return isWithdrawalSuccessful;
}

Date Account::getDateCreated() const {
    return dateCreated;
}

