using uint = unsigned int;

// Base class representing a bank account with common attributes and operations
class Account {
    protected:
        uint accountNumber;      // Unique identifier for the account
        uint accountType;        // Identifier for the type of account
        Date creationDate;       // Date when the account was created
        double accountBalance;    // Current balance of the account

        virtual void initializeAccountNumber() = 0;

        friend class boost::serialization::access;

        // Serialization method for saving account data
        template<class Archive>
        void save(Archive &ar, const uint version) const {
            ar & accountNumber;
            ar & accountType;
            ar & creationDate;
            ar & accountBalance;
        }

        // Serialization method for loading account data
        template<class Archive>
        void load(Archive &ar, const uint version) {
            ar & accountNumber;
            ar & accountType;
            ar & creationDate;
            ar & accountBalance;
        }

        BOOST_SERIALIZATION_SPLIT_MEMBER()

    public:
        Account();                                     // Default constructor
        Account(const Account&);                       // Copy constructor
        Account& operator=(const Account&);           // Assignment operator
        virtual ~Account();                            // Destructor

        uint getAccountNumber() const;                // Retrieve account number
        void setAccountType(uint);                     // Set the account type
        virtual uint getAccountType() const;          // Retrieve account type
        double getBalance() const;                     // Retrieve current balance
        void deposit(double amount);                   // Deposit funds into the account
        bool withdraw(double amount);                  // Withdraw funds from the account
        bool closeAccount();                           // Close the account
        Date getCreationDate() const;                 // Retrieve account creation date
        virtual void display() const = 0;             // Print account details
};

BOOST_SERIALIZATION_ASSUME_ABSTRACT(Account)
BOOST_CLASS_VERSION(Account, 0)

#endif /* ACCOUNT_H */

