using namespace std;
using uint = unsigned int;

uint Client::clientCount = 0;

Client::Client() {
    clientCount++;
    initializeAccessNumber();
}

Client::Client(const string& firstName, const string& lastName, 
               const Date& dateOfBirth, uint SSN, const string& pin,
               const string& address, const string& telephone, const string& email)
    : Person(firstName, lastName, dateOfBirth, SSN, address, telephone, email) 
{
    clientCount++;
    this->PIN = pin;
    initializeAccessNumber();
}

Client::Client(const Client &other)
    : Person(other.getFName(), other.getLName(), other.getBirthDay(),
             other.getBirthMonth(), other.getBirthYear(), other.getSSN(),
             other.getAddress(), other.getTelephone(), other.getEmail()),
      accessNumber(other.accessNumber), PIN(other.PIN)
{   
    clientCount++;
    calculateAge();
    chequingAccounts = other.chequingAccounts;
    savingsAccounts = other.savingsAccounts;
}

Client& Client::operator=(const Client &other) {
    if (this != &other) {
        firstName = other.firstName;
        lastName = other.lastName;
        dateOfBirth = other.dateOfBirth;
        age = other.age;
        SSN = other.SSN;
        address = other.address;
        telephone = other.telephone;
        email = other.email;
        accessNumber = other.accessNumber;
        PIN = other.PIN;

        chequingAccounts = other.chequingAccounts;
        savingsAccounts = other.savingsAccounts;
    }
    return *this;
}

Client::~Client() {
    chequingAccounts.clear();
    savingsAccounts.clear();
}

void Client::initializeAccessNumber() {
    accessNumber = clientCount * 10000 + getBirthMonth() * 100 + getBirthDay();
}

Account* Client::findAccount(uint accountNumber) {
    for (auto& account : chequingAccounts) {
        if (account->getAccNum() == accountNumber) {
            return account;
        }
    }

    for (auto& account : savingsAccounts) {
        if (account->getAccNum() == accountNumber) {
            return account;
        }
    }

    return nullptr;
}

uint Client::createAccount(accountType accType) {
    uint newAccountNumber = 0;

    if (accType == accountType::Chequing) {
        chequingAccounts.push_back(new ChequingAccount);
        newAccountNumber = chequingAccounts.back()->getAccNum();
    } else if (accType == accountType::Savings) {
        savingsAccounts.push_back(new SavingsAccount);
        newAccountNumber = savingsAccounts.back()->getAccNum();
    }

    return newAccountNumber;
}

bool Client::validateLogin(uint accessNum, const string& pin) const {
    return accessNumber == accessNum && PIN == pin;
}

void Client::updatePIN(const string& pin) {
    PIN = pin;
}

uint Client::getAccessNum() const {
    return accessNumber;
}

uint Client::getNumOfChequingAccounts() const {
    return chequingAccounts.size();
}

uint Client::getNumOfSavingsAccounts() const {
    return savingsAccounts.size();
}

double Client::getAccountBalance(uint accountNumber) {
    Account* account = findAccount(accountNumber);
    return account ? account->getBalance() : -1; // Return -1 if account does not exist
}

Date Client::getAccountCreationDate(uint accountNumber) {
    Account* account = findAccount(accountNumber);
    if (account) {
        return account->getDateCreated();
    } else {
        cerr << "No account with account number " << accountNumber << " exists.\n";
        return Date(); // Return default date if account does not exist
    }
}

bool Client::depositToAccount(uint accountNumber, double amount) {
    if (amount <= 0) {
        cerr << "Please enter a positive amount\n";
        return false;
    }

    Account* account = findAccount(accountNumber);
    if (account) {
        account->deposit(amount);
        return true;
    } else {
        cerr << "No account with account number " << accountNumber << " exists.\n";
        return false;
    }
}

bool Client::withdrawFromAccount(uint accountNumber, double amount) {
    if (amount <= 0) {
        cerr << "Please enter a positive amount\n";
        return false;
    }

    Account* account = findAccount(accountNumber);
    if (account) {
        return account->withdraw(amount);
    } else {
        cerr << "No account with account number " << accountNumber << " exists.\n";
        return false;
    }
}

bool Client::deleteAccount(uint accountNumber) {
    Account* account = findAccount(accountNumber);
    if (!account) {
        cerr << "No account with account number " << accountNumber << " exists.\n";
        return false;
    }

    if (account->getBalance() != 0) {
        cerr << "Please withdraw all funds inside account " << accountNumber << " before deleting.\n";
        return false;
    }

    if (account->getAccTypeNum() == 101) { // Chequing account
        chequingAccounts.erase(remove_if(chequingAccounts.begin(), chequingAccounts.end(),
            [accountNumber](Account* acc) { return acc->getAccNum() == accountNumber; }), chequingAccounts.end());
    } else if (account->getAccTypeNum() == 201) { // Savings account
        savingsAccounts.erase(remove_if(savingsAccounts.begin(), savingsAccounts.end(),
            [accountNumber](Account* acc) { return acc->getAccNum() == accountNumber; }), savingsAccounts.end());
    }

    return true;
}

bool Client::deleteAllAccounts() {
    bool allDeleted = true;

    for (auto& account : chequingAccounts) {
        allDeleted &= deleteAccount(account->getAccNum());
    }

    for (auto& account : savingsAccounts) {
        allDeleted &= deleteAccount(account->getAccNum());
    }

    return allDeleted;
}

void Client::printAccountDetails(uint accountNumber) {
    Account* account = findAccount(accountNumber);
    if (account) {
        account->print();
    } else {
        cerr << "No account with account number " << accountNumber << " exists.\n";
    }
}

void Client::listAllAccounts() {
    cout << "Banking profile:\n";
    cout << "  Access Number: " << accessNumber << endl;
    cout << "  Number of Chequing Accounts: " << getNumOfChequingAccounts() << endl << endl;

    for (auto& account : chequingAccounts) {
        account->print();
    }

    cout << "  Number of Savings Accounts: " << getNumOfSavingsAccounts() << endl << endl;

    for (auto& account : savingsAccounts) {
        account->print();
    }
    cout << endl;
}

void Client::displayClientInfo() {
    Person::printPersonInfo();
    cout << endl;
    listAllAccounts();
}

