#ifndef EDGE_HPP
#define EDGE_HPP

#include <string>
#include "Synch_queue.hpp"

class Edge {
public:
    // Default constructor
    Edge() = default;

    // Parameterized constructor for initializing edge properties
    Edge(int id, int weight, Synch_queue* messageQueue, const std::string& address, const std::string& port)
        : index(id), weight(weight), mq(messageQueue), ip_address(address), tcp_port(port) {}

    // Copy constructor for creating a duplicate edge
    Edge(const Edge& other)
        : index(other.index), weight(other.weight), mq(other.mq), ip_address(other.ip_address), tcp_port(other.tcp_port) {}

    // Move constructor for transferring ownership of resources
    Edge(Edge&& other) noexcept
        : index(other.index), weight(other.weight), mq(other.mq), ip_address(other.ip_address), tcp_port(other.tcp_port) {
        // Ownership of message queue is transferred; other.mq remains unchanged
    }

    // Accessor for edge weight
    int get_weight() const { return weight; }

    // Accessor for edge index
    int get_index() const { return index; }

    // Accessor for IP address of the target node
    std::string get_ip_address() const { return ip_address; }

    // Accessor for TCP port of the target node
    std::string get_tcp_port() const { return tcp_port; }

private:
    int index;                         // Index of the target node
    int weight;                        // Weight of the edge
    std::string ip_address;            // IP address of the target node's handler thread
    std::string tcp_port;              // TCP port of the target node's handler thread
    Synch_queue* mq;                   // Associated message queue for this edge
};

#endif // EDGE_HPP

#ifndef FILE_PTR_HPP
#define FILE_PTR_HPP

#include <cstdio>
#include <iostream>
#include <exception>
#include <string>

class FilePointer {
    FILE* fileHandle;
    std::string fileName;
    static const int bufferSize = 300;

public:
    FilePointer() : fileHandle(nullptr) {} // Default constructor

    FilePointer(const char* name, const char* mode) // Constructor to initialize FilePointer with file name and mode
        : fileHandle{ fopen(name, mode) }, fileName(name) {
        if (fileHandle == nullptr) {
            throw std::runtime_error{"FilePointer: Unable to open file: " + fileName};
        }
    }

    FilePointer(const std::string& name, const char* mode) // Constructor to initialize FilePointer with std::string file name and mode
        : FilePointer{name.c_str(), mode} {}

    explicit FilePointer(FILE* handle) // Constructor to initialize FilePointer from a FILE* object
        : fileHandle{ handle } {
        if (fileHandle == nullptr) {
            throw std::runtime_error("FilePointer: nullptr");
        }
    }

    FilePointer& operator=(const FilePointer& other) = delete; // Copy assignment deleted
    FilePointer& operator=(FilePointer&& other) = delete;      // Move assignment deleted
    FilePointer(const FilePointer& other) = delete;            // Copy constructor deleted

    FilePointer(FilePointer&& other) // Move constructor
        : fileHandle{ other.fileHandle } {
        other.fileHandle = nullptr;
    }

    int read(char* line) { // Read a line from the file
        return (fgets(line, bufferSize, fileHandle) == nullptr) ? 0 : 1;
    }

    int write(const char* line) { // Write a C-style string to the file
        return fprintf(fileHandle, "%s\n", line);
    }

    int write(const std::string& line) { // Write a std::string to the file
        return write(line.c_str());
    }

    ~FilePointer() { fclose(fileHandle); } // Destructor to close the file

    operator FILE*() { return fileHandle; } // Conversion operator to FILE*
};

#endif // FILE_PTR_HPP

#include "Handler.hpp"
#include <boost/asio.hpp>
#include "Message.hpp"
#include "split.hpp"
#include "to.hpp"

using boost::asio::ip::tcp;

// Handles incoming TCP connections and message processing.
void Handler::operator()()
{
    // Manages individual client connections and asynchronous message reading.
    class TcpConnection : public std::enable_shared_from_this<TcpConnection>
    {
    public:
        TcpConnection(tcp::socket socket, Synch_queue* message_queue, Synch_cout* synch_cout, int client_index)
            : socket_(std::move(socket)),
              message_queue_(message_queue),
              synch_cout_(synch_cout),
              client_index_(client_index)
        {}

        void start()
        {
            readHeader();
        }

    private:
        void readHeader()
        {
            auto self(shared_from_this());
            boost::asio::async_read(socket_,
                boost::asio::buffer(read_msg.data(), Message::header_length),
                [this, self](boost::system::error_code ec, std::size_t)
                {
                    if (!ec && read_msg.decode_header())
                    {
                        readBody();
                    }
                    else
                    {
                        socket_.close();
                    }
                });
        }

        void readBody()
        {
            auto self(shared_from_this());
            boost::asio::async_read(socket_,
                boost::asio::buffer(read_msg.body(), read_msg.body_length()),
                [this, self](boost::system::error_code ec, std::size_t)
                {
                    if (!ec)
                    {
                        std::string message(read_msg.body(), read_msg.body_length());
                        std::vector<std::string> tokens = split(message);
                        message_queue_->put(read_msg);
                        if (tokens[0] == "finished")
                        {
                            socket_.close();
                        }
                        else
                        {
                            readHeader();
                        }
                    }
                });
        }

        tcp::socket socket_;
        Message read_msg;
        Synch_queue* message_queue_;
        Synch_cout* synch_cout_;
        int client_index_;
    };

    // Accepts incoming connections and manages the connection limit.
    class TcpServer
    {
    public:
        TcpServer(boost::asio::io_service& io_service,
                   const tcp::endpoint& endpoint, Synch_queue* message_queue, Synch_cout* sync_cout, int server_index,
                   size_t max_connections)
            : acceptor_(io_service, endpoint),
              socket_(io_service),
              message_queue_(message_queue),
              connection_count_(0),
              synch_cout_(sync_cout),
              server_index_(server_index),
              max_connections_(max_connections)
        {
            acceptConnection();
        }

    private:
        void acceptConnection()
        {
            acceptor_.async_accept(socket_,
                [this](boost::system::error_code ec)
                {
                    if (!ec)
                    {
                        std::make_shared<TcpConnection>(std::move(socket_), message_queue_, synch_cout_, server_index_)->start();
                        connection_count_++;
                        if (connection_count_ < max_connections_)
                        {
                            acceptConnection();
                        }
                    }
                });
        }

        tcp::acceptor acceptor_;
        tcp::socket socket_;
        size_t max_connections_;
        int connection_count_;
        int server_index_;
        Synch_queue* message_queue_;
        Synch_cout* synch_cout_;
    };

    try
    {
        // Initializes the ASIO I/O service for handling asynchronous operations.
        boost::asio::io_service io_service;
        // Defines the TCP endpoint for the server.
        tcp::endpoint endpoint(tcp::v4(), std::atoi(port_.c_str()));
        // Creates a TCP server to manage incoming connections.
        TcpServer server(io_service, endpoint, message_queue, synch_cout, index, n_connections);
        // Runs the I/O service to process asynchronous events.
        io_service.run();
    }
    catch (std::exception& e)
    {
        std::cerr << "Exception: " << e.what() << "\n";
    }
}

#ifndef HANDLER_HPP
