// Class responsible for handling TCP connections and managing message queues.
class Handler {
public:
    // Constructor to initialize the handler with port, message queue, output stream, and ID.
    Handler(const std::string& port, Synch_queue* msgs_queue, Synch_cout* synch_cout, int ID)
        : port_{port}, message_queue{msgs_queue}, output_stream{synch_cout}, handler_id{ID}, connection_count{0} {}

    // Copy constructor for creating a new Handler instance from an existing one.
    Handler(const Handler& handler)
        : port_{handler.port_}, message_queue{handler.message_queue}, output_stream{handler.output_stream},
          handler_id{handler.handler_id}, connection_count{handler.connection_count} {}

    // Set the number of connections for the handler.
    void set_connection_count(size_t num_connections) {
        connection_count = num_connections;
    }

    // Main execution method for the handler.
    void operator()();

private:
    std::string port_;                // TCP port for the handler.
    int handler_id;                   // Unique identifier for the handler instance.
    Synch_queue* message_queue;       // Pointer to the message queue for communication.
    Synch_cout* output_stream;        // Pointer to the synchronized output stream.
    size_t connection_count;          // Total number of connections to be established.
};

#endif

