void CAocTMDlg::OnDropFiles(HDROP hDropInfo)
{
    int fileCount = DragQueryFile(hDropInfo, 0xFFFFFFFF, NULL, 0);
    TCHAR filePath[4096];
    int loadedCount = 0, newCount = 0;
    CRecgame* recGame;
    CProgressWnd progressWnd;

    CPlayerDatabase players;
    CRecgameDatabase recGames;
    players.m_pRecgameDB = &recGames;

    progressWnd.Create(this, _T("Progress..."), TRUE);
    progressWnd.SetRange(0, fileCount);
    progressWnd.SetText(_T("Loading Recorded Game files..."));

    for (int i = 0; i < fileCount; i++)
    {
        progressWnd.StepIt();
        progressWnd.PeekAndPump();
        if (progressWnd.Cancelled())
        {
            break;
        }

        DragQueryFile(hDropInfo, i, filePath, 4096);
        recGame = new CRecgame;

        if (!recGame->Read(filePath))
        {
            delete recGame;
            continue;
        }

        if (recGame->PlayTime < TIME_4_INCOMPLETE)
        {
            delete recGame;
            continue;
        }

        players.Add(recGame);
        loadedCount++;

        if (theApp.Recgames.Add(recGame))
        {
            recGames.Add(recGame);
            newCount++;
        }
        else
        {
            recGames.Add(theApp.Recgames[theApp.Recgames.GetFirstSameRecgame(recGame)]);
            delete recGame;
        }
    }

    progressWnd.Hide();

    if (newCount > 0)
        theApp.Players.Update(true);

    if (loadedCount < fileCount)
    {
        CString message;
        message.Format(_T("%d(new: %d) of %d Game(s) Loaded."), loadedCount, newCount, fileCount);
        AfxMessageBox(message);
    }

    if (loadedCount > 0)
    {
        players.CopyNickNames();
        ShowReport(&players);
        Refresh();
        players.Free();
    }

    CDialog::OnDropFiles(hDropInfo);
}

