void CAocTMDlg::Refresh()
{
    CString titleText;

    POSITION selectedPos, savedSelectedPos;
    selectedPos = savedSelectedPos = m_List.GetFirstSelectedItemPosition();
    int selectedRecId = (savedSelectedPos) ? m_List.GetItemData(m_List.GetNextSelectedItem(selectedPos)) : -1;

    if (theApp.Recgames.IsEmpty())
    {
        titleText.Format(_T("Empty database."));
        SetDlgItemText(IDC_TITLE, titleText);
        m_List.DeleteAllItems();
        m_List.UpdateWindow();
        return;
    }

    INT_PTR firstGameId = theApp.Recgames.GetFirstGameID();
    INT_PTR lastGameId = theApp.Recgames.GetLastGameID();
    if (firstGameId < 0 || lastGameId < 0)
    {
        AfxMessageBox(_T("Database Error!"));
        return;
    }

    titleText.Format(_T("%3d games (%s to %s)"), theApp.Recgames.GetCount(), theApp.Recgames[firstGameId]->RecordTime.Format(_T("%Y-%m-%d %H:%M:%S")), theApp.Recgames[lastGameId]->RecordTime.Format(_T("%Y-%m-%d %H:%M:%S")));
    SetDlgItemText(IDC_TITLE, titleText);

    m_List.SetRedraw(false);
    m_List.DeleteAllItems();

    CTime fromTime, toTime;
    m_From.GetTime(fromTime);
    m_To.GetTime(toTime);
    CRecgame* recGame;

    for (int i = 0, j = 0; i < theApp.Recgames.GetCount(); i++)
    {
        recGame = theApp.Recgames[i];
        if (recGame->RecordTime < fromTime || recGame->RecordTime > toTime)
            continue;

        titleText.Format(_T("%d"), j + 1);
        m_List.InsertItem(j, titleText);
        m_List.SetItemText(j, 1, recGame->RecordTime.Format(_T("%y-%m-%d %H:%M:%S")));
        m_List.SetItemText(j, 2, recGame->Map.Name);
        m_List.SetItemText(j, 3, recGame->PlayTime.Format(_T("%H:%M:%S")));

        int winnerTeam = recGame->GetWinnerTeam();
        COLORREF backgroundColor = (winnerTeam == 0) ? RGB(220, 220, 220) : ::GetSysColor(COLOR_WINDOW);
        if (winnerTeam == 0) winnerTeam = 1;

        for (int k = 1, winIndex = 0, loseIndex = 0; k <= 8 && k < recGame->Players.GetCount() && !recGame->Players[k].Name.IsEmpty(); k++)
        {
            titleText.Format(_T("[%s]%s"), civ_name[recGame->Players[k].Civ], recGame->Players[k].Name);
            int teamPosition = (recGame->Players[k].Team == winnerTeam) ? 4 + winIndex++ : 8 + loseIndex++;

            if (winIndex > 4 || loseIndex > 4)
            {
                backgroundColor = RGB(220, 0, 0);
            }

            m_List.SetItemText(j, teamPosition, titleText);
            m_List.SetItemColors(j, teamPosition, player_color[recGame->Players[k].Color], backgroundColor);
        }

        m_List.SetItemData(j++, i);
    }

    if (savedSelectedPos)
    {
        for (int i = 0; i < m_List.GetItemCount(); i++)
        {
            if (m_List.GetItemData(i) == selectedRecId)
            {
                m_List.SetItemState(i, LVIS_SELECTED, LVIS_SELECTED);
                m_List.EnsureVisible(i, true);
                break;
            }
        }
    }

    m_List.SetRedraw();
    m_List.UpdateWindow();
}

