void CAocTMDlg::LoadRecFile(bool isAofe, int& newCount, int& loadCount, int& readCount)
{
    CString recPath = isAofe ? theApp.Recgames.GetRecPathAOFE() : theApp.Recgames.GetRecPath();
    if (recPath.IsEmpty())
        return;

    TCHAR oldPath[MAX_PATH];
    ::GetCurrentDirectory(MAX_PATH, oldPath);
    ::SetCurrentDirectory(recPath);

    CFileFind finder;
    INT_PTR lastGameId = theApp.Recgames.GetLastGameID();
    CTime latestGameTime = (lastGameId < 0) ? CTime(0) : theApp.Recgames[lastGameId]->RecordTime;
    BOOL isFileFound = finder.FindFile(_T("*.mg?"));

    while (isFileFound)
    {
        isFileFound = finder.FindNextFile();
        CString fileName = finder.GetFileName();
        if (Renamer::Parse2Playtime(fileName) <= latestGameTime)
            continue;

        CRecgame* recGame = new CRecgame;
        if (!recGame->Read(finder.GetFilePath()))
        {
            delete recGame;
            continue;
        }
        readCount++;

        if (recGame->PlayTime < TIME_4_INCOMPLETE)
        {
            delete recGame;
            continue;
        }

        loadCount++;
        if (theApp.Recgames.Add(recGame))
        {
            newCount++;
        }
        else
        {
            delete recGame;
        }
    }

    ::SetCurrentDirectory(oldPath);
}

int CAocTMDlg::OnAcceleratorLoad()
{
    int readCount = 0, loadCount = 0, newCount = 0;

    LoadRecFile(false, newCount, loadCount, readCount);
    LoadRecFile(true, newCount, loadCount, readCount);

    if (loadCount < readCount)
    {
        CString message;
        message.Format(_T("%d(new: %d) of %d Game(s) Loaded."), loadCount, newCount, readCount);
        AfxMessageBox(message);
    }

    if (newCount > 0)
    {
        theApp.Players.Update(true);
        Refresh();
    }

    return newCount;
}

