void CAocTMDlg::OnNMDblclkRecList(NMHDR* pNMHDR, LRESULT* pResult)
{
    POSITION pos = m_List.GetFirstSelectedItemPosition();
    if (!pos)
        return;

    CGameInfoDlg gameInfoDlg;
    gameInfoDlg.m_Recgame = theApp.Recgames[m_List.GetItemData(m_List.GetNextSelectedItem(pos))];
    gameInfoDlg.DoModal();

    *pResult = 0;
}

void CAocTMDlg::OnBnClickedSummary()
{
    int index;
    CPlayerDatabase players;
    CRecgameDatabase recGames;
    players.m_pRecgameDB = &recGames;

    POSITION pos = m_List.GetFirstSelectedItemPosition();
    if (pos)
    {
        while (pos)
        {
            index = m_List.GetItemData(m_List.GetNextSelectedItem(pos));
            players.Add(theApp.Recgames[index]);
            recGames.Add(theApp.Recgames[index]);
        }
    }
    else
    {
        for (int i = 0; i < m_List.GetItemCount(); i++)
        {
            index = m_List.GetItemData(i);
            players.Add(theApp.Recgames[index]);
            recGames.Add(theApp.Recgames[index]);
        }
    }

    players.CopyNickNames();
    ShowReport(&players);
    players.Free();
}

void CAocTMDlg::OnNMRClickRecList(NMHDR* pNMHDR, LRESULT* pResult)
{
    POSITION pos = m_List.GetFirstSelectedItemPosition();
    if (!pos)
        return;

    CMenu menu, *pSubMenu;
    if (!menu.LoadMenu(IDR_RECPOPMENU))
        return;

    if (!(pSubMenu = menu.GetSubMenu(0)))
        return;

    CPoint cursorPos;
    GetCursorPos(&cursorPos);
    SetForegroundWindow();
    ::TrackPopupMenu(pSubMenu->m_hMenu, 0, cursorPos.x, cursorPos.y, 0, GetSafeHwnd(), NULL);
    PostMessage(WM_NULL, 0, 0);
    menu.DestroyMenu();

    *pResult = 0;
}

void CAocTMDlg::OnSetWinner(UINT command)
{
    int team;
    POSITION pos = m_List.GetFirstSelectedItemPosition();

    switch (command)
    {
    case ID_SETWINNER_0:
        team = 0;
        break;
    case ID_SETWINNER_1:
        team = 1;
        break;
    case ID_SETWINNER_2:
        team = 2;
        break;
    case ID_SETWINNER_CLEAR:
        team = -1;
        break;
    default:
        team = theApp.Recgames[m_List.GetItemData(m_List.GetNextSelectedItem(pos))]->GetWinnerTeam();
    }

    pos = m_List.GetFirstSelectedItemPosition();
    while (pos)
    {
        theApp.Recgames[m_List.GetItemData(m_List.GetNextSelectedItem(pos))]->ManualWinnerTeam = team;
    }
    Refresh();
}

void CAocTMDlg::GroupThis()
{
    POSITION pos = m_List.GetFirstSelectedItemPosition();
    if (!pos)
        return;

    CRecgame* recGame = theApp.Recgames[m_List.GetItemData(m_List.GetNextSelectedItem(pos))];
    if (!recGame)
        return;

    theApp.ClearCurrentPlayers();
    for (int i = 0, j = 0; i < recGame->Players.GetCount(); i++)
    {
        int index = theApp.Players.GetFirstSamePlayer(recGame->Players[i].Name);
        if (index < 0)
            continue;
        theApp.CurrentPlayers[j++] = index;
    }

    theApp.bCurrent = true;
    OnGrouping();
}

void CAocTMDlg::OnRegroupThis()
{
    POSITION pos = m_List.GetFirstSelectedItemPosition();
    if (!pos)
        return;

    CRecgame* recGame = theApp.Recgames[m_List.GetItemData(m_List.GetNextSelectedItem(pos))];
    if (!recGame)
        return;

    theApp.ClearCurrentPlayers();
    for (int i = 0, j = 0; i < recGame->Players.GetCount(); i++)
    {
        int index = theApp.Players.GetFirstSamePlayer(recGame->Players[i].Name);
        if (index < 0)
            continue;
        theApp.CurrentPlayers[j++] = index;
    }

    theApp.bCurrent = true;
    theApp.Players.Update(false, CTime(0), recGame->RecordTime - CTimeSpan(0, 0, 5, 0));
    OnGrouping();
    theApp.Players.Update();
}

