    HQLOperand(number i);
    HQLOperand(ConditionOperator::Type coop);
    HQLOperand(const string&, Type ot = Type::IDENTIFIER);
    HQLOperand(const vector<string>*, Type ot = Type::NUMBER_ARRAY);
    HQLOperand(shared_ptr<HQLNode>);
    HQLOperand(const JSONNode&, Type ot = Type::NIL);
    HQLOperand(const HQLOperand&);
    virtual ~HQLOperand();

    const HQLOperand& operator=(const HQLOperand&);
    bool operator<(const HQLOperand&);
    Type get_type() const { return type; }
    number as_number() const { return data.num; }
    bool as_boolean() const { return data.boolean; }
    uint64_t as_fullname() const { return data.fullname; }
    Keyword as_keyword() const { return data.kw; }
    string* as_string() const { return data.str; }
    const vector<string>* as_string_array() const { return data.array; }
    shared_ptr<HQLNode> as_node() const { return node; }
    string as_coop() const;
    ConditionOperator::Type as_coop_type() const { return data.coop; }
    string as_code_hql() const;
    bool predicate(const HQLOperand&, const JSONNode&);

private:
    Type type;
    union {
        bool boolean;
        number num;
        Keyword kw;
        uint64_t fullname;
        ConditionOperator::Type coop;
        string* str;
        const vector<string>* array;
    } data;
    shared_ptr<HQLNode> node;
};

class HQLNode {
public:
    enum class Type {
        ERROR, EACH, FULLNAME, SL, SLFK, RL, LOGIC, MISC,
    };

    enum class Subtype {
        NORMAL,
        ALL, CONDITION, 
        AND, OR, NOT, 
        LIMIT, ORDER_BY, 
    };

    enum class TargetType {
        NEGATIVE, IMPLICIT, EXPLICIT,
    };

    HQLNode(Type, Subtype subtype = Subtype::NORMAL, TargetType target = TargetType::IMPLICIT);
    HQLNode(const HQLNode&);
    virtual ~HQLNode();

    const HQLNode& operator=(const HQLNode&);

    void push_operand(const HQLOperand&);
    void push_operand(const vector<HQLOperand>&);
    void set_element_type(const string& t) { element_type = t; }
    void set_target(TargetType tt) { target = tt; }
    TargetType get_target() const { return target; }
    void set_operand_count(uint16_t n) { operand_count = n; }
    bool is_error() const { return type == Type::ERROR; }
    Type get_type() const { return type; }
    const string& get_element_type() const { return element_type; }
    const string& get_auxiliary_type() const { return auxiliary_type; }
    Subtype get_subtype() const { return subtype; }
    const HQLOperand& get_operand(size_t i) const { return operands[i]; }
    const vector<HQLOperand>& get_operands() const { return operands; }
    virtual const string to_hql() const = 0;
    virtual const string cache_key(bool do_result_reduce = false) const = 0;
    virtual const set<string> get_ctypes() const = 0;
    virtual const set<string> get_rtypes() const = 0;
    virtual ExtraMatchDataInfo get_extra_match_data_info() const = 0;
    virtual const map<uint64_t, set<string>> match(const Model &m, ModelGetter *getter) = 0;
    virtual HQLNode* copy() = 0;
    virtual HQLNode* reduce() = 0;
    virtual bool validate() const;
    virtual bool has_semantic_each() const = 0;
    virtual pair<string, uint64_t> time_in() const { return std::make_pair("", 0UL); }
    virtual vector<string> has_semantic_foreign_key() const = 0;

protected:
    Type type;
    Subtype subtype;
    TargetType target;
    mutable string element_type; 
    mutable string auxiliary_type; 
    uint16_t operand_count; 
    vector<HQLOperand> operands;
    mutable string error_info;
};

