/* LogicAndNode */

LogicAndNode::LogicAndNode(shared_ptr<HQLNode> leftOperand,
                           shared_ptr<HQLNode> rightOperand,
                           TARGET_TYPE targetType):
    HQLNode(LOGIC, AND, targetType)
{
    push_operand(HQLOperand(leftOperand));
    push_operand(HQLOperand(rightOperand));
}

LogicAndNode::LogicAndNode(vector<HQLOperand> operandsList,
                           TARGET_TYPE targetType):
    HQLNode(LOGIC, AND, targetType)
{
    operands = operandsList;
}

LogicAndNode::LogicAndNode(vector<shared_ptr<HQLNode>> nodeList,
                           TARGET_TYPE targetType):
    HQLNode(LOGIC, AND, targetType)
{
    for(const auto& node : nodeList){
        push_operand(HQLOperand(node));
    }
}

LogicAndNode::LogicAndNode(const LogicAndNode &other):
    HQLNode(other)
{
}

const LogicAndNode& LogicAndNode::operator=(const LogicAndNode& other)
{
    if(this == &other) return *this;
    HQLNode::operator=(other);
    return *this;
}

