{
#ifdef DEBUG
    std::cout << "<DEBUG> HQLNode DTOR: " << this->to_hql() << std::endl;
#endif
}

HQLNode* LogicAndNode::reduce()
{
    if(!validate()){
        return new ErrorNode(error_info);
    }

    HQLNode *resultNode = nullptr;
    vector<HQLNode*> reducedOperands;
    reducedOperands.resize(operands.size());

    std::transform(operands.begin(), operands.end(),
                   reducedOperands.begin(),
                   HQLNodeMemFunCaller<HQLOperand, HQLNode*, &HQLNode::reduce>());

    auto partitionBound = std::partition(reducedOperands.begin(), reducedOperands.end(),
                                         HQLNodeIsSubtype<HQLNode*, AND>());
    auto it = reducedOperands.begin();

    if(it == partitionBound){ // no AND operands
        resultNode = new LogicAndNode(shared_ptr<HQLNode>(*it++),
                                       shared_ptr<HQLNode>(*it++));
        while(it != reducedOperands.end()){
            resultNode->push_operand(HQLOperand(shared_ptr<HQLNode>(*it++)));
        }
    } else { // has one or more AND operands, expand them
        resultNode = *it++;
        while(it != partitionBound){
            resultNode->push_operand((*it)->get_operands());
            delete *it++;
        }
        while(it != reducedOperands.end()){
            resultNode->push_operand(HQLOperand(shared_ptr<HQLNode>(*it++)));
        }
    }

    size_t notCount = std::count_if(resultNode->get_operands().begin(),
                                     resultNode->get_operands().end(),
                                     HQLNodeIsSubtype<HQLOperand, NOT>());
    if(notCount <= 1){
        if(resultNode->validate()){
            return resultNode;
        }
        delete resultNode;
        return new ErrorNode(error_info + "[to fix 1]");
    }

    vector<HQLOperand> operandsList = resultNode->get_operands();
    delete resultNode;
    auto obound = std::partition(operandsList.begin(), operandsList.end(),
                                  HQLNodeIsSubtype<HQLOperand, NOT>());
    auto oit = operandsList.begin();
    resultNode = new LogicOrNode((oit++)->as_node()->get_operand(0).as_node(),
                                 (oit++)->as_node()->get_operand(0).as_node());
    while(oit != obound){
        resultNode->push_operand((oit++)->as_node()->get_operand(0));
    }
    resultNode = new LogicNotNode(shared_ptr<HQLNode>(resultNode));
    if(oit != operandsList.end()){
        resultNode = new LogicAndNode(shared_ptr<HQLNode>(resultNode), (oit++)->as_node());
        while(oit != operandsList.end()){
            resultNode->push_operand(*oit++);
        }
    }

    if(resultNode->validate()){
        return resultNode;
    }
    delete resultNode;
    return new ErrorNode(error_info + "[to fix 2]");
}

HQLNode* LogicAndNode::copy()
{
    return new LogicAndNode(*this);
}

const string LogicAndNode::to_hql() const
{
    vector<HQLOperand>::const_iterator it = operands.begin();
    vector<HQLOperand>::const_iterator last = --operands.end();
    string result;

    while(it != last){
        result += "(" + it->as_node()->to_hql() + ") AND ";
        ++it;
    }
    result += "(" + it->as_node()->to_hql() + ")";
    return result;
}

const string LogicAndNode::cache_key(bool doResultReduce) const
{
    if(doResultReduce){
        vector<HQLOperand> tempOperands = operands;
        std::sort(tempOperands.begin(), tempOperands.end(),
                  HQLNodeIsCacheKeyLess<HQLOperand>());
        auto uniqueEnd = std::unique(tempOperands.begin(), tempOperands.end(),
                                      HQLNodeIsCacheKeyEquals<HQLOperand>());
        tempOperands.resize(uniqueEnd - tempOperands.begin());

        if(tempOperands.size() > 1){
            return LogicAndNode(tempOperands).cache_key(false);
        } else if(tempOperands.size() == 1){
            return tempOperands[0].as_node()->cache_key();
        }
    }

    vector<string> cacheKeys(operands.size());
    std::transform(operands.begin(), operands.end(), cacheKeys.begin(),
                   std::bind2nd(HQLNodeConstMemFunCaller1<HQLOperand, const string, bool, &HQLNode::cache_key>(), false));
    std::sort(cacheKeys.begin(), cacheKeys.end());

    string result = "&[";
    for(auto it = cacheKeys.begin(); it != cacheKeys.end(); ++it){
        result += *it;
        if(it + 1 != cacheKeys.end()) result += ",";
    }
    result += "]";
    return result;
}

const set<string> LogicAndNode::get_ctypes() const
{
    set<string> result = get_rtypes();
    if(!result.empty()) return result;
    return operands[0].as_node()->get_ctypes();
}

const set<string> LogicAndNode::get_rtypes() const
{
    set<string> result;
    for(const auto& operand : operands){
        if(operand.get_type() != HQLOperand::NODE) continue;
        set<string> ext = operand.as_node()->get_rtypes();
        result.insert(ext.begin(), ext.end());
    }
    return result;
}

ExtraMatchDataInfo LogicAndNode::get_xmdinfo() const
{
    ExtraMatchDataInfo result;

    size_t foreignKeyCount = std::count_if(operands.begin(), operands.end(),
                                           HQLNodeIsType<HQLOperand, SLFK>());
    size_t relationCount = std::count_if(operands.begin(), operands.end(),
                                          HQLNodeIsType<HQLOperand, RL>());

    if(foreignKeyCount == 0 && relationCount == 0){
        // Simple ANDs, no Extra Data needed
    } else if(foreignKeyCount == 1 && relationCount == 0){
        string hostType, guestType, foreignKeyName;

        for(const auto& operand : operands){
            if(operand.as_node()->get_type() == HQLNode::SLFK){
                hostType = operand.as_node()->get_atype();
                guestType = operand.as_node()->get_etype();
                foreignKeyName = *(operand.as_node()->get_operand(1).as_str());
                break;
            }
        }

        for(const auto& operand : operands){
            if(operand.as_node()->get_type() != HQLNode::SLFK){
                string etype = operand.as_node()->get_etype();
                if(etype == hostType){
                    // No Extra Data needed
                } else if(etype == guestType){
                    result.add_key(foreignKeyName);
                }
            }
        }
    } else if(foreignKeyCount == 0 && relationCount == 1){
        // 1-rel ANDs
    } else if(foreignKeyCount == 0 && relationCount > 1){
        if(relationCount == 2){
            result += operands[0].as_node()->get_xmdinfo();
            result += operands[1].as_node()->get_xmdinfo();
            result.relation_info = 2;
        }
    } else {
        // Error node
    }

    return result;
}

const map<uint64_t, set<string>> LogicAndNode::match(const Model &model, ModelGetter *getter)
{
    map<uint64_t, set<string>> result, rel;
    if(model.attr<bool>("deleted")) return result;

    size_t foreignKeyCount = std::count_if(operands.begin(), operands.end(),
                                           HQLNodeIsType<HQLOperand, SLFK>());
    size_t relationCount = std::count_if(operands.begin(), operands.end(),
                                          HQLNodeIsType<HQLOperand, RL>());

    if(foreignKeyCount == 0 && relationCount == 0){
        vector<map<uint64_t, set<string>>> matches(operands.size());
        set<uint64_t> foundNodes, unmatchedNodes;
        matches.resize(operands.size());

        for(size_t i = 0; i < operands.size(); ++i){
            matches[i] = operands[i].as_node()->match(model, getter);
            for(const auto& match : matches[i]){
                foundNodes.insert(match.first);
            }
        }

        for(const auto& foundNode : foundNodes){
            for(size_t i = 0; i < matches.size(); ++i){
                rel = matches[i];
                if(rel.find(foundNode) == rel.end() || rel[foundNode].empty()){
                    unmatchedNodes.insert(foundNode);
                }
            }
        }

        for(const auto& unmatchedNode : unmatchedNodes){
            foundNodes.erase(unmatchedNode);
        }

        for(const auto& foundNode : foundNodes){
            uint64_t fn = foundNode;
            vector<vector<shared_ptr<HQLNode>>> fnMatches;
            vector<size_t> dimensions, cycles;
            dimensions.reserve(matches.size());
            cycles.reserve(matches.size());

            for(size_t i = matches.size(); i > 0; --i){
                dimensions[i - 1] = matches[i - 1][fn].size();
                cycles[i - 1] = (i == matches.size()) ? 1 : dimensions[i] * cycles[i];
            }

            size_t matchedCount = cycles[0] * dimensions[0];
            fnMatches.resize(matchedCount, vector<shared_ptr<HQLNode>>(matches.size()));

            for(size_t i = 0; i < matches.size(); ++i){
                set<string> matchedItems = matches[i][fn];
                for(size_t k = 0; k < matchedCount / (cycles[i] * dimensions[i]); k++){
                    size_t j = 0;
                    for(const auto& item : matchedItems){
                        for(size_t t = 0; t < cycles[i]; ++t){
                            size_t row = k * cycles[i] * dimensions[i] + j * cycles[i] + t;
                            fnMatches[row][i] = make_shared<MatchedNode>(item);
                        }
                        j++;
                    }
                }
            }

            for(const auto& match : fnMatches){
                result[fn].insert(LogicAndNode(match).cache_key(true));
            }
        }
    } else if(foreignKeyCount == 1 && relationCount == 0){
        vector<vector<shared_ptr<HQLNode>>> matches(operands.size());
        map<uint64_t, set<string>> tempMatched;
        matches.resize(operands.size());
        string hostType, guestType;
        uint64_t hostFn = model.fullname();
        uint64_t guestFn = 0;
        JSONNode jsonNode;
        Model guestModel(jsonNode);

        for(size_t i = 0; i < operands.size(); ++i){
            if(operands[i].as_node()->get_type() == HQLNode::SLFK){
                hostType = operands[i].as_node()->get_atype();
                guestType = operands[i].as_node()->get_etype();
                string foreignKey = *(operands[i].as_node()->get_operand(1).as_str());
                guestFn = model.attr<uint64_t>(foreignKey);
                if(TypeConfig::type_id(hostType) == 0){
                    hostFn = FULLNAME_SET_CAT(hostFn);
                    guestFn = FULLNAME_SET_CAT(guestFn);
                }
                guestModel = ASTUtil::get_model(guestFn, getter);
                tempMatched = operands[i].as_node()->match(model, getter);
                if(tempMatched[guestFn].empty()) return result;

                for(const auto& item : tempMatched[guestFn]){
                    matches[i].push_back(make_shared<MatchedNode>(item));
                }
            }
        }

        for(size_t i = 0; i < operands.size(); ++i){
            if(operands[i].as_node()->get_type() != HQLNode::SLFK){
                string etype = operands[i].as_node()->get_etype();
                if(etype == hostType){
                    tempMatched = operands[i].as_node()->match(model, getter);
                    if(tempMatched[hostFn].empty()){
                        return result;
                    }
                    for(const auto& item : tempMatched[hostFn]){
                        matches[i].push_back(make_shared<MatchedNode>(item));
                    }
                } else if(etype == guestType){
                    tempMatched = operands[i].as_node()->match(guestModel, getter);
                    if(tempMatched[guestFn].empty()){
                        return result;
                    }
                    for(const auto& item : tempMatched[guestFn]){
                        matches[i].push_back(make_shared<MatchedNode>(item));
                    }
                }
            }
        }

        vector<size_t> dimensions, cycles;
        dimensions.resize(matches.size());
        cycles.resize(matches.size());
        for(size_t i = matches.size(); i > 0; --i){
            dimensions[i - 1] = matches[i - 1].size();
            cycles[i - 1] = (i == matches.size()) ? 1 : dimensions[i] * cycles[i];
        }

        size_t matchedCount = cycles[0] * dimensions[0];
        vector<vector<shared_ptr<HQLNode>> fnMatches(matchedCount, vector<shared_ptr<HQLNode>>(matches.size()));

        for(size_t i = 0; i < matches.size(); ++i){
            vector<shared_ptr<HQLNode>> matchedItems = matches[i];
            for(size_t k = 0; k < matchedCount / (cycles[i] * dimensions[i]); k++){
                for(size_t j = 0; j < matchedItems.size(); j++){
                    for(size_t t = 0; t < cycles[i]; ++t){
                        size_t row = k * cycles[i] * dimensions[i] + j * cycles[i] + t;
                        fnMatches[row][i] = matchedItems[j];
                    }
                }
            }
        }

        for(const auto& match : fnMatches){
            result[guestFn].insert(LogicAndNode(match).cache_key(true));
        }
    } else if(foreignKeyCount == 0 && relationCount == 1){
        // 1-rel ANDs
    } else if(foreignKeyCount == 0 && relationCount > 1){
        if(relationCount == 2){
            do {
                string rel0 = operands[0].as_node()->get_operand(0).as_node()->get_etype();
                string rel1 = operands[1].as_node()->get_operand(0).as_node()->get_etype();
                if(rel0 != rel1) break;
                if(TypeConfig::left_type(rel0) != TypeConfig::right_type(rel0)) break;

                string reversedRelKey = "R" + num2str(model.fullname() & 0xFF) + "_" + num2str(model.right()) + "_" + num2str(model.left());
                vector<uint64_t> relations = ASTUtil::get_relations(reversedRelKey, getter);
                if(relations.empty()) break;
                Model relatedModel = ASTUtil::get_model(relations[0], getter);

                map<uint64_t, set<string>> a0 = operands[0].as_node()->match(model, getter);
                map<uint64_t, set<string>> a1 = operands[1].as_node()->match(model, getter);

                map<uint64_t, set<string>> d0 = operands[0].as_node()->match(relatedModel, getter);
                map<uint64_t, set<string>> d1 = operands[1].as_node()->match(relatedModel, getter);

                for(const auto& match : a0){
                    shared_ptr<HQLNode> leftNode(new MatchedNode(*match.second.begin()));
                    if(a1[match.first].size() > 0){
                        shared_ptr<HQLNode> rightNode(new MatchedNode(*a1[match.first].begin()));
                        result[match.first].insert(LogicAndNode(leftNode, rightNode).cache_key());
                    }
                    if(d1[match.first].size() > 0){
                        shared_ptr<HQLNode> rightNode(new MatchedNode(*d1[match.first].begin()));
                        result[match.first].insert(LogicAndNode(leftNode, rightNode).cache_key());
                    }
                }

                for(const auto& match : d0){
                    shared_ptr<HQLNode> leftNode(new MatchedNode(*match.second.begin()));
                    if(a1[match.first].size() > 0){
                        shared_ptr<HQLNode> rightNode(new MatchedNode(*a1[match.first].begin()));
                        result[match.first].insert(LogicAndNode(leftNode, rightNode).cache_key());
                    }
                    if(d1[match.first].size() > 0){
                        shared_ptr<HQLNode> rightNode(new MatchedNode(*d1[match.first].begin()));
                        result[match.first].insert(LogicAndNode(leftNode, rightNode).cache_key());
                    }
                }

            } while(0);
        }
    } else {
        // Error node
    }
    return result;
}

bool LogicAndNode::validate() const
{
    for(const auto& operand : operands){
        if(!operand.as_node()->validate()){
            error_info = "bad sub statement: " + operand.as_node()->to_hql();
            return false;
        }
    }

    vector<string> foreignKeyTypes = has_semantic_fk();
    if(foreignKeyTypes.size() != 2){ // no SLFK nodes
        auto it = operands.begin();
        etype = (it++)->as_node()->get_etype();
        while(it != operands.end()){
            if((it++)->as_node()->get_etype() != etype){
                error_info = "Logic operands have different etypes";
                return false;
            }
        }
        return true;
    }

    etype = foreignKeyTypes[0];
    atype = foreignKeyTypes[1];

    vector<HQLOperand> tempOperands = operands;
    auto obound = std::partition(tempOperands.begin(), tempOperands.end(),
                                  HQLNodeIsType<HQLOperand, SLFK>());
    auto oit = tempOperands.begin();

    while(oit != obound){
        if(oit->as_node()->get_etype() != etype ||
           oit->as_node()->get_atype() != atype){
            error_info = "Logic operands have different etypes or atypes";
            return false;
        }
        oit++;
    }
    if(oit != operands.end()){
        if(oit->as_node()->get_etype() == etype){
            // This node is valid
        } else if(oit->as_node()->get_etype() == atype){
            if(oit->as_node()->get_target() == EXPLICIT){
                error_info = "Logic operands have different etypes or atypes";
                return false;
            }
            // This node is valid
        }
    }
    return true;
}

bool LogicAndNode::has_semantic_each() const
{
    return std::find_if(operands.begin(), operands.end(),
                        HQLNodeConstMemFunCaller<HQLOperand, bool, &HQLNode::has_semantic_each>())
        != operands.end();
}

pair<string, uint64_t> LogicAndNode::time_in() const
{
    for(const auto& operand : operands){
        pair<string, uint64_t> result = operand.as_node()->time_in();
        if(!result.first.empty()) return result;
    }
    return make_pair("", 0UL);
}

vector<string> LogicAndNode::has_semantic_fk() const
{
    for(const auto& operand : operands){
        vector<string> result = operand.as_node()->has_semantic_fk();
        if(result.size() == 2) return result;
    }
    return vector<string>();
}

/* LogicOrNode */

LogicOrNode::LogicOrNode(shared_ptr<HQLNode> leftOperand,
                         shared_ptr<HQLNode> rightOperand,
                         TARGET_TYPE targetType):
    HQLNode(LOGIC, OR, targetType)
{
    push_operand(HQLOperand(leftOperand));
    push_operand(HQLOperand(rightOperand));
}

LogicOrNode::LogicOrNode(const LogicOrNode &other):
    HQLNode(other)
{
}

const LogicOrNode& LogicOrNode::operator=(const LogicOrNode& other)
{
    if(this == &other) return *this;
    HQLNode::operator=(other);
    return *this;
