HQLNode* LogicNotNode::reduce()
{
    if(!validate()){
        return new ErrorNode(error_info);
    }

    shared_ptr<HQLNode> operandNode = operands[0].as_node();
    HQLNode *reducedNode = operandNode->reduce();
    if(reducedNode->get_type() == LOGIC && reducedNode->get_subtype() == NOT){
        HQLNode *resultNode = reducedNode->get_operand(0).as_node()->copy();
        delete reducedNode;
        return resultNode;
    } else {
        return new LogicNotNode(shared_ptr<HQLNode>(reducedNode));
    }
}

