/* RLNode class implementation */

RLNode::RLNode(const HQLOperand &relation,
               const HQLOperand &leftOperand,
               const HQLOperand &rightOperand,
               TARGET_TYPE targetType) :
    HQLNode(RL, NORMAL, targetType)
{
    push_operand(relation);
    push_operand(leftOperand);
    push_operand(rightOperand);
}

RLNode::RLNode(const RLNode &node) :
    HQLNode(node)
{
}

const RLNode& RLNode::operator=(const RLNode& node)
{
    if (this == &node) return *this;
    HQLNode::operator=(node);
    return *this;
}

RLNode::~RLNode()
{
#ifdef DEBUG
    std::cout << "<DEBUG> HQLNode DTOR: " << this->to_hql() << std::endl;
#endif
}

HQLNode* RLNode::reduce()
{
    HQLNode *firstNode = nullptr, *secondNode = nullptr, *thirdNode = nullptr;

    if (operands[0].get_type() == HQLOperand::NODE) {
        firstNode = operands[0].as_node()->reduce();
    } else {
        return new ErrorNode("Relation can't be AUTO");
    }

    if (operands[1].get_type() == HQLOperand::NODE) {
        secondNode = operands[1].as_node()->reduce();
    } else if (operands[1].get_type() == HQLOperand::KW) {
        string type = TypeConfig::left_type(firstNode->get_etype());
        if (type.empty()) type = "bad-type";
        switch (operands[1].as_keyword()) {
            case AUTO:
                secondNode = new SLAllNode(type, IMPLICIT);
                break;
            case TAUTO:
                secondNode = new SLAllNode(type, EXPLICIT);
                break;
            case ::EACH:
                secondNode = new EachNode(type);
                break;
        }
    } else if (operands[1].get_type() == HQLOperand::FULLNAME) {
        secondNode = new FullnameNode(operands[1].as_fullname());
    }

    if (operands[2].get_type() == HQLOperand::NODE) {
        thirdNode = operands[2].as_node()->reduce();
    } else if (operands[2].get_type() == HQLOperand::KW) {
        string type = TypeConfig::right_type(firstNode->get_etype());
        if (type.empty()) type = "bad-type";
        switch (operands[2].as_keyword()) {
            case AUTO:
                thirdNode = new SLAllNode(type, IMPLICIT);
                break;
            case TAUTO:
                thirdNode = new SLAllNode(type, EXPLICIT);
                break;
            case ::EACH:
                thirdNode = new EachNode(type);
                break;
        }
    } else if (operands[2].get_type() == HQLOperand::FULLNAME) {
        thirdNode = new FullnameNode(operands[2].as_fullname());
    }

    RLNode *resultNode = new RLNode(HQLOperand(shared_ptr<HQLNode>(firstNode)),
                                     HQLOperand(shared_ptr<HQLNode>(secondNode)),
                                     HQLOperand(shared_ptr<HQLNode>(thirdNode)));

    if (!resultNode->validate()) {
        string hql = resultNode->to_hql();
        delete resultNode;
        return new ErrorNode("bad RL: " + hql);
    }
    return resultNode;
}

HQLNode* RLNode::copy()
{
    return new RLNode(*this);
}

const string RLNode::to_hql() const
{
    return "(" + operands[0].as_code_hql() + ") BETWEEN (" +
           operands[1].as_code_hql() + ") AND (" +
           operands[2].as_code_hql() + ")";
}

const string RLNode::cache_key(bool do_result_reduce) const
{
    if (operands[0].get_type() == HQLOperand::NODE &&
        operands[1].get_type() == HQLOperand::NODE &&
        operands[2].get_type() == HQLOperand::NODE) {

        string decorations[] = {"r[", "<", ",", ">]"};
        for (int i = 0; i < 3; i++) {
            if (operands[i].as_node()->get_target() == EXPLICIT) {
                decorations[i] += "*";
                break;
            }
        }
        return decorations[0] + operands[0].as_node()->cache_key() + decorations[1] +
               operands[1].as_node()->cache_key() + decorations[2] +
               operands[2].as_node()->cache_key() + decorations[3];
    } else {
        return "unReducedRL(" + to_hql() + ")";
    }
}

const set<string> RLNode::get_ctypes() const
{
    return this->get_rtypes();
}

ExtraMatchDataInfo RLNode::get_xmdinfo() const
{
    ExtraMatchDataInfo matchDataInfo;
    matchDataInfo.relation_info = 1;

    if (!(HQLNodeIsType<HQLOperand, EACH>()(operands[1]) ||
          (HQLNodeIsType<HQLOperand, SL>()(operands[1]) && 
           HQLNodeIsSubtype<HQLOperand, ALL>()(operands[1])))) {
        matchDataInfo.add_key("left");
    }
    if (!(HQLNodeIsType<HQLOperand, EACH>()(operands[2]) ||
          (HQLNodeIsType<HQLOperand, SL>()(operands[2]) && 
           HQLNodeIsSubtype<HQLOperand, ALL>()(operands[2])))) {
        matchDataInfo.add_key("right");
    }
    return matchDataInfo;
}

const set<string> RLNode::get_rtypes() const
{
    set<string> resultTypes = operands[0].as_node()->get_ctypes();
    if (operands[1].get_type() == HQLOperand::NODE) {
        set<string> additionalTypes = operands[1].as_node()->get_rtypes();
        resultTypes.insert(additionalTypes.begin(), additionalTypes.end());
    }
    if (operands[2].get_type() == HQLOperand::NODE) {
        set<string> additionalTypes = operands[2].as_node()->get_rtypes();
        resultTypes.insert(additionalTypes.begin(), additionalTypes.end());
    }
    return resultTypes;
}

const map<uint64_t, set<string>> RLNode::match(const Model &model, ModelGetter *getter)
{
    map<uint64_t, set<string>> result, relation, left, right;
    if (model.attr<bool>("deleted")) return result;

    relation = operands[0].as_node()->match(model, getter);
    uint64_t fullNameModel = model.fullname();
    uint64_t fullNameLeft = model.left();
    uint64_t fullNameRight = model.right();
    uint64_t target = 0;

    if (operands[0].as_node()->get_target() == HQLNode::EXPLICIT) {
        target = fullNameModel;
    } else if (operands[1].as_node()->get_target() == HQLNode::EXPLICIT) {
        target = fullNameLeft;
    } else if (operands[2].as_node()->get_target() == HQLNode::EXPLICIT) {
        target = fullNameRight;
    }

    if (target != fullNameModel) {
        vector<uint64_t> relations = ASTUtil::get_relations(model.rel_cache_key(), getter);
        if (relations.size() > 1 || (relations.size() == 1 && relations[0] != model.fullname())) {
            return result;
        }
    }

    if (HQLNodeIsType<HQLOperand, EACH>()(operands[1])) {
        left[fullNameLeft].insert("#" + num2str(fullNameLeft));
    } else if (HQLNodeIsType<HQLOperand, SL>()(operands[1]) && 
               HQLNodeIsSubtype<HQLOperand, ALL>()(operands[1])) {
        left[fullNameLeft].insert(operands[1].as_node()->cache_key());
    } else {
        left = operands[1].as_node()->match(ASTUtil::get_model(fullNameLeft, getter), getter);
    }

    if (HQLNodeIsType<HQLOperand, EACH>()(operands[2])) {
        right[fullNameRight].insert("#" + num2str(fullNameRight));
    } else if (HQLNodeIsType<HQLOperand, SL>()(operands[2]) && 
               HQLNodeIsSubtype<HQLOperand, ALL>()(operands[2])) {
        right[fullNameRight].insert(operands[2].as_node()->cache_key());
    } else {
        right = operands[2].as_node()->match(ASTUtil::get_model(fullNameRight, getter), getter);
    }

    for (const auto& relItem : relation[fullNameModel]) {
        for (const auto& leftItem : left[fullNameLeft]) {
            for (const auto& rightItem : right[fullNameRight]) {
                RLNode matchedNode(HQLOperand(shared_ptr<HQLNode>(new MatchedNode(relItem,
                                                                                  operands[0].as_node()->get_target()))),
                                               HQLOperand(shared_ptr<HQLNode>(new MatchedNode(leftItem,
                                                                                             operands[1].as_node()->get_target()))),
                                               HQLOperand(shared_ptr<HQLNode>(new MatchedNode(rightItem,
                                                                                             operands[2].as_node()->get_target()))));
                result[target].insert(matchedNode.cache_key());
            }
        }
    }

    return result;
}

bool RLNode::validate() const
{
    bool isValid = operands[0].as_node()->validate();
    if (!isValid) {
        error_info = "sub statement error";
        return false;
    }

    string relationType = operands[0].as_node()->get_etype();
    auto typeIterator = TypeConfig::all_types.find(relationType);
    if (typeIterator == TypeConfig::all_types.end()) {
        error_info = "bad relation type: " + relationType;
        return false;
    }
    if (typeIterator->second->id <= 128) {
        error_info = "bad relation type: " + relationType;
        return false;
    }

    // Check Left and Right operands
    HQLOperand temporaryOperands[3];
    temporaryOperands[0] = operands[0];

    string temporaryTypes[3];
    temporaryTypes[1] = TypeConfig::left_type(relationType);
    temporaryTypes[2] = TypeConfig::right_type(relationType);
    for (int i = 1; i < 3; i++) {
        switch (operands[i].get_type()) {
            case HQLOperand::KW:
                switch (operands[i].as_keyword()) {
                    case ::AUTO:
                        temporaryOperands[i] = HQLOperand(shared_ptr<HQLNode>(new SLAllNode(temporaryTypes[i], IMPLICIT)));
                        break;
                    case ::TAUTO:
                        temporaryOperands[i] = HQLOperand(shared_ptr<HQLNode>(new SLAllNode(temporaryTypes[i], EXPLICIT)));
                        break;
                    case ::EACH:
                        temporaryOperands[i] = HQLOperand(shared_ptr<HQLNode>(new EachNode(temporaryTypes[i])));
                        break;
                }
                break;
            case HQLOperand::FULLNAME:
                temporaryOperands[i] = HQLOperand(shared_ptr<HQLNode>(new FullnameNode(operands[i].as_fullname())));
                break;
            case HQLOperand::NODE:
                temporaryOperands[i] = operands[i];
                break;
            default:
                error_info = "left/right statement error";
                return false;
        }
    }

    // Validate TARGET_TYPE
    int explicitIndex = -1;
    for (int i = 0; i < 3; i++) {
        int j = (i + 1) % 3;
        int k = (i + 2) % 3;
        if (temporaryOperands[i].as_node()->get_target() == EXPLICIT) {
            if (temporaryOperands[j].as_node()->get_target() == EXPLICIT ||
                temporaryOperands[k].as_node()->get_target() == EXPLICIT) {
                error_info = "more than one EXPLICIT node";
                return false;
            }
            explicitIndex = i;
            etype = temporaryOperands[i].as_node()->get_etype();
        }
    }
    if (explicitIndex < 0) {
        error_info = "no IMPLICIT etype in statement: " + to_hql();
        return false;
    }
    if (explicitIndex > 0) {
        if (temporaryOperands[3 - explicitIndex].as_node()->get_type() != HQLNode::EACH) {
            error_info = "cannot collect entities by relation between SL and SL";
            return false;
        }
    }

    return true;
}

bool RLNode::has_semantic_each() const
{
    HQLNode *node = nullptr;
    for (int i = 0; i < 3; i++) {
        if (operands[i].get_type() == HQLOperand::NODE) {
            node = operands[i].as_node()->reduce();
            bool hasEach = node->has_semantic_each();
            delete node;
            if (hasEach) {
                return true;
            }
        } else if (operands[i].get_type() == HQLOperand::KW && operands[i].as_keyword() == ::EACH) {
            return true;
        }
    }
    return false;
}

