    return "SELECT " + *operands[0].as_str() + "." + *operands[1].as_str() + " AS " + prefix + *operands[2].as_str() +
           " WHERE " + *operands[3].as_str() + " " + operands[4].as_coop() + " " + operands[5].as_code_hql();
}

