const map<uint64_t, set<string>> SLFKCondNode::match(const Model &model, ModelGetter *getter) {
    map<uint64_t, set<string>> result;
    if (model.attr<bool>("deleted")) return result;

    uint64_t foreignKeyName = model.attr<uint64_t>(*operands[1].as_str());
    string type = model.type();
    string attribute = *operands[3].as_str();
    JSONNode valueNode = model.attr<JSONNode>(attribute);

    if (valueNode.type() == JSON_NODE && valueNode.size() <= 0) {
        return result;
    }

    if (!TypeConfig::is_subtype(type, *operands[0].as_str())) {
        return result;
    }

    if (TypeConfig::type_id(*operands[0].as_str()) == 0) {
        foreignKeyName = FULLNAME_SET_CAT(foreignKeyName);
    }

    if (has_semantic_each()) {
        switch (operands[4].as_coop_type()) {
            case COND_OPER::EQ: {
                HQLOperand operandValue = HQLOperand(valueNode);
                SLFKCondNode conditionNode(type, *operands[1].as_str(), etype, attribute, operands[4], operandValue);
                result[foreignKeyName].insert(conditionNode.cache_key());
                break;
            }
            case COND_OPER::CONTAINS: {
                string separator = operands[5].as_str_array()->at(1);
                string valueString = valueNode.as_string();
                string unit;
                string::size_type start = 0, end = 0;

                while (end != string::npos) {
                    end = valueString.find_first_of(separator, start);
                    unit = (end == string::npos) ? valueString.substr(start) : valueString.substr(start, end - start);
                    start = end + 1;

                    if (unit.empty()) continue;

                    vector<string> *arguments = new vector<string>;
                    arguments->push_back("\"" + unit + "\"");
                    arguments->push_back(separator);
                    HQLOperand operandValue = HQLOperand(arguments, HQLOperand::CONTAINS_ARG);

                    SLFKCondNode conditionNode(type, *operands[1].as_str(), etype, attribute, operands[4], operandValue);
                    result[foreignKeyName].insert(conditionNode.cache_key());
                }
                break;
            }
            default:
                return result;
        }
    } else {
        if (operands[4].predicate(operands[5], valueNode)) {
            result[foreignKeyName].insert(cache_key());
        }
    }

    return result;
}

bool SLFKCondNode::validate() const {
    if (!HQLNode::validate()) {
        return false;
    }
    if (!TypeConfig::has_type(*operands[0].as_str())) {
        error_info = "bad fk-host type";
        return false;
    }
    if (operands[5].get_type() == HQLOperand::KW &&
        operands[5].as_keyword() == ::EACH &&
        operands[4].as_coop_type() != COND_OPER::EQ) {
        error_info = "cannot use EACH as (non-eq) operand";
        return false;
    }
    return true;
}

bool SLFKCondNode::has_semantic_each() const {
    if (operands[5].get_type() == HQLOperand::KW) {
        return operands[5].as_keyword() == ::EACH;
    }
    if (operands[5].get_type() == HQLOperand::CONTAINS_ARG) {
        string arg1 = (operands[5].as_str_array())->at(0);
        return arg1.size() == 1 && arg1[0] == 0;
    }
    return false;
}

pair<string, uint64_t> SLFKCondNode::time_in() const {
    if (operands[4].as_coop_type() != COND_OPER::TIME_IN || has_semantic_each()) {
        return make_pair("", 0UL);
    }
    return make_pair(*operands[3].as_str(), static_cast<uint64_t>(operands[5].as_num()));
}

vector<string> SLFKCondNode::has_semantic_fk() const {
    return {get_etype(), get_atype()};
}

