{
    map<uint64_t, set<string>> result;
    if (model.attr<bool>("deleted")) return result;

    uint64_t fullName = model.fullname();
    string type = model.type();
    string attribute = *operands[1].as_str();
    JSONNode valueNode = model.attr<JSONNode>(attribute);

    if (valueNode.type() == JSON_NODE && valueNode.size() <= 0) {
        return result;
    }

    if (!TypeConfig::is_subtype(type, etype)) {
        return result;
    }

    if (TypeConfig::type_id(get_etype()) == 0) {
        fullName = FULLNAME_SET_CAT(fullName);
    }

    if (this->has_semantic_each()) {
        switch (operands[2].as_coop_type()) {
            case COND_OPER::EQ: {
                HQLOperand operandValue = HQLOperand(valueNode);
                SLCondNode conditionNode = SLCondNode(etype, attribute, operands[2], operandValue);
                result[fullName].insert(conditionNode.cache_key());
                break;
            }
            case COND_OPER::CONTAINS: {
                string separator = operands[3].as_str_array()->at(1);
                string valueString = valueNode.as_string();
                string unit;
                string::size_type start = 0, end = 0;

                while (end != string::npos) {
                    end = valueString.find_first_of(separator, start);
                    unit = (end == string::npos) ? valueString.substr(start) : valueString.substr(start, end - start);
                    start = end + 1;

                    if (unit.empty()) continue;

                    vector<string> *arguments = new vector<string>;
                    arguments->push_back("\"" + unit + "\"");
                    arguments->push_back(separator);

                    HQLOperand operandValue = HQLOperand(arguments, HQLOperand::CONTAINS_ARG);
                    SLCondNode conditionNode = SLCondNode(etype, attribute, operands[2], operandValue);
                    result[fullName].insert(conditionNode.cache_key());
                }
                break;
            }
            default: {
                return result;
            }
        }
    } else {
        if (operands[2].predicate(operands[3], valueNode)) {
            result[fullName].insert(this->cache_key());
        }
    }

    return result;
}

bool SLCondNode::validate() const
{
    if (!HQLNode::validate()) {
        return false;
    }
    if (operands[3].get_type() == HQLOperand::KW &&
        operands[3].as_keyword() == ::EACH &&
        operands[2].as_coop_type() != COND_OPER::EQ) {
        error_info = "cannot use EACH as a non-equal operand";
        return false;
    }
    return true;
}

bool SLCondNode::has_semantic_each() const
{
    if (operands[3].get_type() == HQLOperand::KW) {
        return operands[3].as_keyword() == ::EACH;
    }
    if (operands[3].get_type() == HQLOperand::CONTAINS_ARG) {
        string arg1 = (operands[3].as_str_array())->at(0);
        return arg1.size() == 1 && arg1[0] == 0;
    }
    return false;
}

pair<string, uint64_t> SLCondNode::time_in() const
{
    if (operands[2].as_coop_type() != COND_OPER::TIME_IN || has_semantic_each()) {
        return make_pair("", 0UL);
    }
    return make_pair(*operands[1].as_str(), static_cast<uint64_t>(operands[3].as_num()));
}

