// Class representing a daemon process that manages multiple programs.
class Daemon {
private:
  PmanConf configuration_;
  PidFile pidFile_;
  std::vector<Program> programList_;
  std::queue<Task> taskQueue_;

  // Initializes the daemon process.
  void daemonize();

  // Registers signal handler for abort signal.
  void registerAbortSignal();

  // Registers signal handler for child process termination.
  void registerChildSignal();

  // Handles the termination of child processes.
  void handleChildSignal();

  // Retrieves a program by its process ID.
  Program *findProgramByPid(int pid);

  // Cleans up resources and state.
  void cleanupResources();

  // Starts a specified program.
  void launchProgram(Program &program);

  // Starts a program identified by its name.
  void launchProgramByName(std::string name);

  // Stops a specified program.
  void terminateProgram(Program &program);

  // Stops a program identified by its name.
