  Daemon(PmanConf configuration, std::vector<ProgramConf> programConfigurations);

  std::mutex mutex_;

  // Sets up the daemon environment.
  void initialize();

  // Runs the main loop of the daemon.
  int executeLoop();

  // Adds a task to the task queue.
  void enqueueTask(Task task) { this->taskQueue_.push(task); }

  // Checks if a task with the specified ID exists.
