QDebug operator<<(QDebug debugStream, const Device &device)
{
    debugStream.nospace() << "Device(";
    debugStream.nospace() << "\n  id: " << device.id;
    debugStream.nospace() << "\n  modalias: " << device.modalias;
    debugStream.nospace() << "\n  model: " << device.model;
    debugStream.nospace() << "\n  vendor: " << device.vendor;

    // Log each driver associated with the device
    foreach (const Driver &driver, device.drivers) {
        debugStream.nospace() << "\n  Driver(" << driver.packageName;
        debugStream.nospace() << " recommended[" << driver.isRecommended << "]";
        debugStream.nospace() << " free[" << driver.isFree << "]";
        debugStream.nospace() << " fromDistro[" << driver.isFromDistro << "]";
        debugStream.nospace() << " builtin[" << driver.isBuiltin << "]";
        debugStream.nospace() << " manualInstall[" << driver.isManualInstall << "]";
        debugStream.nospace() << " fuzzyActive[" << driver.isFuzzyActive << "]";
        debugStream.nospace() << " package[" << driver.package << "]";
        debugStream.nospace() << ")";
    }
    debugStream.nospace() << "\n)";
    return debugStream.maybeSpace();
}

const QDBusArgument &operator>>(const QDBusArgument &argument, Driver &driver)
{
    argument.beginMap();
    while (!argument.atEnd()) {
        QString key;
        bool value;
        argument.beginMapEntry();
        argument >> key >> value;

        // Assign values based on the key
        if (key == QLatin1String("recommended")) {
            driver.isRecommended = value;
        } else if (key == QLatin1String("free")) {
            driver.isFree = value;
        } else if (key == QLatin1String("from_distro")) {
            driver.isFromDistro = value;
        } else if (key == QLatin1String("builtin")) {
            driver.isBuiltin = value;
        } else if (key == QLatin1String("manual_install")) {
            driver.isManualInstall = value;
        }
        argument.endMapEntry();
    }

    argument.endMap();
    return argument;
}

const QDBusArgument &operator>>(const QDBusArgument &argument, QList<Driver> &driverList)
{
    argument.beginMap();
    while (!argument.atEnd()) {
        Driver driver;
        argument.beginMapEntry();
        argument >> driver.packageName >> driver;
        argument.endMapEntry();
        driverList.append(driver);
    }
    argument.endMap();
    return argument;
}

const QDBusArgument &operator>>(const QDBusArgument &argument, Device &device)
{
    argument.beginMap();

    while (!argument.atEnd()) {
        QString key;
        QVariant value;

        argument.beginMapEntry();
        argument >> key >> value;

        // Assign device properties based on the key
        if (key == QLatin1String("modalias")) {
            device.modalias = value.toString();
        } else if (key == QLatin1String("vendor")) {
            device.vendor = value.toString();
        } else if (key == QLatin1String("model")) {
            device.model = value.toString();
        } else if (value.canConvert<QDBusArgument>()) {
            QDBusArgument arg = value.value<QDBusArgument>();
            arg >> device.drivers;
        }

        argument.endMapEntry();
    }

    argument.endMap();
    return argument;
}

const QDBusArgument &operator>>(const QDBusArgument &argument, DeviceList &deviceList)
{
    qDebug() << Q_FUNC_INFO;
    argument.beginMap();
    while (!argument.atEnd()) {
        Device device;
        argument.beginMapEntry();
        argument >> device.id >> device;
        argument.endMapEntry();
        deviceList.append(device);
        qDebug() << device;
    }
    argument.endMap();
    return argument;
}

QDBusArgument &operator<<(QDBusArgument &argument, const DeviceList &deviceList)
{
    Q_UNUSED(deviceList);
    qDebug() << Q_FUNC_INFO << "is noop";
    argument.beginMap(QVariant::String, QVariant::Map);
    argument.endMap();
    return argument;
}

