/**
 * \class Data
 * 
 * Class to manage a date, ensuring its validity including leap years.
 */
Data::Data() {}

Data::Data(int dia, std::string mes, int ano) throw (std::invalid_argument) {
    set(dia, mes, ano);
}

void Data::validar(int dia, std::string mes, int ano) throw (std::invalid_argument) {
    if (dia < 1 || dia > 31) {
        throw std::invalid_argument("Dia invalido - Deve estar entre 1 e 31");
    }
    if (ano < 2000 || ano >= 2100) {
        throw std::invalid_argument("Ano invalido - Deve estar entre 2000 e 2100");
    }
    if (mes == "fev") {
        if ((ano % 4 == 0 && dia > 29) || (ano % 4 != 0 && dia > 28)) {
            throw std::invalid_argument("Dia invalido - Fevereiro cóm apenas 28 ou 29 dias");
        }
    } else if ((mes == "abr" || mes == "jun" || mes == "set" || mes == "nov") && dia > 30) {
        throw std::invalid_argument("Dia invalido - Mes cóm apenas 30 dias");
    }
}

void Data::set(int dia, std::string mes, int ano) throw (std::invalid_argument) {
    validar(dia, mes, ano);
    this->dia = dia;
    this->mes = mes;
    this->ano = ano;
}

int Data::getDia() const {
    return dia;
}

std::string Data::getMes() const {
    return mes;
}

int Data::getAno() const {
    return ano;
}

int Data::mes_number(const std::string &o_mes) throw (std::invalid_argument) {
    if (o_mes == "jan") return 1;
    if (o_mes == "fev") return 2;
    if (o_mes == "mar") return 3;
    if (o_mes == "abr") return 4;
    if (o_mes == "mai") return 5;
    if (o_mes == "jun") return 6;
    if (o_mes == "jul") return 7;
    if (o_mes == "ago") return 8;
    if (o_mes == "set") return 9;
    if (o_mes == "out") return 10;
    if (o_mes == "nov") return 11;
    if (o_mes == "dez") return 12;
    throw std::invalid_argument("O mes passado nao esta dentre os possiveis");
}

bool Data::operator<(Data &dt) {
    if (this->getAno() != dt.getAno()) {
        return this->getAno() < dt.getAno();
    }
    if (this->mes_number(this->getMes()) != Data::mes_number(dt.getMes())) {
        return this->mes_number(this->getMes()) < Data::mes_number(dt.getMes());
    }
    return this->getDia() < dt.getDia();
}

std::ostream& operator<<(std::ostream& os, const Data& t) {  
    os << t.getDia() << " " << t.getMes() << " " << t.getAno();
