/**
 * \class Senha
 * 
 * Class to manage a password, ensuring its validity.
 */
Senha::Senha() {}

Senha::Senha(std::string senha) throw (std::invalid_argument) {
    set(senha);
}

void Senha::validar(std::string senha) throw (std::invalid_argument) {
    bool upper = false, lower = false, digit = false, simbol = false;
    if (senha.size() != 8) {
        throw std::invalid_argument("Senha invalida - Deve-se ter 8 caracteres");
    }
    for (char ch : senha) {
        if (isupper(ch)) upper = true;
        else if (islower(ch)) lower = true;
        else if (isdigit(ch)) digit = true;
        else if (ch == '!' || ch == '#' || ch == '$' || ch == '%' || ch == '&') simbol = true;
    }
    if (!upper) throw std::invalid_argument("Senha invalida - Nao ha nenhuma letra maiuscula");
    if (!lower) throw std::invalid_argument("Senha invalida - Nao ha nenhuma letra minuscula");
    if (!digit) throw std::invalid_argument("Senha invalida - Nao ha nenhum numero");
    if (!simbol) throw std::invalid_argument("Senha invalida - Nao ha nenhum simbolo");
    for (size_t i = 0; i < senha.size() - 1; i++) {
        for (size_t j = i + 1; j < senha.size(); j++) {
            if (senha[i] == senha[j]) {
                throw std::invalid_argument("Senha invalida - Existe caracter repetido");
            }
        }
    }
}

void Senha::set(std::string senha) throw (std::invalid_argument) {
    validar(senha);
    this->senha = senha;
}

std::string Senha::get() const {
    return senha;
}

