    os << password.get();
    return os;  
}  

std::istream& operator>>(std::istream& is, Senha& password) {  
    std::string sen;
    is >> sen;
    password.set(sen);
    return is;  
}

bool Senha::operator==(const Senha &senha) {
    return senha.get() == get();
}

