{
    try {
        string config_file;
        string target_file;
        string input_directory;
        string staging_directory;
        string output_directory;
        string google_maps_api_key;

        // Define command line options
        po::options_description generic_options("Generic options");
        generic_options.add_options()
            ("version,v", "print version string")
            ("help,h", "produce help message")
            ("config,c", po::value<string>(&config_file)->default_value(getenv("HOME") + string("/.fby/config.ini")),
                  "configuration file name")
            ("doeverything", "rebuild the web site")
            ("dowikifiles", "process the wiki files")
            ("dodirtyfiles", "process the dirty files")
            ("dochangedfiles", "process the changed files")
            ("scanwikifiles", "scan the wiki files")
            ("scanimages", "scan the image files")
            ("scandplfiles", "scan the DPL files")
            ("rebuilddetached", "fork and do everything")
            ("teststuff", "execute random test hooks")
            ("getwikifiles", "retrieve a list of all wiki files")
            ("writewikifile", po::value<string>(&target_file), "wiki file to write to")
            ("writeimagefile", po::value<string>(&target_file), "image file to write to")
            ("readwikifile", po::value<string>(&target_file), "wiki file to read from")
            ("loadexifdata", po::value<string>(&target_file), "load EXIF data for a single image")
            ("verifywikilink", po::value<string>(&target_file), "extract wiki link text from a link")
            ("showwikistatus", po::value<string>(&target_file), "retrieve status record for a wiki entry")
            ("loadjpegdata", po::value<string>(&target_file), "load JPEG data for a wiki entry")
            ("scanwikifile", po::value<string>(&target_file), "scan specified file for links")
            ("dowikifile", po::value<string>(&target_file), "process specified file for links")
            ("markcontentdirty", po::value<string>(&target_file), "mark specified wiki page as dirty")
            ("markreferencesdirty", po::value<string>(&target_file), "mark specified wiki page references as dirty");

        // Define configuration options
        po::options_description config_options("Configuration");
        config_options.add_options()
            ("input_directory", po::value<string>(&input_directory), "directory containing .wiki files")
            ("staging_directory", po::value<string>(&staging_directory), "directory for staging HTML files")
            ("html_directory", po::value<string>(&output_directory), "final output directory for web server")
            ("google_maps_api_key", po::value<string>(&google_maps_api_key), "Google Maps API key");

        // Define hidden options
        po::options_description hidden_options("Hidden options");
        hidden_options.add_options()
            ("input-file", po::value<vector<string>>(), "input file");

        po::options_description cmdline_options;
        cmdline_options.add(generic_options).add(config_options).add(hidden_options);

        po::options_description config_file_options;
        config_file_options.add(config_options).add(hidden_options);

        po::options_description visible_options("Allowed options");
        visible_options.add(generic_options).add(config_options);

        po::positional_options_description positional_options;
        po::variables_map variables_map;
        store(po::command_line_parser(argc, argv).options(cmdline_options).positional(positional_options).run(), variables_map);
        notify(variables_map);

        ifstream config_stream(config_file.c_str());
        if (!config_stream) {
            cout << "Cannot open config file: " << config_file << "\n";
            return 0;
        } else {
            store(parse_config_file(config_stream, config_file_options), variables_map);
            notify(variables_map);
        }

        if (variables_map.count("help")) {
            cout << visible_options << "\n";
            return 0;
        }

        if (variables_map.count("version")) {
            cout << "Multiple sources example, version 1.0\n";
            return 0;
        }

        // Initialize Wiki object with database connection
        WikiPtr wiki(new Wiki(new FbyPostgreSQLDB("dbname='flutterbynet' user='danlyke' password='danlyke'")));
