        if (variables_map.count("dowikifiles")) {
            wiki->DoWikiFiles();
        }
        if (variables_map.count("getwikifiles")) {
            wiki->GetWikiFiles();
        }
        if (variables_map.count("writewikifile")) {
            wiki->WriteWikiFile(target_file);
        }
        if (variables_map.count("writeimagefile")) {
            wiki->WriteImageFile(target_file);
        }
        if (variables_map.count("readwikifile")) {
            wiki->ReadWikiFile(target_file);
        }
        if (variables_map.count("rebuilddetached")) {
            wiki->RebuildDetached();
        }
        if (variables_map.count("importkml")) {
            wiki->ImportKML(target_file);
        }
        if (variables_map.count("dodirtyfiles")) {
            wiki->DoDirtyFiles();
        }
        if (variables_map.count("dochangedfiles")) {
            wiki->DoChangedFiles();
        }
        if (variables_map.count("scanimages")) {
            wiki->ScanImages();
        }
        if (variables_map.count("scanwikifiles")) {
            wiki->ScanWikiFiles();
        }
        if (variables_map.count("teststuff")) {
            wiki->TestStuff();
        }
        if (variables_map.count("scanwikifile")) {
            wiki->ScanWikiFileForLinks(target_file.c_str());
        }
        if (variables_map.count("dowikifile")) {
            wiki->DoWikiFile(target_file);
        }
        if (variables_map.count("markcontentdirty")) {
            wiki->MarkContentDirty(target_file.c_str());
        }
        if (variables_map.count("markreferencesdirty")) {
            wiki->MarkReferencesDirty(target_file.c_str());
        }
        if (variables_map.count("loadexifdata")) {
            wiki->LoadEXIFData(target_file);
        }
        if (variables_map.count("scandplfiles")) {
            wiki->ScanDPLFiles();
        }
        if (variables_map.count("verifywikilink")) {
            wiki->VerifyWikiLink(target_file);
        }
        if (variables_map.count("showwikistatus")) {
            wiki->ShowWikiStatus(target_file);
        }
        if (variables_map.count("loadjpegdata")) {
            wiki->LoadJPEGData(target_file);
        }

    } catch(std::exception& e) {
        cout << e.what() << "\n";
        return 1;
    } catch(FbyBaseExceptionPtr e) {
        cout << e->file << ":" << e->line << " " << e->Message << endl;
        return 1;
    }

    return 0;
}

#ifndef COCOAARRAY_H_INCLUDED
#define COCOAARRAY_H_INCLUDED

#include "fby_core_unix_propertyhelper.h"
#include <vector>
#include <boost/smart_ptr.hpp>
#include <algorithm>

namespace FbyHelpers
{

	template <typename ElementType> class UnixArray;

	template <typename ElementType> class UnixArrayHelper
	{
	private:
		FBYUNCOPYABLE(UnixArrayHelper);
		UnixArray<ElementType> *managedArray;

		friend class UnixArray<ElementType>;

	public:
		int GetCount() const;

		UnixArrayHelper(UnixArray<ElementType> *array) 
			: managedArray(array),
			  Count(this, &UnixArrayHelper<ElementType>::GetCount),
			  Length(this, &UnixArrayHelper<ElementType>::GetCount)
		{
#ifdef COCOAARRAYDEBUG
			printf("Created UnixArrayHelper %lx\n", (unsigned long)this);
			printf("   for UnixArray %lx\n", (unsigned long)managedArray);
#endif // COCOAARRAYDEBUG
		}

		~UnixArrayHelper()
		{
#ifdef COCOAARRAYDEBUG
			printf("Destroyed UnixArrayHelper %lx\n", (unsigned long)this);
			printf("   for UnixArray %lx\n", (unsigned long)managedArray);
#endif // COCOAARRAYDEBUG
			memset(this, 0, sizeof(*this));
		}

		PropertyHelper<UnixArrayHelper<ElementType>, int> Count;
		PropertyHelper<UnixArrayHelper<ElementType>, int> Length;

		void Add(ElementType obj);
		bool Contains(ElementType obj);
		void RemoveAt(int index);
		void Clear();
		void RemoveRange(int index, int count);
		void Remove(const ElementType &obj);
		void AddRange(UnixArray<ElementType> array);
		void AddRange(boost::intrusive_ptr<UnixArray<ElementType>> array);

		void CopyTo(UnixArray<ElementType> target, int index)
		{
			while (index < target.elems->size())
			{
				if (!(index < managedArray->elems->size()))
					break;
				ElementType value = (*(managedArray->elems))[index];
				(*(target.elems))[index] = value;
				++index;
			}
		}

		void Reverse()
		{
			std::reverse(managedArray->elems->begin(), managedArray->elems->end());
		}
	};

	class UnixArrayBase
	{
	public:
		UnixArrayBase()
		{
#ifdef COCOAARRAYDEBUG
			printf("Created UnixArrayBase %lx\n", (unsigned long)this);
#endif // COCOAARRAYDEBUG
		}

		virtual ~UnixArrayBase()
		{
#ifdef COCOAARRAYDEBUG
			printf("Destroyed UnixArrayBase %lx\n", (unsigned long)this);
#endif // COCOAARRAYDEBUG
			memset(this, 0, sizeof(*this));
		}

		virtual bool IsNull() const = 0;
	};

	inline bool IsNull(const UnixArrayBase &array)
	{
		return array.IsNull();
	}

	template <typename ElementType> class UnixArray : public UnixArrayBase
	{
	private:
		UnixArrayHelper<ElementType> helper;
		boost::shared_ptr<std::vector<ElementType>> elems;

	public:
		UnixArray(int size = 0)
			: helper(this),
			  elems(new std::vector<ElementType>(size))
		{
#ifdef COCOAARRAYDEBUG
			printf("Created UnixArray %lx\n", (unsigned long)this);
#endif // COCOAARRAYDEBUG
		}

		UnixArray(const UnixArray<ElementType> &rhs)
			: helper(this),
			  elems(rhs.elems)
		{
#ifdef COCOAARRAYDEBUG
			printf("Created UnixArray %lx from %lx\n", (unsigned long)this, (unsigned long)&rhs);
#endif // COCOAARRAYDEBUG
		}

		virtual ~UnixArray()
		{
#ifdef COCOAARRAYDEBUG
			printf("Destroyed UnixArray %lx\n", (unsigned long)this);
#endif // COCOAARRAYDEBUG
			elems.reset();
		}

		UnixArray<ElementType> & operator =(const UnixArray<ElementType> &rhs)
		{
#ifdef COCOAARRAYDEBUG
			printf("Copied UnixArray %lx from %lx\n", (unsigned long)this, (unsigned long)&rhs);
#endif // COCOAARRAYDEBUG
			elems = rhs.elems;
			helper.managedArray = this;
			return *this;
		}

		friend class UnixArrayHelper<ElementType>;

		ElementType Get(int index)
		{
			return (*elems)[index];
		}

		void Set(int index, const ElementType& value)
		{
			(*elems)[index] = value;
		}

		ElementType & operator [](int index)
		{
			return (*elems)[index];
		}

		UnixArrayHelper<ElementType> *operator->()
		{
			return &helper;
		}

		bool IsNull() const
		{
			return elems->empty();
		}
	};

	template <typename ElementType> bool ArrayIsNull(const UnixArray<ElementType> &array)
	{
		return array.IsNull();
	}

	template <typename ElementType> inline void UnixArrayHelper<ElementType>::Add(ElementType obj)
	{
		managedArray->elems->push_back(obj);
	}

	template <typename ElementType> inline bool UnixArrayHelper<ElementType>::Contains(ElementType obj)
	{
		return std::find(managedArray->elems->begin(), managedArray->elems->end(), obj) != managedArray->elems->end();
	}

	template <typename ElementType> inline int UnixArrayHelper<ElementType>::GetCount() const
	{
		return managedArray->elems->size();
	}

	template <typename ElementType> inline void UnixArrayHelper<ElementType>::RemoveAt(int index)
	{
		managedArray->elems->erase(managedArray->elems->begin() + index);
	}

	template <typename ElementType> inline void UnixArrayHelper<ElementType>::Clear()
	{
		managedArray->elems->clear();
	}

	template <typename ElementType> inline void UnixArrayHelper<ElementType>::RemoveRange(int index, int count)
	{
		managedArray->elems->erase(managedArray->elems->begin() + index, managedArray->elems->begin() + index + count);
	}

	template <typename ElementType> inline void UnixArrayHelper<ElementType>::Remove(const ElementType &obj)
	{	
		managedArray->elems->erase(std::find(managedArray->elems->begin(), managedArray->elems->end(), obj));
	}

	template <typename ElementType> inline void UnixArrayHelper<ElementType>::AddRange(UnixArray<ElementType> array)
	{
		for (int i = 0; i < array->Count; ++i)
		{
			Add(array[i]);
		}
	}

	template <typename ElementType> inline void UnixArrayHelper<ElementType>::AddRange(boost::intrusive_ptr<UnixArray<ElementType>> array)
	{
		printf("AddRange boost\n");
		for (int i = 0; i < (*array)->Count; ++i)
		{
			printf("  Adding element %d: %d\n", i, (*array)[i]);
			Add((*array)[i]);
		}
	}

} // end of namespace FbyHelpers

#endif // #ifndef COCOAARRAY_H_INCLUDED

#ifndef FBY_CORE_UNIX_PROPERTYHELPER_H_INCLUDED
#define FBY_CORE_UNIX_PROPERTYHELPER_H_INCLUDED

#include <stdio.h>
#include <string.h>
#include <assert.h>

// A utility class that facilitates property access and manipulation for a container object.
template <typename Container, typename ValueType>
class PropertyHelper
{
public:
    // Constructor initializes the container and the getter/setter methods.
    PropertyHelper(Container* const container = nullptr,
                   ValueType (Container::*getter)() const = nullptr,
                   void (Container::*setter)(ValueType value) = nullptr) :
        containerObject(const_cast<Container*>(container)), 
        Get(getter), 
        Set(setter)
    {
    }

    // Assigns a value to the property and returns the assigned value.
    ValueType operator =(const ValueType& value)
    {
        assert(containerObject != nullptr);
        assert(Set != nullptr);
        (containerObject->*Set)(value);
        return value;
    }

    // Adds a value to the property and returns the added value.
    ValueType operator +=(const ValueType& value)
    {
        assert(containerObject != nullptr);
        assert(Set != nullptr);
        assert(Get != nullptr);
        (containerObject->*Set)((containerObject->*Get)() + value);
        return value;
    }

    // Compares the property value with another value.
    bool operator < (const ValueType& value)
    {
        assert(containerObject != nullptr);
        assert(Get != nullptr);
        return (containerObject->*Get)() < value;
    }

    bool operator > (const ValueType& value)
    {
        assert(containerObject != nullptr);
        assert(Get != nullptr);
        return (containerObject->*Get)() > value;
    }

    bool operator <= (const ValueType& value)
    {
        assert(containerObject != nullptr);
        assert(Get != nullptr);
        return (containerObject->*Get)() <= value;
    }

    bool operator >= (const ValueType& value)
    {
        assert(containerObject != nullptr);
        assert(Get != nullptr);
        return (containerObject->*Get)() >= value;
    }

    // Subtracts a value from the property and returns the subtracted value.
    ValueType operator -=(const ValueType& value)
    {
        assert(containerObject != nullptr);
        assert(Set != nullptr);
        assert(Get != nullptr);
        (containerObject->*Set)((containerObject->*Get)() - value);
        return value;
    }

    // Divides the property value by a given value and returns the divided value.
    ValueType operator /=(const ValueType& value)
    {
        assert(containerObject != nullptr);
        assert(Set != nullptr);
        assert(Get != nullptr);
        (containerObject->*Set)((containerObject->*Get)() / value);
        return value;
    }

    // Converts the PropertyHelper to the underlying ValueType.
    operator ValueType() const
    {
        assert(containerObject != nullptr);
        assert(Get != nullptr);
        return (containerObject->*Get)();
    }

private:
    Container* containerObject;  // Pointer to the container object.
    ValueType (Container::*Get)() const;  // Pointer to the getter method.
    void (Container::*Set)(ValueType value);  // Pointer to the setter method.
};

