string convertToLower(string str) {
    for_each(str.begin(), str.end(), [](char & ch) { ch = static_cast<char>(tolower(ch)); });
    return str;
}

Reservation::Reservation(QDate startDate, QDate endDate, string guestName, string guestSurname, Room *room) {
    name = guestName;
    surname = guestSurname;
    parent = room;
    firstDay = startDate;
    lastDay = endDate;

    auto freeDatesIterator = (parent->getFreeDates()).begin();
    while (*freeDatesIterator < firstDay)
        ++freeDatesIterator;

    auto endIterator = freeDatesIterator;
    while (*endIterator <= lastDay)
        ++endIterator;

    (parent->getFreeDates()).erase(freeDatesIterator, endIterator);
    string combinedName = convertToLower(surname + name);
    parent->addReservation(combinedName, this);
}

string Reservation::toString() {
    string result;
    result += string(getParent().getParent().getParent()) + "~"; // City
    result += string(getParent().getParent()) + "~"; // Hotel
    result += firstDay.toString("dd/MM/yy").toStdString() + "~"; // First day
    result += lastDay.toString("dd/MM/yy").toStdString() + "~"; // Last day
    result += name + "~";
    result += surname + "~";

    std::stringstream ss;
    ss << static_cast<int>(getParent());
    result += ss.str();

    return result;
}

ostream & operator<<(ostream & os, const Reservation & reservation) {
    os << string(reservation.getParent().getParent().getParent()) << "~"; // City
    os << string(reservation.getParent().getParent()) << "~"; // Hotel
    os << reservation.firstDay.toString("dd/MM/yy").toStdString() << "~"; // First day
    os << reservation.lastDay.toString("dd/MM/yy").toStdString() << "~"; // Last day
    os << reservation.name << "~";
    os << reservation.surname << "~";

    std::stringstream ss;
    ss << static_cast<int>(reservation.getParent());
    os << ss.str() << std::endl;

    return os;
}

Room::Room(int roomNumber, Hotel *hotel) {
    number = roomNumber;
    parent = hotel;
    parent->addRoom(this);

    QDate currentDate = QDate::currentDate();
    QDate endDate = currentDate.addDays(30);

    while (currentDate < endDate) {
        freeDates.push_back(currentDate);
        currentDate = currentDate.addDays(1);
    }
}

bool Room::isFree(QDate startDate, QDate endDate) {
    if (startDate > endDate)
        return false;

    auto startIterator = std::find(freeDates.begin(), freeDates.end(), startDate);
    auto endIterator = std::find(freeDates.begin(), freeDates.end(), endDate);

    if (startIterator == freeDates.end() || endIterator == freeDates.end())
        return false;

    return distance(startIterator, endIterator) == (endDate.toJulianDay() - startDate.toJulianDay());
}

void Room::book(QDate startDate, QDate endDate, string guestName, string guestSurname) {
    new Reservation(startDate, endDate, guestName, guestSurname, this);
    getParent().getParent().getParent().writeToFile();
}

Hotel::Hotel(string hotelName, int pricePerNight, City *city) {
    name = hotelName;
    priceForNight = pricePerNight;
    parent = city;
    parent->addHotel(this);

    for (int i = 0; i < howManyRooms; ++i) {
        new Room((i + 1), this);
    }
}

Room & Hotel::getRoom(QDate startDate, QDate endDate) const {
    for (auto room : rooms) {
        if (room->isFree(startDate, endDate))
            return *room;
    }
    throw NoRoomsAvailable();
}

Room & Hotel::getRoom(int roomNumber) const {
    if (roomNumber < 1 || roomNumber > howManyRooms)
        throw BadRoomNumber();
    return *(rooms[static_cast<std::vector<Room *>::size_type>(roomNumber - 1)]);
}

void Hotel::show(ostream & os) const {
    os << setw(25) << std::left << name << " " << std::right << setw(5) << priceForNight << endl;
}

void Hotel::showReservations(ostream & os) const {
    for (auto room : rooms) {
        room->showReservations(os);
    }
}

City::City(string cityName, ifstream & inFile, DataBase *database) {
    name = cityName;
    getData(inFile);
    parent = database;
    database->addCity(this);
}

bool City::getData(std::ifstream & inFile) {
    std::string hotelName;
    std::string hotelPrice;
    std::string hotelPrefix = "Hotel";
    std::streampos previousPosition;

    while (getline(inFile, hotelName) && hotelName.substr(0, hotelPrefix.size()) == hotelPrefix) {
        hotelPrice = hotelName.substr(hotelName.find('(') + 1,
            hotelName.find(')') - (hotelName.find('(') + 1) - std::string("zl/noc").size());
        hotelName = hotelName.substr(hotelPrefix.size() + 1, hotelName.find('(') - (hotelPrefix.size() + 2));

        new Hotel(hotelName, std::stoi(hotelPrice), this);
        previousPosition = inFile.tellg();  // Store the position
    }

    inFile.seekg(previousPosition); // Return to the stored position
    return true;
}

Hotel & City::getHotel(std::string hotelName) const {
    for (auto hotel : hotels) {
        if (convertToLower(std::string(*hotel)) == convertToLower(hotelName)) {
            return *hotel;
        }
    }
    throw BadHotelName();
}

void City::show(ostream & os) const {
    os << "City: " << name << std::endl;
    for (auto hotel : hotels) {
        hotel->show(os);
    }
}

void City::showReservations(ostream & os) const {
    for (auto hotel : hotels) {
        if (hotel->hasReservations()) {
            hotel->showReservations(os);
        }
    }
}

DataBase::DataBase(string fileName) : inFile(fileName), madeResName("reservations.txt"), madeReservations(madeResName, std::ios::trunc) {
    if (!inFile.is_open()) {
        throw BadFileName();
    }
    if (!madeReservations.is_open()) {
        throw BadFileName();
    }

    string cityName;
    string hotelPrefix = "Hotel";
    string endMarker = "koniec";

    while (getline(inFile, cityName)) {
        cityName = cityName.substr(0, cityName.find(char(13))); // Remove Carriage Return
        if (cityName.substr(0, endMarker.size()) == endMarker)
            break;
        if (!(cityName.substr(0, hotelPrefix.size()) == hotelPrefix)) { // If the line is not a hotel name, it's a city
            new City(cityName, inFile, this);
        }
    }
}

