#ifndef __LOG_H__
#define __LOG_H__

#include "pch.h"

// Class responsible for logging messages to a file and console.
class Log {
private:
	static inline std::ofstream logFile;
	static inline bool isLoggingEnabled = false;

public:
	// Initializes the logging system by setting up the log file.
	static inline bool init() {
		using namespace std::filesystem;

		path packsDirectory = current_path() / "packs";
		path logFilePath = packsDirectory / "log.txt";

		// Ensure the packs directory exists and is valid.
		if (!exists(packsDirectory)) {
			create_directories(packsDirectory);
		} else if (!is_directory(packsDirectory)) {
			MessageBox(nullptr, "ERROR: packs is an existing file.\n please remove it to use textureldr.", "textureldr", MB_OK | MB_ICONERROR);
		}

		// Set up the log file based on its existence and size.
		if (!is_directory(logFilePath)) {
			if (exists(logFilePath) && file_size(logFilePath) > 500000) {
				logFile.open(logFilePath.c_str(), std::ios::trunc); // Overwrite if file exceeds 0.5MB.
			} else {
				logFile.open(logFilePath.c_str(), std::ios::app); // Append if file is smaller or doesn't exist.
			}
		} else {
			MessageBox(nullptr, "ERROR: log.txt is an existing directory.\n could not initialize logging.", "textureldr", MB_OK | MB_ICONERROR);
		}

		std::cout.rdbuf(logFile.rdbuf()); // Redirect console output to log file.

		// Confirm successful initialization of logging.
		if (logFile.good() && std::cout.rdbuf()) {
			if (file_size(logFilePath)) {
				std::cout << "\n\n"; // Add spacing if log file is not empty.
			}
			Log::info("Logger initialized.");
			isLoggingEnabled = true;
			return true;
		}
		return false;
	}

	// Logs an error message if logging is enabled.
	template<typename ...Args>
	static inline void error(Args... args) {
		if (isLoggingEnabled) {
			std::cout << "[ERROR] ";
			(std::cout << ... << args);
			std::cout << std::endl;
		}
	}

	// Logs an informational message if logging is enabled.
	template<typename ...Args>
	static inline void info(Args... args) {
		if (isLoggingEnabled) {
			std::cout << "[INFO] ";
			(std::cout << ... << args);
			std::cout << std::endl;
		}
	}
};

#endif

