class Ticket {
public:
    int id = -1;

    int number = -1;
    string startCity = "undefined";
    string destinationCity = "undefined";
    string departureTime = "undefined";
    string arrivalTime = "undefined";
    double price = 0.0;
    int ticketNumber = -1;

    // Default constructor.
    Ticket() = default;

    // Parameterized constructor for initializing all attributes.
    Ticket(int number, string startCity, string destinationCity, string departureTime, string arrivalTime,
           double price, int ticketNumber) :
            number(number), startCity(move(startCity)), destinationCity(move(destinationCity)),
            departureTime(move(departureTime)), arrivalTime(move(arrivalTime)),
            price(price), ticketNumber(ticketNumber) {}

    /**
     * Converts the ticket object to a JSON representation.
     * Note: C++ lacks true reflection capabilities.
     *
     * @return JSON object representing the ticket.
     */
    Json::Value toJson() const {
        Json::Value ticketJson;

        ticketJson["id"] = to_string(id);
        ticketJson["number"] = to_string(number);
        ticketJson["startCity"] = startCity;
        ticketJson["destinationCity"] = destinationCity;
        ticketJson["departureTime"] = departureTime;
        ticketJson["arrivalTime"] = arrivalTime;
        ticketJson["price"] = to_string(price);
        ticketJson["ticketNumber"] = to_string(ticketNumber);

        return ticketJson;
    }
};

/**
