namespace ddd {

using namespace std;

// Khởi tạo seed cho bộ sinh số ngẫu nhiên dựa trên thời gian hiện tại
auto seed = chrono::system_clock::now().time_since_epoch().count();
auto randomGenerator = bind(uniform_int_distribution<int64_t>{}, mt19937{seed});
constexpr short hexLength = 16;

// Chuyển đổi số nguyên thành chuỗi hex với độ dài cố định
auto convertToHex = [](stringstream &stream, int64_t value) { 
    stream << setfill('0') << setw(hexLength) << hex << value; 
};

Uuid::Uuid() : most(getRandomValue()), least(getRandomValue()) {}

Uuid::Uuid(int64_t mostValue, int64_t leastValue) : most(mostValue), least(leastValue) {}

Uuid::Uuid(const Uuid &id) : most(id.most), least(id.least) {}

bool Uuid::operator==(const Uuid &id) {
    return most == id.most && least == id.least;
}

bool Uuid::operator!=(const Uuid &id) {
    return !(*this == id);
}

int64_t Uuid::getRandomValue() {
    return randomGenerator();
}

const char * Uuid::toString() {
    // Chuyển đổi UUID thành chuỗi theo định dạng 8-4-4-4-12
    stringstream stream;
    convertToHex(stream, most);
    convertToHex(stream, least);
    string result(stream.str());

    // Chèn dấu phân cách vào vị trí thích hợp
    for (int i = 0; i < 4; i++) {
        result.insert(FIRST_SEP_POSITION + (i * 4) + i, 1, SEP);
    }
    return result.c_str();
}

