string getCoordinate(const string &location) {
    const string GEO_API_BASE = "https://restapi.amap.com/v3/geocode/geo";

    auto response = cpr::Get(cpr::Url{GEO_API_BASE},
                              cpr::Parameters{{"key", GEO_API_KEY},
