#include <iostream>
using namespace std;

class Complex {
private:
    int realPart;
    int imaginaryPart;

public:
    Complex() {}

    Complex(int real, int imaginary) {
        realPart = real;
        imaginaryPart = imaginary;
    }

    // Displays the real and imaginary parts of the complex number
    void display() const {
        cout << realPart << " " << imaginaryPart << "\n";
    }

    Complex operator+(const Complex& other) const;
    Complex operator-(const Complex& other) const;
    Complex operator++();
    Complex operator--();
    bool operator==(const Complex& other) const;
};

Complex Complex::operator+(const Complex& other) const {
    Complex result;
    result.realPart = other.realPart + realPart;
    result.imaginaryPart = other.imaginaryPart + imaginaryPart;
    return result;
}

Complex Complex::operator-(const Complex& other) const {
    Complex result;
    result.realPart = realPart - other.realPart;
    result.imaginaryPart = imaginaryPart - other.imaginaryPart;
    return result;
}

Complex Complex::operator++() {
    ++realPart;
    ++imaginaryPart;
    return *this;
}

Complex Complex::operator--() {
    --realPart;
    --imaginaryPart;
    return *this;
}

bool Complex::operator==(const Complex& other) const {
    return (other.realPart == realPart) && (other.imaginaryPart == imaginaryPart);
}

int main() {
    Complex firstComplex(10, 20), secondComplex(5, 30);
    Complex resultComplex;

    firstComplex.display();
    secondComplex.display();

    cout << "Addition of complex numbers:";
    resultComplex = firstComplex + secondComplex;
    resultComplex.display();

    cout << "Subtraction of complex numbers:";
    resultComplex = firstComplex - secondComplex;
    resultComplex.display();

    cout << "Checking if the two complex numbers are equal\n";
    firstComplex.display();
    secondComplex.display();
    bool areEqual = firstComplex == secondComplex;
    cout << (areEqual ? "Numbers are the same\n" : "Numbers are different\n");

    cout << "Incrementing complex number:";
    firstComplex.display();
    ++firstComplex;
    cout << "After increment:";
    firstComplex.display();

    cout << "Decrementing complex number:";
    secondComplex.display();
    --secondComplex;
    cout << "After decrement:";
    secondComplex.display();

    return 0;
}

