#include <iostream>
#include <cstdlib>
using namespace std;

const int MAX_SIZE = 10;

template <class ElementType>
class Sorter {
public:
    ElementType elements[MAX_SIZE];

    Sorter() {}

    // Reads elements into the array from standard input
    void readElements(int count) {
        for (int i = 0; i < count; i++) {
            cin >> elements[i];
        }
    }

    // Displays the elements of the array to standard output
    void displayElements(int count) {
        for (int i = 0; i < count; i++) {
            cout << elements[i] << " ";
        }
        cout << "\n";
    }

    // Performs bubble sort on the array
    template <class T>
    void bubbleSort(T *items, int count) {
        for (int i = 1; i < count; i++) {
            for (int j = count - 1; j >= i; j--) {
                if (items[j - 1] > items[j]) {
                    swap(items[j - 1], items[j]);
                }
            }
        }
    }
};

int main() {
    Sorter<int> intSorter;
    Sorter<double> doubleSorter;
    int intArraySize, doubleArraySize;

    cout << "\nEnter the size of the integer array: -\n";
    cin >> intArraySize;
    cout << "\nEnter the size of the double array: -\n";
    cin >> doubleArraySize;

    if (intArraySize > MAX_SIZE || doubleArraySize > MAX_SIZE) {
        cout << "Please enter a smaller value\n";
        return 1; // Exit if sizes are invalid
    }

    cout << "\nEnter the integer array:-\n";
    intSorter.readElements(intArraySize);
    cout << "\nEnter the double array:-\n";
    doubleSorter.readElements(doubleArraySize);

    cout << "\nUnsorted integer array is:-\n";
    intSorter.displayElements(intArraySize);
    cout << "\nUnsorted double array is:-\n";
    doubleSorter.displayElements(doubleArraySize);

    intSorter.bubbleSort(intSorter.elements, intArraySize);
    doubleSorter.bubbleSort(doubleSorter.elements, doubleArraySize);

    cout << "\nSorted integer array is:-\n";
    intSorter.displayElements(intArraySize);
    cout << "\nSorted double array is:-\n";
    doubleSorter.displayElements(doubleArraySize);

    return 0;
}

#include <iostream>
#define MAX_SIZE 5
using namespace std;

class Stack {
private:
    int item;
    int topIndex;
    int elements[MAX_SIZE];

public:
    void initialize();
    void push();
    int pop();
    void display();
};

// Initializes the stack by setting the top index to -1
void Stack::initialize() {
    topIndex = -1;
}

// Adds an item to the top of the stack if there is space
void Stack::push() {
    if (topIndex == MAX_SIZE - 1) {
        cout << "\nNo space available to push new item.";
        return;
    }
    cout << "\nEnter item to be inserted: ";
    cin >> item;
    elements[++topIndex] = item;
    cout << item << " has been inserted into the stack.";
}

// Removes and returns the top item from the stack
int Stack::pop() {
    if (topIndex == -1) {
        cout << "\nThe stack is empty!";
        return 0; // Return 0 to indicate stack underflow
    }
    return elements[topIndex--];
}

// Displays all items in the stack
void Stack::display() {
    if (topIndex == -1) {
        cout << "\nEmpty stack!";
        return;
    }

    cout << "\nThe stack elements are:\n";
    for (int i = 0; i <= topIndex; i++) {
        cout << elements[i] << "\n";
    }
}

int main() {
    Stack stackInstance;
    stackInstance.initialize();
    int userChoice, poppedItem = 0;

    while (true) {
        cout << "\n\nEnter your choice: ";
        cout << "\n1. Push \t 2. Pop \t 3. Display \t 4. Exit\n";
        cin >> userChoice;

        switch (userChoice) {
            case 1:
                stackInstance.push();
                break;

            case 2:
                poppedItem = stackInstance.pop();
                cout << poppedItem << " has been deleted from the stack!";
                break;

            case 3:
                stackInstance.display();
                break;

            case 4:
                exit(0);

            default:
                cout << "\nPlease enter a valid choice!";
                break;
        }
    }
}

