#include <iostream>
#include <string>
using namespace std;

class Student {
private:
    string name;
    float marks[3], average;
    int index, usn;

public:
    void readDetails();
    float calculateAverage();
    void displayDetails();
};

// Reads student details including USN, name, and marks for three subjects
void Student::readDetails() {
    cout << "\nEnter USN: ";
    cin >> usn;
    cout << "\nEnter name: ";
    cin.ignore();
    getline(cin, name);
    cout << "\nEnter marks of 3 subjects.";
    for (index = 0; index < 3; index++) {
        cout << "\nEnter marks for subject " << index + 1 << ": ";
        cin >> marks[index];
    }
}

// Calculates the average marks excluding the lowest score
float Student::calculateAverage() {
    float total = 0.0, minimum = marks[0];
    for (index = 0; index < 3; index++) {
        if (minimum > marks[index])
            minimum = marks[index];
        total += marks[index];
    }
    average = (total - minimum) / 2;
    return average;
}

// Displays the student's USN, name, marks, and average
void Student::displayDetails() {
    cout << usn << "\t" << name << "\t";
    for (index = 0; index < 3; index++)
        cout << marks[index] << "\t";
    cout << average << "\n";
}

int main() {
    int studentCount, topperIndex, i;
    float highestAverage = 0;

    cout << "\nEnter number of students: ";
    cin >> studentCount;

    Student students[studentCount];
    for (i = 0; i < studentCount; i++) {
        students[i].readDetails();
        float currentAverage = students[i].calculateAverage();
        if (currentAverage > highestAverage)
            highestAverage = currentAverage; // Update highest average
    }

    for (i = 0; i < studentCount; i++) {
        float averageToCompare = students[i].calculateAverage();
        if (averageToCompare == highestAverage)
            topperIndex = i; // Identify the topper
    }

    cout << "\nStudent details are:\n";
    for (i = 0; i < studentCount; i++) {
        students[i].displayDetails();
    }

    cout << "\nThe topper is student " << topperIndex + 1 << endl;
    students[topperIndex].displayDetails(); // Display topper details

    return 0;
}

