public:
    static int resource; // Static variable shared across all instances

    int acquireResource(); // Attempts to acquire the resource
    void releaseResource(); // Releases the resource
};

int SharedResource::resource = 0;

int SharedResource::acquireResource() {
    // Check if the resource is already acquired
    if (resource) {
        return 0; // Resource is in use, return 0
    } else {
        resource = 1; // Acquire the resource
        return 1; // Successfully acquired, return 1
    }
}

void SharedResource::releaseResource() {
    resource = 0; // Release the resource
}

int main() {
    SharedResource instance1, instance2;

    // Attempt to acquire resource with instance1
    if (instance1.acquireResource()) {
        cout << "\nInstance 1 has access";
    }

    // Attempt to acquire resource with instance2
    if (!instance2.acquireResource()) {
        cout << "\nInstance 2 has NO access";
    }

    instance1.releaseResource(); // Release the resource

    // Attempt to acquire resource with instance2 again
    if (instance2.acquireResource()) {
        cout << "\nInstance 2 now has access" << endl;
    }
}

