class ObjectCounter {
public:
    static int instanceCount;

    ObjectCounter() { // Increments the instance count upon creation
        instanceCount++;
    }

    ~ObjectCounter() { // Decrements the instance count upon destruction
        instanceCount--;
    }
};

int ObjectCounter::instanceCount = 0; // Initialize instance count to 0

void displayObjectCount() {
    ObjectCounter temporaryObject;
    cout << "\nCurrent number of objects in existence: ";
    cout << temporaryObject.instanceCount << endl; // Displays the count of objects
}

