#include <iostream>
#include <new>

using namespace std;

struct Node {
    int value;
    Node* next; // points to the next node in the list
};

class LinkedList {
    Node* head;

public:
    LinkedList() : head(nullptr) {} // Initialize head as null when creating the object

    // Insert a new node at the front of the list
    void insertFront(int value) {
        Node* newNode = new Node; // Create a new node at runtime
        newNode->value = value; // Assign the value to the new node
        newNode->next = head; // Link the new node to the current head
        head = newNode; // Update head to the new node
    }

    // Remove the node at the front of the list
    void deleteFront() {
        if (head == nullptr) { // Check if the list is empty
            cout << "List empty\n";
            return;
        }
        Node* tempNode = head; // Temporarily store the current head
        head = head->next; // Move head to the next node
        cout << "Item deleted is " << tempNode->value << "\n";
        delete tempNode; // Free the memory of the removed node
    }

    // Insert a new node at the rear of the list
    void insertRear(int value) {
        Node* newNode = new Node; // Create a new node
        newNode->value = value;

        if (head == nullptr) { // Check if the list is empty
            newNode->next = nullptr; // New node will be the only node
            head = newNode; // Update head to the new node
            return;
        }

        Node* currentNode = head;
        while (currentNode->next != nullptr) { // Traverse to the end of the list
            currentNode = currentNode->next;
        }
        newNode->next = nullptr; // Set the new node's next to null
        currentNode->next = newNode; // Link the last node to the new node
    }

    // Remove the node at the rear of the list
    void deleteRear() {
        if (head == nullptr) { // Check if the list is empty
            cout << "List empty\n";
            return;
        }

        Node* currentNode = head;
        Node* previousNode = nullptr;

        while (currentNode->next != nullptr) { // Traverse to the last node
            previousNode = currentNode; // Keep track of the previous node
            currentNode = currentNode->next;
        }
        if (previousNode != nullptr) {
            previousNode->next = nullptr; // Set the previous node's next to null
        } else {
            head = nullptr; // If there was only one node, update head to null
        }
        cout << "Item deleted is " << currentNode->value << "\n";
        delete currentNode; // Free the memory of the removed node
    }

    // Display all the items in the list
    void display() {
        if (head == nullptr) { // Check if the list is empty
            cout << "List empty\n";
            return;
        }
        Node* currentNode = head;
        while (currentNode != nullptr) { // Traverse throughout the list
            cout << currentNode->value << "\t";
            currentNode = currentNode->next;
        }
        cout << "\n";
    }
};

int main() {
    int choice, item;
    LinkedList linkedList;

    while (true) { // Infinite loop for user interaction
        cout << "1. Insert Front\t2. Delete Front\t3. Insert Rear\t4. Delete Rear\t5. Display\t6. Exit\n";
        cin >> choice;
        switch (choice) {
            case 1: {
                cout << "Enter item to be inserted\n";
                cin >> item;
                linkedList.insertFront(item);
                break;
            }
            case 2: {
                linkedList.deleteFront();
                break;
            }
            case 3: {
                cout << "Enter item to be inserted\n";
                cin >> item;
                linkedList.insertRear(item);
                break;
            }
            case 4: {
                linkedList.deleteRear();
                break;
            }
            case 5: {
                linkedList.display();
                break;
            }
            default: {
                return 0; // Exit the program for any other choice
            }
        }
    }

    return 0;
}

