#include <iostream>
#include <cstring>
using namespace std;

class NegativeNumberException {
public:
    char message[80];
    int value;

    NegativeNumberException(const char* msg, int val) {
        strcpy(message, msg);
        value = val;
    }
};

class DivideByZeroException {
public:
    char message[80];
    int value;

    DivideByZeroException(const char* msg, int val) {
        strcpy(message, msg);
        value = val;
    }
};

int main() {
    int inputValue, numerator, denominator;

    // Prompt for a positive number and validate input
    try {
        cout << "Enter a positive number: ";
        cin >> inputValue;

        if (inputValue < 0) {
            throw NegativeNumberException("Not Positive", inputValue);
        }
    } catch (NegativeNumberException& e) { 
        cout << e.message << ": " << e.value << "\n";
    }

    // Prompt for numerator and denominator, and validate denominator
    try {
        cout << "Enter the value of numerator: ";
        cin >> numerator;
        cout << "Enter the value of denominator: ";
        cin >> denominator;

        if (denominator == 0) {
            throw DivideByZeroException("Cannot divide by zero", denominator);
        }
    } catch (DivideByZeroException& e) { 
        cout << e.message << ": " << e.value << "\n";
    }

    return 0;
}

