        outtextxy(100, 210, "\n\tEnter price of product: ");
        cout << "\n\t\t\t\t\t\t";
        cin >> productPrice;
        calculateTax();
    }

    /****************************************************
                Function to Display Product Information
    ****************************************************/
    void displayProductInfo() {
        setcolor(CYAN);
        settextstyle(1, 0, 4);
        outtextxy(100, 90, "\n\t\tPRODUCT DETAILS");
        settextstyle(1, 0, 2);
        outtextxy(100, 130, "\n\tProduct Code: ");
        cout << "\n\n\n\n\t\t\t\t\t" << productCode;
        outtextxy(100, 170, "\n\tProduct Name: ");
        cout << "\n\n\t\t\t\t\t" << productName;
        outtextxy(100, 210, "\n\tProduct Quantity: ");
        cout << "\n\n\n\t\t\t\t\t" << productQuantity;
        outtextxy(100, 250, "\n\tProduct Price: ");
        cout << "\n\n\t\t\t\t\t" << productPrice;
    }

    /****************************************************
                Function to Modify Product Information
    ****************************************************/
    void updateProductInfo() {
        outtextxy(100, 300, "\n\tProduct Code: ");
        cout << "\n\n\n\t\t\t\t\t" << productCode;
        outtextxy(100, 330, "\n\t\tENTER NEW PRODUCT DETAILS");
        outtextxy(100, 360, "\n\tEnter new product name: ");
        cout << "\n\n\n\n\t\t\t\t\t\t\t";
        gets(productName);
        outtextxy(100, 400, "\n\tEnter new quantity of product: ");
        cout << "\n\n\t\t\t\t\t\t\t"; 
        cin >> productQuantity;
        outtextxy(100, 440, "\n\tEnter new price of product:");
        cout << "\n\n\t\t\t\t\t\t\t"; 
        cin >> productPrice;
        calculateTax();
    }

    /****************************************************
                Function to Show All Product Information
    ****************************************************/
    void displayAllInfo() {
        cout << setw(4) << "\n" << setw(19) << productCode << setw(19) << productName << setw(24) << productQuantity << setw(20) << productPrice << setw(1) << "\n";
    }

    /****************************************************
                Function to Calculate Tax
    ****************************************************/
    double calculateTax() {
        if (productPrice < 1000) {
            productTax = productPrice * 0.05; 
            productPrice += productTax; 
            return productPrice;
        } 
        if (productPrice >= 1000 && productPrice < 10000) {
            productTax = productPrice * 0.15; 
            productPrice += productTax; 
            return productPrice;
        } 
        if (productPrice >= 10000 && productPrice < 50000) {
            productTax = productPrice * 0.25; 
            productPrice += productTax; 
            return productPrice;
        } 
        if (productPrice >= 50000) {
            productTax = productPrice * 0.4; 
            productPrice += productTax; 
            return productPrice;
        }
    }

    /****************************************************
                Function to Return Product Code
    ****************************************************/
    inline int getProductCode() {
        return productCode;
    }

    /****************************************************
                Function to Return Product Name
    ****************************************************/
    inline char* getProductName() {
        return productName;
    }
} shop;

