using namespace std;

typedef pair<int, int> IndexFrequencyPair;
typedef pair<float, int> FloatIndexPair;	
typedef pair<int, float> IndexFloatPair;

class CustomSorter {    
public:    
    bool operator()(const IndexFrequencyPair& pair1, const IndexFrequencyPair& pair2) {   
        if (pair1.second == pair2.second) {
            return pair1.first < pair2.first;
        }
        return pair1.second > pair2.second;
    }
};

class Graph {
private:
    int vertexCount;  
    vector<vector<IndexFloatPair>> adjacencyList; 
    vector<vector<int>> categoryList; 
    int edgeCount; 
    vector<vector<float>> distanceMatrix;
    vector<vector<float>> nextMatrix;
    bool requiresUpdate = true; 

public:
    Graph(int vertices) {
        vertexCount = vertices;
        adjacencyList.resize(vertices + 1);
        categoryList.resize(vertices + 1);	
        scanf("%d\n", &edgeCount);

        int categoryIndex;
        for (int j = 0; j < vertexCount; j++) {
            cin >> categoryIndex;
            categoryList[categoryIndex].push_back(j + 1);
        }

        int vertex1, vertex2;
        float weight;
        for (int i = 0; i < edgeCount; i++) {
            cin >> vertex1 >> vertex2 >> weight;
            addEdge(vertex1, vertex2, weight);	
        }
    }

    void addEdge(int vertex1, int vertex2, float weight) {
        IndexFloatPair edge = make_pair(vertex2, weight);
        adjacencyList[vertex1].push_back(edge);
    } 

    void calculateMinimumTime(int source, float optimalWeight, int printFlag) {
        vector<float> distances(vertexCount + 1, pow(2, 20));
        priority_queue<FloatIndexPair, vector<FloatIndexPair>, greater<FloatIndexPair>> priorityQueue;
        priorityQueue.push(make_pair(0, source));
        distances[source] = 0;

        while (!priorityQueue.empty()) {
            int currentVertex = priorityQueue.top().second;
            priorityQueue.pop();
            for (const auto& neighbor : adjacencyList[currentVertex]) {
                int adjacentVertex = neighbor.first;
                float edgeWeight = neighbor.second;
                if (distances[adjacentVertex] > distances[currentVertex] + edgeWeight) {
                    distances[adjacentVertex] = distances[currentVertex] + edgeWeight;
                    priorityQueue.push(make_pair(distances[adjacentVertex], adjacentVertex));
                }
            }
        }

        if (printFlag == 1) {
            for (int i = 1; i <= vertexCount; i++) {
                if (distances[i] < pow(2, 20) && distances[i] != 0) {
                    printf("%0.3f ", distances[i]);    
                } else if (distances[i] == 0) {
                    cout << "0.000 ";
                } else {
                    cout << "-1.000 "; 
                }
            }
        } else {
            requiresUpdate = true;
            for (auto& neighbor : adjacencyList[source]) {
                if (neighbor.second > optimalWeight) {
                    neighbor.second = optimalWeight;
                    distances[neighbor.first] = optimalWeight;    
                }
            }
            for (int i = 1; i <= vertexCount; i++) {
                if (distances[i] > optimalWeight) {
                    addEdge(source, i, optimalWeight);
                }
            }
        }
    }

    void findTopK(int category, int k) {
        vector<IndexFrequencyPair> frequencyReference(vertexCount + 1, make_pair(0, 0));

        for (int i = 0; i < categoryList[category].size(); i++) {
            int currentVertex = categoryList[category][i];
            for (const auto& neighbor : adjacencyList[currentVertex]) {                  
                int adjacentVertex = neighbor.first;
                frequencyReference[adjacentVertex].second++;
            }
        }

        CustomSorter sorter;
        sort(frequencyReference.begin(), frequencyReference.end(), sorter);

        int size = 0;
        for (int l = 0; l < frequencyReference.size(); l++) {
            if (frequencyReference[l].second == 0) {
                size = l;
                break;
            }
        }
        k = min(k, size);
        for (int i = 0; i < k; i++) {
            cout << frequencyReference[i].first;
            if (i != k - 1) {
                cout << " ";	
            }
        }
    }

    void calculatePairwiseDistance(int category1, int category2) {
        if (requiresUpdate) {
            distanceMatrix = vector<vector<float>>(vertexCount + 1, vector<float>(vertexCount + 1, pow(2, 20)));
            nextMatrix = vector<vector<float>>(vertexCount + 1, vector<float>(vertexCount + 1, -1));
            for (int i = 1; i <= vertexCount; i++) {
                for (const auto& neighbor : adjacencyList[i]) {
                    int adjacentVertex = neighbor.first;
                    distanceMatrix[i][adjacentVertex] = neighbor.second;
                    nextMatrix[i][adjacentVertex] = adjacentVertex;
                }
            }

            for (int k = 1; k <= vertexCount; k++) {
                for (int i = 1; i <= vertexCount; i++) {
                    for (int j = 1; j <= vertexCount; j++) {
                        if (distanceMatrix[i][k] + distanceMatrix[k][j] < distanceMatrix[i][j]) {
                            distanceMatrix[i][j] = distanceMatrix[i][k] + distanceMatrix[k][j];
                            nextMatrix[i][j] = nextMatrix[i][k];
                        } else if (distanceMatrix[i][k] + distanceMatrix[k][j] == distanceMatrix[i][j]) {
                            if (nextMatrix[i][j] > nextMatrix[i][k]) {
                                nextMatrix[i][j] = nextMatrix[i][k];
                            }
                        }
                    }
                }
            }
            requiresUpdate = false;
        }        

        vector<int> path;
        for (int j1 = 0; j1 < categoryList[category1].size(); j1++) {
            for (int j2 = 0; j2 < categoryList[category2].size(); j2++) {
                int vertex1 = categoryList[category1][j1];
                int vertex2 = categoryList[category2][j2];
                if (nextMatrix[vertex1][vertex2] == -1) {
                    cout << vertex1 << " " << vertex2;
                    printf("\t");
                    cout << "-1";
                } else {                       
                    int currentVertex = vertex1;
                    cout << vertex1 << " " << vertex2 << "\t" << vertex1 << " ";
                    while (currentVertex != vertex2) {
                        currentVertex = nextMatrix[currentVertex][vertex2];
                        cout << currentVertex << " ";
                    }
                }
                cout << endl;
            }
        }
    }
};

int main() {
    int numberOfVertices;
    cin >> numberOfVertices;
    Graph graph(numberOfVertices);
    string command;
    int parameter1, parameter2;
    float parameter3;

    while (cin >> command >> parameter1) {
        if (command == "sssp") {
            graph.calculateMinimumTime(parameter1, 1, 1);
            cout << endl;
        } else if (command == "update") {
            cin >> parameter3;
            graph.calculateMinimumTime(parameter1, parameter3, 0);
        } else if (command == "top-k") {
            cin >> parameter2;
            graph.findTopK(parameter1, parameter2);
            cout << endl;
        } else if (command == "apsp") {
            cin >> parameter2;
            graph.calculatePairwiseDistance(parameter1, parameter2);
        }
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

using namespace std;

class TrieNode {
public:
    bool isEndOfWord;
    TrieNode* children[26];
    int frequency;

    // Initializes a new TrieNode with default values
    TrieNode() {
        isEndOfWord = false;
        frequency = 0;
        fill(begin(children), end(children), nullptr);
    }
};

class Trie {
public:
    // Inserts a word into the Trie
    void insert(TrieNode* root, const string& word) {
        TrieNode* currentNode = root;
        for (char character : word) {
            int index = character - 'a';
            if (!currentNode->children[index]) {
                currentNode->children[index] = new TrieNode();
            }
            currentNode = currentNode->children[index];
        }
        currentNode->isEndOfWord = true;
    }

    // Prints all words in the Trie that are descendants of the given node
    void printProgeny(TrieNode* node, const string& prefix) {
        if (node->isEndOfWord) {
            cout << prefix << " ";
        }

        for (int i = 0; i < 26; i++) {
            if (node->children[i]) {
                printProgeny(node->children[i], prefix + static_cast<char>(i + 'a'));
            }
        }
    }

    // Searches for a word in the Trie and prints its frequency or progeny
    void search(TrieNode* root, const string& word) {
        TrieNode* currentNode = root;
        for (char character : word) {
            int index = character - 'a';
            currentNode = currentNode->children[index];
            if (!currentNode) {
                cout << word << " ";
                printProgeny(root, word);
                return;
            }
        }
        if (currentNode->isEndOfWord) {
            cout << word << " " << ++(currentNode->frequency);
        } else {
            cout << word << " ";
            printProgeny(currentNode, word);
        }
    }
};

int main() {
    int numberOfWords, numberOfSearches;
    cin >> numberOfWords >> numberOfSearches;

    Trie trie;
    TrieNode* root = new TrieNode();

    string word;
    for (int i = 0; i < numberOfWords; i++) {
        cin >> word;
        trie.insert(root, word);
    }
    for (int j = 0; j < numberOfSearches; j++) {
        cin >> word;
        trie.search(root, word);
        cout << endl;
    }

    return 0;
}

#include <iostream>
#include <climits>
#include <stack>
#include <queue>

using namespace std;

// Class representing multiple stacks within a single array
class MultiStack {
    int *dataArray;   // Array to store stack elements
    int *stackTops;   // Array to track the top index of each stack
    int *nextFree;    // Array to manage free slots in the data array
    int totalSize, stackCount;
    int freeIndex;    // Index of the first free slot

public:
    // Constructor to initialize multiple stacks
    MultiStack(int stackCount, int totalSize);

    // Check if all stacks are full
    bool isFull() const { return (freeIndex == -1); }

    // Push an item onto the specified stack
    void push(int item, int stackNumber);

    // Pop an item from the specified stack
    int pop(int stackNumber);

    // Check if the specified stack is empty
    bool isEmpty(int stackNumber) const { return (stackTops[stackNumber] == -1); }
};

// Constructor to initialize multiple stacks
MultiStack::MultiStack(int stackCount, int totalSize) {
    this->stackCount = stackCount;
    this->totalSize = totalSize;
    dataArray = new int[totalSize];
    stackTops = new int[stackCount];
    nextFree = new int[totalSize];

    // Initialize all stacks as empty
    for (int i = 0; i < stackCount; i++) {
        stackTops[i] = -1;
    }

    // Initialize all slots as free
    freeIndex = 0;
    for (int i = 0; i < totalSize - 1; i++) {
        nextFree[i] = i + 1;
    }
    nextFree[totalSize - 1] = -1;  // -1 indicates the end of the free list
}

// Push an item onto the specified stack
void MultiStack::push(int item, int stackNumber) {
    // Check for stack overflow
    if (isFull()) {
        cout << "\nStack Overflow\n";
        return;
    }

    int currentIndex = freeIndex; // Store index of the first free slot
    freeIndex = nextFree[currentIndex]; // Update freeIndex to the next free slot

    // Update the next pointer for the new top of the stack
    nextFree[currentIndex] = stackTops[stackNumber];
    stackTops[stackNumber] = currentIndex;

    // Store the item in the data array
    dataArray[currentIndex] = item;
}

// Pop an item from the specified stack
int MultiStack::pop(int stackNumber) {
    // Check for stack underflow
    if (isEmpty(stackNumber)) {
        return INT_MAX; // Return a sentinel value for underflow
    }

    int currentIndex = stackTops[stackNumber]; // Get the index of the top item
    stackTops[stackNumber] = nextFree[currentIndex]; // Update the top index

    // Reattach the popped index to the free list
    nextFree[currentIndex] = freeIndex;
    freeIndex = currentIndex;

    // Return the popped item
    return dataArray[currentIndex];
}

int main() {
    // Create multiple stacks in an array of specified size
    int stackCount;
    int totalSize = 200;

    cin >> stackCount;

    MultiStack multiStack(stackCount, totalSize);

    int inputValue;
    cin >> inputValue;
    int initialValue = inputValue;
    multiStack.push(inputValue, 0);
    int depth = 0;

    while (!cin.eof()) {
        cin >> inputValue;
        if (inputValue == initialValue) depth++;
        multiStack.push(inputValue, depth);
    }

    stack<int> mainStack, sideStack;
    int stackSizes[stackCount];
    int stringSizes[stackCount];
    int tempSizes[stackCount];

    for (int i = 1; i < stackCount; i++) {
        // Transfer items from the main stack to a temporary stack
        while (!multiStack.isEmpty(0)) {
            int poppedValue = multiStack.pop(0);
            mainStack.push(poppedValue);
        }

        // Transfer items from the current stack to a side stack
        while (!multiStack.isEmpty(i)) {
            int poppedValue = multiStack.pop(i);
            sideStack.push(poppedValue);
        }

        int currentStringSize = sideStack.size();
        stringSizes[i] = currentStringSize;
        int matchCount = 0;

        // Compare items from both stacks
        while (!mainStack.empty() || !sideStack.empty()) {
            int mainValue = 0, sideValue = 0;
            if (!mainStack.empty()) {
                mainValue = mainStack.top();
                mainStack.pop();
                multiStack.push(mainValue, 0);
            }

            if (!sideStack.empty()) {
                sideValue = sideStack.top();
                sideStack.pop();
                multiStack.push(sideValue, i);
            }

            if (mainValue == sideValue) matchCount++; // Count matching indices
        }
        tempSizes[i] = currentStringSize - matchCount;
        stackSizes[i] = currentStringSize - matchCount;
    }

    queue<int> resultQueue;

    // Transfer items from the main stack to a temporary stack
    stack<int> tempStack;
    while (!multiStack.isEmpty(0)) {
        int poppedValue = multiStack.pop(0);
        tempStack.push(poppedValue);
    }

    // Push items from the temporary stack to the result queue
    while (!tempStack.empty()) {
        int tempValue = tempStack.top();
        tempStack.pop();
        resultQueue.push(tempValue);
    }

    // Process each stack to fill the result queue
    for (int s = 1; s < stackCount; s++) {
        int minSize = 101;
        int selectedStack;

        for (int i = 1; i < stackCount; i++) {
            if (tempSizes[i] < minSize) {
                minSize = tempSizes[i];
                selectedStack = i;
            }
        }
        tempSizes[selectedStack] = 102; // Mark as processed

        stack<int> tempStackForQueue; // Temporary stack for queuing elements

        // Transfer items from the selected stack to the temporary stack
        for (int q = 0; q < stackSizes[selectedStack]; q++) {
            int trashValue = multiStack.pop(selectedStack);
            tempStackForQueue.push(trashValue);
        }

        // Push items from the temporary stack to the result queue
        for (int g = 0; g < stackSizes[selectedStack]; g++) {
            int queuedValue = tempStackForQueue.top();
            tempStackForQueue.pop();
            resultQueue.push(queuedValue);
        }
    }

    // Output the final queue
    while (!resultQueue.empty()) {
        cout << resultQueue.front() << " ";
        resultQueue.pop();
    }

    return 0;
}

