// Base class representing a generic shape
class Shape {
public:
    virtual int Area() = 0; // Pure virtual function for calculating area
};

// Derived class representing a rectangle with area calculation and operator overloading
class Rectangle : public Shape {
public:
    Rectangle(int x1, int y1, int x2, int y2) {
        vertexOne.x = x1;
        vertexOne.y = y1;
        vertexTwo.x = x2;
        vertexTwo.y = y2;
    }

    int Area() override {
        return (abs(vertexOne.x - vertexTwo.x) * abs(vertexOne.y - vertexTwo.y));
    }

    int operator+(const Rectangle& other) {
        int maxX = max(vertexOne.x, other.vertexOne.x);
        int minY = min(vertexOne.y, other.vertexOne.y);
        int minX = min(vertexTwo.x, other.vertexTwo.x);
        int maxY = max(vertexTwo.y, other.vertexTwo.y);

        if (maxX > minX || minY < maxY) {
            cout << "-1" << endl;
        } else if (maxX == minX && minY == maxY) {
            cout << maxX << " " << minY << " " << "0" << "\n";
        } else {
            cout << setprecision(0) << fixed;
            cout << maxX << " " << minY << " " << minX << " " << maxY << " " << abs((maxX - minX) * (minY - maxY)) << "\n";
        }
        return 0;
    }

protected:
    Vertex vertexOne;
    Vertex vertexTwo;
};

// Derived class representing a circle with area calculation and operator overloading
class Circle : public Shape {
public:
    Circle(int x, int y, int r) {
        center.setCoordinates(x, y);
        radius = r;
    }

    double Area() override {
        return (3.14 * radius * radius);
    }

    int operator+(const Circle& other) {
        double distanceBetweenCenters = abs(other.center.x - center.x);

        // Check for non-intersecting circles
        if (distanceBetweenCenters > (radius + other.radius)) {
            cout << setprecision(2) << fixed << "-1" << " ";
            cout << trunc(Area() * 100) / 100 << " " << trunc(other.Area() * 100) / 100 << "\n";
            return 0;
        }

        // Check for one circle completely inside another
        if (distanceBetweenCenters < (radius - other.radius) || distanceBetweenCenters < (other.radius - radius)) {
            cout << setprecision(2) << fixed;
            cout << "0" << " " << trunc(Area() * 100) / 100 << " " << trunc(other.Area() * 100) / 100 << "\n";
            return 0;
        }

        // Check for overlapping circles
        if (distanceBetweenCenters == 0) {
            cout << setprecision(2) << fixed;
            cout << "0" << " " << trunc(Area() * 100) / 100 << " " << trunc(other.Area() * 100) / 100 << "\n";
            return 0;
        }

        // Calculate intersection points
        double a = (pow(radius, 2) - pow(other.radius, 2) + pow(distanceBetweenCenters, 2)) / (2 * distanceBetweenCenters);
        double p2x = center.x + a * (other.center.x - center.x) / distanceBetweenCenters;
        double p2y = center.y;

        double h = sqrt(pow(radius, 2) - pow(a, 2));
        double intersectX1, intersectX2, intersectY1, intersectY2;

        if (other.center.x - center.x > 0) {
            intersectY1 = p2y - h * (other.center.x - center.x) / distanceBetweenCenters;
            intersectY2 = p2y + h * (other.center.x - center.x) / distanceBetweenCenters;
            intersectX1 = p2x;
            intersectX2 = p2x;
        } else {
            intersectY1 = p2y + h * (other.center.x - center.x) / distanceBetweenCenters;
            intersectY2 = p2y - h * (other.center.x - center.x) / distanceBetweenCenters;
            intersectX1 = p2x;
            intersectX2 = p2x;
        }

        // Output intersection points and areas
        if ((intersectX1 == intersectX2) && (intersectY1 == intersectY2)) {
            cout << setprecision(2) << fixed;
            cout << trunc(intersectX1 * 100) / 100 << " " << trunc(intersectY1 * 100) / 100;
            cout << " " << trunc(Area() * 100) / 100 << " " << trunc(other.Area() * 100) / 100 << "\n";
        } else {
            cout << setprecision(2) << fixed;
            cout << trunc(intersectX1 * 100) / 100 << " " << trunc(intersectY1 * 100) / 100 << " "
                 << trunc(intersectX2 * 100) / 100 << " " << trunc(intersectY2 * 100) / 100;
            cout << " " << trunc(Area() * 100) / 100 << " " << trunc(other.Area() * 100) / 100 << "\n";
        }
        return 0;
    }

protected:
    Vertex center;
    int radius;
};

int main() {
    int numberOfShapes;
    cin >> numberOfShapes;

    // Process each shape based on user input
    for (int i = 0; i < numberOfShapes; i++) {
        char shapeType;
        int a, b, c1, d, e, f, g, h;

        cin >> shapeType;

        if (shapeType == 'C') {
            cin >> a >> b >> c1 >> d >> e >> f;
            Circle circle1(a, b, c1);
            Circle circle2(d, e, f);
            circle1 + circle2;
        }

        if (shapeType == 'R') {
            cin >> a >> b >> c1 >> d >> e >> f >> g >> h;
            Rectangle rectangle1(a, b, c1, d);
            Rectangle rectangle2(e, f, g, h);
            rectangle1 + rectangle2;
        }
    }

    return 0;
}

