class Matrix {
private:
    long int rows, cols; 
    long int data[100][100]; 

public:
    // Constructor to initialize the matrix with user input
    Matrix(long int row_count, long int col_count) {
        rows = row_count; 
        cols = col_count;

        for (long int i = 0; i < rows; i++) {
            for (long int j = 0; j < cols; j++) {
                long long int element;
                cin >> element;
                data[i][j] = element;
            }
        }
    }

    // Function to print the matrix
    void PrintMatrix() {
        for (long int i = 0; i < rows; i++) {
            for (long int j = 0; j < cols; j++) {
                cout << data[i][j] << " ";
            }
            cout << endl;
        }
    }

    // Overloaded operator for special addition
    Matrix operator+(Matrix M) {
        long int column_count = (cols < M.cols) ? cols : M.cols;

        for (long int i = 0; i < rows; i++) {
            long int max_value, max_row, max_column, source_matrix = 0;
            long int temp = 0;

            // Find maximum absolute value in the current row of this matrix
            for (long int j = 0; j < cols; j++) {
                if (abs(data[i][j]) > temp) {
                    temp = abs(data[i][j]);
                    max_row = i;
                    max_column = j;
                    source_matrix = 0; 
                }
                if (abs(data[i][j]) == temp && data[i][j] > 0) {
                    temp = data[i][j];
                    max_row = i;
                    max_column = j;
                    source_matrix = 0;
                }
            }

            // Find maximum absolute value in the current row of the second matrix
            for (long int k = 0; k < M.cols; k++) {
                if (abs(M.data[i][k]) > temp) {
                    temp = abs(M.data[i][k]);
                    max_row = i;
                    max_column = k;
                    source_matrix = 1; 
                }
                if (abs(M.data[i][k]) == temp && M.data[i][k] > 0) {
                    temp = M.data[i][k];
                    max_row = i;
                    max_column = k;
                    source_matrix = 1;
                }
            }

            // Output the determined maximum value
            if ((source_matrix == 0 && data[max_row][max_column] <= 0) || 
                (source_matrix == 1 && M.data[max_row][max_column] <= 0)) {
                cout << (-1) * temp << " ";
            } else {
                cout << temp << " ";
            }

            // Set the used element to zero
            if (source_matrix == 0) {
                data[max_row][max_column] = 0;
            } else {
                M.data[max_row][max_column] = 0;
            }
        }
        cout << "\n";
        return M;
    }

    // Overloaded operator to find the maximum sum of the matrix
    long int operator&() {
        long int prev_max = pow(2, 56);
        long int sum = 0;
        long int current_max = 0;
        char status;

        // Iterate from the last row to find the maximum sum
        for (long int i = rows - 1; i >= 0; i--) {
            status = CheckForMaximum(prev_max, &data[i][0], cols);
            if (status == 'N' && i != rows - 1) {
                cout << "NO" << endl; 
                return 0;
            }
            current_max = FindMaximum(prev_max, &data[i][0], cols);
            prev_max = current_max;
            sum += current_max;
        }

        cout << sum << endl;
        return 0;
    }

    // Overloaded operator for convolution operation
    Matrix operator-(Matrix M) {
        for (long int main_row = 0; main_row < rows - M.rows + 1; main_row++) {
            for (long int main_column = 0; main_column < cols - M.cols + 1; main_column++) {
                long int sum = 0;
                for (long int small_row = 0; small_row < M.rows; small_row++) {
                    for (long int small_column = 0; small_column < M.cols; small_column++) {
                        sum += M.data[small_row][small_column] * data[main_row + small_row][main_column + small_column];
                    }
                }
                cout << sum << " "; 
            }
            cout << endl;
        }
        return M;
    }

    // Overloaded operator for rotating the matrix
    long int operator*(long int rotations) {
        if (rows == 1) {
            long int array[cols];
            for (int i = 0; i < cols; i++) {
                array[i] = data[0][i];
            }
            for (long int j = 0; j < rotations; j++) {
                RotateArray(array, cols);
            }
            for (int l = 0; l < cols; l++) {
                cout << array[l] << " ";
            }
            cout << endl;
            return 0;
        }

        if (cols == 1) {
            long int array[rows];
            for (int i = 0; i < rows; i++) {
                array[i] = data[i][0];
            }
            for (long int j = 0; j < rotations; j++) {
                RotateArray(array, rows);
            }
            for (int l = 0; l < rows; l++) {
                cout << array[l] << " ";
            }
            cout << endl;
            return 0;
        }

        long int perimeter_size = 2 * (rows + cols) - 4;
        long int array[perimeter_size];

        // Store perimeter elements in an array
        for (long int i = 0; i < cols; i++) {
            array[i] = data[0][i];
        }
        for (long int i = 1; i < rows; i++) {
            array[cols + i - 1] = data[i][cols - 1];
        }
        for (long int i = cols - 2; i >= 0; i--) {
            array[2 * cols + rows - 3 - i] = data[rows - 1][i];
        }
        for (long int i = rows - 2; i > 0; i--) {
            array[2 * cols + 2 * rows - 4 - i] = data[i][0];
        }

        // Perform the required number of rotations
        for (long int i = 0; i < rotations; i++) {
            RotateArray(array, perimeter_size);
        }

        // Update the matrix with rotated values
        for (long int i = 0; i < cols; i++) {
            data[0][i] = array[i];
        }
        for (long int i = 1; i < rows; i++) {
            data[i][cols - 1] = array[cols + i - 1];
        }
        for (long int i = cols - 2; i >= 0; i--) {
            data[rows - 1][i] = array[2 * cols + rows - 3 - i];
        }
        for (long int i = rows - 2; i > 0; i--) {
            data[i][0] = array[2 * cols + 2 * rows - 4 - i];
        }

        PrintMatrix();
        return 0;
    }
};

// Function to find the maximum element in a row of the matrix that is less than prev_max
long int FindMaximum(long int prev_max, long int* B, long int columns) {
    long int max_value = -INF;
    long int first_element = *B;

    for (long int k = 1; k < columns; k++) {
        if ((max_value < *(++B)) && prev_max > *(B)) { 
            max_value = *(B);
        } 
    }

    if (first_element > max_value && first_element < prev_max) {
        max_value = first_element;
    }

    return max_value;
}

// Function to check if a maximum value exists
char CheckForMaximum(long int prev_max, long int* B, long int columns) {
    long int max_value = -INF;       
    char result = 'N';

    if (*B < prev_max) result = 'Y';

    for (long int k = 1; k < columns; k++) {
        if ((max_value < *(++B)) && prev_max > *(B)) {            
            result = 'Y';
            max_value = *(B);
        } 
    }                    
    return result;
}

// Function to rotate the array elements
void RotateArray(long int* Arr, long int size) {
    for (long int i = size - 1; i >= 0; i--) {
        Arr[i + 1] = Arr[i];
    }
    Arr[0] = Arr[size];
}

