#include <vector>
using namespace std;

class ArraySearch {
public:
    // Performs binary search to find the index of the element if present
    int BinarySearch(vector<int> array, int target, int start, int end, bool &found) {
        if (array[start] > target) return -1;

        int mid;
        while (start <= end) {
            mid = (start + end) / 2;
            if (target >= array[mid]) {
                start = mid + 1;
            } else {
                end = mid - 1;
            }
        }

        if (target == array[start - 1]) found = true;
        return start - 1;
    }

    // Performs linear search to find the index of the element if present
    int LinearSearch(vector<int> array, int target, int start, int end, bool &found) {
        for (int i = end; i >= 0; i--) {
            if (array[i] <= target) {
                if (array[i] == target) {
                    found = true;
                }
                return i;
            }
        }
        return -1;
    }
};

class Client {
public:
    // Computes the lower bound using binary search
    int lower_bound(vector<int> array, int target, int start, int end, bool &found) {
        ArraySearch searchAlgorithm;
        bool tempFlag = true;

        int index = searchAlgorithm.BinarySearch(array, target, start, end, tempFlag);
        found = tempFlag; // Update the original found flag
        return index; // Return the index found
    }

    // Computes the upper bound using binary search
    int upper_bound(vector<int> array, int target, int start, int end, bool &found) {
        ArraySearch searchAlgorithm;
        bool tempFlag = true;
        int index = searchAlgorithm.BinarySearch(array, target, start, end, tempFlag);

        found = tempFlag; // Update the original found flag

        // Handle corner cases for upper bound
        if (index == -1) index = start - 1;
        if (index == end) index = -2;

        return index + 1; // Adjust index according to upper bound definition
    }
};

int main() {
    vector<int> elements;
    ArraySearch searchAlgorithm;
    Client client;

    int n;
    cin >> n;

    for (int i = 0; i < n; i++) {
        int temp;
        cin >> temp;
        elements.push_back(temp); // Populate the vector with input elements
    }

    string operation;
    int target, start, end;

    // First operation: Binary search
    cin >> operation >> target >> start >> end;
    bool found = true;
    int index = searchAlgorithm.BinarySearch(elements, target, start, end - 1, found);
    cout << index;

    // Second operation: Linear search
    cin >> operation >> target >> start >> end;
    found = true;
    index = searchAlgorithm.LinearSearch(elements, target, start, end - 1, found);
    cout << endl << index;

    // Third operation: Lower bound
    cin >> operation >> target >> start >> end;
    found = true;
    index = client.lower_bound(elements, target, start, end - 1, found);
    cout << endl << index;

    // Fourth operation: Upper bound
    cin >> operation >> target >> start >> end;
    found = true;
    index = client.upper_bound(elements, target, start, end - 1, found);
    cout << endl << index; // Output results after each operation

    return 0;
}

