                cin >> inputValue; 
                data[i][j] = inputValue;
            }
        }		    
    }   
};

class SortedArray : public Matrix {
public:
    // Function to search for an element in the sorted 2D array
    // Operates in O(m+n) time with O(1) auxiliary space
    pair<int, int> searchElement() {
        long int targetElement;
        cin >> targetElement;

        int rowIndex = 0;
        int colIndex = cols - 1;

        // Start searching from the top-right corner of the matrix
        while (rowIndex < rows && colIndex >= 0) {
            if (data[rowIndex][colIndex] == targetElement) {
                return make_pair(rowIndex, colIndex); // Return the coordinates if found
            }

            if (data[rowIndex][colIndex] > targetElement) {
                colIndex--; // Move left if the current element is greater
            } else {
                rowIndex++; // Move down if the current element is smaller
            }
        }
        return make_pair(-1, -1); // Return (-1, -1) if the element is not found
    }
};

int main() {
    Matrix matrixInstance; // Create and populate the matrix

    SortedArray sortedArrayInstance; // Initialize an object for sorted search operations
    pair<int, int> result = sortedArrayInstance.searchElement();
    cout << result.first << " " << result.second << endl;

    return 0;
}

