#define INT_MAX pow(33, 2)
#define INT_MIN -1 * pow(33, 2) // Define extreme values for array element limits

int BinarySearch(const vector<int>& sortedArray, int target, int start, int end) {
    // Perform binary search to find the index of the target in the sorted array
    if (sortedArray[start] > target) return -1;

    int mid;
    while (start <= end) {
        mid = (start + end) / 2;
        if (target >= sortedArray[mid]) 
            start = mid + 1;
        else 
            end = mid - 1; // Handle potential duplicates in O(n) time
    }

    return start - 1; 
}

class Matrix {
public:
    int rowCount, colCount;
    vector<vector<int>> data;

    // Constructor to initialize and populate the 2D array
    Matrix() {
        int inputValue;
        cin >> rowCount >> colCount;
        data.resize(rowCount);
        for (int i = 0; i < rowCount; i++)
            data[i].resize(colCount);

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                cin >> inputValue; 
                data[i][j] = inputValue;
            }
        }		    
    }   
};

class Client {
public:
    // Compute the upper bound of a target value in a sorted array
    int upper_bound(const vector<int>& sortedArray, long int& target, int start, int& end) {
        int index = BinarySearch(sortedArray, target, start, end);

        // Handle corner cases for the upper bound
        if (index == -1) index = start - 1;
        if (index == end) index = -2;

        return index + 1; // Adjust output for upper bound definition
    }
};

class RowSortedArray : public Matrix {
public:
    // Find the median of the matrix
    int find_median() {
        Client client;
        long int minValue = INT_MAX, maxValue = INT_MIN;

        // Determine the minimum and maximum values in the first and last columns
        for (int i = 0; i < rowCount; i++) {
            if (data[i][0] < minValue)
                minValue = data[i][0];
            if (data[i][colCount - 1] > maxValue)
                maxValue = data[i][colCount - 1];
        }  

        int desiredCount = (rowCount * colCount + 1) / 2;
        while (minValue < maxValue) { // Loop until the assumed median converges
            long int midValue = minValue + (maxValue - minValue) / 2; 
            long int countLessThanMid = 0;

            for (int i = 0; i < rowCount; ++i) {
                int count = client.upper_bound(data[i], midValue, 0, colCount);
                // Count elements less than the assumed median
                countLessThanMid += (count != -1) ? count : colCount; 
            }

            if (countLessThanMid < desiredCount)
                minValue = midValue + 1; // Adjust median upwards
            else 
                maxValue = midValue; // Adjust median downwards
        }
        return minValue;
    }    
};

int main() {
    Matrix matrix; // Create and populate a 2D array
    RowSortedArray sortedArray; // Instantiate an object to use the find_median function
    int median = sortedArray.find_median(); // Find and return the median

    cout << median;

    return 0;
}

