class Token {
private:
    string tokenName;
    int tokenType; // 0 for variable; 1 for constant; 2 for operator.
    int tokenValue;
    char operatorChar;

public:
    int getType() const {
        return tokenType;
    }

    void setType(int type) {
        tokenType = type;
    }

    bool isInitialized() const; // for variable
    bool isValid() const; // for operator

    int operator+(const Token& other) const {
        return tokenValue + other.getValue();
    }

    int operator-(const Token& other) const {
        return tokenValue - other.getValue();
    }

    int operator+(int value) const {
        return tokenValue + value;
    }

    int operator-(int value) const {
        return tokenValue - value;
    }

    void setValue(int value) {
        tokenValue = value;
    }

    int getValue() const {
        return tokenValue;
    }

    void setName(const string& name) {
        tokenName = name;
    }

    string getName() const {
        return tokenName;
    }

    void setOperator(char op) {
        operatorChar = op;
    }

    char getOperator() const {
        return operatorChar;
    }
};

class Expression {
private:
    vector<Token> tokens;
    int expressionSize = 0;

public:
    void pushBack(const Token& token) {
        tokens.push_back(token);
        expressionSize++;
    }

    Token getToken(int index) const {
        return tokens[index];
    }

    // Validates the left-hand side of the expression for assignment
    int validateExpression() const {
        for (int i = 0; i < tokens.size(); i++) {
            if (tokens[i].getType() == 2 && tokens[i].getOperator() == '=' && i != 1) {
                cout << "Invalid l-value";
                return 0;
            }
        }
        return 1;
    }

    // Processes the expression for assignment or printing
    void processExpression() {
        if (tokens[1].getOperator() == '=') {
            if (tokens.size() == 3) {
                pair<string, int> assignment;
                assignment.first = tokens[0].getName();
                assignment.second = tokens[2].getValue();
                variableAssignments.insert(assignment);
            } else {
                int result = tokens[2].getValue();
                Token tempToken;
                tempToken.setValue(result);
                int plusCount = 0;
                int minusCount = 0;

                for (int i = 3; i < expressionSize; i += 2) {
                    if (tokens[i].getOperator() == '+') {
                        result += tempToken + tokens[i + 1];
                        plusCount++;
                    } else {
                        tempToken - tokens[i + 1];
                        minusCount++;
                    }
                    result -= (plusCount + minusCount - 1) * tokens[2].getValue();
                }

                tokens[0].setValue(result);
                pair<string, int> assignment;
                assignment.first = tokens[0].getName();
                assignment.second = result;
                variableAssignments.insert(assignment);
            }
        } else if (tokens[0].getType() == 3) {
            // Handles print statements
            for (int i = 1; i < expressionSize; i++) {
                if (tokens[i].getType() != 0) {
                    cout << "Expression is not allowed for print";
                } else {
                    cout << tokens[i].getValue() << " ";
                }
            }
            cout << endl;
        }
    }
};

int main() {
    string line;
    while (getline(cin, line)) {
        istringstream iss(line);
        vector<string> tokens{istream_iterator<string>{iss}, istream_iterator<string>{}};

        Expression expression;

        for (const auto& tokenStr : tokens) {
            Token token;
            if (isNumber(tokenStr)) {
                token.setType(1);
                int value = stoi(tokenStr);
                token.setValue(value);
            } else if (tokenStr == "43" || tokenStr == "45" || tokenStr == "61") {
                token.setType(2);
                char op = tokenStr[0];
                token.setOperator(op);
            } else {
                if (tokenStr != "print") {
                    token.setType(0);
                    token.setName(tokenStr);
                } else {
                    token.setType(3);
                }
            }
            expression.pushBack(token);
        }

        if (expression.validateExpression() == 0) return 0;
        expression.processExpression();
    }

    return 0;
}

bool isNumber(const string& str) {
    return all_of(str.begin(), str.end(), ::isdigit);
}

