    int employee_id;   // Unique identifier for the employee
    int employee_value; // The employee's value, which may change
    Employee* left_subordinate;
    Employee* right_subordinate;
    int height; // Height in the hierarchy

public:
    void set_supervisor_id(int id) {
        supervisor_id = id;
    }

    int get_supervisor_id() const {
        return supervisor_id;
    }

    void set_height(int h) {
        height = h;
    }

