    }
};

class Organisation {
private:
    int root_index;
    vector<int> supervisor_list;
    vector<Employee> employees; // Contains all employee data
    int employee_count;

public:
    Organisation(int count) {
        employee_count = count;
        for (int i = 0; i < employee_count; i++) {
            int supervisor_id;
            cin >> supervisor_id;
            supervisor_list.push_back(supervisor_id);
        }

        // Initialize employee objects
        for (int i = 0; i < employee_count; i++) {
            Employee emp;
            emp.set_supervisor_id(supervisor_list[i]);
            emp.set_employee_value(i);
            emp.set_employee_id(i);
            emp.set_left_subordinate(nullptr);
            emp.set_right_subordinate(nullptr);
            employees.push_back(emp);
        }

        // Establish left and right subordinate relationships
        for (int i = 0; i < employee_count; i++) {
            int supervisor_id = employees[i].get_supervisor_id();
            if (supervisor_id >= 0) {
                if (employees[supervisor_id].get_left_subordinate() == nullptr) {
                    employees[supervisor_id].set_left_subordinate(&employees[i]);
                } else {
                    employees[supervisor_id].set_right_subordinate(&employees[i]);
                }
            } else {
                root_index = i;
            }
        }

        // Initialize heights for each employee
        for (int i = 0; i < employee_count; i++) {
            employees[i].set_height(calculate_max_depth(&employees[i]));
        }
    }

    int get_root_index() const {
        return root_index;
    }

    Employee* get_head() {
        return &employees[root_index];
    }

    // Pre-order traversal using a stack
    void iterative_preorder(Employee* root) {
        if (root == nullptr) return;

        stack<Employee*> employee_stack;
        employee_stack.push(root);

        while (!employee_stack.empty()) {
            Employee* current_employee = employee_stack.top();
            employee_stack.pop();
            cout << current_employee->get_employee_id() << " ";

            if (current_employee->get_right_subordinate()) {
                employee_stack.push(current_employee->get_right_subordinate());
            }
            if (current_employee->get_left_subordinate()) {
                employee_stack.push(current_employee->get_left_subordinate());
            }
        }
    }

    // In-order traversal using a stack
    void inorder_iterative(Employee* root) {
        stack<Employee*> employee_stack;
        Employee* current = root;

        while (!employee_stack.empty() || current != nullptr) {
            if (current != nullptr) {
                employee_stack.push(current);
                current = current->get_left_subordinate();
            } else {
                current = employee_stack.top();
                employee_stack.pop();
                cout << current->get_employee_value() << " ";
                current = current->get_right_subordinate();
            }
        }
    }

    void print_level_order(Employee* root) {
        if (root == nullptr) return;

        int current_queue = 1;
        int level = 0;
        int level_product[100] = {1};
        queue<Employee*> queue1;
        queue<Employee*> queue2;

        queue1.push(root);

        while (!queue1.empty() || !queue2.empty()) {
            if (current_queue == 1) {
                if (queue1.empty()) {
                    current_queue++;
                    level++;
                    level_product[level] = 1;
                } else {
                    Employee* node = queue1.front();
                    level_product[level] *= node->get_employee_id();
                    cout << node->get_employee_id() << " ";
                    queue1.pop();

                    if (node->get_left_subordinate() != nullptr) {
                        queue2.push(node->get_left_subordinate());
                    }
                    if (node->get_right_subordinate() != nullptr) {
                        queue2.push(node->get_right_subordinate());
                    }
                }
            } else if (current_queue == 2) {
                if (queue2.empty()) {
                    current_queue--;
                    level++;
                    level_product[level] = 1;
                } else {
                    Employee* node = queue2.front();
                    level_product[level] *= node->get_employee_id();
                    cout << node->get_employee_id() << " ";
                    queue2.pop();

                    if (node->get_left_subordinate() != nullptr) {
                        queue1.push(node->get_left_subordinate());
                    }
                    if (node->get_right_subordinate() != nullptr) {
                        queue1.push(node->get_right_subordinate());
                    }
                }
            }
        }

        // Print level-wise products
        cout << endl;
        for (int i = 0; i <= level; i++) {
            cout << i + 1 << " " << level_product[i] << " ";
        }
    }

    int calculate_max_depth(Employee* emp) {
        if (emp == nullptr) return 0;

        int left_depth = calculate_max_depth(emp->get_left_subordinate());
        int right_depth = calculate_max_depth(emp->get_right_subordinate());

        return max(left_depth, right_depth) + 1;
    }

    int find_diameter() {
        int max_diameter = 0;
        for (int i = 0; i < employee_count; i++) {
            Employee* root = &employees[i];
            if (root->get_left_subordinate() != nullptr && root->get_right_subordinate() != nullptr) {
                max_diameter = max(max_diameter, root->get_left_subordinate()->get_height() + root->get_right_subordinate()->get_height() + 1);
            } else if (root->get_left_subordinate() != nullptr) {
                max_diameter = max(max_diameter, root->get_left_subordinate()->get_height() + 1);
            } else if (root->get_right_subordinate() != nullptr) {
                max_diameter = max(max_diameter, root->get_right_subordinate()->get_height() + 1);
            }
        }
        return max_diameter;
    }

    int modify(Employee* root) {
        int total_value, left_value, right_value;

        if (root->get_right_subordinate() == nullptr && root->get_left_subordinate() == nullptr) {
            return root->get_employee_value();
        } else if (root->get_right_subordinate() == nullptr) {
            total_value = modify(root->get_left_subordinate());
        } else {
            left_value = modify(root->get_left_subordinate());
            right_value = modify(root->get_right_subordinate());
            total_value = left_value + right_value;
        }

        // Ensure the employee's value does not decrease
        if (total_value < root->get_employee_id()) {
            int difference = root->get_employee_id() - total_value;
            Employee* iterator = root->get_left_subordinate();
            while (iterator != nullptr) {
                iterator->set_employee_value(difference + iterator->get_employee_value());
                iterator = iterator->get_left_subordinate();
            }
            return root->get_employee_value();
        } else {
            root->set_employee_value(total_value);
            return total_value;
        }
    }
};

int main() {
    int employee_count;
    scanf("%d\n", &employee_count);

    Organisation org(employee_count);
    Employee* root = org.get_head();

    cout << org.calculate_max_depth(root) << endl;
    org.print_level_order(root);
    cout << endl;
    org.iterative_preorder(root);
    cout << endl;

    int modified_value = org.modify(root);
    org.inorder_iterative(root);
    cout << endl;

    cout << org.find_diameter() << endl;

    return 0;
}

