// Functor for sorting pairs based on the first element
class PairSorter {    
public:    
    bool operator()(const IntPair& pair1, const IntPair& pair2) const {   
        return pair1.first < pair2.first;
    }
};

class Graph {
private:
    int vertexCount;   // Total number of vertices
    vector<vector<int>> adjacencyList; // Adjacency list representation of the graph
    int edgeCount, maxDistance; // Edge count and maximum distance
    vector<vector<int>> components; // Stores information about connected components

public:
    // Constructor initializes the graph with a given number of vertices
    Graph(int vertices) {
        vertexCount = vertices;
        adjacencyList.resize(vertices + 1);	
        scanf("%d %d\n", &edgeCount, &maxDistance);
        int vertex1, vertex2;
        for (int i = 0; i < edgeCount; i++) {
            cin >> vertex1 >> vertex2;
            addEdge(vertex1, vertex2);
            addEdge(vertex2, vertex1);
        }
    }

    void addEdge(int vertex, int neighbor) {
        adjacencyList[vertex].push_back(neighbor);
    } 

    // Counts the number of connected components in the graph
    int countComponents() {
        vector<bool> visited(vertexCount + 1, false);
        int componentCount = 0;
        for (int vertex = 1; vertex <= vertexCount; vertex++) {
            if (!visited[vertex]) {
                vector<int> component;
                component.push_back(vertex);
                performDFS(vertex, visited, component);
                components.push_back(component);
                componentCount++;
            }
        }
        return componentCount;
    }

    // Depth-First Search to explore the graph and mark components
    void performDFS(int vertex, vector<bool>& visited, vector<int>& component) {
        visited[vertex] = true; 
        for (int neighbor : adjacencyList[vertex]) {
            if (!visited[neighbor]) {
                component.push_back(neighbor);
                performDFS(neighbor, visited, component);
            }
        }
    }

    // Finds and prints all vertices reachable within a specified distance from the source
    void findShortestPaths(int source) {
        vector<int> distances(vertexCount + 1, pow(2, 23));
        priority_queue<IntPair, vector<IntPair>, greater<IntPair>> priorityQueue;
        priorityQueue.push(make_pair(0, source));
        distances[source] = 0;

        while (!priorityQueue.empty()) {
            int currentVertex = priorityQueue.top().second;
            priorityQueue.pop();
            for (int neighbor : adjacencyList[currentVertex]) {
                if (distances[neighbor] > distances[currentVertex] + 1) {
                    distances[neighbor] = distances[currentVertex] + 1;
                    priorityQueue.push(make_pair(distances[neighbor], neighbor));
                }
            }
        }

        int reachableCount = 0;
        for (int i = 1; i <= vertexCount; i++) {
            if (distances[i] <= maxDistance && distances[i] != 0) {
                printf("%d ", i);
                reachableCount++;
            }
        }
        if (reachableCount == 0) cout << "-1";
    }

    // Identifies the largest component and its root, also calls the shortest paths function
    int findLargestComponentAndSmallestSource() {
        int maxSize = 0, largestComponentIndex = 0;
        for (int i = 0; i < components.size(); i++) {
            int componentSize = components[i].size();
            if (componentSize > maxSize) {
                maxSize = componentSize;
                largestComponentIndex = i;
            } else if (componentSize == maxSize) {
                if (*max_element(components[i].begin(), components[i].end()) > 
                    *max_element(components[largestComponentIndex].begin(), components[largestComponentIndex].end())) {
                    largestComponentIndex = i;
                }
            }
        }

        int smallestRoot = *min_element(components[largestComponentIndex].begin(), components[largestComponentIndex].end());
        findShortestPaths(smallestRoot);

        int smallestSize = pow(2, 20), smallestComponentIndex = 0;
        for (int i = 0; i < components.size(); i++) {
            int componentSize = components[i].size();
            if (componentSize < smallestSize) {
                smallestSize = componentSize;
                smallestComponentIndex = i;
            } else if (componentSize == smallestSize) {
                if (*min_element(components[i].begin(), components[i].end()) < 
                    *min_element(components[smallestComponentIndex].begin(), components[smallestComponentIndex].end())) {
                    smallestComponentIndex = i;
                }
            }
        }

        return *max_element(components[smallestComponentIndex].begin(), components[smallestComponentIndex].end());
    }

    // Initiates auxiliary vectors and calls DFS to find pre and post timestamps of vertices
    void executeModifiedDFS(int source) {
        vector<bool> visited(vertexCount + 1, false);
        vector<IntPair> found, finished;
        int time = 0, count = 0;
        performModifiedDFS(source, visited, time, found, finished, count);
        PairSorter sorter;
        sort(found.begin(), found.end(), sorter);
        sort(finished.begin(), finished.end(), sorter);
        for (int i = 0; i < count; i++) {
            cout << found[i].first << " " << found[i].second << " " << finished[i].second << endl;
        }
    }

    // Finds the found and finished times of the nodes and stores them in the provided vectors
    void performModifiedDFS(int vertex, vector<bool>& visited, int& time, vector<IntPair>& found, vector<IntPair>& finished, int& count) {
        count++;      
        visited[vertex] = true; 
        found.push_back(make_pair(vertex, time));
        time += 2; // Time spent in the city
        sort(adjacencyList[vertex].begin(), adjacencyList[vertex].end());
        for (int neighbor : adjacencyList[vertex]) {
            if (!visited[neighbor]) {      
                time += 1; // Increment time for each new road encountered
                performModifiedDFS(neighbor, visited, time, found, finished, count);
            }  
        }
        finished.push_back(make_pair(vertex, time));
        time++;
    }

    // Checks for cycles in the graph based on the number of edges and components
    void checkForCycles() {
        if (edgeCount > (vertexCount - countComponents())) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
    }					  
};

int main() {
    int vertexCount;
    scanf("%d", &vertexCount);

    Graph graph(vertexCount);
    cout << graph.countComponents() << " ";
    graph.checkForCycles();
    int source = graph.findLargestComponentAndSmallestSource();
    cout << endl;
    graph.executeModifiedDFS(source);

    return 0;
}

