// Comparator for sorting pairs based on the first element
class PairComparator {
public:
    bool operator()(const pair<int, int>& firstPair, const pair<int, int>& secondPair) {
        return firstPair.first < secondPair.first;
    }
};

// Comparator for sorting integers
class IntComparator {
public:
    bool operator()(int firstInt, int secondInt) {
        return firstInt < secondInt;
    }
};

class Graph {
    int vertexCount, edgeCount;
    vector<vector<pair<int, int>>> adjacencyList;
    vector<int> vertexIds;
    map<int, int> idToIndexMap;
    map<int, int> indexToIdMap;

public:
    Graph() {}

    Graph(int vertices, int edges) : vertexCount(vertices), edgeCount(edges) {
        adjacencyList.resize(vertices);
    }

    void addVertex(int index, int vertexId) {
        vertexIds.push_back(vertexId);
        idToIndexMap[index] = vertexId;
        indexToIdMap[vertexId] = index;
    }

    void addEdge(int fromVertex, int toVertex, int weight) {
        adjacencyList[indexToIdMap[fromVertex]].emplace_back(toVertex, weight);
    }

    Graph operator+(const Graph& otherGraph) {
        int newVertexCount = vertexCount + otherGraph.vertexCount;
        int newEdgeCount = edgeCount + otherGraph.edgeCount;
        Graph combinedGraph(newVertexCount, newEdgeCount);

        sort(vertexIds.begin(), vertexIds.end());
        sort(otherGraph.vertexIds.begin(), otherGraph.vertexIds.end());

        for (size_t i = 0; i < vertexIds.size(); i++) {
            combinedGraph.addVertex(i, vertexIds[i]);
            for (const auto& edge : adjacencyList[indexToIdMap[vertexIds[i]]]) {
                combinedGraph.addEdge(vertexIds[i], edge.first, edge.second);
            }
        }

        for (size_t j = 0; j < otherGraph.vertexIds.size(); j++) {
            if (binary_search(combinedGraph.vertexIds.begin(), combinedGraph.vertexIds.end(), otherGraph.vertexIds[j])) {
                for (const auto& edge : otherGraph.adjacencyList[otherGraph.indexToIdMap[otherGraph.vertexIds[j]]]) {
                    auto it = find(adjacencyList[indexToIdMap[otherGraph.vertexIds[j]]].begin(),
                                   adjacencyList[indexToIdMap[otherGraph.vertexIds[j]]].end(), edge);
                    if (it == adjacencyList[indexToIdMap[otherGraph.vertexIds[j]]].end()) {
                        combinedGraph.addEdge(otherGraph.vertexIds[j], edge.first, edge.second);
                    } else {
                        combinedGraph.addEdge(otherGraph.vertexIds[j], edge.first, edge.second + it->second);
                    }
                }
            } else {
                combinedGraph.addVertex(vertexIds.size() + j, otherGraph.vertexIds[j]);
                for (const auto& edge : otherGraph.adjacencyList[otherGraph.indexToIdMap[otherGraph.vertexIds[j]]]) {
                    combinedGraph.addEdge(otherGraph.vertexIds[j], edge.first, edge.second);
                }
            }
        }
        return combinedGraph;
    }

    Graph operator-(const Graph& otherGraph) {
        int newVertexCount = vertexCount + otherGraph.vertexCount;
        int newEdgeCount = edgeCount + otherGraph.edgeCount;
        Graph differenceGraph(newVertexCount, newEdgeCount);

        sort(vertexIds.begin(), vertexIds.end());
        sort(otherGraph.vertexIds.begin(), otherGraph.vertexIds.end());

        for (size_t i = 0; i < vertexIds.size(); i++) {
            differenceGraph.addVertex(i, vertexIds[i]);
            for (const auto& edge : adjacencyList[indexToIdMap[vertexIds[i]]]) {
                differenceGraph.addEdge(vertexIds[i], edge.first, edge.second);
            }
        }

        for (size_t j = 0; j < otherGraph.vertexIds.size(); j++) {
            if (binary_search(differenceGraph.vertexIds.begin(), differenceGraph.vertexIds.end(), otherGraph.vertexIds[j])) {
                for (const auto& edge : otherGraph.adjacencyList[otherGraph.indexToIdMap[otherGraph.vertexIds[j]]]) {
                    auto it = find(adjacencyList[indexToIdMap[otherGraph.vertexIds[j]]].begin(),
                                   adjacencyList[indexToIdMap[otherGraph.vertexIds[j]]].end(), edge);
                    if (it == adjacencyList[indexToIdMap[otherGraph.vertexIds[j]]].end()) {
                        differenceGraph.addEdge(otherGraph.vertexIds[j], edge.first, edge.second);
                    } else {
                        differenceGraph.addEdge(otherGraph.vertexIds[j], edge.first, edge.second - it->second);
                    }
                }
            } else {
                differenceGraph.addVertex(vertexIds.size() + j, otherGraph.vertexIds[j]);
                for (const auto& edge : otherGraph.adjacencyList[otherGraph.indexToIdMap[otherGraph.vertexIds[j]]]) {
                    differenceGraph.addEdge(otherGraph.vertexIds[j], edge.first, edge.second);
                }
            }
        }
        return differenceGraph;
    }

    void printWeight(int fromVertex, int toVertex) {
        for (const auto& edge : adjacencyList[indexToIdMap[fromVertex]]) {
            if (edge.first == toVertex) {
                cout << edge.second << endl;
                return;
            }
        }
    }

    void printAdjacencyList(int vertex) {
        PairComparator comparator;
        sort(adjacencyList[indexToIdMap[vertex]].begin(), adjacencyList[indexToIdMap[vertex]].end(), comparator);
        for (const auto& edge : adjacencyList[indexToIdMap[vertex]]) {
            cout << edge.first << " ";
        }
        cout << endl;
    }

    void printDegreeSequence(int vertex) {
        PairComparator comparator;
        sort(adjacencyList[indexToIdMap[vertex]].begin(), adjacencyList[indexToIdMap[vertex]].end(), comparator);
        for (const auto& edge : adjacencyList[indexToIdMap[vertex]]) {
            cout << adjacencyList[indexToIdMap[edge.first]].size() << " ";
        }
        cout << endl;
    }

    void performDFS(int startVertex) {
        vector<bool> visited(vertexCount, false);
        performDFSUtil(startVertex, visited);
    }

private:
    void performDFSUtil(int vertex, vector<bool>& visited) {
        visited[indexToIdMap[vertex]] = true;
        cout << vertex << " ";

        PairComparator comparator;
        sort(adjacencyList[indexToIdMap[vertex]].begin(), adjacencyList[indexToIdMap[vertex]].end(), comparator);
        for (const auto& edge : adjacencyList[indexToIdMap[vertex]]) {
            if (!visited[indexToIdMap[edge.first]]) {
                performDFSUtil(edge.first, visited);
            }
        }
    }

public:
    void countComponents() {
        int componentCount = 0;
        vector<bool> visited(vertexCount, false);

        for (int vertex = 0; vertex < vertexCount; vertex++) {
            if (!visited[vertex]) {
                performDFSUtil(vertex, visited);
                componentCount++;
            }
        }
        cout << componentCount << endl;
    }
};

// BooleanGraph class derived from Graph class
class BooleanGraph : public Graph {
public:
    BooleanGraph() {}

    BooleanGraph(int vertices, int edges) : Graph(vertices, edges) {}

    void addVertex(int index, int vertexId) {
        idToIndexMap[index] = vertexId;
        indexToIdMap[vertexId] = index;
    }

    void addEdge(int fromVertex, int toVertex) {
        adjacencyList[indexToIdMap[fromVertex]].push_back(toVertex);
    }

    void printWeight(int fromVertex, int toVertex) {
        int edgeCount = 0;
        for (const auto& edge : adjacencyList[indexToIdMap[fromVertex]]) {
            if (edge == toVertex) {
                cout << 1 << endl;
                edgeCount++;
            }
        }
        if (edgeCount == 0) {
            cout << "0" << endl;
        }
    }

    void printAdjacencyList(int vertex) {
        IntComparator comparator;
        sort(adjacencyList[indexToIdMap[vertex]].begin(), adjacencyList[indexToIdMap[vertex]].end(), comparator);
        for (const auto& edge : adjacencyList[indexToIdMap[vertex]]) {
            cout << edge << " ";
        }
        cout << endl;
    }

    void printDegreeSequence(int vertex) {
        IntComparator comparator;
        sort(adjacencyList[indexToIdMap[vertex]].begin(), adjacencyList[indexToIdMap[vertex]].end(), comparator);
        for (const auto& edge : adjacencyList[indexToIdMap[vertex]]) {
            cout << adjacencyList[indexToIdMap[edge]].size() << " ";
        }
        cout << endl;
    }

    void performDFS(int startVertex) {
        vector<bool> visited(size, false);
        performDFSUtil(startVertex, visited);
    }

private:
    void performDFSUtil(int vertex, vector<bool>& visited) {
        visited[indexToIdMap[vertex]] = true;
        cout << vertex << " ";

        IntComparator comparator;
        sort(adjacencyList[indexToIdMap[vertex]].begin(), adjacencyList[indexToIdMap[vertex]].end(), comparator);
        for (const auto& edge : adjacencyList[indexToIdMap[vertex]]) {
            if (!visited[indexToIdMap[edge]]) {
                performDFSUtil(edge, visited);
            }
        }
    }
};

int main() {
    map<int, Graph> graphs;
    map<int, BooleanGraph> booleanGraphs;

    int graphCount, queryCount;
    cin >> graphCount >> queryCount;

    for (int k = 0; k < graphCount; k++) {
        int vertexCount, edgeCount, graphType;
        cin >> vertexCount >> edgeCount >> graphType;

        if (graphType == 0) {
            Graph graph(vertexCount, edgeCount);
            for (int i = 0; i < vertexCount; i++) {
                int vertexId;
                cin >> vertexId;
                graph.addVertex(i, vertexId);
            }
            for (int i = 0; i < edgeCount; i++) {
                int fromVertex, toVertex, weight;
                cin >> fromVertex >> toVertex >> weight;
                graph.addEdge(fromVertex, toVertex, weight);
            }
            graphs[k] = graph;
        } else {
            BooleanGraph booleanGraph(vertexCount, edgeCount);
            for (int i = 0; i < vertexCount; i++) {
                int vertexId;
                cin >> vertexId;
                booleanGraph.addVertex(i, vertexId);
            }
            for (int i = 0; i < edgeCount; i++) {
                int fromVertex, toVertex;
                cin >> fromVertex >> toVertex;
                booleanGraph.addEdge(fromVertex, toVertex);
            }
            booleanGraphs[k] = booleanGraph;
        }
    }

    for (int q = 0; q < queryCount; q++) {
        string query;
        cin >> query;

        if (query == "WEIGHT") {
            int fromVertex, toVertex, graphIndex;
            cin >> fromVertex >> toVertex >> graphIndex;
            if (graphs.find(graphIndex) != graphs.end()) {
                graphs[graphIndex].printWeight(fromVertex, toVertex);
            } else {
                booleanGraphs[graphIndex].printWeight(fromVertex, toVertex);
            }
        } else if (query == "ADJOUT") {
            int vertex, graphIndex;
            cin >> vertex >> graphIndex;
            if (graphs.find(graphIndex) != graphs.end()) {
                graphs[graphIndex].printAdjacencyList(vertex);
            } else {
                booleanGraphs[graphIndex].printAdjacencyList(vertex);
            }
        } else if (query == "DEGSEQ") {
            int vertex, graphIndex;
            cin >> vertex >> graphIndex;
            if (graphs.find(graphIndex) != graphs.end()) {
                graphs[graphIndex].printDegreeSequence(vertex);
            } else {
                booleanGraphs[graphIndex].printDegreeSequence(vertex);
            }
        } else if (query == "DFS") {
            int startVertex, graphIndex;
            cin >> startVertex >> graphIndex;
            if (graphs.find(graphIndex) != graphs.end()) {
                graphs[graphIndex].performDFS(startVertex);
                cout << endl;
            } else {
                booleanGraphs[graphIndex].performDFS(startVertex);
                cout << endl;
            }
        } else if (query == "ADD") {
            int firstGraphIndex, secondGraphIndex, resultGraphIndex;
            cin >> firstGraphIndex >> secondGraphIndex >> resultGraphIndex;
            if (graphs.find(firstGraphIndex) != graphs.end()) {
                graphs[resultGraphIndex] = graphs[firstGraphIndex] + graphs[secondGraphIndex];
            } else {
                booleanGraphs[resultGraphIndex] = booleanGraphs[firstGraphIndex] + booleanGraphs[secondGraphIndex];
            }
        } else if (query == "SUB") {
            int firstGraphIndex, secondGraphIndex, resultGraphIndex;
            cin >> firstGraphIndex >> secondGraphIndex >> resultGraphIndex;
            if (graphs.find(firstGraphIndex) != graphs.end()) {
                graphs[resultGraphIndex] = graphs[firstGraphIndex] - graphs[secondGraphIndex];
            } else {
                booleanGraphs[resultGraphIndex] = booleanGraphs[firstGraphIndex] - booleanGraphs[secondGraphIndex];
            }
        } else if (query == "NEG") {
            int graphIndex, resultGraphIndex;
            cin >> graphIndex >> resultGraphIndex;
            if (graphs.find(graphIndex) != graphs.end()) {
                graphs[resultGraphIndex] = -graphs[graphIndex];
            } else {
                booleanGraphs[resultGraphIndex] = -booleanGraphs[graphIndex];
            }
        } else if (query == "NCOMP") {
            int graphIndex;
            cin >> graphIndex;
            if (graphs.find(graphIndex) != graphs.end()) {
                graphs[graphIndex].countComponents();
            } else {
                // Handle counting components for boolean graphs if needed
            }
        }
    }

    return 0;
}

