    void createBook() {
        cout << "\nNEW BOOK ENTRY...\n";
        cout << "\nEnter The book number: ";
        cin >> bookNumber;
        cout << "\n\nEnter The Name of The Book: ";
        cin.ignore();
        cin.getline(bookName, 50);
        cout << "\n\nEnter The Author's Name: ";
        cin.getline(authorName, 20);
        cout << "\n\nBook Created.";
    }

    void showBook() const {
        cout << "\nBook Number: " << bookNumber;
        cout << "\nBook Name: " << bookName;
        cout << "\nAuthor Name: " << authorName;
    }

    void modifyBook() {
        cout << "\nBook Number: " << bookNumber;
        cout << "\nModify Book Name: ";
        cin.ignore();
        cin.getline(bookName, 50);
        cout << "\nModify Author's Name: ";
        cin.getline(authorName, 20);
    }

    const char* getBookNumber() const {
        return bookNumber;
    }

    void report() const {
        cout << bookNumber << setw(30) << bookName << setw(30) << authorName << endl;
    }
};

class Student {
    char admissionNumber[6];
    char studentName[20];
    char issuedBookNumber[6];
    int token;

public:
    void createStudent() {
        cout << "\nNEW STUDENT ENTRY...\n";
        cout << "\nEnter The Admission Number: ";
        cin >> admissionNumber;
        cout << "\n\nEnter The Name of The Student: ";
        cin.ignore();
        cin.getline(studentName, 20);
        token = 0;
        issuedBookNumber[0] = '\0';
        cout << "\n\nStudent Record Created.";
    }

    void showStudent() const {
        cout << "\nAdmission Number: " << admissionNumber;
        cout << "\nStudent Name: " << studentName;
        cout << "\nNumber of Books Issued: " << token;
        if (token == 1) {
            cout << "\nIssued Book Number: " << issuedBookNumber;
        }
    }

    void modifyStudent() {
        cout << "\nAdmission Number: " << admissionNumber;
        cout << "\nModify Student Name: ";
        cin.ignore();
        cin.getline(studentName, 20);
    }

    const char* getAdmissionNumber() const {
        return admissionNumber;
    }

    const char* getIssuedBookNumber() const {
        return issuedBookNumber;
    }

    int getToken() const {
        return token;
    }

    void issueBook() {
        token = 1;
    }

    void returnBook() {
        token = 0;
    }

    void setIssuedBookNumber(const char* bookNumber) {
        strcpy(issuedBookNumber, bookNumber);
    }

    void report() const {
        cout << "\t" << admissionNumber << setw(20) << studentName << setw(10) << token << endl;
    }
};

fstream fileStream, tempFileStream;
