void writeBook() {
    char choice;
    fileStream.open("book.dat", ios::out | ios::app);
    do {
        book.createBook();
        fileStream.write(reinterpret_cast<char*>(&book), sizeof(Book));
        cout << "\n\nDo you want to add more records? (y/n): ";
        cin >> choice;
    } while (choice == 'y' || choice == 'Y');
    fileStream.close();
}

