// Function to issue a book to a student
void issueBook() {
    char studentAdmissionNumber[6], bookNumber[6];
    bool studentFound = false, bookFound = false;
    cout << "\nBOOK ISSUE...\n";
    cout << "\nEnter The Student's Admission Number: ";
    cin >> studentAdmissionNumber;
    fileStream.open("student.dat", ios::in | ios::out);
    fstream bookFileStream;
    bookFileStream.open("book.dat", ios::in | ios::out);
    while (fileStream.read(reinterpret_cast<char*>(&student), sizeof(Student)) && !studentFound) {
        if (strcmp(student.getAdmissionNumber(), studentAdmissionNumber) == 0) {
            studentFound = true;
            if (student.getToken() == 0) {
                cout << "\nEnter the Book Number: ";
                cin >> bookNumber;
                while (bookFileStream.read(reinterpret_cast<char*>(&book), sizeof(Book)) && !bookFound) {
                    if (strcmp(book.getBookNumber(), bookNumber) == 0) {
                        book.showBook();
                        bookFound = true;
                        student.issueBook();
                        student.setIssuedBookNumber(book.getBookNumber());
                        int position = -1 * sizeof(student);
                        fileStream.seekp(position, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&student), sizeof(Student));
                        cout << "\nBook issued successfully.\n";
                        cout << "Please note: Write the current date on the back of the book and submit within 15 days.\n";
                        cout << "A fine of Rs.1 for each day will be charged after the 15-day period.\n";
                    }
                }
                if (!bookFound) {
                    cout << "Book number does not exist.\n";
                }
            } else {
                cout << "You have not returned the last book. A book can be issued only after returning the previous one.\n";
            }
        }
    }
    if (!studentFound) {
        cout << "Student record does not exist.\n";
    }
    cin.get();
    fileStream.close();
    bookFileStream.close();
}

