#include <vector>
#include <utility>
#include <memory>

namespace fp {

    struct Node {
        int distance{};
        bool north, south, east, west;
        std::array<int, 2> parent{};
        std::stack<std::array<int, 2>> children;

        Node() : distance{}, parent{}, children{}, north{}, south{}, east{}, west{} {}
        ~Node() = default;
    };

    class Algorithm {
    public:
        bool pathFound, requiresNewPath;
        bool temporaryGoal{false}, pathBlocked{true};
        int visitedCount = 0;
        fp::Maze mazeData;
        char currentDirection;
        char blockedDirection;
        std::array<int, 2> currentNode;
        std::array<int, 2> parentNode;
        std::stack<std::array<int, 2>> nodeStack;
        std::shared_ptr<fp::LandBasedRobot> robot;
        std::stack<std::array<int, 2>> pathStack;
        std::array<std::array<Node, 16>, 16> nodeGrid;
        std::array<std::array<Node, 16>, 16> masterNodeGrid;
        std::array<std::array<bool, 16>, 16> exploredGrid;
        std::array<std::array<bool, 16>, 16> visitedGrid;
        std::array<int, 2> goal1, goal2, goal3, goal4, endGoal;

    public:
        Algorithm() : pathFound{false}, requiresNewPath{true}, currentDirection{'N'}, 
                      goal1{8, 7}, goal2{8, 8}, goal3{7, 8}, goal4{7, 7}, 
                      endGoal{}, currentNode{}, blockedDirection{}, nodeStack{}, pathStack{}, 
                      parentNode{}, visitedGrid{}, masterNodeGrid{}, exploredGrid{}, robot{nullptr} {}

        ~Algorithm() = default;

        // Checks if a node has been explored
        bool IsExplored(std::array<int, 2> node);

        // Identifies neighboring nodes of the current node
        void FindNeighbours(std::array<int, 2> node, char direction);

        // Backtracks to the start node from the current node
        std::stack<std::array<int, 2>> BackTrack(std::array<int, 2> currentNode, 
                                                   std::array<std::array<Node, 16>, 16> &nodeGrid);

        // Executes the Depth First Search algorithm for maze solving
        void DFSAlgorithm(const std::shared_ptr<fp::LandBasedRobot> &robot);

        // Guides the robot through the backtracked path in the maze
        void Navigate(std::array<int, 2> &current, std::array<int, 2> &next);

        // Clears the node stack
        void ClearStack();

        // Resets local variables to their default values
        void SetDefaults();

        // Checks if a node has been visited
        bool IsVisited(std::array<int, 2> node);
    };
}

