        LandBasedRobot()
            : name_{}, speed_{}, width_{}, length_{}, height_{}, capacity_{}, position_x_{15}, position_y_{0}, facing_direction_{'N'} {}

        // Constructor initializing the robot with a name
        explicit LandBasedRobot(std::string &name)
            : name_{name}, speed_{}, width_{}, length_{}, height_{}, capacity_{}, position_x_{15}, position_y_{0}, facing_direction_{'N'} {}

        // Constructor initializing the robot with a name and position
