                       int x, int y, char direction)
            : name_{name}, speed_{speed}, width_{width}, length_{length}, height_{height}, capacity_{capacity}, position_x_{x},
              position_y_{y}, facing_direction_{direction} {}

        // Destructor
        ~LandBasedRobot() = default;

        // Pure virtual method to get the robot's facing direction
        virtual char GetDirection() = 0;

        // Pure virtual method to move the robot forward
