        // Pure virtual method to pick up an object
        virtual void PickUp(std::string object) = 0;

        // Pure virtual method to release the robot's gripper
        virtual void Release(std::string object) = 0;

        // Setter for the robot's name
        virtual void setName(std::string name);

        // Setter for the robot's speed
