        // Setter for the robot's length
        virtual void setLength(double length);

        // Setter for the robot's height
        virtual void setHeight(double height);

        // Setter for the robot's payload capacity
        virtual void setCapacity(double capacity);

        // Setter for the robot's x-axis position
        virtual void setPositionX(int x);

        // Setter for the robot's y-axis position
        virtual void setPositionY(int y);

        // Setter for the robot's facing direction
        virtual void setFacingDirection(char direction);

        // Getter for the robot's name
        virtual const std::string &getName() const;

        // Getter for the robot's speed
        virtual double getSpeed() const;

        // Getter for the robot's width
        virtual double getWidth() const;

        // Getter for the robot's length
        virtual double getLength() const;

        // Getter for the robot's height
        virtual double getHeight() const;

        // Getter for the robot's payload capacity
        virtual double getCapacity() const;

        // Getter for the robot's x-axis position
        virtual int getPositionX() const;

        // Getter for the robot's y-axis position
        virtual int getPositionY() const;

        // Getter for the robot's facing direction
