namespace fp {

    class Maze {
    public:
        // Maze wall configurations for each direction
        std::array<std::array<bool, 16>, 16> northWalls_;
        std::array<std::array<bool, 16>, 16> southWalls_;
        std::array<std::array<bool, 16>, 16> eastWalls_;
        std::array<std::array<bool, 16>, 16> westWalls_;

        // Default constructor initializes the maze boundaries
        Maze() : northWalls_{}, southWalls_{}, eastWalls_{}, westWalls_{} {
            for (int y = 0; y < 16; ++y) {
                for (int x = 0; x < 16; ++x) {
                    // Set west wall for the first column
                    if (x == 0) {
                        westWalls_[15 - y][x] = true;
                        API::setWall(x, y, 'w');
                    } else {
                        westWalls_[15 - y][x] = false;
                    }
                    // Set east wall for the last column
                    if (x == 15) {
                        eastWalls_[15 - y][x] = true;
                        API::setWall(x, y, 'e');
                    } else {
                        eastWalls_[15 - y][x] = false;
                    }
                    // Set south wall for the first row
                    if (y == 0) {
                        southWalls_[15 - y][x] = true;
                        API::setWall(x, y, 's');
                    } else {
                        southWalls_[15 - y][x] = false;
                    }
                    // Set north wall for the last row
                    if (y == 15) {
                        northWalls_[15 - y][x] = true;
                        API::setWall(x, y, 'n');
                    } else {
                        northWalls_[15 - y][x] = false;
                    }
                }
            }
        }

        // Destructor
        ~Maze() = default;

        // Updates the wall configuration based on the current node and direction
        void ReadMaze(std::array<int, 2> currentNode, char direction);

        // Colors the path on the maze grid
        static void ColorPath(std::array<int, 2> coordinates);

    }; // class Maze
} // namespace fp

#endif // MAZE_SOLVER_ROBOT_MAZE_H

