class Passenger {
protected:
    string sourceStation, destinationStation;
    vector<string> passengerNames;
    int ticketCount, ticketClass, travelTime, age[5], totalBill, availableSeats[3], selectedSeats[50], seatIndex;
    double aadharNumbers[5];
    static int sleeperACSeats, nonSleeperSeats, secondClassSeats, sleeperACAvailable, nonSleeperAvailable, secondClassAvailable;

public:
    Passenger();

    void selectRoute() {
        cout << "\tWELCOME TO RAILWAY RESERVATION SYSTEM";
        cout << "\n1. Erode <-> Chennai\n2. Coimbatore <-> Chennai\n3. Kanyakumari <-> Chennai\nEnter your choice: ";
        cin >> ticketClass;
        cout << "Enter your source station: ";
        cin >> sourceStation;
        cout << "Enter your destination station: ";
        cin >> destinationStation;
    }

    void selectTime() {
        switch (ticketClass) {
            case 1:
                if (sourceStation == "erode" || sourceStation == "ERODE") {
                    cout << "\nSelect your timing\n1. 6.00\n2. 11.00\n3. 18.00\n";
                    cin >> travelTime;
                } else if (sourceStation == "chennai" || sourceStation == "CHENNAI") {
                    cout << "\nSelect your timing\n1. 10.00\n2. 13.00\n3. 22.00\n";
                    cin >> travelTime;
                } else {
                    cout << "\nINVALID STATION";
                }
                break;
            case 2:
                if (sourceStation == "coimbatore" || sourceStation == "COIMBATORE") {
                    cout << "\nSelect your timing\n1. 6.00\n2. 11.00\n3. 18.00\n";
                    cin >> travelTime;
                } else if (sourceStation == "chennai" || sourceStation == "CHENNAI") {
                    cout << "\nSelect your timing\n1. 10.00\n2. 13.00\n3. 22.00\n";
                    cin >> travelTime;
                } else {
                    cout << "\nINVALID STATION";
                }
                break;
            case 3:
                if (sourceStation == "kanyakumari" || sourceStation == "KANYAKUMARI") {
                    cout << "\nSelect your timing\n1. 6.00\n2. 11.00\n3. 18.00\n";
                    cin >> travelTime;
                } else if (sourceStation == "chennai" || sourceStation == "CHENNAI") {
                    cout << "\nSelect your timing\n1. 10.00\n2. 13.00\n3. 22.00\n";
                    cin >> travelTime;
                } else {
                    cout << "\nINVALID STATION";
                }
                break;
        }
    }

    void bookTickets(int sleeperACPrice = 550, int nonSleeperPrice = 420, int secondClassPrice = 360) {
        cout << "1. A/C Sleeper\n2. Non A/C Sleeper\n3. Second Class\nEnter your choice: ";
        cin >> ticketClass;
        cout << "Enter the number of tickets: ";
        cin >> ticketCount;

        switch (ticketClass) {
            case 1:
                if (ticketCount > sleeperACAvailable) {
                    cout << "Not enough A/C Sleeper seats available.\n";
                    break;
                }
                totalBill += sleeperACPrice * ticketCount;
                sleeperACAvailable -= ticketCount;
                selectedSeats[seatIndex++] = sleeperACSeats + 1;
                break;
            case 2:
                if (ticketCount > nonSleeperAvailable) {
                    cout << "Not enough Non A/C Sleeper seats available.\n";
                    break;
                }
                totalBill += nonSleeperPrice * ticketCount;
                nonSleeperAvailable -= ticketCount;
                selectedSeats[seatIndex++] = nonSleeperSeats + 1;
                break;
            case 3:
                if (ticketCount > secondClassAvailable) {
                    cout << "Not enough Second Class seats available.\n";
                    break;
                }
                totalBill += secondClassPrice * ticketCount;
                secondClassAvailable -= ticketCount;
                selectedSeats[seatIndex++] = secondClassSeats + 1;
                break;
        }
    }

    void collectPassengerDetails() {
        for (int i = 1; i <= ticketCount; i++) {
            cout << "Enter details for passenger number " << i << "\nEnter Name: ";
            cin >> passengerNames[i];
            cout << "Enter age: ";
            cin >> age[i];
            cout << "Enter your Aadhar number: ";
            cin >> aadharNumbers[i];
        }
    }

    void displayBookingDetails() {
        cout << "\nNumber of travellers: " << ticketCount;
        for (int i = 1; i <= ticketCount; i++) {
            cout << "\nName: " << passengerNames[i];
            cout << "\nAge: " << age[i];
        }
        cout << "\nClass: " << (ticketClass == 0 ? "A/C Sleeper" : (ticketClass == 1 ? "Non A/C Sleeper" : "Second Class"));
        cout << "\nTime: ";
        switch (travelTime) {
            case 1: cout << "6.00"; break;
            case 2: cout << "11.00"; break;
            case 3: cout << "18.00"; break;
        }
        cout << "\nBill amount: " << totalBill;
        cout << "\nRemaining seats:\nIn A/C Sleeper: " << sleeperACAvailable << "\nIn Non A/C Sleeper: " << nonSleeperAvailable << "\nIn Second Class: " << secondClassAvailable;
    }

    friend void displaySeatPositions(Passenger passenger, int selectedSeats[], int seatIndex);
};

int Passenger::sleeperACSeats = 100;
int Passenger::sleeperACAvailable = 100;
int Passenger::nonSleeperSeats = 100;
int Passenger::nonSleeperAvailable = 100;
int Passenger::secondClassSeats = 100;
int Passenger::secondClassAvailable = 100;

class Goods : virtual protected Passenger {
protected:
    string goodsName;
    int totalCost, itemCount, goodsType;
    static int availableCoaches;

public:
    void collectGoodsDetails() {
        totalCost = 0;
        cout << "Enter the name of the goods: ";
        cin >> goodsName;
        cout << "Choose the types of materials\n1. Raw materials\n2. Food materials\n3. Fossil fuels\nEnter the choice: ";
        cin >> goodsType;
        cout << "\nHow many coaches do you need? ";
        cin >> itemCount;
    }

    void bookGoods(int rawMaterialPrice = 250, int foodMaterialPrice = 150, int fossilFuelPrice = 50) {
        switch (goodsType) {
            case 1:
                if (itemCount > availableCoaches) {
                    cout << "Not enough coaches available for raw materials.\n";
                    break;
                }
                totalCost += itemCount * rawMaterialPrice;
                availableCoaches -= itemCount;
                break;
            case 2:
                if (itemCount > availableCoaches) {
                    cout << "Not enough coaches available for food materials.\n";
                    break;
                }
                totalCost += itemCount * foodMaterialPrice;
                availableCoaches -= itemCount;
                break;
            case 3:
                if (itemCount > availableCoaches) {
                    cout << "Not enough coaches available for fossil fuels.\n";
                    break;
                }
                totalCost += itemCount * fossilFuelPrice;
                availableCoaches -= itemCount;
                break;
        }
    }

    void displayGoodsDetails() {
        cout << "\nName of user: " << goodsName;
        cout << "\nMaterials: " << (goodsType == 1 ? "Raw" : (goodsType == 2 ? "Food" : "Fossil fuels"));
        cout << "\nTotal cost: " << totalCost;
        cout << "\nRemaining coaches: " << availableCoaches;
    }
};

int Goods::availableCoaches = 100;

class Railway : protected Goods {
protected:
    int choice;
    char continueChoice, exitChoice;

public:
    void makeChoice() {
        while (exitChoice != '5') {
            cout << "\nBookings:\n1. Passenger Train\n2. Goods Train\nEnter your choice: ";
            cin >> choice;
            switch (choice) {
                case 1:
                    selectRoute();
                    selectTime();
                    bookTickets();
                    collectPassengerDetails();
                    displayBookingDetails();
                    cout << "\nDo you want to know your seat position (y/n)? ";
                    cin >> continueChoice;
                    if (continueChoice == 'y') {
                        displaySeatPositions(*this, selectedSeats, seatIndex);
                    }
                    break;
                case 2:
                    collectGoodsDetails();
                    bookGoods();
                    displayGoodsDetails();
                    break;
            }
            cout << "\nEnter 5 to exit or press any key to continue: ";
            cin >> exitChoice;
            if (exitChoice == '5') {
                cout << "\nTHANK YOU FOR VISITING";
            }
        }
    }
};

void displaySeatPositions(Passenger passenger, int selectedSeats[], int seatIndex) {
    for (int i = 0; i < seatIndex; ++i) {
        int seatNumber = selectedSeats[i];
        int seatPosition = seatNumber % 4;
        int coachNumber = seatNumber / 2;

        if (coachNumber == 0) {
            if (seatPosition == 0 || seatPosition == 1) {
                cout << seatNumber << " is a window seat\n";
            } else if (seatPosition == 2) {
                cout << seatNumber << " is a middle seat\n";
            } else {
                cout << seatNumber << " is an aisle seat\n";
            }
        } else if (coachNumber == 1) {
            if (seatPosition == 0 || seatPosition == 1) {
                cout << seatNumber << " is a window seat\n";
            } else if (seatPosition == 3) {
                cout << seatNumber << " is a middle seat\n";
            } else {
                cout << seatNumber << " is an aisle seat\n";
            }
        }
    }
}

inline Passenger::Passenger() {
    ticketClass = 0;
    totalBill = 0;
    seatIndex = 0;
}

int main() {
    int index = 0;
    char continueChoice;
    Railway railwayInstances[20];

    cout << "\nPress 0 to exit the whole page or press any key to continue: ";
    cin >> continueChoice;
    while (continueChoice != '0') {
        railwayInstances[index].makeChoice();
        index++;
        cout << "\nPress 0 to exit the whole page or press any key to continue: ";
        cin >> continueChoice;
    }
}

