	private: System::Void CreateButton_Click(System::Object^ sender, System::EventArgs^ e) {
		try
		{
			String^ accountHolderName = accountHolderTextBox->Text;
			String^ accountType = accountTypeComboBox->SelectedItem->ToString();
			String^ amountInString = initialAmountTextBox->Text;
			Decimal^ initialAmount = System::Convert::ToDecimal(amountInString);
			String^ accountNumberInString = accountNumberMaskedTextBox->Text;
			Int32^ accountNumber = System::Convert::ToInt32(accountNumberInString);

			String^ connectionString = L"datasource=localhost; port=3306; username=root; password=root";
			MySqlConnection^ databaseConnection = gcnew MySqlConnection(connectionString);
			databaseConnection->Open();

			MySqlCommand^ insertCommand = gcnew MySqlCommand("INSERT INTO `database`.`account` (`AccountNumber`, `AccountHolderName`, `AccountType`, `Balance`) VALUES(@AccountNumber, @AccountHolderName, @AccountType, @Balance)", databaseConnection);
			insertCommand->Parameters->AddWithValue("@AccountNumber", accountNumber);
			insertCommand->Parameters->AddWithValue("@AccountHolderName", accountHolderName);
			insertCommand->Parameters->AddWithValue("@AccountType", accountType);
			insertCommand->Parameters->AddWithValue("@Balance", initialAmount);
			insertCommand->ExecuteNonQuery();
		}
		catch (Exception^ e)
		{
			MessageBox::Show(e->Message);
		}
	}
