AutoTellerMachine currentAccount;
vector<AutoTellerMachine> accountList; // Stores multiple accounts for user management

void UserMenu();

void AutoTellerMachine::SetAccountLogin(int accountIndex) {
    loggedInAccountIndex = accountIndex;
}

int AutoTellerMachine::GetAccountLogin() const {
    return loggedInAccountIndex;
}

void AutoTellerMachine::CreateNewAccount(const string& username, const string& password) {
    int accountCount = accountList.size();
    accountList.at(accountCount - 1).accountBalance = 0.0;
    accountList.at(accountCount - 1).username = username;
    accountList.at(accountCount - 1).password = password;
}

void AutoTellerMachine::AccountLogin(const string& username, const string& password) {
    int accountCount = accountList.size();
    bool loginSuccessful = false;
    int accountIndex = 0;

    for (int i = 0; i < accountCount; i++) {
        if (username == accountList.at(i).username && password == accountList.at(i).password) {
            loginSuccessful = true;
            accountIndex = i;
            break;
        }
    }

    if (!loginSuccessful) {
        cout << endl << "******** LOGIN FAILED! ********" << endl << endl;
        UserMenu();
    } else {
        SetAccountLogin(accountIndex);
        cout << endl << "Access Granted - " << accountList.at(loggedInAccountIndex).username << endl;
        AccountMenu();
    }
}

void AutoTellerMachine::DepositMoney(double amount) {
    accountList.at(loggedInAccountIndex).accountBalance += amount;
}

void AutoTellerMachine::WithdrawMoney(double amount) {
    accountList.at(loggedInAccountIndex).accountBalance -= amount;
}

double AutoTellerMachine::GetAccountBalance(int accountIndex) const {
    return accountList.at(loggedInAccountIndex).accountBalance;
}

void AutoTellerMachine::SetLastMoneyMovement(int accountIndex, double amount) {
    accountList.at(accountIndex).lastMoneyMovement = amount;
}

void AutoTellerMachine::SetBeginningBalance(int accountIndex) {
    accountList.at(accountIndex).beginningBalance = accountList.at(loggedInAccountIndex).accountBalance;
}

void AutoTellerMachine::SetLastOperation(int accountIndex, char operation) {
    accountList.at(accountIndex).lastOperation = operation;
}

double AutoTellerMachine::GetLastMoneyMovement(int accountIndex) const {
    return accountList.at(accountIndex).lastMoneyMovement;
}

double AutoTellerMachine::GetBeginningBalance(int accountIndex) const {
    return accountList.at(accountIndex).beginningBalance;
}

char AutoTellerMachine::GetLastOperation(int accountIndex) const {
    return accountList.at(accountIndex).lastOperation;
}

string AutoTellerMachine::GetUsername(int accountIndex) const {
    return accountList.at(GetAccountLogin()).username;
}

void UserMenu() {
