void Hospital::pack(const Record& record) {
    fstream fileStream;
    fileStream.open(FILENAME, ios::out | ios::app);

    if (!fileStream) {
        cout << "\nCannot open file";
        exit(0);
    }

    char buffer[45];
    snprintf(buffer, sizeof(buffer), "%s|%s|%s|%s|%s|%s|%s|*", 
             record.id, record.name, record.age, record.sex, 
             record.contact, record.time, record.description);

    fileStream << buffer << endl;
    fileStream.close();
}

Record Hospital::unpack(const char buffer[]) {
    Record record;
    int index = 0, bufferIndex = 0;

    while (buffer[bufferIndex] != '|') record.id[index++] = buffer[bufferIndex++];
    record.id[index] = '\0'; index = 0; bufferIndex++;

    while (buffer[bufferIndex] != '|') record.name[index++] = buffer[bufferIndex++];
    record.name[index] = '\0'; index = 0; bufferIndex++;

    while (buffer[bufferIndex] != '|') record.age[index++] = buffer[bufferIndex++];
    record.age[index] = '\0'; index = 0; bufferIndex++;

    while (buffer[bufferIndex] != '|') record.sex[index++] = buffer[bufferIndex++];
    record.sex[index] = '\0'; index = 0; bufferIndex++;

    while (buffer[bufferIndex] != '|') record.contact[index++] = buffer[bufferIndex++];
    record.contact[index] = '\0'; index = 0; bufferIndex++;

    while (buffer[bufferIndex] != '|') record.time[index++] = buffer[bufferIndex++];
    record.time[index] = '\0'; index = 0; bufferIndex++;

    while (buffer[bufferIndex] != '|') record.description[index++] = buffer[bufferIndex++];
    record.description[index] = '\0';

    return record;
}

