void Hospital::displayRecords() {
    fstream fileStream;
    char buffer[500];
    Record record;

    fileStream.open(FILENAME, ios::in);
    if (!fileStream) {
        cout << "\nCannot open file";
        exit(0);
    }

    cout << "#\tID\tName\tAge\tSex\tContact Number\tTime Slot\tDescription\n";
    int count = 1;

    while (true) {
        fileStream.getline(buffer, 500, '*');
        if (fileStream.eof()) break;

        record = unpack(buffer);
        cout << count << "\t" << record.id << "\t" << record.name << "\t" 
             << record.age << "\t" << record.sex << "\t" << record.contact << "\t" 
             << record.time << "\t" << record.description << endl;
        count++;
    }

    fileStream.close();
}

void Hospital::modifyRecord() {
    fstream fileStream;
    char id[15], buffer[45];
    int recordCount = 0;
    Record records[100];

    fileStream.open(FILENAME, ios::in);
    if (!fileStream) {
        cout << "\nCannot open file";
        exit(0);
    }

    cout << "\nEnter the ID to be modified: ";
    cin >> id;

    while (true) {
        fileStream.getline(buffer, 45, '*');
        if (fileStream.eof()) break;

        records[recordCount++] = unpack(buffer);
    }

    for (int j = 0; j < recordCount; j++) {
        if (strcmp(records[j].id, id) == 0) {
            cout << "\nValues of the record are:\n";
            cout << "\nID: " << records[j].id;
            cout << "\nName: " << records[j].name;        
            cout << "\nAge: " << records[j].age;
            cout << "\nSex (M/F): " << records[j].sex;
            cout << "\nContact: " << records[j].contact;
            cout << "\nTime Slot: " << records[j].time;
            cout << "\nDescription: " << records[j].description;
            cout << "\nEnter the new values:\n";

            cout << "\nID: ";
            cin >> records[j].id;
            cout << "\nName: ";
            cin >> records[j].name;
            cout << "\nAge: ";
            cin >> records[j].age;
            cout << "\nSex (M/F): ";
            cin >> records[j].sex;
            cout << "\nContact: ";
            cin >> records[j].contact;
            cout << "\nTime Slot: ";
            cin >> records[j].time;
            cout << "\nDescription: ";
            cin >> records[j].description;
            break;
        }
    }

    if (recordCount == 0) {
        cout << "\nRecord not found";
        return;
    }

    fileStream.close();
    fstream outputFileStream;
    outputFileStream.open(FILENAME, ios::out | ios::trunc);
    if (!outputFileStream) {
        cout << "\nCannot open file";
        exit(0);
    }

    for (int j = 0; j < recordCount; j++) {
        pack(records[j]);
    }

    outputFileStream.close();
}

void Hospital::searchRecord() {
    fstream fileStream;
    char id[15], buffer[45];
    Record record;

    fileStream.open(FILENAME, ios::in);
    if (!fileStream) {
        cout << "\nCannot open file";
        exit(0);
    }

    cout << "\nEnter the ID to be searched: ";
    cin >> id;

    while (true) {
        fileStream.getline(buffer, 45, '*');
        if (fileStream.eof()) break;

        record = unpack(buffer);
        if (strcmp(record.id, id) == 0) {
            cout << "\nRecord found\n";
            cout << "\nID: " << record.id;
            cout << "\nName: " << record.name;
            cout << "\nAge: " << record.age;
            cout << "\nSex (M/F): " << record.sex;
            cout << "\nContact: " << record.contact;
            cout << "\nDescription: " << record.description;
            return;
        }
    }

    cout << "\nRecord not found";
}

