using json = nlohmann::json;
using namespace std;

class Bank {
private:
    int nextAccountID = 0;
    vector<Account*> * accounts;

    /**
     * Inserts account data from JSON into the bank's account list.
     * @param data The JSON data containing account information.
     */
    void loadAccountsFromJson(const json& data) {
        for (const auto& accountData : data) {
            Account * newAccount = new Account(
                nextAccountID++,
                accountData["fName"],
                accountData["lName"],
                accountData["cBal"],
                accountData["sBal"]
            );

            // Add checking account transactions
            for (const auto& transactionData : accountData["checkingTransactions"]) {
                Transaction * transaction = new Transaction(transactionData["id"], transactionData["amt"]);
                newAccount->getCheckingTransactions()->insert(transaction);
            }

            // Add savings account transactions
            for (const auto& transactionData : accountData["savingsTransactions"]) {
                Transaction * transaction = new Transaction(transactionData["id"], transactionData["amt"]);
                newAccount->getSavingsTransactions()->insert(transaction);
            }

            accounts->push_back(newAccount);
        }

        cout << "Accounts loaded successfully from file." << endl;
    }

    /**
     * Saves the current bank data to a specified JSON file.
     * @param data The JSON data to be saved.
     */
    void saveDataToFile(const json& data) {
        string filePath = "./dataOut.json";

        cout << "Please enter a path to save the data to [./dataOut.json]: ";
        cin >> filePath;

        ofstream outputFile((filePath.length() > 0) ? filePath : "./dataOut.json");
        if (outputFile.is_open()) {
            outputFile << data.dump();
            outputFile.close();
            cout << "Data successfully saved to file: '" << filePath << "'" << endl;
        } else {
            cout << "Failed to open file for writing." << endl;
        }
    }

public:
    /**
     * Constructor initializes the account list.
     */
    Bank() {
        accounts = new vector<Account*>();
    }

    /**
     * Destructor cleans up the account list.
     */
    ~Bank() {
        delete accounts;
    }

    /**
     * Retrieves the list of accounts in the bank.
     * @return A pointer to the vector of accounts.
     */
    vector<Account*> * getAccounts() {
        return accounts;
    }

    /**
     * Retrieves the next available account ID.
     * @return The next account ID.
     */
    int getNextAccountID() {
        return nextAccountID;
    }

    /**
     * Adds a new account to the bank based on user input.
     */
    void addAccount() {
        string firstName, lastName;
        double checkingBalance, savingsBalance;

        cout << "Enter your first name: ";
        cin >> firstName;
        cout << "Enter your last name: ";
        cin >> lastName;
        cout << "Enter starting checking balance: $";
        cin >> checkingBalance;
        cout << "Enter starting savings balance: $";
        cin >> savingsBalance;

        Account * newAccount = new Account(
            nextAccountID++,
            firstName,
            lastName,
            checkingBalance,
            savingsBalance
        );

        accounts->push_back(newAccount);
    }

    /**
     * Deletes an account from the bank by its unique ID.
     * @param accountID The unique ID of the account to delete.
     */
    void deleteAccount(int accountID) {
        Account * targetAccount = searchAccount(accountID);
        if (targetAccount) {
            accounts->erase(accounts->begin() + accountID);
            delete targetAccount;
        }
    }

    /**
     * Searches for an account by its unique ID.
     * @param accountID The unique ID of the account to search for.
     * @return A pointer to the account if found, otherwise nullptr.
     */
    Account * searchAccount(int accountID) {
        if (accountID >= accounts->size()) {
            cout << "Account not found." << endl;
            return nullptr;
        }

        int low = 0;
        int high = accounts->size() - 1;
        int mid;

        // Binary search for the account
        while (low <= high) {
            mid = (low + high) / 2;
            int id = accounts->at(mid)->getId();
            if (id == accountID) {
                return accounts->at(mid);
            } else if (id > accountID) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        cout << "Account not found." << endl;
        return nullptr;
    }

    /**
     * Loads accounts from a specified JSON file path.
     */
    void loadAccounts() {
        string dataString;
        string line;
        string filePath = "./data.json";

        cout << "Enter path to import data file: ";
        cin >> filePath;

        ifstream inputFile((filePath.length() > 0) ? filePath : "./data.json");
        if (inputFile.is_open()) {
            while (getline(inputFile, line)) {
                dataString += line;
            }
            inputFile.close();
        } else {
            cout << "Unable to open file." << endl;
            return;
        }

        json data = json::parse(dataString);
        loadAccountsFromJson(data["accountList"]);
    }

    /**
     * Saves all accounts in the bank to a JSON-formatted file.
     */
    void saveAccounts() {
        json saveData;

        // Collect account information for saving
        for (size_t i = 0; i < accounts->size(); ++i) {
            saveData["accountList"][i] = {
                {"fName", accounts->at(i)->getFName()},
                {"lName", accounts->at(i)->getLName()},
                {"cBal", accounts->at(i)->getCBal()},
                {"sBal", accounts->at(i)->getSBal()}
            };

            // Collect checking transactions
            LinkedTransactionList * checkingTransactions = accounts->at(i)->getCheckingTransactions();
            Transaction * currentTransaction = checkingTransactions->start;
            int j = 0;
            while (currentTransaction) {
                saveData["accountList"][i]["checkingTransactions"][j++] = {
                    {"id", currentTransaction->getID()},
                    {"amt", currentTransaction->getAmount()}
                };
                currentTransaction = currentTransaction->next;
            }

            // Collect savings transactions
            LinkedTransactionList * savingsTransactions = accounts->at(i)->getSavingsTransactions();
            currentTransaction = savingsTransactions->start;
            j = 0;
            while (currentTransaction) {
                saveData["accountList"][i]["savingsTransactions"][j++] = {
                    {"id", currentTransaction->getID()},
                    {"amt", currentTransaction->getAmount()}
                };
                currentTransaction = currentTransaction->next;
            }
        }

        saveDataToFile(saveData);
    }

    void sortAccountsByBalance() {
        // Sorting functionality not implemented
        cout << "Sorting by balance is not implemented." << endl;
    }
};

