#ifndef BENNYSBANK_LINKEDTRANSACTIONLIST_H
#define BENNYSBANK_LINKEDTRANSACTIONLIST_H

#include <string>
#include "Transaction.h"

using namespace std;

/**
 * Class responsible for managing a linked list of transactions.
 */
class LinkedTransactionList {
public:
    Transaction* head; // Pointer to the first transaction in the list.

    LinkedTransactionList() : head(nullptr) {}

    ~LinkedTransactionList() {
        delete head; // Clean up the list upon destruction.
    }

    /**
     * Generates a formatted string representation of all transactions.
     * @return A string displaying all transactions or a message if none exist.
     */
    string displayTransactions() {
        string formattedTransactions;
        Transaction* currentTransaction = head;

        // Construct the display string for each transaction.
        while (currentTransaction) {
            formattedTransactions += "\n---------------------------------------------"
                                    "\nID: " + to_string(currentTransaction->getID()) +
                                    "\nAmount: $ " + to_string(currentTransaction->getAmount()) +
                                    "\nTime: " + to_string(currentTransaction->getTime()) + "ms\n"
                                    + "---------------------------------------------\n";

            currentTransaction = currentTransaction->next;
        }

        // Provide a message if no transactions are available.
        if (formattedTransactions.empty()) {
            formattedTransactions = "NO TRANSACTIONS FOUND...";
        }

        return formattedTransactions;
    }

    /**
     * Adds a new transaction to the end of the transaction list.
     * @param newTransaction The transaction to be added.
     */
    void insert(Transaction* newTransaction) {
        if (head == nullptr) {
            head = newTransaction; // Initialize the list with the new transaction.
            newTransaction->next = nullptr;
        } else {
            Transaction* currentTransaction = head;

            // Traverse to the end of the linked list.
            while (currentTransaction->next != nullptr) {
                currentTransaction = currentTransaction->next;
            }

            currentTransaction->next = newTransaction; // Link the new transaction at the end.
            newTransaction->next = nullptr;
        }
    }
};

#endif //BENNYSBANK_LINKEDTRANSACTIONLIST_H

