void Account::depositFunds(Transaction *transaction)
{
    int fundIndex = (transaction->getSecondAccountID() == -1) ? 
                    (transaction->getAccountID() % 10) : 
                    (transaction->getSecondAccountID() % 10);

    int currentFundAmount = tenFunds[fundIndex].getAmount();
    int depositAmount = transaction->getCash();

    tenFunds[fundIndex].setAmount(currentFundAmount + depositAmount);
    tenFunds[fundIndex].addHistory(transaction);
}

void Account::withdrawFunds(Transaction *transaction)
{
    int fundIndex = transaction->getAccountID() % 10;
    int currentFundAmount = tenFunds[fundIndex].getAmount();
    int withdrawalAmount = transaction->getCash();

    if ((currentFundAmount - withdrawalAmount) >= 0)
    {
        tenFunds[fundIndex].setAmount(currentFundAmount - withdrawalAmount);
    }
    else
    {
        int deficitAmount = currentFundAmount - withdrawalAmount;

        // Attempt to cover withdrawal from adjacent funds
        if ((fundIndex == 0 || fundIndex == 2) && 
            (tenFunds[fundIndex + 1].getAmount() + deficitAmount >= 0))
        {
            tenFunds[fundIndex + 1].setAmount(tenFunds[fundIndex + 1].getAmount() + deficitAmount);
            transaction->setCash(-deficitAmount);
            transaction->setAccountID(transaction->getAccountID() + 1);
            tenFunds[fundIndex + 1].addHistory(transaction);

            transaction->setAccountID(transaction->getAccountID() - 1);
            tenFunds[fundIndex].setAmount(0);
            transaction->setCash(currentFundAmount);
        }
        else if ((fundIndex == 1 || fundIndex == 3) && 
                 (tenFunds[fundIndex - 1].getAmount() + deficitAmount >= 0))
        {
            tenFunds[fundIndex - 1].setAmount(tenFunds[fundIndex - 1].getAmount() + deficitAmount);
            transaction->setCash(-deficitAmount);
            transaction->setAccountID(transaction->getAccountID() - 1);
            tenFunds[fundIndex - 1].addHistory(transaction);

            transaction->setAccountID(transaction->getAccountID() + 1);
            tenFunds[fundIndex].setAmount(0);
            transaction->setCash(currentFundAmount);
        }
        else
        {
            transaction->setSuccess(false);
            cerr << "ERROR: Insufficient funds to withdraw " << withdrawalAmount 
                 << " from " << firstName << " " << lastName << " " 
                 << tenFunds[fundIndex].getName() << ".\n";
        }
    }
    tenFunds[fundIndex].addHistory(transaction);
}

