#include "BSTree.h"
#include <iostream>

using namespace std;

BSTree::BSTree() : root(nullptr) {}

BSTree::BSTree(const BSTree& source) : root(nullptr) {
    copy(source);
}

// Inserts a new account into the binary search tree
bool BSTree::Insert(Account *client) {
    Node *newNode = new Node();
    newNode->pAcct = client;

    if (root == nullptr) {
        root = newNode;
        return true;
    }
    return Insert(root, newNode);
}

// Helper function to insert a node in the correct position
bool BSTree::Insert(Node *currentNode, Node *newNode) {
    if (currentNode->pAcct->getID() > newNode->pAcct->getID()) {
        if (currentNode->left == nullptr) {
            currentNode->left = newNode;
            return true;
        } else if (currentNode->left->pAcct->getID() < newNode->pAcct->getID()) {
            newNode->left = currentNode->left;
            currentNode->left = newNode;
        } else {
            return Insert(currentNode->left, newNode);
        }
    } else if (currentNode->pAcct->getID() < newNode->pAcct->getID()) {
        if (currentNode->right == nullptr) {
            currentNode->right = newNode;
            return true;
        } else if (currentNode->right->pAcct->getID() > newNode->pAcct->getID()) {
            newNode->right = currentNode->right;
            currentNode->right = newNode;
        } else {
            return Insert(currentNode->right, newNode);
        }
    }
    return false;
}

// Retrieves an account by its ID
bool BSTree::Retrieve(const int &iD, Account * &client) const {
    if (this == nullptr) {
        client = nullptr;
        return false;
    }
    return Retrieve(root, iD, client);
}

// Helper function to find an account in the tree
bool BSTree::Retrieve(const Node *currentNode, const int &iD, Account * &client) const {
    if (currentNode == nullptr) {
        client = nullptr;
        return false;
    } else if (currentNode->pAcct->getID() == iD) {
        client = currentNode->pAcct;
        return true;
    } else if (currentNode->pAcct->getID() < iD) {
        return Retrieve(currentNode->right, iD, client);
    } else {
        return Retrieve(currentNode->left, iD, client);
    }
}

// Checks if the tree is empty
bool BSTree::isEmpty() const {
    return root == nullptr;
}

// Clears the entire tree
void BSTree::Empty() {
    if (root != nullptr) {
        Empty(root);
        root = nullptr;
    }
}

// Recursive function to delete nodes in the tree
void BSTree::Empty(Node *currentNode) {
    if (currentNode == nullptr) {
        return;
    }
    Empty(currentNode->left);
    Empty(currentNode->right);
    delete currentNode->pAcct;
    delete currentNode;
}

// Displays the accounts in the tree in-order
void BSTree::Display() const {
    if (root != nullptr) {
        Display(root);
    }
}

// Helper function to display nodes in-order
void BSTree::Display(Node *currentNode) const {
    if (currentNode == nullptr) {
        return;
    }
    Display(currentNode->left);
    cout << *currentNode->pAcct << "\n";
    Display(currentNode->right);
}

// Assignment operator overload
BSTree& BSTree::operator=(const BSTree &source) {
    if (this != &source) {
        clear();
        copy(source);
    }
    return *this;
}

// Clears the tree and resets the root
void BSTree::clear() {
    delete root;
    root = nullptr;
}

// Copies the contents of another tree
void BSTree::copy(const BSTree & source) {
    root = new Node();
    *root = *source.root;
}

// Destructor to clear the tree
BSTree::~BSTree() {
    clear();
}

