class BinarySearchTree
{
public:
    BinarySearchTree();
    BinarySearchTree(const BinarySearchTree &);
    ~BinarySearchTree();

    bool Insert(Account *);
    // Retrieve an Account object by its ID. 
    // The second parameter will point to the found object, or NULL if not found.
    bool Retrieve(const int &, Account * &) const;

    // Display the contents of the tree to standard output.
    void Display() const;
