#include <iostream>

using namespace std;

class ComplexNumber
{
    float realPart, imaginaryPart;

public:
    // Constructor khởi tạo mặc định
    ComplexNumber() : realPart(0), imaginaryPart(0) {}

    // Constructor khởi tạo với giá trị cụ thể
    ComplexNumber(float real, float imaginary)
    {
        realPart = real;
        imaginaryPart = imaginary;
    }

    // Hiển thị số phức dưới dạng a + bi
    void display()
    {
        cout << realPart << " + i" << imaginaryPart << endl;
    }

    // Định nghĩa toán tử cộng cho số phức
    friend ComplexNumber operator +(const ComplexNumber &lhs, const ComplexNumber &rhs);

    // Định nghĩa toán tử trừ cho số phức
    friend ComplexNumber operator -(const ComplexNumber &lhs, const ComplexNumber &rhs);

    // Định nghĩa toán tử nhân cho số phức
    friend ComplexNumber operator *(const ComplexNumber &lhs, const ComplexNumber &rhs);

    // Định nghĩa toán tử chia cho số phức
    friend ComplexNumber operator /(const ComplexNumber &lhs, const ComplexNumber &rhs);
};

// Thực hiện phép cộng hai số phức
ComplexNumber operator +(const ComplexNumber &lhs, const ComplexNumber &rhs)
{
    ComplexNumber result;
    result.realPart = lhs.realPart + rhs.realPart;
    result.imaginaryPart = lhs.imaginaryPart + rhs.imaginaryPart;

    return result;
}

// Thực hiện phép trừ hai số phức
ComplexNumber operator -(const ComplexNumber &lhs, const ComplexNumber &rhs)
{
    ComplexNumber result;
    result.realPart = lhs.realPart - rhs.realPart;
    result.imaginaryPart = lhs.imaginaryPart - rhs.imaginaryPart;

    return result;
}

// Thực hiện phép nhân hai số phức
ComplexNumber operator *(const ComplexNumber &lhs, const ComplexNumber &rhs)
{
    ComplexNumber result;
    float realProduct = lhs.realPart * rhs.realPart;
    float imaginaryProduct = -(lhs.imaginaryPart * rhs.imaginaryPart);
    float crossProduct1 = lhs.realPart * rhs.imaginaryPart;
    float crossProduct2 = lhs.imaginaryPart * rhs.realPart;

    result.realPart = realProduct + imaginaryProduct;
    result.imaginaryPart = crossProduct1 + crossProduct2;

    return result;
}

// Thực hiện phép chia hai số phức
ComplexNumber operator /(const ComplexNumber &lhs, const ComplexNumber &rhs)
{
    ComplexNumber result, conjugate, numerator, denominator;

    conjugate = rhs;
    conjugate.imaginaryPart = -(conjugate.imaginaryPart);
    numerator = lhs * conjugate;
    denominator = rhs * conjugate;

    result.realPart = numerator.realPart / denominator.realPart;
    result.imaginaryPart = numerator.imaginaryPart / denominator.realPart;

    return result;
}

int main()
{
    float real1, imaginary1, real2, imaginary2;
    ComplexNumber result;

    // Nhập các thành phần của hai số phức
    cin >> real1 >> imaginary1 >> real2 >> imaginary2;
    ComplexNumber firstComplex(real1, imaginary1), secondComplex(real2, imaginary2);

    // Thực hiện và hiển thị kết quả của các phép toán
    result = firstComplex + secondComplex;
    result.display();
    result = firstComplex - secondComplex;
    result.display();
    result = firstComplex * secondComplex;
    result.display();
    result = firstComplex / secondComplex;
    result.display();

    return 0;
}

#include <iostream>

using namespace std;

// Class representing complex numbers and supporting basic arithmetic operations.
class ComplexNumber
{
    float realPart, imaginaryPart;

public:
    ComplexNumber() : realPart(0), imaginaryPart(0) {}

    ComplexNumber(float real, float imaginary)
    {
        realPart = real;
        imaginaryPart = imaginary;
    }

    // Displays the complex number in the format a + ib.
    void display() const
    {
        cout << realPart << " + i" << imaginaryPart << endl;
    }

    friend ComplexNumber add(const ComplexNumber &first, const ComplexNumber &second);
    friend ComplexNumber subtract(const ComplexNumber &first, const ComplexNumber &second);
    friend ComplexNumber multiply(const ComplexNumber &first, const ComplexNumber &second);
    friend ComplexNumber divide(const ComplexNumber &first, const ComplexNumber &second);
};

// Adds two complex numbers.
ComplexNumber add(const ComplexNumber &first, const ComplexNumber &second)
{
    ComplexNumber result;
    result.realPart = first.realPart + second.realPart;
    result.imaginaryPart = first.imaginaryPart + second.imaginaryPart;

    return result;
}

// Subtracts the second complex number from the first.
ComplexNumber subtract(const ComplexNumber &first, const ComplexNumber &second)
{
    ComplexNumber result;
    result.realPart = first.realPart - second.realPart;
    result.imaginaryPart = first.imaginaryPart - second.imaginaryPart;

    return result;
}

// Multiplies two complex numbers.
ComplexNumber multiply(const ComplexNumber &first, const ComplexNumber &second)
{
    ComplexNumber result;
    float realProduct = first.realPart * second.realPart;
    float imaginaryProduct = -(first.imaginaryPart * second.imaginaryPart);
    float crossProduct1 = first.realPart * second.imaginaryPart;
    float crossProduct2 = first.imaginaryPart * second.realPart;

    result.realPart = realProduct + imaginaryProduct;
    result.imaginaryPart = crossProduct1 + crossProduct2;

    return result;
}

// Divides the first complex number by the second.
ComplexNumber divide(const ComplexNumber &first, const ComplexNumber &second)
{
    ComplexNumber conjugate = second;
    conjugate.imaginaryPart = -conjugate.imaginaryPart;

    ComplexNumber numerator = multiply(first, conjugate);
    ComplexNumber denominator = multiply(second, conjugate);

    ComplexNumber result;
    result.realPart = numerator.realPart / denominator.realPart;
    result.imaginaryPart = numerator.imaginaryPart / denominator.realPart;

    return result;
}

int main()
{
    float a, b, c, d;
    ComplexNumber result;

    cin >> a >> b >> c >> d;
    ComplexNumber firstNumber(a, b), secondNumber(c, d);

    result = add(firstNumber, secondNumber);
    result.display();
    result = subtract(firstNumber, secondNumber);
    result.display();
    result = multiply(firstNumber, secondNumber);
    result.display();
    result = divide(firstNumber, secondNumber);
    result.display();

    return 0;
}

