        taskId = pvm_mytid();
        if (taskId < 0) {
            fprintf(logFile, "Error occurred: taskId=%d\n", taskId);
            fclose(logFile);
            pvm_exit();
        }
        // Retrieve the parent task ID
        parentTaskId = pvm_parent();
        if ((parentTaskId < 0) && (parentTaskId == PvmNoParent)) {
            fprintf(logFile, "Error occurred: parentTaskId=%d\n", parentTaskId);
            fclose(logFile);
            pvm_exit();
        }
        // Set the initial balance
        currentBalance = initialAmount;
        // Notify the parent task that the account has been initialized
        NotifyParent(BA_INIT_CB);
    }

    void WithdrawMoney(int amount) {
        // Validate withdrawal amount
        if (currentBalance - amount > 0) {
            currentBalance -= amount;
        } else {
            operationStatus = 1; // Indicate failure
        }
        // Notify parent task of the operation result
        NotifyParent(BA_OPERATION_CB);
    }

    void AddMoney(int amount) {
        currentBalance += amount;
        // Notify parent task of the operation result
        NotifyParent(BA_OPERATION_CB);
    }

    void GetAmount() {
        // Notify parent task of the current balance
        NotifyParent(BA_OPERATION_CB);
    }

};


int main() {

    int operationId, amount;
    bool shouldExit = false;

    logFile = fopen("bout", "w");
    fprintf(logFile, "Bank Account Log File\n\n");

    // Wait for initialization message from head office
    pvm_recv(-1, BA_INIT);
    pvm_upkint(&amount, 1, 1);
    // Instantiate and initialize a bank account with the received amount
    BankAccount account(amount);

    while (!shouldExit) {
        pvm_recv(-1, BA_OPERATION);
        pvm_upkint(&operationId, 1, 1);

        // Redirect to the appropriate bank account operation based on the received operation ID
        switch (operationId) {
            case ADDMONEY:
                pvm_upkint(&amount, 1, 1);
                account.AddMoney(amount);
                break;
            case WITHDRAWMONEY:
                pvm_upkint(&amount, 1, 1);
                account.WithdrawMoney(amount);
                break;
            case GETAMOUNT:
                account.GetAmount();
                break;
            case EXITB:
                shouldExit = true;
                break;
            // Exit if an invalid operation ID is received
            default:
                shouldExit = true;
                break;
        }
    }

    pvm_exit();
    return 0;
}

#include "pvminc.h"
#include "IOperation.h"
#include "IMessage.h"
#include "config.h"

int nstid[0];

class Client {

private:
    int myTaskId, headOperation;
    int nstid[0], bankTaskIds[10], accountTaskIds[3][10];

    // Request and receive a bank task ID from the nameserver
    int RequestHeadOffice(int nstid[0]) {
        int bankTaskId;
        headOperation = INIT;

        // Send request to nameserver for head office servers
        pvm_initsend(PvmDataDefault);
        pvm_pkint(&headOperation, 1, 1);
        pvm_send(nstid[0], NS_OPERATION);

        // Receive head office task ID
        pvm_recv(-1, NS_OPERATION_CB);
        pvm_upkint(&bankTaskId, 1, 1);

        return bankTaskId;
    }

    // Request and receive a bank account task ID from a head office server
    int RequestBankAccount(int bankTaskId, int initialAmount) {
        int accountTaskId;
        // Request head office for bank accounts
        pvm_initsend(PvmDataDefault);
        pvm_pkint(&headOperation, 1, 1);
        pvm_pkint(&initialAmount, 1, 1);
        pvm_send(bankTaskId, HO_OPERATION);

        // Receive bank account task ID
        pvm_recv(-1, HO_OPERATION_CB);
        pvm_upkint(&accountTaskId, 1, 1);
        pvm_upkint(&initialAmount, 1, 1);

        return accountTaskId;
    }

    // Prompt the user to select a bank account and call SelectOperation(bankInfo, bankAccountInfo)
    void SelectBankAccountInfo(int bankInfo) {
        int selectedAccountInfo;

        printf("BANK ACCOUNT\n\t");
        printf("0- account:%d\n\t", accountTaskIds[bankInfo][0]);
        printf("1- account:%d\n\t", accountTaskIds[bankInfo][1]);
        printf("2- return to bank listing\n");

        scanf("%d", &selectedAccountInfo);

        if (selectedAccountInfo == 2) {
            SelectBank();
        } else if (selectedAccountInfo == 0 || selectedAccountInfo == 1) {
            SelectOperation(bankInfo, selectedAccountInfo);
        }
    }

    // Prompt the user to select an operation and redirect to the appropriate method
    int SelectOperation(int bankInfo, int selectedAccountInfo) {
        int actionChoice, amount, operationSuccess;

        // Display available operations
        printf("OPERATION\n\t");
        for (int i = 0; i != GETAMOUNT; i++) {
            printf("%d %s\n\t", i + 1, operations[i]);
        }
        printf("4 TRANSFER\n\t");
        printf("5 EXIT\n\t");
        printf("6 return to bank account listing\n");
        scanf("%d", &actionChoice);

        headOperation = BANKACCOUNTOP;
        if (actionChoice == 1 || actionChoice == 2) {
            printf("What is the amount?\n");
            scanf("%d", &amount);

            PrepareSendOperation(bankInfo, selectedAccountInfo, actionChoice, amount);
            pvm_send(bankTaskIds[bankInfo], HO_OPERATION);

            amount = ReceiveOperation(bankInfo, selectedAccountInfo);
            pvm_upkint(&operationSuccess, 1, 1);
            if (operationSuccess == 0)
                printf("\tamount:%d\n", amount);
            else
                printf("\terror - not enough money on the account - amount:%d\n", amount);

        } else if (actionChoice == 3) {
            PrepareSendOperation(bankInfo, selectedAccountInfo, actionChoice);
            pvm_send(bankTaskIds[bankInfo], HO_OPERATION);

            amount = ReceiveOperation(bankInfo, selectedAccountInfo);
            printf("\tamount: %d\n", amount);
        } else if (actionChoice == 5) {
            Exit();
        } else if (actionChoice == 6) {
            SelectBankAccountInfo(bankInfo);
        } else if (actionChoice == 4) {
            ExecuteBankTransfer(bankInfo, selectedAccountInfo);
        }

        SelectOperation(bankInfo, selectedAccountInfo);
    }

    // Perform a transfer from the current bank account to another specified account
    void ExecuteBankTransfer(int bankInfo, int selectedAccountInfo) {
        int targetBank, targetAccount, transferAmount, fromAccountBalance, toAccountBalance, transferSuccess;
        printf("Insert target bank ID, target account ID, and amount\n");
        scanf("%d %d %d", &targetBank, &targetAccount, &transferAmount);

        // Attempt to withdraw money from the current bank account
        PrepareSendOperation(bankInfo, selectedAccountInfo, WITHDRAWMONEY, transferAmount);
        pvm_send(bankTaskIds[bankInfo], HO_OPERATION);
        fromAccountBalance = ReceiveOperation(bankInfo, selectedAccountInfo);
        pvm_upkint(&transferSuccess, 1, 1);

        // If withdrawal is successful, deposit the money into the target account
        if (transferSuccess == 0) {
            PrepareSendOperation(targetBank, targetAccount, ADDMONEY, transferAmount);
            pvm_send(bankTaskIds[targetBank], HO_OPERATION);
            toAccountBalance = ReceiveOperation(targetBank, targetAccount);
            printf("\tsuccess - %d were transferred from bank %d account %d to bank %d account %d\n", transferAmount, bankInfo, selectedAccountInfo, targetBank, targetAccount);
        } else {
            printf("\terror - not enough money on the account - amount:%d\n", fromAccountBalance);
        }
    }

    // Prepare data for sending an operation to the head office
    void PrepareSendOperation(int bankInfo, int selectedAccountInfo, int actionChoice) {
        pvm_initsend(PvmDataDefault);
        pvm_pkint(&headOperation, 1, 1);
        pvm_pkint(&accountTaskIds[bankInfo][selectedAccountInfo], 1, 1);
        pvm_pkint(&actionChoice, 1, 1);
    }

    // Overloaded method to include amount information for sending an operation
    void PrepareSendOperation(int bankInfo, int selectedAccountInfo, int actionChoice, int amount) {
        PrepareSendOperation(bankInfo, selectedAccountInfo, actionChoice);
        pvm_pkint(&amount, 1, 1);
    }

    // Wait to receive a callback operation from the head office
    int ReceiveOperation(int bankInfo, int selectedAccountInfo) {
        int amount;
        pvm_recv(-1, HO_OPERATION_CB);
        pvm_upkint(&accountTaskIds[bankInfo][selectedAccountInfo], 1, 1);
        pvm_upkint(&amount, 1, 1);
        return amount;
    }

    // Exit the client and notify all associated processes
    void Exit() {
        // Notify all bank accounts to exit
        SendExit(EXITB, BA_OPERATION, accountTaskIds[0][0]);
        SendExit(EXITB, BA_OPERATION, accountTaskIds[0][1]);
        SendExit(EXITB, BA_OPERATION, accountTaskIds[1][0]);
        SendExit(EXITB, BA_OPERATION, accountTaskIds[1][1]);

        // Notify both banks to exit
        SendExit(EXITH, HO_OPERATION, bankTaskIds[0]);
        SendExit(EXITH, HO_OPERATION, bankTaskIds[1]);

        // Notify the nameserver to exit
        SendExit(EXITNS, NS_OPERATION, nstid[0]);

        // Exit the client
        pvm_exit();
    }

    // Send an exit operation to the specified process
    void SendExit(int operation, int msgTag, int processId) {
        pvm_initsend(PvmDataDefault);
        pvm_pkint(&operation, 1, 1);
        pvm_send(processId, msgTag);
    }

public:
    // Initialize a PVM session and return the task ID
    Client() {
        myTaskId = pvm_mytid();
        if (myTaskId < 0) {
            printf("An error occurred - client initialization\n");
        }
        printf("*info* myTaskId=%d\n", myTaskId);        
    }

    // Create two head offices and two bank accounts with initial amounts for each head office
    void BootStrapper(int nstid[0]) {
        // Create two head offices with the given nameserver task ID
        bankTaskIds[0] = RequestHeadOffice(nstid);
        bankTaskIds[1] = RequestHeadOffice(nstid);

        // Create two bank accounts with random amounts for these head offices
        accountTaskIds[0][0] = RequestBankAccount(bankTaskIds[0], 211);
        accountTaskIds[0][1] = RequestBankAccount(bankTaskIds[0], 157);
        accountTaskIds[1][0] = RequestBankAccount(bankTaskIds[1], 184);
        accountTaskIds[1][1] = RequestBankAccount(bankTaskIds[1], 126);

        printf("*info* Bootstrapping completed - 2 head offices and 4 bank accounts created\n");
    }

    // Prompt the user to select a bank and call SelectBankAccountInfo(bankInfo)
    void SelectBank() {
        int bankInfo;

        printf("BANK:\n\t");
        printf("0- bank:%d\n\t", bankTaskIds[0]);
        printf("1- bank:%d\n", bankTaskIds[1]);

        scanf("%d", &bankInfo);

        SelectBankAccountInfo(bankInfo);
    }
};

int main() {
    // Create a client instance
    Client client;

    // Spawn the nameserver and retrieve its task ID
    pvm_spawn(nameServerExe, (char**) 0, PvmTaskHost, nameServer, 1, nstid);

    client.BootStrapper(nstid);

    // Start user interaction - first step, select a bank
    client.SelectBank();

    return 0;
}

#include "pvminc.h"
