// Log file for head office operations
FILE *logFile;

class HeadOffice {

private:
    int headOfficeTaskId, parentTaskId, clientTaskId, accountTaskIds[10];

public:
    HeadOffice(int clientId) {
        // Initialize PVM session and set the head office task ID
        headOfficeTaskId = pvm_mytid();
        if (headOfficeTaskId < 0) {
            fprintf(logFile, "Error occurred - initializing head office - taskId=%d\n", headOfficeTaskId);
            fclose(logFile);
            pvm_exit();
        }

        // Retrieve and set the parent task ID
        parentTaskId = pvm_parent();
        if ((parentTaskId < 0) && (parentTaskId == PvmNoParent)) {
            fprintf(logFile, "Error occurred - retrieving head office parent task ID - parentId=%d\n", parentTaskId);
            fclose(logFile);
            pvm_exit();
        }

        // Set the client task ID
        clientTaskId = clientId;
    }

    void InitBankAccount(char* processName, char* serverName, int initialAmount) {
        pvm_spawn(processName, (char**) 0, PvmTaskHost, serverName, 1, accountTaskIds);

        // Send the initial amount to the bank account
        pvm_initsend(PvmDataDefault);
        pvm_pkint(&initialAmount, 1, 1);
        pvm_send(accountTaskIds[0], BA_INIT);

        // Receive the confirmed amount from the bank account
        pvm_recv(-1, BA_INIT_CB);
        pvm_upkint(&initialAmount, 1, 1);

        // Send back account task IDs and amount to the client
        pvm_initsend(PvmDataDefault);
        pvm_pkint(&accountTaskIds[0], 1, 1);
        pvm_pkint(&initialAmount, 1, 1);
        pvm_send(clientTaskId, HO_OPERATION_CB);
    }

    void ProcessOperation() {
        int taskIds[10], operationId, amount, success;

        // Unpack task IDs and operation details from the client
        pvm_upkint(&taskIds[0], 1, 1);
        pvm_upkint(&operationId, 1, 1);
        pvm_upkint(&amount, 1, 1);

        // Send the operation to the bank account
        pvm_initsend(PvmDataDefault);
        pvm_pkint(&operationId, 1, 1);
        pvm_pkint(&amount, 1, 1);
        pvm_send(taskIds[0], BA_OPERATION);

        // Receive the result from the bank account
        pvm_recv(-1, BA_OPERATION_CB);
        pvm_upkint(&amount, 1, 1);
        pvm_upkint(&success, 1, 1);

        // Send back the result to the client
        pvm_initsend(PvmDataDefault);
        pvm_pkint(&taskIds[0], 1, 1);
        pvm_pkint(&amount, 1, 1);
        pvm_pkint(&success, 1, 1);
        pvm_send(clientTaskId, HO_OPERATION_CB);
    }
};

int main() {
    int operationId, amount, clientId;
    bool shouldExit = false;

    logFile = fopen("hout", "w");
    fprintf(logFile, "Head Office Log File\n\n");

    // Wait for a nameserver initialization message
    pvm_recv(-1, HO_INIT);
    pvm_upkint(&clientId, 1, 1);

    // Instantiate and initialize the head office with the client ID received from the nameserver
    HeadOffice office(clientId);

    while (!shouldExit) {
        pvm_recv(-1, HO_OPERATION);
        pvm_upkint(&operationId, 1, 1);

        // Redirect to the appropriate head office operations based on the operation ID
        switch (operationId) {
            case INIT:
                // Spawn a bank account process
                pvm_upkint(&amount, 1, 1);
                office.InitBankAccount(bankaccountExe, bankaccountServer, amount);
                break;
            case BANKACCOUNTOP:
                // Process a bank account operation
                office.ProcessOperation();
                break;
            case EXITH:
                shouldExit = true;
                break;
            // If the operation ID is invalid, exit the loop
            default:
                shouldExit = true;
                break;
        }
    }
    pvm_exit();
    return 0;
}

#include "pvminc.h"
