// Log file for the nameserver
FILE *logFile; 

class NameServer {
private:
    int myTaskId, parentTaskId, bankTaskIds[10];
public:
    // Initialize a PVM session and set the nameserver task ID
    NameServer() {
        myTaskId = pvm_mytid();
        if (myTaskId < 0) {
            fprintf(logFile, "Error occurred - initializing nameserver - mytid=%d\n", myTaskId);
            fclose(logFile);
            pvm_exit();
        }

        // Retrieve the parent task ID
        parentTaskId = pvm_parent();
        if ((parentTaskId < 0) && (parentTaskId == PvmNoParent)) {
            fprintf(logFile, "Error occurred - retrieving nameserver parent task ID - parenttid=%d\n", parentTaskId);
            fclose(logFile);
            pvm_exit();
        }
    }

    void InitializeHeadOffice(char* processName, char* serverName) {
        // Spawn a head office process
        pvm_spawn(processName, (char**) 0, PvmTaskHost, serverName, 1, bankTaskIds);

        // Send the client ID to the head office
        pvm_initsend(PvmDataDefault);
        pvm_pkint(&parentTaskId, 1, 1);
        pvm_send(bankTaskIds[0], HO_INIT);

        // Send back the head office task ID to the client
        pvm_initsend(PvmDataDefault);
        pvm_pkint(&bankTaskIds[0], 1, 1);
        pvm_send(parentTaskId, NS_OPERATION_CB);
    }
};

int main() {
    int operationId;
    bool shouldExit = false;
    logFile = fopen("nout", "w");
    fprintf(logFile, "Nameserver log file\n\n");

    // Instantiate and initialize a nameserver
    NameServer nameServer;

    // Infinite loop to handle operations
    while (!shouldExit) {
        pvm_recv(-1, NS_OPERATION);
        pvm_upkint(&operationId, 1, 1);

        // Route the operation ID to the appropriate method
        switch (operationId) {
            case INIT:
                nameServer.InitializeHeadOffice(headofficeExe, headofficeServer);
                break;
            case EXITNS:
                shouldExit = true;
                break;
            // If the received integer is not valid, exit the loop
            default:
                shouldExit = true;
                break;
        }
    }
    pvm_exit();
    return 0;
}

