// Function to write the account data to .dat file
void createAccountInFile() {
    Account newAccount;
    ofstream file;
    file.open("info.dat", ios::binary | ios::app);
    newAccount.createAccount();
    file.write(reinterpret_cast<char*>(&newAccount), sizeof(Account));
    file.close();
}

void displaySingleAccount(int accountNumber) { // Function to retrieve a record from file
    Account account;
    bool found = false;
    ifstream file;
    file.open("info.dat", ios::binary);
    if (!file) {
        cout << "File could not be opened! Press any key to exit...";
        return;
    }
    cout << "\nBALANCE DETAILS\n";

    while (file.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            found = true;
        }
    }
    file.close();
    if (!found) {
        cout << "\n\nAccount number does not exist.";
    }
}

// Function to modify record of an account stored in file
void updateAccountInFile(int accountNumber) {
    bool found = false;
    Account account;
    fstream file;
    file.open("info.dat", ios::binary | ios::in | ios::out);
    if (!file) {
        cout << "File could not be opened! Press any key...";
        return;
    }
    while (!file.eof() && !found) {
        file.read(reinterpret_cast<char*>(&account), sizeof(Account));
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            cout << "\n\nEnter The New Details of account:" << endl;
            account.updateAccount();
            int position = (-1) * static_cast<int>(sizeof(Account));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            cout << "\n\n\t Record Updated.";
            found = true;
        }
    }
    file.close();
    if (!found) {
        cout << "\n\n Record Not Found.";
    }
}

// Function to delete a record from file
void deleteAccount(int accountNumber) {
    Account account;
    ifstream inputFile;
    ofstream outputFile;
    inputFile.open("info.dat", ios::binary);
    if (!inputFile) {
        cout << "File could not be opened! Press any key...";
        return;
    }
    outputFile.open("Temp.dat", ios::binary);
    inputFile.seekg(0, ios::beg);
    while (inputFile.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() != accountNumber) {
            outputFile.write(reinterpret_cast<char*>(&account), sizeof(Account));
        }
    }
    inputFile.close();
    outputFile.close();
    remove("info.dat");
    rename("Temp.dat", "info.dat");
    cout << "\n\n\tRecord Deleted.";
}

