#include <iostream>
using namespace std;

struct Vector3D {
    float x;
    float y;
    float z;
};

// Initializes a 3D vector with given coordinates
Vector3D createVector(float x, float y, float z) {
    Vector3D vector;
    vector.x = x;
    vector.y = y;
    vector.z = z;
    return vector;
}

// Overloads the + operator to add two 3D vectors
Vector3D operator+(const Vector3D& A, const Vector3D& B) {
    return createVector(A.x + B.x, A.y + B.y, A.z + B.z);
}

// Overloads the - operator to subtract two 3D vectors
Vector3D operator-(const Vector3D& A, const Vector3D& B) {
    return createVector(A.x - B.x, A.y - B.y, A.z - B.z);
}

// Overloads the * operator to multiply two 3D vectors component-wise
Vector3D operator*(const Vector3D& A, const Vector3D& B) {
    return createVector(A.x * B.x, A.y * B.y, A.z * B.z);
}

// Overloads the / operator to divide two 3D vectors component-wise
Vector3D operator/(const Vector3D& A, const Vector3D& B) {
    return createVector(A.x / B.x, A.y / B.y, A.z / B.z);
}

// Prompts the user to input the coordinates of a 3D vector
Vector3D inputVector(char vectorName) {
    float x, y, z;
    cout << "Please enter vector " << vectorName << ":\n";
    cout << "Enter x-coordinate " << vectorName << ".x = ";
    cin >> x;
    cout << "Enter y-coordinate " << vectorName << ".y = ";
    cin >> y;
    cout << "Enter z-coordinate " << vectorName << ".z = ";
    cin >> z;
    return createVector(x, y, z);
}

// Displays the components of a 3D vector
void displayVector3D(const Vector3D& vector, char vectorName) {
    cout << "Displaying 3D Vector " << vectorName << ":\n";
    cout << vectorName << " ( " << vector.x << ", " << vector.y << ", " << vector.z << " )\n";
}

// Displays the menu of operations available for 3D vectors
void displayMenu() {
    cout << " ---------------------------------\n";
    cout << "\t1. Add 3D Vectors\n";
    cout << "\t2. Subtract 3D Vectors\n";
    cout << "\t3. Multiply 3D Vectors\n";
    cout << "\t4. Divide 3D Vectors\n";
    cout << " ---------------------------------\n";
}

int main() {
    while (true) {
        Vector3D vectorA, vectorB, resultVector;
        char vectorNameA = 'A', vectorNameB = 'B', resultVectorName = 'C';

        vectorA = inputVector(vectorNameA);
        displayVector3D(vectorA, vectorNameA);

        vectorB = inputVector(vectorNameB);
        displayVector3D(vectorB, vectorNameB);

        displayMenu();
        int operationChoice;
        cout << "Please choose an operation:\n";
        cin >> operationChoice;

        switch (operationChoice) {
            case 1:
                resultVector = vectorA + vectorB;
                cout << "Result of " << vectorNameA << " + " << vectorNameB << ":\n";
                displayVector3D(resultVector, resultVectorName);
                break;
            case 2:
                resultVector = vectorA - vectorB;
                cout << "Result of " << vectorNameA << " - " << vectorNameB << ":\n";
                displayVector3D(resultVector, resultVectorName);
                break;
            case 3:
                resultVector = vectorA * vectorB;
                cout << "Result of " << vectorNameA << " * " << vectorNameB << ":\n";
                displayVector3D(resultVector, resultVectorName);
                break;
            case 4:
                resultVector = vectorA / vectorB;
                cout << "Result of " << vectorNameA << " / " << vectorNameB << ":\n";
                displayVector3D(resultVector, resultVectorName);
                break;
        }

        cout << "Do you want to exit the program (y/n)? ";
        char exitChoice;
        cin >> exitChoice;
        if (exitChoice == 'y' || exitChoice == 'Y') {
            break;
        }
    }
    system("pause");
    return 0;
}

