namespace CT {

    // Class representing a forward iterator for character arrays
    class Iterator {
    private:
        char* currentPosition;

    public:
        Iterator(char* initialLocation = nullptr) : currentPosition(initialLocation) {}

        // Pre-increment operator
        Iterator& operator++() {
            ++currentPosition;
            return *this;
        }

        // Post-increment operator
        Iterator operator++(int) {
            Iterator previousState(*this);
            ++currentPosition;
            return previousState;
        }

        // Pre-decrement operator
        Iterator& operator--() {
            --currentPosition;
            return *this;
        }

        // Post-decrement operator
        Iterator operator--(int) {
            Iterator previousState(*this);
            --currentPosition;
            return previousState;
        }

        // Addition operator for offsetting the iterator
        Iterator operator+(size_t offset) {
            Iterator previousState(*this);
            currentPosition += offset;
            return previousState;
        }

        // Assignment operator
        Iterator& operator=(const Iterator& rhs) {
            currentPosition = rhs.currentPosition;
            return *this;
        }

        // Equality comparison operator
        bool operator==(const Iterator& rhs) const {
            return currentPosition == rhs.currentPosition;
        }

        // Inequality comparison operator
        bool operator!=(const Iterator& rhs) const {
            return currentPosition != rhs.currentPosition;
        }

        // Dereference operator
        char& operator*() {
            return *currentPosition;
        }

        // Arrow operator
        char* operator->() {
            return currentPosition;
        }
    };

