#include <bits/stdc++.h>

class String {
private:
    char* data;
    size_t length;

public:
    // Default constructor initializes an empty string
    String() : data(new char('\0')), length(0) {}

    // Constructor from a C-style string
    String(char* other) : length(strlen(other)) {
        data = new char[length + 1];
        strcpy(data, other);
    }

    // Constructor from a std::string
    String(const std::string& other) : length(other.size()) {
        data = new char[length + 1];
        for (size_t i = 0; i < length; ++i) {
            data[i] = other[i];
        }
        data[length] = '\0';
    }

    // Copy constructor for deep copy
    String(const String &other) : length(other.length) {
        data = new char[length + 1];
        strcpy(data, other.data);
    }

    // Getter for the string data
    inline char* get_string() const {
        return data;
    }

    // Change a character at a specific index
    inline void change_character(unsigned index, char ch) {
        if (index < length) {
            data[index] = ch;
        }
    }

    // Access character at a specific index with bounds checking
    char& access_character(unsigned index) {
        if (index >= length) {
            return data[0];
        }
        return data[index];
    }

    // Assignment operator for deep copy
    String& operator=(const String& other) {
        if (this != &other) {
            length = other.length;
            delete[] data;
            data = new char[length + 1];
            strcpy(data, other.data);
        }
        return *this;
    }

    // Destructor to free allocated memory
    ~String() {
        delete[] data;
    }

    // Move constructor for efficient resource transfer
    String(String&& other) : length(std::exchange(other.length, 0)), data(std::exchange(other.data, nullptr)) {
        std::cout << "Move constructor invoked\n";
    }

    // Equality operator to compare two strings
    inline bool operator==(const String& other) const {
        if (length != other.length) {
            return false;
        }
        for (size_t i = 0; i < length; ++i) {
            if (data[i] != other.data[i]) {
                return false;
            }
        }
        return true;
    }

    // Less-than operator for string comparison
    inline bool operator<(const String& other) const {
        if (length < other.length) {
            return true;
        }
        if (length > other.length) {
            return false;
        }

        for (size_t i = 0; i < length; i++) {
            if (data[i] != other.data[i]) {
                return data[i] < other.data[i];
            }
        }
        return false; // Strings are identical
    }
};

// Function to return a String object
String create_string(String input) {
    return input;
}

int main() {
    String str1; // Default constructed string
    String str2("abc cba");

    std::cout << "My string str1 is: " << str1.get_string() << '\n';
    std::cout << "My string str2 is: " << str2.get_string() << '\n';

    std::string example = "tudor";
    String str3(example);
    std::cout << "My string str3 is: " << str3.get_string() << '\n';

    String str4 = str3; // Copying str3 to str4
    str1 = str4; // Assigning str4 to str1
    std::cout << "My string str4 is: " << str4.get_string() << '\n';
    std::cout << "My string str1 is: " << str1.get_string() << '\n';

    str1.change_character(1, 'm'); // Modifying str1
    std::cout << "My string str4 is: " << str4.get_string() << '\n';
    std::cout << "My string str1 is: " << str1.get_string() << '\n';

    str1.change_character(2, 'm'); // Further modification
    std::cout << "My string str4 is: " << str4.get_string() << '\n';
    std::cout << "My string str1 is: " << str1.get_string() << '\n';

    String str5 = create_string(str4); // Using the function to create a new string
    std::cout << "My string str5 is: " << str5.get_string() << '\n';

    return 0;
}

#include <iostream>
#include <fstream>
#include <vector>

using namespace std;

class DynamicIntVector {
    size_t size;
    std::vector<int*> elements;

public:
    DynamicIntVector() : size(0) {}

    DynamicIntVector(const std::vector<int>& inputVector) : size(inputVector.size()) {
        for (const auto& value : inputVector) {
            elements.emplace_back(new int(value)); // Allocate new integer for each element
        }
    }

    DynamicIntVector(const DynamicIntVector& other) : size(other.size) {
        for (const auto& ptr : other.elements) {
            elements.emplace_back(new int(*ptr)); // Deep copy of each integer
        }
    }

    // Operator Overloading
    friend ostream& operator<<(ostream&, const DynamicIntVector&);
    friend istream& operator>>(istream&, DynamicIntVector&);

    DynamicIntVector operator+(int value) const {
        DynamicIntVector result(*this); // Create a copy for modification
        for (auto& ptr : result.elements) {
            (*ptr) += value; // Increment each element by the given value
        }
        return result;
    }

    friend DynamicIntVector operator+(int value, const DynamicIntVector& vector) {
        return vector + value; // Allow addition from the left side
    }

    DynamicIntVector& operator++() {
        for (auto& ptr : elements) {
            (*ptr)++; // Increment each element
        }
        return *this;
    }

    DynamicIntVector operator++(int) {
        DynamicIntVector copy(*this); // Create a copy for post-increment
        operator++(); // Reuse pre-increment logic
        return copy;
    }

    int& operator[](int index) {
        return *elements[index]; // Access element by index
    }

    // Destructor
    ~DynamicIntVector() {
        for (auto& ptr : elements) {
            delete ptr; // Free allocated memory
        }
        elements.clear(); // Clear the vector
    }

    DynamicIntVector& operator=(const DynamicIntVector& vector) {
        if (this != &vector) { // Self-assignment check
            size = vector.size;
            for (auto& ptr : elements) {
                delete ptr; // Free existing memory
            }
            elements.clear();
            for (const auto& ptr : vector.elements) {
                elements.emplace_back(new int(*ptr)); // Deep copy of each integer
            }
        }
        return *this;
    }

    bool operator==(const DynamicIntVector& vector) const {
        if (size != vector.size) {
            return false; // Sizes must match for equality
        }
        for (size_t i = 0; i < elements.size(); i++) {
            if (*elements[i] != *(vector.elements[i])) {
                return false; // Compare each element
            }
        }
        return true;
    }

    bool operator<(const DynamicIntVector& vector) const {
        for (size_t i = 0; i < min(size, vector.size); i++) {
            if (*elements[i] != *vector.elements[i]) {
                return *elements[i] < *vector.elements[i]; // Compare elements
            }
        }
        return size < vector.size; // Compare sizes if all elements are equal
    }
};

// Output stream operator for DynamicIntVector
ostream& operator<<(ostream& out, const DynamicIntVector& vector) {
    for (const auto& ptr : vector.elements) {
        out << *ptr << ' '; // Output each element
    }
    return out;
}

// Input stream operator for DynamicIntVector
istream& operator>>(istream& in, DynamicIntVector& vector) {
    in >> vector.size; // Read the size of the vector
    for (auto& ptr : vector.elements) {
        delete ptr; // Free existing memory
    }
    vector.elements.clear();
    for (size_t i = 0; i < vector.size; i++) {
        int value;
        in >> value; // Read each integer value
        vector.elements.emplace_back(new int(value)); // Allocate new integer
    }
    return in;
}

int main() {
    DynamicIntVector vector = DynamicIntVector(std::vector<int>({1, -9, 77, 55, -88}));

    std::cout << vector << '\n'; // Output the vector

    DynamicIntVector result;
    std::cin >> result; // Input vector values

    result = result + 2; // Add 2 to each element
    cout << result << '\n'; // Output the modified vector

    result = 9 + result; // Add 9 to each element
    cout << result << '\n'; // Output the modified vector

    cout << ++result << '\n'; // Pre-increment and output
    cout << result++ << '\n'; // Post-increment and output

    result[1] = 9; // Modify the second element
    cout << result << '\n'; // Output the modified vector

    return 0;
}

