    Base* basePtr = &derivedInstance;  // Upcasting to base class pointer

    Base& baseRef = baseInstance;       // Reference to base instance
    Base& derivedRef = derivedInstance;  // Upcasting to base class reference

    std::cout << derivedInstance.value << " " << derivedRef.value << '\n'; // Outputs: 10 10
    derivedRef.value = 6;
    std::cout << derivedInstance.value << " " << derivedRef.value << '\n'; // Outputs: 6 6!

    baseRef.display();      // Calls Base's display
    derivedRef.display();   // Calls Derived's display

    // Accessing Derived's specific area through Base pointer
    static_cast<Derived*>(basePtr)->additionalValue = 77; // Safe downcast
    std::cout << derivedInstance.additionalValue << '\n';

    // Unsafe downcast from Base to Derived
    Derived* unsafeDerivedPtr = (Derived*)&baseInstance;  // Residual area of Derived
    unsafeDerivedPtr->display(); // Calls Base's display (not virtual)

