#include <iostream>

class Base {
public:
    virtual void display() {
        std::cout << "Base\n";
    }
};

class Derived : public Base {
public:
    void display() override {
        std::cout << "Derived\n";
    }
};

int main() {
    Base* basePtr = new Derived();

    // Check the actual type of the object pointed to by basePtr
    if (dynamic_cast<Derived*>(basePtr)) {
