    ifstream bookFile("Books.txt");
    if (bookFile.is_open()) {
        while (bookFile >> bookID >> bookName >> bookAuthor) {
            bookFound = false;
            for (int i = 0; i < 101; i++) {
                if (bookName[i] == '_')
                    bookName[i] = ' ';
                if (bookAuthor[i] == '_')
                    bookAuthor[i] = ' ';
            }
            bookId = atoi(bookID);
            if (bookId == bookId) {
                bookFound = true;
                bookFile.close();
                break;
            }
        }
        bookFile.close();
    } else {
        cerr << "Error Opening File!" << endl;
        cout << "Enter 0 to exit or 1 to try again." << endl;
        int retryOption;
        cin >> retryOption;
        if (retryOption == 1)
            goto retryBookSearch;
        else
            exit(0);
