#include <iostream>
using namespace std;

class Matrix {
    int rows, cols;
    int elements[5][5];

public:
    void input(int, int);
    void display() const;
    void add(const Matrix&, const Matrix&);
};

// Accepts the dimensions and elements of the matrix from user input.
void Matrix::input(int r, int c) {
    rows = r;
    cols = c;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            cin >> elements[i][j];
        }
    }
}

// Displays the matrix elements in a formatted manner.
void Matrix::display() const {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            cout << elements[i][j] << " ";
        }
        cout << endl;
    }
}

// Computes the sum of two matrices and stores the result in the current matrix.
void Matrix::add(const Matrix &m1, const Matrix &m2) {
    rows = m1.rows;
    cols = m1.cols;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            elements[i][j] = m1.elements[i][j] + m2.elements[i][j];
        }
    }
}

