};

void CompareAges(const Person &firstPerson, const Person &secondPerson) {
    // Compare ages of two persons and print the result
    if (firstPerson.age != secondPerson.age) {
        int olderAge = (firstPerson.age > secondPerson.age) ? firstPerson.age : secondPerson.age;
