// Abstract base class for handling exceptions related to account operations
class ExceptionHandler {
public:
    virtual void ShowExceptionInfo() const = 0; // Pure virtual function for displaying exception information
};

// Exception for negative values in account transactions
class MinusException : public ExceptionHandler {
private:
    double invalidValue;

public:
    MinusException(double value) : invalidValue(value) {}

    void ShowExceptionInfo() const override {
        cout << "Giá trị giao dịch " << invalidValue << " không hợp lệ!" << endl;
    }
};

// Exception for insufficient balance during transactions
class InsuffException : public ExceptionHandler {
private:
    double currentBalance;
    double requiredAmount;

public:
    InsuffException(double balance, double amount) : currentBalance(balance), requiredAmount(amount) {}

    void ShowExceptionInfo() const override {
        cout << "Thiếu " << requiredAmount - currentBalance << " để thực hiện giao dịch!" << endl;
    }
};

