// Abstract base class for traversing nodes in a data structure
class ARTraverser
{
public:
    ARTraverser();
    virtual ~ARTraverser();

    virtual bool hasNode() = 0; // Checks if there are more nodes to traverse
    virtual int next() = 0;      // Retrieves the next node's value

protected:
    Node *current; // Pointer to the current node being traversed
};

// Class for traversing nodes in a depth-first manner
class ARTF : public ARTraverser
{
public:
    ARTF(Node *startNode);
    virtual ~ARTF();

    virtual bool hasNode() override; // Checks for remaining nodes
    virtual int next() override;      // Returns the next node's value
};

// Class for traversing nodes in a breadth-first manner
class ARTL : public ARTraverser
{
public:
    ARTL(Node *startNode);
    virtual ~ARTL();

    virtual bool hasNode() override; // Checks for remaining nodes
    virtual int next() override;      // Returns the next node's value
};

