// Global variables for calculations
float totalCost = 0;
double taxRate = 0.08;
int discountRate = 0;
float discountedTotal = 0;
float discountAmount = 0;

template <class T>
class Shop {
    vector<T> items;

public:
    // Constructor to initialize shop with an item and calculate total cost
    Shop(T initialItem) {
        items.push_back(initialItem);
        totalCost = initialItem.getPay() * (1 + taxRate);
    }

    // Function to add an item and update total cost
    void add(T newItem) {
        items.push_back(newItem);
        totalCost += newItem.getPay() * (1 + taxRate);
    }

    // Overloaded operator for exception handling
    T* operator[](int index) {
        throw string("We don't have enough Cookies!");
    }

    // Overloaded operator for printing shop details
    friend ostream& operator<<(ostream& output, const Shop<T>& shop) {
        output << "*********************" << endl;
        output << "Number of Items: " << shop.items.size() << endl;

        for (size_t i = 0; i < shop.items.size(); i++) {
            output << i + 1 << ": " << shop.items[i].getName() 
                   << " #" << shop.items[i].getNumber() 
                   << " Cost: " << shop.items[i].getPay() << endl;
        }

        output << "Total Cost: " << totalCost << endl;

        if (discountRate > 0) {
            output << "Discount: " << discountRate << "%" << endl;
            output << "Discount Amount: " << discountAmount << endl;
            output << "Discounted Cost: " << discountedTotal << endl;
        }

        output << "*********************" << endl;
        totalCost = 0; // Reset total cost after printing
        return output;
    }

    // Function to set discount rate and calculate discount details
    void setDiscount(int rate) {
        if (rate > 0 && rate < 30) {
            discountRate = rate;
            discountedTotal = totalCost * (1 - static_cast<float>(discountRate) / 100);
            discountAmount = totalCost - discountedTotal;
        } else {
            throw string("Discount rate is out of range!");
        }
    }
};

