        try {
            connection.Rollback();
        } catch (SAException &) {
        }
        cout << (const char*)exception.ErrText(); 
    }

    return 0;

menu:
    while (true) {
        system("cls");
        cout << setw(50) << ":Welcome to Nsm Bank:" << endl;
        cout << setw(55) << "Please select your option from below:" << endl;
        cout << "1. Create Account" << endl;
        cout << "2. Balance Enquiry" << endl;
        cout << "3. Modify Account" << endl;
        cout << "4. Reset password for your account" << endl;
        cout << "5. Exit" << endl;
        cout << "6. List all accounts" << endl;
        cout << setw(50) << "Your choice ->> ";
        cin >> choice;
        system("cls");

        switch (choice) {
            case 1: {
                try {
                    cout << "Enter the following data to create your account:" << endl;
                    bank.createNewAccount();

                    SACommand insertCommand(&connection, "INSERT INTO v(name, uname, Balance, Password) VALUES(:1, :2, :3, :4)");
                    insertCommand.Param(1).setAsString() = bank.name.c_str();
                    insertCommand.Param(2).setAsString() = bank.username.c_str();
                    insertCommand.Param(3).setAsString() = bank.initialBalance.c_str();
                    insertCommand.Param(4).setAsString() = bank.password.c_str();
                    insertCommand.Execute();
                    connection.Commit();

                    cout << endl << "Congratulations! Account created." << endl;
                    system("pause");
                } catch (SAException &exception) {
                    try {
                        connection.Rollback();
                    } catch (SAException &) {
                    }
                    cout << endl << "Please enter a different username, this username is already taken." << endl;
                    system("pause");
                }
                break;
            }

            case 2: {
                system("cls");
                string balance;
                string inputPassword;

                cout << setw(40) << "Enter Username for checking balance: ";
                cin >> bank.username;
                cout << setw(40) << "Enter password for checking balance: ";
                cin >> inputPassword;

                SACommand balanceCommand(&connection, "SELECT balance FROM v WHERE uname=:1 AND password=:2");
                balanceCommand.Param(1).setAsString() = bank.username.c_str();
                balanceCommand.Param(2).setAsString() = inputPassword.c_str();
                balanceCommand.Execute();

                if (balanceCommand.FetchNext() == 1) {
                    balance = balanceCommand.Field("balance").asString();
                    cout << "Press any key to see your balance:" << endl;
                    system("pause");
                    system("cls");
                    cout << "Your account balance is: RS." << balance << "/-" << endl << endl << endl;
                    system("pause");
                } else {
                    cout << endl << "Please input correct username or password." << endl << endl;
                    system("pause");
                }
                break;
            }

            case 3: {
                system("cls");
                int modificationChoice;
                cout << "Choose an option for further modification of account:" << endl;
                cout << "1. Delete your account" << endl;
                cout << "2. Withdrawal" << endl;
                cout << "3. Deposit" << endl;
                cout << "4. Go to Main Menu" << endl;
                cin >> modificationChoice;

                switch (modificationChoice) {
                    case 1: {
                        cout << "Enter your username to delete your account: ";
                        cin >> bank.userToDelete;
                        SACommand deleteCommand(&connection, "DELETE FROM v WHERE uname=:1");
                        deleteCommand.Param(1).setAsString() = bank.userToDelete.c_str();
                        deleteCommand.Execute();
                        cout << "Account Deleted" << endl;
                        system("pause");
                        break;
                    }
                    case 2: {
                        cout << "Enter your Username: ";
                        cin >> bank.userToWithdraw;
                        cout << "Enter amount to be withdrawn: ";
