void BorrowReceipt::createReturnReceipt() {
    string receiptData[50];
    int receiptIds[50];
    int receiptCount = 0, position = 0;
    fstream file;
    file.open("BorrowReceipts.txt", ios::in);
    if (!file.is_open()) {
        cout << "Unable to open BorrowReceipts.txt";
        return;
    }

    while (!file.eof()) {
        getline(file, receiptData[receiptCount++], '\n');
    }
    receiptCount--;
    file.close();

    if (receiptCount > 0) {
        string line;
        string receiptIdStr;
        int intReceiptId = 0, bookCount = 0;

        for (int j = 0; j < receiptCount; j++) {
            line = receiptData[j];
            string delimiter = "\t";
            receiptIdStr = line.substr(0, line.find(delimiter));
            if (!receiptIdStr.empty()) {
                stringstream ss(receiptIdStr);
                ss >> intReceiptId;
                if (intReceiptId == getReceiptId()) {
                    position = j;
                    size_t pos = 0;
                    string token;
                    bookCount = 0;
                    while ((pos = line.find(delimiter)) != string::npos) {
                        token = line.substr(0, pos);
                        stringstream ssToken(token);
                        ssToken >> receiptIds[bookCount++];
                        line.erase(0, pos + delimiter.length());
                    }
                }
            }
        }

        for (int j = 2; j < bookCount; j++) {
            processReturnedBook(receiptIds[j]);
        }

        fstream filePM;
        filePM.open("BorrowReceipts.txt", ios::out);
        if (!filePM.is_open()) {
            cout << "Unable to open BorrowReceipts.txt";
            return;
        }

        for (int i = 0; i < receiptCount; i++) {
            if (i != position) {
                filePM << receiptData[i] << "\n";
            }
        }

        cout << "\nBooks returned successfully\n";

        cout << setfill('-');
        cout << "+" << setw(15) << "+" << setw(30) << "+" << endl;
        cout << setfill(' ');

        cout << setw(15) << left << "| Receipt ID";
        cout << "| " << setw(28) << left << receiptIds[0] << "|" << endl;

        cout << setfill('-');
        cout << setw(15) << "+" << setw(30) << "+" << "+" << endl;
        cout << setfill(' ');

        cout << setw(15) << left << "| Student ID";
        cout << "| " << setw(28) << left << receiptIds[1] << "|" << endl;

        cout << setfill('-');
        cout << setw(15) << "+" << setw(30) << "+" << "+" << endl;
        cout << setfill(' ');

        cout << setw(15) << left << "| Returned Books:";
        cout << setw(30) << left << "| " << "|" << endl;
        for (int j = 2; j < bookCount; j++) {
            cout << setfill('-');
            cout << setw(15) << "+" << setw(30) << "+" << "+" << endl;
            cout << setfill(' ');
            displayBookDetails(receiptIds[j]);
        }
        cout << setfill('-');
        cout << setw(15) << "+" << setw(30) << "+" << "+" << endl;
        cout << setfill(' ');

        filePM.close();
    } else {
        cout << endl << "No borrow receipts found.";
    }
}

void BorrowReceipt::processReturnedBook(int returnedBookId) {
    int bookId;
    string line, bookTitle, author, publisher, publicationYear;
    fstream libraryFile;
    libraryFile.open("Library.txt", ios::in);
    if (!libraryFile.is_open()) {
        cout << "Unable to open Library.txt";
        return;
    }

    while (!libraryFile.eof()) {
        libraryFile >> bookId;
        if (bookId == returnedBookId) {
            getline(libraryFile, line, '\t');
            getline(libraryFile, bookTitle, '\t');
            getline(libraryFile, author, '\t');
            getline(libraryFile, publisher, '\t');
            getline(libraryFile, publicationYear, '\n');
            break;
        } else {
            getline(libraryFile, line, '\n');
        }
    }
    libraryFile.close();

    fstream catalogFile;
    catalogFile.open("BookCatalog.txt", ios::app | ios::out);
    if (!catalogFile.is_open()) {
        cout << "Unable to open BookCatalog.txt";
        return;
    }
    catalogFile << returnedBookId << "\t" << bookTitle << "\t" << author << "\t" << publisher << "\t" << publicationYear << "\n";
    catalogFile.close();
}

void BorrowReceipt::findReceiptsByStudentId() const {
    int receiptId, studentId, bookCount, bookIds[50];
    string line, bookIdStr, bookIdArray[50];
    fstream file;
    file.open("BorrowReceipts.txt", ios::in);
    if (!file.is_open()) {
        cout << "Unable to open BorrowReceipts.txt";
        return;
    }

    int bookIdCount = 0;
    while (!file.eof()) {
        file >> receiptId;
        file >> studentId;
        if (getStudentId() == studentId) {
            getline(file, line, '\t');
            getline(file, line, '\n');
            bookIdArray[bookIdCount++] = line;
        } else {
            getline(file, line, '\n');
        }
    }
    file.close();

    bookIdCount--;
    if (bookIdCount > 0) {
        int uniqueBookCount = 0;
        for (int i = 0; i < bookIdCount; i++) {
            stringstream ss(bookIdArray[i]);
            string token;
            while (getline(ss, token, '\t')) {
                bookIds[uniqueBookCount++] = stoi(token);
            }
        }

        // Remove duplicates
        int uniqueBooks[50], uniqueBookCountFinal = 0;
        for (int i = 0; i < uniqueBookCount; i++) {
            bool isDuplicate = false;
            for (int j = 0; j < uniqueBookCountFinal; j++) {
                if (uniqueBooks[j] == bookIds[i]) {
                    isDuplicate = true;
                    break;
                }
            }
            if (!isDuplicate) {
                uniqueBooks[uniqueBookCountFinal++] = bookIds[i];
            }
        }

        cout << endl << "Total books borrowed by student " << getStudentId() << ": " << uniqueBookCountFinal;
        cout << "\nBooks borrowed by the student: " << endl;
        cout << setfill('-');
        cout << "+" << setw(15) << "+" << setw(30) << "+" << endl;
        cout << setfill(' ');

        for (int j = 0; j < uniqueBookCountFinal; j++) {
            displayBookDetails(uniqueBooks[j]);
            cout << setfill('-');
            cout << setw(15) << "+" << setw(30) << "+" << "+" << endl;
            cout << setfill(' ');
        }
    } else {
        cout << endl << "No books borrowed by the student.";
    }
}

void BorrowReceipt::displayBookDetails(int bookId) const {
    int libraryBookId;
    string line, bookTitle, author, publisher, publicationYear;
    fstream libraryFile;
    libraryFile.open("Library.txt", ios::in);
    if (!libraryFile.is_open()) {
        cout << "Unable to open Library.txt";
        return;
    }

    while (!libraryFile.eof()) {
        libraryFile >> libraryBookId;
        if (bookId == libraryBookId) {
            getline(libraryFile, line, '\t');
            getline(libraryFile, bookTitle, '\t');
            getline(libraryFile, author, '\t');
            getline(libraryFile, publisher, '\t');
            getline(libraryFile, publicationYear, '\n');
            break;
        } else {
            getline(libraryFile, line, '\n');
        }
    }
    libraryFile.close();

    cout << setw(15) << left << "| Book ID";
    cout << "| " << setw(28) << left << bookId << "|" << endl;
    cout << setw(15) << left << "| Book Title";
    cout << "| " << setw(28) << left << bookTitle << "|" << endl;
}

