void Book::deleteBookFromLibrary(string fileName) {
    setCheckId(0);
    int position, bookCount;
    string bookList[50];
    fstream file;

    file.open(fileName + ".txt", ios::in);
    if (!file.is_open()) {
        cout << "Unable to open " + fileName + ".txt";
        return;
    }

    position = 0;
    bookCount = 0;
    while (!file.eof()) {
        getline(file, bookList[bookCount++], '\n');
    }
    bookCount--;
    file.close();

    string line;
    string bookIdStr, bookInfo[10];
    int intBookId, currentBookCount;
    for (int j = 0; j < bookCount; j++) {
        line = bookList[j];
        string delimiter = "\t";
        bookIdStr = line.substr(0, line.find(delimiter));
        if (!bookIdStr.empty()) {
            stringstream ss(bookIdStr);
            ss >> intBookId;
            if (intBookId == getId()) {
                position = j;
                size_t pos = 0;
                string token;
                currentBookCount = 0;
                while ((pos = line.find(delimiter)) != string::npos) {
                    token = line.substr(0, pos);
                    bookInfo[currentBookCount++] = token;
                    line.erase(0, pos + delimiter.length());
                }
            }
        }
    }

    fstream fileOut;
    fileOut.open(fileName + ".txt", ios::out);
    if (!fileOut.is_open()) {
        cout << "Unable to open " + fileName + ".txt";
        setCheckId(0);
    } else {
        for (int i = 0; i < bookCount; i++) {
            if (i != position) {
                fileOut << bookList[i] << "\n";
            }
        }
        setCheckId(1);
    }
}

