void Member::updateMember() {
    int position, totalMembers;
    string memberList[50];
    fstream file;
    file.open("Members.txt", ios::in);
    if (!file.is_open()) {
        cout << "Unable to open Members.txt";
        return;
    }

    position = 0;
    totalMembers = 0;
    while (!file.eof()) {
        getline(file, memberList[totalMembers++], '\n');
    }
    totalMembers--;
    file.close();

    string line;
    string memberIdStr, memberDetails[10];
    int memberId, memberCount;

    for (int j = 0; j < totalMembers; j++) {
        line = memberList[j];
        string delimiter = "\t";
        memberIdStr = line.substr(0, line.find(delimiter));
        if (!memberIdStr.empty()) {
            stringstream idStream(memberIdStr);
            idStream >> memberId;
            if (memberId == getStudentId()) {
                position = j;
                size_t pos = 0;
                string token;
                memberCount = 0;
                while ((pos = line.find(delimiter)) != string::npos) {
                    token = line.substr(0, pos);
                    memberDetails[memberCount++] = token;
                    line.erase(0, pos + delimiter.length());
                }
            }
        }
    }

    fstream outputFile;
    outputFile.open("Members.txt", ios::out);
    if (!outputFile.is_open()) {
        cout << "Unable to open Members.txt";
        return;
    }

    for (int i = 0; i < totalMembers; i++) {
        if (i != position) {
            outputFile << memberList[i] << "\n";
        } else {
            if (outputFile << getStudentId() << "\t" << getMemberName() << "\t" << getManagementClass() << "\t" << getPhoneNumber() << "\t" << getCardExpiryDate() << "\n") {
                cout << "\nMember updated successfully!";
            } else {
                cout << "\nFailed to update member!";
            }
        }
    }
}

void Member::removeMember() {
    int position, totalMembers;
    string memberList[50];
    fstream file;
    file.open("Members.txt", ios::in);
    if (!file.is_open()) {
        cout << "Unable to open Members.txt";
