matrix operator+(matrix& A, matrix& B)
{
    int loopCount;
    cout << "Enter the number of iterations for matrix addition: ";
    cin >> loopCount;

    if (A.liczba_wierszy == B.liczba_wierszy && A.liczba_kolumn == B.liczba_kolumn)
    {
        time_t startTime, endTime;
        matrix resultMatrix(A.liczba_wierszy, A.liczba_kolumn);

        startTime = time(NULL);
        for (int k = 0; k < loopCount; k++)
        {
#pragma omp parallel for
            for (int i = 0; i < resultMatrix.liczba_wierszy; i++)
                for (int j = 0; j < resultMatrix.liczba_kolumn; j++)
                    resultMatrix.macierz[i][j] = A.macierz[i][j] + B.macierz[i][j];
        }

        endTime = time(NULL);
        cout << "Time taken for matrix addition: " << difftime(endTime, startTime) << "\n";
        return resultMatrix;
    }
    else
    {
        throw matrix::Blad_wymiaru_macierzy();
    }
}

