class AccountManager {
private:
    char accountNumber[20];
    char firstName[10];
    char lastName[10];
    float totalBalance;

public:
    void inputAccountData();
    void displayAccountData();
    void saveRecord();
    void loadRecords();
    void findRecord();
    void updateRecord();
    void removeRecord();
};

void AccountManager::inputAccountData() {
    cout << "\nEnter Account Number: ";
    cin >> accountNumber;
    cout << "Enter First Name: ";
    cin >> firstName;
    cout << "Enter Last Name: ";
    cin >> lastName;
    cout << "Enter Balance: ";
    cin >> totalBalance;
    cout << endl;
}

void AccountManager::displayAccountData() {
    cout << "Account Number: " << accountNumber << endl;
    cout << "First Name: " << firstName << endl;
    cout << "Last Name: " << lastName << endl;
    cout << "Current Balance: Rs.  " << totalBalance << endl;
    cout << "-------------------------------" << endl;
}

void AccountManager::saveRecord() {
    ofstream outfile;
    outfile.open("record.bank", ios::binary | ios::app);
    inputAccountData();
    outfile.write(reinterpret_cast<char*>(this), sizeof(*this));
    outfile.close();
}

void AccountManager::loadRecords() {
    ifstream infile;
    infile.open("record.bank", ios::binary);
    if (!infile) {
        cout << "Error in Opening! File Not Found!!" << endl;
        return;
    }
    cout << "\n****Data from file****" << endl;
    while (!infile.eof()) {
        if (infile.read(reinterpret_cast<char*>(this), sizeof(*this)) > 0) {
            displayAccountData();
        }
    }
    infile.close();
}

void AccountManager::findRecord() {
    int recordNumber;
    ifstream infile;
    infile.open("record.bank", ios::binary);
    if (!infile) {
        cout << "\nError in opening! File Not Found!!" << endl;
        return;
    }
    infile.seekg(0, ios::end);
    int recordCount = infile.tellg() / sizeof(*this);
    cout << "\n There are " << recordCount << " records in the file";
    cout << "\n Enter Record Number to Search: ";
    cin >> recordNumber;
    infile.seekg((recordNumber - 1) * sizeof(*this));
    infile.read(reinterpret_cast<char*>(this), sizeof(*this));
    displayAccountData();
}

void AccountManager::updateRecord() {
    int recordNumber;
    fstream iofile;
    iofile.open("record.bank", ios::in | ios::binary);
    if (!iofile) {
        cout << "\nError in opening! File Not Found!!" << endl;
        return;
    }
    iofile.seekg(0, ios::end);
    int recordCount = iofile.tellg() / sizeof(*this);
    cout << "\n There are " << recordCount << " records in the file";
    cout << "\n Enter Record Number to edit: ";
    cin >> recordNumber;
    iofile.seekg((recordNumber - 1) * sizeof(*this));
    iofile.read(reinterpret_cast<char*>(this), sizeof(*this));
    cout << "Record " << recordNumber << " has the following data" << endl;
    displayAccountData();
    iofile.close();
    iofile.open("record.bank", ios::out | ios::in | ios::binary);
    iofile.seekp((recordNumber - 1) * sizeof(*this));
    cout << "\nEnter data to Modify " << endl;
    inputAccountData();
    iofile.write(reinterpret_cast<char*>(this), sizeof(*this));
}

void AccountManager::removeRecord() {
    int recordNumber;
    ifstream infile;
    infile.open("record.bank", ios::binary);
    if (!infile) {
        cout << "\nError in opening! File Not Found!!" << endl;
        return;
    }
    infile.seekg(0, ios::end);
    int recordCount = infile.tellg() / sizeof(*this);
    cout << "\n There are " << recordCount << " records in the file";
    cout << "\n Enter Record Number to Delete: ";
    cin >> recordNumber;
    fstream tempFile;
    tempFile.open("tmpfile.bank", ios::out | ios::binary);
    infile.seekg(0);
    for (int i = 0; i < recordCount; i++) {
        infile.read(reinterpret_cast<char*>(this), sizeof(*this));
        if (i == (recordNumber - 1))
            continue;
        tempFile.write(reinterpret_cast<char*>(this), sizeof(*this));
    }
    infile.close();
    tempFile.close();
    remove("record.bank");
    rename("tmpfile.bank", "record.bank");
}

int main() {
    AccountManager accountManager;
    int userChoice;
    cout << "***Account Information System***" << endl;
    while (true) {
        cout << "Select one option below ";
        cout << "\n\t1-->Add record to file";
        cout << "\n\t2-->Show record from file";
        cout << "\n\t3-->Search Record from file";
        cout << "\n\t4-->Update Record";
        cout << "\n\t5-->Delete Record";
        cout << "\n\t6-->Quit";
        cout << "\nEnter your choice: ";
        cin >> userChoice;
        switch (userChoice) {
            case 1:
                accountManager.saveRecord();
                break;
            case 2:
                accountManager.loadRecords();
                break;
            case 3:
                accountManager.findRecord();
                break;
            case 4:
                accountManager.updateRecord();
                break;
            case 5:
                accountManager.removeRecord();
                break;
            case 6:
                exit(0);
                break;
            default:
                cout << "\nEnter correct choice";
                exit(0);
        }
    }
    return 0;
}

