// Abstract class representing a game state with polymorphic behavior
class GameState
{
public:
	virtual void Initialize(RenderWindow* window) {}
	virtual void Update(RenderWindow* window) {}
	virtual void Render(RenderWindow* window) {}
	virtual void Cleanup(RenderWindow* window) {}
};

class GameStateManager
{
private:
	RenderWindow* window;
	GameState* currentState;

public:
	GameStateManager() : currentState(nullptr) {}

	void SetWindow(RenderWindow* window)
	{
		this->window = window;
	}

	// Set the current game state and initialize it if necessary
	void SetState(GameState* state)
	{
		if (currentState != nullptr)
		{
			currentState->Cleanup(window);
		}
		currentState = state;
		if (currentState != nullptr)
		{
			currentState->Initialize(window);
		}
	}

	// Update the current game state
	void Update()
	{
		if (currentState != nullptr)
		{
			currentState->Update(window);
		}
	}

	// Render the current game state
	void Render()
	{
		if (currentState != nullptr)
		{
			currentState->Render(window);
		}
	}

	// Cleanup resources when the manager is destroyed
	~GameStateManager()
	{
		if (currentState != nullptr)
		{
			currentState->Cleanup(window);
		}
	}
};

