// Base class representing a game entity, serving as a foundation for specific entities like Ball and Paddle.
class GameEntity : public Sprite
{
private:
	Texture* textureResource;

public:
	Vector2f velocity; // Velocity of the entity represented as a Vector2f

	// Retrieves the current velocity of the entity.
	Vector2f getVelocity() const
	{
		return velocity;
	}

	// Sets the velocity of the entity.
	void setVelocity(Vector2f newVelocity)
	{
		velocity = newVelocity;
	}

	// Loads texture from a specified file and applies it to the entity.
	void loadTexture(const string& filename)
	{
		textureResource->loadFromFile("Graphics/sprites/" + filename);
		this->setTexture(*textureResource);
	}

	// Updates the entity's position based on its velocity.
	virtual void update()
	{
		this->move(velocity);
	}

	// Checks for collision with another game entity.
	bool checkCollision(GameEntity* otherEntity) const
	{
		return this->getGlobalBounds().intersects(otherEntity->getGlobalBounds());
	}

	GameEntity()
	{
		textureResource = new Texture();
	}

	~GameEntity()
	{
		delete textureResource;
	}
};

