// Function to generate the food bill based on customer input
void FoodManager::generateFoodBill() {
    double billAmount = -1;
    char customerName[20], foodName[20];
    int quantity;

    cleardevice();
    setfillstyle(7, 1);
    floodfill(0, 0, 4);
    setfillstyle(7, 10);
    bar(17, 40, 605, 420);
    rectangle(17, 40, 605, 420);
    setfillstyle(1, 7);
    bar(24, 47, 598, 413);
    rectangle(24, 47, 598, 413);
    setcolor(4);
    settextstyle(7, 0, 1);

    outtextxy(30, 70, "ENTER CUSTOMER NAME ");
    gotoxy(50, 6);
    std::cin >> customerName;

    outtextxy(30, 120, "ENTER ITEM NAME TAKEN");
    gotoxy(50, 9);
    std::cin >> foodName;

    outtextxy(30, 170, "ENTER THE QUANTITY");
    gotoxy(50, 12);
    std::cin >> quantity;

    foodFile.close();
    foodFile.open("food.txt", std::ios::in | std::ios::binary);

    while (foodFile.read(reinterpret_cast<char*>(&foodItem), sizeof(foodItem))) {
        if (strcmp(foodItem.name, foodName) == 0) {
            billAmount = quantity * foodItem.price;
        }
    }

    if (billAmount == -1) {
        setcolor(1);
        for (int i = 0; i <= 20; i++) {
            setcolor(1);
            outtextxy(30, 220, "ITEM IS NOT PRESENT");
            delay(100);
            setcolor(WHITE);
            outtextxy(30, 220, "ITEM IS NOT PRESENT");
            delay(100);
        }
    } else {
        char quantityStr[5], billStr[5];
        setcolor(1);
        itoa(quantity, quantityStr, 10);
        itoa(billAmount, billStr, 10);
        outtextxy(30, 250, "NAME FOOD.NAME      QUANTITY      BILL ");
        setcolor(1);
        settextstyle(4, 0, 1);
        outtextxy(30, 280, customerName);
        outtextxy(140, 280, foodName);
        outtextxy(320, 280, quantityStr);
        outtextxy(445, 280, billStr);
        getch();
    }
}

