// Function to modify an existing customer
void CustomerManager::modifyCustomer() {
    cleardevice();
    customerFile.close();
    setfillstyle(7, 1);
    floodfill(0, 0, 4);
    setfillstyle(7, 10);
    bar(10, 10, 600, 470);
    rectangle(10, 10, 600, 470);
    setfillstyle(1, 7);
    bar(17, 17, 593, 463);
    rectangle(17, 17, 593, 463);

    int customerNumber;
    outtextxy(30, 42, "ENTER CUSTOMER NO TO BE MODIFIED");
    gotoxy(65, 4);
    std::cin >> customerNumber;

    customerFile.open("cust.txt", std::ios::in | std::ios::binary);
    while (customerFile.read(reinterpret_cast<char*>(&customer), sizeof(customer))) {
        if (customer.customerNumber == customerNumber) {
            customerFile.close();
            int recordPosition = sizeof(customer) * (customerNumber - 1);
            customerFile.open("cust.txt", std::ios::out | std::ios::ate | std::ios::binary);
            customerFile.seekp(recordPosition, std::ios::beg);
            outtextxy(30, 110, "ENTER NEW RECORD ");
            outtextxy(30, 150, "NAME");
            gotoxy(30, 11);
            std::cin >> customer.name;
            outtextxy(30, 200, "ADDRESS");
            gotoxy(30, 14);
            std::cin >> customer.address;
            outtextxy(30, 250, "DATE");
            gotoxy(30, 17);
            std::cin >> customer.arrivalDate;
            outtextxy(30, 300, "MONTH");
            gotoxy(30, 20);
            std::cin >> customer.arrivalMonth;
            outtextxy(30, 350, "YEAR");
            gotoxy(30, 23);
            std::cin >> customer.arrivalYear;
            customerFile.write(reinterpret_cast<char*>(&customer), sizeof(customer));
            customerFile.close();
        }
    }
}

// Function to delete a specific customer
void CustomerManager::deleteCustomer() {
    cleardevice();
    customerFile.close();
    setfillstyle(7, 1);
    floodfill(0, 0, 4);
    setfillstyle(7, 10);
    bar(10, 10, 600, 470);
    rectangle(10, 10, 600, 470);
    setfillstyle(1, 7);
    bar(17, 17, 593, 463);
    rectangle(17, 17, 593, 463);

    int customerNumber;
    outtextxy(30, 42, "ENTER CUSTOMER NO TO BE DELETED");
    gotoxy(65, 4);
    std::cin >> customerNumber;

    customerFile.open("cust.txt", std::ios::in | std::ios::binary);
    std::fstream tempFile;
    tempFile.open("temp.txt", std::ios::app | std::ios::binary);

    while (customerFile.read(reinterpret_cast<char*>(&customer), sizeof(customer))) {
        if (customer.customerNumber != customerNumber) {
            tempFile.write(reinterpret_cast<char*>(&customer), sizeof(customer));
        }
    }

    customerFile.close();
    tempFile.close();
    remove("cust.txt");
    rename("temp.txt", "cust.txt");
}

