                delay(100);
                settextstyle(7, 0, 1);
                outtextxy(200, 340, "PRESS ANY KEY TO CONTINUE");
            }
            cleardevice();
        }
    }

    do {
        choice = mainMenu();
        handleChoice(choice);
    } while (choice != 5);
}

