template <typename T>
void removeMember(const string& filePath, const string& tempFilePath, const T& schoolMember)
{
    system("cls");
    int inputId = 0;
    short matchCount = 0;
    ifstream inputFile(filePath, ios::binary);
    ofstream outputFile(tempFilePath, ios::binary | ios::app);

    cout << "Enter ID of the member to remove: ";
    cin >> inputId;

    while (inputFile.read(reinterpret_cast<char*>(&schoolMember), sizeof(schoolMember)))
    {
        if (inputId == schoolMember.getId())
            matchCount++;
        else
            outputFile.write(reinterpret_cast<char*>(&schoolMember), sizeof(schoolMember));
    }

    if (matchCount == 0)
        cout << "Sorry, no match found.";
    else
        cout << "Data of ID " << inputId << " has been removed from the file.";

    inputFile.close();
    outputFile.close();
    remove(filePath.c_str());
    rename(tempFilePath.c_str(), filePath.c_str());
    basicNavigation();
}

