template <typename T>
void updateMemberData(const string& filePath, T& schoolMember)
{
    system("cls");
    int inputId = 0;
    short matchCount = 0;
    long filePosition = 0;
    fstream file(filePath, ios::in | ios::out | ios::binary);

    if (file)
    {
        cout << "Enter ID or roll number of the member to update: ";
        cin >> inputId;

        while (!file.eof())
        {
            filePosition = file.tellg();
            file.read(reinterpret_cast<char*>(&schoolMember), sizeof(schoolMember));
            if (inputId == schoolMember.getId())
            {
                matchCount++;
                break;
            }
        }

        if (matchCount > 0)
        {
            schoolMember.updateData();
            file.seekg(filePosition);
            file.write(reinterpret_cast<char*>(&schoolMember), sizeof(schoolMember));
            cout << "\nFile has been successfully updated.";
        }
        else
            cout << "Sorry, no match found.";
    }
    else
        cout << "\nOops! There's something wrong with the file " << filePath << ". Please, ensure it exists.\n";

    basicNavigation();
}

