void Student::generateRollNumber()
{
    Student tempStudent;
    fstream studentFile("data/student.dat", ios::in | ios::out | ios::app | ios::binary);
    short matchCount = 0;

    while (studentFile.read(reinterpret_cast<char*>(&tempStudent), sizeof(tempStudent)))
    {
        if (studentClass == tempStudent.studentClass && studentSection == tempStudent.studentSection)
        {
            matchCount++;
            sanitizeCharArray(name, NAME_LENGTH);
            if (strcmp(name, tempStudent.name) == 0)
            {
                id = tempStudent.id + 1;
                break;
            }
            else
            {
                for (short i = 0; i < 5; ++i)
                {
                    if (tempStudent.name[i] > name[i])
                    {
                        tempStudent.id++;
                        id = tempStudent.id - 1;
                        break;
                    }
                    else if (tempStudent.name[i] < name[i])
                    {
                        id = tempStudent.id + 1;
                        break;
                    }
                }
            }
        }
    }

    if (matchCount == 0)
        id = (studentClass * 1000) + (studentSection - 96) * 100 + id;
}

