		return out << "Car Name: " << car->getName() << ", Manufacturer: " << car->getManufacturer();
	}

	Car() = default; // Default constructor
	Car(const Car&) = delete; // Copy constructor
	Car(Car&&) = delete; // Move constructor
	virtual ~Car() {} // Destructor
};

