/*
* Singleton Design Pattern
* Ensures that a class has only one instance and provides a global point of access to it.
*/
class Singleton {
public:
	// Initializes the Singleton instance
	static void NotifyInitialization()
	{
		std::cout << "Initializing Singleton" << std::endl;
	}

	// Provides access to the single instance of Singleton
	static Singleton& getInstance() 
	{
		std::call_once(onceFlag, []() {
			NotifyInitialization();
			instance.reset(new Singleton());
		});
		std::cout << "Retrieving Singleton instance" << std::endl;
		return *instance;
	}

private:
	static std::unique_ptr<Singleton> instance; // Holds the single instance of Singleton
	static std::once_flag onceFlag; // Ensures thread-safe initialization

	Singleton() = default; // Private constructor
	Singleton(const Singleton& other) = delete; // Prevent copy construction
	Singleton& operator=(const Singleton& other) = delete; // Prevent assignment
};

// Definition of static members
std::unique_ptr<Singleton> Singleton::instance;
std::once_flag Singleton::onceFlag;

int main()
{
	Singleton& instance1 = Singleton::getInstance();
	Singleton& instance2 = Singleton::getInstance();

	system("pause");
	return 0;
}

