#include <string>
#include <vector>

// Liskov Substitution Principle (LSP) ensures that objects of a superclass 
// should be replaceable with objects of a subclass without affecting the correctness of the program.

class Rectangle
{
private:
    double height_;
    double width_;

public:
    Rectangle(double height, double width) : height_(height), width_(width) {}

    virtual void SetHeight(double height) { height_ = height; }
    virtual void SetWidth(double width) { width_ = width; }

    double GetHeight() const { return height_; }
    double GetWidth() const { return width_; }

    double CalculateArea() const { return width_ * height_; }
};

class Square : public Rectangle
{
public:
    Square(double sideLength) : Rectangle(sideLength, sideLength) {}

    virtual void SetWidth(double width) override
    {
        Rectangle::SetWidth(width);
        Rectangle::SetHeight(width);
    }

    virtual void SetHeight(double height) override
    {
        Rectangle::SetHeight(height);
        Rectangle::SetWidth(height);
    }
};

// Processes a rectangle by setting its height and calculating the area.
void ProcessRectangle(Rectangle& rectangle)
{
    double originalWidth = rectangle.GetWidth();
    rectangle.SetHeight(10);
    std::cout << "Expected area = " << (10 * originalWidth) 
              << ", Calculated area = " << rectangle.CalculateArea() << std::endl;
}

int main() 
{
    Rectangle rectangle(5, 5);
    ProcessRectangle(rectangle);

    Square square(5);
    ProcessRectangle(square); // This violates LSP as Square does not behave like a Rectangle.
}

