#include <string>
#include <vector>

enum class Color { RED, GREEN, BLUE };
enum class Size { SMALL, MEDIUM, LARGE };

class Product {
private:
    std::string name_;
    Color color_;
    Size size_;

public:
    Product(std::string name, Color color, Size size) : name_(std::move(name)), color_(color), size_(size) {}

    const std::string& getName() const { return name_; }
    const Color& getColor() const { return color_; }
    const Size& getSize() const { return size_; }

    void print() const { std::cout << "Name = " << name_ << std::endl; }
};

// Abstract base class for specifications
template <typename T>
class ISpecification {
public:
    virtual bool isSatisfied(T* item) = 0;
};

class ColorSpecification : public ISpecification<Product> {
private:
    Color color_;

public:
    explicit ColorSpecification(Color color) : color_(color) {}

    bool isSatisfied(Product* product) override {
        return product->getColor() == color_;
    }
};

class SizeSpecification : public ISpecification<Product> {
private:
    Size size_;

public:
    explicit SizeSpecification(Size size) : size_(size) {}

    bool isSatisfied(Product* product) override {
        return product->getSize() == size_;
    }
};

template<typename T>
class AndSpecification : public ISpecification<T> {
private:
    ISpecification<T>& first_;
    ISpecification<T>& second_;

public:
    AndSpecification(ISpecification<T>& first, ISpecification<T>& second) : first_(first), second_(second) {}

    bool isSatisfied(T* product) override {
        return first_.isSatisfied(product) && second_.isSatisfied(product);
    }
};

template<typename T>
class OrSpecification : public ISpecification<T> {
private:
    ISpecification<T>& first_;
    ISpecification<T>& second_;

public:
    OrSpecification(ISpecification<T>& first, ISpecification<T>& second) : first_(first), second_(second) {}

    bool isSatisfied(T* product) override {
        return first_.isSatisfied(product) || second_.isSatisfied(product);
    }
};

// Abstract base class for filters
template <typename T>
class IFilter {
public:
    virtual std::vector<T*> filter(const std::vector<T*>& items, ISpecification<T>& spec) = 0;
};

class ProductFilter : public IFilter<Product> {
public:
    std::vector<Product*> filter(const std::vector<Product*>& items, ISpecification<Product>& spec) override {
        std::vector<Product*> results;
        for (const auto& item : items) {
            if (spec.isSatisfied(item)) {
                results.emplace_back(item);
            }
        }
        return results;
    }
};

int main() {
    Product apple("Apple", Color::GREEN, Size::MEDIUM);
    Product tree("Tree", Color::GREEN, Size::LARGE);
    Product house("House", Color::BLUE, Size::LARGE);

    std::vector<Product*> allProducts = { &apple, &tree, &house };
    ProductFilter productFilter;

    ColorSpecification greenSpec(Color::GREEN);
    auto greenProducts = productFilter.filter(allProducts, greenSpec);
    std::cout << "Green products: " << std::endl;
    for (const auto& greenProduct : greenProducts) {
        greenProduct->print();
    }

    SizeSpecification largeSpec(Size::LARGE);
    auto largeProducts = productFilter.filter(allProducts, largeSpec);
    std::cout << "Large products: " << std::endl;
    for (const auto& largeProduct : largeProducts) {
        largeProduct->print();
    }

    AndSpecification<Product> greenAndLarge(greenSpec, largeSpec);
    auto greenAndLargeProducts = productFilter.filter(allProducts, greenAndLarge);
    std::cout << "Green and large products: " << std::endl;
    for (const auto& product : greenAndLargeProducts) {
        product->print();
    }

    OrSpecification<Product> greenOrLarge(greenSpec, largeSpec);
    auto greenOrLargeProducts = productFilter.filter(allProducts, greenOrLarge);
    std::cout << "Green or large products: " << std::endl;
    for (const auto& product : greenOrLargeProducts) {
        product->print();
    }

    system("pause");
}

