// Class representing a journal that holds entries and a title.
class Journal
{
private:
    std::string title_;
    std::vector<std::string> entries_;

public:
    Journal(const std::string &title) : title_(title) {}

    // Adds a new entry to the journal.
    void add(const std::string& entry)
    {
        entries_.emplace_back(entry);
    }

    // Retrieves all entries from the journal.
    std::vector<std::string> getEntries() const { return entries_; }

    // Retrieves the title of the journal.
    std::string getTitle() const { return title_; }
