class PersistenceManager
{
public:
    // Saves the journal entries to the specified filename.
    static void save(const Journal& journal, const std::string& filename)
    {
        std::ofstream file(filename);
        // Write each entry to the file, followed by a newline.
        for (const auto& entry : journal.getEntries())
        {
            file << entry << std::endl;    
        }
    }
};

