// Interface for all song components, including both composite and leaf nodes.
class SongComponent {
public:
    virtual void addSong(const std::weak_ptr<SongComponent>& songComponent) { /* No operation for leaf nodes */ }
    virtual void displaySongInfo() const = 0;
    virtual std::string getName() const = 0;
    virtual ~SongComponent() {}
};

// Represents a group of songs, which can contain other song groups or individual songs.
class SongGroup : public SongComponent {
public:
    explicit SongGroup(const std::string& groupName) : groupName(groupName) {}

    void addSong(const std::weak_ptr<SongComponent>& songComponent) override {
        if (!songComponent.expired()) {
            children.push_back(songComponent);
        }
    }

    void displaySongInfo() const override {
        std::cout << " (";
        std::for_each(children.begin(), children.end(), [](const std::weak_ptr<SongComponent>& songComponent) {
            if (!songComponent.expired()) {
                songComponent.lock()->displaySongInfo();
            }
        });
        std::cout << ") ";
    }

    std::string getName() const override { return groupName; }

    ~SongGroup() {}

private:
    std::vector<std::weak_ptr<SongComponent>> children;
    std::string groupName;
};

// Represents an individual song, which does not contain any children.
class Song : public SongComponent {
public:
    explicit Song(const std::string& name) : songName(name) {}

    void displaySongInfo() const override {
        std::cout << "[" << songName << "]";
    }

    std::string getName() const override { return songName; }

    ~Song() {}

private:
    std::string songName;
};

int main() {
    auto seasonGroup = std::make_shared<SongGroup>("Season");
    auto springGroup = std::make_shared<SongGroup>("Spring");
    auto winterGroup = std::make_shared<SongGroup>("Winter");
    auto song1 = std::make_shared<Song>("Song1");
    auto song2 = std::make_shared<Song>("Song2");
    auto song3 = std::make_shared<Song>("Song3");
    auto song4 = std::make_shared<Song>("Song4");
    auto song5 = std::make_shared<Song>("Song5");

    seasonGroup->addSong(song1);
    seasonGroup->addSong(springGroup);

    springGroup->addSong(song2);
    springGroup->addSong(song3);

    winterGroup->addSong(song4);
    winterGroup->addSong(song5);

    springGroup->addSong(winterGroup);

    std::cout << "Season Group: ";
    seasonGroup->displaySongInfo();
    std::cout << "\n";

    std::cout << "Spring Group: ";
    springGroup->displaySongInfo();
    std::cout << "\n";

    std::cout << "Winter Group: ";
    winterGroup->displaySongInfo();
    std::cout << "\n";

    std::cout << "Song5: ";
    song5->displaySongInfo();
    std::cout << "\n";

    system("pause");
    return 0;
}

#include <iostream>
