template<class ObjType>
void ReaderController::show(const ObjType &object) {
    deepInfo.clear();
    vector<string> temp = object.explicitKey();

    for (const string &key : temp) {
        deepInfo.push_back(key);
        deepInfo.push_back(object[key]);
    }
}

template<class ObjType>
string AdminController::freeze(ObjType obj) {
    ErrorCode err = server->freeze(user, obj);

    switch (err) {
        case objectNotAccessible:
            return "Object cannot be frozen";
        case loginAgain:
            return "You have been disconnected, please log in again";
        case permissionDenied:
            return "You do not have permission to freeze this object";
        case noError:
            return "Successfully frozen";
        default:
            return "Failed to freeze";
    }
}

template<class ObjType>
string AdminController::unfreeze(ObjType obj) {
    ErrorCode err = server->unfreeze(user, obj);

    switch (err) {
        case objectNotAccessible:
            return "Object is not frozen";
        case loginAgain:
            return "You have been disconnected, please log in again";
        case permissionDenied:
            return "You do not have permission to unfreeze this object";
        case noError:
            return "Successfully unfrozen";
        default:
            return "Failed to unfreeze";
    }
}

template<class ObjType>
string RootController::removeObject(ObjType obj) {
    ErrorCode errorCode = server->remove(user, obj);

    switch (errorCode) {
        case loginAgain:
            return "You have been disconnected, please log in again";
        case noError:
            return "Successfully deleted";
        default:
            return "Failed to delete";
    }
}

