class Database {
private:
    string databaseName;
    mongocxx::client mongoClient;
    mongocxx::database mongoDatabase;

    document convertToDocument(const Object &object);
    document convertToDocument(const Search &searchObject);
    document convertToCompleteDocument(const Object &object);
    document convertToCompleteDocument(const User &user);
    document createFindDocument(const Object &object);

public:
    #ifdef TEST
    void displayDatabaseInfo() {
        cout << "Database address = " << this << endl;
        cout << databaseName << endl;
    }
    #endif

    Database(const string& name = "LMS");
    bool doesUserExist(const User& user); 
    bool isUserAdmin(const User& user);
    bool isUserRoot(const User& user);
    bool findObject(Object& object, bool allowFrozen = false); 
    bool doesObjectExist(const Object& object);

    string generateNewRecordId();
    ErrorCode changePassword(const User& user, const Password& newPassword);

    template<typename ObjectType>
    ErrorCode addObject(const ObjectType& object);

    template<typename ObjectType>
    ErrorCode updateObject(const ObjectType& object);

    template<typename ObjectType>
    ErrorCode removeObject(const ObjectType& object);

    template<typename ObjectType>
    ErrorCode searchObjects(const Search& searchKey, vector<ObjectType> &results);
};

template<typename ObjectType>
ErrorCode Database::addObject(const ObjectType &object) {
    auto collection = mongoDatabase[object.typeName()];
    if (collection.find_one(createFindDocument(object).view())) return objectExists;

    document documentToInsert = convertToCompleteDocument(object);
    collection.insert_one(documentToInsert.view());
    return noError;
}

template<typename ObjectType>
ErrorCode Database::updateObject(const ObjectType& object) {
    auto collection = mongoDatabase[object.typeName()];
    document findDocument = createFindDocument(object);
    if (!collection.find_one(findDocument.view())) return objectNotFound;

    document updateDocument;
    updateDocument << "$set" << convertToDocument(object);
    collection.update_one(findDocument.view(), updateDocument.view());
    return noError;
}

template<typename ObjectType>
ErrorCode Database::removeObject(const ObjectType& object) {
    auto collection = mongoDatabase[object.typeName()];
    document findDocument = createFindDocument(object);
    if (!collection.find_one(findDocument.view())) return objectNotFound;

    collection.delete_one(findDocument.view());
    return noError;
}

template<typename ObjectType>
ErrorCode Database::searchObjects(const Search& searchKey, vector<ObjectType> &results) {
    auto collection = mongoDatabase[ObjectType().typeName()];
    document searchDocument = convertToDocument(searchKey);

    auto cursor = collection.find(searchDocument.view());
    results.clear();

    for (auto&& element : cursor) {
        ObjectType object;
        for (int k = 0; k < 2; ++k) {
            for (auto key : (k ? object.explicitKey() : object.implicitKey())) {
                object.update(string(key), string(element[key].get_utf8().value));
            }
        }
        results.push_back(object);
    }

    return noError;
}

