#include <iostream>
#include <string>
#include <vector>
#include <fstream>
using namespace std;

class Person {
    // Overloaded output stream operator for Person class
    friend ostream& operator<<(ostream& os, const Person& individual) {
        os << "Person: " << individual.name << ", bday: " << individual.bday;
        if (individual.spouse == nullptr) {
            os << " single";
        } else {
            os << " married to: " << individual.spouse->name; 
        }
        return os;
    }

    // Function to modify the pointer to a Person object
    friend void modifyPointer(Person& target) {
        Person* ptr = &target;
        ptr->name = "Mathilda";
        const Person* constPtr = &target;
        Person* const constPtr2 = &target;
    }

public:
    // Constructor for Person class
    Person(const string& personName, const Date& birthDate) 
        : name(personName), bday(birthDate), spouse(nullptr) {}

    // Method to marry another Person
    bool marry(Person& partner) {
        if (spouse == nullptr && partner.spouse == nullptr) {
            spouse = &partner;
            partner.spouse = this;
            return true;
        }
        return false;
    }

private:
    string name;
    Date bday;
    Person* spouse; 
};

class Date {
    // Overloaded output stream operator for Date class
    friend ostream& operator<<(ostream& os, const Date& date) {
        os << date.month << '/' << date.day << '/' << date.year;
        return os;
    }

public:
    // Constructor for Date class
    Date(int month, int day, int year) : month(month), day(day), year(year) {}

private:
    int month, day, year;
};

int main() {
    vector<Person*> people; // Vector to store pointers to Person objects
    ifstream file("people.txt"); // Open file containing person data
    string name;
    int month, day, year;

    // First pass to read data incorrectly
    while (file >> name) {
        file >> month >> day >> year;
        Person myPerson(name, Date(month, day, year));
        people.push_back(&myPerson); // This is problematic as myPerson goes out of scope
    }

    people.clear(); // Clear the vector, but does not affect the objects it points to

    // Correct way to read data and allocate memory
    while (file >> name) {
        file >> month >> day >> year;
        Person* newPerson = new Person(name, Date(month, day, year)); // Allocate memory on the heap
        people.push_back(newPerson); // Store the pointer to the new Person object
    }

    // Memory leak demonstration
    new Person("fred", Date(1, 2, 3)); // Object created but not stored, causing a memory leak

    // Clean up allocated memory for Person objects
    for (Person* person : people) {
        delete person; // Release memory allocated on the heap
    }
}

