#ifndef VECTOR_H
#define VECTOR_H
#include <iostream>

namespace CS1124 {

	template <class T>
	class Vector {
		template <class U>
		friend std::ostream& operator<< (std::ostream&, const Vector<U>&);

	public:
		Vector();                          // Default Constructor
		Vector(const Vector&);              // Copy Constructor
		Vector(int size);                   // Constructor with specified size
		~Vector();                          // Destructor

		void resize(int newSize);           // Resize the Vector
		Vector& operator=(const Vector&);   // Assignment operator
		T& operator[](int index);           // Non-const subscript operator
		T operator[](int index) const;      // Const subscript operator

	private:
		int size;                           // Current size of the Vector
		T* data;                            // Pointer to the data array
	};

	template <class T>
	Vector<T>::Vector() : size(4), data(new T[size]) {
	}

	template <class T>
	Vector<T>::Vector(int s) : size(s), data(new T[size]) {
	}

	template <class T>
	Vector<T>::Vector(const Vector& other) {
		size = other.size;
		data = new T[size];
		for (int i = 0; i < size; i++)
			data[i] = other.data[i];
	}

	template <class T>
	Vector<T>::~Vector() {
		delete[] data; // Release allocated memory
	}

	template <class T>
	void Vector<T>::resize(int newSize) {
		if (newSize > size) {
			T* newData = new T[newSize];
			for (int i = 0; i < size; ++i)
				newData[i] = data[i];
			delete[] data; // Free old memory
			data = newData;
			size = newSize;
		}
	}

	template <class T>
	Vector<T>& Vector<T>::operator=(const Vector& right) {
		if (this != &right) { // Prevent self-assignment
			if (size != right.size) {
				delete[] data; // Free old memory if sizes differ
				size = right.size;
				data = new T[size];
			}
			for (int i = 0; i < size; i++)
				data[i] = right.data[i];
		}
		return *this; // Return current object
	}

	template <class T>
	std::ostream& operator<< (std::ostream& os, const Vector<T>& v) {
		for (int i = 0; i < v.size; i++) {
			os << v.data[i];
			if (i < v.size - 1) os << ", "; // Add comma between elements
		}
		return os;
	}

	template <class T>
	T& Vector<T>::operator[](int index) {
		return data[index]; // Return reference for assignment
	}

	template <class T>
	T Vector<T>::operator[](int index) const {
		return data[index]; // Return value for const access
	}
}
#endif

