void DisplayWelcomeMessage() {
    cout << "Welcome To Movie Ticket Booking System" << endl << endl;
    cout << "Menu" << endl;
}

void BookTicket() {
    system("cls");

    // Variables for Booking
    char menuChoice;
    string customerName, customerPhone, selectedSeat, movieId;
    float totalPrice = 0.0;
    bool isValidId = false, exitBooking = false;

    string movieIds[5000];
    int movieIndex = 0;

    DisplayWelcomeMessage();
    queryState = mysql_query(connection, "SELECT * FROM movie_tb");
    if (!queryState) {
        resultSet = mysql_store_result(connection);
        printf("---------------------------------------------------------------------------------------------------\n");
        printf("| %-10s | %-15s | %-7s | %-15s | %-15s | %-10s | %-5s |\n", "Column Id", "Name", "Format", "Show Date", "Show Time", "Price", "Seat");
        while ((rowData = mysql_fetch_row(resultSet))) {
            if (atoi(rowData[7]) > 0) {
                printf("| %-10s | %-15s | %-7s | %-15s | %-15s | %-10s | %-5s |\n", rowData[0], rowData[1], rowData[3], rowData[4], rowData[5], rowData[6], rowData[7]);
                movieIds[movieIndex++] = rowData[0];
            }
        }
        printf("---------------------------------------------------------------------------------------------------\n");
    } else {
        cout << "Query Execution Problem!" << mysql_errno(connection) << endl;
    }

    while (true) {
        cout << "Enter a Movie ID (q to exit): ";
        cin >> movieId;

        if (movieId == "q") {
            exitBooking = true;
            break;
        }

        isValidId = false;
        for (int i = 0; i < movieIndex; i++) {
            if (movieId == movieIds[i]) {
                isValidId = true;
                break;
            }
        }
        if (!isValidId) {
            cout << "Enter a valid number." << endl;
        } else {
            break;
        }
    }

    if (!exitBooking) {
        cout << "Enter Customer Name: "; cin >> customerName;
        cout << "Enter Customer Phone: "; cin >> customerPhone;
        cout << "Book Seat: "; cin >> selectedSeat;

        string movieQuery = "SELECT * FROM movie_tb WHERE m_id = '" + movieId + "'";
        const char* query = movieQuery.c_str();
        queryState = mysql_query(connection, query);

        if (!queryState) {
            resultSet = mysql_store_result(connection);
            printf("--------------------------------------------------------------------\n");
            printf("| %-10s | %-15s | %-15s | %-15s |\n", "Column Id", "Name", "Format", "Price");
            while ((rowData = mysql_fetch_row(resultSet))) {
                if (atoi(rowData[7]) > 0) {
                    printf("| %-10s | %-15s | %-15s | %-15s |\n", rowData[0], rowData[1], rowData[3], rowData[6]);
                    totalPrice = strtof(rowData[6], 0) * strtof(selectedSeat.c_str(), 0);
                }
            }
            printf("--------------------------------------------------------------------\n");
        } else {
            cout << "Query Execution Problem!" << mysql_errno(connection) << endl;
        }

        string updateQuery = "UPDATE movie_tb SET m_seat = m_seat - '" + selectedSeat + "' WHERE m_id = '" + movieId + "'";
        const char* update = updateQuery.c_str();
        queryState = mysql_query(connection, update);

        string insertQuery = "INSERT INTO customer_tb (name, phone, movie, format, seat, price) VALUES ('" + customerName + "','" + customerPhone + "','" + rowData[1] + "', '" + rowData[3] + "', '" + selectedSeat + "', '" + to_string(totalPrice) + "')";
        const char* insert = insertQuery.c_str();
        queryState = mysql_query(connection, insert);

        if (!queryState) {
            cout << endl << "Purchase Successfully Done." << endl;
            cout << endl << "Total Price: " << totalPrice << endl;
        }
    }

    // Exit Code
    cout << endl << "Press 'm' to Menu and any other key to Exit: ";
    cin >> menuChoice;
    if (menuChoice == 'm' || menuChoice == 'M') {
        main();
    } else {
        exit(0);
    }
}

