// Forward declarations
class Route;
class ShortestRoute;

// Leg class representing a segment of the route
class Leg {
    friend ostream& operator<<(ostream&, const Leg&);
    friend ostream& operator<<(ostream&, const Route&);
    friend class Route;
    friend class ShortestRoute;

public:
    Leg(const string startCity, const string endCity, const double legDistance);

    // Prevent assignment
    void operator=(const Leg&) {
        assert(false);
    }

private:
    const string cityStart;
    const string cityEnd;
    const double distance;
};

// Constructor for Leg class
Leg::Leg(const string startCity, const string endCity, const double legDistance) 
    : cityStart(startCity), cityEnd(endCity), distance(legDistance) {}

// Route class representing a collection of legs between cities
class Route {
    friend ostream& operator<<(ostream&, const Route&);
    friend class ShortestRoute;

public:
    Route(const Leg& initialLeg);
    Route(const Route& existingRoute, const Leg& additionalLeg);
    Route(const Route& routeToCopy);
    ~Route();

    double getDistance() const;
    bool isGreaterThan(const Route&) const;

    // Prevent assignment
    void operator=(const Route&) {
        assert(false);
    }

private:
    const int legCount;
    const Leg** const legs; // dynamically-sized array of Leg pointers
};

// Constructor for a single-leg route
Route::Route(const Leg& initialLeg) 
    : legCount(1), legs(new const Leg*[1]) {
    legs[0] = &initialLeg;
}

// Constructor for a multi-leg route
Route::Route(const Route& existingRoute, const Leg& additionalLeg) 
    : legCount(existingRoute.legCount + 1), legs(new const Leg*[legCount]) {
    for (int i = 0; i < legCount - 1; i++) {
        legs[i] = existingRoute.legs[i];
    }
    legs[legCount - 1] = &additionalLeg;

    if (legs[legCount - 2]->cityEnd != legs[legCount - 1]->cityStart) {
        delete[] legs;
        throw "End City of Route does not match Start City of Leg.";
    }
}

// Copy constructor for Route
Route::Route(const Route& routeToCopy) 
    : legCount(routeToCopy.legCount), legs(new const Leg*[legCount]) {
    for (int i = 0; i < legCount; i++) {
        legs[i] = routeToCopy.legs[i];
    }
}

// Destructor for Route
Route::~Route() {
    delete[] legs;
}

// Calculate total distance of the route
double Route::getDistance() const {
    double totalDistance = 0;
    for (int i = 0; i < legCount; i++) {
        totalDistance += legs[i]->distance;
    }
    return totalDistance;
}

// Compare distances of two routes
bool Route::isGreaterThan(const Route& otherRoute) const {
    return this->getDistance() > otherRoute.getDistance();
}

// ShortestRoute class to manage routes and legs
class ShortestRoute {
public:
    static vector<Leg> legs; // Collection of leg objects
    static const Route getAnyRoute(const string from, const string to);
    static const Route getShortestRoute(const string from, const string to);

    ShortestRoute(); // Default constructor

    // Prevent assignment
    void operator=(const ShortestRoute&) {
        assert(false);
    }
};

// Definition of static member
vector<Leg> ShortestRoute::legs;

// Retrieve any route from the collection
const Route ShortestRoute::getAnyRoute(const string from, const string to) {
    for (const auto& leg : ShortestRoute::legs) {
        if (leg.cityEnd == to) {
            if (leg.cityStart == from) {
                return Route(leg);
            } else {
                return Route(getAnyRoute(from, leg.cityStart), leg);
            }
        }
    }
    throw "No route possible from the given vector of ShortestRoute::legs.";
}

// Retrieve the shortest route from the collection
const Route ShortestRoute::getShortestRoute(const string from, const string to) {
    static vector<Route> potentialRoutes;
    static const Route* shortestRoute;

    for (const auto& leg : ShortestRoute::legs) {
        try {
            if (leg.cityEnd == to) {
                if (leg.cityStart == from) {
                    potentialRoutes.push_back(Route(leg));
                } else {
                    potentialRoutes.push_back(Route(getShortestRoute(from, leg.cityStart), leg));
                }
            }
        } catch (const char* ex) {
            continue;
        }
    }

    // Determine the shortest route from potential routes
    int lastIndex = potentialRoutes.size() - 1;
    shortestRoute = &potentialRoutes[lastIndex];

    for (const auto& route : potentialRoutes) {
        if (route.legs[0]->cityStart == from) {
            if (route.legs[route.legCount - 1]->cityEnd == to) {
                if (shortestRoute->isGreaterThan(route)) {
                    shortestRoute = &route;
                }
            }
        }
    }

    return *shortestRoute;
}

// Overloaded output operator for Leg
ostream& operator<<(ostream& out, const Leg& leg) {
    out << leg.cityStart << " to " << leg.cityEnd << ", " << leg.distance << " miles." << endl;
    return out;
}

// Overloaded output operator for Route
ostream& operator<<(ostream& out, const Route& route) {
    out << route.legs[0]->cityStart;
    for (int i = 0; i < route.legCount; i++) {
        out << " to " << route.legs[i]->cityEnd;
    }
    out << "; Distance = " << route.getDistance() << " miles." << endl;
    return out;
}

