class Elevator
{
  // Class constants for elevator states
  static int elevatorID; // Unique ID for each elevator
  static const int IDLE = 0; // Elevator is not moving
  static const int UP = 1; // Elevator is moving up
  static const int DOWN = -1; // Elevator is moving down

  // Private member variables
  const int ID; // Unique identifier for the elevator
  const int capacity; // Maximum number of riders
  const int speed; // Speed of the elevator in inches per second
  const Floor* destinationFloor; // Pointer to the destination floor
  int currentLocation; // Current height of the elevator in inches above ground
  int movementDirection; // Current movement direction (IDLE, UP, DOWN)
  bool isDoorOpen; // Indicates if the elevator door is open
  vector<Rider> riders; // List of riders currently in the elevator

public:
  Elevator(const int capacity, const int speed, const Floor& startingFloor); // Constructor

  // Inline functions for state checks and door operations
  bool isDoorOpen() const { return isDoorOpen; }
  bool isIdle() const { return movementDirection == IDLE; }
  bool isMovingUp() const { return movementDirection == UP; }
  bool isMovingDown() const { return movementDirection == DOWN; }
  void closeDoor() { isDoorOpen = false; }
  void openDoor() { isDoorOpen = true; }
  void setIdle() { movementDirection = IDLE; }
  void setDirectionUp() { movementDirection = UP; }
  void setDirectionDown() { movementDirection = DOWN; }
  void moveUp() { currentLocation += speed; }
  void moveDown() { currentLocation -= speed; }
  void setDestination(const Floor* floor) { destinationFloor = floor; }
  const Floor& getDestination() const { return *destinationFloor; }
  int getLocation() const { return currentLocation; }
  bool hasADestination() const { return destinationFloor != nullptr; }
  bool hasRiders() const { return !riders.empty(); }
  int getRiderCount() const { return riders.size(); }
  int getCapacity() const { return capacity; }
  int getAvailableSpace() const { return capacity - riders.size(); }

  // Non-inline functions for movement and rider management
  bool isNearDestination() const; // Check if close to destination
  void moveToDestinationFloor(); // Move elevator to the destination floor
  vector<Rider> removeRidersForDestinationFloor(); // Remove riders who have reached their destination
  void addRiders(const vector<Rider>& newRiders); // Add riders to the elevator
  void setDestinationBasedOnRiders(); // Set destination based on riders' destinations

  // Friend function for output
  friend ostream& operator<<(ostream&, const Elevator&);
};

