using namespace std;

class Vehicle
{
protected:
    string brand;
    long long price;
    int manufacturingYear;

public:
    Vehicle()
    {
        brand = "Null";
        price = 0;
        manufacturingYear = 0;
    }

    Vehicle(string b, long long p, int year)
    {
        brand = b;
        price = p;
        manufacturingYear = year;
    }
};

class Car : private Vehicle
{
private:
    int seatingCapacity;
    int payloadCapacity;

public:
    Car()
    {
        seatingCapacity = 0;
        payloadCapacity = 0;
    }

    Car(string b, long long p, int year, int seats, int payload) : Vehicle(b, p, year)
    {
        seatingCapacity = seats;
        payloadCapacity = payload;
    }

    // Collects input data for the car
    void input()
    {
        cout << "Enter car brand: ";
        cin.ignore();
        getline(cin, brand);
        cout << "Enter price: ";
        cin >> price;
        cout << "Enter manufacturing year: ";
        cin >> manufacturingYear;
        cout << "Enter seating capacity: ";
        cin >> seatingCapacity;
        cout << "Enter payload capacity: ";
        cin >> payloadCapacity;
    }

    // Displays car information
    void output()
    {
        cout << setw(10) << brand << setw(15) << price << setw(15) << manufacturingYear 
             << setw(15) << seatingCapacity << setw(15) << payloadCapacity << endl;
    }
};

int main(int argc, char const *argv[])
{
    Car cars[20];
    int numberOfCars;

    cout << "Enter number of cars: ";
    do
    {
        cin >> numberOfCars;
        if (numberOfCars <= 0 || numberOfCars > 20)
            cout << endl << "Please enter again! ";
    } while (numberOfCars <= 0 || numberOfCars > 20);

    cout << "-------------------------------------------------------" << endl;

    // Input car details for each car
    for (int i = 0; i < numberOfCars; ++i)
    {
        cout << endl << "Enter details for car " << i + 1 << ":" << endl;
        cars[i].input();
    }

    cout << endl;
    cout << setw(10) << "Brand" << setw(15) << "Price" << setw(15) << "Year" 
         << setw(15) << "Seats" << setw(15) << "Payload" << endl;

    // Output car details for each car
    for (int i = 0; i < numberOfCars; ++i)
    {
        cars[i].output();
    }

    system("PAUSE");
    return 0;
}

