class Employee {
protected:
    char name[50], gender[5], address[100];
    DateOfBirth dob;

public:
    Employee() {
        strcpy(name, "Null");
        strcpy(gender, "Null");
        strcpy(address, "Null");
    }

    friend class DateOfBirth;
};

class CivilServant : private Employee {
protected:
    char profession[20], educationLevel[50];
    int yearOfJoining;
    float salaryCoefficient, allowance;

public:
    CivilServant() {
        strcpy(profession, "Null");
        strcpy(educationLevel, "Null");
        yearOfJoining = 0;
        salaryCoefficient = allowance = 1;
    }

    void Input() {
        cout << "Enter name: ";
        fflush(stdin);
        gets(name);
        cout << "Enter gender: ";
        gets(gender);
        cout << "Enter date of birth (dd/mm/yyyy): ";
        dob.InputDate();
        cout << "Enter address: ";
        fflush(stdin);
        gets(address);
        cout << "Enter profession: ";
        gets(profession);
        cout << "Enter education level (DH, CD, TC): ";
        gets(educationLevel);
        cout << "Enter year of joining: ";
        cin >> yearOfJoining;
        cout << "Enter salary coefficient: ";
        cin >> salaryCoefficient;
        cout << "Enter allowance amount: ";
        cin >> allowance;
    }

    void Output() {
        cout << setw(20) << name << setw(10) << gender;
        dob.OutputDate();
        cout << setw(20) << address << setw(20) << profession << setw(10) << educationLevel
             << setw(10) << yearOfJoining << setw(10) << setprecision(2) << salaryCoefficient
             << setw(10) << fixed << allowance << setw(10) << CalculateIncome() << endl;
    }

    double CalculateIncome() {
        return salaryCoefficient * 830 + allowance;
    }
};

void FindMinIncome(CivilServant employees[], int count) {
    double minIncome = employees[0].CalculateIncome();
    int index = 0;

    for (int i = 0; i < count; ++i) {
        if (minIncome > employees[i].CalculateIncome()) {
            minIncome = employees[i].CalculateIncome();
            index = i;
        }
    }

    cout << endl << "Information of the employee with the lowest income: " << endl;
    cout << setw(20) << "Name" << setw(10) << "Gender" << setw(20) << "DOB";
    cout << setw(20) << "Address" << setw(20) << "Profession" << setw(10) << "Education Level"
         << setw(10) << "Year of Joining" << setw(10) << "Salary Coefficient" << setw(10) << "Allowance"
         << setw(10) << "Income" << endl;
    employees[index].Output();
}

void BubbleSort(CivilServant employees[], int count) {
    for (int i = 0; i < count - 1; ++i) {
        for (int j = count - 1; j > i; --j) {
            if (employees[j].CalculateIncome() > employees[j - 1].CalculateIncome()) {
                swap(employees[j], employees[j - 1]);
            }
        }
    }
}

int main(int argc, char const *argv[]) {
    CivilServant employees[50];
    int count;

    cout << "Enter number of civil servants: ";
    do {
        cin >> count;
        if (count <= 0 || count > 50)
            cout << endl << "Please enter again!";
    } while (count <= 0 || count > 50);

    for (int i = 0; i < count; ++i) {
        cout << endl << "Enter information for employee " << i + 1 << ":" << endl;
        employees[i].Input();
    }

    FindMinIncome(employees, count);
    BubbleSort(employees, count);

    cout << endl << endl << "List of civil servants: " << endl;
    cout << setw(20) << "Name" << setw(10) << "Gender" << setw(20) << "DOB";
    cout << setw(20) << "Address" << setw(20) << "Profession" << setw(10) << "Education Level"
         << setw(10) << "Year of Joining" << setw(10) << "Salary Coefficient" << setw(10) << "Allowance"
         << setw(10) << "Income" << endl;

    for (int i = 0; i < count; ++i) {
        employees[i].Output();
    }

    system("PAUSE");
    return 0;
}

