// Extracts the last name from the full name
void extractLastName(const char fullName[], char lastName[]) {
    for (int i = strlen(fullName) - 1; i >= 0; i--) {
        if (fullName[i] == ' ') {
            strcpy(lastName, fullName + 1 + i);
            break;
        }
    }
}

// Sorts the employee list based on last name and full name
void sortEmployees(Employee employeeList[], int employeeCount) {
    for (int i = 0; i < employeeCount; i++) {
        for (int j = i + 1; j < employeeCount; j++) {
            char lastName1[255] = "", lastName2[255] = "";
            extractLastName(employeeList[i].fullName, lastName1);
            extractLastName(employeeList[j].fullName, lastName2);
            int comparisonResult = strcmp(lastName1, lastName2);
            if (comparisonResult > 0) {
                swap(employeeList[i], employeeList[j]);
            } else if (comparisonResult == 0) {
                int fullNameComparison = strcmp(employeeList[i].fullName, employeeList[j].fullName);
                if (fullNameComparison > 0) {
                    swap(employeeList[i], employeeList[j]);
                }
            }
        }
    }
}

int main(int argc, char const *argv[]) {
    Employee *employeeList;
    int employeeCount;
    cout << "========= Quan Ly Nhan Su =========" << endl;
    cout << " - Nhap so luong nhan su: ";
    cin >> employeeCount;

    employeeList = new Employee[employeeCount];

    cout << "==== Nhap Thong Tin " << employeeCount << " Nhan Su ===" << endl;
    for (int i = 0; i < employeeCount; ++i) {
        cout << " * Thong tin nhan su " << i + 1 << endl;
        employeeList[i].input();
    }

    // Sort the employee list
    sortEmployees(employeeList, employeeCount);

    cout << endl;
