#include <bits/stdc++.h>

using namespace std;

class Polynomial
{
    int degree;
    int *coefficients;

public:
    Polynomial() : degree(0), coefficients(nullptr) {}

    Polynomial(int degree) : degree(degree)
    {
        coefficients = new int[degree + 1]();
    }

    Polynomial(int degree, int coeffs[])
    {
        this->degree = degree;
        coefficients = new int[degree + 1]();
        for (int i = 0; i <= degree; ++i)
        {
            coefficients[i] = coeffs[i];
        }
    }

    Polynomial operator+(const Polynomial& other);
    Polynomial operator-(const Polynomial& other);
    Polynomial operator*(const Polynomial& other);
    Polynomial operator/(const Polynomial& divisor);

    friend ostream& operator<<(ostream& out, const Polynomial& poly);
};

Polynomial Polynomial::operator+(const Polynomial& other)
{
    Polynomial result;
    if (degree > other.degree)
    {
        result.degree = degree;
        result.coefficients = new int[degree + 1]();
        for (int i = 0; i <= other.degree; ++i)
            result.coefficients[i] = coefficients[i] + other.coefficients[i];
        for (int i = other.degree + 1; i <= degree; ++i)
            result.coefficients[i] = coefficients[i];
    }
    else
    {
        result.degree = other.degree;
        result.coefficients = new int[other.degree + 1]();
        for (int i = 0; i <= degree; ++i)
            result.coefficients[i] = coefficients[i] + other.coefficients[i];
        for (int i = degree + 1; i <= other.degree; ++i)
            result.coefficients[i] = other.coefficients[i];
    }
    return result;
}

Polynomial Polynomial::operator-(const Polynomial& other)
{
    Polynomial result;
    if (degree > other.degree)
    {
        result.degree = degree;
        result.coefficients = new int[degree + 1]();
        for (int i = 0; i <= other.degree; ++i)
            result.coefficients[i] = coefficients[i] - other.coefficients[i];
        for (int i = other.degree + 1; i <= degree; ++i)
            result.coefficients[i] = coefficients[i];
    }
    else
    {
        result.degree = other.degree;
        result.coefficients = new int[other.degree + 1]();
        for (int i = 0; i <= degree; ++i)
            result.coefficients[i] = coefficients[i] - other.coefficients[i];
        for (int i = degree + 1; i <= other.degree; ++i)
            result.coefficients[i] = -other.coefficients[i];
    }
    return result;
}

Polynomial Polynomial::operator*(const Polynomial& other)
{
    int *tempCoeffs = new int[degree + other.degree + 1]();
    Polynomial result(degree + other.degree, tempCoeffs);

    for (int i1 = 0; i1 <= result.degree; i1++)
    {
        for (int i = 0; i <= degree; i++)
        {
            for (int j = 0; j <= other.degree; j++)
            {
                if (i + j == i1)
                {
                    result.coefficients[i1] += coefficients[i] * other.coefficients[j];
                }
            }
        }
    }
    return result;
}

Polynomial Polynomial::operator/(const Polynomial& divisor)
{
    if (degree < divisor.degree)
        return Polynomial(); // Return a zero polynomial

    int tempDegree = degree - divisor.degree;
    Polynomial quotient(tempDegree);
    Polynomial tempPoly(degree, coefficients);

    for (int i = degree; i >= divisor.degree; i--, tempDegree--)
    {
        quotient.coefficients[i - divisor.degree] = tempPoly.coefficients[i] / divisor.coefficients[divisor.degree];
        if (i - 1 >= divisor.degree)
        {
            for (int j = i - 1, k = divisor.degree - 1; k >= 0; j--, k--)
                tempPoly.coefficients[j] -= quotient.coefficients[i - divisor.degree] * divisor.coefficients[k];
        }
    }
    return quotient;
}

ostream& operator<<(ostream& out, const Polynomial& poly)
{
    if (poly.degree == 1)
    {
        if (poly.coefficients[0] != 0)
            out << poly.coefficients[0] << " + ";
        if (poly.coefficients[1] != 0)
        {
            if (poly.coefficients[1] == 1)
                out << "x ";
            else
                out << poly.coefficients[1] << "*x ";
        }
    }
    else
    {
        if (poly.coefficients[0] != 0)
            out << poly.coefficients[0] << " + ";
        if (poly.coefficients[1] != 0)
        {
            if (poly.coefficients[1] == 1)
                out << "x + ";
            else
                out << poly.coefficients[1] << "*x + ";
        }

        for (int i = 2; i < poly.degree; ++i)
        {
            if (poly.coefficients[i] != 0)
            {
                if (poly.coefficients[i] == 1)
                    out << "x^" << i << " + ";
                else
                    out << poly.coefficients[i] << "*x^" << i << " + ";
            }
        }

        if (poly.coefficients[poly.degree] == 1)
            out << "x^" << poly.degree;
        else if (poly.coefficients[poly.degree] == 0)
            out << "0";
        else
            out << poly.coefficients[poly.degree] << "*x^" << poly.degree;
    }
    return out;
}

