#include <iostream>

using namespace std;

class Vector {
private:
    int dimension;
    float *elements;

public:
    // Default constructor initializes an empty vector
    Vector() : dimension(0), elements(nullptr) {}

    // Constructor that initializes a vector with a specified dimension
    Vector(int dimension) : dimension(dimension) {
        elements = new float[dimension];
    }

    // Constructor that initializes a vector with a specified dimension and array of elements
    Vector(int dimension, float array[]) : dimension(dimension) {
        elements = new float[dimension];
        for (int i = 0; i < dimension; ++i) {
            elements[i] = array[i];
        }
    }

    // Returns the maximum value in the vector
    float maxValue() {
        float maxElement = elements[0];
        for (int i = 1; i < dimension; ++i) {
            if (maxElement < elements[i]) {
                maxElement = elements[i];
            }
        }
        return maxElement;
    }

    // Returns the minimum value in the vector
    float minValue() {
        float minElement = elements[0];
        for (int i = 1; i < dimension; ++i) {
            if (minElement > elements[i]) {
                minElement = elements[i];
            }
        }
        return minElement;
    }

    // Destructor to free allocated memory
    ~Vector() {
        dimension = 0;
        delete[] elements;
    }

    friend ostream& operator<<(ostream& out, const Vector& vector);
    friend istream& operator>>(istream& in, Vector& vector);
};

// Overloaded input operator to read vector data
istream& operator>>(istream& in, Vector& vector) {
    cout << "- Nhap chieu cua vector? ";
    in >> vector.dimension;
    vector.elements = new float[vector.dimension];
    cout << "- Nhap thanh phan cua vector? (VD vector 2 chieu (2,3) nhap 2 3) ";
    for (int i = 0; i < vector.dimension; ++i) {
        in >> vector.elements[i];
    }
    return in;
}

// Overloaded output operator to display vector data
ostream& operator<<(ostream& out, const Vector& vector) {
    out << "(";
    for (int i = 0; i < vector.dimension; ++i) {
        out << vector.elements[i];
        if (i < vector.dimension - 1) {
            out << ",";
        }
    }
    out << ")";
    return out;
}

int main(int argc, char const *argv[]) {
    float sampleArray[10] = {5, 4, 3, 2, 1, -1, -2, -3, -4, -5};
    Vector vectorX(10, sampleArray);

    cout << "max[sampleArray] = " << vectorX.maxValue() << endl;
    cout << "min[sampleArray] = " << vectorX.minValue() << endl;
    cout << "- Thong tin mang khoi tao X: " << vectorX;

    Vector vectorC;
    cout << "-- Nhap du lieu cho vector --" << endl;
    cin >> vectorC;

    cout << "- Gia tri nho nhat cua vector: " << vectorC.minValue() << endl;
    cout << "- Gia tri lon nhat cua vector: " << vectorC.maxValue() << endl;
    cout << "- Thong tin mang nhap C: " << vectorC;

    return 0;
}

