#include <iostream>

using namespace std;

class Complex {
    float realPart, imaginaryPart;

public:
    Complex() : realPart(0), imaginaryPart(0) {}

    Complex(float real, float imaginary) : realPart(real), imaginaryPart(imaginary) {}

    Complex operator+(const Complex& other) {
        Complex result;
        result.realPart = this->realPart + other.realPart;
        result.imaginaryPart = this->imaginaryPart + other.imaginaryPart;
        return result;
    }

    friend ostream& operator<<(ostream& out, const Complex& complexNumber);
    friend istream& operator>>(istream& in, Complex& complexNumber);
};

istream& operator>>(istream& in, Complex& complexNumber) {
    in >> complexNumber.realPart >> complexNumber.imaginaryPart;
    return in;
}

ostream& operator<<(ostream& out, const Complex& complexNumber) {
    out << complexNumber.realPart << " + " << complexNumber.imaginaryPart << "i";
    return out;
}

int main(int argc, char const *argv[]) {
    Complex* complexNumbers;
    int count;

    cout << "## Nhap n ? ";
    do {
        cin >> count;
    } while (count < 1);

    complexNumbers = new Complex[count];

    for (int i = 0; i < count; ++i) {
        cout << "# Nhap so phuc thu " << i + 1 << "? (VD: a+bi thi nhap a b) ";
        cin >> complexNumbers[i];
    }

    // Tính tổng các số phức
    Complex totalSum;
    for (int i = 0; i < count; ++i) {
        totalSum = totalSum + complexNumbers[i];
        cout << "(" << complexNumbers[i] << ")";
        if (i < count - 1) {
            cout << " + ";
        }
    }
    cout << " = " << totalSum << endl;

    delete[] complexNumbers; // Giải phóng bộ nhớ đã cấp phát
    return 0;
}

