using namespace std;

class Date {
protected:
    int day, month, year;

public:
    Date() : day(0), month(0), year(0) {}

    Date(int d, int m, int y) : day(d), month(m), year(y) {}

    void input() {
        cout << " - Nhap ngay sinh? (dd/mm/yyyy) ";
        scanf("%d/%d/%d", &day, &month, &year);
        fflush(stdin);
    }

    void output() const {
        cout << setw(7) << right << day << "/" << setw(2) << month << "/" << setw(4) << year;
    }
};

class Person : private Date {
private:
    char idCard[15], fullName[50], birthplace[20];

public:
    Person() {
        idCard[0] = fullName[0] = birthplace[0] = '\0';
    }

    Person(const char id[15], const char name[50], const char birthPlace[20]) {
        strcpy(this->idCard, id);
        strcpy(this->fullName, name);
        strcpy(this->birthplace, birthPlace);
    }

    Person(const char id[15], const char name[50], const char birthPlace[20], int d, int m, int y) : Date(d, m, y) {
        strcpy(this->idCard, id);
        strcpy(this->fullName, name);
        strcpy(this->birthplace, birthPlace);
    }

    void input() {
        cout << " - Nhap ho ten: ";
        gets(fullName);
        cout << " - Nhap chung minh thu: ";
        gets(idCard);
        cout << " - Nhap noi sinh: ";
        gets(birthplace);
        Date::input();
    }

    void output() const {
        cout << setw(30) << left << fullName;
        cout << setw(20) << idCard;
        cout << setw(20) << birthplace;
        Date::output();
        cout << setw(10) << age();
        cout << endl;
    }

    int age() const {
        time_t currentTime = time(NULL);
        struct tm *localTime = localtime(&currentTime);
        int currentYear = localTime->tm_year + 1900;
        return currentYear - year;
    }

    void operator=(const Person& other) {
        strcpy(this->idCard, other.idCard);
        strcpy(this->fullName, other.fullName);
        strcpy(this->birthplace, other.birthplace);
        this->day = other.day;
        this->month = other.month;
        this->year = other.year;
    }
};

void printTitle() {
    cout << setw(30) << left << "Ho ten";
    cout << setw(20) << "CMT";
    cout << setw(20) << "Noi sinh";
    cout << setw(15) << right << "Ngay";
    cout << setw(10) << "Tuoi";
    cout << endl;
}

void inputPersons(Person *list, int &count) {
    cout << "\n============= NHAP VAO DS " << count << " NGUOI =============\n";
    for (int i = 0; i < count; ++i) {
        cout << "# Nhap thong tin nguoi thu " << i + 1 << endl;
        list[i].input();
    }
}

void outputPersons(const Person *list, int count) {
    cout << "\n============= DANH SACH " << count << " NGUOI =============\n";
    printTitle();
    for (int i = 0; i < count; ++i) {
        list[i].output();
    }
}

void sortByAge(Person *list, int count) {
    for (int i = 1; i < count; ++i) {
        for (int j = 0; j < count - i; ++j) {
            if (list[j].age() < list[j + 1].age()) {
                Person temp = list[j];
                list[j] = list[j + 1];
                list[j + 1] = temp;
            }
        }
    }
    outputPersons(list, count);
}

int main() {
    int count;
    Person *list;

    cout << "# Nhap so k? ";
    do {
        cin >> count;
    } while (count < 1);
    fflush(stdin);

    list = new Person[count];
    inputPersons(list, count);
    outputPersons(list, count);
    sortByAge(list, count);

    delete[] list; // Clean up dynamically allocated memory
    return 0;
}

