const float PI = 3.14;



class circle

{

    public:

        float radius;

        float perimeter()

        {

            return (2*PI*radius);

        }

        float area()

        {

            return (PI*radius*radius);

        }

};



class rectangle

{

    public:

        float length,breadth;

        float perimeter()

        {

            float x=(length+breadth)*2;

            return (x);

        }

        float area()

        {

            return (length*breadth);

        }

};



class triangle

{

    public:

        float side1,side2,side3;

        float perimeter()

        {

            return (side1+side2+side3);

        }

        float area()

        {

            float s=(side1+side2+side3)/2;

            return (sqrt(s*(s-side1)*(s-side2)*(s-side3)));

        }

};

