     }
     delPtr = currPtr;
     //the next two lines basically patch the hole in the list
     currPtr = currPtr->link; 
     tempPtr->link = currPtr;

     delete delPtr; //remove this node from the list

     cout << "  Your account was successfully deleted.";
}

