    dayOfYear days[12]={{9,6},{11,12},{12,12},{2,4},{7,4},{3,5},{1,3},{9,6},{1,3},{21,8},{9,6},{20,9}};

    people array_people[7];

//Object arrayi olustururken arraydeki object degerleri default constructor a gore belirlendigi icin
