void asset::warrantyexpired() {

  time_t t = time(NULL);

  struct tm d = *localtime(&t);

  int m,day,y,n;

  day=d.tm_mday;

  m=d.tm_mon;

  y=d.tm_year;

  ifstream fin;

  fin.open("c:\\ams.dat");

  n=recordcount();

  if(n==0)

    {

      cout<<"\n FILE IS EMPTY ! ";

      getch();

    }

  for(int i=0;i<n;i++)

    {

      fin.read((char*)&obj,sizeof(obj));

      if(yy<y)

	    obj.display();

      else if(yy==y)

        {

          if(mm<m)

            obj.display();

          else if(mm==m)

	        {

              if(dd<day)

                obj.display();

            }

        }

    }

  fin.close();

}



void asset::warrantynearing()

{

  time_t t = time(NULL);

  struct tm d = *localtime(&t);

  int m,day,y,n;

  day=d.tm_mday;

  m=d.tm_mon;

  y=d.tm_year;

  ifstream fin;

  fin.open("c:\\ams.dat");

  n=recordcount();

  if(n==0)

    {

      cout<<"\n FILE IS EMPTY ! ";

      getch();



    }

  for(int i=0;i<n;i++)

    {

      fin.read((char*)&obj,sizeof(obj));

      if(yy>y)

        obj.display();

      else if(yy==y)

        {

          if(mm>m)

	        obj.display();

          else if(mm==m)

            {

	          if(dd>=day)

                obj.display();

            }

        }

    }

  fin.close();

}



