// WAP with class template to represent array and add member functions to find minimum, maximum and sort the generic array.

#include<iostream>
using namespace std;

const int SIZE = 5;

template <class t>
class array{
	t a[SIZE];
	public:
	void input(){
		for(int i=0;i<SIZE;i++) {
			cout << "Element " << i+1 << ": ";
			cin>>a[i];
			}
	}
	void sort(){
	t m=a[0];
		for(int i=0;i<SIZE;i++){
		for(int j=0;j<SIZE;j++){
			if (a[i]<a[j]){
				m=a[i];
				a[i]=a[j];
				a[j]=m;
			}
		}
		}

	}

	t minimum(){
		return a[0];
	}
	t maximum(){
		return a[4];
	}
};

int main(){
	array<int> x ;
	cout << "Enter the elements of array:" << endl;
	x.input();
	x.sort();
	cout<<"Min = "<<x.minimum() << endl;
	cout<<"Max = "<<x.maximum() << endl;
	array<float> y ;
	y.input();
	y.sort();
	cout<<"Min = "<<y.minimum() << endl;
	cout<<"Max = "<<y.maximum() << endl;

}

// Create a class template with necessary member variables to represent vectors.
// Write initialization mechanism and overload * operator to find the scalar product of the two vectors.
// Also write a member function to display the vector.
// Use above template and write main funciton to perform scalar product of vectors of type int and double.

#include<iostream>
using namespace std;

const int size=3;

template<class T>
class vect
{
    T* v;
public:
    vect()
    {
        v = new T[size];
        for(int i=0;i<size;i++)
        {
            v[i]=0;
        }
    }
    vect(T* a)
    {
        v = new T[size];
        for(int i=0;i<size;i++)
        {
            v[i]=a[i];
        }
    }
    T operator*(vect &y)
    {
        T sum = 0;
        for(int i=0;i<size;i++)
        {
            sum += v[i]*y.v[i];
        }
        return sum;
    }
};
int main()
{
    int x[3]={1,2,3};
    int y[3]={2,3,4};
    vect <int>v1(x);
    vect <int>v2(y);
    int product = v1*v2;
    cout<< "Product = "<<product<<endl;
    double p[3]={1.8,2.6,3.4};
    double q[3]={2.8,3.2,4.7};
    vect <double>v3(p);
    vect <double>v4(q);
    double product2 = v3*v4;
    cout<< "Product = "<<product2<<endl;
    return 0;
}

// Define a class to represent time. It should have memvber function to read and display the time.
// The function to read time should raise an exception if the user enter invalid values for hour, minutes and seconds.
// The exception thrown should contain an argument.
// The exception thrown should be thandled outside of the member functions of the class


#include<iostream>
using namespace std;

class Clock {
	int hour,min,sec;
	public:
	void input(){
			cout<<"Hour: ";cin>>hour;
			if(hour>24||hour<0)
				throw Exception('H');
			cout<<"Min: ";cin>>min;
			if(min>60 or min<0){
				throw Exception('M');
			}
			cout<<"Sec: ";cin>>sec;
			if(sec>60 or sec<0){
				throw Exception('S');
			}
	}
	void display(){
		cout<<"Time: " << hour<<" : "<<min<<" : "<<sec;
	}
	class Exception {
        public:
            char message;
            Exception(char m): message(m) {}
	};
};

int main() {
	Clock t;
	try {
        t.input();
        t.display();
    }
	catch (Clock::Exception err){
		switch(err.message) {
            case 'H': cout << "Hour can't be greater than 24." << endl;
                      break;
            case 'M': cout << "Minute can't be greater than 60." << endl;
                      break;
            case 'S': cout << "Second can't be greater than 60." << endl;
                      break;
		}
	}
    return 0;
}

