	*p.s = 1000;

	cout<<endl;

	cout<<"Address of pointer variable of both objects: "<<p.s<< " "<<p1.s<<endl; //object p1 also points to the same location of pointer member p

	p1.getdet();
	cout<<endl;
	p.getdet(); //changes only reflected in object p's copy of pointer var s;
