// sum at k level 
int ksum(Node* root, int k)
{
    if(root == NULL){
        return -1;
    }

    queue<Node*> q;
    q.push(root);
    q.push(NULL);
    int sum = 0;
    int level = 0;

    while(!q.empty())
    {
        Node* node = q.front();
        q.pop();

        if(node != NULL){

            if(level == k){
                sum+=node->data;
            }
            // if there is element in left then push to queue
            if(node->left){
                q.push(node->left);
            }
              // if there is element in right then push to queue
            if(node->right){
                q.push(node->right);
            }
        }

//after evrery level we are adding NULL to queue
        else if(!q.empty())
        {
            q.push(NULL);
            level++;
        }
    }
    return sum;

}

