using namespace std;

class Node
{
	public:

		int key;
		int data;
		Node *next;

		Node()
		{
			key=0;
			data=0;
			next=NULL;
		}

		Node(int k, int d)
		{
			int key=k;
			int data=d;
		}
};

class sll
{
	public:
		Node *head;

		sll()
		{
			head=NULL;
		}
		sll(Node *n)
		{
			head=n;
		}

		Node* nexist(int k) //k= key value
		{
			Node *temp=NULL;
			Node *ptr=head;

			while(ptr!=NULL)
			{
				if(ptr->key==k)
				{
					temp=ptr;
				}
				ptr=ptr->next;
			}
			return temp;
		}

		Node *appendnode(Node *n) //n= new node 
		{
			if(nexist(n->key)!=NULL)
			{
				cout<<"Entered node exist "<<n->key<<endl;
			}
			else
			{
				if(head==NULL) //assuming that node is empty
				{
					head=n;
					cout<<"Node appended"<<endl;
				}
				else  //assuming that node stores some data
				{
					Node *ptr=head;
					while(ptr->next!=NULL)
					{
						ptr=ptr->next;
					}
					ptr->next=n;
					cout<<"Node appended "<<endl;
				}
			}
		}

		void prependnode(Node *n)
		{
			if(nexist(n->key)!=NULL)
			{
				cout<<"Node already exist = "<<n->key<<endl;
			}
			else
			{
				n->next=head;
				head=n;
				cout<<"Node prepended "<<endl;
			}
		}

		void insertnode(int k,Node *n) 
		{
			Node *ptr=nexist(k);
			if(ptr==NULL) //checking wether the entered key node exist or not
			{
				cout<<"No node exist with this key value = "<<k<<endl;
			}
			else
			{
				if(nexist(n->key)!=NULL)
				{
					cout<<"Node already exist with same key value = "<<n->key<<endl;
				}
				else
				{
					n->next=ptr->next;
					ptr->next=n;
					cout<<"Node inserted "<<endl;
				}
			}
		}

		void dnode(int k)
		{
			if(head==NULL)
			{
				cout<<"Node is empty "<<endl;
			}
			else if(head!=NULL)
			{
				if(head->key==k)// assuming that the head is being deleted
				{
					head=head->next;
					cout<<"Node deleted "<<endl;
				}
				else //assuming that any middle or last node is being is deleted
				{
					Node *temp=NULL;
					Node *prevptr=head;
					Node *currentptr=head->next;
					while(currentptr != NULL)
					{
						if(currentptr->key == k)
						{
							temp=currentptr;
							currentptr=NULL;

						}
						else
						{
							prevptr=prevptr->next;
							currentptr=currentptr->next;
						}
					}
					if(temp!=NULL)
					{
						prevptr->next=temp->next;
						cout<<"Node deleted "<<k<<endl;
					}
					else
					{
						cout<<"No node exist with "<<k<<" value "<<endl;
					}
				}
			}
		}

		void updatenode(int k, int d)
		{
			Node *ptr=nexist(k);
			if(ptr!=NULL)
			{
				ptr->data=d;
				cout<<"Node data updated successfully "<<endl;
			}
			else
			{
				cout<<"Node doesn't exist "<<k<<" value "<<endl;
			}
		}

		void printlist()
		{
			if(head==NULL)
			{
				cout<<"Node is empty "<<endl;
			}
			else
			{
				cout<<"\nSingly linked list values are "<<endl;
				Node *temp=head;

				while(temp!=NULL)
				{
					cout<<"("<<temp->key<<","<<temp->data<<")-->"<<endl;
					temp=temp->next;
				}

			}
		}	
};

