#ifndef FILEMANAGER_H

#define FILEMANAGER_H



#include <cstring>

#include "BPlusTree.hpp"

#include "constant.h"

#include "Node.hpp"

#include "utility.hpp"





#define start 4096



/**

 *

 * isLeaf, key number, val number, child number, then vector values sequentially.

 * finally is one addType, means the next node.

 */



namespace sjtu {



    template<class Key_Type,

            class Value_Type,

            class Compare = std::less<Key_Type>,

            class Compare_child = std::less<addType>

    >

    class FileManager {

    private:

        typedef TreeNode<Key_Type, Value_Type> Node;



        char filename[100];

        FILE *file;

        bool isOpened;



        bool Cmp(const Key_Type &x, const Key_Type &y) const {       /// <

            static Compare _cmp;

            return _cmp(x, y);

        }



        bool Equal(const Key_Type &x, const Key_Type &y) const {     /// ==

            if ((Cmp(x, y) || Cmp(y, x))) return 0;

            else return 1;

        }



    public:

        addType root_off;

        addType head_off;

        addType tail_off;

        addType append_off;



        struct one{

            addType root_off = -1;

            addType head_off = -1;

            addType tail_off = -1;

            addType append_off = start;



        };



        struct two{

            bool isLeaf;

            addType next;

            short key;

            short value;

            short child;

        };







    private:

        void createFile() {

            file = fopen(filename, "wb");

            root_off = head_off = tail_off = -1;

            append_off = start;

            one a;



            fwrite(&a,sizeof(one),1,file);

            fclose(file);

        }



        void init() {

            file = fopen(filename, "r");

            if (file == nullptr) {

                createFile();

                file = fopen(filename, "r+b");

            } else {

                file = fopen(filename, "r+b");

                one a;

                fread(&a,sizeof(one),1,file);

                head_off = a.head_off;

                tail_off = a.tail_off;

                root_off = a.root_off;

                append_off = a.append_off;



            }

        }



    public:

        FileManager() {

            filename[0] = '\0';

            isOpened = false;

            root_off = head_off = tail_off = -1;

            append_off = start;

            file = nullptr;

        }



        ~FileManager() {

            if (isOpened) {

                close_file();

            }

        }



        void set_fileName(const char *fname) {

            strcpy(filename, fname);

        }



        void clear_fileName() {

            filename[0] = '\0';

        }



        bool open_file() {

            if (isOpened) {

                return false;

            } else {

                init();

                isOpened = true;

                return true;

            }

        }



        bool close_file() {

            if (!isOpened) {

                std::cout << "false!";

                return false;

            } else {

                fseek(file, 0, SEEK_SET);

                one a;

                a.head_off = head_off;

                a.root_off = root_off;

                a.tail_off = tail_off;

                a.append_off = append_off;

                fwrite(&a,sizeof(one),1,file);





                fclose(file);

                root_off = head_off = tail_off = -1;

                append_off = start;

                file = nullptr;

                isOpened = false;

                return true;

            }

        }



        bool clean() {

            if (!isOpened) return false;

            else {

                fclose(file);

                root_off = head_off = tail_off = -1;

                append_off = start;

                file = fopen(filename, "w+");

                fclose(file);

                file = fopen(filename, "wb+");

                fseek(file, 0, SEEK_SET);

                one a;

                fwrite(&a,sizeof(one),1,file);

                return true;

            }

        }



        bool is_opened() {

            return isOpened;

        }



        void get_block(addType offset, Node &ret) {

            ret.address = offset;

            two a;



            fseek(file, offset, SEEK_SET);

            fread(&a, sizeof(two), 1, file);

            ret.isLeaf = a.isLeaf;

            ret.next = a.next;

            short K_size = a.key;

            short V_size = a.value;

            short Ch_size = a.child;





            ret.keys.read_file(file, K_size);

            ret.vals.read_file(file, V_size);

            ret.childs.read_file(file, Ch_size);



        }



        bool get_next_block(const Node &cur, Node &ret) {

            if (cur.next == -1)

                return false;

            else {

                get_block(cur.next, ret);

                return true;

            }

        }



        bool get_root(Node &ret) {

            if (root_off == -1) return false;

            else  get_block(root_off, ret);

            return true;

        }



        bool get_head(Node &ret) {

            if (head_off == -1) return false;

            if (head_off == 0)

                get_block(tree_utility_byte, ret);

            else

                get_block(head_off, ret);

            return true;

        }



        bool get_tail(Node &ret) {

            if (tail_off == -1) return false;

            if (tail_off == 0)

                get_block(tree_utility_byte, ret);

            else

                get_block(tail_off, ret);

            return true;

        }



        void append_block(Node &ret, bool isLeaf) {

            ret.clear();

            ret.address = append_off;

            ret.isLeaf = isLeaf;

            append_off += BlockSize;

        }













        void write_block(Node &now) {

            fseek(file,now.address,SEEK_SET);

            two a;

            a.isLeaf = now.isLeaf;

            a.next = now.next;

            a.key = now.keys.size();

            a.value = now.vals.size();

            a.child = now.childs.size();

            fwrite(&a, sizeof(two), 1, file);



            now.keys.write_file(file);



            now.vals.write_file(file);



            now.childs.write_file(file);





        }



        void set_root(addType offset) {

            root_off = offset;

        }



        addType get_root() {

            return root_off;

        }



        sjtu::vector<Value_Type> traverse_multi(const Key_Type &K) {

            sjtu::vector<Value_Type> ans;

            if (head_off == -1) {

                return ans;

            }

            Node now;

            get_block(head_off, now);

            while (true) {

                if (Cmp(now.keys[now.keys.size() - 1], K)) {

                    if (now.next != -1)

                        get_block(now.next, now);

                    else return ans;

                } else {

                    int i;

                    for (i = 0; i < now.keys.size(); ++i) {

                        if (Equal(now.keys[i], K)) break;

                    }

                    --i;

                    while (true) {

                        i++;

                        if (!Equal(now.keys[i], K)) break;

                        ans.push_back(now.vals[i]);

                        if (i == now.keys.size() - 1) {

                            if (now.next == -1) {

                                return ans;

                            }

                            get_block(now.next, now);

                            i = -1;

                        }

                    }

                    break;

                }



            }

            return ans;

        }



        void traverse() {

            if (head_off == -1) {

                std::cout << "empty!\n";

                return;

            }

            std::cout << root_off << "root_off\n";

            Node now;

            get_block(head_off, now);

            int ans = 0;



            while (true) {

                for (int i = 0; i < now.keys.size(); ++i) {

                    ans++;

                }

                if (now.next == -1)

                    break;

                get_block(now.next, now);

            }

            std::cout << ans;

        }

    };

};



#endif

#ifndef TREENODE_H

#define TREENODE_H



#include "vector.hpp"

#include "constant.h"



#define min_cmp 20



namespace sjtu {



    template<class Key_Type,

            class Value_Type,

            class Compare = std::less<Key_Type>,

            class Compare_value = std::less<Value_Type>

    >

    class TreeNode {

    public:

        addType address;          // 文件中地址

        bool isLeaf;

        addType next;

        sjtu::vector<Key_Type> keys;

        sjtu::vector<Value_Type> vals;

        sjtu::vector<addType> childs;





        bool Cmp(const Key_Type &x, const Key_Type &y) const {       ///<

            static Compare _cmp;

            return _cmp(x, y);

        }



        bool Equal(const Key_Type &x, const Key_Type &y) const {     /// ==

            if (Cmp(x, y) || Cmp(y, x)) return 0;

            else return 1;

        }



        bool Cmp_value(const Value_Type &x, const Value_Type &y) const        ///<

        {

            static Compare_value _cmp;

            return _cmp(x, y);

        }



        bool Equal_value(const Value_Type &x, const Value_Type &y) const      /// ==

        {

            if (Cmp_value(x, y) || Cmp_value(y, x)) return 0;

            else return 1;

        }



        explicit TreeNode(addType _address = -1, bool _isleaf = true) :

                childs(), vals(), keys() {

            address = _address;

            next = -1;

            isLeaf = _isleaf;

        }



        TreeNode(const TreeNode &other) noexcept:

                childs(),

                vals(),

                keys() {

            address = other.address;

            next = other.next;

            isLeaf = other.isLeaf;

            keys = other.keys;

            if (isLeaf)

                vals = other.vals;

            else

                childs = other.childs;

        }



        TreeNode &operator=(const TreeNode &other) {

            address = other.address;

            childs = other.childs;

            keys = other.keys;

            vals = other.vals;

            next = other.next;

            isLeaf = other.isLeaf;

            return *this;

        }



        /**找最小的i使得 key[i] > K，没有则返回-1;*/

        int search_sup(Key_Type K) {

            int pos = 0;

            if (keys.size() < min_cmp) {

                while (pos < keys.size() && !Cmp(K, keys[pos])) pos++;

                if (pos == keys.size()) return -1;

                else return pos;

            } else {

                int low = 0, high = keys.size() - 1;

                int mid;

                while (high - low >= min_cmp) {

                    mid = (low + high) / 2;

                    if (!Cmp(K, keys[mid]))

                        low = mid;

                    else

                        high = mid;

                }

                while (low < keys.size() && !Cmp(K, keys[low])) ++low;

                if (low == keys.size()) return -1;

                else return low;

            }

        }



        /**找确切key[i] = K */

        int search_exact(const Key_Type &K) {

            int pos = 0;

            while (pos < keys.size() && !Equal(K, keys[pos])) ++pos;

            if (pos == keys.size()) return -1;

            else return pos;

        }



        int search_sup_multi(Key_Type K) {

            int pos = 0;

            while (pos < keys.size() && Cmp(keys[pos], K)) pos++;

            return pos;



        }



        /**   清空node      */

        void clear_content() {

            childs.clear();

            keys.clear();

            vals.clear();

        }



        void clear() {

            address = next = -1;

            isLeaf = true;

            childs.clear();

            keys.clear();

            vals.clear();

        }



        /**   找块中孩子，失败返回-1      */

        int search_child(addType child) {

            if (childs.size() < 20) {

                int i = 0;

                while (i < childs.size() && childs[i] != child) ++i;

                if (i == childs.size()) {

                    return -1;

                } else return i;

            } else {

                int low = 0, high = childs.size() - 1;

                int mid;

                while (high - low >= 20) {

                    mid = (low + high) / 2;

                    if (childs[mid] == child)

                        return mid;

                    else if (childs[mid] < child)

                        low = mid;

                    else

                        high = mid;

                }

                while (low < childs.size() && childs[low] != child) ++low;



                if (low == childs.size()) return -1;

                else return low;

            }

        }

    };





};

#endif

