    unaryop1()
    {

    }
    unaryop1(int a1,int b1, int c1)
    {
        a=a1;
        b=b1;
        c=c1;
    }
    void operator --()
    {
        --a;
        --b;
        --c;
    }
    void display()
    {
        cout<<a<<" "<<b<<" "<<c<<endl;
    }
};
