class movie

{

public:



    struct node *head[10],*temp,*cn;

    movie()

    {

        for(int i=0;i<10;i++)

        {

            head[i]=NULL;

        }

        temp=NULL;



    }

    void create()

    {

        for(int i=0;i<10;i++)

        {

            for(int j=0;j<7;j++)

            {

                temp=new node();

                temp->state='U';

                temp->next=NULL;

                temp->prev=NULL;



                if(head[i]==NULL)

                {

                    temp->next=temp;

                    temp->prev=temp;

                    head[i]=temp;

                }

                else

                {

                    cn=head[i];

                    while(cn->next!=head[i])

                    {

                        cn=cn->next;

                    }



                    cn->next=temp;

                    temp->prev=cn;

                    temp->next=head[i];

                    head[i]->prev=temp;

                }

            }



        }

    }

