        {

            cn=head[r-1];

            for(int i=1;i<c;i++)

            {

                cn=cn->next;



            }

            cn->state='U';

            cn->id=0;

            cn->name="";



            cout<<"ticket canceled successfully "<<endl;

        }

        else

            cout<<"enter valid row and column "<<endl;

    }

    void display()

    {

        cout<<"                           Screen                          "<<endl;

