        cin>>r>>c;

        cn=head[r-1];



        for(int i=1;i<c;i++)

        {

            cn=cn->next;



        }

         cout<<"seat details "<<endl;

         cout<<"seat status :"<<cn->state<<endl;

         cout<<"seat booked by :"<<cn->name<<endl;

         cout<<"movie id:"<<cn->id<<endl;

    }

