{

	os << "[\n";



	for (Book b : anInstance.getAll())

	{

		os << b << "\n";

	}



	os << "]" << endl;



	return os;

}



void Library::deleteBook(string name)

{



	for (int i = 0; i < _bookshelf.size(); i++)

	{

		if (_bookshelf.at(i).getName().compare(name) == 0)

		{

			_bookshelf.erase(_bookshelf.begin() + i);

			return;

		}

	}

}

