  switch(sayi){
    case 1:
      for(; j<16; j++)
      {
        if(Odalar[j]!=Bos)
        {
          Odalar[j]=Dolu;
          cout<<"Adınız: ";
          cin>>ad;
          cout<<"Soyadınız: ";
          cin>>soyad;
          cout<<"Kalacağınız gün sayısı: ";
          cin>>x2;
          Toplam += x2 * 50;
          SayacIki++;
