          *MusteriAdi[j] = ad;
          MusteriSoyadi[j] = new string;
          *MusteriSoyadi[j] = soyad;
          break;
        }
      }
      if(j == 16)
        cout<<"Ne yazık ki bütün tek kişilik odalar dolu."<<endl;
      break;
    case 2:
      for(; k<46; k++)
      {
        if(Odalar[k] != Dolu)
        {
          Odalar[k] = Dolu;
          cout<<"Adınız: ";
          cin>>ad;
          cout<<"Soyadınız: ";
          cin>>soyad;
          cout<<"Kalacağınız gün sayısı: ";
          cin>>x2;
          Toplam += x2 * 70;
          SayacIki++;
          MusteriAdi[j] = new string;
          *MusteriAdi[j] = ad;
          MusteriSoyadi[j] = new string;
          *MusteriSoyadi[j] = soyad;
          break;
        }
      }
      if(k == 46)
        cout<<"Ne yazık ki bütün odalar dolu."<<endl;
      break;
    case 3:
      for(; i<6; i++)
      {
        if(Odalar[i] != Dolu)
        {
          Odalar[i]=Dolu;
          cout<<"Adınız: ";
          cin>>ad;
          cout<<"Soyadınız: ";
          cin>>soyad;
          cout<<"Kalacağınız gün sayısı: ";
