void Otel::OdaBosaltma()
{
  cout<<"Boşaltacağınız oda numarası: ";
  int sayi;
  cin>>sayi;

  if(Odalar[sayi] == Dolu)
  {  
    if(sayi>0 && sayi<6)
    {
      Odalar[sayi] = Bos;
      delete MusteriAdi[sayi];
      delete MusteriSoyadi[sayi];
      SayacBir--;
      cout<<"Belirtilen oda silindi."<<endl;
    }
    else
      if(sayi>5 && sayi<14)
      {
        Odalar[sayi]=Bos;
        delete MusteriAdi[sayi];
        delete MusteriSoyadi[sayi];
        SayacIki--;
        cout<<"Belirtilen oda silindi."<<endl;
      }
  }
  else
    cout<<"Lütfen oda numarasını doğru giriniz.\n"<<endl;
}

void Otel::MusteriSayisi()
{
  cout<<"Dolu oda sayısı: "<<SayacBir + SayacIki<<endl;
}

void Otel::YatakOdasiSorgu()
{
  if(SayacIki == 0)
    cout<<"Bütün odalar boş."<<endl;
  else
  {
    cout<<"Oda Numarası Müşteri Adı Müşteri Soyadı"<<endl;
    cout<<"---------------------------------------"<<endl;
    for(int i=6; i<46; i++)
      if(Odalar[i] == Dolu)
        cout<<i<<"\t\t"<<*MusteriAdi[i]<<"\t\t"<<*MusteriSoyadi[i]<<endl;
  }
}

void Otel::SunumOdasiSorgu()
{
  if(SayacBir != 6){
    cout<<"Sunum odaları dolu."<<endl;
    for(int i=1; i<6; i++)
      if(Odalar[i] == Dolu)
        cout<<"Oda Numarası: "<<i<<endl;
  }
  else
    cout<<"Bütün sunum odaları boş."<<endl;
}

void Otel::Gelir()
{
  cout<<"Gelir: "<<Toplam;
}

