		if (this->nume.compare(stud.nume) == 0)
			return true;
		else
			return false;

	}

	//operatorul la float
	explicit operator float() {
		return this->getMedie();
	}

	explicit operator int() {
		return this->varsta;
	}

	int operator()(int min, int max) {
		int contor = 0;
		for (int i = 0; i < this->nrNote; i++)
			if (this->note[i] >= min && this->note[i] <= max)
				contor += 1;
		return contor;
	}

	int& operator[](int index) {
		if (index >= 0 && index <= this->nrNote)
			return this->note[index];
		else
			throw new exception();
	}

	//preincrementare
	Student operator++() {
		this->varsta += 1;
		return *this;
	}

	//postincrementare
	Student operator++(int) {
		Student copie = *this;
		this->varsta += 1;
		return copie;
	}

	friend Student operator+(Student& stud, int nota);
	friend void operator>>(istream& in, Student& stud);
};

