	int* listaNoua = new int[rezultat.getNrNote() + 1];
	for (int i = 0; i < rezultat.getNrNote(); i++)
		listaNoua[i] = rezultat.note[i];
	listaNoua[rezultat.nrNote] = nota;

	if (rezultat.note != NULL)
		delete[] rezultat.note;

	rezultat.note = listaNoua;
	rezultat.nrNote += 1;

	return rezultat;

}

