            cout<<"\t\t\t"<<index++<<". "<<college_companies[i]<<endl;
        }
    }
    struct less_than_key
    {
        inline bool operator()(const Placement &struct1, const Placement &struct2)
        {
            return (struct1.year < struct2.year);
        }
    };

    void placement_history()
    {
