class Counter{
	//private: commented out for ease of testing
	public:
		int count;
	    	mutable boost::mutex m_mutex;
	public:
		Counter() : count(1) {}

		Counter * get(){
			return this;
		}

		int getCurrentCount(){
			return count;
		}

		void inc(){
			boost::mutex::scoped_lock lock(m_mutex);
			this->count++;
		}

		void dec(){
			boost::mutex::scoped_lock lock(m_mutex);
			this->count--;
		}
};


