void *operator new(size_t sz) throw (bad_alloc) {
    char *p = (char *) malloc(sz + 8);
    *((size_t *) p) = sz;
    __sync_add_and_fetch(&AllocatedSpace, sz);
    return p + 8;
}

void operator delete(void *vp) throw () {

    if (vp == 0) {
        return;
    }

    char *p = (char *) vp;
    size_t sz = *((size_t *) (p - 8));
    __sync_sub_and_fetch(&AllocatedSpace, sz);
    free(p - 8);
}

