    cout<<"\nUsing data members access";
    SetConsoleTextAttribute(color, 7 );     //Setting color White
    class_ptr->length = 2;
    class_ptr->breadth = 3;
    class_ptr->initialize(class_ptr->length,class_ptr->breadth);
    class_ptr->display();

