{


         for(j=0;j<n;j++)


         {


              for(i=0;i<n-1;i++)


                    {


                        if(a[i]>a[i+1])


                            {


                                temp=a[i+1];


                                a[i+1]=a[i];


                                a[i]=temp;


                            }


                    }


     }


    cout<<"\n The sorted array is ";


    for(i=0;i<n;i++)


        {


              cout<<"\n a["<<i<<"]="<<a[i];


        }


    }




