{
   for(i=0;i<n;i++)


                 {


                        b[i]=a[i];


                 }


            cout<<"\n The exchanged array is "; 


            for(i=0;i<n;i++)


                 {


                       cout<<"\n b["<<i<<"]="<<b[i];


                 }


        }


