class Queue

{

	public :

		int a;

		list <int> s;

		list <int> :: iterator itr;





		void push()

		{

			cout<<"\n Enter a number : ";

				cin>>a;

				s.push_back(a);

		}



		void displaystack()

		{

			cout<<"\n The elements in the queue are : "<<"\n";

			for(itr=s.begin() ; itr!=s.end() ; itr++)

			{

				cout<<*itr<<"\t";

			}

		}



		void pop()

		{

			itr=s.begin();

			s.pop_front();

			cout<<"\n The element popped out of the queue is "<<*itr;

		}



};



