class str_command
{
  public:
    str_command(size_t size)
    {
        cmd.resize(size);
    }
    ~str_command()
    {
        std::cout << "CMD Destroyed" << std::endl;
    }
    std::vector<uint8_t> get_cmd()
    {
        return cmd;
    }
    int get_cmd_id()
    {
        return cmd[3];
    }

