template <typename T>
class Named
{
protected:
	T data;
	char *name;

public:
	Named()
	{
		data = T();
		name = NULL;
	}
	Named(T _data, char *_name)
	{
		data = _data;
		name = new char[strlen(_name) + 1];
		strcpy(name, _name);
	}
	Named(Named const& n)
	{
		data = n.data;
		name = new char[strlen(n.name) + 1];
		strcpy(name, n.name);
	}
	Named& operator=(Named const& n)
	{
		if(this!=&n)
		{
			delete name;

			data = n.data;
			name = new char[strlen(n.name) + 1];
			strcpy(name, n.name);
		}
		return *this;
	}
	~Named()
	{
		delete name;
	}

	template <typename T>
	friend ostream& operator<<(ostream&, Named<T> const&);
	template <typename T>
	friend istream& operator>>(istream&, Named<T> const&);

};

template <typename T>
ostream& operator<<(ostream& os, Named<T> const& n)
{
	os << "Name: " << n.name;
	os << "Data: " << n.data;
	return os;
}

template <typename T>
istream& operator<<(istream& is, Named<T> const& n)
{
	is << "Name: " << n.name;
	is << "Data: " << n.data;
	return is;
}

