		this->name = new char[strlen(other.name) + 1];
		strcpy(this->name, other.name);
		this->grade = other.grade;
	}

	//предефиниране на оператор равно
	//типа на връщане е Student& за да може да се прави student1=student2=student3
	Student& operator=(Student const& other)
	{
		//трябва да се защитим от следната ситуация student1=student1
		if(this!=&other)
		{
			//стандартното изтриване, заделяне и копиране на памет
			delete[] this->name;
			this->name = new char[strlen(other.name) + 1];
			strcpy(this->name, other.name);
			this->grade = other.grade;
		}
		//this е указател *this е референция, какъвто е и типа на втъщане на оператора
		return *this;
	}

	//деструктор
	~Student()
	{
		//използваме delete[] от теоретична гледна точка защото name е масив от елементи а не само един елемент
		//само delete би свършило същата работа
		delete[] name;
	}
};

class Inventory
{
	Rune* runes;
	int current; //index
	int capacity; //size

	void copy(Inventory const& other)
	{
		current = other.current;
		capacity = other.capacity;

		runes = new Rune[capacity];
		for (int i = 0; i <= current; i++)
			runes[i] = other.runes[i];
	}

	void remove()
	{
		delete[] runes;
	}

  void resize()
	{
		capacity *= 2;
		Rune *runes2 = new Rune[capacity];
		for (int i = 0; i < capacity; i++)
		{
			runes2[i] = runes[i];
		}
		delete[] runes;
		runes = runes2;
	}

public:
	Inventory()
	{
		current = -1;
		capacity = 10;
		runes = new Rune[capacity];
	}

	void add(Rune const& rune)
	{
		if(current==capacity-1)
		{
			resize();
		}

		current++;
		runes[current] = rune;
	}

	Inventory(Inventory const& other)
	{
		copy(other);
	}

	Inventory& operator=(Inventory const& other)
	{

		if (this != &other)
		{
			remove();
			copy(other);
		}

		return *this;
	}

	~Inventory()
	{
		remove();
	}
};

void testInventory()
{

	while(true)
	{
		Inventory inv;
		for (int i = 0; i < 1000; i++)
		{
			Rune r;
			inv.add(r);
		}
	}
}

int main()
{
	testInventory();
  return 0;
}

