#define size 10
class QueueOfString
{public:
	int in,out; // input from in, and output from out
	string arr[size];

	QueueOfString () { in=-1; out=-1;
	for(int i=0;i<size;i++)
		arr[i]="";
	}
	void Print()
	{ if(!IsEmpty())
	{int temp=out;
		while(temp!=in)
		{ if(temp==size-1  )
			{cout<<endl<<arr[temp]; temp=0; }
		else	cout<<endl<<arr[temp++];
		}
		cout<<endl<<arr[temp++];}
		else cout<<" empty";	
	}
	bool IsEmpty ()
	{ return out==-1?1:0; }

	bool Full()
	{  return ((in+1)%size==out)?1:0; }

	void Clear()
	{ in=out=-1; }

	void Enqueue (string temp)
	{ if(!Full())
	{ if(in==-1 || in==size-1)
		{arr[0]=temp; in=0;
		if(out==-1)
			out=0;}
	else { in=(in+1);  arr[in]=temp; } 
	}
	else 
		cout<<" Queue is Full";
	}

	string Dequeue ()
	{	if(!IsEmpty())
		{ string temp=arr[out];
			if(in==out)
			{in=-1; out=-1;}
		else if(out==size-1  )
				out=0;
		else	out=out++;
			return temp;
		}
	else return ""; }
};


