		int gcd(int a, int b) {
		    int res = min(a, b);
		    while (res > 1) {
		        if (a % res == 0 && b % res == 0)
		            break;
		        res--;
		    }
			return res;
		};
		void reduce(int &a, int &b){
			int tmp; 
			while(gcd(a,b)!=1){
				tmp = gcd (a,b);
				a = a/tmp;
				b = b/tmp;
			}

		}
		void tong(int a,int b,int c,int d){
			int tu = a * d + b * c ;
			int mau= d * b ;
			reduce(tu,mau);
			cout<<"tong: "<<tu <<"/" << mau <<endl;
		};
		void hieu(int a,int b, int c, int d){
			int tu = a * d - b * c ;
