        }
};
class Distance{
    private: 
        float x1, y1, x2, y2;

    public:
        Distance(float x1, float y1, float x2, float y2){
            this->x1 = x1;
            this->y1 = y1;
            this->x2 = x2;
            this->y2 = y2;
        }

        float getDistance(){
            return sqrt((x2 - x1)*(x2 - x1) + (y2 - y1)*(y2 - y1));
        }
};

