        }
    }
    void findMaxPhanSo(){
        if (n == 0) {
            cout << "Mang rong!" << endl;
            return;
        }
        PhanSo maxPS = p[0];
        for(int i = 1; i < n; i++){
            // So sanh phan so voi nhau bang cross multiplication
            if (p[i] > maxPS) {
                maxPS = p[i];
            }
