        for(int i = 0; i < n-1; i++){
            for(int j = i+1; j < n; j++){
                if( (p[i] > p[j])){
                    swap(p[i], p[j]);
                }
            }
        }
        cout<<"Mang phan so sau khi sap xep la: \n";
        Xuat();
    }

};

