#include<bits/stdc++.h>
using namespace std;

class PhanSo{
private:
    int tuso, mauso;
public:
    PhanSo(int tu = 0, int mau = 1): tuso(tu), mauso(mau) {}
    PhanSo (const PhanSo& ps): tuso(ps.tuso), mauso(ps.mauso) {}
    int LayTu() const { return tuso; }
    int LayMau() const { return mauso; }
    void GanTu(int tu) { tuso = tu; }
    void GanMau(int mau) { mauso = mau; }
    void nhap(){
        cout<<"Nhap tu so: ";
        cin>>tuso;
        cout<<"Nhap mau so: ";
        cin>>mauso;
    }
    void xuat() const {
        cout<<tuso<<"/"<<mauso;
    }
    bool operator>(const PhanSo &ps) const{
        return (tuso * ps.mauso) > (ps.tuso * mauso);
    }
    PhanSo operator+(const PhanSo &ps) const{
        PhanSo temp;
        temp.tuso = tuso * ps.mauso + ps.tuso * mauso;
        temp.mauso = mauso * ps.mauso;
        return temp;
    }
    PhanSo operator-(const PhanSo &ps) const{
        PhanSo temp;
        temp.tuso = tuso * ps.mauso - ps.tuso * mauso;
        temp.mauso = mauso * ps.mauso;
        return temp;
    }
};

class dsPhanSo{
private: 
    PhanSo *ds;
    int n;
public:
    dsPhanSo(int size = 0): n(size), ds((size==0)?nullptr:new PhanSo[size]) {}
    ~dsPhanSo(){
        delete[] ds;
    }
    friend istream& operator>>(istream &is, dsPhanSo &dsp);
    friend ostream& operator<<(ostream &os, const dsPhanSo &dsp);

    PhanSo TimMax() const {
        PhanSo max = ds[0];
        for(int i = 1; i < n; i++){
            if(ds[i] > max){
                max = ds[i];
            }
        }
        return max;
    }
    PhanSo Tong() const {
        PhanSo sum;
        for(int i = 0; i < n; i++){
            sum = sum + ds[i];
        }
        return sum;
    }
};
istream& operator>>(istream &is, dsPhanSo &dsp){
    cout<<"Nhap so luong phan so: ";
    is >> dsp.n;
    delete[] dsp.ds;
    dsp.ds = new PhanSo[dsp.n];
    for(int i = 0; i < dsp.n; i++){
        cout<<"Nhap phan so thu "<<i+1<<":"<<endl;
        dsp.ds[i].nhap();
    }
    return is;
}
ostream& operator<<(ostream &os, const dsPhanSo &dsp){
    for(int i = 0; i < dsp.n; i++){
        os<<"Phan so thu "<<i+1<<": ";
        dsp.ds[i].xuat();
        os<<endl;
    }
    return os;
}
int main(){
    dsPhanSo dsp;
    cin >> dsp;
    cout << dsp;
    PhanSo max = dsp.TimMax();
    cout << "Phan so lon nhat: ";
    max.xuat();
    cout << endl;
    PhanSo sum = dsp.Tong();
    cout << "Tong cac phan so: ";
    sum.xuat();
    cout << endl;
}

#include<bits/stdc++.h>
using namespace std;

class Matran{
private:
    int rows, cols;
    int **data;
public:
    Matran(int r = 0, int c = 0): rows(r), cols(c){
        data = new int*[rows];
        for(int i = 0; i < rows; i++){
            data[i] = new int[cols];
        }
    }
    ~Matran(){
        for(int i = 0; i < rows; i++){
            delete[] data[i];
        }
        delete[] data;
    }
    void MatranRandom(){
        srand(time(0));
        rows = rand() % 5 + 1;
        cols = rand() % 5 + 1;
        data = new int*[rows];
        for(int i = 0; i < rows; i++){
            data[i] = new int[cols];
            for(int j = 0; j < cols; j++){
                data[i][j] = rand() % 10;
            }
        }

    }

    Matran operator+(const Matran &other) const {
        if (rows != other.rows || cols != other.cols) {
            throw invalid_argument("Matrices must have the same dimensions for addition.");
        }
        Matran result(rows, cols);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                result.data[i][j] = data[i][j] + other.data[i][j];
            }
        }
        return result;
    }
    Matran operator*(const Matran &other) const {
        if (cols != other.rows) {
            throw invalid_argument("Incompatible matrix dimensions for multiplication.");
        }
        Matran result(rows, other.cols);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < other.cols; j++) {
                result.data[i][j] = 0;
                for (int k = 0; k < cols; k++) {
                    result.data[i][j] += data[i][k] * other.data[k][j];
                }
            }
        }
        return result;
    }
    friend ostream& operator<<(ostream &os, const Matran &m);
    friend istream& operator>>(istream &is, Matran &m);

};

ostream& operator<<(ostream &os, const Matran &m) {
    for (int i = 0; i < m.rows; i++) {
        for (int j = 0; j < m.cols; j++) {
            os << m.data[i][j] << " ";
        }
        os << endl;
    }
    return os;
}

istream& operator>>(istream &is, Matran &m) {
    cout << "Nhap so hang: ";
    is >> m.rows;
    cout << "Nhap so cot: ";
    is >> m.cols;
    for (int i = 0; i < m.rows; i++) {
        delete[] m.data[i];
    }
    delete[] m.data;
    m.data = new int*[m.rows];
    for (int i = 0; i < m.rows; i++) {
        m.data[i] = new int[m.cols];
        for (int j = 0; j < m.cols; j++) {
            cout<<"Nhap phan tu ["<<i<<"]["<<j<<"]: ";
            is >> m.data[i][j];
        }
    }
    return is;
}

int main(){
    Matran A, B;
    cout<<"Nhap ma tran A:"<<endl;
    cin >> A;
    cout<<"Nhap ma tran B:"<<endl;
    cin >> B;
    try {
        Matran C = A + B;
        cout << "Ma tran A + B:\n" << C << endl;
    } catch (const invalid_argument &e) {
        cout << e.what() << endl;
    }
    try {
        Matran D = A * B;
        cout << "Ma tran A * B:\n" << D << endl;
    } catch (const invalid_argument &e) {
        cout << e.what() << endl;
    }
    return 0;
}

