/* Bai 2.13: Big Integer.
			Số nguyên lớn là các số nguyên có giá trị rất lớn và không thể biểu diễn bằng các kiểu dữ liệu
			nguyên cơ bản. Để biểu diễn số nguyên lớn, ta có thể dùng kiểu struct như sau:
			struct bigNum{
			char sign;
			char num[101];
			};
			Nhiệm vụ các bạn là đa năng hóa các toán tử để thực hiện các phép toán số học với kiểu dữ liệu
			số nguyên lớn vừa định nghĩa ở trên.
			Input: Dữ liệu vào gồm hai dòng mô tả hai số nguyên lớn aa và bb, mỗi dòng chứa 1 chuỗi ký tự
			mô tả 1 số nguyên lớn không vượt quá 1010010100. Chữ số đầu của mỗi chuỗi ký tự sẽ thể hiện
			dấu của số đó: 0 là âm, 1 là dương. Các chữ số sau thể hiện giá trị của số đó.
			Output: In ra giá trị của biểu thức ab−3a+4bab−3a+4b. Kết quả in ra một số nguyên lớn dưới
			dạng chuỗi ký tự có định dạng như mô tả trong dữ liệu vào. */

#include<iostream>
#include<string> 
#include<algorithm>

using namespace std;

// Khai bao cau truc bigNum de luu tru so lon
struct bigNum{
	char sign;  // Danh dau dau so: '1' la duong, '0' la am
	string num;  // Phan chu so cua so lon
};

// Ham so sanh hai chuoi so a_55 va b_55
int compareBigNum_55 (const string &a_55, const string &b_55){
	if (a_55.length() != b_55.length()) return a_55.length() - b_55.length();  // So sanh do dai chuoi
	return a_55.compare(b_55);  // Neu bang do dai, so sanh tu trai qua phai
} 

// Ham cong hai chuoi so
string addBigNum_55 (const string &a_55, const string &b_55){
	string c_55;
	int carry_55 = 0;   // Bien nho khi cong
	int i_55 = a_55.length() - 1;  // Chi so cuoi cua chuoi a
	int j_55 = b_55.length() - 1;  // Chi so cuoi cua chuoi b
	while (i_55 >= 0 || j_55 >= 0 || carry_55){   // Lap den khi het chu so va het nho
		int numoa_55, numob_55; 
		if (i_55 >= 0){
			numoa_55 = a_55[i_55] - '0';  // Lay chu so tu a
			i_55--;
		} else {
			numoa_55 = 0; 
		} 
		if (j_55 >= 0){
			numob_55 = b_55[j_55] - '0';  // Lay chu so tu b
			j_55--;
		} else {
			numob_55 = 0;
		}
		int sum_55 = numoa_55 + numob_55 + carry_55;  // Tong 2 chu so + nho
		c_55 += (sum_55 % 10 + '0');  // Them chu so vao ket qua
		carry_55 = sum_55 / 10;  // Cap nhat bien nho
	}
	while (c_55.length() > 1 && c_55.back() == '0') c_55.pop_back();  // Bo so 0 du thua
	reverse(c_55.begin(), c_55.end());  // Dao nguoc chuoi ket qua
	return c_55;
}

	/****************************
	# Pham Duc Manh - 20235155 #
	****************************/

// Ham tru chuoi so 
string subBigNum_55 (const string &a_55, const string &b_55){
	string c_55;
	int carry_55 = 0;
	int i_55 = a_55.length() - 1;
	int j_55 = b_55.length() - 1;
	while (i_55 >= 0){
		int numoa_55, numob_55;
		if (i_55 >= 0){
			numoa_55 = a_55[i_55] - '0';  // Lay chu so tu a
			i_55--;
		} else {
			numoa_55 = 0; 
		} 
		if (j_55 >= 0){
			numob_55 = b_55[j_55] - '0';  // Lay chu so tu b hoac 0
			j_55--; 
		} else {
			numob_55 = 0;
		}
		int sub_55 = numoa_55 - numob_55 - carry_55;  // Hieu giua 2 chu so tru nho
		if (sub_55 < 0){
			sub_55 += 10;
			carry_55 = 1;
		} else {
			carry_55 = 0;
		}
		c_55 += (sub_55 + '0');  // Them vao chuoi ket qua
	}
	while (c_55.length() > 1 && c_55.back() == '0') c_55.pop_back();  // Xoa so 0 du
	reverse(c_55.begin(), c_55.end());  // Dao nguoc ket qua
	return c_55;
}

// Ham nhan chuoi so 
string mulBigNum_55 (const string &a_55, const string &b_55){
	int i_55 = a_55.length();
	int j_55 = b_55.length();
	string c_55(i_55 + j_55, '0');  // Khoi tao chuoi ket qua toan 0
	for (int i = i_55 - 1; i >= 0; i--){
		int carry_55 = 0;
		for (int j = j_55 - 1; j >= 0; j--){
			int mul_55 = (c_55[i + j + 1] - '0') + (a_55[i] - '0') * (b_55[j] - '0') + carry_55;
			c_55[i + j + 1] = (mul_55 % 10 + '0');  // Ghi chu so vao vi tri
			carry_55 = mul_55 /10;  // Cap nhat bien nho
		}
		c_55[i] += carry_55;
	}
	// Xoa so 0 o dau
	size_t pos = c_55.find_first_not_of('0');
	if (pos == string::npos) {
    	return "0";
	} else {
    	return c_55.substr(pos);
	}
}

/****************************
# Pham Duc Manh - 20235155 #
****************************/

// Doi chuoi sang bigNum
bigNum stringToBigNum_55(const string& s_55){
	bigNum bn_55;
	bn_55.sign = s_55[0];  // Dau duoc luu o vi tri 0
	bn_55.num = s_55.substr(1);   // Phan con lai la so
    if (bn_55.num == "") bn_55.num = "0", bn_55.sign = '1';  // Neu trong thi gan = 0
    return bn_55;
} 

// Da nang hoa toan tu + 
bigNum operator + (bigNum a_55, bigNum b_55) {
	bigNum c_55;
	if (a_55.sign == b_55.sign){  // Cung dau thi cong
		c_55.sign = a_55.sign;
		c_55.num = addBigNum_55(a_55.num, b_55.num); 
	} else {  // Khac dau thi tru
		if(compareBigNum_55(a_55.num, b_55.num) >= 0){
			c_55.sign = a_55.sign;
			c_55.num = subBigNum_55(a_55.num, b_55.num);
		} else {
			c_55.sign = b_55.sign;
			c_55.num = subBigNum_55(b_55.num, a_55.num);
		}
	}
	if (c_55.num == "0") c_55.sign = '1';  // Neu ket qua = 0 thi xem la duong
	return c_55;
} 

// Da nang hoa toan tu -
bigNum operator - (bigNum a_55, bigNum b_55) {
	bigNum c_55 = b_55;
	c_55.sign = (b_55.sign == '1' ? '0' : '1');  // Doi dau b roi cong
	return a_55 + c_55;
}

// Da nang hoa toan tu *
bigNum operator * (bigNum a_55, bigNum b_55){
	bigNum c_55;
	c_55.sign = (a_55.sign == b_55.sign ? '1' : '0');  // Cung dau thi duong, khac dau thi am
	c_55.num = mulBigNum_55(a_55.num, b_55.num);
	if (c_55.num == "0") c_55.sign = '1';  // Neu ket qua bang 0 thi la duong
	return c_55;
}

bigNum operator * (bigNum a_55, int n_55){
	bigNum b_55;
	b_55.sign = '1';  // Mac dinh la duong
	b_55.num = to_string(n_55);  // Chuyen n sang chuoi
	return a_55 * b_55;
}

