EmployeeNode* SortedMerge(EmployeeNode* a, EmployeeNode* b);

void FrontBackSplit(EmployeeNode* source, EmployeeNode** frontRef, EmployeeNode** backRef);

void MergeSort(EmployeeNode** headRef)

{

    EmployeeNode* head = *headRef;

    EmployeeNode* a;

    EmployeeNode* b;

    if ((head == NULL) || (head->next == NULL)) {

        return;

    }

    FrontBackSplit(head, &a, &b);

    MergeSort(&a);

    MergeSort(&b);

    *headRef = SortedMerge(a, b);

}

EmployeeNode* SortedMerge(EmployeeNode* a, EmployeeNode* b)

{

    EmployeeNode* result = NULL;

    if (a == NULL)

        return (b);

    else if (b == NULL)

        return (a);

    if (a->fn <= b->fn) {

        result = a;

        result->next = SortedMerge(a->next, b);

    }

    else {

        result = b;

        result->next = SortedMerge(a, b->next);

    }

    return (result);

}

void FrontBackSplit(EmployeeNode* source, EmployeeNode** frontRef, EmployeeNode** backRef)

{

    EmployeeNode* fast;

    EmployeeNode* slow;

    slow = source;

    fast = source->next;

    while (fast != NULL) {

        fast = fast->next;

        if (fast != NULL) {

            slow = slow->next;

            fast = fast->next;

        }

    }

    *frontRef = source;

    *backRef = slow->next;

    slow->next = NULL;

}

