    cout<<"\n Enter Record Number to Delete: ";

    cin>>n;

    fstream tmpfile;

    tmpfile.open("tmpfile.bank", ios::out|ios::binary);

    infile.seekg(0);

    for(int i=0; i<count; i++)

    {

        infile.read(reinterpret_cast<char*>(this),sizeof(*this));

