				break;

			}	

			if (!found)

			    cout<<"Record Not Found"<<endl;

		    break;

		case 3: //deposit operation

		    cout<<"Enter Account Number To Deposit Ammount: ";

		    cin>> a;

		    for (i=0;i<=2;i++){

		    	found = C[i].Search(a);

