		    		C[i].Deposit();

					break;			

				}

			}

			if (!found)

			    cout<<"Record Not Found"<<endl;

			break;

		case 4: // withdraw operation

            cout << "Account Number To Withdraw Amount? ";

            cin >> a;

            for (i = 0; i <= 2; i++) {

                found = C[i].Search(a);

                if (found) {

                    C[i].Withdrawal();

                    break;

                }

            }

            if (!found)

                cout << "Record Not Found" << endl;

            break;

        case 5: // exit

            cout << "Have a nice day" << endl;

            break;

        default:

            cout << "Wrong Option" << endl;



		}

	}while (ch != 5);

	return 0;

}

