	entity (function);

	entity (void)    ;

	~entity(void)    ;



public:

	void        register_entity(function)          ;

	Slot*       getdest        (void) const        ;

	void*       getmemfunPtr   (void) const        ;

	Return_Type emitSignal     (Tparams const& ...);



private:

	function function_;

};



