					{

						userData.push_back(row[i]);

						std::cout << row[i] << std::endl;

					}

				}

			}

			delete usernames;

			delete passwords;

			return true;

		}

		else

		{

			return false;

		}

	}

	catch (std::string e) {

		std::cout << "Error" << e << std::endl;

		system("PAUSE");

		return false;

	}

}





