	p1 = start;

	p2 = p1->next;

	p1->next = NULL;

	p1->pre = p2;

	while (p2 != NULL)

	{

		p2->pre = p2->next;

		p2->next = p1;

		p1 = p2;

		p2 = p2->pre;

	}

	start = p1;

