class stack
{
	public:
		int *data ;
		int capacity, top;
		stack(int s)
		{
			data = new int [5];
			capacity = s;
			top = 0;
		}
		bool isfull()
		{
			if (top == capacity )
			{
				return true;

			}
			else 
			{
			return false;
		}
		}
		void push (int d)
		{
			if (isfull())
			{
				cout<<" "<<endl;
			}
			data [top ++] = d;
		}
		bool isempty()
		{
			if (top == 0)
			{
				return true;
			}
		}
		int pop()
		{
			if (isempty())
			{
				cout<< " "<<endl;
			}

		return data[--top];
}
};
