#include <iostream>
#include <cmath>
using namespace std;

class Point
{
	private:
		float x,y;
	public:
	Point (float x, float y)	
	{
		this->x=x;
		this->y=y;
	}	
    Point()
	{
		x=0;
		y=0;
	}
	float X()
	{
		return x;
	}
	float Y()
	{
		return this->y;
	}
	void Set(float x, float y)
	{
		this->x=x;
		this->y=y;
	}
	void Scale(float f)
	{
		x=x*f;
		y=y*f;
	}
	float Length(Point s)
	{
		float dx=this->x-s.X(); 
		float dy=this->y-s.Y();
		return sqrt(dx*dx+dy*dy); 
	}	
};
class Polygon
{
	private:
		Point *Vertices; 
		int noVertices;
		int index;
	public:
		Polygon(int noVertices)
		{
			Vertices=new Point[noVertices];   
			this->noVertices=noVertices;
			index=0;
		}
		Polygon&Add(float x, float y) 
		{
			if (index<noVertices)
			{
				Vertices[index].Set(x,y);
				index++;
			}
			return *this; 
		}
		Polygon&Add(Point s) 
		{
			if(index<noVertices)
			{
				Vertices[index]=s;
				index++;			
			}
			return *this; 
		}
		Polygon&Add(Point *s) 
		{
			if (index<noVertices)
			{
				Vertices[index].Set(s->X(),s->Y());
				index++;
			}
			return *this; 
		}
};
