	cout<<p2.X()<<"\t"<<p2.X()<<endl;
	cout<<p1.Length(p2)<<endl;
	cout<<p2.Length(p1); 
	Polygon s1(4);
	s1.Add(0,5).Add(p1).Add(3,0).Add(new Point(0,0)); 
	return 0;
}

