		}
		else 
		{
		cout<<h<<":"<<m<<":"<<s<<"pm";
		}
	}
	int Compare(int x, int y, int z, bool w)
	{
		int t1,t2;
		if (w)
		{
			 t1=3600*x+60*y+z;
		}
		else
		{
			 t1=3600*(x+12)+60*y+z;
		}
		if (am)
		{
			 t2=3600*h+60*m+s;
		}
		else
		{
			 t2=3600*(h+12)+60*m+s;
		}
		if (t1>t2)
		{
			return 1;
		}
		else if(t1==t2)
		{
			return 0;
		}
		else
		{
			return -1;
		}
	}


};

