			cout << "2 : Current Resistance " << endl;

			cout << "3 : Type" << endl;

			cin >> choice;

		} while (choice < 0 || choice>3);		//check if the given choice is valid

		BubbleSort(myVector, choice);

		return false;

	case 10:

		return true;

	default:

		cout << "Option not available!" << endl;

		return false;

	}

}





