	// Return the object
	obj2 = +obj1;
	// 5
	obj1.print();
	// 5
	obj1.print();
	// Change the obj1 value
	obj1.setValue(10);
	// 10
	obj1.print();
	// 5
	obj2.print();
return 0;
}

