    */
    ofstream ofs;
    ofs.open("accountDetails.txt",ios::trunc);
    map<long long,Account>::iterator itr;
    for(itr=accounts.begin();itr!=accounts.end();itr++){
        ofs<<itr->second;
    }
    ofs.close();
}

