    if(!fs)
    {
        cout<<"\n cannot open file ! ";
        getch();
        return -1;
    }
    while(fs.read((char*)&stud, sizeof(stud)))
    {
        if(strcmpi(stud.sroll,roll)==0 && stud.no_of_books == 3)
        {
            found = 1;
            break;
        }
        else if(strcmpi(stud.sroll,roll)==0 && stud.no_of_books<3)
        {
            found = 2;
            break;
        }

    }
    fs.close();
    return found;
}

