    while(fb.read((char*)&bk,sizeof(bk)))
    {
        if(bkcode==bk.book_id && bk.status==0)
        {
            found = 2;
            break;
        }
        else if(bkcode == bk.book_id && bk.status==1)
        {
            found = 1;
            break;
        }
    }
    fb.close();
    return found;
}

