#include <type_traits>
#include <boost/optional.hpp>
#include <map>
#include <list>

template<class T>
struct Cacheable {
   virtual ~Cacheable() { }
   virtual void purge() = 0;
   virtual bool operator ==(T const&) const = 0;
   virtual bool operator <(T const&) const = 0;
   bool operator !=(T const&) const;
   bool operator >(T const&) const;
   bool operator <=(T const&) const;
   bool operator >=(T const&) const;
};

typedef uint64_t cachesize_t;

template<class T>
struct Cache {
   // Cool, isn't? Emulating Haskell-like parametric polymorphism with constraints
   static_assert(std::is_base_of<Cacheable<T>, T>::value,
         "Cache<T>: T must be derived from Cacheable<T>");
   Cache(cachesize_t maxSize);
   ~Cache();
   boost::optional<T> find(T const&) const;
   // Logically const is a bendable definition, you know.
   void insert(T const&) const;
   void remove(T const&) const;
private:
   Cache(Cache<T> const&);
   Cache<T>& operator =(Cache<T> const&);
private:
   cachesize_t m_maxSize;
   mutable std::map<T, typename std::list<T>::iterator> m_map;
   mutable std::list<T> m_list;
};

#include "cache_impl.h"

template<class T>
bool Cacheable<T>::operator !=(T const& o) const { return !(*this == o); }
template<class T>
bool Cacheable<T>::operator >(T const& o) const { return o < *this; }
template<class T>
bool Cacheable<T>::operator <=(T const& o) const { return !(*this > o); }
template<class T>
bool Cacheable<T>::operator >=(T const& o) const { return !(*this < o); }

template<class T>
Cache<T>::Cache(cachesize_t maxSize): m_maxSize(maxSize) { }

template<class T>
Cache<T>::~Cache() {
   for(auto elem = m_list.begin(); elem != m_list.end(); ++elem)
      elem->purge();
}

template<class T>
boost::optional<T> Cache<T>::find(T const& val) const {
   auto mapIt = m_map.find(val);
   if(mapIt == m_map.end()) return boost::optional<T>();
   T res = mapIt->first;
   // Optimisation to put most recently used at the top
   m_list.erase(mapIt->second);
   m_list.push_front(res);
   mapIt->second = m_list.begin();
   return boost::optional<T>(res);
}

template<class T>
void Cache<T>::insert(T const& val) const {
   if(m_list.size() == m_maxSize) remove(m_list.back());
   m_list.push_front(val);
   m_map.insert(make_pair(val, m_list.begin()));
}

template<class T>
void Cache<T>::remove(T const& val) const {
   auto mapIt = m_map.find(val);
   if(mapIt == m_map.end()) return;
   T res = mapIt->first;
   m_list.erase(mapIt->second);
   m_map.erase(mapIt);
   res.purge();
}

