ThoiGian ThoiGian::operator++(int x)

{

    if (giay == 59)

    {

        giay = 0;

        if (phut == 59)

        {

            phut = 0;

            gio++;

        }

        else

            phut++;

    }

    else

        giay++;

    return *this;

}



