			if(ch=='n')
				file2.write((char*)&t, sizeof(t));
			else
				cout<<"\n\n-------- RECORD DELETED --------";
		}
		else
			file2.write((char*)&t, sizeof(t));
		file1.read((char*)&t,sizeof(t));
	}
	if(found==0)
