int geneno()
{
   emp a;
   int en, len=sizeof(emp);
   ifstream fin("emp.txt");
   if (!fin)
   	en=0;
   else
   {
      fin.seekg(0, ios::end);
      int n=fin.tellg()/len;
      if (n==0)
         en=0;
      else
      {
         fin.seekg(len*(n-1), ios::beg);
         fin.read((char*)&a, sizeof(a));
         en=a.reteno();
      }
   }
   fin.close();
   return en + 1;
}
