//注册
void Log::SignIN(User *p) {
    string a;
    int f;
    while(1)
    {
        f=1;
        cout<<"请输入学号/工号：";
        cin>>a;
        //判断该学生是否注册
        for(int i=0;i<=User::User_Number;i++)
        {
            if(p[i].GetID()==a)
            {
                cout<<"该学生已注册！"<<endl;
                f=0;
            }
        }
        if(f==1){break;}
    }
    string b,bb;
    string c, cc;
    while(1)
    {
        cout<<"请输入姓名："<<endl;
        cin>>b;
        cout<<"请输入学院："<<endl;
        cin>>bb;
        cout<<"请输入密码："<<endl;
        cin>>c;
        cout<<"请再次输入密码："<<endl;
        cin>>cc;
        if(cc!=c)
        {
            cout<<"两次输入密码不一致，请重新输入。"<<endl;
        }
        if(cc==c)
        {
            break;
        }
    }
    (p+User::User_Number)->Setname(b);
    (p+User::User_Number)->SetID(a);
    (p+User::User_Number)->SetKey(c);
    (p+User::User_Number)->SetIdentity(false,true,false);
    (p+User::User_Number)->SetInstitute(bb);
    u.Setname(b);
    u.SetID(a);
    u.SetKey(c);
    u.SetInstitute(bb);
    number=User::User_Number;
    User::User_Number++;

}
//登陆
void Log::Login(User *p) {
    string a,b;
    int flag=0;
    cout<<"请输入学号/工号："<<endl;
    cin>>a;
    cout<<"请输入密码："<<endl;
    cin>>b;

    for(int i=0; i<User::User_Number;i++)
    {
        //验证账号与密码是否正确
        if(a==p[i].GetID()&&b==p[i].GetKey())
        {
            u.SetIdentity(p[i].GetIsLibrarian(),p[i].GetIsStudent(),p[i].GetIsAdmin());
            u.SetID(a);u.SetKey(b);u.Setname(p[i].getName());
            flag=1; //若账号与密码都正确，则flag=1，否则为0
            break;
        }
    }
    //登陆成功
    if(flag==1)
    {
        //图书管理员
        if(u.Judge()==3)
        {
            LogName=u.getName();
            cout<<"登录成功"<<endl;
            cout<<"尊敬的图书管理员"<<u.getName()<<",您好！"<<endl;
            Is_Log=true;
        }
        //同学
        else if(u.Judge()==4)
        {
            LogName=u.getName();
            cout<<"登录成功"<<endl;
            cout<<"亲爱的同学"<<u.getName()<<",您好！"<<endl;
            Is_Log=true;
        }
        //系统管理员
        else if(u.Judge()==5)
        {
            LogName=u.getName();
            cout<<"登录成功"<<endl;
            cout<<"尊敬的系统管理员"<<u.getName()<<",您好！"<<endl;
            Is_Log=true;
        }
    }
    //登陆失败
    else
    {
        cout<<"学号或密码错误"<<endl;
        Is_Log= false;
    }
}

