//Encrypts the entered word by adding the length of the string to each character

char* encrypt(char pass[])

{

	int i=0;

	for(i=0;pass[i]!='\0';i++)

		pass[i]+=strlen(pass);

	return pass;

}

char* getpass()	//Function to get password

{

	char pass[200];

	int i=0;

	while(1)

	{

	pass[i] = getch();

	if(pass[i]==13)

	{

		pass[i]='\0';

		break;

	}

	else if(i>=1 && pass[i]==8)	//Checks for backspace

	{

		i--;

		gotoxy(46+i,12);

		cout<<" ";

		gotoxy(46+i,12);

	}

	else

	{

		cout<<'*';

		i++;

	}

	}

	return pass;

}

