//Creates horizontal rule

void hr(int i,char ch)

{

	for(int j=0;j<80;j++)

	{

		gotoxy(j,i);

		cout<<ch;

	}

}

//Creates vertical rule

void vr(int i,char ch)

{

		for(int j=0;j<25;j++)

		{

			gotoxy(i,j);

			cout<<ch;

		}

}

//Creates borders

void borders()

{

	char ch = '*';

	hr(0,ch);

	hr(25,ch);

	vr(0,ch);

	vr(81,ch);

}



//Center Functions

void center(char* word,int y=12.5)

{

	int length = strlen(word);

	gotoxy(40.5 - length/2,y);

	cout<<word;

}



