	{

		align("                              ",30,11);

		align("Amount Paid: ",30,11);

		cin>>paid;

	}

	else

		goto start;

	if (paid<=0)

	{

		errormsg("Invalid Amount!!!");

		goto start;

	}

	strcpy(description[size],"BILL PAID");

	amount[size]=(-paid);

	qty[size]=0;

	size++;

	msg("You Have Closed A Payment");

	calcTotal();

}

float patient::calcTotal()

{

	tot=0;

	for(int i=0;i<size;i++)

	{

		if(qty[i]==0)

			tot+=amount[i];

		else

			tot+=qty[i]*amount[i];

	}

	return tot;

}



