		"russia","france","mexico","denmark","vietnam","kuwait",

		"china","japan","dubai","spain","finland","canada","argentina"

	};

	randomize();

	int n=random(17);

	strcpy(word,words[n]);

	Unknown(word, unknown);

	align("Welcome to hangman",1,2);

	align("Guess the country name",1,3);

	align("You have 5 guesses left",1,4);

	align("~~~~~~~~~~~~~~~~~~~~~~~~",1,5);

	while (WrongGuess <mt)

	{

		gotoxy(1,6);

		cout<<endl<<endl<<unknown;

		align("\n\nGuess a letter: ",1,7);

		cin>>letter;

		if (letterFill(letter, word, unknown)==0)

		{

			WrongGuess++;

			clrscr();

		}

		else

		{

			clrscr();

		}

		gotoxy(1,4);

		cout <<"You have "<<mt-WrongGuess<<" guesses left"<<endl;

		if (strcmp(word,unknown)==0)

		{

			gotoxy(1,8);

			cout<<word<<endl;

			align("You guessed it right!",1,9);

			align("Press Any Key To Continue",27,15);

			getche();

			exitprogram();

			break;

		}

	}

	if(WrongGuess == mt)

		{

			gotoxy(1,7);

			cout<<endl<<"You lose... you've been hanged."<<endl;

			gotoxy(1,6);

			cout<<"The word was: "<<word<<endl;

			dixit(33,3);

			dixit(47,3);

			dixit(61,3);

			align("Press Any Key To Continue",27,15);

			getche();

			exitprogram();

		}

	getch();

}

int letterFill (char guess, char secretword[], char guessword[])

{

	int matches=0;

	for (int i = 0; secretword[i]!='\0'; i++)

	{

		if (guess == guessword[i])

			return 0;

		if (guess == secretword[i])

	{

		guessword[i] = guess;

		matches++;

	}

  }

	return matches;

}

void Unknown (char word[], char unknown[])

{

	for (int i = 0; i<strlen(word) ; i++)

	unknown[i]='*';

	unknown[i]='\0';

}

