//Menu functions
//Creates output screen with border and heading
int createMenu(char* word,char array[50][50]=NULL,int size=0,int step=3,int start=6)
{
	clrscr();
	borders();
	hr(4,'*');
	center(word,2);
	for(int i=0;i<size;i++)
	{
		char word[50] = {i+49,'.'};				//Makes the list of items numbered
		for(int j = 2; array[i][j-2]!='\0';j++)
		{
			word[j]=array[i][j-2];
		}
	 center(word,start+(i*step));
	}
	i--;
	char ch;
	align("<--",60,start);
	int temp = start;
	while(ch!=13)
	{
		ch=getch();
		ch = toupper(ch);
		switch(ch)
		{
			case 'W':
				if(temp == start)
				{
					align("   ",60,temp);
					align("<--",60,(start+i*step));
				}
				else
				{
					align("   ",60,temp);
					temp = temp - step;
					align("<--",60,temp);
				}
				break;
			case 'S':
				if(temp == (start+i*step))
				{
					align("   ",60,temp);
					align("<--",60,start);
				}
				else
				{
					align("   ",60,temp);
					temp = temp + 2;
					align("<--",60,temp);
				}
				break;
			default:
				ch = getch();
				break;
		}
	}
	temp=(temp-6)/2;
	return temp;
}
