		bool operator==(const Book& b4) {                                                        
	        if (authorname == b4.authorname) {                                                            
	        	return 1;
	        }
	        else if (name == b4.name) {
	        	return 1;
			}
			else if (category == b4.category) {
				return 1;
			}
			else {
				return 0;
			}
