bool findString(const string & strA, const string & strB)
{
  auto it = search(
    strA.begin(), strA.end(),
    strB.begin(),   strB.end(),
    [](char ch1, char ch2) { return toupper(ch1) == toupper(ch2); }
  );
  return (it != strA.end() );
}

bool comp(pair<int,string> a,pair<int,string> b){return (a.first>b.first);}

string upCase(string a){
    int n=a.length();
    for(int i=0;i<n;i++){
        if(a[i]>='a'&&a[i]<='z'){
            a[i]=a[i]+'A'-'a';
        }
    }
    return a;
}

