struct Node { 

    int data; 

    struct Node* link;;

}; 

struct Queue { struct Node *front, *rear; };  

void enQueue(Queue *q, int value) { 

    struct Node *temp = new Node; 

    temp->data = value; 

    if (q->front == NULL) 

        q->front = temp; 

    else

        q->rear->link = temp; 

	    q->rear = temp; 

	    q->rear->link = q->front; 

} 

int deQueue(Queue *q) 

{ 

    if (q->front == NULL) 

    { 

        printf ("Queue is empty"); 

        return INT_MIN; 

    } 



	int value;



    if (q->front == q->rear) 

    { 

        value = q->front->data; 

        free(q->front); 

        q->front = NULL; 

        q->rear = NULL; 

    } 

    else 

    { 

        struct Node *temp = q->front; 

        value = temp->data; 

        q->front = q->front->link; 

        q->rear->link= q->front; 

        free(temp); 

    } 

    return value ; 

}  

void displayQueue(struct Queue *q) 

{ 

    struct Node *temp = q->front; 

    printf("\nElements in Circular Queue are: "); 

    while (temp->link != q->front) 

    { 

        printf("%d ", temp->data); 

        temp = temp->link; 

    } 

    printf("%d", temp->data); 

} 

