class Claim {
    Date claim_date;
    Book book;
    User user;

public:
    Claim() {
        this->claim_date = NULL;
        this->book = NULL;
        this->user = NULL;
    }

    Claim(Date claim_date, Book book, User user) {
        this->claim_date = claim_date;
        this->book = book;
        this->user = user;
    }

    Claim(const Claim &original) {
        this->claim_date = original.claim_date;
        this->book = original.book;
        this->user = original.user;
    }

    Date getClaimDate() {
        return claim_date;
    }

    void setClaimDate(Date claim_date) {
        this->claim_date = claim_date;
    }

    Book getBook() {
        return book;
    }

    void setBook(Book book) {
        this->book = book;
    }

    User getUser() {
        return user;
    }

    void setUser(User user) {
        this->user = user;
    }

    bool isValid() {
        Date current_date = Date.getInstance();
        if (claim_date == NULL || current_date > claim_date + 4)
            return false;
        return true;
    }

    void display() {
        cout << book.getTitle() << " claimed by " << user.getName() << endl;
        if (claim_date == NULL) {
            list<Claim> claim_list = book.getClaimList();
            list<Claim>::iterator it = find(claim_list.begin(), claim_list.end(), *this);
            int position = distance(claim_list.begin(), it) + 1;
            string suffix;
            switch (position) {
                case 1:
                    suffix = "st";
                    break;
                case 2:
                    suffix = "nd";
                    break;
                case 3:
                    suffix = "rd";
                    break;
                default:
                    suffix = "th";
                    break;
            }
            cout << "The claim is " + position + suffix +" in the queue." << endl;
            return;
        }
        if (isValid()) {
            cout << "The claim is valid for " << (claim_date - current_date + 4) << " more days" << endl;
            return;
        }
        cout << "The claim has expired." << endl;
    }
}

#include "Date.h"
#include <ctime>

class Date {
    unsigned int date;
    unsigned int month;
    unsigned int year;

    Date() {
        this->date = 0;
        this->month = 0;
        this->year = 0;
    }

    Date(unsigned int date, unsigned int month, unsigned int year) {
        this->date = date;
        this->month = month;
        this->year = year;
    }

    Date(const Date &original) {
        this->date = original.date;
        this->month = original.month;
        this->year = original.year;
    }

    unsigned int getDate() {
        return date;
    }

    void setDate(unsigned int date) {
        this->date = date;
    }

    unsigned int getMonth() {
        return month;
    }

    void setDate(unsigned int month) {
        this->month = month;
    }

    unsigned int getYear() {
        return year;
    }

    void setYear(unsigned int year) {
        this->year = year;
    }

    static Date getInstance() {
        time_t t = time(0);
        struct tm *now = localtime(&t);
        return new Date(now->tm_mday, now->tm_mon + 1, now->tm_year + 1900);
    }

    static unsigned int getDaysInMonth(unsigned int month, unsigned int year) {
        int numDays = 0;
        switch (month) {
            case 1:
            case 3:
            case 5:
            case 7:
            case 8:
            case 10:
            case 12:
                numDays = 31;
                break;
            case 4:
            case 6:
            case 9:
            case 11:
                numDays = 30;
                break;
            case 2:
                if (((year % 4 == 0) && !(year % 100 == 0)) || (year % 400 == 0))
                    numDays = 29;
                else
                    numDays = 28;
                break;
        }
        return numDays;
    }

    bool isValid() {
        if (year < 0 || month < 1 || month > 12 || days < 1 || days > getDaysInMonth(month, year))
            return false;
        return true;
    }

    void validate() {
        if (isValid())
            return;
        if (days < 0) {
            month = month == 1 ? 12 : month - 1;
            int numDays = getDaysInMonth(month, year);
            days +=  numDays;
        }
        else {
            int numDays = getDaysInMonth(month, year);
            days -= numDays;
            month = month == 12 ? 1 : month + 1;
        }
        validate();
    }

    Date operator+(unsigned int days) {
        Date new_date(*this);
        new_date.date += days;
        new_date.validate();
        return new_date;
    }

    Date operator-(unsigned int days) {
        Date new_date(*this);
        new_date.date -= days;
        new_date.validate();
        return new_date;
    }

    int operator-(Date d2) {
        Date d1(*this);
        if (d1 < d2)
            return -1 * (d2 - d1);
        if (d1.year == d2.year && d1.month == d2.month)
            return d1.date - d2.date;
        int previous_month = d1.month == 1 ? 12 : d1.month - 1;
        int numDays = getDaysInMonth(previous_month, d1.year);
        return numDays + ((d1 - numDays) - d2);
    }

    bool operator==(Date d) {
        if (year == d.year && month == d.month && date == d.date)
            return true;
        return false;
    }

    bool operator!=(Date d) {
        if (*this == date)
            return false;
        return true;
    }

    bool operator>(Date d) {
        if (year > d.year)
            return true;
        else if (year < d.year)
            return false;
        if (month > d.month)
            return true;
        else if (month < d.month)
            return false;
        if (date > d.date)
            return true;
        else
            return false;
    }

    bool operator>=(Date d) {
        if (*this == d || *this > d)
            return true;
        return false;
    }

    bool operator<(Date d) {
        if (*this >= d)
            return false;
        return true;
    }

    bool operator<=(Date d) {
        if (*this > d)
            return false;
        return true;
    }
}

