class Table

{

private:

	string res[11][8]; //total slots for reservations are 11  and every slot is of 1 hour i.e: (11 AM - 10 PM)

	int size;





public:

	Table(){

		for (int i = 0; i < 11; i++){

			for (int j = 0; j < 8; j++){

				res[i][j] = "empty";

			}



		}

		size = 8;

	}

	Table(int siz){

		for (int i = 0; i < 11; i++){

			for (int j = 0; j < 8; j++){

				res[i][j] = "empty";

			}



		}

	size = siz;

	}

	int checktable(int tim){

		for (int i = 0; i < size; i++){

			if (res[tim][i] == "empty"){

				return i;

			}



		}

		return -1;

	}







	int totalfreetables(int tim){

		int freetables=0;

		for (int i = 0; i < size; i++){

			if (res[tim][i] == "empty"){

				freetables++;

			}



		}

		return freetables;



	}

	int reserveslot(int tim,int tab,string name){

		res[tim][tab] = name;

		return 0;

	}







};



