    bool success = false;
    if( amount > 0 ) {
        if( getAccount(accountNum) != NULL) {
            success = getAccount(accountNum)->withdraw(amount);
        }
        else {
            cerr << "No account with account number " << accountNum << " exists.\n";
            success = false;
        }
    }
    else
        cerr << "Please enter a postive amount\n";

    return success; 
}

