#include<iostream>
#include<cstdlib>
using namespace std;
const int SIZE=10;

template<class atype> class sort{
	public: atype a[SIZE];
			sort(){}

			void read(int z){
				for(int i=0;i<z;i++)
					cin>>a[i];
			}

			void disp(int z){
				for(int i = 0; i < z; i++)
					cout<<a[i]<<" ";
				cout<<"\n";
			}

			template<class X> void bubble(X *items,int count){
				int a,b;
				X t;
				for(a=1;a<count;a++){
					for(b=count-1;b>=a;b--){
						if(items[b-1]>items[b]){
							t=items[b-1];
							items[b-1]=items[b];
							items[b]=t;
						}
					}
				}
			}
};

int main(){
	sort <int> intob;
	sort <double> doubleob;
	int i,m,n;

	cout<<"\nEnter the size of integer array: -\n";
	cin>>n;
	cout<<"\nEnter the size of double array: -\n";
	cin>>m;

	if (n > 10 || m > 10) {
		cout << "please enter a smaller value\n";
	}

	// intob[n-1]=0;
	// doubleob[m-1]=0;

	cout<<"\nEnter the integer array:-\n";
	intob.read(n);
	cout<<"\nEnter the double array:-\n";
	doubleob.read(m);

	cout<<"\nUnsorted integer array is:-\n";
	intob.disp(n);
	cout<<"\nUnsorted double array is:-\n";
	doubleob.disp(m);

	intob.bubble(intob.a,n);
	doubleob.bubble(doubleob.a,m);

	cout<<"\nSorted integer array is:-\n";
	intob.disp(n);
	cout<<"\nSorted double array is:-\n";
	doubleob.disp(m);

	return 0;
}

#include<iostream>
#define SIZE 5
using namespace std;

class stack{
	private: int item, top, A[SIZE];
	public: void initialise();
			void push();
			int pop();
			void display();
};

void stack::initialise(){
	top = -1;
}

void stack::push(){
	if(top == SIZE-1){
		cout<<"\nNo space";
		return;
	}
	cout<<"\nEnter item to be inserted: ";
	cin>>item;
	A[++top] = item;
	cout<<item<<" is inserted";
}

int stack::pop(){
	int del;
	if(top == -1){
		cout<<"\nThe stack is empty!";	 
		return 0;
	}
	else
		del = A[top--];
	return del;
}

void stack::display(){
	int i;
	if(top == -1)
		cout<<"\nEmpty stack!";
	else{ 
		cout<<"\nThe stack elements are:\n";
		for(i=0; i<=top; i++){
			cout<<A[i]<<"\n";
		}
	}
}

int main(){
	stack ob;
	ob.initialise();
	int choice, out = 0;
	while(1){
		cout<<"\n\nEnter your choice: ";
		cout<<"\n1. Push \t 2. Pop \t 3. Display \t 4. Exit\n";
		cin>>choice;

		switch(choice){
			case 1: ob.push();
					break;

			case 2: out = ob.pop();
					cout<<out<<" is deleted!";
					break;

			case 3: ob.display();
					break;

			case 4: exit(0);

			default: cout<<"\nEnter valid choice!";
					 break;
		}
	}
}

