int student::calculate(int n){
	float sum=0.0, min = marks[0];
	for(i=0; i<3; i++){
		if(min > marks[i])
			min = marks[i];
		sum = sum + marks[i];
	}
	avg = (sum-min)/2;
	return avg;
}

