record hospital::unpack(char buff[])

{

	record r;

	int i=0,j=0;

	while(buff[j]!='|')

		r.id[i++]=buff[j++];

	r.id[i]='\0';

	i=0;

	j++;

	while(buff[j]!='|')

		r.name[i++]=buff[j++];

	r.name[i]='\0';

	i=0;

	j++;

	while(buff[j]!='|')

		r.age[i++]=buff[j++];

	r.age[i]='\0';

	i=0;

	j++;

	while(buff[j]!='|')

		r.sex[i++]=buff[j++];

	r.sex[i]='\0';

	i=0;

	j++;

	while(buff[j]!='|')

		r.contact[i++]=buff[j++];

	r.contact[i]='\0';

	i=0;

	j++;

	while(buff[j]!='|')

		r.time[i++]=buff[j++];

	r.time[i]='\0';

	i=0;

	j++;

	while(buff[j]!='|')

		r.discription[i++]=buff[j++];

	r.discription[i]='\0';

	return(r);

}

