					DisplayVector3D(C, Z);
					break;
				}
			case 2: {
				C = A - B;
				cout << "Hieu 2 Vector " << X << " + " << Y << endl;
				DisplayVector3D(C, Z);
				break;
			}
			case 3: {
				C = A * B;
				cout << "Tich 2 Vector " << X << " + " << Y << endl;
				DisplayVector3D(C, Z);
				break;
			}
			case 4: {
				C = A / B;
				cout << "Thuong 2 Vector " << X << " + " << Y << endl;
