void Sach::ktraMaSach(string fileName) {
	setCheckMaSach(0);
	int maSach;
	string str, ten, tacGia, nhaXB, namXB;
	fstream file;
	file.open(fileName + ".txt", ios::in);
	if (!file.is_open())
	{
		cout << "Khong mo duoc file " + fileName + ".txt";
	}
	else
	{
		while (!file.eof()) {
			file >> maSach;
			if (getMaSach() == maSach) {
				setCheckMaSach(1);
				getline(file, str, '\t');
				getline(file, ten, '\t');
				getline(file, tacGia, '\t');
				getline(file, nhaXB, '\t');
				getline(file, namXB, '\n');
				setMaSach(maSach);
				setTenSach(ten);
				setTacGia(tacGia);
				setNhaXB(nhaXB);
				setNamXB(namXB);
				break;
			}
			else {
				getline(file, str, '\n');
			}
		}
	}
	file.close();
}

