void TaiKhoan::dangNhap() {
	int inputStk;
	int inputMK;
	int stk,mk,n,tmp;
	cout << "Moi quan ly thu vien dang nhap he thong";
	cout << "\nNhap so tk : ";
	cin >> inputStk;
	cout << "Nhap mat khau : ";
	cin >> inputMK;
	cout << "STK nhap : " << inputStk << "\t MK nhap : " << inputMK << endl;
	setCheck(0);
	fstream myfile;
	myfile.open("TaiKhoan.txt", ios::in);
	if (!myfile.is_open()) cout << "Khong mo duoc file TaiKhoan.txt";
	myfile >> n;
	while (!myfile.eof()) {
		for (int i = 0; i < n; i++) {
			myfile >> stk;
			if (i % 2 == 0) {
				if (stk == inputStk) {
					myfile >> mk;
					if (mk == inputMK) {
						i++;
						setCheck(1);
					}
					else
					{
						i++;
						setCheck(0);
					}
				}
				else
				{
					i++;
					myfile >> tmp;
				}
			}
		}
	}
	myfile.close();
}

