#include <iostream>
#include <memory>

/*
* Target
* defines specific interface that Client uses
*/
class Target {
public:
	virtual void request_1() const = 0;
	virtual void request_2() const = 0;
	virtual void request_3() const = 0;
	virtual void request_4() const = 0;
	virtual ~Target(){}
	// ...
};

/*
* Adaptee
* all requests get delegated to the Adaptee which defines
* an existing interface that needs adapting
*/
class Adaptee {
public:
	void specificRequest_1() const
	{
		std::cout << " specific request 1 " << std::endl;
		// ...
	}
	void specificRequest_2() const
	{
		std::cout << " specific request 2 " << std::endl;
		// ...
	}
	void specificRequest_3(const int& value) const
	{
		std::cout << " specific request 3 set value = " << value << std::endl;
		// ...
	}
	void specificRequest_4() const
	{
		std::cout << " specific request 4 " << std::endl;
		// ...
	}
	void specificRequest_5() const
	{
		std::cout << " specific request 5 " << std::endl;
		// ...
	}
	~Adaptee(){}
	// ...
};

/*
*  Adapter (i don't have money yet to buy radiator)
* implements the Target interface and lets the Adaptee respond
* to request on a Target by extending both classes
* ie adapts the interface of Adaptee to the Target interface
*/
class Adapter : public Target, private Adaptee {
public:
	virtual void request_1() const override
	{
		specificRequest_1();
		specificRequest_2();
		// ...
	}

	virtual void request_2() const override
	{
		specificRequest_3(5);
		// ...
	}

	virtual void request_3() const override
	{
		specificRequest_3(10);
		// ...
	}

	virtual void request_4() const override
	{
		specificRequest_4();
		specificRequest_5();
		// ...
	}
	virtual ~Adapter(){}
	// ...
};


int main()
{
	std::unique_ptr<Target> target = std::make_unique<Adapter>();
	target->request_1();
	target->request_2();
	target->request_3();
	target->request_4();

	system("pause");
	return 0;
}

/*
* C++ Design Patterns: Bridge
* Author: walid Abbassi [https://github.com/walidAbbassi]
* 2019
*
* Source code is licensed under MIT License
* (for more details see LICENSE)
*
*/

#include <iostream>
#include <memory>

/*
* Implementor
* defines the interface for implementation classes
*/
class Implementor {
public:
	virtual void operationImpl(const double& side) = 0;
	virtual ~Implementor(){}
	// ...
};

/*
* Concrete Implementors A
* implement the Implementor interface and define concrete implementations
*/
class ConcreteImplementors_A : public Implementor {
public:
	void operationImpl(const double& side) override
	{
		std::cout << "Concrete Implementor A " << std::endl;
	}
	~ConcreteImplementors_A() {}
	// ...
};

/*
* Concrete Implementors B
* implement the Implementor interface and define concrete implementations
*/
class ConcreteImplementors_B : public Implementor {
public:
	void operationImpl(const double& side) override
	{
		std::cout << "Concrete Implementor B " << std::endl;
	}
	~ConcreteImplementors_B() {}
	// ...
};

/*
* Abstraction
* defines the abstraction's interface
*/
class Abstraction {
public:
	virtual void operation() = 0; // low-level
	virtual void action(const double& size) = 0; // high-level
	virtual ~Abstraction() {}
protected:
	std::weak_ptr<Implementor> implementor_ptr;
	Abstraction(const std::weak_ptr<Implementor> &implementor) : implementor_ptr(implementor) {}
	// ...
};

/*
* RefinedAbstraction
* extends the interface defined by Abstraction
*/
class RefinedAbstraction : public Abstraction {
public:
	RefinedAbstraction(const double& side, const std::shared_ptr<Implementor> &implementor)
		: side(side), Abstraction(implementor) {}

	//	 low-level i.e. Implementation specific
	void operation() override
	{
		implementor_ptr.lock()->operationImpl(side);
	}

	//	 high-level i.e. Abstraction specific
	void action(const double& size) override
	{
		std::cout << "action  " << std::endl;
		side *= size;
	}

	~RefinedAbstraction() {}
	// ...

private:
	double side;
	double size;
};



int main()
{
	std::shared_ptr<Implementor> implementor_A = std::make_shared<ConcreteImplementors_A>();
	std::shared_ptr<Implementor> implementor_B = std::make_shared<ConcreteImplementors_B>();

	std::shared_ptr<Abstraction> abstraction = std::make_shared<RefinedAbstraction>(5, implementor_A);
	abstraction->operation();
	abstraction->action(2);
	abstraction->operation();

	abstraction = std::make_shared<RefinedAbstraction>(10, implementor_B);
	abstraction->operation();

	system("pause");
	return 0;
}

