string AdminController::unfreeze(ObjType obj)

{

	ErrorCode err=server->unfreeze(user,obj);

	switch(err){

	case objectNotAccessible:

		return "对象未被冻结";

		break;

	case loginAgain:

		return "您已掉线,请再次登录";

		break;

	case permissionDenied:

		return "您无权限解冻此对象";

		break;

	case noError:

		return "解冻成功";

		break;

	default:

		return "解冻失败";

	}

}



