class SINHVIEN
{
private:
	string maSV, hoTen;
	double diemToan, diemLy, diemHoa;
public:
	void Nhap()
	{
		cin.ignore();
		cout<<" - Nhap ma sinh vien: ";
		getline(cin, maSV);
		cout<<" - Nhap ho ten sinh vien: ";
		getline(cin, hoTen);
