using namespace std;



class Vector

{

private:

	int n;

	float *a;

public:

	Vector()

	{

		n = 0;

		a= NULL;

	}

	Vector(int n)

	{

		this->n=n;

		a = new float[n];

	}

	Vector(int n, float a[])

	{

		this->n = n;

		this->a = new float[this->n];

		for (int i = 0; i < this->n; ++i)

		{

			this->a[i] = a[i];

		}

	}



	float maxVector()

	{

		float max = a[0];

		for (int i = 1; i < n; ++i)

		{

			if (max < a[i])

			{

				max = a[i];

			}

		}

		return max;

	}



	float minVector()

	{

		float min = a[0];

		for (int i = 1; i < n; ++i)

		{

			if (min > a[i])

			{

				min = a[i];

			}

		}

		return min;

	}

	~Vector()

	{

		n = 0;

		delete [] a;

	}

	friend ostream& operator<<(ostream& out, Vector VT);

	friend istream& operator>>(istream& in, Vector &VT);

};



