	{

		in>>VT.a[i];

	}



	return in;

}



ostream& operator<<(ostream& out, Vector VT)

{

	out<<"(";

	for (int i = 0; i < VT.n; ++i)

	{

		out<<VT.a[i]<<",";

	}

	out<<")";



	return out;

}



