	{

		cout<<"# Nhap thong tin nguoi thu "<<i+1<<endl;

		ds[i].nhap();

	}

}



void output(NGUOI *ds, int k)

{

	cout<<"\n============= DANH SACH "<<k<<" NGUOI =============\n";

	title();

	for (int i = 0; i < k; ++i)

	{

		ds[i].xuat();

	}

}



void sortbyold(NGUOI *ds, int k)

{

	for (int i = 1; i < k; ++i)

	{

		for (int j = 0; j < k-i; ++j)

		{

			if (ds[j].tuoi() <  ds[j+1].tuoi())

			{

				NGUOI tmp = ds[j];

				ds[j] = ds[j+1];

				ds[j+1] = tmp;

			}

		}

	}



	output(ds,k);

}



int main(int argc, char const *argv[])

{

	int k;

	NGUOI *ds;

	cout<<"# Nhap so k? ";

	do{ cin>> k; }while(k<1);

	fflush(stdin);

	ds = new NGUOI[k];

	input(ds,k);

	output(ds,k);

	sortbyold(ds,k);

	return 0;

}



